(() => {
  let nlImageBase64 = '';
  let nlMimeType = 'image/jpeg';
  let ebayToken = '';
  let activeOfferId = '';
  let activeListingId = '';
  let activeSku = '';
  let activeListingStatus = '';
  let pendingDraftPayload = null;
  let cachedListings = [];
  let cachedPolicies = null; // { fulfillmentPolicies, paymentPolicies, returnPolicies }
  let viewMode = 'cards';
  let isConnected = false;
  // The two things setup is actually about. Held here because three surfaces report them — the
  // setup modal, the Settings page card and the dashboard checklist — and they must never
  // disagree about whether the seller is ready to list.
  let hasAnthropicKey = false;
  let hasBusinessPolicies = false;

  document.addEventListener('DOMContentLoaded', init);

  async function guardedFetch(url, opts) {
    return fetch(url, opts);
  }

  // ── Reliability layer ─────────────────────────────────────────────────────
  //
  // One way to call the app, one way to describe a failure, and one place that decides whether a
  // Retry button is honest. Before this, each caller wrote its own `fetch(...).then(r => r.json())`
  // and its own `catch (err) { show(err.message) }`, so a rate limit, an expired eBay token and a
  // 500 HTML error page all reached the seller as the same red line of unusable text — and the
  // AI paths, which are the slowest and most expensive to redo, had the least helpful messages.

  // A generated listing can legitimately take minutes at high thinking effort, so the ceiling is
  // generous. It exists so a request that will never come back stops looking like one that is still
  // working — an unbounded spinner is the failure sellers read as "this app is broken".
  const AI_TIMEOUT_MS = 5 * 60 * 1000;
  const PUBLISH_TIMEOUT_MS = 4 * 60 * 1000;
  const QUICK_TIMEOUT_MS = 60 * 1000;

  // Always resolves. Never throws, never rejects — the caller branches on `ok`.
  async function callApi(url, { method = 'GET', body = null, timeoutMs = QUICK_TIMEOUT_MS } = {}) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, {
        method,
        signal: controller.signal,
        headers: body ? { 'Content-Type': 'application/json' } : undefined,
        body: body ? JSON.stringify(body) : undefined,
      });

      // The app answered, whatever it said. Anything that was waiting for it to come back can stop
      // waiting — including the offline banner.
      noteBackendReachable();

      const text = await res.text();
      let data = null;
      try { data = text ? JSON.parse(text) : null; } catch { data = null; }

      if (res.ok && data !== null) return { ok: true, data, failure: null };
      if (res.ok) return { ok: true, data: {}, failure: null };

      // The server's own classification, when it gave one.
      if (data && data.failure) return { ok: false, data, failure: data.failure };

      // A body that isn't our envelope: an older endpoint, or ASP.NET's HTML error page. Both are
      // reported as an app-side fault rather than pasted at the seller as-is.
      //
      // An endpoint that answers `{ "error": "..." }` is still saying something the seller needs,
      // and it is written in their language — that sentence leads, rather than being buried under a
      // status code with the real explanation folded away in Technical detail.
      const serverSaid = typeof data?.error === 'string' && data.error.trim() ? data.error.trim() : '';
      const unreadable = data === null && text && !looksLikeHtml(text);
      return {
        ok: false,
        data,
        failure: {
          kind: unreadable ? 'Unreadable' : 'Unknown',
          headline: serverSaid ? 'The app could not do that' : 'The app returned an error',
          whatHappened: serverSaid
            || `The request came back as HTTP ${res.status}${res.statusText ? ` (${res.statusText})` : ''}.`,
          whatToDo: 'Try again. If it keeps happening, open Logs and send the detail below.',
          retryable: true,
          fixAction: 'open-logs',
          workPreserved: true,
          technical: looksLikeHtml(text)
            ? `The app sent back an error page instead of data (HTTP ${res.status}).`
            : (serverSaid || text || '').slice(0, 600) || `HTTP ${res.status}.`,
        },
      };
    } catch (err) {
      if (err.name === 'AbortError') {
        return {
          ok: false,
          data: null,
          failure: {
            kind: 'Timeout',
            headline: 'That took too long and was stopped',
            whatHappened: `No answer came back within ${describeTimeout(timeoutMs)}, so the request was cancelled.`,
            whatToDo: 'Try again. Everything you filled in is still here.',
            retryable: true,
            workPreserved: true,
            technical: `Client timeout after ${timeoutMs} ms on ${url}.`,
          },
        };
      }
      // Nothing answered at all. That is one specific thing — the app is not there — and it gets
      // said as such rather than as whatever the browser calls it this week.
      noteBackendUnreachable();
      return { ok: false, data: null, failure: unreachableFailure(err, url) };
    } finally {
      clearTimeout(timer);
    }
  }

  // "Five minutes" reads better than "5 minutes" and "60000 ms" reads like a bug report. A one-minute
  // ceiling rounded to "1 minutes" was what the old wording produced.
  function describeTimeout(ms) {
    if (ms < 90_000) return `${Math.max(1, Math.round(ms / 1000))} seconds`;
    const mins = Math.round(ms / 60_000);
    return `${mins} minute${mins === 1 ? '' : 's'}`;
  }

  // ── When the app itself is not there ──────────────────────────────────────
  //
  // "Failed to fetch" is the browser's own words for "this request never reached a server". It is a
  // sentence about the fetch API, shown to somebody who sells on eBay, and it is exactly what the
  // Listing Copilot printed on the day the backend had been closed and the page was left open: the
  // seller read a browser internal and concluded the app was broken. Nothing below ever passes that
  // string on — not as a headline, not as evidence, not through a template literal.

  // fetch only rejects with a TypeError when the request could not be made at all, so the shape is
  // the reliable test. The wording is not: Chrome says "Failed to fetch", Firefox says "NetworkError
  // when attempting to fetch resource.", Safari says "Load failed". Matched as a fallback only.
  function isUnreachable(err) {
    if (!err) return false;
    if (err.name === 'AbortError') return false;
    if (err.name === 'TypeError') return true;
    return /failed to fetch|networkerror|load failed|network request failed|err_connection|connection refused/i
      .test(String(err.message || err));
  }

  // The one sentence for the one situation, used everywhere a status line has room for a sentence
  // and nothing more. The panels with room for a whole explanation get `unreachableFailure`.
  const UNREACHABLE_SENTENCE =
    'ING AutoLister is not running — this page is still open, but nothing is answering it. '
    + 'Start the app again from the tray icon and this page will reconnect on its own.';

  // Evidence a developer can act on, with none of the browser's phrasing in it: which request, and
  // what kind of failure. Kept because sellers forward this when they ask for help.
  function technicalDetail(err, url) {
    if (isUnreachable(err)) {
      return `The request to ${url || 'the app'} never reached ${location.origin} `
           + `(${err?.name || 'NetworkError'} — no response, no status).`;
    }
    return String(err?.message || err || 'Unknown error.').slice(0, 600);
  }

  function unreachableFailure(err, url) {
    return {
      kind: 'Network',
      headline: 'ING AutoLister is not running',
      whatHappened:
        'This page is still open, but nothing answered it. The app behind it has been closed or has '
        + 'stopped, so nothing on this screen can reach your listings until it is back.',
      whatToDo:
        'Start ING AutoLister again — the price-tag icon in your system tray, or the desktop '
        + 'shortcut. This page reconnects by itself the moment it does; there is no need to reload it.',
      retryable: true,
      workPreserved: true,
      technical: technicalDetail(err, url),
    };
  }

  // The one place a caught exception becomes words a seller reads. Messages the server wrote are
  // already in their language and pass through unchanged; the two failures the browser invents its
  // own wording for — the app not being there, and a request that was given up on — are replaced.
  // Calling this is also what starts the app watching for the backend to come back, so every swept
  // call site gets the recovery for free.
  function errorText(err, fallback) {
    if (isUnreachable(err)) { noteBackendUnreachable(); return UNREACHABLE_SENTENCE; }
    if (err?.name === 'AbortError') return 'That took too long, so it was stopped. Try again.';
    const message = String(err?.message || '').trim();
    return message || fallback || 'Something went wrong.';
  }

  // ── Noticing the app come back ────────────────────────────────────────────
  //
  // A seller who restarts the app should not also have to work out that the page needs reloading.
  // The moment any request fails at the network layer this starts knocking on the app's cheapest
  // endpoint — the identity document, which needs no services and answers before setup is complete —
  // and when it answers, the banner goes and whatever was waiting on it runs again.
  const BACKEND_PROBE_URL = '/api/app/instance';
  const BACKEND_PROBE_MS = 3000;
  let backendDown = false;
  let backendProbeTimer = null;
  const backendWaiters = [];

  function noteBackendUnreachable() {
    if (!backendDown) { backendDown = true; showOfflineBanner(); }
    if (!backendProbeTimer) backendProbeTimer = setInterval(probeBackend, BACKEND_PROBE_MS);
  }

  function noteBackendReachable() {
    if (backendProbeTimer) { clearInterval(backendProbeTimer); backendProbeTimer = null; }
    if (!backendDown) return;
    backendDown = false;
    hideOfflineBanner();
    // Spliced first: a waiter that fails again re-registers itself rather than being run twice.
    backendWaiters.splice(0).forEach(fn => { try { fn(); } catch { /* one bad waiter is not the others' problem */ } });
  }

  async function probeBackend() {
    try {
      const res = await fetch(BACKEND_PROBE_URL, { cache: 'no-store' });
      if (res.ok) noteBackendReachable();
    } catch { /* still gone — keep knocking */ }
  }

  // "Run this again once the app is back", registered by whatever failed. The seller gets the thing
  // they clicked rather than a live page they have to drive back to it themselves.
  function whenBackendReturns(fn) {
    if (typeof fn !== 'function' || backendWaiters.includes(fn)) return;
    backendWaiters.push(fn);
  }

  const OFFLINE_BANNER_TEXT =
    '<strong>ING AutoLister is not running.</strong> This page is still open, but nothing is '
    + 'answering it. Start the app again — the price-tag icon in your system tray — and this page '
    + 'will reconnect on its own.';

  function offlineBanner() {
    let el = document.getElementById('app-offline-banner');
    if (el) return el;
    el = document.createElement('div');
    el.id = 'app-offline-banner';
    el.className = 'app-offline-banner hidden';
    el.setAttribute('role', 'status');
    el.innerHTML = '<span class="app-offline-text"></span>';
    document.body.appendChild(el);
    return el;
  }

  function showOfflineBanner() {
    const el = offlineBanner();
    el.classList.remove('hidden', 'app-offline-back');
    el.querySelector('.app-offline-text').innerHTML = OFFLINE_BANNER_TEXT;
  }

  function hideOfflineBanner() {
    const el = document.getElementById('app-offline-banner');
    if (!el) return;
    // Said out loud rather than vanishing: a seller who has just restarted the app needs to know
    // this page is theirs again, not wonder whether the message went away on its own.
    el.classList.add('app-offline-back');
    el.querySelector('.app-offline-text').innerHTML =
      '<strong>Reconnected.</strong> ING AutoLister is answering again — carry on where you left off.';
    setTimeout(() => el.classList.add('hidden'), 5000);
  }

  function looksLikeHtml(text) {
    const head = (text || '').trimStart().slice(0, 80).toLowerCase();
    return head.startsWith('<!doctype') || head.startsWith('<html');
  }

  // Which button resolves this failure, if one can.
  const FIX_ACTIONS = {
    'ai-key':           { label: 'Open Settings',   run: () => handleNav('settings') },
    'connect-ebay':     { label: 'Log into eBay',   run: () => startEbayLogin() },
    'ebay-policies':    { label: 'Open Settings',   run: () => handleNav('settings') },
    'open-logs':        { label: 'Open Logs',       run: () => handleNav('logs') },
    // A dead Facebook session is only ever fixed by the person, in a browser — so it gets the
    // button that opens one rather than a Retry that would fail the same way every time.
    'connect-facebook': { label: 'Reconnect Facebook', run: () => facebookConnect() },
  };

  // The eBay sign-in button lives in more than one place depending on which screen is open, so the
  // fix action finds whichever one is present rather than assuming a single id.
  function startEbayLogin() {
    const btn = $('btn-connect');
    if (btn) { btn.click(); return; }
    handleNav('settings');
  }

  // One failure, rendered the same way everywhere: what happened, what to do about it, the button
  // that does it, and the raw text kept as evidence rather than as the headline.
  function renderFailure(container, failure, options = {}) {
    const el = typeof container === 'string' ? $(container) : container;
    if (!el || !failure) return;

    const fix = FIX_ACTIONS[failure.fixAction];
    const buttons = [];
    // Only offered when the server (or the transport) says another attempt could genuinely differ.
    // A Retry button on a rejected API key teaches sellers to click Retry on everything.
    if (failure.retryable && options.onRetry) buttons.push('<button type="button" class="btn btn-primary small" data-fp-retry>Try again</button>');
    if (fix) buttons.push(`<button type="button" class="btn btn-secondary small" data-fp-fix>${esc(fix.label)}</button>`);
    (options.extraButtons || []).forEach((b, i) =>
      buttons.push(`<button type="button" class="btn btn-secondary small" data-fp-extra="${i}">${esc(b.label)}</button>`));

    const attempts = failure.attempts > 1
      ? `<p class="failure-attempts">Tried ${failure.attempts} times before giving up.</p>` : '';

    const preserved = failure.workPreserved === false
      ? '' : '<p class="failure-preserved">Nothing you entered has been lost.</p>';

    el.innerHTML =
      `<div class="failure-head">${esc(failure.headline || 'Something went wrong')}</div>` +
      (failure.whatHappened ? `<p class="failure-what">${esc(failure.whatHappened)}</p>` : '') +
      (failure.whatToDo ? `<p class="failure-todo">${esc(failure.whatToDo)}</p>` : '') +
      preserved + attempts +
      (buttons.length ? `<div class="failure-actions">${buttons.join('')}</div>` : '') +
      (failure.technical
        ? `<details class="failure-detail"><summary>Technical detail</summary><pre>${esc(failure.technical)}</pre></details>`
        : '');

    el.classList.remove('hidden');
    el.querySelector('[data-fp-retry]')?.addEventListener('click', () => { hideFailure(el); options.onRetry(); });
    el.querySelector('[data-fp-fix]')?.addEventListener('click', () => fix.run());
    el.querySelectorAll('[data-fp-extra]').forEach(btn =>
      btn.addEventListener('click', () => options.extraButtons[Number(btn.dataset.fpExtra)].run()));

    // Bring it into view. Caught by measuring it in a real browser: the panel lives low in the
    // modal's scrollable body, so a seller who was scrolled anywhere else got a failure message
    // rendered 989px down a 950px viewport and behind the sticky footer — a perfect explanation of
    // what went wrong that they never saw, which is the same as no message at all.
    try {
      const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
      el.scrollIntoView({ block: 'center', behavior: reduced ? 'auto' : 'smooth' });
    } catch { el.scrollIntoView(); }
  }

  function hideFailure(container) {
    const el = typeof container === 'string' ? $(container) : container;
    if (!el) return;
    el.innerHTML = '';
    el.classList.add('hidden');
  }

  // ── Crash recovery: the listing in progress survives the tab ───────────────
  //
  // A Claude-written listing costs real API spend and a minute or two of waiting, and until now it
  // lived only in the DOM: one accidental Ctrl+W, one refresh, one crash, and it was gone with no
  // trace and no way back. Autosave puts it in the app's own database, so the work outlives the page.

  // Long enough that typing a description isn't 400 round trips; short enough that almost nothing is
  // lost if the tab dies mid-sentence.
  const AUTOSAVE_DEBOUNCE_MS = 2500;

  // How long to wait before trying a save the app never took. The ladder is short at the front
  // because most of these are a single dropped request, and capped at half a minute because a save
  // that keeps failing is failing for a reason no amount of hurry will fix.
  const AUTOSAVE_RETRY_MS = [2000, 5000, 15000, 30000];

  // sendBeacon is capped at 64 KB by the spec's own floor, and a payload over the cap is not
  // truncated or queued — the call returns false and nothing is sent. A listing with a written
  // description and a dozen specifics gets close enough to that ceiling for it to matter, and it is
  // the biggest listings, the ones that cost the most to redo, that cross it first. Anything near
  // the limit goes by keepalive fetch instead, which has no such cap.
  const BEACON_LIMIT_BYTES = 60 * 1024;

  // The copy that outlives the app itself. See writeLocalMirror.
  const LOCAL_MIRROR_KEY = 'ing-autolister.wip.v1';

  let workKey = null;
  let autosaveTimer = null;
  let autosaveRetryTimer = null;
  let autosaveRetryStep = 0;
  // The payload the app has CONFIRMED it stored — not the one most recently sent to it. The
  // difference is the whole of the bug this replaced: the old code marked the payload clean the
  // moment the request left the browser, so a save that failed was never sent again. The seller
  // typed their last sentence, the save failed, and `lastAutosavePayload` said it was safe.
  let lastAutosavePayload = '';
  let autosaveInFlight = null;
  let autosaveQueued = false;

  function currentWorkKey() {
    if (!workKey) workKey = `wip-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    return workKey;
  }

  // The fields that hold the seller's own work. Everything else the form sends — condition, package
  // type, quantity, handling time, country, format, duration — is a control with a default, so an
  // untouched blank tab already has values for all of them and its payload is full size. Sizing the
  // payload cannot tell a blank tab from real work; naming these can. Mirrors ContentFields in
  // WorkRecoveryStore.cs, which enforces the same rule server-side.
  const AUTOSAVE_CONTENT_FIELDS = [
    'title', 'subtitle', 'description', 'conditionDescription',
    'brand', 'mpn', 'upc', 'ean', 'isbn', 'sku',
    'category', 'categoryId', 'secondaryCategoryId',
    'price', 'itemSpecifics', 'imageUrls',
  ];

  function hasAutosaveContent(draft) {
    return AUTOSAVE_CONTENT_FIELDS.some(field => {
      const value = draft?.[field];
      if (value == null) return false;
      if (typeof value === 'string') return value.trim() !== '';
      if (typeof value === 'number') return value !== 0;   // 0 is an untyped price, not a price of 0
      if (Array.isArray(value)) return value.some(Boolean);
      if (typeof value === 'object') return Object.values(value).some(v => v !== '' && v != null);
      return Boolean(value);
    });
  }

  function scheduleAutosave() {
    clearTimeout(autosaveTimer);
    autosaveTimer = setTimeout(() => { flushAutosave(false); }, AUTOSAVE_DEBOUNCE_MS);
  }

  // What would be saved right now, or null when there is nothing worth saving.
  //
  // An empty form is not work worth recovering. This used to be a size test (`length < 400`), which
  // a blank tab sails past on its defaults alone — so opening the modal and closing it again left an
  // "Untitled listing" behind, and a banner that cries wolf on every launch is one nobody reads on
  // the launch it is holding a real Claude-written listing.
  function autosaveBody() {
    let draft, payload;
    try {
      draft = buildNlPayload();
      payload = JSON.stringify(draft);
    } catch { return null; }
    if (!hasAutosaveContent(draft)) return null;

    const title = (draft.title || '').trim();
    return { key: currentWorkKey(), label: title || 'Untitled listing', payload, stage: 'editing' };
  }

  // ── The copy that outlives the app ────────────────────────────────────────
  //
  // The server-side store covers everything that can happen to the browser: a closed tab, a refresh,
  // a cleared cache, a different browser. It cannot cover the one thing that happens to the app
  // itself. A save that never arrived is not in the database, and until now it was not anywhere else
  // either — the seller's last edits died with the process that was supposed to be keeping them.
  //
  // So a copy is written here first, on every path including the unload one, and removed only once
  // the app confirms the row landed. The only work this holds is work that is not yet safe
  // elsewhere, and it is replayed on the next launch.

  function writeLocalMirror(body) {
    try {
      localStorage.setItem(LOCAL_MIRROR_KEY, JSON.stringify({
        key: body.key, label: body.label, payload: body.payload, mirroredAt: new Date().toISOString(),
      }));
    } catch { /* private mode, or the quota. The request is still the primary path. */ }
  }

  function readLocalMirror() {
    try {
      const held = JSON.parse(localStorage.getItem(LOCAL_MIRROR_KEY) || 'null');
      return held && held.key && held.payload ? held : null;
    } catch { return null; }
  }

  // Cleared only when what is held is the same work that was just confirmed. A mirror written after
  // this save started belongs to a later edit, and dropping it would throw away the newer copy —
  // which is the exact failure this whole mechanism exists to prevent.
  function clearLocalMirror(payload) {
    try {
      const held = readLocalMirror();
      if (held && payload && held.payload !== payload) return;
      localStorage.removeItem(LOCAL_MIRROR_KEY);
    } catch { /* nothing to clear */ }
  }

  // Run once on load, before the seller touches anything: whatever the app never received is pushed
  // up now, so it shows up under Recover with every other unfinished listing rather than sitting in
  // a browser key nobody reads.
  async function replayLocalMirror() {
    const held = readLocalMirror();
    if (!held) return false;

    const { ok, data } = await callApi('/api/work/autosave', {
      method: 'POST',
      body: { key: held.key, label: held.label || 'Untitled listing', payload: held.payload, stage: 'editing' },
      timeoutMs: 15000,
    });

    // `saved:false` with a reason is the app declining on purpose — empty, oversized, or a key that
    // has since gone live. None of those are worth holding the copy for.
    if (!ok) return false;
    clearLocalMirror(held.payload);
    if (data?.saved) {
      addActivity('Unsaved work recovered',
        `"${held.label || 'an unfinished listing'}" was still on this device when the app last stopped. It is saved now.`);
    }
    return Boolean(data?.saved);
  }

  // ── Saving ────────────────────────────────────────────────────────────────

  // `useBeacon` is the page-unload path: a plain fetch is cancelled when the document goes away, and
  // this is the one save that matters most — it is the save that makes the difference between
  // recovering the listing and losing it.
  //
  // Returns a promise for the ordinary path, so a caller that must not run ahead of the save — the
  // publish button — can wait for it.
  function flushAutosave(useBeacon) {
    clearTimeout(autosaveTimer);

    const body = autosaveBody();
    if (!body) return Promise.resolve(true);

    // A no-op save is still a database write and a Prune pass. Skip when nothing has changed since
    // the app last confirmed one.
    if (body.payload === lastAutosavePayload) return Promise.resolve(true);

    // Written before anything is sent, so that whatever becomes of the request, the work exists.
    writeLocalMirror(body);

    if (useBeacon) return Promise.resolve(sendAutosaveOnUnload(body));

    // One save at a time, and the newest content wins. Two overlapping saves of the same row can
    // come back out of order, and the older one landing last would mark the newer payload clean.
    if (autosaveInFlight) { autosaveQueued = true; return autosaveInFlight; }
    return runAutosave(body);
  }

  async function runAutosave(body) {
    setSaveState('saving');

    autosaveInFlight = (async () => {
      const { ok, data } = await callApi('/api/work/autosave', {
        method: 'POST', body, timeoutMs: 15000,
      });

      if (ok && data?.saved) {
        lastAutosavePayload = body.payload;
        autosaveRetryStep = 0;
        clearTimeout(autosaveRetryTimer);
        clearLocalMirror(body.payload);
        setSaveState('saved');
        return true;
      }

      // This key is the record that a listing went live, and the app refuses to write over it. The
      // draft continues under a new key rather than retrying into a row that will refuse it for the
      // rest of the session.
      if (ok && data?.reason === 'published') {
        workKey = null;
        lastAutosavePayload = '';
        clearLocalMirror(body.payload);
        setSaveState('saved');
        return true;
      }

      // The app agrees there is nothing here worth keeping. Not a failure, and not worth retrying.
      if (ok && data?.reason === 'empty') {
        lastAutosavePayload = body.payload;
        clearLocalMirror(body.payload);
        setSaveState('idle');
        return true;
      }

      // Everything else is a save that did not happen. The payload stays dirty so the next attempt
      // carries it, the copy on this device stays where it is, and the seller is told which of the
      // two is actually holding their listing.
      if (ok && data?.reason === 'too_large') { setSaveState('too-big'); return false; }

      setSaveState('local-only');
      scheduleAutosaveRetry();
      return false;
    })();

    try { return await autosaveInFlight; }
    finally {
      autosaveInFlight = null;
      // A change that arrived mid-flight was never sent. Send it now.
      if (autosaveQueued) { autosaveQueued = false; flushAutosave(false); }
    }
  }

  function scheduleAutosaveRetry() {
    clearTimeout(autosaveRetryTimer);
    const wait = AUTOSAVE_RETRY_MS[Math.min(autosaveRetryStep, AUTOSAVE_RETRY_MS.length - 1)];
    autosaveRetryStep += 1;
    autosaveRetryTimer = setTimeout(retryAutosaveNow, wait);
    // And the instant the app answers anything at all, rather than waiting out the ladder. This is
    // the ordinary case behind a failed autosave: the app was restarted, and it is back.
    whenBackendReturns(retryAutosaveNow);
  }

  function retryAutosaveNow() {
    clearTimeout(autosaveRetryTimer);
    flushAutosave(false);
  }

  // The unload save. Three things were wrong with what this replaced, all of them silent, and all of
  // them on the one save the seller never gets a second chance at:
  //
  //   1. sendBeacon's return value was thrown away, so a rejected beacon looked exactly like an
  //      accepted one.
  //   2. A payload over the browser's beacon ceiling is rejected outright — so the largest listings,
  //      the ones that took the longest to write, were the ones whose last save silently vanished.
  //   3. Nothing was left on this device for the case where the app is what went away.
  //
  // The local mirror covers (3) and is written by the caller before this runs. Returns whether the
  // save was handed to something that will deliver it.
  function sendAutosaveOnUnload(body) {
    const json = JSON.stringify(body);
    const bytes = new Blob([json]).size;

    if (navigator.sendBeacon && bytes <= BEACON_LIMIT_BYTES) {
      try {
        if (navigator.sendBeacon('/api/work/autosave', new Blob([json], { type: 'application/json' }))) return true;
      } catch { /* fall through to keepalive */ }
    }

    // keepalive outlives the document the way a plain fetch does not, and has no size ceiling.
    try {
      fetch('/api/work/autosave', {
        method: 'POST',
        body: json,
        keepalive: true,
        headers: { 'Content-Type': 'application/json' },
      }).catch(() => { /* the mirror on this device is the answer to a failure here */ });
      return true;
    } catch { return false; }
  }

  // ── Saying whether the work is actually safe ──────────────────────────────
  //
  // Autosave used to be entirely invisible, which is fine right up until it stops working: a seller
  // whose saves have been failing for ten minutes looks at exactly the same screen as one whose
  // saves are all landing. This is one line beside the tabs, quiet when everything is fine and
  // explicit when it is not.
  const SAVE_STATES = {
    saving:       { text: 'Saving…',            cls: '', title: 'Storing this listing in the app.' },
    saved:        { text: 'Saved',              cls: 'nl-save-state--ok',
                    title: 'This listing is stored in the app. Closing this tab will not lose it.' },
    'local-only': { text: 'Not saved yet',      cls: 'nl-save-state--warn',
                    title: 'The app did not take the last save, so this listing is being kept on this device '
                         + 'and will be sent again automatically. Do not clear your browser data until it says Saved.' },
    'too-big':    { text: 'Too large to save',  cls: 'nl-save-state--warn',
                    title: 'This listing is past the size the app will autosave. Shorten the description, '
                         + 'or save it as an eBay draft before closing this tab.' },
  };

  function setSaveState(state) {
    const el = $('nl-save-state');
    if (!el) return;
    const shown = SAVE_STATES[state];
    if (!shown) { el.textContent = ''; el.className = 'nl-save-state'; el.removeAttribute('title'); return; }
    el.textContent = shown.text;
    el.className = 'nl-save-state ' + shown.cls;
    el.title = shown.title;
  }

  function bindAutosave() {
    const form = $('new-listing-overlay') || document;
    // Capture phase, and on both events: `input` covers typing, `change` covers selects and the
    // paste-and-blur case that never fires `input`.
    ['input', 'change'].forEach(evt =>
      form.addEventListener(evt, e => {
        if (!e.target?.id?.startsWith('nl-')) return;
        scheduleAutosave();
      }, true));

    // Both, deliberately: `pagehide` is the one that fires reliably on mobile and on tab discard,
    // `beforeunload` on a desktop close. A duplicate save is free; a missed one is the whole problem.
    window.addEventListener('beforeunload', () => flushAutosave(true));
    window.addEventListener('pagehide', () => flushAutosave(true));
  }

  /**
   * Where recovered work is offered, and why it is offered in two different places.
   *
   * The dashboard banner used to stack one row per unfinished listing, and with seven of them it
   * pushed the entire app below the fold. Most of those seven were not abandoned work at all — they
   * were autosave snapshots left behind by app restarts — so the banner was mostly reporting its own
   * noise, and it was turned off wholesale. That fixed the noise and left a worse problem behind it:
   * autosave kept writing rows that the seller then had no way on earth to reach. Work that cannot
   * be recovered is work that was lost, whatever the database says.
   *
   * So the two kinds of row are separated rather than the whole feature being on or off:
   *
   *   - A publish the app cannot vouch for — still marked publishing when it came back up, or one
   *     eBay refused — is announced on the dashboard, because it is about a listing that may be live
   *     and costing money right now, and because there is never a stack of them.
   *   - An ordinary unfinished draft waits behind Recover in the listing screen's own header, where
   *     somebody who wants their draft back will go looking, and where a dozen of them cost the
   *     dashboard nothing.
   */
  function isUrgentRecovery(item) {
    return Boolean(item?.outcomeUnknown || item?.lastError);
  }

  // A publish is journalled even when its draft never reached the app — that is the whole point of
  // journalling it — so some rows carry an outcome to resolve and no listing to put back on screen.
  // Offering Restore on one of those opens an empty form over whatever the seller was doing.
  function hasRestorableContent(item) {
    const text = (item?.payload || '').trim();
    if (text.length < 2) return false;
    try { return Object.keys(JSON.parse(text) || {}).length > 0; }
    catch { return true; }   // not JSON, but it is something — let the seller decide
  }

  let recoverableItems = [];

  async function loadRecoverableWork() {
    const { ok, data } = await callApi('/api/work/recoverable', { timeoutMs: 15000 });
    recoverableItems = (ok && data?.items) || [];

    renderRecoveryBanner(recoverableItems.filter(isUrgentRecovery));
    renderRecoverButton(recoverableItems);
    // Kept in step when it is open — restoring or discarding from it changes what it should list.
    if (!$('nl-recover-panel')?.classList.contains('hidden')) renderRecoverPanel(recoverableItems);
  }

  function recoveryRowsHtml(items) {
    return items.map((item, i) => {
      const when = item.updatedUtc ? new Date(item.updatedUtc).toLocaleString() : 'recently';
      const unknown = item.outcomeUnknown
        ? '<span class="recovery-flag">publish outcome unknown</span>' : '';
      const failed = item.lastError
        ? `<span class="recovery-error">${esc(item.lastError.slice(0, 160))}</span>` : '';
      return `<li class="recovery-row">
          <div class="recovery-meta">
            <span class="recovery-label">${esc(item.label || 'Untitled listing')}</span>
            <span class="recovery-when">last saved ${esc(when)}</span>
            ${unknown}${failed}
          </div>
          <div class="recovery-row-actions">
            ${hasRestorableContent(item) ? `<button type="button" class="btn btn-primary small" data-recover="${i}">Restore</button>` : ''}
            ${item.outcomeUnknown ? `<button type="button" class="btn btn-secondary small" data-recover-check="${i}">Check eBay</button>` : ''}
            <button type="button" class="btn btn-ghost small" data-recover-discard="${i}">Discard</button>
          </div>
        </li>`;
    }).join('');
  }

  // The buttons in a rendered list, wired against the exact rows that produced it. Passed in rather
  // than read from `recoverableItems`, because the banner shows a filtered subset and an index into
  // the wrong array restores the wrong listing.
  function bindRecoveryActions(container, items) {
    container.querySelectorAll('[data-recover]').forEach(btn =>
      btn.addEventListener('click', () => restoreWork(items[Number(btn.dataset.recover)])));
    container.querySelectorAll('[data-recover-check]').forEach(btn =>
      btn.addEventListener('click', () => checkRecoveredPublish(items[Number(btn.dataset.recoverCheck)])));
    container.querySelectorAll('[data-recover-discard]').forEach(btn =>
      btn.addEventListener('click', () => discardWork(items[Number(btn.dataset.recoverDiscard)])));
  }

  function renderRecoveryBanner(urgent) {
    const banner = $('recovery-banner');
    if (!banner) return;

    // Never announce recovery when there is nothing that needs announcing.
    if (!urgent.length) { banner.classList.add('hidden'); banner.innerHTML = ''; return; }

    banner.innerHTML =
      `<div class="recovery-head">${urgent.length === 1
          ? 'A publish did not finish'
          : `${urgent.length} publishes did not finish`}</div>` +
      '<p class="recovery-sub">The app cannot tell whether these reached eBay. Check before publishing '
      + 'again — publishing twice puts two live listings up for one item.</p>' +
      `<ul class="recovery-list">${recoveryRowsHtml(urgent)}</ul>`;
    banner.classList.remove('hidden');
    bindRecoveryActions(banner, urgent);
  }

  // The count on the header button, and nothing at all when there is nothing to recover.
  function renderRecoverButton(items) {
    const btn = $('nl-recover-btn');
    if (!btn) return;
    if (!items.length) { btn.classList.add('hidden'); return; }
    btn.classList.remove('hidden');
    btn.textContent = `Recover (${items.length})`;
    btn.title = items.length === 1
      ? 'One unfinished listing was saved before this screen last closed'
      : `${items.length} unfinished listings were saved before this screen last closed`;
  }

  function renderRecoverPanel(items) {
    const panel = $('nl-recover-panel');
    if (!panel) return;

    if (!items.length) {
      panel.innerHTML = '<div class="recovery-head">Nothing to recover</div>'
        + '<p class="recovery-sub">Every listing you have written is either published or still on screen.</p>';
      return;
    }

    // Offered only when there is more than one, so it does not sit beside a single row's own Discard
    // saying the same thing twice.
    const discardAll = items.length > 1
      ? '<div class="recovery-bulk"><button type="button" class="btn btn-ghost small" '
        + `id="recovery-discard-all">Discard all ${items.length}</button></div>`
      : '';

    panel.innerHTML =
      `<div class="recovery-head">${items.length === 1
          ? 'An unfinished listing was saved'
          : `${items.length} unfinished listings were saved`}</div>` +
      '<p class="recovery-sub">These were being written when this screen last closed. Restore one to '
      + 'carry on where it left off.</p>' +
      `<ul class="recovery-list">${recoveryRowsHtml(items)}</ul>` + discardAll;

    bindRecoveryActions(panel, items);
    $('recovery-discard-all')?.addEventListener('click', () => discardAllWork(items.length));
  }

  function toggleRecoverPanel() {
    const panel = $('nl-recover-panel');
    if (!panel) return;
    const opening = panel.classList.contains('hidden');
    panel.classList.toggle('hidden', !opening);
    if (opening) renderRecoverPanel(recoverableItems);
  }

  function bindRecoverButton() {
    $('nl-recover-btn')?.addEventListener('click', toggleRecoverPanel);
  }

  function restoreWork(item) {
    if (!item) return;
    $('nl-recover-panel')?.classList.add('hidden');
    let payload;
    try { payload = JSON.parse(item.payload || '{}'); }
    catch {
      addActivity('Could not restore that draft', 'The saved copy could not be read.');
      return;
    }

    // Adopt the recovered key so continuing to edit updates that same row rather than starting a
    // second one beside it — otherwise a restored draft would be offered back twice next launch.
    workKey = item.key;
    // What is on screen is exactly what the app is holding, so the next save is genuinely a no-op
    // and the indicator says so rather than opening on a blank state.
    lastAutosavePayload = item.payload || '';
    autosaveRetryStep = 0;
    clearTimeout(autosaveRetryTimer);
    setSaveState('saved');

    openNewListingModal();
    fillNlForm(payload);
    // Photos are URLs into the app's own generated-photos folder, so a recovered draft keeps them.
    if (Array.isArray(payload.imageUrls) && payload.imageUrls.length) {
      nlClearAllPhotoSlots();
      payload.imageUrls.filter(Boolean).forEach(url => nlAddPhotoRow(url));
    }
    addActivity('Draft restored', payload.title || item.label || 'Unfinished listing recovered');
    loadRecoverableWork();
  }

  async function checkRecoveredPublish(item) {
    if (!item) return;
    let payload = {};
    try { payload = JSON.parse(item.payload || '{}'); } catch { /* title fallback below */ }
    const title = payload.title || item.label || '';
    if (!title) return;

    addActivity('Checking eBay', `Looking for "${title}" among your live listings…`);
    const { ok, data, failure } = await callApi('/api/listing/check-published', {
      method: 'POST', body: { title, workKey: item.key }, timeoutMs: 90000,
    });

    if (!ok) {
      addActivity('Could not check eBay', failure?.whatHappened || 'The check did not complete.');
      return;
    }
    addActivity(data.found ? 'It is already live on eBay' : 'It never went live', data.message || '');
    if (data.found) loadListings('Listings refreshed after reconciling a publish');
    loadRecoverableWork();
  }

  async function discardWork(item) {
    if (!item) return;
    if (!confirm(`Discard "${item.label || 'this draft'}"? This cannot be undone.`)) return;
    await callApi('/api/work/discard', { method: 'POST', body: { key: item.key }, timeoutMs: 15000 });
    if (workKey === item.key) { workKey = null; lastAutosavePayload = ''; }
    loadRecoverableWork();
  }

  // One action for a banner full of drafts the seller has finished with. The count is in the prompt
  // because this is the one recovery action that cannot be undone one row at a time.
  async function discardAllWork(count) {
    if (!confirm(`Discard all ${count} recovered drafts? This cannot be undone.`)) return;

    const { ok, data, failure } = await callApi('/api/work/discard-all', { method: 'POST', timeoutMs: 20000 });
    if (!ok) {
      addActivity('Could not clear the recovered drafts', failure?.whatHappened || 'Nothing was discarded.');
      return;
    }
    // The draft being edited now may have been one of them, so stop autosaving into a row that is gone.
    workKey = null;
    lastAutosavePayload = '';
    addActivity('Recovered drafts cleared', `${data?.discarded ?? count} draft(s) discarded.`);
    loadRecoverableWork();
  }

  async function init() {
    // Not awaited: whether a newer version exists is never worth delaying the dashboard for, and
    // the check answers "no" on every failure anyway.
    checkForUpdate();

    initTheme();              // the theme is already ON the page from the head script; this wires the switch to it
    initWorkspaceTabs();      // the Dashboard tab has to exist before any route can open beside it
    initOverlayMotion();      // before anything can open a modal, so the first close animates too
    initVizTooltips();        // one delegated tooltip layer, so any chart drawn later opts in with an attribute
    initPhotoGrid();          // render 6 photo slots on page load, not just on modal open
    initPhotoEditorPaste();
    initSettingsNav();        // the Settings rail; idle until the Settings section is on screen
    bindDashboard();
    bindSetup();
    bindSetupChecklist();
    bindNewListingModal();
    bindImageGenSetup();
    bindPgImggen();
    bindConnectionDoctor();
    bindOpportunitySearch();
    bindSupplierAnalyzer();
    bindFacebookMarketplace();
    bindNegotiation();
    bindCouponCheck();
    bindRollTheDice();
    bindPhotoLibrary();
    bindInventoryHealth();
    bindWatcherOffers();
    bindRescue();
    bindBudget();
    bindRelist();
    bindLotAnalyzer();
    bindPromoted();
    bindShipping();
    bindWhatsNot();
    bindTrendRadar();
    bindDealRadar();
    bindSnapSource();
    bindWhereToSell();
    bindSniper();
    bindEarnings();
    bindTax();
    bindStorePlan();
    bindRestock();
    bindPricePosition();
    bindPipeline();
    bindHomeButtons();
    bindForm();
    initEditDrawer();
    initEditorOverview();   // after the form has been relocated into the drawer
    bindMarketResearch();
    bindCrossListing();
    bindTakeHome('nl');
    bindTakeHome('f');
    loadFeeProfile();
    bindAutosave();
    bindRecoverButton();
    restoreListingViewMode();
    addActivity('ING Listing Engine™ ready', 'Official product of ING Mining LLC — all systems operational.');

    await checkSetupOnLoad();
    // The checklist's extras row now carries live Connect buttons, so their state has to be known
    // on the dashboard and not only once Settings is opened. Not awaited: neither button's state
    // blocks anything else on the page, and a slow status check shouldn't hold up the listings.
    loadFacebookStatus();
    await checkLicenseStatus();
    await checkTrialStatus();

    try {
      // /api/ebay/status, not token-status: an eBay account that was revoked has no token either,
      // and reporting that as a plain "not connected" is how a seller finds the app quietly signed
      // out with no account of why. The server has recorded the reason; show it.
      const ebayStatus = await fetch('/api/ebay/status').then(r => r.json());
      updateAuthUI(!!ebayStatus.hasToken);
      if (ebayStatus.reauthRequired && ebayStatus.reauthReason) {
        addActivity('eBay connection ended', ebayStatus.reauthReason);
        showResult('error', `${esc(ebayStatus.reauthReason)} Open Settings → eBay and click Connect eBay Account.`);
      } else if (ebayStatus.binding && ebayStatus.binding.verified && !ebayStatus.binding.ok) {
        addActivity('eBay sign-in cannot complete', ebayStatus.binding.problem);
        showResult('error', esc(ebayStatus.binding.problem));
      }
      if (ebayStatus.hasToken) {
        await loadListings('Connected account detected');
        loadPolicies(false); // background — populate dropdowns for next modal open
      } else await loadPlaceholderListings('Sample listings loaded');
    } catch {
      updateAuthUI(false);
      await loadPlaceholderListings('Sample listings loaded');
    }

    renderListings();
    updateStats();

    // Not awaited, and quiet on failure: the running total is the best thing on the dashboard when
    // there is one, and no reason to hold the page up when there isn't. The band stays hidden
    // unless real money comes back.
    loadEarnings(true);

    // Same posture: not awaited, quiet on failure. The board is only worth a front-page band
    // when real money is actually out, so a seller with no tracked deals never sees a $0 banner.
    loadPipeline(true);

    // Last, and not awaited: a listing recovered from a crash is the most valuable thing on this
    // page, but it must not delay the page loading — and if the check itself fails, the banner simply
    // stays hidden rather than holding up everything behind it.
    //
    // The mirror first, and awaited by the recovery load rather than the page: anything this device
    // is still holding because the app never took it has to be pushed up before the app is asked
    // what there is to recover, or the one listing most at risk is the one missing from the list.
    replayLocalMirror().finally(loadRecoverableWork);

    // Navigate to whatever section the URL hash specifies (supports reload + deep links)
    if (location.hash) handleNav(location.hash.slice(1));
  }

  // ── Theme ─────────────────────────────────────────────────────────────────────
  //
  // Three choices, two outcomes. 'light' and 'dark' are the seller's decision and
  // persist; 'system' is the default and defers to the OS live — change the Windows
  // app mode with this open and the page follows, no reload.
  //
  // The resolved theme is already on <html> before any of this runs: the inline
  // script in the head applies it ahead of the first paint, because doing it here
  // would mean a white flash on every load for anyone who chose dark. This owns the
  // switch, the persistence and the OS listener. It does not own the first paint.
  const THEME_KEY = 'ingTheme';
  const THEME_ORDER = ['light', 'dark', 'system'];
  let systemDarkQuery = null;
  let themeFadeTimer = null;

  function initTheme() {
    const group = $('theme-switch');
    if (!group) return;

    systemDarkQuery = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
    // Only acts while the choice is 'system'. A seller who picked a side keeps it,
    // even if the OS changes underneath them.
    systemDarkQuery?.addEventListener('change', () => {
      if (readThemeChoice() === 'system') applyTheme('system');
    });

    group.querySelectorAll('[data-theme-choice]').forEach(btn => {
      btn.addEventListener('click', () => applyTheme(btn.dataset.themeChoice));
      // A radiogroup is one tab stop with arrow keys inside it, not three tab stops.
      btn.addEventListener('keydown', e => {
        const step = (e.key === 'ArrowRight' || e.key === 'ArrowDown') ? 1
          : (e.key === 'ArrowLeft' || e.key === 'ArrowUp') ? -1 : 0;
        if (!step) return;
        e.preventDefault();
        const i = THEME_ORDER.indexOf(readThemeChoice());
        const next = THEME_ORDER[(i + step + THEME_ORDER.length) % THEME_ORDER.length];
        applyTheme(next);
        group.querySelector(`[data-theme-choice="${next}"]`)?.focus();
      });
    });

    renderThemeSwitch(readThemeChoice());
  }

  function readThemeChoice() {
    const choice = document.documentElement.getAttribute('data-theme-choice');
    return THEME_ORDER.includes(choice) ? choice : 'system';
  }

  function applyTheme(choice) {
    if (!THEME_ORDER.includes(choice)) choice = 'system';
    const root = document.documentElement;
    const dark = choice === 'dark' || (choice === 'system' && !!systemDarkQuery?.matches);

    // The cross-fade is worn only for the length of the change. Leaving a global
    // transition on the document would put one on every hover in the app.
    root.classList.add('theme-switching');
    clearTimeout(themeFadeTimer);
    themeFadeTimer = setTimeout(() => root.classList.remove('theme-switching'), 360);

    root.setAttribute('data-theme', dark ? 'dark' : 'light');
    root.setAttribute('data-theme-choice', choice);
    // 'system' is the absence of a choice, so it is stored as the absence of a key —
    // which is also what the head script reads it back as.
    try {
      if (choice === 'system') localStorage.removeItem(THEME_KEY);
      else localStorage.setItem(THEME_KEY, choice);
    } catch { /* private mode: the choice lasts the session */ }

    renderThemeSwitch(choice);
  }

  function renderThemeSwitch(choice) {
    const group = $('theme-switch');
    if (!group) return;
    // The gold pill's position is one number the CSS animates; the buttons only
    // carry state. Nothing here measures or writes a pixel offset.
    group.style.setProperty('--theme-i', String(Math.max(0, THEME_ORDER.indexOf(choice))));
    group.querySelectorAll('[data-theme-choice]').forEach(btn => {
      const on = btn.dataset.themeChoice === choice;
      btn.setAttribute('aria-checked', on ? 'true' : 'false');
      btn.tabIndex = on ? 0 : -1;
    });
  }

  function bindDashboard() {
    on('license-nag-dismiss',  'click', () => { $('license-nag')?.classList.add('hidden'); sessionStorage.setItem('licenseNagDismissed', '1'); });
    on('license-nag-settings', 'click', () => { $('license-nag')?.classList.add('hidden'); openSetupWithPolicies(null); });
    on('btn-import-listings', 'click', () => loadListings('Manual import requested'));
    on('btn-refresh-listings', 'click', () => loadListings('Listings refreshed'));
    on('btn-refresh-dashboard', 'click', () => loadListings('Dashboard refresh requested'));
    on('btn-refresh-logs', 'click', loadLogs);
    on('btn-new-ai-listing', 'click', showAiSection);
    on('btn-back-dashboard', 'click', showDashboard);
    on('global-search', 'input', renderListings);

    // The gold card on the front page. It opens the board and puts the caret in the field the
    // board needs filled — the search runs on a keyword, so landing on the screen with nothing
    // focused is one wasted click on the most important action the dashboard offers.
    on('dash-act-goldmines', 'click', () => {
      navigateTo('opportunity');
      // navigateTo routes through hashchange, so the board is still hidden on this tick and a
      // focus() on a hidden field does nothing at all. One frame later it is on screen.
      setTimeout(() => { const box = $('fb-query-input'); if (box) { box.focus(); box.select(); } }, 60);
    });

    // The search box advertises Ctrl+K; this is what makes the label true.
    // Escape clears and re-renders, so a filtered grid is one key from whole.
    document.addEventListener('keydown', e => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        const box = $('global-search');
        box?.focus();
        box?.select();
        return;
      }
      if (e.key === 'Escape' && document.activeElement?.id === 'global-search') {
        const box = $('global-search');
        if (box && box.value) { box.value = ''; renderListings(); }
      }
    });

    on('btn-card-view', 'click', () => setViewMode('cards'));
    on('btn-table-view', 'click', () => setViewMode('table'));

    document.querySelectorAll('.nav-item').forEach(btn => {
      btn.addEventListener('click', () => navigateTo(btn.dataset.page || 'dashboard'));
    });

    window.addEventListener('hashchange', () => {
      handleNav(location.hash.slice(1) || 'dashboard');
    });
  }

  // Every route in this app is a workspace tab now, so navigation is one line: open the tab, or
  // switch to it if it is already open.
  function handleNav(page) {
    openWorkspaceTab(page || 'dashboard');
  }

  // Setting the hash to what it already is fires no hashchange, so the click would do nothing at
  // all. Navigate directly in that case. Shared by the sidebar, the workspace tab bar and every
  // dashboard button that jumps to a screen, so all three routes behave identically.
  function navigateTo(page) {
    if (location.hash.slice(1) === page) handleNav(page);
    else location.hash = page;
  }

  function setActiveNavItem(page) {
    document.querySelectorAll('.nav-item').forEach(btn => btn.classList.toggle('active', btn.dataset.page === page));
  }

  // ── Workspace tabs ───────────────────────────────────────────────────────
  // Every feature here is a full-screen overlay, and opening one used to CLOSE the one before it:
  // pricing a pallet meant losing the sourcing board that found it, and coming back re-ran the
  // scan that produced it. These tabs are the model the AI Listing drafts already use
  // (newDraftTab / switchDraftTab / renderDraftTabs / closeDraftTab), lifted one level up so a
  // *feature* is a tab. Each open tab keeps its own section alive in the DOM, so switching back
  // to a finished scan shows that scan rather than re-spending the eBay calls and comp lookups
  // that paid for it.
  //
  // A page belongs in this table if it has a screen of its own. `section` is the element the
  // screen lives in, `open` is that screen's existing opener (it hides the others, renders and
  // loads), and the optional hooks are for the two screens that need more than show/hide:
  //   refresh — re-run on every return to the tab. Only for screens whose whole content is
  //             server state; never for one holding something the seller typed.
  //   onShow / onHide — start and stop work that must not run for a screen nobody is looking at.
  const WORKSPACE_PAGES = {
    dashboard:   { section: 'dashboard-section',     open: showDashboard, pinned: true },
    earnings:    { section: 'earnings-section',      open: showEarningsSection },
    // Server state end to end — no field on it holds anything the seller typed except the bracket,
    // which is saved the moment it is applied — so every return to the tab re-reads it. A sale
    // imported since the last look changes the bill, and a stale bill is the one thing this screen
    // must not show.
    tax:         { section: 'tax-section',           open: showTaxSection, refresh: loadTaxPack },
    // Not refreshed on every return: the listing count behind it is an eBay round trip, and this
    // screen's answer moves on a scale of months, not minutes. "Recount my listings" is the button
    // that goes back to eBay, and it is in the header where the seller can see it.
    storeplan:   { section: 'storeplan-section',     open: showStorePlanSection },
    pipeline:    { section: 'pipeline-section',      open: showPipelineSection },
    // Listings and Activity are regions of the Dashboard, not screens: they focus the Dashboard
    // tab and scroll, instead of opening a second tab showing the same page.
    listings:    { scrollTo: 'listings-section', scrollBlock: 'start' },
    ai:          { section: 'new-listing-overlay',   open: showAiSection },
    photos:      { section: 'photo-library-section', open: showPhotoLibrarySection },
    // The one page that is doing something whether or not it is open. onShow/onHide only control
    // how often it re-reads itself — the scanning happens in the server either way.
    snap:        { section: 'snap-section',          open: showSnapSection },
    // No refresh hook, unlike the Tax Pack: this one reads the seller's live eBay listings to work
    // out what they have none of, and that is a real API call. It loads once and reloads when the
    // seller asks — coming back to a tab is not asking.
    restock:     { section: 'restock-section',       open: showRestockSection },
    // Same rule as the Restock List, and for a stronger reason: one load is the seller's live
    // listings plus one eBay search per product on them. Coming back to a tab is not asking for
    // a dozen searches — the Refresh button is.
    position:    { section: 'position-section',      open: showPricePositionSection },
    radar:       { section: 'radar-section',         open: showRadarSection,
                   onShow: startRadarWatchPolling, onHide: stopRadarWatchPolling },
    opportunity: { section: 'opportunity-section',   open: showOpportunitySection },
    // Off the sidebar at the seller's request, so it carries its own title and icon — a tab opened
    // by URL would otherwise be labelled "snipe" wearing the Dashboard glyph.
    snipe:       { section: 'snipe-section',         open: showSnipeSection,
                   onShow: startSnipeTicker, onHide: stopSnipeTicker,
                   title: 'Auction Sniper',  icon: '#i-opportunity' },
    budget:      { section: 'budget-section',        open: showBudgetSection },
    offers:      { section: 'offers-section',        open: showOffersSection },
    rescue:      { section: 'rescue-section',        open: showRescueSection },
    promoted:    { section: 'promoted-section',      open: showPromotedSection },
    copilot:     { section: 'copilot-section',       open: showCopilotSection },
    shipping:    { section: 'shipping-section',      open: showShippingSection },
    whatsnot:    { section: 'whatsnot-section',      open: showWhatsNotSection },

    // These five have no sidebar entry — they were removed from the nav — so they carry their own
    // title and icon. Everything else takes both off its nav button, which is why renaming a
    // feature in the sidebar renames its tab with nothing to keep in sync. A page reachable only
    // by URL still has to open as a properly labelled tab rather than one reading "wheretosell".
    inventory:   { section: 'inventory-section', open: showInventorySection,
                   title: 'Inventory Health', icon: '#i-inventory' },
    relist:      { section: 'relist-section',    open: showRelistSection,
                   title: 'Lost Sales',       icon: '#i-money' },
    lots:        { section: 'lots-section',      open: showLotsSection,
                   title: 'Lot Analyzer',     icon: '#i-opportunity' },
    wheretosell: { section: 'wts-section',       open: showWhereToSellSection,
                   title: 'Where to Sell',    icon: '#i-money' },
    trends:      { section: 'trends-section',    open: showTrendsSection,
                   title: 'Rising Now',       icon: '#i-opportunity' },
    activity:    { scrollTo: 'activity-list', scrollBlock: 'center' },
    logs:        { section: 'logs-section',          open: showLogsSection, refresh: loadLogs },
    settings:    { section: 'settings-section',      open: showSettingsSection },
    license:     { section: 'license-section',       open: showLicenseSection, refresh: loadLicenseStatus },
  };

  let workspaceTabs = [];        // [{ id, page, title, icon, pinned, loaded }] in bar order
  let activeWorkspaceTabId = null;
  let workspaceTabCounter = 0;

  // Title and icon come off the sidebar entry rather than a second list here, so renaming a
  // feature in the nav renames its tab and there is nothing to keep in sync. A page with no nav
  // entry falls back to the title/icon on its own registry entry — see the five above.
  function workspaceNavItem(page) {
    return document.querySelector('.nav-item[data-page="' + page + '"]');
  }

  function newWorkspaceTab(page) {
    workspaceTabCounter++;
    const nav = workspaceNavItem(page);
    const def = WORKSPACE_PAGES[page] || {};
    const tab = {
      id: workspaceTabCounter,
      page,
      title: (nav ? nav.textContent.trim() : '') || def.title || page,
      icon: nav?.querySelector('use')?.getAttribute('href') || def.icon || '#i-dashboard',
      pinned: !!def.pinned,
      loaded: false
    };
    workspaceTabs.push(tab);
    return tab;
  }

  function findWorkspaceTab(page) {
    return workspaceTabs.find(t => t.page === page);
  }

  function openWorkspaceTab(page) {
    const def = WORKSPACE_PAGES[page];
    if (!def) { openWorkspaceTab('dashboard'); return; }

    if (def.scrollTo) {
      openWorkspaceTab('dashboard');
      $(def.scrollTo)?.scrollIntoView({ behavior: 'smooth', block: def.scrollBlock || 'start' });
      return;
    }

    activateWorkspaceTab(findWorkspaceTab(page) || newWorkspaceTab(page));
  }

  function activateWorkspaceTab(tab) {
    if (!tab) return;
    const def = WORKSPACE_PAGES[tab.page];
    const outgoing = workspaceTabs.find(t => t.id === activeWorkspaceTabId);
    if (outgoing && outgoing.id !== tab.id) WORKSPACE_PAGES[outgoing.page]?.onHide?.();

    activeWorkspaceTabId = tab.id;

    if (!tab.loaded) {
      def.open();                 // first visit: the screen's own opener does the work
    } else {
      // Already open once. Put it back exactly as the seller left it — calling open() again
      // would throw away a completed scan and charge for it a second time.
      hideOverlaySections();
      if (tab.page === 'dashboard') {
        showDashboard();
      } else {
        $(def.section)?.classList.remove('hidden');
        setActiveNavItem(tab.page);
        def.refresh?.();
        def.onShow?.();
      }
    }
    tab.loaded = true;
    syncWorkspaceHash(tab.page);
    renderWorkspaceTabs();
    // The screen is on the page by now whichever branch put it there, so one
    // call covers both the first open and every return to an already-loaded tab.
    playEnter($(def.section));
  }

  // Some screens open by a route other than the sidebar — the AI Listing modal off a pasted
  // screenshot or a recovered draft, the Opportunity Finder off Roll the Dice. Every show*Section
  // ends here, so a screen that put itself on the page always gets a tab, without opening twice.
  function markWorkspaceTabOpen(page) {
    if (!WORKSPACE_PAGES[page]) return;
    const tab = findWorkspaceTab(page) || newWorkspaceTab(page);
    tab.loaded = true;
    if (activeWorkspaceTabId !== tab.id) {
      const outgoing = workspaceTabs.find(t => t.id === activeWorkspaceTabId);
      if (outgoing) WORKSPACE_PAGES[outgoing.page]?.onHide?.();
      activeWorkspaceTabId = tab.id;
    }
    syncWorkspaceHash(page);
    renderWorkspaceTabs();
  }

  // The URL follows the active tab so a reload lands back on it. replaceState fires no
  // hashchange, so this can never loop back into handleNav. The Dashboard is the one exception:
  // showDashboard() clears the hash itself, because "#dashboard" is not a place.
  function syncWorkspaceHash(page) {
    if (page === 'dashboard') return;
    if (location.hash.slice(1) === page) return;
    history.replaceState(null, '', location.pathname + location.search + '#' + page);
  }

  // The ✕ on a tab and the ✕ in a screen's own header do the same thing: close that one screen
  // and land on the tab beside it. Neither closes the seller's other open work, which is what
  // "back to the dashboard" used to do to it.
  function closeWorkspaceTab(id) {
    const idx = workspaceTabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    const tab = workspaceTabs[idx];
    if (tab.pinned) return;       // the Dashboard is the floor — there is nothing behind it

    const def = WORKSPACE_PAGES[tab.page];
    def?.onHide?.();
    if (def?.section) $(def.section)?.classList.add('hidden');
    workspaceTabs.splice(idx, 1);

    if (activeWorkspaceTabId === id) {
      activeWorkspaceTabId = null;
      activateWorkspaceTab(workspaceTabs[Math.min(idx, workspaceTabs.length - 1)]);
    }
    renderWorkspaceTabs();
  }

  function closeWorkspacePage(page) {
    const tab = findWorkspaceTab(page);
    if (tab) { closeWorkspaceTab(tab.id); return; }
    // Nothing on the bar for it (it was never opened through the workspace) — fall back to the
    // old behaviour so a stray close button can still get the screen off the page.
    const def = WORKSPACE_PAGES[page];
    if (def?.section) $(def.section)?.classList.add('hidden');
    showDashboard();
  }

  function renderWorkspaceTabs() {
    const bar = $('ws-tab-bar');
    if (!bar) return;
    const newBtn = $('ws-tab-new-btn');
    bar.querySelectorAll('.ws-tab').forEach(el => el.remove());

    workspaceTabs.forEach(tab => {
      const def = WORKSPACE_PAGES[tab.page];
      const active = tab.id === activeWorkspaceTabId;

      const el = document.createElement('div');
      el.className = 'ws-tab' + (active ? ' active' : '');

      const main = document.createElement('button');
      main.type = 'button';
      main.className = 'ws-tab-main';
      main.setAttribute('role', 'tab');
      main.setAttribute('aria-selected', active ? 'true' : 'false');
      if (def?.section) main.setAttribute('aria-controls', def.section);
      // Only the selected tab is in the page's tab order; ← and → move between them. That is the
      // ARIA tablist pattern, and it stops Tab from walking through twenty open features before
      // it reaches the screen the seller is actually reading.
      main.tabIndex = active ? 0 : -1;
      main.innerHTML =
        '<svg class="ws-tab-icon" aria-hidden="true"><use href="' + esc(tab.icon) + '"/></svg>' +
        '<span class="ws-tab-title">' + esc(tab.title) + '</span>';
      main.addEventListener('click', () => navigateTo(tab.page));
      el.appendChild(main);

      if (!tab.pinned) {
        const x = document.createElement('button');
        x.type = 'button';
        x.className = 'ws-tab-close';
        x.tabIndex = -1;          // reachable by Delete on the focused tab, not by another Tab stop
        x.setAttribute('aria-label', 'Close ' + tab.title);
        x.title = 'Close ' + tab.title;
        x.textContent = '✕';
        x.addEventListener('click', e => { e.stopPropagation(); closeWorkspaceTab(tab.id); });
        el.appendChild(x);
      }

      bar.insertBefore(el, newBtn);
    });

    // One tab is not a workspace — it is the app as it always was. The strip only takes room off
    // the top of the window once there is something to switch between.
    document.body.classList.toggle('ws-tabs-open', workspaceTabs.length > 1);
  }

  // ── The "+" menu ─────────────────────────────────────────────────────────
  // Built from the sidebar's own children, groups and all, so it is one list of features rather
  // than a second one to keep in step with the first.
  function renderWorkspaceMenu() {
    const menu = $('ws-open-menu');
    if (!menu) return;
    menu.innerHTML = '';

    document.querySelectorAll('.nav-list > *').forEach(src => {
      if (src.classList.contains('nav-group-label')) {
        const label = document.createElement('p');
        label.className = 'ws-open-menu-group';
        label.textContent = src.textContent.trim();
        menu.appendChild(label);
        return;
      }
      if (!src.classList.contains('nav-item')) return;

      const page = src.dataset.page;
      const def = WORKSPACE_PAGES[page];
      // The Dashboard is always on the bar already, and Listings/Activity are regions of it
      // rather than screens — neither opens a tab, so neither belongs in a tab opener.
      if (!def || def.pinned || def.scrollTo) return;

      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'ws-open-menu-item';
      item.setAttribute('role', 'menuitem');
      item.dataset.page = page;
      const open = !!findWorkspaceTab(page);
      item.innerHTML =
        '<svg class="ws-tab-icon" aria-hidden="true"><use href="' +
          esc(src.querySelector('use')?.getAttribute('href') || '#i-dashboard') + '"/></svg>' +
        '<span class="ws-open-menu-label">' + esc(src.textContent.trim()) + '</span>' +
        (open ? '<span class="ws-open-menu-open">open</span>' : '');
      // An already-open feature switches to its tab rather than opening a second one, which is
      // why every entry stays clickable instead of going grey.
      item.addEventListener('click', () => { closeWorkspaceMenu(); navigateTo(page); });
      menu.appendChild(item);
    });
  }

  function openWorkspaceMenu() {
    const menu = $('ws-open-menu');
    const btn = $('ws-tab-new-btn');
    if (!menu || !btn) return;
    renderWorkspaceMenu();
    menu.classList.remove('hidden');
    btn.setAttribute('aria-expanded', 'true');

    // The bar scrolls horizontally, so the "+" is not at a fixed x. Anchor to where it actually
    // is, and keep the panel on screen when it sits near the right edge.
    const rect = btn.getBoundingClientRect();
    menu.style.top = rect.bottom + 4 + 'px';
    menu.style.left = Math.min(rect.left, window.innerWidth - menu.offsetWidth - 12) + 'px';
    menu.querySelector('.ws-open-menu-item')?.focus();
  }

  function closeWorkspaceMenu({ refocus = false } = {}) {
    const menu = $('ws-open-menu');
    if (!menu || menu.classList.contains('hidden')) return;
    menu.classList.add('hidden');
    $('ws-tab-new-btn')?.setAttribute('aria-expanded', 'false');
    if (refocus) $('ws-tab-new-btn')?.focus();
  }

  function toggleWorkspaceMenu() {
    if ($('ws-open-menu')?.classList.contains('hidden')) openWorkspaceMenu();
    else closeWorkspaceMenu({ refocus: true });
  }

  function focusWorkspaceTabAt(index) {
    const buttons = $('ws-tab-bar')?.querySelectorAll('.ws-tab-main');
    buttons?.[index]?.focus();
  }

  function bindWorkspaceTabs() {
    const bar = $('ws-tab-bar');
    if (!bar) return;
    // Manual activation: arrows move focus, Enter/Space (the button's own behaviour) opens. A
    // screen can cost API calls to load, so arrowing past one must not load it.
    bar.addEventListener('keydown', e => {
      const buttons = Array.from(bar.querySelectorAll('.ws-tab-main'));
      const i = buttons.indexOf(document.activeElement);
      if (i === -1) return;

      if (e.key === 'ArrowRight')     { e.preventDefault(); focusWorkspaceTabAt((i + 1) % buttons.length); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); focusWorkspaceTabAt((i - 1 + buttons.length) % buttons.length); }
      else if (e.key === 'Home')      { e.preventDefault(); focusWorkspaceTabAt(0); }
      else if (e.key === 'End')       { e.preventDefault(); focusWorkspaceTabAt(buttons.length - 1); }
      else if (e.key === 'Delete' || e.key === 'Backspace') {
        const tab = workspaceTabs[i];
        if (!tab || tab.pinned) return;
        e.preventDefault();
        closeWorkspaceTab(tab.id);
        // Keep the keyboard in the bar: focus whatever slid into that slot.
        focusWorkspaceTabAt(Math.min(i, workspaceTabs.length - 1));
      }
    });

    on('ws-tab-new-btn', 'click', toggleWorkspaceMenu);

    const menu = $('ws-open-menu');
    menu?.addEventListener('keydown', e => {
      const items = Array.from(menu.querySelectorAll('.ws-open-menu-item'));
      const i = items.indexOf(document.activeElement);
      // Several screens close themselves on a document-level Escape. Dismissing this menu must
      // not also close the screen behind it, so the key stops here.
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        closeWorkspaceMenu({ refocus: true });
        return;
      }
      if (i === -1) return;
      if (e.key === 'ArrowDown')    { e.preventDefault(); items[(i + 1) % items.length].focus(); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); items[(i - 1 + items.length) % items.length].focus(); }
      else if (e.key === 'Home')    { e.preventDefault(); items[0].focus(); }
      else if (e.key === 'End')     { e.preventDefault(); items[items.length - 1].focus(); }
    });

    // Clicking anywhere else is a dismissal, including onto the screen behind the menu.
    document.addEventListener('pointerdown', e => {
      if (e.target.closest?.('#ws-open-menu, #ws-tab-new-btn')) return;
      closeWorkspaceMenu();
    });
  }

  function initWorkspaceTabs() {
    workspaceTabs = [];
    activeWorkspaceTabId = null;
    const home = newWorkspaceTab('dashboard');
    home.loaded = true;
    activeWorkspaceTabId = home.id;
    bindWorkspaceTabs();
    renderWorkspaceTabs();
  }

  function showAiSection() {
    openNewListingModal();
  }

  // Every full-screen view in the app, including the AI Listing modal: hiding "the screens" has
  // to mean all of them, or navigating out of a draft leaves it sitting on top of the next one.
  // 'copilot-section' was missing from this list, which is a bigger bug than it looks: every other
  // screen calls hideOverlaySections() on the way in, so leaving the Copilot out meant navigating
  // AWAY from it left it on screen, sitting over whatever you had just opened. Opening a rewritten
  // draft was where it showed — the AI Listing tab opened and went active, the route changed to
  // #ai, and the Copilot was still the thing you were looking at.
  const OVERLAY_SECTIONS = ['settings-section', 'logs-section', 'license-section', 'opportunity-section', 'photo-library-section', 'inventory-section', 'offers-section', 'rescue-section', 'budget-section', 'relist-section', 'lots-section', 'promoted-section', 'shipping-section', 'whatsnot-section', 'trends-section', 'radar-section', 'snap-section', 'wts-section', 'snipe-section', 'earnings-section', 'tax-section', 'storeplan-section', 'restock-section', 'position-section', 'pipeline-section', 'copilot-section', 'new-listing-overlay'];

  function hideOverlaySections() {
    OVERLAY_SECTIONS.forEach(id => $(id)?.classList.add('hidden'));
  }

  function showDashboard() {
    hideOverlaySections();
    // Closing an overlay has to clear the hash too, or the URL keeps claiming we're on a page
    // that is no longer open — which breaks the next click on that sidebar entry and makes a
    // reload land on a section the user already closed. replaceState fires no hashchange, so
    // this can't loop back into handleNav.
    if (location.hash && location.hash !== '#dashboard')
      history.replaceState(null, '', location.pathname + location.search);
    $('dashboard-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setActiveNavItem('dashboard');
    markWorkspaceTabOpen('dashboard');
  }

  // Settings has no `refresh` hook on purpose: every return to the tab would re-run
  // loadSettingsStatus() over inputs the seller may be halfway through typing into.
  async function showSettingsSection() {
    hideOverlaySections();
    $('settings-section')?.classList.remove('hidden');
    $('settings-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setActiveNavItem('settings');
    markWorkspaceTabOpen('settings');
    // Paints the panel, never runs the check: the doctor costs two Chrome
    // launches, so arriving at Settings must not start one.
    renderConnectionsPanel();
    await refreshRequiredState();
    await loadSettingsStatus();
    await loadFacebookStatus();
  }

  // ── The Settings rail ─────────────────────────────────────────────────────
  // Scroll-spy over the six cards on the Settings page, plus click-to-scroll.
  //
  // The rail is buttons and not <a href="#pg-fees-card">, and the reason is not
  // cosmetic: location.hash is this app's router — see handleNav — so a real
  // anchor would navigate the whole workspace away from Settings on its way to a
  // card six inches down the page. Nothing here reads or writes the hash.
  function initSettingsNav() {
    const nav = $('settings-nav');
    if (!nav) return;

    const targets = Array.from(nav.querySelectorAll('.settings-nav-link'))
      .map(link => ({ link, el: $(link.dataset.settingsTarget) }))
      .filter(t => t.el);
    if (!targets.length) return;

    let current = null;

    function mark(link) {
      if (link === current) return;
      current = link;
      targets.forEach(({ link: l }) => {
        if (l === link) l.setAttribute('aria-current', 'true');
        else l.removeAttribute('aria-current');
      });
    }

    // Whichever card crossed the reading line last. It starts on the first one
    // rather than on nothing, because a rail with no mark on it reads as broken.
    function spy() {
      const line = Math.max(96, window.innerHeight * 0.28);
      let found = targets[0];
      for (const t of targets) {
        if (t.el.getBoundingClientRect().top <= line) found = t;
      }
      // The last card is often too short to ever reach the line. At the bottom of
      // the document it is the one being read, whatever the arithmetic says.
      const atEnd = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 4;
      mark((atEnd ? targets[targets.length - 1] : found).link);
    }

    let ticking = false;
    function onScroll() {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        ticking = false;
        // Settings is one of twenty-odd sections sharing this scroll container.
        if ($('settings-section')?.classList.contains('hidden')) return;
        spy();
      });
    }

    targets.forEach(({ link, el }) => {
      link.addEventListener('click', () => {
        // Marked before the scroll, not after it: the answer to a click is owed
        // immediately, and smooth scrolling takes a few hundred milliseconds.
        mark(link);
        el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll, { passive: true });
    mark(targets[0].link);
  }

  // The header chip on an optional connect strip. Three strips, one look, so "connected" means
  // the same thing at a glance whichever one you are reading.
  function setConnectState(id, on, onText, offText) {
    const chip = $(id);
    if (!chip) return;
    chip.textContent = on ? onText : offText;
    chip.classList.toggle('is-on', !!on);
  }

  // ── Facebook Marketplace (local sourcing) ────────────────────────────────
  // Same connect/status/disconnect shape as Terapeak above, for the same reason: no public
  // API, so the seller logs into their own account once in a real browser window and the
  // saved session is reused. Searching is always a click — nothing polls Facebook.
  const FACEBOOK_BANNERS = [
    ['pg-facebook-status', 'pg-facebook-connect', 'pg-facebook-disconnect'],
    ['fb-connect-status', 'fb-connect-btn', 'fb-disconnect-btn'],
    ['setup-facebook-status', 'setup-facebook-connect', 'setup-facebook-disconnect'],
  ];

  function paintFacebookBanner(statusEl, connectBtn, disconnectBtn, data) {
    if (!statusEl) return;
    if (data.loginInProgress) {
      statusEl.textContent = 'Connecting — log into Facebook in the browser window that opened. Don\'t see it? Alt+Tab, or check the taskbar for the login window.';
      connectBtn?.classList.remove('hidden');
      if (connectBtn) connectBtn.disabled = true;
      disconnectBtn?.classList.add('hidden');
    } else if (data.connected) {
      statusEl.textContent = '✓ Connected — local Marketplace search is ready.';
      connectBtn?.classList.add('hidden');
      disconnectBtn?.classList.remove('hidden');
    } else {
      // A session that died is not the same as one that was never made: the seller already did
      // this once, and "Not connected" reads to them as the app having forgotten it. The server
      // says which it is — see FacebookSessionFile.
      statusEl.textContent = data.lastError
        ? `Facebook connect failed: ${data.lastError}`
        : data.reason && data.state && data.state !== 'Missing'
        ? `${data.reason} Click ${data.needsReconnect ? 'Reconnect' : 'Connect'} to sign in again.`
        : 'Not connected — click Connect to log into your own Facebook account once.';
      if (connectBtn && data.needsReconnect) connectBtn.textContent = 'Reconnect Facebook';
      connectBtn?.classList.remove('hidden');
      if (connectBtn) connectBtn.disabled = false;
      disconnectBtn?.classList.add('hidden');
    }
    // The search buttons are NOT tied to Facebook any more: Craigslist needs no login, so a
    // disconnected Facebook only removes one source. What gates the buttons is whether any
    // source is ticked at all — see refreshLocalSearchButtons.
    refreshLocalSearchButtons();
  }

  async function loadFacebookStatus() {
    try {
      const data = await fetch('/api/facebook/status').then(r => r.json());
      FACEBOOK_BANNERS.forEach(([statusId, connectId, disconnectId]) =>
        paintFacebookBanner($(statusId), $(connectId), $(disconnectId), data));
      setConnectState('pg-facebook-state', data.connected, 'Connected', 'Not connected');
      markSetupStep('step4', data.connected, 'Connected');
      const row4 = $('step4-row');
      if (row4) row4.dataset.known = '1';
      refreshChecklistVisibility();
      // A Facebook connect/disconnect changes what the source list says about itself.
      loadLocalSources();
      return data;
    } catch (err) {
      FACEBOOK_BANNERS.forEach(([statusId]) => {
        const el = $(statusId);
        if (el) el.textContent = `Unable to check Facebook status: ${errorText(err)}`;
      });
      return null;
    }
  }

  async function facebookConnect(e) {
    const btn = e?.currentTarget || $('pg-facebook-connect');
    try {
      if (btn) btn.disabled = true;
      const data = await fetch('/api/facebook/connect', { method: 'POST' }).then(r => r.json());
      FACEBOOK_BANNERS.forEach(([statusId]) => {
        const el = $(statusId);
        if (el) el.textContent = data.message || 'Opening browser…';
      });
      const poll = setInterval(async () => {
        const s = await fetch('/api/facebook/status').then(r => r.json()).catch(() => null);
        if (s && !s.loginInProgress) {
          clearInterval(poll);
          await loadFacebookStatus();
        }
      }, 3000);
    } catch (err) {
      FACEBOOK_BANNERS.forEach(([statusId]) => {
        const el = $(statusId);
        if (el) el.textContent = `Connect failed: ${errorText(err)}`;
      });
      if (btn) btn.disabled = false;
    }
  }

  async function facebookDisconnect() {
    await fetch('/api/facebook/disconnect', { method: 'POST' }).catch(() => {});
    await loadFacebookStatus();
  }

  // The topbar's "Log into eBay" and the connection doctor's "Connect eBay" have
  // to start the same flow, including the part where missing developer keys send
  // you to the setup modal instead of to a broken auth URL — two copies of that
  // is how one of them ends up sending people somewhere useless.
  async function startEbayConnect() {
    try {
      const status = await fetch('/api/setup/status').then(r => r.json());
      const hasEbayCreds = status.hasEbayClientId && status.hasEbayClientSecret;
      if (!hasEbayCreds) {
        openSetup(status);
        showResult('error', 'Add your eBay Client ID and Client Secret in Settings first.');
        return;
      }
      // A refusal here is deliberate and already explained — the URL was not built because it
      // could not have come back. Show that reason rather than the response text, which is how
      // "eBay login failed: {}" used to be all anybody saw.
      const res  = await fetch('/api/ebay/auth-url');
      const body = await res.json().catch(() => null);
      if (!res.ok || !body?.url) {
        openSetup(null);
        showResult('error', body?.error
          ? `Can't start the eBay sign-in: ${esc(body.error)} ${esc(body.nextAction || '')}`
          : 'Can\'t start the eBay sign-in, and the app gave no reason. Check Settings → eBay → Advanced.');
        return;
      }
      window.location.href = body.url;
    } catch (err) {
      openSetup(null);
      showResult('error', `eBay login failed: ${esc(errorText(err))}`);
    }
  }

  // ── Connection doctor ────────────────────────────────────────────────────
  // The Settings panel that answers "is this actually connected, and if not,
  // why". Everything above this line reports a connection from a saved flag — a
  // session file on disk, a token in the credentials store — which is how a
  // revoked eBay grant, a dead Facebook login and an unreachable comps host all
  // went on looking identical (and, in two of the three cases, looking fine).
  // /api/diagnostics/connections goes and asks instead; see ConnectionDoctor.
  //
  // Two rules this panel does not bend:
  //   * A row reads Connected only when the doctor just said Connected. There is
  //     no optimistic paint and no "assume ok while loading" — before a check and
  //     during one, every row is explicitly unknown.
  //   * Nothing runs it on the way past. Two Chrome launches and up to a minute
  //     is a button, not a poll, so Settings opens on the idle state.

  /** The last verdict and when it was taken, or null if never asked this session. */
  let lastConnectionCheck = null;
  let connectionCheckInFlight = false;

  /**
   * The fix behind each row, matched against the name the doctor reports rather
   * than an id it doesn't send. Facebook/Terapeak/comps are tested before eBay
   * because "eBay OAuth" is the loosest pattern of the four.
   */
  const CONNECTION_FIXES = [
    {
      key: 'facebook', match: /facebook/i, label: 'Connect Facebook', run: facebookConnect,
      // NEEDS-HUMAN, said in the row rather than left to be discovered: this
      // opens a real browser window and then waits for a person to type a
      // password into it. A window that opened behind the app is the single
      // most common way this looks like a hung button.
      human: 'Sign in to Facebook in the window that opens.',
      // Without Node/Playwright, Connect cannot work at all and the doctor's own
      // next action is "install Node" — offering the button anyway is a dead end.
      unavailableIn: ['NotConfigured'],
    },
    // There is no per-connection endpoint, so this re-runs the doctor. The comps
    // answer it gives back is a fresh live query either way, which is what the
    // button promises.
    { key: 'comps', match: /comps/i, label: 'Test comps API', run: () => checkConnections() },
    {
      key: 'ebay', match: /ebay/i, label: 'Connect eBay', run: startEbayConnect,
      human: 'eBay opens its own sign-in page — accept every permission it asks for.',
    },
  ];

  /** Chip wording per doctor state. "Connected" is reachable from Ok and nowhere else. */
  const CONNECTION_STATE_LABEL = {
    Ok: 'Connected',
    NotConfigured: 'Not set up',
    NoSession: 'Not signed in',
    SessionExpired: 'Sign-in expired',
    AuthRejected: 'Sign-in refused',
    Unreachable: 'Couldn\'t reach it',
  };

  /**
   * ok = the doctor proved it. bad = a login to fix. warn = nothing wrong with
   * the credentials (unreachable, or never set up — three of the four are
   * optional and "not set up" must not read as a failure). unknown = we don't
   * know, which is where a half-answer lands rather than defaulting to green.
   */
  function connectionTone(c) {
    if (c.connected === true && c.state === 'Ok') return 'ok';
    if (c.connected === true || c.state === 'Ok') return 'unknown';
    return c.state === 'Unreachable' || c.state === 'NotConfigured' ? 'warn' : 'bad';
  }

  function connectionFixFor(name) {
    return CONNECTION_FIXES.find(f => f.match.test(name || '')) || null;
  }

  function connectionRowHtml(c) {
    const tone = connectionTone(c);
    const connected = tone === 'ok';
    const fix = connectionFixFor(c.name);
    // "Nothing to do." is how the doctor says a connected row needs nothing.
    // Anything else on a connected row is a warning worth acting on before it
    // becomes an outage — an eBay refresh token a fortnight from expiring is
    // connected today and dead listings on the day it lapses.
    const actionable = !connected || (c.nextAction && c.nextAction !== 'Nothing to do.');
    const canFix = !!fix && actionable && !(fix.unavailableIn || []).includes(c.state);

    // Everything below is escaped, and nothing here is a credential: the doctor's
    // Detail carries status codes, expiry dates and row counts only, never a
    // token, cookie, key or URL with one in it.
    return `
      <div class="cd-row cd-row--${tone}" data-cd-row="${esc(fix ? fix.key : c.name)}">
        <div class="cd-row-body">
          <div class="cd-row-head">
            <span class="cd-row-name">${esc(c.name)}</span>
            <span class="cd-chip">${esc(CONNECTION_STATE_LABEL[c.state] || 'Unknown')}</span>
          </div>
          <p class="cd-reason">${esc(c.reason)}</p>
          ${!connected && fix?.human ? `<p class="cd-human"><strong>Needs you:</strong> ${esc(fix.human)}</p>` : ''}
          ${actionable && c.nextAction ? `<p class="cd-next">${esc(c.nextAction)}</p>` : ''}
          ${c.detail ? `<p class="cd-detail">${esc(c.detail)}</p>` : ''}
        </div>
        ${canFix ? `<div class="cd-row-actions">
          <button class="btn ${connected ? 'btn-secondary' : 'btn-primary'} small" type="button"
                  data-cd-fix="${esc(fix.key)}">${esc(fix.label)}</button>
        </div>` : ''}
      </div>`;
  }

  /** The head chip. Never says anything about connections it hasn't been told about. */
  function setConnectionsSummary(text, allGood = false) {
    setConnectState('cd-summary', allGood, text, text);
  }

  function renderConnectionResults(rows, checkedAt) {
    const host = $('cd-rows');
    if (!host) return;
    host.innerHTML = rows.map(connectionRowHtml).join('');
    const good = rows.filter(c => connectionTone(c) === 'ok').length;
    const clock = checkedAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    // The time is part of the verdict: a result from twenty minutes ago is a
    // claim about twenty minutes ago, and this panel doesn't refresh itself.
    setConnectionsSummary(`${good} of ${rows.length} connected · ${clock}`, good === rows.length);
  }

  /**
   * What Settings opens on. Says plainly that nothing has been tested rather
   * than showing four hopeful rows — the panel exists because unearned green
   * chips were the original problem.
   */
  function renderConnectionsPanel() {
    const host = $('cd-rows');
    if (!host) return;
    if (lastConnectionCheck) {
      renderConnectionResults(lastConnectionCheck.rows, lastConnectionCheck.at);
      return;
    }
    renderState(host, {
      icon: 'i-plug',
      compact: true,
      title: 'Connections haven\'t been checked yet',
      body: 'This tests all four for real — an eBay token refresh and an authenticated API call, both saved browser logins replayed, and a live query against the comps API — then says exactly what\'s wrong with any that are down.',
      hint: 'Takes up to a minute, so it only runs when you ask it to.',
      actions: [{ label: 'Check connections', id: 'check', kind: 'btn-primary' }],
    }, { check: () => checkConnections() });
    setConnectionsSummary('Not checked yet');
  }

  async function checkConnections() {
    const host = $('cd-rows');
    if (!host || connectionCheckInFlight) return;
    connectionCheckInFlight = true;
    $('cd-recheck')?.classList.add('is-busy');
    // Skeletons, not the last verdict dimmed: while the check is running we do
    // not know the answer, and the previous answer is exactly the stale claim
    // this panel was built to stop making.
    host.innerHTML = skeletonRowsHtml(4);
    setConnectionsSummary('Checking…');

    try {
      const res = await fetch('/api/diagnostics/connections');
      if (!res.ok) throw new Error(`The diagnostics endpoint answered HTTP ${res.status}.`);
      const rows = (await res.json())?.connections;
      if (!Array.isArray(rows) || rows.length === 0)
        throw new Error('The diagnostics endpoint returned no connections.');
      lastConnectionCheck = { rows, at: new Date() };
      renderConnectionResults(rows, lastConnectionCheck.at);
    } catch (err) {
      // A failed check is not a failed connection — it says nothing about any of
      // them, so nothing gets a verdict here.
      renderState(host, {
        variant: 'error',
        compact: true,
        title: 'Couldn\'t run the connection check',
        body: 'The app is running but the diagnostics endpoint didn\'t answer, so none of the four connections were tested. Nothing below is a verdict on them.',
        detail: errorText(err),
        actions: [{ label: 'Try again', id: 'retry', kind: 'btn-primary' }],
      }, { retry: () => checkConnections() });
      setConnectionsSummary('Check failed');
    } finally {
      connectionCheckInFlight = false;
      $('cd-recheck')?.classList.remove('is-busy');
    }
  }

  /**
   * A verdict was true when it was taken and stops being true the moment a fix
   * starts. Rather than leave "sign-in expired" on screen next to the login
   * window the seller is typing into, the row says what it is now waiting for —
   * and still doesn't turn green until a re-check earns it.
   */
  function markConnectionRowWaiting(fix) {
    const row = document.querySelector(`#cd-rows [data-cd-row="${fix.key}"]`);
    if (!row) return;
    const name = row.querySelector('.cd-row-name')?.textContent || fix.label;
    row.className = 'cd-row cd-row--unknown';
    row.innerHTML = `
      <div class="cd-row-body">
        <div class="cd-row-head">
          <span class="cd-row-name">${esc(name)}</span>
          <span class="cd-chip">Waiting for you</span>
        </div>
        <p class="cd-human"><strong>Needs you:</strong> ${esc(fix.human)}
          Don't see it? Alt+Tab, or check the taskbar for the login window.</p>
        <p class="cd-next">When you're done, click Re-check all — this panel won't call it connected until a check proves it.</p>
      </div>`;
    setConnectionsSummary('Re-check when you\'re done');
  }

  function bindConnectionDoctor() {
    on('cd-recheck', 'click', () => checkConnections());
    // Delegated: the rows are replaced on every check, so binding per button
    // would leave the fixes wired to markup that is no longer on the page.
    $('cd-rows')?.addEventListener('click', e => {
      const btn = e.target.closest('[data-cd-fix]');
      if (!btn) return;
      const fix = CONNECTION_FIXES.find(f => f.key === btn.dataset.cdFix);
      if (!fix) return;
      if (fix.human) markConnectionRowWaiting(fix);
      // Called with no event on purpose: facebookConnect falls
      // back to their own Settings buttons, which are on this same page and are
      // the ones that should show "connecting…" — the row above has already been
      // replaced by then.
      fix.run();
    });
  }

  // ── Pluggable local supply sources ───────────────────────────────────────
  // The panel below searches whichever sites are ticked here, and the list is rendered from
  // /api/local/sources rather than hard-coded — a source added on the server shows up here on
  // its own. Craigslist is public (no login); Facebook needs its saved session.
  let localSources = [];

  function selectedSourceIds() {
    return [...document.querySelectorAll('#local-source-picker input[type=checkbox]')]
      .filter(cb => cb.checked).map(cb => cb.value);
  }

  // Gated on "is any site selected", not on any one site's connection: Craigslist alone is a
  // complete local search, so a disconnected Facebook must not disable the buttons.
  function refreshLocalSearchButtons() {
    const picked = selectedSourceIds();
    ['fb-search-btn', 'fb-arb-btn'].forEach(id => {
      const btn = $(id);
      if (btn) btn.disabled = picked.length === 0;
    });
    // The metro override only means anything to Craigslist.
    $('cl-site-row')?.classList.toggle('hidden', !picked.includes('craigslist'));
    if (picked.includes('craigslist')) loadCraigslistSites();
    // "Leave it blank" is only true advice while a source that means something by a blank search is
    // ticked — on every other one an empty query is the whole classifieds section.
    $('fb-blank-query-hint')?.classList.toggle('hidden', !picked.some(allowsBlankQuery));
    renderManualSites(picked);
    // Zip and radius mean nothing to a nationwide feed. Dimmed rather than hidden — untick the
    // online source and they matter again, and a field that vanishes is a field people hunt for.
    const online = picked.length > 0 && picked.every(id => !isLocationBasedSource(id));
    ['fb-zip-input', 'fb-radius-select'].forEach(id => {
      const el = $(id);
      if (el) el.disabled = online;
    });
  }

  // Which sources charge sales tax / ignore the zip. Read off /api/local/sources rather than
  // hard-coded, so a second online source needs no change here.
  function isLocationBasedSource(id) {
    const source = localSources.find(s => s.id === id);
    return source ? source.locationBased !== false : true;
  }

  // Whether buying from this source puts sales tax on the bill. Read off the source rather than
  // inferred from "is it nationwide", which was only ever right by coincidence — a liquidation
  // auction is local AND taxed, and inferring would have silently priced it tax-free.
  function chargesSalesTax(id) {
    const source = localSources.find(s => s.id === id);
    return source ? source.chargesSalesTax === true : false;
  }

  // Whether a blank keyword is a real search on this source. True only for the freebie board, where
  // "everything being given away near me" is the best search there is — a seller shopping for free
  // things does not care what they are. Read off the source rather than hard-coded here.
  function allowsBlankQuery(id) {
    const source = localSources.find(s => s.id === id);
    return source ? source.allowsBlankQuery === true : false;
  }

  // The liquidation marketplaces this app deliberately doesn't scrape, offered as prefilled
  // searches. Rendered from the source's own list so the URLs live on the server.
  function renderManualSites(picked) {
    const row = $('manual-sites-row');
    const links = $('manual-sites-links');
    if (!row || !links) return;

    const sites = picked.flatMap(id => localSources.find(s => s.id === id)?.manualSites || []);
    row.classList.toggle('hidden', sites.length === 0);
    if (sites.length === 0) return;

    // The query is read at click time, not now: the seller types it after ticking the source.
    links.innerHTML = sites.map(s =>
      `<a class="manual-site-link" href="#" data-url="${esc(s.urlTemplate)}" title="${esc(s.note)}">${esc(s.label)} ↗</a>`
    ).join('');

    links.querySelectorAll('.manual-site-link').forEach(link => {
      link.addEventListener('click', event => {
        event.preventDefault();
        const query = ($('fb-query-input')?.value || '').trim();
        if (!query) { setLocalStatus('Type what you are looking for first — these open a search on that site.'); return; }
        window.open(link.dataset.url.replace('{query}', encodeURIComponent(query)), '_blank', 'noopener');
      });
    });
  }

  async function loadLocalSources() {
    const picker = $('local-source-picker');
    if (!picker) return;

    // The picker is the panel's front door — with nothing to tick there is nothing to search, so
    // a failure here offers the retry rather than leaving a sentence and a dead panel.
    const { data, error } = await localFetchJson('/api/local/sources', 20000);
    // An empty list means the server couldn't describe its sources — same dead panel as a failed
    // request, so it gets the same treatment rather than a picker with nothing in it.
    if (!Array.isArray(data) || !data.length) {
      picker.innerHTML = `${esc(`Couldn't load the list of places to search. ${error || ''}`.trim())} ` +
        '<button type="button" class="btn btn-secondary small local-sources-retry">Try again</button>';
      picker.querySelector('.local-sources-retry')?.addEventListener('click', loadLocalSources);
      return;
    }
    // eBay is filtered out on purpose: it has its own scanner panel above this one, and listing
    // it in both places is how the panel got confusing enough to need splitting.
    localSources = data.filter(s => s.id !== EBAY_SOURCE_ID);

    // A remembered choice wins; on a first run the default is everything that can answer right
    // now, which on a fresh install is Craigslist alone.
    const saved = (localStorage.getItem('localSources') || '').split(',').filter(Boolean);
    picker.innerHTML = localSources.map(s => {
      const checked = saved.length ? saved.includes(s.id) : s.available;
      const badge = !s.requiresConnection ? 'no login'
        : s.available ? 'connected' : 'needs login';
      return `<label class="local-source${s.available ? '' : ' local-source-off'}" title="${esc(s.note || '')}">
                <input type="checkbox" value="${esc(s.id)}"${checked ? ' checked' : ''} />
                <span class="local-source-name">${esc(s.label)}</span>
                <span class="local-source-badge">${badge}</span>
              </label>`;
    }).join('');

    picker.querySelectorAll('input[type=checkbox]').forEach(cb => cb.addEventListener('change', () => {
      localStorage.setItem('localSources', selectedSourceIds().join(','));
      refreshLocalSearchButtons();
      // The category note names which of the ticked sites can search a board rather than a keyword,
      // so it has to be redrawn when that set changes.
      renderCategoryNote();
    }));
    refreshLocalSearchButtons();
    renderCategoryNote();
  }

  // ── Categories ────────────────────────────────────────────────────────────
  // What KIND of thing to look for, which is three decisions rather than a filter: which craigslist
  // board is searched, what is allowed to put a resale price on a row, and what selling it costs.
  // Rendered from /api/local/categories so the list lives in ResaleCategoryCatalog on the server.
  let localCategories = [];

  function selectedCategoryId() {
    return $('fb-category-select')?.value || 'anything';
  }

  async function loadLocalCategories() {
    const sel = $('fb-category-select');
    if (!sel) return;

    const { data } = await localFetchJson('/api/local/categories', 20000);
    // A failed load is survivable in a way a failed source load isn't: the picker keeps its single
    // "Anything" option, which is exactly what the scanner did before categories existed.
    if (!Array.isArray(data) || !data.length) return;

    localCategories = data;

    // Grouped, because "Cars & trucks" and "Tools" are not the same kind of choice — one changes
    // the fee model and the valuation, the other changes neither.
    const groups = [...new Set(localCategories.map(c => c.group))];
    sel.innerHTML = groups.map(group => {
      const inGroup = localCategories.filter(c => c.group === group);
      const options = inGroup.map(c =>
        `<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('');
      // The default group holds one entry and needs no heading above it.
      return inGroup.length === 1 && group === 'Anything' ? options : `<optgroup label="${esc(group)}">${options}</optgroup>`;
    }).join('');

    const saved = localStorage.getItem('localCategory');
    if (saved && localCategories.some(c => c.id === saved)) sel.value = saved;

    sel.addEventListener('change', () => {
      localStorage.setItem('localCategory', sel.value);
      renderCategoryNote();
    });
    renderCategoryNote();
  }

  // What the chosen category does, said before the scan rather than after it. The part that matters
  // is the refusal: a seller who picks Boats is told here that this app has no sold-comp source for
  // them, instead of waiting two minutes to be shown a column of dashes.
  function renderCategoryNote() {
    const note = $('fb-category-note');
    if (!note) return;

    const category = localCategories.find(c => c.id === selectedCategoryId());
    if (!category || category.id === 'anything') {
      note.classList.add('hidden');
      note.innerHTML = '';
      return;
    }

    // Craigslist is the only source with a board per category. Saying so stops "Cars & trucks"
    // looking broken when Facebook returns a floor mat: it was searched by keyword, because that is
    // all Facebook offers.
    const boardSources = (localSources || []).filter(s => s.supportsCategoryBoards).map(s => s.label);
    const others = (localSources || []).filter(s => !s.supportsCategoryBoards).map(s => s.label);

    note.innerHTML =
      `<strong>${esc(category.label)}</strong> — ${esc(category.hint)}` +
      (boardSources.length
        ? `<span class="fb-category-scope">${esc(boardSources.join(' + '))} searches that board directly` +
          `${others.length ? `; ${esc(others.join(', '))} can only be searched by keyword, so their results are sorted into categories afterwards` : ''}.</span>`
        : '') +
      (category.valuedByHand
        ? '<span class="fb-category-manual">This app has no sold-price source it trusts for these, so rows it can\'t ' +
          'check come back marked <em>estimate unavailable</em> with a link to the eBay sold listings — never a made-up number.</span>'
        : '');
    note.classList.remove('hidden');
  }

  // Craigslist's metro list is ~230 entries and only matters if the auto-picked board is wrong,
  // so it's fetched once, on demand, rather than on every page load.
  async function loadCraigslistSites() {
    const sel = $('cl-site-select');
    if (!sel || sel.dataset.loaded) return;
    sel.dataset.loaded = '1';
    try {
      const sites = await fetch('/api/craigslist/sites').then(r => r.json());
      sel.insertAdjacentHTML('beforeend', sites
        .map(s => `<option value="${esc(s.id)}">${esc(s.label)}, ${esc(s.state)}</option>`).join(''));
      const saved = localStorage.getItem('clSite');
      if (saved) sel.value = saved;
    } catch {
      // Auto-resolution from the zip still works; only the manual override is unavailable.
      sel.dataset.loaded = '';
    }
  }

  function bindFacebookMarketplace() {
    on('pg-facebook-connect', 'click', facebookConnect);
    on('pg-facebook-disconnect', 'click', facebookDisconnect);
    on('fb-connect-btn', 'click', facebookConnect);
    on('fb-disconnect-btn', 'click', facebookDisconnect);
    on('fb-search-btn', 'click', runLocalSearch);
    on('fb-arb-btn', 'click', runLocalArbitrage);
    on('cl-site-select', 'change', e => localStorage.setItem('clSite', e.currentTarget.value));
    // Enter runs the ranked scan, not the plain list — the ranking is what the panel is for,
    // and the plain list is one click away.
    on('fb-query-input', 'keydown', e => { if (e.key === 'Enter') runLocalArbitrage(); });
    on('fb-zip-input', 'keydown', e => { if (e.key === 'Enter') runLocalArbitrage(); });
    on('fb-arb-sort', 'change', renderArbitrageRows);
    on('fb-arb-category', 'change', renderArbitrageRows);
    on('fb-arb-price', 'change', renderArbitrageRows);
    on('fb-arb-hide-losers', 'change', renderArbitrageRows);
    on('fb-arb-proven-only', 'change', renderArbitrageRows);
    on('fb-arb-fast-only', 'change', renderArbitrageRows);
    on('fb-arb-warranty-only', 'change', renderArbitrageRows);
    on('ebay-scan-btn', 'click', runEbayScan);
    on('fb-picks-btn', 'click', () => loadFacebookPicks(true));
    on('fb-picks-search-btn', 'click', () => loadFacebookPicks(true));
    on('fb-picks-query', 'keydown', e => { if (e.key === 'Enter') { e.preventDefault(); loadFacebookPicks(true); } });
    // Changing a filter is the search: a dropdown that needs a second click to take effect
    // is how people conclude a filter does nothing.
    ['fb-picks-category','fb-picks-sort','fb-picks-condition','fb-picks-date','fb-picks-delivery','fb-picks-radius']
      .forEach(id => on(id, 'change', () => loadFacebookPicks(true)));
    restoreEbayScanFilters();
    // Enter in the eBay box scans, rather than doing nothing on a one-field form.
    on('ebay-scan-query', 'keydown', e => { if (e.key === 'Enter') { e.preventDefault(); runEbayScan(); } });
    // The seller's zip and radius don't change between searches — remembering them is the
    // difference between a two-field search and a one-field one.
    const zip = localStorage.getItem('fbZip');
    const radius = localStorage.getItem('fbRadius');
    if (zip && $('fb-zip-input')) $('fb-zip-input').value = zip;
    if (radius && $('fb-radius-select')) $('fb-radius-select').value = radius;
  }

  // The form values every local search shares, plus the selected sources. Craigslist's metro
  // override rides along and is ignored by every other source.
  function localSearchParams() {
    const query = $('fb-query-input')?.value.trim() || '';
    const zip = $('fb-zip-input')?.value.trim() || '';
    const radius = $('fb-radius-select')?.value || '40';
    const sources = selectedSourceIds();
    const site = $('cl-site-select')?.value || '';
    const category = selectedCategoryId();

    localStorage.setItem('fbZip', zip);
    localStorage.setItem('fbRadius', radius);

    const qs = `q=${encodeURIComponent(query)}&zip=${encodeURIComponent(zip)}&radius=${encodeURIComponent(radius)}` +
      `&sources=${encodeURIComponent(sources.join(','))}` +
      // Sent on every scan. Not a filter — it picks the craigslist board, the valuation provider and
      // the fee model server-side. See ResaleCategoryCatalog.
      `&category=${encodeURIComponent(category)}` +
      (site ? `&craigslistSite=${encodeURIComponent(site)}` : '');

    return { query, zip, radius, sources, category, qs };
  }

  // Whether "no keyword at all" is a real search this time. It is when a category board is being
  // searched by a source that has boards: "everything on the cars board within 40 miles" is exactly
  // what picking a category means, and demanding a keyword on top of it would make the picker
  // useless for the one job it is best at.
  function isBoardSearch(category, sources) {
    if (!category || category === 'anything') return false;
    return sources.some(id => localSources.find(s => s.id === id)?.supportsCategoryBoards);
  }

  function sourceLabelsFor(ids) {
    return ids.map(id => localSources.find(s => s.id === id)?.label || id).join(' + ');
  }

  // "within 40 miles of 89101" is a promise, and a nationwide feed didn't keep it. Says what was
  // actually searched: the radius only when a location-based source is in the scan, the word
  // "nationwide" only when an online one is.
  function scopeTextFor(ids, radius, zip) {
    const local = ids.some(isLocationBasedSource);
    const online = ids.some(id => !isLocationBasedSource(id));

    // A source with a radius floor searched further than the form said. Reporting the form's
    // number would be the same broken promise the nationwide feeds used to make.
    const widest = Math.max(radius || 0, ...ids.map(id =>
      localSources.find(s => s.id === id)?.minRadiusMiles || 0));

    const parts = [];
    if (local) {
      parts.push(widest > radius
        ? `within ${radius}–${widest} miles${zip ? ` of ${zip}` : ''}`
        : `within ${radius} miles${zip ? ` of ${zip}` : ''}`);
    }
    if (online) parts.push('nationwide');
    return parts.join(' and ');
  }

  // ── Never dead-ending the panel ──────────────────────────────────────────
  // The server guarantees a 200 with a valid body for every local search, however badly a site
  // behaves (see LocalSupplyGuard). This is the other half of that promise: the cases the server
  // can't reach — the app not running, the connection dropping mid-scan, a proxy returning HTML,
  // a response that never arrives — all have to end as a sentence on screen with a way forward.
  // `fetch(...).then(r => r.json())` ends every one of them as an unhandled rejection instead,
  // which is what left this panel showing a spinner and "Failed to fetch".
  //
  // Client-side ceilings, generous enough not to cut a real scan short: the point is that a
  // request which will never come back stops looking like one that is still working.
  const LOCAL_SEARCH_TIMEOUT_MS = 4 * 60 * 1000;      // Craigslist is seconds; Facebook loads a real page
  const LOCAL_ARBITRAGE_TIMEOUT_MS = 8 * 60 * 1000;   // + a sold-comp lookup per distinct product

  // The last search the seller ran, so a Try again button can repeat it without them retyping.
  let lastLocalRun = null;

  // Always resolves to { data, error } — never throws, never rejects.
  // `init` carries method/headers/body for the callers that POST. Everything else about this helper
  // — the timeout, the abort, the "a readable body wins over the status code" rule — is what every
  // caller wanted anyway, so they share it rather than each growing their own fetch.
  async function localFetchJson(url, timeoutMs, init) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, { ...(init || {}), signal: controller.signal });
      noteBackendReachable();
      const text = await res.text();

      let data = null;
      try { data = text ? JSON.parse(text) : null; } catch { data = null; }
      // A readable body wins even on a non-OK status: it carries the per-source detail, and
      // showing that beats showing the status code it arrived with.
      if (data && typeof data === 'object') return { data, error: null };

      if (!res.ok) {
        return { data: null, error: `The app answered HTTP ${res.status}${res.statusText ? ` (${res.statusText})` : ''}.` };
      }
      return { data: null, error: 'The app sent back a response this page couldn\'t read.' };
    } catch (err) {
      if (err.name === 'AbortError') {
        return {
          data: null,
          error: `No answer after ${Math.round(timeoutMs / 60000)} minutes, so the search was stopped. ` +
                 'Try again, or untick Facebook — Craigslist alone answers in seconds.',
        };
      }
      // The app not being there is its own answer, and it is not "Couldn't reach the app
      // (Failed to fetch)" — that put the browser's word for the problem in the seller's mouth.
      return { data: null, error: errorText(err, 'The search could not be run.') };
    } finally {
      clearTimeout(timer);
    }
  }

  // The panel's one status line. Takes plain text — everything shown here can contain a message
  // from a site or an exception, so it is escaped rather than trusted — plus an optional Try again
  // button wired to whichever search was last run.
  function setLocalStatus(message, retry) {
    const el = $('fb-status');
    if (!el) return;
    if (!message) { el.innerHTML = ''; return; }

    el.innerHTML = esc(message) +
      (retry && lastLocalRun ? ' <button type="button" class="btn btn-secondary small local-retry-btn">Try again</button>' : '');
    el.querySelector('.local-retry-btn')?.addEventListener('click', () => lastLocalRun && lastLocalRun());
  }

  async function runLocalSearch() {
    const { query, zip, radius, sources, category, qs } = localSearchParams();
    const btn = $('fb-search-btn');

    lastLocalRun = runLocalSearch;

    if (!query && !sources.some(allowsBlankQuery) && !isBoardSearch(category, sources))
      return setLocalStatus('Enter what you want to look for, or pick a category to browse its whole board.');
    if (!sources.length) return setLocalStatus('Tick at least one place to search.');

    $('fb-results')?.classList.add('hidden');
    if (btn) btn.disabled = true;
    // Honest about the cost, which differs per source: Craigslist is one HTTPS request, Facebook
    // is a real browser loading a page and scrolling a grid.
    setLocalStatus(`Searching ${sourceLabelsFor(sources)} ${scopeTextFor(sources, radius, zip)}` +
      `${sources.includes('facebook') ? ' — Facebook opens a real page, so give it up to a minute…' : '…'}`);

    const { data, error } = await localFetchJson(`/api/local/search?${qs}`, LOCAL_SEARCH_TIMEOUT_MS);
    if (btn) btn.disabled = false;

    if (!data) {
      setLocalStatus(`Local search didn't complete. ${error}`, true);
      return;
    }
    renderLocalResults(data);
  }

  // Everything that isn't a usable result set, handled the same way for both the plain list and
  // the arbitrage ranking. With several sources these statuses only appear when NONE of them
  // answered — one disconnected site never blanks results another site returned.
  // Returns true when it handled (and therefore ended) the render.
  function handleLocalNonResult(data) {
    if (data.status === 'no_sources') {
      setLocalStatus('Tick at least one place to search.');
      return true;
    }
    if (data.status === 'not_connected') {
      setLocalStatus(data.error || 'Connect your Facebook account above, or tick Craigslist — it needs no login.');
      loadFacebookStatus();
      return true;
    }
    if (data.status === 'session_expired') {
      setLocalStatus(data.error || 'Your saved Facebook session expired — click Connect Facebook to log in again.');
      loadFacebookStatus();
      return true;
    }
    if (data.status !== 'ok') {
      // Retryable is a per-source judgement, so the whole-search button is offered whenever any
      // site said "come back shortly" — a blocked Craigslist is the common case here.
      const retryable = (data.sources || []).some(s => s.retryable);
      setLocalStatus(data.error || 'The local search didn\'t come back with anything usable.', retryable);
      return true;
    }
    return false;
  }

  // One site answering while another doesn't is the normal case, not a failure — but a bare count
  // silently presents one site's results as the whole local market. This says which is which.
  function partialLocalNote(sources) {
    const answered = (sources || []).filter(s => s.status === 'ok');
    const missing = (sources || []).filter(s => s.status !== 'ok');
    if (!answered.length || !missing.length) return '';

    const why = missing.map(s =>
      s.status === 'not_connected' ? `${s.label} needs connecting`
      : s.status === 'session_expired' ? `${s.label}'s session expired`
      // Not a failure of the site and mustn't read as one: the scan spent its time on the sites
      // before it and never asked this one. The seller's move is different too — untick something.
      : s.status === 'skipped' ? `${s.label} wasn't reached before the scan ran out of time`
      : s.retryable ? `${s.label} is blocked right now`
      : `${s.label} couldn't be searched`).join(', ');

    return `Showing ${answered.map(s => s.label).join(' + ')} only — ${why}.`;
  }

  // What each site contributed, including the ones that couldn't answer and why — with several
  // sources in one table, "24 results" alone hides that a site failed silently. Each chip that
  // describes a fixable state carries the button that fixes it, so the seller never has to work
  // out from a sentence which of three things to click.
  // What this site was worth once the board was built, rather than what its search returned. Only
  // the goldmine board fills these in — a plain local search prices nothing, so it passes
  // withProfit false and the chip stays the count it always was.
  //
  // "12 priced" beside "48 results" is the sentence that stops a seller unticking the site that was
  // paying: the gap is the analysis cap, not the site, and saying "more were found than could be
  // priced" is the difference between a limit and a failure.
  function sourceYieldHtml(s) {
    const bits = [];
    // Said only when it differs from the count beside it. "6 results · 6 priced" is the same fact
    // twice, and a number that appears whether or not it means anything stops being read at all —
    // which is exactly the number that has to be noticed on the site that WAS cut short.
    if (s.analyzed && s.analyzed !== s.count) bits.push(`only ${s.analyzed} priced`);
    // Zero profitable is worth saying out loud. A chip that goes quiet when a site earns nothing
    // reads as though the site was never in the ranking at all.
    bits.push(s.profitableCount
      ? `<strong class="local-chip-money">${s.profitableCount} worth buying · ${money(s.potentialProfit)}</strong>`
      : s.ranked ? 'none worth buying' : '');
    return bits.filter(Boolean).join(' · ');
  }

  function renderSourceOutcomes(sources, options = {}) {
    const el = $('local-source-status');
    if (!el) return;
    if (!sources || !sources.length) { el.innerHTML = ''; return; }

    const withProfit = options.withProfit === true;

    el.innerHTML = sources.map(s => {
      const ok = s.status === 'ok';
      const yield_ = withProfit && ok ? sourceYieldHtml(s) : '';
      const detail = ok && s.count
        ? `${s.count} result${s.count === 1 ? '' : 's'}${s.scopeLabel ? ` · ${esc(s.scopeLabel)}` : ''}` +
          (yield_ ? ` · ${yield_}` : '')
        : ok ? 'no results'
        : s.status === 'not_connected' ? 'connect required'
        : s.status === 'session_expired' ? 'session expired'
        // "not searched" rather than "blocked": this site did nothing wrong and a red chip reading
        // as a site failure sends the seller off to check a connection that was never the problem.
        : s.status === 'skipped' ? 'not searched — out of time'
        : s.retryable ? 'blocked — retry'
        : 'unavailable';
      // Connect is offered only for the source whose connect flow this page actually has. A future
      // session-based source gets its own button here, not Facebook's. The word changes with the
      // state: someone whose session just expired has connected before, and "Connect" reads to them
      // as the app having forgotten it rather than as the one thing left to do.
      const connectLabel = s.status === 'session_expired' ? 'Reconnect' : 'Connect';
      const action = (s.status === 'not_connected' || s.status === 'session_expired') && s.id === 'facebook'
        ? `<button type="button" class="btn btn-secondary small local-chip-btn local-chip-connect">${connectLabel}</button>`
        : (!ok && s.retryable)
        ? '<button type="button" class="btn btn-secondary small local-chip-btn local-chip-retry">Retry</button>'
        : '';
      const link = s.searchUrl
        ? ` <a class="link-ext" href="${esc(s.searchUrl)}" target="_blank" rel="noopener">open ↗</a>` : '';
      return `<span class="local-source-chip${ok ? '' : ' local-source-chip-off'}">
                <strong>${esc(s.label)}</strong> ${detail}${link} ${action}
                ${s.error ? `<span class="local-source-chip-err">${esc(s.error)}</span>` : ''}
              </span>`;
    }).join('');

    el.querySelectorAll('.local-chip-connect').forEach(b => b.addEventListener('click', facebookConnect));
    el.querySelectorAll('.local-chip-retry').forEach(b =>
      b.addEventListener('click', () => lastLocalRun && lastLocalRun()));
  }

  function renderLocalResults(data) {
    const results = $('fb-results');
    const list = $('fb-list');
    const summary = $('fb-summary');
    if (!list || !results) return;

    renderSourceOutcomes(data.sources);
    if (handleLocalNonResult(data)) return;
    const scope = scopeTextFor((data.sources || []).map(s => s.id), data.radiusMiles, data.zipCode);

    if (!data.count) {
      setLocalStatus(data.error
        ? `Nothing found — ${data.error}`
        : `Nothing found for "${data.query}" ${scope}.`,
        (data.sources || []).some(s => s.retryable));
      return;
    }

    // Blank unless part of the search is missing, in which case the count above it needs the
    // caveat more than the panel needs a clean status line.
    // A partial board offers the re-run here as well as on the chip. The sentence is what the
    // seller reads; making them find the matching chip to act on it is a step for nothing.
    setLocalStatus(partialLocalNote(data.sources), (data.sources || []).some(s => s.status !== 'ok' && s.retryable));
    // Radius is echoed from the response, not the form: Facebook snaps it to one of its own
    // dropdown values, so this reports what was actually searched. Per-site links live in the
    // source chips above, since each site has its own results URL.
    summary.innerHTML =
      `<strong>${data.count}</strong> listing${data.count === 1 ? '' : 's'} for "${esc(data.query)}" ` +
      `${esc(scope)} · ` +
      `asking ${money(data.min)}–${money(data.max)} · median ${money(data.median)}`;

    list.innerHTML = data.items.map(item => {
      const drop = item.originalPrice
        ? `<span class="fb-drop">was ${money(item.originalPrice)}</span>` : '';
      const meta = [
        item.location ? esc(item.location) : '',
        item.distanceMiles != null ? `${item.distanceMiles} mi away` : '',
        item.postedAgo ? esc(item.postedAgo) : '',
        // Year, make, model and the odometer, where the listing said them — the facts a vehicle ad
        // buries in the middle of its own title. See VehicleTitleParser.
        item.vehicle?.label ? `<span class="veh-chip">${esc(item.vehicle.label)}</span>` : '',
        item.vehicle?.wearText ? `<span class="veh-wear">${esc(item.vehicle.wearText)}</span>` : '',
      ].filter(Boolean).join(' · ');
      return `
        <div class="fb-card" data-title="${esc(item.title)}" data-price="${item.price ?? 0}">
          ${item.imageUrl ? `<img class="fb-card-img" src="${esc(item.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" />` : '<div class="fb-card-img fb-card-img-empty">📦</div>'}
          <div class="fb-card-body">
            <div class="fb-card-price">${item.isFree ? 'Free' : money(item.price)} ${drop}
              <span class="local-badge local-badge-${esc(item.source)}">${esc(item.sourceLabel || item.source)}</span>
            </div>
            <div class="fb-card-title">${esc(item.title)}</div>
            <div class="fb-card-meta">${meta}</div>
            <div class="fb-card-actions">
              <a class="btn btn-ghost small" href="${esc(item.url)}" target="_blank" rel="noopener">View listing ↗</a>
              <button class="btn btn-secondary small fb-comp-btn" type="button">Check eBay sold price</button>
            </div>
            <div class="fb-card-comp"></div>
          </div>
        </div>`;
    }).join('');

    // Sold-comp lookups are per-card and on demand — one click, one lookup. Checking every
    // result automatically would fire a scrape per tile off a single search.
    list.querySelectorAll('.fb-comp-btn').forEach(btn =>
      btn.addEventListener('click', () => facebookCheckComp(btn)));

    results.classList.remove('hidden');
  }

  // Prices the local ask against real eBay sold data using the existing /api/sold-comps
  // pipeline (Terapeak session first, then Marketplace Insights) — the whole point of a
  // local sourcing search is the spread between the two.
  async function facebookCheckComp(btn) {
    const card = btn.closest('.fb-card');
    const out = card?.querySelector('.fb-card-comp');
    const title = card?.dataset.title || '';
    if (!out || !title) return;

    btn.disabled = true;
    out.textContent = 'Checking eBay sold prices…';
    try {
      const data = await fetch(`/api/sold-comps?q=${encodeURIComponent(title)}`).then(r => r.json());
      const avg = data.average || data.median || 0;
      if (!avg) {
        out.innerHTML = `<span class="fb-comp-none">No sold comps found for this title. <a class="link-ext" href="${esc(data.fallbackUrl || '#')}" target="_blank" rel="noopener">Search eBay ↗</a></span>`;
        return;
      }
      // The numeric price off the card, not the rendered text — a price-drop card shows two
      // prices ("$450 was $700") and scraping the digits back out of that reads as $450,700.
      const localAsk = parseFloat(card.dataset.price) || 0;
      const spread = avg - localAsk;
      // Gross spread only — this is sold price minus local ask, before eBay fees and
      // shipping. The listing editor's profit panel is where the net number lives.
      const verdict = localAsk > 0
        ? `<span class="${spread > 0 ? 'fb-comp-good' : 'fb-comp-bad'}">${spread > 0 ? '+' : ''}${money(spread)} vs local ask (before fees &amp; shipping)</span>`
        : '';
      out.innerHTML = `<span class="fb-comp-val">eBay sold avg ${money(avg)}${data.count ? ` from ${data.count} comps` : ''}</span> ${verdict}`;
    } catch (err) {
      out.textContent = `Couldn't check sold prices: ${errorText(err)}`;
    } finally {
      btn.disabled = false;
    }
  }

  // ── Local arbitrage ranking ──────────────────────────────────────────────
  // The whole local-sourcing feature in one table: every local listing priced against real
  // eBay sold comps, ranked by what's left after fees. Held here so the sort/filter controls
  // re-render from the same response instead of re-running a multi-minute scan.
  let arbitrageData = null;

  const ARB_VERDICTS = {
    goldmine: { label: '💎 Goldmine', cls: 'goldmine' },
    solid:    { label: '✅ Worth it', cls: 'solid' },
    thin:     { label: '⚠️ Thin', cls: 'thin' },
    pass:     { label: '✕ Pass', cls: 'pass' },
    no_data:  { label: '? No data', cls: 'nodata' },
  };

  // Which sold-comps database answered. Named on every row rather than left to "eBay data":
  // a seller deciding whether to drive somewhere is entitled to know where the price came from.
  const ARB_SOURCES = {
    hosted_comps: 'sold-comps DB',
  };

  // How long the money stays spent, in one cell. Server-side tiers (DaysToCashEstimator) so the
  // colour on the row and the sentence in the tooltip can't disagree.
  const SPEED_TIERS = {
    fast:       { cls: 'fast',  short: 'fast' },
    steady:     { cls: 'steady', short: 'steady' },
    slow:       { cls: 'slow',  short: 'slow' },
    dead_money: { cls: 'dead',  short: 'parked' },
    unknown:    { cls: 'unknown', short: '' },
  };

  // The buy side, on the row. Server-side verdicts (NegotiationAdvisor) so the badge, the number
  // and the drafted message can never tell three different stories.
  const NEG_VERDICTS = {
    buy_now:        { label: 'Take it', cls: 'buynow', hint: 'Already under your great-buy price — ask once, take it either way.' },
    negotiate:      { label: 'Haggle', cls: 'haggle', hint: 'Profitable at their ask. Everything you talk off is free money.' },
    must_negotiate: { label: 'Only at your price', cls: 'must', hint: 'Not worth their ask — this one only works if they come down.' },
    long_shot:      { label: 'Long shot', cls: 'longshot', hint: 'A polite offer barely clears the fees. One message, then let it go.' },
    walk:           { label: 'Walk', cls: 'walk', hint: 'No offer here both makes money and gets answered.' },
    no_data:        { label: '—', cls: 'nodata', hint: 'No sold history to negotiate against.' },
  };

  const NEG_TONES = {
    great: { cls: 'great', label: 'great buy' },
    good:  { cls: 'good',  label: 'worth doing' },
    thin:  { cls: 'thin',  label: 'thin' },
    loss:  { cls: 'loss',  label: 'you lose money' },
  };

  // "$1.85/day" — the profit spread over the wait. Sub-dollar rates keep their cents, because
  // that is exactly the range where two flips are being compared.
  function perDay(value) {
    if (value == null) return '';
    const abs = Math.abs(value);
    return `${value < 0 ? '-' : ''}$${abs < 10 ? abs.toFixed(2) : Math.round(abs).toLocaleString()}/day`;
  }

  // The days-to-cash cell shared by both boards: the wait, then what it earns per day of waiting.
  function daysToCashCell(row) {
    const tier = SPEED_TIERS[row.speedTier] || SPEED_TIERS.unknown;
    if (row.daysToCash == null) {
      return '<span class="fb-arb-muted" title="No dated sold history for this product, so there is no honest estimate of how long the money stays tied up.">—</span>';
    }
    const rate = row.profitPerDay != null && row.profitPerDay > 0
      ? `<span class="speed-rate">${perDay(row.profitPerDay)}</span>` : '';
    return `<span class="speed-days speed-${tier.cls}" title="${esc(row.speedNote || '')}">${row.daysToCash}d</span>${rate}`;
  }

  // ── Update banner ─────────────────────────────────────────────────────────
  /**
   * Tells the seller a newer version exists, once, quietly, at the top of the dashboard.
   *
   * Never blocks anything and never reports its own failure: the endpoint answers "no update" for
   * every problem it hits, so this either shows a banner or does nothing at all. A listing tool that
   * interrupted someone to complain it could not reach GitHub would be worse than one that never
   * checked.
   */
  async function checkForUpdate() {
    const el = $('update-banner');
    if (!el) return;

    try {
      const res = await fetch('/api/update/check');
      if (!res.ok) return;
      const u = await res.json();
      if (!u.updateAvailable || !u.latest) return;

      // Dismissal is per version: "not now" on 2.3.0 must not hide 2.4.0 six weeks later.
      if (localStorage.getItem('updateDismissed') === u.latest) return;

      el.innerHTML =
        `<strong>Version ${esc(u.latest)} is out.</strong> ` +
        `You're running ${esc(u.current)}. ` +
        `<a href="${esc(u.downloadUrl)}" target="_blank" rel="noopener noreferrer">Get the update</a>` +
        `<button type="button" id="update-dismiss" class="btn btn-ghost small">Not now</button>`;
      el.classList.remove('hidden');

      on('update-dismiss', 'click', () => {
        localStorage.setItem('updateDismissed', u.latest);
        el.classList.add('hidden');
      });
    } catch {
      // Offline, or the app is mid-restart. Neither is worth a word on screen.
    }
  }

  // ── Today's picks: Marketplace's own front page ───────────────────────────
  // The one place on this screen that shows real local supply without being asked a question
  // first. Click-loaded, never polled — same rule as every other Facebook read here.
  let fbPicksLoaded = false;
  let fbPicksOptionsLoaded = false;

  // Facebook's own filter lists, fetched rather than hard-coded — an option Marketplace adds is
  // then a server edit, not a second list in the browser to forget about.
  async function loadFacebookBrowseOptions() {
    if (fbPicksOptionsLoaded) return;
    const { data } = await localFetchJson('/api/facebook/browse-options', 20000);
    if (!data) return;
    fbPicksOptionsLoaded = true;

    const fill = (id, options, selected) => {
      const el = $(id);
      if (!el) return;
      el.innerHTML = options.map(o =>
        `<option value="${esc(o.value)}"${o.value === selected ? ' selected' : ''}>${esc(o.label)}</option>`).join('');
    };
    fill('fb-picks-category', data.categories, '');
    fill('fb-picks-sort', data.sorts, '');
    fill('fb-picks-condition', data.conditions, '');
    fill('fb-picks-date', data.dates, '');
    fill('fb-picks-delivery', data.delivery, '');

    const radius = $('fb-picks-radius');
    if (radius) {
      radius.innerHTML = (data.radii || []).map(m =>
        `<option value="${m}"${m === 40 ? ' selected' : ''}>${m} miles</option>`).join('');
    }
  }

  function facebookBrowseQuery() {
    const val = id => ($(id)?.value || '').trim();
    const num = id => {
      const v = parseFloat($(id)?.value);
      return isFinite(v) && v > 0 ? v : null;
    };
    const min = num('fb-picks-min');
    const max = num('fb-picks-max');
    const parts = [];
    const add = (k, v) => { if (v !== '' && v !== null && v !== undefined) parts.push(`${k}=${encodeURIComponent(v)}`); };
    add('q', val('fb-picks-query'));
    add('category', val('fb-picks-category'));
    add('condition', val('fb-picks-condition'));
    add('daysListed', val('fb-picks-date'));
    add('delivery', val('fb-picks-delivery'));
    add('sortBy', val('fb-picks-sort'));
    add('radius', val('fb-picks-radius'));
    add('minPrice', min);
    add('maxPrice', max);
    return { qs: parts.join('&'), min, max };
  }

  async function loadFacebookPicks(force) {
    const grid = $('fb-picks-grid');
    const btn = $('fb-picks-btn');
    const status = $('fb-picks-status');
    if (!grid) return;
    if (fbPicksLoaded && !force) return;

    await loadFacebookBrowseOptions();

    if (btn) { btn.disabled = true; btn.textContent = 'Loading…'; }
    if (status) status.textContent = 'Opening your Marketplace feed — this drives a real page load, so it takes about half a minute…';
    // These cards arrive in Facebook's order and stay in it until the prices land, so the sort
    // line has to go away for as long as it isn't true.
    const order = $('fb-picks-order');
    if (order) order.hidden = true;
    // Placeholder tiles rather than an empty strip: this call takes ~30s, and a panel that shows
    // nothing at all for that long reads as broken rather than as busy.
    grid.innerHTML = Array.from({ length: 12 },
      () => '<div class="fb-pick-card fb-pick-skeleton"><div class="fb-pick-img fb-pick-img-empty"></div></div>').join('');

    const { qs, min, max } = facebookBrowseQuery();
    if (min !== null && max !== null && min > max) {
      if (btn) { btn.disabled = false; btn.textContent = 'Refresh'; }
      grid.innerHTML = '';
      if (status) status.textContent = 'The minimum price is above the maximum — swap them and search again.';
      return;
    }

    // One endpoint for both: with no filters set this IS the picks feed, which is what makes the
    // blank search meaningful here rather than an error.
    const { data, error } = await localFetchJson(`/api/facebook/browse?${qs}`, 150000);

    if (btn) { btn.disabled = false; btn.textContent = 'Refresh'; }

    if (!data) {
      if (status) status.textContent = `Couldn't load your Marketplace picks. ${error || ''}`.trim();
      grid.innerHTML = '';
      return;
    }
    if (data.status === 'not_connected' || data.status === 'session_expired') {
      if (status) status.textContent = data.error || 'Connect Facebook to see your Marketplace picks.';
      grid.innerHTML = '';
      return;
    }
    if (data.status !== 'ok' || !(data.items || []).length) {
      if (status) status.textContent = data.error || 'Facebook returned no picks just now — try Refresh in a minute.';
      grid.innerHTML = '';
      return;
    }

    fbPicksLoaded = true;
    if (status) status.textContent = '';
    const sub = $('fb-picks-sub');
    if (sub) sub.textContent = `${data.items.length} listings — ${data.scopeLabel || 'your Marketplace feed'}. Click one to open it on Marketplace.`;

    grid.innerHTML = data.items.map(item => `
      <a class="fb-pick-card" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer" title="${esc(item.title)}">
        ${item.imageUrl
          ? `<img class="fb-pick-img" src="${esc(item.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" />`
          : '<div class="fb-pick-img fb-pick-img-empty">📦</div>'}
        <span class="fb-pick-price">${item.isFree ? 'Free' : (item.price != null ? money(item.price) : esc(item.priceText || ''))}</span>
        <span class="fb-pick-title">${esc(item.title)}</span>
        <span class="fb-pick-loc">${esc(item.location || '')}</span>
        <span class="fb-pick-money" data-pick-money="${esc(item.itemId || '')}"></span>
      </a>`).join('');

    priceFacebookPicks(data);
  }

  /**
   * Fills each pick card with the numbers that decide whether it is a buy: what it sells for on
   * eBay, how many sold comps that is based on, the profit after fees, and the ROI.
   *
   * The grid renders first and unpriced, because the browse is already a ~30 second page load and a
   * seller staring at a blank panel for a minute assumes it is broken. The prices arrive after,
   * into cards that are already on screen and already clickable.
   */
  async function priceFacebookPicks(feed) {
    const note = $('fb-picks-status');
    if (note) note.textContent = 'Pricing these against real eBay sold data…';

    const { data } = await localFetchJson('/api/local/price-these?maxItems=40&terapeakBudget=0', 180000, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(feed)
    });

    if (!data || !(data.items || []).length) {
      if (note) note.textContent = '';
      return;
    }

    let priced = 0;
    for (const row of data.items) {
      const slot = document.querySelector(`[data-pick-money="${CSS.escape(row.itemId || '')}"]`);
      if (!slot) continue;

      const profit = row.netProfit;
      const roi = row.roiPercent;
      const comp = row.ebayExpectedSale ?? row.ebayResaleMedian;
      const comps = row.soldCompCount || 0;

      // No comps means no opinion. Saying "$0 profit" would be a claim; saying "no sold data" is
      // the truth, and the seller can still open the listing and judge it themselves.
      if (comp == null || !comps) {
        slot.innerHTML = '<span class="fb-pick-nodata">no sold data</span>';
        continue;
      }

      const good = profit != null && profit > 0;
      slot.innerHTML =
        `<span class="fb-pick-profit ${good ? 'is-good' : 'is-bad'}">` +
          `${good ? '+' : ''}${money(profit)}${roi != null ? ` · ${Math.round(roi)}%` : ''}</span>` +
        `<span class="fb-pick-comp">sells ~${money(comp)} · ${comps} sold</span>`;
      priced++;
    }

    // The numbers are on the cards; now put the best one first. Only worth doing — and only
    // honest to announce — if something could actually be ranked.
    if (priced) reorderFacebookPicks(data.items);

    if (note) {
      note.textContent = priced
        ? `${priced} of ${feed.items.length} priced against real eBay sold data. Profit is after fees and shipping.`
        : 'None of these could be priced — no matching eBay sold history.';
    }
  }

  /**
   * How two priced picks rank against each other. Pure — no DOM, no fetch — so the rule can be
   * tested on its own rather than only by looking at a grid.
   *
   * Highest ROI first, because that is the question the seller is asking: of the things for sale
   * near me today, which one returns the most on what I put in. A card with no matching sold
   * history is not a bad deal, it is *no opinion* — so it sinks below every ranked card instead
   * of being scored as a zero, and it stays on the grid.
   */
  function compareFacebookPicks(a, b) {
    const rank = row => {
      const comps = (row && row.soldCompCount) || 0;
      const sale = row && (row.ebayExpectedSale ?? row.ebayResaleMedian);
      // The same test the card itself uses to decide between numbers and "no sold data", so the
      // cards that read as unranked are exactly the cards that sort as unranked.
      const ranked = sale != null && comps > 0;
      const num = v => (ranked && typeof v === 'number' && isFinite(v) ? v : null);
      return { ranked, roi: num(row && row.roiPercent), profit: num(row && row.netProfit) };
    };

    const ra = rank(a), rb = rank(b);

    if (ra.ranked !== rb.ranked) return ra.ranked ? -1 : 1;
    if (!ra.ranked) return 0;

    // ROI descending, which puts every losing deal below every winning one for free. A priced
    // card that has no ROI figure at all ranks under every card that has one.
    if (ra.roi !== rb.roi) {
      if (ra.roi == null) return 1;
      if (rb.roi == null) return -1;
      return rb.roi - ra.roi;
    }

    // Same ROI (or neither has one): the bigger dollar profit is the better of the two.
    const pa = ra.profit ?? -Infinity, pb = rb.profit ?? -Infinity;
    return pa === pb ? 0 : pb - pa;
  }

  /**
   * Re-orders the cards already on screen into best-return-first.
   *
   * Moving the existing nodes rather than re-rendering the grid is deliberate: the markup is
   * unchanged, so every thumbnail that has finished loading stays loaded and the panel never
   * blanks a second time after the seller has already waited half a minute for it.
   */
  function reorderFacebookPicks(pricedRows) {
    const grid = $('fb-picks-grid');
    if (!grid) return;

    const byId = new Map();
    for (const row of pricedRows) if (row && row.itemId) byId.set(String(row.itemId), row);

    const cards = Array.from(grid.querySelectorAll('.fb-pick-card'));
    if (cards.length < 2) return;

    const ordered = cards.map((card, index) => ({
      card, index,
      row: byId.get(card.querySelector('[data-pick-money]')?.getAttribute('data-pick-money') || '') || null
    }));

    // Facebook's own order is the tiebreak, so equally-good picks don't shuffle on every refresh.
    ordered.sort((x, y) => compareFacebookPicks(x.row, y.row) || x.index - y.index);

    const frag = document.createDocumentFragment();
    for (const entry of ordered) frag.appendChild(entry.card);
    grid.appendChild(frag);

    // A grid that silently rearranges itself looks arbitrary unless it says what it sorted by.
    const order = $('fb-picks-order');
    if (order) order.hidden = false;
  }

  // ── eBay scanner (its own panel, above the local one) ─────────────────────
  // Buying and selling on the same site is a one-field search: no zip, no radius, no login. It
  // runs the SAME scan engine as the panel below, restricted to the eBay source, and renders into
  // the same results table — one scanner, two front doors. Nothing here duplicates renderArbitrage.
  const EBAY_SOURCE_ID = 'ebay';

  // A seller's buying rules don't change between sessions — someone who only buys used under $500
  // is still doing that tomorrow. Restored rather than re-typed.
  function restoreEbayScanFilters() {
    let saved;
    try { saved = JSON.parse(localStorage.getItem('ebayScanFilters') || 'null'); } catch (_) { return; }
    if (!saved) return;
    const set = (id, value) => { if (value !== null && value !== undefined && value !== '' && $(id)) $(id).value = value; };
    set('ebay-scan-type', saved.type);
    set('ebay-scan-condition', saved.condition);
    set('ebay-scan-min', saved.min);
    set('ebay-scan-max', saved.max);
    set('ebay-scan-feedback', saved.feedback);
  }

  async function runEbayScan() {
    const query = $('ebay-scan-query')?.value.trim() || '';
    const btn   = $('ebay-scan-btn');

    if (!query) return setLocalStatus('Type what you want to look for on eBay.');

    // Re-running is what the Try again button does, so it has to point at this scan and not at
    // whatever the panel below ran last.
    lastLocalRun = runEbayScan;

    $('fb-results')?.classList.add('hidden');
    $('fb-arb-results')?.classList.add('hidden');
    if (btn) btn.disabled = true;

    setLocalStatus(`Searching eBay for "${query}", then pricing every result against real sold data — this can take a minute…`);

    const sort = $('fb-arb-sort')?.value || 'roi';
    const num = id => {
      const v = parseFloat($(id)?.value);
      return isFinite(v) && v > 0 ? v : null;
    };
    const min = num('ebay-scan-min');
    const max = num('ebay-scan-max');
    const feedback = num('ebay-scan-feedback');
    const type = $('ebay-scan-type')?.value || 'BOTH';
    const condition = $('ebay-scan-condition')?.value || '';

    // Caught here rather than at eBay, which would answer a reversed band with an empty result
    // that looks exactly like "nothing is listed".
    if (min !== null && max !== null && min > max)
      return setLocalStatus('The minimum price is above the maximum — swap them and scan again.');

    // The eBay scanner has its own route: condition and auction/Buy-It-Now mean nothing to a
    // classifieds feed, so they are not parameters on the shared multi-source scan.
    const qs = `q=${encodeURIComponent(query)}` +
      `&listingType=${encodeURIComponent(type)}` +
      (condition ? `&condition=${encodeURIComponent(condition)}` : '') +
      (min !== null ? `&minPrice=${encodeURIComponent(min)}` : '') +
      (max !== null ? `&maxPrice=${encodeURIComponent(max)}` : '') +
      (feedback !== null ? `&minFeedback=${encodeURIComponent(feedback)}` : '') +
      `&category=${encodeURIComponent(selectedCategoryId())}` +
      `&sort=${encodeURIComponent(sort)}`;

    // Remembered between scans: a seller who only buys used under $500 is still doing that
    // tomorrow, and retyping it every time is the kind of friction that stops it being used.
    localStorage.setItem('ebayScanFilters', JSON.stringify({ type, condition, min, max, feedback }));

    // Put the results under the box that was searched, BEFORE the request goes out, so even the
    // "searching..." line appears where the seller is looking rather than at the foot of the other
    // card. One block, moved — not a second copy to keep in sync.
    moveScanResultsTo('ebay-results-slot');

    const { data, error } = await localFetchJson(`/api/ebay/scan?${qs}`, LOCAL_ARBITRAGE_TIMEOUT_MS);
    if (btn) btn.disabled = false;

    if (!data) {
      setLocalStatus(`The eBay scan didn't complete. ${error}`, true);
      return;
    }

    // Say so when the spelling was corrected, and leave a way back. eBay answers a typo with zero
    // results and no hint, so without this the seller reads a slip of the keyboard as "nothing out
    // there" — and a silent correction is its own problem: results for a search nobody typed.
    if (data.correctedTo && data.correctedFrom) {
      // The corrected search found things worth buying, so that is what is on screen.
      const input = $('ebay-scan-query');
      if (input) input.value = data.correctedTo;
      setLocalStatus(
        `Showing results for "${data.correctedTo}" — "${data.correctedFrom}" found nothing. ` +
        `Put the original back in the box to search it as typed.`);
    } else if (data.correctedTo) {
      // Nothing was swapped: a suggestion only, offered rather than applied.
      setLocalStatus(`No priced results. Did you mean "${data.correctedTo}"? Click to try it.`);
      const box = $('fb-status');
      if (box) {
        box.style.cursor = 'pointer';
        box.onclick = () => {
          const input = $('ebay-scan-query');
          if (input) { input.value = data.correctedTo; runEbayScan(); }
        };
      }
    }

    renderArbitrage(data);
  }

  /**
   * Moves the one shared results block (status line, plain results, arbitrage table) under whichever
   * scanner was actually used.
   *
   * The eBay Scanner and the local board share a single rendering path — the same table, the same
   * summary, the same status line — and that block used to sit permanently under the local panel.
   * So searching eBay from the box at the top printed "Searching eBay for ..." and then the whole
   * results table at the bottom of the Local &amp; online deals card, a different box entirely. The
   * seller asked in one place and was answered in another.
   *
   * Moving the existing nodes rather than duplicating them keeps one render path: a second copy
   * would drift, and every fix would have to be made twice.
   */
  function moveScanResultsTo(slotId) {
    let block = $('scan-results-block');

    if (!block) {
      const first = $('fb-status');
      if (!first || !first.parentNode) return;
      block = document.createElement('div');
      block.id = 'scan-results-block';
      first.parentNode.insertBefore(block, first);
      // Order matters: this is the order they render down the page.
      ['fb-status', 'local-source-status', 'fb-results', 'fb-arb-results']
        .map($).filter(Boolean).forEach(el => block.appendChild(el));
    }

    const slot = $(slotId);
    if (slot && block.parentNode !== slot) slot.appendChild(block);
  }

  async function runLocalArbitrage() {
    const { query, zip, radius, sources, category, qs } = localSearchParams();
    // Local search answers under the local box, for the same reason.
    moveScanResultsTo('local-results-slot');
    const buttons = ['fb-search-btn', 'fb-arb-btn'].map($).filter(Boolean);

    lastLocalRun = runLocalArbitrage;

    // Blank is a real search on the freebie board (see allowsBlankQuery) and on any category board:
    // "price everything on the cars board near me" is the search this whole feature is for.
    if (!query && !sources.some(allowsBlankQuery) && !isBoardSearch(category, sources))
      return setLocalStatus('Enter what you want to look for, or pick a category to price its whole board.');
    if (!sources.length) return setLocalStatus('Tick at least one place to search.');

    $('fb-results')?.classList.add('hidden');
    $('fb-arb-results')?.classList.add('hidden');
    buttons.forEach(b => { b.disabled = true; });
    // Honest about the cost: every selected site is searched, then one sold-comp lookup per
    // distinct product, then up to five Terapeak lookups. Minutes, not seconds.
    setLocalStatus(`Searching ${sourceLabelsFor(sources)} ${scopeTextFor(sources, radius, zip)}, ` +
      'then pricing every result against eBay sold data — this can take a couple of minutes…');

    // The scan comes back already ordered the way the seller last chose to look at it. Changing
    // the sort afterwards is still purely client-side — it must never re-run a multi-minute scan.
    const sort = $('fb-arb-sort')?.value || 'roi';
    const { data, error } = await localFetchJson(
      `/api/local/arbitrage?${qs}&sort=${encodeURIComponent(sort)}`, LOCAL_ARBITRAGE_TIMEOUT_MS);
    buttons.forEach(b => { b.disabled = false; });

    if (!data) {
      setLocalStatus(`The local scan didn't complete. ${error}`, true);
      return;
    }
    renderArbitrage(data);
  }

  function renderArbitrage(data) {
    const wrap = $('fb-arb-results');
    if (!wrap) return;

    // With the money each site is responsible for, which the plain local search has no way to know.
    renderSourceOutcomes(data.sources, { withProfit: true });
    if (handleLocalNonResult(data)) return;
    // What the scan actually covered, from the sources that ran — not from the form, which may
    // have moved since.
    const scannedIds = (data.sources || []).map(s => s.id);
    const scope = scopeTextFor(scannedIds, data.radiusMiles, data.zipCode);

    if (!data.localListingsFound) {
      setLocalStatus(data.error
        ? `Nothing found — ${data.error}`
        : `Nothing found for "${data.query}" ${scope}.`,
        (data.sources || []).some(s => s.retryable));
      return;
    }
    if (!data.count) {
      // The sites answered and the listings are real — what's missing is the pricing half, and
      // dataWarning is where the server says why (no comps source, or a pricing pass that broke).
      setLocalStatus(`Found ${data.localListingsFound} listing(s), but none could be priced. ` +
        (data.dataWarning || data.error || 'None of them had a price to work from.'), true);
      return;
    }

    arbitrageData = data;
    // A partial board offers the re-run here as well as on the chip. The sentence is what the
    // seller reads; making them find the matching chip to act on it is a step for nothing.
    setLocalStatus(partialLocalNote(data.sources), (data.sources || []).some(s => s.status !== 'ok' && s.retryable));

    // Which sites are actually in this ranking — a mixed table has to say so, and a site that
    // returned nothing shouldn't be implied to have been searched fruitfully.
    const searched = (data.sources || []).filter(s => s.status === 'ok' && s.count)
      .map(s => `${esc(s.label)} (${s.count})`).join(' + ');

    const scanned = [
      `<strong>${data.count}</strong> deal${data.count === 1 ? '' : 's'} priced for "${esc(data.query)}"`,
      esc(scope),
      searched ? `from ${searched}` : '',
      data.goldmineCount ? `<strong class="fb-arb-hit">${data.goldmineCount} goldmine${data.goldmineCount === 1 ? '' : 's'}</strong>` : 'no goldmines this time',
      // Capital that comes back inside three weeks is capital that can buy the next one — worth its
      // own headline next to the total, which says nothing about when any of it arrives.
      data.fastCashCount ? `<strong class="fb-arb-hit">${data.fastCashCount} that ${data.fastCashCount === 1 ? 'pays' : 'pay'} back inside 3 weeks</strong>` : '',
      `${money(data.totalPotentialProfit)} total profit if you bought every profitable one`,
      // Which site to open first next weekend — the decision a sourcing seller repeats more often
      // than any other, and one no single row can answer. Only said when there is more than one
      // site in the ranking: "best site: Craigslist" with Craigslist the only site searched is a
      // sentence with no information in it.
      data.bestSourceLabel && (data.sources || []).filter(s => s.status === 'ok' && s.count).length > 1
        ? `most of it on <strong class="fb-arb-hit">${esc(data.bestSourceLabel)}</strong>`
        : '',
      // A site the cap cut short is a site with more on it, and that reads nothing like a site with
      // nothing on it. Named rather than counted: the fix is per site — search that one on its own.
      (() => {
        const capped = (data.sources || []).filter(s => s.status === 'ok' && s.capped);
        return capped.length
          ? `more found on ${capped.map(s => esc(s.label)).join(' + ')} than this scan could price — ` +
            'search that site on its own to reach the rest'
          : '';
      })(),
      // The buy side, said plainly: this is the money that costs nothing to earn. Framed as a
      // ceiling, because nobody accepts every opening offer.
      data.negotiationUpside > 0
        ? `<strong class="fb-arb-hit">${money(data.negotiationUpside)} more</strong> if all ${data.negotiableCount} sellers took your opening offer`
        : '',
      // A closeout row expires. A profitable one read on Thursday for an auction that ended
      // Wednesday is a deal the seller never had, so the deadline gets its own headline.
      data.closingSoonCount
        ? `<strong class="fb-arb-hit">${data.closingSoonCount} profitable auction${data.closingSoonCount === 1 ? '' : 's'} closing inside 48h</strong>`
        : '',
      // The money that costs nothing to make. Its own headline because it is the only figure on
      // this board with nothing to lose behind it — no cost basis, so a row that doesn't sell costs
      // an afternoon rather than money.
      data.freeMoneyOnTheTable > 0
        ? `<strong class="fb-arb-hit">${money(data.freeMoneyOnTheTable)} from ${data.freebieCount} free item${data.freebieCount === 1 ? '' : 's'}</strong> — nothing spent`
        : (data.freebieCount ? `${data.freebieCount} free item${data.freebieCount === 1 ? '' : 's'} found, none worth the trip` : ''),
      // And the half of that which is gone by tomorrow.
      data.expiringTodayCount
        ? `<strong class="fb-arb-hit">${data.expiringTodayCount} of them gone today</strong> — free posts get claimed the same day`
        : '',
      // The buy side of the retail rows. Framed as conditional on purpose: a public promo code is
      // a claim, and this money is only real if the code is.
      data.couponSavingsOnTheTable > 0
        ? `<strong class="fb-arb-hit">${money(data.couponSavingsOnTheTable)} more</strong> if the codes work on ${data.couponedCount} of them`
        : '',
      data.couponRescuedCount
        ? `<strong class="fb-arb-hit">${data.couponRescuedCount} only ${data.couponRescuedCount === 1 ? 'works' : 'work'} with a code</strong>`
        : '',
      // The covered half of the board. Its own headline because it is not a better price — it is the
      // same flip with the downside cut off, and a seller who can't absorb one bad buy shops this
      // column before the profit ranking.
      data.warrantyCount
        ? `<strong class="fb-arb-hit">${data.warrantyCount} still under warranty</strong>` +
          (data.warrantyUpliftOnTheTable > 0
            ? ` — ${money(data.warrantyUpliftOnTheTable)} of the profit above is what that cover is worth on resale`
            : '')
        : '',
      // And the rows that say the opposite, where the price makes it matter.
      data.asIsRiskCount
        ? `<strong class="fb-arb-hit">${data.asIsRiskCount} sold as-is with no returns</strong> — test before you pay`
        : '',
      // The rows the app refused to value. Said in the headline rather than left to be discovered a
      // row at a time: on a scan of the cars board this is most of the board, and it is a limit of
      // the data rather than of the deals.
      data.manualValuationCount
        ? `${data.manualValuationCount} could not be valued from sold data — priced by hand, with a search link on each`
        : '',
      // The junk that was kept off the board. Said out loud because these listings carry the real
      // part number and would otherwise have ranked first: a $1 "repair evaluation" priced against
      // the $899 board it services is a five-figure ROI that cannot be bought.
      data.notTheItemCount
        ? `${data.notTheItemCount} hidden — repair services, manuals and core charges, not the item itself`
        : '',
    ].filter(Boolean).join(' · ');
    // How many of the priced rows are guesses. Said in the summary as well as on the rows, because
    // a board where most of the percentages are estimates is a different board from one where two
    // of them are — and that is not visible from any single row.
    const estimates = (data.items || []).filter(r => r.evidenceTier === 'low' && r.netProfit != null).length;

    $('fb-arb-summary').innerHTML =
      scanned +
      `<div class="fb-arb-sources">Priced ${data.productsPriced} distinct product${data.productsPriced === 1 ? '' : 's'} against sold comps` +
      `.` +
      `${estimates ? ` <strong class="fb-arb-estimate-flag">${estimates} row${estimates === 1 ? ' is an estimate' : 's are estimates'}</strong>` +
        ` — too few matching sold comps to trust, so the ROI and margin on ${estimates === 1 ? 'it' : 'them'} are dimmed rather than shown as real rates.` : ''}</div>`;

    const warn = $('fb-arb-warning');
    if (warn) {
      warn.textContent = data.dataWarning || '';
      warn.classList.toggle('hidden', !data.dataWarning);
    }

    renderCouponStores(data.couponStores);
    renderArbitrageCategoryFilter(data.categories);
    renderArbitrageRows();
    wrap.classList.remove('hidden');
  }

  // The category filter above the table, built from the scan's own tallies so an option that
  // matches nothing can never appear. A scan for "anything" routinely returns six kinds of thing in
  // one ranking, and until it says so the seller has to read every row to find the truck.
  function renderArbitrageCategoryFilter(categories) {
    const sel = $('fb-arb-category');
    if (!sel) return;

    const list = (categories || []).filter(c => c.count > 0);
    // One category is not a choice — hide the control rather than offer a filter that does nothing.
    sel.classList.toggle('hidden', list.length < 2);
    if (list.length < 2) { sel.value = ''; return; }

    const previous = sel.value;
    sel.innerHTML = '<option value="">All categories</option>' + list.map(c =>
      // The priced count is the useful half: "Cars & trucks (14, 2 priced)" says at a glance that
      // this app could put a number on two of them and the rest need a look by hand.
      `<option value="${esc(c.id)}">${esc(c.label)} (${c.count}${c.pricedCount < c.count ? `, ${c.pricedCount} priced` : ''})</option>`
    ).join('');
    if (list.some(c => c.id === previous)) sel.value = previous;
  }

  // Re-sorting and filtering are pure client-side views over the response already in hand —
  // changing the sort must never re-run the scan.
  // The least net profit that makes a flip worth the work at all - LocalArbitrageAnalyzer.SolidProfit.
  // Spelled here too because the board filters on it before the server's verdict is ever read.
  const WORTH_DOING_NET = 100;

  // Why the board is empty, counted rather than guessed. Naming the bar that cut is the difference
  // between "this tool is broken" and "there was nothing here worth buying" - and the second one is
  // the answer that saves the seller money.
  function emptyUnderTheBarMessage() {
    const all = (arbitrageData && arbitrageData.items) || [];
    const priced = all.filter(r => r.netProfit != null);
    const clearsBar = priced.filter(r => r.netProfit >= WORTH_DOING_NET);
    const proven = clearsBar.filter(r => r.evidenceTier === 'confident');

    if (!clearsBar.length) {
      return `${all.length} deal${all.length === 1 ? '' : 's'} priced, and not one nets $${WORTH_DOING_NET} `
           + `after fees. That is the answer: there is nothing here worth the drive, the listing and the packing. `
           + `Untick "Only deals that clear $${WORTH_DOING_NET}" to see the small stuff anyway.`;
    }
    return `${clearsBar.length} deal${clearsBar.length === 1 ? '' : 's'} clear $${WORTH_DOING_NET}, but `
         + `${proven.length === 0 ? 'none of them are' : 'only ' + proven.length + ' of them are'} `
         + `priced off sold comps that actually match the item - the rest rest on one loose comp or on `
         + `another product's price. Untick "Only prices backed by real sold comps" to see them, knowing `
         + `the resale figures on those rows are guesses.`;
  }

  function renderArbitrageRows() {
    const body = $('fb-arb-body');
    if (!body || !arbitrageData) return;

    const sort = $('fb-arb-sort')?.value || 'roi';
    const hideLosers = !!$('fb-arb-hide-losers')?.checked;
    const provenOnly = !!$('fb-arb-proven-only')?.checked;
    const fastOnly = !!$('fb-arb-fast-only')?.checked;
    const warrantyOnly = !!$('fb-arb-warranty-only')?.checked;
    const category = $('fb-arb-category')?.value || '';

    let rows = arbitrageData.items.slice();
    // What KIND of thing, applied first: it is the widest cut and the one the seller picked most
    // deliberately. Server-side ids, so the filter and the fee model can't disagree about what a
    // row is.
    if (category) rows = rows.filter(r => (r.categoryId || 'anything') === category);

    // Price band. Measured on paidFor() — the taxed, all-in cost — so "under $100" means under $100
    // out of pocket, not under $100 on a sticker that becomes $108 at the till. An open-ended top
    // band ("10000-") has no upper bound rather than a zero one.
    const band = $('fb-arb-price')?.value || '';
    if (band) {
      const [lo, hi] = band.split('-');
      const min = parseFloat(lo) || 0;
      const max = hi === '' || hi == null ? Infinity : parseFloat(hi);
      rows = rows.filter(r => { const paid = paidFor(r); return paid >= min && paid <= max; });
    }

    // The $100 bar, not a "> 0" bar. A row that nets $14 on a 280% return is not a deal: it does
    // not pay for finding it, listing it and packing it, and it pushes the rows that would down
    // the board. Same figure the server grades verdicts on (LocalArbitrageAnalyzer.SolidProfit),
    // so the filter and the badge cannot disagree about what "worth doing" means.
    if (hideLosers) rows = rows.filter(r => r.netProfit != null && r.netProfit >= WORTH_DOING_NET);
    // A price nobody could check is not a price. These rows kept arriving at the top of the board
    // with the biggest numbers on them precisely BECAUSE they were unchecked — one unusual sold
    // comp sets a resale figure no real sale supports.
    if (provenOnly) rows = rows.filter(r => r.evidenceTier === 'confident');
    // "Money back in 3 weeks" is the server's own fast tier, not a number re-derived here.
    if (fastOnly) rows = rows.filter(r => r.speedTier === 'fast');
    // Cover that is still running, whoever it protects. A seller's own guarantee is worth nothing
    // on resale and is still the reason to buy this unit over the identical uncovered one, so it
    // belongs in the same filter — see WarrantyPricer.
    if (warrantyOnly) rows = rows.filter(r => r.warranty && r.warranty.kind !== 'none' && r.warranty.monthsRemaining > 0);

    // Unpriced rows always sort last whatever the key — "we couldn't price this" isn't a zero.
    const nullsLast = (a, b, key) => (a[key] == null) - (b[key] == null) || null;
    // A free item's ROI is unbounded, not missing — it belongs at the top of an ROI sort, not
    // below a listing that loses money.
    const roiOf = r => (r.roiPercent != null ? r.roiPercent : r.netProfit > 0 && r.localAsk === 0 ? Infinity : null);
    const cmp = {
      profit: (a, b) => nullsLast(a, b, 'netProfit') ?? (b.netProfit - a.netProfit),
      // Two unbounded ROIs are equal, not NaN — Infinity - Infinity would corrupt the sort.
      roi: (a, b) => { const x = roiOf(a), y = roiOf(b); return (x == null) - (y == null) || (x === y ? 0 : y - x); },
      margin: (a, b) => nullsLast(a, b, 'marginPercent') ?? (b.marginPercent - a.marginPercent),
      distance: (a, b) => nullsLast(a, b, 'distanceMiles') ?? (a.distanceMiles - b.distanceMiles),
      // Sorted on the taxed cost, so "cheapest first" means cheapest to actually buy.
      ask: (a, b) => paidFor(a) - paidFor(b),
      // The point of the whole feature: money that comes back soonest, and money that earns most
      // per day it is tied up. Rows that lose money stay below rows that make it in both — a fast
      // route to a loss is not a fast flip — and an unmeasured wait is never treated as instant.
      fastest: (a, b) => ((b.netProfit > 0) - (a.netProfit > 0))
        || (nullsLast(a, b, 'daysToCash') ?? ((a.daysToCash - b.daysToCash) || (b.netProfit - a.netProfit)))
        || 0,
      perday: (a, b) => ((b.netProfit > 0) - (a.netProfit > 0))
        || (nullsLast(a, b, 'profitPerDay') ?? (b.profitPerDay - a.profitPerDay))
        || 0,
    }[sort];
    rows.sort(cmp);

    const shown = $('fb-arb-shown');
    if (shown) {
      shown.textContent = rows.length === arbitrageData.items.length
        ? `${rows.length} shown`
        : `${rows.length} of ${arbitrageData.items.length} shown`;
    }

    body.innerHTML = rows.length
      ? rows.map(arbitrageRowHtml).join('')
      : `<tr><td colspan="9" class="fb-arb-empty">${
          category && arbitrageData.items.length
            ? 'Nothing in that category once the other filters were applied. Set the category back to all to see the rest of what this scan found.'
            : warrantyOnly && arbitrageData.items.length
            ? 'Nothing in this search said it still carries a warranty. Untick the filter to see everything it did find — most classifieds listings never mention cover either way, so this is as often silence as it is a no.'
            : fastOnly && arbitrageData.items.some(r => r.netProfit > 0)
              ? 'Nothing here turns your money around inside three weeks. Untick the filter to see the slower flips this search did find.'
              // An empty board under these two filters is an ANSWER, not a malfunction, and it has
              // to say which bar did the cutting — otherwise it reads as the tool being broken,
              // which is exactly how a board full of unchecked $800 fantasies got trusted instead.
              : (hideLosers || provenOnly) && arbitrageData.items.length
                ? emptyUnderTheBarMessage()
                : 'Nothing here clears its fees. That is a real answer — this search has no local flip worth driving to.'}</td></tr>`;

    // Re-bound after every render: the table body is replaced wholesale by the sort and filter
    // controls, so listeners attached to the previous rows are gone with them.
    body.querySelectorAll('.fb-arb-neg-btn').forEach(btn =>
      btn.addEventListener('click', () => openNegotiation(btn.dataset.key)));
    body.querySelectorAll('.fb-arb-track-btn').forEach(btn =>
      btn.addEventListener('click', () => trackArbitrageRow(btn.dataset.key, btn)));
    body.querySelectorAll('.fb-arb-more').forEach(btn =>
      btn.addEventListener('click', () => toggleArbitrageDetail(btn)));
  }

  // Opens the supporting figures under one row. Closed by default and closed again on the next
  // render: the board is a ranking first, and thirty rows unfolded at once is the wall of numbers
  // this table was just cut down from.
  function toggleArbitrageDetail(btn) {
    const detail = document.getElementById(btn.getAttribute('aria-controls'));
    if (!detail) return;
    const open = detail.classList.toggle('is-open');
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    btn.classList.toggle('is-open', open);
  }

  // Research is only worth what gets acted on. This is the one step between a ranked table the
  // seller closes and a deal they can still see next week — and it freezes the forecast as it
  // stands right now, which is the only way the pipeline can grade it against the outcome later.
  async function trackArbitrageRow(key, btn) {
    const row = (arbitrageData?.items || []).find(r => arbRowKey(r) === key);
    if (!row || !btn) return;

    const original = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Tracking…';

    try {
      const res = await fetch('/api/deals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: row.title,
          stage: 'sourced',
          source: row.source,
          sourceLabel: row.sourceLabel,
          sourceUrl: row.url,
          sourceItemId: row.itemId,
          // Frozen as the cash it will actually take, tax included — the pipeline grades the buy
          // against this later, and a sticker price would grade it against money never spent.
          askPrice: paidFor(row),
          maxBuyPrice: row.maxBuyPrice,
          projectedSalePrice: row.ebayExpectedSale,
          projectedNetProfit: row.netProfit,
          projectedRoiPercent: row.roiPercent,
          projectedDaysToCash: row.daysToCash,
          // What the forecast rested on, carried across verbatim. A projection with no stated
          // basis is impossible to argue with later, which makes it impossible to learn from.
          projectedBasis: [
            // The comps that PRICED it, not the ones the search returned — the pipeline grades this
            // forecast later, and grading it against a comp count it never used teaches nothing.
            row.pricedCompCount ? `${row.pricedCompCount} sold comp${row.pricedCompCount === 1 ? '' : 's'} priced it` : '',
            row.evidenceTier === 'low' ? 'ESTIMATE ONLY' : '',
            row.confidenceLevel,
            row.speedLabel,
          ].filter(Boolean).join(' · '),
        }),
      });

      if (!res.ok) throw new Error(await res.text());
      pipeline = await res.json();
      renderDashboardPipeline();
      btn.textContent = '✓ Tracked';
      btn.classList.add('fb-arb-tracked');
      setLocalStatus(`Tracking "${row.title}" — it's on the Deal Pipeline board, with this forecast frozen against it.`);
      addActivity('Deal tracked', `${row.title} — ${money(row.netProfit || 0)} projected`);
    } catch (err) {
      btn.disabled = false;
      btn.textContent = original;
      setLocalStatus(`Couldn't track that deal: ${errorText(err)}`);
    }
  }

  // Rows have no id of their own that survives across sources, so the key is source + the site's
  // own listing id, with the title as a last resort.
  function arbRowKey(row) {
    return `${row.source}::${row.itemId || row.url || row.title}`;
  }

  // The photo is the decision on this board: nobody can judge a free pool table from the words
  // "Pool Table". So the empty box has exactly one meaning — this post has no photograph — and a
  // URL that 404s or is refused by the host it points at has to land on that same box rather than
  // on the browser's broken-image glyph, which reads as the app being broken instead.
  const ARB_NO_PHOTO = 'This listing has no photo';
  const ARB_PHOTO_FAILED = "This listing's photo couldn't be loaded";

  window.__arbThumbFailed = function (img) {
    const box = document.createElement('span');
    box.className = 'fb-arb-thumb fb-arb-thumb-empty';
    box.title = ARB_PHOTO_FAILED;
    box.setAttribute('aria-label', ARB_PHOTO_FAILED);
    box.textContent = '📦';
    img.replaceWith(box);
  };

  function arbThumbHtml(row) {
    if (!row.imageUrl) {
      return `<span class="fb-arb-thumb fb-arb-thumb-empty" title="${ARB_NO_PHOTO}" aria-label="${ARB_NO_PHOTO}">📦</span>`;
    }
    // referrerpolicy because several of these hosts refuse a hotlink that names where it came from.
    return `<img class="fb-arb-thumb" src="${esc(row.imageUrl)}" alt="" loading="lazy" ` +
           `referrerpolicy="no-referrer" onerror="__arbThumbFailed(this)" />`;
  }

  function arbitrageRowHtml(row, index) {
    const verdict = ARB_VERDICTS[row.verdict] || ARB_VERDICTS.no_data;
    const meta = [
      row.distanceMiles != null ? `${row.distanceMiles} mi` : '',
      row.location ? esc(row.location) : '',
      row.postedAgo ? esc(row.postedAgo) : '',
      // On a retail row the struck-through figure is the retail list price, not a seller who
      // changed their mind — saying "price dropped" about Amazon would be nonsense.
      row.originalPrice
        ? (row.isRetail ? `list ${money(row.originalPrice)}` : `was ${money(row.originalPrice)} — price dropped`)
        : '',
      row.isRetail && row.freeShipping ? 'ships free' : '',
      // A price that only exists with a code is not a price without it.
      row.couponCode ? `<span class="retail-code">code ${esc(row.couponCode)}</span>` : '',
      ...categoryMeta(row),
      ...liquidationMeta(row),
      ...freebieMeta(row),
      ...warrantyMeta(row),
      ...couponMeta(row),
    ].filter(Boolean).join(' · ');

    // A free item has no cost basis, so its ROI is unbounded rather than zero.
    const roi = row.roiPercent != null ? `${Math.round(row.roiPercent)}%`
      : row.netProfit > 0 && row.localAsk === 0 ? '∞' : '—';

    // Percentages off thin or mismatched comps are still shown — hiding them would just hide the
    // lead — but they are dimmed and labelled, so a 698% return backed by one loose sale can never
    // be read the same way as one backed by twenty. See LocalArbitrageAnalyzer.GradeEvidence.
    // Only ever applied to a figure that exists — a dash has nothing to hedge, and hedging it
    // would put a warning on the one row that already says plainly it couldn't be priced.
    const guessed = row.evidenceTier === 'low' && row.ebayExpectedSale != null;

    // ROI lost its column but not its place: the board is ranked by it, and a ranking key nobody
    // can see is a ranking nobody can check. It rides under the net profit it is derived from,
    // the way $/day rides under the wait.
    const roiLine = roi === '—' ? ''
      : `<span class="fb-arb-roi-line${guessed ? ' fb-arb-estimate' : ''}"${
          guessed ? ` title="${esc(row.evidenceNote)}"` : ''}>${roi} ROI</span>`;

    const evidence = row.ebayExpectedSale == null
      // A refused valuation is not "no sold history" — it is "the sold history was for the wrong
      // kind of thing", and the two send a seller to do completely different things next. The
      // provider's own sentence says which, and the link is what the row has instead of a number.
      ? valuationCell(row)
      : [
          // Where the price came from and how far to believe it — the two things a figure someone
          // is about to spend money against has to carry.
          valuationSourceLabel(row),
          // The count that priced it leads, with the count the search returned behind it — they are
          // routinely very different, and only the first one backs the money columns.
          compsCell(row),
              // Which sold-comps database answered, named rather than implied.
          ARB_SOURCES[row.resaleSource] || '',
          row.confidenceLevel ? esc(row.confidenceLevel) : '',
          row.liquidityLevel ? esc(row.liquidityLevel) : '',
        ].filter(Boolean).join(' · ');

    // The row and its detail are two <tr>s, so the stripe can no longer come from nth-child —
    // every second element would be a detail panel. Parity and the top-three rank colour are set
    // here instead, on the row that is actually a deal (see .fb-arb-row.is-alt in style.css).
    const detailId = `fb-arb-detail-${index}`;
    const state = [
      'fb-arb-row',
      `fb-arb-row-${verdict.cls}`,
      index % 2 ? 'is-alt' : '',
      index < 3 ? 'is-top3' : '',
    ].filter(Boolean).join(' ');

    return `
      <tr class="${state}">
        <td class="fb-arb-th-rank" data-label="Rank">${index + 1}</td>
        ${/* The flex lives on a span inside the cell, never on the cell itself: a cell that is
              itself display:flex stops stretching to the row's height, and its bottom border then
              draws a stray rule across one column halfway up the row. */''}
        <td class="fb-arb-deal" data-label="Deal">
          <span class="fb-arb-item">
          ${arbThumbHtml(row)}
          <span class="fb-arb-item-text">
            <a class="fb-arb-title" href="${esc(row.url)}" target="_blank" rel="noopener">${esc(row.title)} ↗</a>
            <span class="fb-arb-meta">${meta}</span>
            <span class="fb-arb-badges">
              <span class="fb-verdict fb-verdict-${verdict.cls}">${verdict.label}</span>
              ${/* The one warning that must not need a click: a price this thin is the difference
                    between a lead and a fact, and it used to sit in a column that is now folded away. */
                guessed ? estimateFlag(row) : ''}
              <button class="fb-arb-more" type="button" aria-expanded="false" aria-controls="${detailId}">
                <span class="fb-arb-more-chev" aria-hidden="true">›</span>Resale, fees, ROI &amp; evidence
              </button>
            </span>
            <span class="fb-arb-note">${esc(row.verdictNote)}</span>
          </span>
          </span>
        </td>
        <td class="fb-arb-source" data-label="Source"><span class="local-badge local-badge-${esc(row.source)}">${esc(row.sourceLabel || row.source)}</span></td>
        <td class="num" data-label="You pay">${buyCostCell(row)}</td>
        <td class="num dt-money fb-arb-profit ${row.netProfit > 0 ? 'good' : row.netProfit != null ? 'bad' : ''}" data-label="Net profit">${row.netProfit != null ? money(row.netProfit) : '—'}${couponProfitLine(row)}${roiLine}</td>
        <td class="num fb-arb-speed" data-label="Days to cash">${daysToCashCell(row)}</td>
        <td class="num" data-label="Max to pay">${row.maxBuyPrice != null ? money(row.maxBuyPrice) : '—'}</td>
        <td class="num fb-arb-offer" data-label="Offer them"><span class="fb-arb-offer-stack">${offerCell(row)}</span></td>
        <td class="fb-arb-track" data-label="Track">${trackCell(row)}</td>
      </tr>
      ${arbitrageRowDetailHtml(row, detailId, guessed, evidence)}`;
  }

  // The supporting half of a row, folded away until it is asked for. Nothing here is new and
  // nothing was dropped: these are the five columns the board used to carry behind a horizontal
  // scrollbar — the resale price every profit figure was computed from, the fees taken back out of
  // it, the two percentage views of the same spread, and the evidence the price rests on. They are
  // the answer to "why is that the number", which is a question asked of one row at a time, not of
  // thirty at once. Kept in the same DOM row so it opens under the deal it explains.
  function arbitrageRowDetailHtml(row, detailId, guessed, evidence) {
    // The comp lookup runs on the fullest title in the product group, which may not be this
    // row's own wording — say so rather than implying the match was against this exact tile.
    const pricedAs = row.pricedAs && row.pricedAs !== row.title
      ? ` title="Priced as: ${esc(row.pricedAs)}"` : '';
    // The hedge follows the figure, not the column: a resale price, an ROI and a margin off two
    // loose comps are all one guess wearing three faces.
    const hedge = guessed ? ` class="fb-arb-fig-value fb-arb-estimate" title="${esc(row.evidenceNote)}"` : ' class="fb-arb-fig-value"';

    const fig = (label, value, attrs = ' class="fb-arb-fig-value"') =>
      `<div class="fb-arb-fig"><span class="fb-arb-fig-label">${label}</span><span${attrs}>${value}</span></div>`;

    return `
      <tr class="fb-arb-detail-row" id="${detailId}">
        <td class="fb-arb-detail" colspan="9">
          <div class="fb-arb-detail-figs"${pricedAs}>
            ${fig('Resell on eBay',
                  `${row.ebayExpectedSale != null ? money(row.ebayExpectedSale) : manualResaleCell(row)}${warrantyResaleLine(row)}`,
                  hedge)}
            ${fig('eBay fees &amp; shipping',
                  `${row.estimatedFees != null ? `-${money(row.estimatedFees)}` : '—'}${categoryCostLine(row)}`,
                  ' class="fb-arb-fig-value fb-arb-cost"')}
            ${fig('ROI', row.roiPercent != null ? `${Math.round(row.roiPercent)}%`
                    : row.netProfit > 0 && row.localAsk === 0 ? '∞' : '—', hedge)}
            ${fig('Margin', row.marginPercent != null ? `${Math.round(row.marginPercent)}%` : '—', hedge)}
          </div>
          <div class="fb-arb-fig fb-arb-fig-evidence">
            <span class="fb-arb-fig-label">Evidence</span>
            <span class="fb-arb-evidence">${evidence}${row.disagreementMessage ? ` <span class="fb-arb-flag" title="${esc(row.disagreementMessage)}">⚠</span>` : ''}</span>
          </div>
          ${/* The evidence line above says how much to believe the price; this says how the price
                was arrived at. Folded shut, because it is the answer to a question asked of one
                row — but asked of that row it has to be answerable. */''}
          ${priceBasisHtml(row.priceBasis)}
        </td>
      </tr>`;
  }

  // ── Category, vehicle and valuation ───────────────────────────────────────
  // What kind of thing this row is, and — where it isn't a parcel — how that changed the money. The
  // category chip is only worth showing when it is not the default: labelling every row "Anything"
  // is noise, and labelling the truck "Cars & trucks" is the whole point.
  function categoryMeta(row) {
    const out = [];

    if (row.categoryId && row.categoryId !== 'anything' && row.categoryLabel)
      out.push(`<span class="cat-chip">${esc(row.categoryLabel)}</span>`);

    // The identity the app read off the title, plus the wear. Shown because "2011 Toyota Tundra ·
    // 137,000 miles" is the entire basis on which a seller decides whether to drive to it, and it
    // is buried in the middle of the ad copy in the title beside it.
    // The wear stands on its own: plenty of ads state an odometer and never say what the thing is,
    // and "100,000 miles" is worth reading whether or not the year and make came with it.
    const vehicle = row.vehicle;
    if (vehicle?.label) out.push(`<span class="veh-chip">${esc(vehicle.label)}</span>`);
    if (vehicle?.wearText) out.push(`<span class="veh-wear">${esc(vehicle.wearText)}</span>`);

    // The departures from the parcel model, said on the row. A net profit with no shipping and no
    // percentage fee in it is a good number and a misleading one if the row doesn't say so.
    const cat = row.category;
    if (cat && cat.shipsToBuyer === false)
      out.push(`<span class="cat-pickup" title="${esc(cat.note || '')}">buyer collects · ${esc(cat.feeBasis || '')}</span>`);

    return out;
  }

  // The costs a parcel row has no line for: the title transfer, and transport when it is ever
  // costed. Under the fees rather than inside them — eBay doesn't charge you to register a truck,
  // and folding the two together would make the row's stated fee basis uncheckable.
  function categoryCostLine(row) {
    const cat = row.category;
    if (!cat || !(cat.extraCostTotal > 0) || row.netProfit == null) return '';
    return `<br /><span class="cat-extra" title="${esc(cat.note || '')}">-${money(cat.extraCostTotal)} title &amp; transport</span>`;
  }

  // Where the price came from and how far to believe it, in one phrase. Two facts that always
  // travel together: a source with no confidence beside it invites the number to be read as a
  // fact, and a confidence with no source invites it to be read as eBay's.
  function valuationSourceLabel(row) {
    const val = row.valuation;
    if (!val || !val.sourceLabel) return '';
    const tier = val.confidence === 'confident' ? 'ok' : val.confidence === 'low' ? 'weak' : 'none';
    return `<span class="val-src val-src-${tier}" title="${esc(val.note || '')}">${esc(val.sourceLabel)}</span>`;
  }

  // A row the app refused to price. Everything here is deliberately not a number: the sentence
  // saying why, and the search that answers it. Inventing a resale price for a category with no comp
  // data would put a fabricated profit on a board somebody spends money from — see
  // Services/ResaleValuation.cs.
  function valuationCell(row) {
    const val = row.valuation;
    if (!val) return '<span class="fb-arb-muted">no sold history</span>';

    const link = val.lookupUrl
      ? ` <a class="link-ext val-lookup" href="${esc(val.lookupUrl)}" target="_blank" rel="noopener">check sold listings ↗</a>`
      : '';
    return `<span class="val-manual" title="${esc(val.note || '')}">${esc(val.sourceLabel || 'estimate unavailable')}</span>${link}`;
  }

  // What sits where the resale price would be on a refused row. "Estimate unavailable" rather than a
  // dash, because a dash reads as a bug and this is an answer.
  function manualResaleCell(row) {
    const val = row.valuation;
    if (!val || val.status !== 'manual') return '—';
    return `<span class="val-manual-price" title="${esc(val.note || '')}">estimate<br />unavailable</span>`;
  }

  // How many comps actually set this price, out of how many the search returned. The gap between
  // the two is the whole point: a twelve-comp search that priced off one of them is not a
  // twelve-comp price, and until now the row only ever showed the twelve.
  function compsCell(row) {
    const priced = row.pricedCompCount || 0;
    const found = row.soldCompCount || 0;
    if (!found) return '';
    if (!priced) return `${found} sold comp${found === 1 ? '' : 's'}`;

    const label = `${priced} sold comp${priced === 1 ? '' : 's'} priced it`;
    return priced < found
      ? `<span title="${found} matched the search; the rest were a different product, a different quantity, or a price outlier.">${label} <span class="fb-arb-muted">of ${found}</span></span>`
      : label;
  }

  // ── Where the price came from, and where the confidence went ──────────────
  // The panel that answers "why should I believe that number?" without asking anyone to take a
  // word of it on trust. Two halves, and both are arithmetic rather than adjectives:
  //
  //   1. The blend. Each sold-data source's OWN figure, its comp count, and how much of the price
  //      is its opinion. The board could already say "63% local / 37% Terapeak" and had no way to
  //      say 63% and 37% *of what* — the two medians are overwritten the moment they are combined.
  //   2. The confidence score, taken apart into the seven terms that make it, with the points each
  //      one earned out of the points it could have. A bare "62" can only be accepted or ignored;
  //      the same 62 with "no comp matched on a part number — 20 points" is something the seller
  //      can act on.
  //
  // Shared by the deals board and the Opportunity Finder, so the two screens can never explain the
  // same pipeline's numbers differently. See Services/PriceBasis.cs.
  function priceBasisHtml(basis) {
    if (!basis || !(basis.price > 0)) return '';

    const sources = (basis.sources || []).map(s => {
      // "7 of 19 comps" — the gap is the identity guard, the outlier trim and the strong-match
      // filter, and it is routinely most of the search. Only the first number backs the price.
      const counts = s.foundCount > s.compCount
        ? `${s.compCount} of ${s.foundCount} comps`
        : `${s.compCount} comp${s.compCount === 1 ? '' : 's'}`;
      // When these sales happened, and what their age already cost this source's share. The
      // weights are age-adjusted before they get here, so a reader given the percentages and not
      // the dates is being shown an adjustment with its reason left off screen.
      const age = [s.asOf, s.freshnessNote].filter(Boolean).join(' · ');
      return `<div class="pb-src">
        <span class="pb-src-name">${esc(s.label)}</span>
        <span class="pb-src-count">${counts}</span>
        <span class="pb-src-value">${esc(s.valueLabel)} ${moneyExact(s.value)}</span>
        <span class="pb-src-weight">${Math.round(s.weightPercent)}%</span>
        ${age ? `<span class="pb-src-age">${esc(age)}</span>` : ''}
      </div>`;
    }).join('');

    const factors = (basis.confidenceFactors || []).map(f => {
      const earned = Number.isInteger(f.earned) ? f.earned : f.earned.toFixed(1);
      const pts = `${earned} / ${f.possible}`;
      return `<div class="pb-factor">
        <span class="pb-factor-label">${esc(f.label)}</span>
        ${vizMeter(f.earned, {
          max: f.possible, valueText: pts,
          label: `${f.label}: ${pts} confidence points`,
          tip: f.lever ? `${f.detail}\n${f.lever}` : f.detail,
        })}
        <span class="pb-factor-detail">${esc(f.detail)}</span>
      </div>`;
    }).join('');

    // The two figures the blend line doesn't state and a seller checking this row will look for:
    // the plain median (what an eBay sold search shows them) and what to actually list at.
    const alsos = [
      basis.medianPrice != null ? `median of the same comps ${moneyExact(basis.medianPrice)}` : '',
      basis.recommendedListingPrice != null ? `list at ${moneyExact(basis.recommendedListingPrice)}` : '',
    ].filter(Boolean).join(' · ');

    return `<details class="pb-basis">
      <summary class="pb-summary">How this price and its confidence were worked out</summary>
      <div class="pb-body">
        ${basis.disagreementMessage ? `<p class="pb-disagree">⚠ ${esc(basis.disagreementMessage)}</p>` : ''}
        <p class="pb-arith">${esc(basis.arithmetic)}</p>
        ${sources ? `<div class="pb-srcs">${sources}</div>` : ''}
        ${alsos ? `<p class="pb-also">${esc(alsos)}</p>` : ''}
        <p class="pb-conf-head">Confidence <strong>${basis.confidenceScore}</strong> / 100${
          basis.confidenceLevel ? ` — ${esc(basis.confidenceLevel)}` : ''}</p>
        ${factors ? `<div class="pb-factors">${factors}</div>` : ''}
        ${basis.biggestGap ? `<p class="pb-gap"><strong>Biggest gap:</strong> ${esc(basis.biggestGap)}</p>` : ''}
      </div>
    </details>`;
  }

  // The label beside a dimmed figure. Without it a greyed-out percentage reads as a rendering
  // fault; with it, it reads as the warning it is. Returns the chip alone — the caller decides
  // whether it goes on its own line under a figure or into the stack beside the title.
  function estimateFlag(row) {
    if (row.evidenceTier !== 'low' || row.ebayExpectedSale == null) return '';
    const why = row.identityVerified === false
      ? 'no comp matches this model'
      : `too few comps (${(row.pricedCompCount || 0) + (row.terapeakCompCount || 0)})`;
    return `<span class="fb-arb-estimate-flag" title="${esc(row.evidenceNote)}">estimate — ${why}</span>`;
  }

  // The way out of a research table and into the pipeline. Offered on every row that could be
  // priced — including the ones that don't profit, because "I looked at this and walked" is worth
  // recording too — but never on a row with no sold history, which has no forecast to freeze.
  function trackCell(row) {
    if (row.ebayExpectedSale == null) {
      return '<span class="fb-arb-muted" title="Nothing sold-comp-backed to freeze against this one.">—</span>';
    }
    const tracked = isDealTracked(row.source, row.itemId);
    return tracked
      ? '<span class="fb-arb-tracked-flag" title="Already on the Deal Pipeline board.">✓ Tracked</span>'
      : `<button class="btn btn-secondary small fb-arb-track-btn" type="button" data-key="${esc(arbRowKey(row))}">＋ Track</button>`;
  }

  function isDealTracked(source, itemId) {
    if (!itemId || !pipeline?.deals) return false;
    return pipeline.deals.some(d => d.deal?.source === source && d.deal?.sourceItemId === itemId);
  }

  // Everything an auction row says about itself that a classifieds row has no equivalent for: what
  // the sale is, who is running it, how many units are in the lot, and — the part that expires —
  // how long is left to bid.
  function liquidationMeta(row) {
    const lot = row.liquidation;
    if (!lot) return [];

    const closing = lot.timeLeft
      ? `<span class="${closingSoon(lot) ? 'liq-closing-soon' : 'liq-closing'}">closes in ${esc(lot.timeLeft)}</span>`
      : '';

    return [
      // The reason the stock is cheap, and the whole point of the board.
      lot.isLiquidationEvent && lot.eventName
        ? `<span class="liq-event">${esc(lot.eventName)}</span>`
        : (lot.eventName ? esc(lot.eventName) : ''),
      lot.auctionHouse ? esc(lot.auctionHouse) : '',
      lot.isLot ? `<span class="liq-units">lot of ${lot.units}${lot.gradeLabel ? ` · ${esc(lot.gradeLabel)}` : ''}</span>` : '',
      // "No bids yet" is a materially different position from "you are bidding against people".
      lot.isStartingBid ? 'no bids yet' : `${lot.bidCount} bid${lot.bidCount === 1 ? '' : 's'}`,
      closing,
    ];
  }

  function closingSoon(lot) {
    if (!lot.closesUtc) return false;
    const hours = (new Date(lot.closesUtc) - Date.now()) / 3600000;
    return hours > 0 && hours <= 48;
  }

  // What a free row says about itself. The deadline leads, because it is the thing that actually
  // decides whether this deal is real: a free classified post is claimed within hours, and a free
  // price is pulled without notice. Everything else here is a cost the word "free" hides.
  const FREE_URGENCY = {
    today: { cls: 'now', label: 'gone today' },
    first_come: { cls: 'now', label: 'first come, first served' },
    this_week: { cls: 'soon', label: 'ends this week' },
  };

  function freebieMeta(row) {
    const free = row.freebie;
    if (!free) return [];

    const clock = FREE_URGENCY[free.urgency];

    return [
      `<span class="free-kind">${esc(free.kindLabel)}</span>`,
      clock ? `<span class="free-clock free-clock-${clock.cls}" title="${esc(free.urgencyNote)}">⏱ ${clock.label}${free.expiresText ? ` (${esc(free.expiresText)})` : ''}</span>` : '',
      free.isPickup ? 'collect in person' : '',
      // The code is the price. Without it this is a full-price item.
      free.requiresCoupon && !row.couponCode ? '<span class="retail-code">needs the code</span>' : '',
      // A cost the app could not see, large enough to change the answer — see FreebiePricer.CapReason.
      free.cappedReason ? `<span class="free-caveat" title="${esc(free.cappedReason)}">⚠ read this</span>` : '',
    ];
  }

  // What a used item's cover says about itself. Two very different chips come out of here and the
  // difference is the whole feature: cover that TRANSFERS is a line the seller can put in their own
  // listing and is already inside the profit beside it, while cover that doesn't still protects the
  // money they are about to spend. A stated absence of cover gets the loudest chip of the three,
  // because on an expensive buy it is the most important thing the listing said.
  const WARRANTY_TONE = {
    none: 'risk',
    seller: 'partial',
    manufacturer: 'ok',
    refurbisher: 'ok',
    extended: 'ok',
  };

  function warrantyMeta(row) {
    const cover = row.warranty;
    if (!cover) return [];

    // An estimate is never dressed as a fact. It reaches the seller because "bought three months
    // ago and Dyson runs two years — ask for the receipt" is worth acting on, and it is marked as
    // worked-out rather than stated everywhere it appears.
    const tone = cover.kind === 'none' ? 'risk'
      : cover.evidence === 'estimated' ? 'guess'
      : (WARRANTY_TONE[cover.kind] || 'partial');

    const worth = cover.resaleUplift > 0
      ? ` — worth ${money(cover.resaleUplift)} more on resale`
      : '';

    return [
      `<span class="warranty-chip warranty-chip-${tone}" title="${esc(cover.note)}">` +
        `${cover.kind === 'none' ? '⚠' : '🛡'} ${esc(cover.kindLabel)}${worth}</span>`,
      // The one that changes a decision rather than a number.
      cover.riskNote
        ? `<span class="warranty-risk" title="${esc(cover.riskNote)}">no cover, no returns — test it first</span>`
        : '',
      // Said plainly, because it is the difference between a claim and a conversation.
      cover.hasProofOfPurchase ? '<span class="warranty-proof">receipt mentioned</span>' : '',
    ];
  }

  // The premium, under the resale price it is already part of. Shown rather than folded away
  // silently: this is the one figure on the board that came from a listing's prose instead of from
  // sold comps, and the seller should be able to see it and subtract it.
  function warrantyResaleLine(row) {
    const cover = row.warranty;
    if (!cover || !(cover.resaleUplift > 0)) return '';

    return `<br /><span class="warranty-extra" title="${esc(cover.note)}">` +
      `incl. +${money(cover.resaleUplift)} still under warranty</span>`;
  }

  // What a promo code does to this row. The code itself leads, because it is the thing the seller
  // has to type — everything after it is the condition attached to it.
  const COUPON_CONFIDENCE = {
    high: { cls: 'ok', label: 'looks live' },
    medium: { cls: 'maybe', label: 'unconfirmed' },
    low: { cls: 'weak', label: 'lead only' },
  };

  function couponMeta(row) {
    const coupons = row.coupons;
    if (!coupons) return [];

    const applied = (coupons.applied || []).filter(o => o.code);
    const cashback = (coupons.applied || []).find(o => o.kind === 'cashback');
    const grade = COUPON_CONFIDENCE[coupons.confidence] || COUPON_CONFIDENCE.low;

    return [
      // The saving, with everything that qualifies it one hover away. A code with no discount
      // behind it still earns its place: the seller can go and try it.
      coupons.discount > 0
        ? `<span class="coupon-chip coupon-chip-${grade.cls}" title="${esc(coupons.note)}">🏷 ${applied.map(o => esc(o.code)).join(' + ')} — ${money(coupons.discount)} off · ${grade.label}</span>`
        : (coupons.alsoFound || []).length
          ? `<span class="coupon-chip coupon-chip-weak" title="${esc(coupons.note)}">🏷 ${coupons.alsoFound.length} code${coupons.alsoFound.length === 1 ? '' : 's'} for ${esc(row.retailer || 'this store')} — none counted</span>`
          : '',
      cashback
        ? `<span class="coupon-cashback" title="Paid by the portal, not the store — so it stacks with a code. ${esc(coupons.note)}">${money(coupons.cashbackExpected)} back in ~${coupons.cashbackWaitDays}d</span>`
        : '',
      // The one that changes a decision rather than a number: without the code this row is a walk.
      coupons.rescuesTheDeal
        ? '<span class="coupon-rescue" title="At the shelf price this loses money. It only works if the code does.">only profits with the code</span>'
        : '',
    ];
  }

  // What the code is worth, under the profit it would be added to. Never merged into the figure
  // above it: the row's own profit is the one the app stands behind, and a public code is a claim.
  function couponProfitLine(row) {
    const coupons = row.coupons;
    if (!coupons || !(coupons.extraProfit > 0)) return '';

    const verdict = coupons.verdictIfItWorks ? ARB_VERDICTS[coupons.verdictIfItWorks] : null;
    return `<br /><span class="coupon-extra" title="${esc(coupons.note)}">+${money(coupons.extraProfit)} with the code` +
      `${verdict ? ` → ${esc(verdict.label.toLowerCase())}` : ''}</span>`;
  }

  // Which stores were checked and what each one had — including the ones that had nothing, because
  // "we checked Amazon and Amazon doesn't take codes" is an answer and an empty column isn't. The
  // links are the point on the blocked lists: RetailMeNot and the cashback portals refuse automated
  // reads, so the seller opening them is the feature working rather than a fallback.
  function renderCouponStores(stores) {
    const wrap = $('fb-arb-coupons');
    if (!wrap) return;

    const list = stores || [];
    wrap.classList.toggle('hidden', list.length === 0);
    if (!list.length) return;

    wrap.innerHTML =
      '<div class="coupon-stores-head">🏷 Codes checked on the buy side</div>' +
      list.map(store => `
        <div class="coupon-store">
          <span class="coupon-store-name">${esc(store.merchantLabel)}</span>
          <span class="coupon-store-count">${store.status === 'error'
            ? 'couldn\'t be checked'
            : `${store.offerCount} code${store.offerCount === 1 ? '' : 's'}`}${store.rowCount ? ` · ${store.rowCount} row${store.rowCount === 1 ? '' : 's'}` : ''}</span>
          ${store.note ? `<span class="coupon-store-note">${esc(store.note)}</span>` : ''}
          ${store.error ? `<span class="coupon-store-note">${esc(store.error)}</span>` : ''}
          <span class="coupon-store-links">${(store.manualSites || []).map(site =>
            `<a href="${esc(site.urlTemplate)}" target="_blank" rel="noopener" title="${esc(site.note)}">${esc(site.label)} ↗</a>`
          ).join(' · ')}</span>
        </div>`).join('');
  }

  // ── Coupon check ──────────────────────────────────────────────────────────
  // The same lookup the scan runs per store, pointed at whatever the seller is looking at in
  // another tab. Its own control because most buying happens outside this app, and a code found
  // before checkout is worth exactly as much as one found on the board.
  function bindCouponCheck() {
    const btn = $('coupon-check-btn');
    if (!btn) return;

    btn.addEventListener('click', runCouponCheck);
    ['coupon-store-input', 'coupon-price-input'].forEach(id =>
      $(id)?.addEventListener('keydown', event => { if (event.key === 'Enter') runCouponCheck(); }));
  }

  async function runCouponCheck() {
    const store = ($('coupon-store-input')?.value || '').trim();
    const price = parseFloat($('coupon-price-input')?.value);
    const status = $('coupon-check-status');
    const results = $('coupon-check-results');
    const btn = $('coupon-check-btn');
    if (!status || !results) return;

    if (!store) { status.textContent = 'Name the store you are buying from.'; return; }

    results.classList.add('hidden');
    status.textContent = `Reading the public code lists for ${store}…`;
    if (btn) btn.disabled = true;

    const params = new URLSearchParams({ store });
    if (price > 0) params.set('price', price);
    // The seller's own rate, shared with the scan above — a code lowers what the register rings up,
    // so the tax it saves is part of what it saves.

    const { data, error } = await localFetchJson(`/api/coupons?${params}`, 60000);
    if (btn) btn.disabled = false;

    if (!data) { status.textContent = error || 'The coupon lookup couldn\'t be completed.'; return; }

    status.textContent = '';
    renderCouponLookup(data);
  }

  function renderCouponLookup(data) {
    const results = $('coupon-check-results');
    if (!results) return;

    const grade = COUPON_CONFIDENCE[data.stack?.confidence] || COUPON_CONFIDENCE.low;
    const stack = data.stack;

    // The answer, when there is a price to answer against: what this actually costs with the best
    // legal combination applied, beside what it cost before.
    const priced = stack && stack.hasSaving
      ? `<div class="coupon-verdict coupon-verdict-${grade.cls}">
           <strong>${money(stack.netCost)}</strong> all-in, from a ${money(stack.subtotal)} price
           <span class="coupon-verdict-sub">${grade.label}</span>
           <div class="coupon-verdict-note">${esc(stack.note)}</div>
         </div>`
      : stack
        ? `<div class="coupon-verdict coupon-verdict-weak"><div class="coupon-verdict-note">${esc(stack.note)}</div></div>`
        : '';

    const offers = (data.offers || []).map(offer => `
      <li class="coupon-offer">
        ${offer.code ? `<code class="coupon-code">${esc(offer.code)}</code>` : '<span class="coupon-code coupon-code-none">no code</span>'}
        <span class="coupon-offer-what">${esc(couponOfferText(offer))}</span>
        <!-- The distinction that decides whether a code is worth anything on a different item.
             Most codes on these lists are posted against one deal — see CouponOffer.AppliesToOrder. -->
        <span class="coupon-offer-scope">${offer.appliesToOrder ? 'any order' : 'that deal only'}</span>
        ${offer.minSpend > 0 ? `<span class="coupon-offer-min">on orders over ${money(offer.minSpend)}</span>` : ''}
        ${offer.expiresUtc ? `<span class="coupon-offer-exp">until ${esc(shortDate(offer.expiresUtc))}</span>` : ''}
        <span class="coupon-offer-grade coupon-chip-${(COUPON_CONFIDENCE[offer.confidence] || COUPON_CONFIDENCE.low).cls}"
              title="${esc(offer.confidenceNote)}">${(COUPON_CONFIDENCE[offer.confidence] || COUPON_CONFIDENCE.low).label}</span>
        ${offer.exclusionsNote ? `<span class="coupon-offer-excl">${esc(offer.exclusionsNote)}</span>` : ''}
        <a class="coupon-offer-src" href="${esc(offer.url)}" target="_blank" rel="noopener">${esc(offer.sourceLabel)} ↗</a>
      </li>`).join('');

    results.innerHTML =
      priced +
      // Said out loud rather than left as an empty list: at some stores a code list is simply the
      // wrong place to look, and silence there reads as "no discount available".
      (data.merchantNote ? `<p class="coupon-merchant-note">${esc(data.merchantNote)}</p>` : '') +
      (data.error ? `<p class="coupon-merchant-note">${esc(data.error)}</p>` : '') +
      (offers
        ? `<ul class="coupon-offers">${offers}</ul>`
        : `<p class="coupon-merchant-note">No machine-readable codes found for ${esc(data.merchantLabel || data.query)} right now.</p>`) +
      `<div class="coupon-store-links">${(data.manualSites || []).map(site =>
        `<a href="${esc(site.urlTemplate)}" target="_blank" rel="noopener" title="${esc(site.note)}">${esc(site.label)} ↗</a>`
      ).join(' · ')}</div>`;

    results.classList.remove('hidden');
  }

  function couponOfferText(offer) {
    if (offer.kind === 'percent_off') {
      return offer.value > 0
        ? `${offer.value}% off${offer.maxDiscount > 0 ? `, up to ${money(offer.maxDiscount)}` : ''}`
        : offer.title;
    }
    if (offer.kind === 'amount_off') return offer.value > 0 ? `${money(offer.value)} off` : offer.title;
    if (offer.kind === 'cashback') return `${offer.value}% back after the order`;
    if (offer.kind === 'free_shipping') return 'free shipping';
    return offer.title;
  }

  // What actually leaves the wallet. On a private-party buy that is the asking price; on a retail
  // buy the register adds sales tax, and on an auction the house adds its premium first and the tax
  // sits on top of both. Every profit figure in the row was computed from the all-in number — so
  // showing the sticker alone would leave the arithmetic looking wrong.
  function buyCostCell(row) {
    // A free row is the one place where the headline number and the money that leaves the wallet
    // are genuinely different things: a rebate deal costs full price today and pays most of it back
    // in eight weeks. Showing only the net would describe a deal the seller isn't being offered.
    const free = row.freebie;
    if (free && free.outOfPocketNow > 0) {
      return `${money(row.buyCostAllIn || 0)}` +
        `<br /><span class="retail-tax" title="${esc(free.costNote)}">${money(free.outOfPocketNow)} up front, ` +
        `${money(free.refundExpected)} back${free.refundWaitDays ? ` in ~${free.refundWaitDays}d` : ''}</span>`;
    }
    if (free) return '<span class="free-price">Free</span>';

    if (!(row.buyCostAllIn > 0)) return row.localAsk > 0 ? money(row.localAsk) : 'Free';

    const lot = row.liquidation;
    const lines = [];

    if (lot && lot.buyerPremium > 0) {
      lines.push(`<span class="retail-tax">${money(row.localAsk)} bid + ${money(lot.buyerPremium)} premium` +
        `${lot.buyerPremiumAssumed ? ' (assumed)' : ''}${row.salesTax > 0 ? ` + ${money(row.salesTax)} tax` : ''}</span>`);
    } else if (row.salesTax > 0) {
      lines.push(`<span class="retail-tax">${money(row.localAsk)} + ${money(row.salesTax)} tax</span>`);
    }

    // On a lot the number that decides anything is the cost of one sellable unit — $240 for a
    // pallet means nothing until you know it is $6.50 an item.
    if (lot && lot.isLot && lot.costPerSellableUnit > 0) {
      lines.push(`<span class="liq-per-unit">${money(lot.costPerSellableUnit)} per unit you can sell</span>`);
    }

    // What the same buy costs with a code typed in. Second, and marked as conditional, because the
    // figure above it is the one every other number on the row was computed from.
    if (row.coupons?.discount > 0) {
      lines.push(`<span class="coupon-cost" title="${esc(row.coupons.note)}">` +
        `${money(row.coupons.buyCostWithCoupons)} with the code</span>`);
    }

    return `${money(row.buyCostAllIn)}${lines.length ? `<br />${lines.join('<br />')}` : ''}`;
  }

  // The cash a row ties up — the figure to sort and budget on, taxed where tax applies.
  function paidFor(row) {
    return row.buyCostAllIn != null ? row.buyCostAllIn : row.localAsk;
  }

  // The buy-side cell: what to open at, what saying it is worth, and the way into the drafts.
  // A row we'd walk away from gets the walk badge and no button — the most useful thing this
  // feature can do on a bad deal is fail to produce a message for it.
  function offerCell(row) {
    const plan = row.negotiation;

    // Nothing to negotiate at zero. What this row needs instead is speed, so that is what the cell
    // says — the whole of the buy-side decision on a free item is "get there before somebody else".
    if (row.freebie) {
      return `<span class="fb-arb-muted" title="${esc(row.freebie.urgencyNote)}">free — just be first</span>`;
    }

    // Nobody at Amazon is reading your offer. The honest buy-side answer on a retail row is the
    // shelf price to stop at, which is already in the "Max to pay" column beside this one — so
    // this says so instead of drafting a message that cannot be sent.
    if (row.isRetail) {
      return '<span class="fb-arb-muted" title="Retail price — there is nobody to haggle with. The number to act on is Max to pay: above that shelf price this stops making money.">retail — no haggling</span>';
    }

    // An auctioneer takes bids, not offers. The buy-side decision on this row is entirely "what is
    // the most I can bid", and that number — premium and tax already removed from it — is the one
    // shown here, because it is the only thing the seller has to remember when the clock runs down.
    if (row.liquidation) {
      const max = row.liquidation.maxBidForTargetRoi;
      if (!(max > 0)) {
        return '<span class="fb-arb-muted" title="The bid is already past what this lot returns after the premium, the tax and eBay\'s fees.">bid past it — walk</span>';
      }
      return `
        <span class="neg-offer" title="Bid up to this and you still clear ${Math.round(row.liquidation.targetRoiPercent)}% ROI after the buyer's premium, sales tax, eBay's fees and shipping.">${money(max)}</span>
        <span class="neg-upside">max bid</span>`;
    }

    if (!plan || plan.verdict === 'no_data') {
      return '<span class="fb-arb-muted" title="No sold history matched this, so there is no honest number to negotiate against.">—</span>';
    }

    const v = NEG_VERDICTS[plan.verdict] || NEG_VERDICTS.no_data;
    if (plan.openingOffer == null) {
      return `<span class="neg-badge neg-${v.cls}" title="${esc(plan.headline)}">${v.label}</span>`;
    }

    return `
      <span class="neg-offer" title="${esc(plan.headline)}">${money(plan.openingOffer)}</span>
      ${plan.upside > 0 ? `<span class="neg-upside">saves ${money(plan.upside)}</span>` : ''}
      <span class="neg-badge neg-${v.cls}">${v.label}</span>
      <button class="btn btn-secondary small fb-arb-neg-btn" type="button" data-key="${esc(arbRowKey(row))}">What to say</button>`;
  }

  // ── Buy-side negotiation ─────────────────────────────────────────────────
  // The other half of every deal on the board above. A dollar talked off the buy price is worth
  // more than a dollar added to the sale price — it arrives now, eBay takes none of it, and nothing
  // has to ship for it. This is where that dollar gets asked for.
  function bindNegotiation() {
    const close = () => $('neg-overlay')?.classList.add('hidden');
    on('neg-close', 'click', close);
    on('neg-close-x', 'click', close);
    $('neg-overlay')?.addEventListener('click', e => {
      if (e.target.id === 'neg-overlay') close();
    });
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && !$('neg-overlay')?.classList.contains('hidden')) close();
    });
  }

  function openNegotiation(key) {
    const row = (arbitrageData?.items || []).find(r => arbRowKey(r) === key);
    const plan = row?.negotiation;
    if (!plan) return;

    const v = NEG_VERDICTS[plan.verdict] || NEG_VERDICTS.no_data;
    $('neg-title').textContent = row.title;
    const headline = $('neg-headline');
    headline.className = `neg-headline neg-headline-${v.cls}`;
    headline.textContent = plan.headline;

    // The four numbers, in the order they get used: open here, stop here, never past here.
    $('neg-numbers').innerHTML = [
      tile('Their ask', money(plan.askPrice), row.postedAgo ? `listed ${esc(row.postedAgo)}` : ''),
      plan.openingOffer != null
        ? tile('Open at', money(plan.openingOffer),
               plan.upside > 0 ? `${plan.openingDiscountPercent}% off — ${money(plan.upside)} straight to you` : 'their price', 'open')
        : '',
      plan.ceilingPrice != null
        ? tile('Stop at', money(plan.ceilingPrice),
               // When the ceiling IS their ask, "above this it stops being worth the drive" reads as
               // a warning about a price nobody is being asked to pay.
               plan.ceilingPrice >= plan.askPrice
                 ? 'their price is already inside your limit'
                 : 'above this it stops being worth the drive', 'stop') : '',
      tile('Break-even', money(plan.breakEvenPrice), 'pay this and you worked for free', 'stop'),
    ].filter(Boolean).join('');

    $('neg-signals').innerHTML = (plan.signals || []).length
      ? `<div class="neg-signals-head">Your leverage</div><ul>${
          plan.signals.map(s => `<li>${esc(s)}</li>`).join('')}</ul>`
      : '';

    // The counter-offer table: they name a number mid-conversation, and this says yes or no without
    // any arithmetic happening in a driveway.
    $('neg-ladder').innerHTML = (plan.ladder || []).length
      ? `<div class="neg-signals-head">If you end up paying…</div>
         <table class="inv-table neg-ladder-table">
           <thead><tr><th class="num">Price</th><th class="num">You keep</th><th class="num">ROI</th><th>What that is</th></tr></thead>
           <tbody>${plan.ladder.map(negRungHtml).join('')}</tbody>
         </table>`
      : '';

    $('neg-messages').innerHTML = (plan.messages || []).length
      ? `<div class="neg-signals-head">What to say</div>${plan.messages.map(negMessageHtml).join('')}`
      : '<p class="neg-nomessage">No message drafted for this one on purpose — there is no offer here that both makes you money and gets a reply. Sending one anyway is how a bad deal gets talked into.</p>';

    $('neg-evidence').textContent = plan.evidenceNote
      ? `${plan.evidenceNote} Read the draft before you send it and make it sound like you — this app never messages anyone on your behalf.`
      : '';

    $('neg-messages').querySelectorAll('.neg-copy').forEach(btn =>
      btn.addEventListener('click', () => negCopy(btn)));

    $('neg-overlay')?.classList.remove('hidden');
  }

  function tile(label, value, sub, cls) {
    return `<div class="neg-tile${cls ? ` neg-tile-${cls}` : ''}">
        <span class="neg-tile-label">${esc(label)}</span>
        <strong class="neg-tile-value">${value}</strong>
        ${sub ? `<span class="neg-tile-sub">${sub}</span>` : ''}
      </div>`;
  }

  function negRungHtml(rung) {
    const tone = NEG_TONES[rung.tone] || NEG_TONES.thin;
    const tags = [rung.isOpening ? 'your opener' : '', rung.isCeiling ? 'your ceiling' : '',
                  rung.isAsk ? 'their ask' : ''].filter(Boolean)
      .map(t => `<span class="neg-tag">${t}</span>`).join('');

    return `
      <tr class="neg-rung neg-rung-${tone.cls}">
        <td class="num"><strong>${moneyExact(rung.price)}</strong>${tags}</td>
        <td class="num neg-rung-net">${moneyExact(rung.netProfit)}</td>
        <td class="num">${rung.roiPercent != null ? `${Math.round(rung.roiPercent)}%` : '∞'}</td>
        <td><span class="neg-tone neg-tone-${tone.cls}">${tone.label}</span> <span class="neg-rung-label">${esc(rung.label)}</span></td>
      </tr>`;
  }

  // Editable on purpose. A message that reads like a form letter gets treated like one, and the
  // seller's own wording closes deals that a template doesn't.
  function negMessageHtml(msg) {
    const rows = Math.min(12, Math.max(4, (msg.text || '').split('\n').length + 2));
    return `
      <div class="neg-message">
        <div class="neg-message-head">
          <div>
            <strong>${esc(msg.label)}</strong>
            <span class="neg-message-when">${esc(msg.when)}</span>
          </div>
          <button class="btn btn-secondary small neg-copy" type="button" data-id="${esc(msg.id)}">Copy</button>
        </div>
        <textarea class="neg-message-text" rows="${rows}" spellcheck="true">${esc(msg.text)}</textarea>
      </div>`;
  }

  // Copies whatever is in the box now, not the original draft — an edited message is the one being
  // sent, so it is the one that has to end up on the clipboard.
  async function negCopy(btn) {
    const text = btn.closest('.neg-message')?.querySelector('.neg-message-text')?.value || '';
    const original = btn.textContent;
    try {
      await navigator.clipboard.writeText(text);
      btn.textContent = 'Copied ✓';
    } catch {
      btn.textContent = 'Select and copy';
    }
    setTimeout(() => { btn.textContent = original; }, 2000);
  }

  // ── Roll the Dice ────────────────────────────────────────────────────────
  // The board every other panel can't produce: the seller types nothing, the server sweeps whole
  // categories of sold history, and what comes back is what to buy, for how much, and where.
  //
  // A roll is minutes of server work across four external systems, so it borrows the local panel's
  // never-throw fetch contract (localFetchJson) — a roll that will never come back has to stop
  // looking like one that is still working.
  const DICE_TIMEOUT_MS = 10 * 60 * 1000;

  let diceData = null;
  let diceNextSeed = null;
  let diceRolling = false;
  // The rows currently drawn, in the order they were drawn — the actions on a row need the whole
  // play, and sorting/filtering means a row's position is not its position in diceData.plays.
  let diceRows = [];
  // Searches Deal Radar is already watching, so re-rolling into the same product says "already
  // watching" instead of offering to spend a second of the twelve slots on it. Keyed the way the
  // server compares them — see PlayWatchBuilder.SameSearch.
  let diceWatchedSearches = new Set();

  const searchKey = q => (q || '').trim().replace(/\s+/g, ' ').toLowerCase();

  const DICE_TIERS = {
    jackpot: { label: '🎰 Jackpot', cls: 'jackpot' },
    strong:  { label: '💰 Strong play', cls: 'strong' },
    target:  { label: '🎯 Target price', cls: 'target' },
    thin:    { label: '⚠️ Thin margin', cls: 'thin' },
    watch:   { label: '👀 Watch — thin data', cls: 'watch' },
    pass:    { label: '✕ Pass', cls: 'pass' },
  };

  const DICE_WATCHING_LABEL = '🔔 Deal Radar is watching';

  function bindRollTheDice() {
    // The dashboard band: one click has to produce a board, not a form to fill in.
    on('btn-roll-dice', 'click', () => {
      showOpportunitySection();
      $('dice-results')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      rollTheDice(null);
    });
    on('dice-roll-btn', 'click', () => rollTheDice(null));
    on('dice-again-btn', 'click', () => rollTheDice(diceNextSeed));
    on('dice-only-buyable', 'change', renderDiceBoard);
    on('dice-min-100', 'change', renderDiceBoard);
    on('dice-sort', 'change', renderDiceBoard);
    on('dice-fast-only', 'change', renderDiceBoard);
    on('dice-zip-input', 'keydown', e => { if (e.key === 'Enter') rollTheDice(null); });

    // Same remembered zip and radius the local scan uses — a seller types their zip code once.
    const zip = localStorage.getItem('fbZip');
    const radius = localStorage.getItem('fbRadius');
    if (zip && $('dice-zip-input')) $('dice-zip-input').value = zip;
    if (radius && $('dice-radius-select')) {
      const select = $('dice-radius-select');
      if ([...select.options].some(o => o.value === radius)) select.value = radius;
    }
  }

  function setDiceStatus(message, retry) {
    const el = $('dice-status');
    if (!el) return;
    if (!message) { el.innerHTML = ''; return; }
    el.innerHTML = esc(message) +
      (retry ? ' <button type="button" class="btn btn-secondary small dice-retry-btn">Try again</button>' : '');
    el.querySelector('.dice-retry-btn')?.addEventListener('click', () => rollTheDice(null));
  }

  // seed === null means "a fresh random roll"; passing the previous response's nextSeed is what
  // makes Roll again sweep categories this seller hasn't just seen.
  async function rollTheDice(seed) {
    if (diceRolling) return;

    const zip = $('dice-zip-input')?.value.trim() || '';
    const radius = $('dice-radius-select')?.value || '40';
    const niches = $('dice-niches-select')?.value || '4';
    if (zip) localStorage.setItem('fbZip', zip);
    localStorage.setItem('fbRadius', radius);

    // Whatever sites the seller ticked in Local Deals. Omitted when nothing is ticked (or the
    // picker hasn't loaded), which lets the server search everything reachable.
    const sources = selectedSourceIds();

    // "best" is the server's own ranking, which is the default — only the velocity sorts are worth
    // asking for, and the board can still be re-sorted client-side afterwards without re-rolling.
    const sort = $('dice-sort')?.value || 'best';

    const qs = `niches=${encodeURIComponent(niches)}&zip=${encodeURIComponent(zip)}` +
      `&radius=${encodeURIComponent(radius)}` +
      (sources.length ? `&sources=${encodeURIComponent(sources.join(','))}` : '') +
      (seed != null ? `&seed=${encodeURIComponent(seed)}` : '') +
      `&sort=${encodeURIComponent(sort)}`;

    const buttons = ['dice-roll-btn', 'dice-again-btn', 'btn-roll-dice'].map($).filter(Boolean);
    diceRolling = true;
    buttons.forEach(b => { b.disabled = true; });
    $('dice-results')?.classList.add('hidden');
    // Honest about the cost: a sweep, a real sold-comp lookup per product, then a supply search
    // per product. Minutes, not seconds — and Facebook loads a real browser page.
    setDiceStatus(`🎲 Rolling — sweeping ${niches} categories of eBay sold history, pricing the best ` +
      `products against real comps, then hunting for where to buy them` +
      `${zip ? ` near ${zip}` : ' on eBay'}. Give it a minute or two…`);

    const { data, error } = await localFetchJson(`/api/opportunities/roll-the-dice?${qs}`, DICE_TIMEOUT_MS);

    diceRolling = false;
    buttons.forEach(b => { b.disabled = false; });

    if (!data) {
      setDiceStatus(`The roll didn't complete. ${error}`, true);
      return;
    }
    renderDice(data);
  }

  function renderDice(data) {
    const wrap = $('dice-results');
    if (!wrap) return;

    diceNextSeed = data.nextSeed;
    $('dice-again-btn')?.classList.remove('hidden');

    if (data.status === 'error') {
      setDiceStatus(data.error || 'The roll came back with nothing usable.', true);
      return;
    }

    diceData = data;

    const swept = (data.niches || []).length;
    const summary = [
      data.jackpotCount
        ? `<strong class="fb-arb-hit">${data.jackpotCount} jackpot${data.jackpotCount === 1 ? '' : 's'}</strong>`
        : `<strong>${data.count}</strong> play${data.count === 1 ? '' : 's'}`,
      `across ${swept} categor${swept === 1 ? 'y' : 'ies'}`,
      data.fastCashCount ? `<strong class="fb-arb-hit">${data.fastCashCount} that ${data.fastCashCount === 1 ? 'pays' : 'pay'} back inside 3 weeks</strong>` : '',
      data.totalPotentialProfit > 0
        ? `${money(data.totalPotentialProfit)} of profit sitting in supply you can buy right now`
        : '',
    ].filter(Boolean).join(' · ');

    // The funnel, in full. What was thrown away matters as much as what survived: a short board is
    // the guards working, and this is where a seller can see that rather than assume the sweep
    // simply found nothing.
    $('dice-summary').innerHTML = summary +
      `<div class="fb-arb-sources">Mined ${data.compsScanned.toLocaleString()} sold comps → ` +
      `${data.productsConsidered} product${data.productsConsidered === 1 ? '' : 's'} worth a look → ` +
      `${data.productsPriced} priced against real comps → ${data.productsSourced} checked for supply` +
      `. ` +
      `${data.productsDropped ? `${data.productsDropped} dropped — too little sold history, or two reads of it that disagreed. ` : ''}` +
      `${data.supplyRejected ? `${data.supplyRejected} cheap listing${data.supplyRejected === 1 ? '' : 's'} rejected as parts or accessories rather than the product. ` : ''}` +
      `Roll #${data.seed} · ${data.rollsToCoverEverything} rolls covers all ${data.nichesInUniverse} categories.</div>`;

    const warn = $('dice-warning');
    if (warn) {
      warn.textContent = data.dataWarning || '';
      warn.classList.toggle('hidden', !data.dataWarning);
    }

    // Which categories were dug, and what each one gave up — a sweep that reports "no plays"
    // without saying where it looked can't be trusted or repeated.
    const chips = $('dice-niche-chips');
    if (chips) {
      chips.innerHTML = (data.niches || []).map(n => {
        const detail = n.playsFound
          ? `${n.playsFound} play${n.playsFound === 1 ? '' : 's'}`
          : n.note ? esc(n.note)
          : `${n.productsFound} product${n.productsFound === 1 ? '' : 's'}, none made the board`;
        return `<span class="dice-chip${n.playsFound ? ' dice-chip-hit' : ''}">
                  <strong>${esc(n.label)}</strong> ${detail}
                  <span class="dice-chip-probe">${(n.probes || []).map(esc).join(', ')}</span>
                </span>`;
      }).join('');
    }

    // Which sourcing channels actually answered — an empty supply list has to be distinguishable
    // from a site that was never searched.
    const searched = [
      data.ebaySupplySearched ? 'eBay Buy It Now' : '',
      ...(data.sources || []).map(s => s.status === 'ok'
        ? `${s.label} (${s.count})`
        : `${s.label} — ${s.status === 'not_connected' ? 'not connected'
            : s.status === 'session_expired' ? 'session expired' : 'unavailable'}`),
    ].filter(Boolean);
    setDiceStatus(searched.length
      ? `Supply checked on: ${searched.join(' · ')}.`
      : 'No supply sites were searched — add a zip code to include local classifieds.');

    // What Deal Radar is already looking for. Its own call, failing on its own: if it doesn't
    // answer, the buttons still offer to create a watch and the server reports the duplicate — the
    // wrong wording for a moment, never a second watch.
    loadDiceWatchedSearches();

    renderDiceBoard();
    wrap.classList.remove('hidden');
  }

  async function loadDiceWatchedSearches() {
    const status = await fetch('/api/radar/status').then(r => r.json()).catch(() => null);
    if (!status) return;
    diceWatchedSearches = new Set((status.watches || []).map(w => searchKey(w.query)));
    renderDiceBoard();
  }

  // Sorting and filtering are pure views over the response already in hand — neither may re-run a
  // roll, which is minutes of work across four systems.
  /** What a play is worth: the live buy's net, or what buying at the target would net. */
  const cashOf = p => (p.netProfit != null ? p.netProfit : p.profitAtTarget) || 0;

  function renderDiceBoard() {
    const board = $('dice-board');
    if (!board || !diceData) return;

    const onlyBuyable = !!$('dice-only-buyable')?.checked;
    const fastOnly = !!$('dice-fast-only')?.checked;
    const sort = $('dice-sort')?.value || 'best';
    const all = diceData.plays || [];

    let rows = onlyBuyable ? all.filter(p => p.sources && p.sources.length) : all.slice();
    if (fastOnly) rows = rows.filter(p => p.speedTier === 'fast');

    // The $100 bar. Judged on the same figure the headline quotes — what the live buy nets, or what
    // buying at the target would net — so a row can't clear the bar in one place and fail it in
    // another. A play that nets $33 does not pay for finding, buying, listing and packing the thing.
    if ($('dice-min-100')?.checked) rows = rows.filter(p => cashOf(p) >= 100);

    // "best" is the order the server ranked them in — believability first — and is left alone.
    // The velocity sorts keep plays that can't be believed at the bottom, same rule the server uses.
    // The play's money: what the live buy nets, or what buying at the target would net.
    const cash = cashOf;
    const weak = p => p.tier === 'pass' || p.tier === 'no_data';
    const diceCmp = {
      // Highest return on the cash tied up. Plays that cannot be believed stay at the bottom, the
      // same rule the other sorts use, and net profit breaks a tie.
      roi: (a, b) => (weak(a) - weak(b))
        || ((a.roiPercent == null) - (b.roiPercent == null))
        || ((b.roiPercent - a.roiPercent) || (cash(b) - cash(a))) || 0,
      fastest: (a, b) => (weak(a) - weak(b))
        || ((a.daysToCash == null) - (b.daysToCash == null))
        || ((a.daysToCash - b.daysToCash) || (cash(b) - cash(a))) || 0,
      perday: (a, b) => (weak(a) - weak(b))
        || ((a.profitPerDay == null) - (b.profitPerDay == null))
        || ((b.profitPerDay - a.profitPerDay) || (cash(b) - cash(a))) || 0,
      profit: (a, b) => (weak(a) - weak(b)) || (cash(b) - cash(a)),
    }[sort];
    if (diceCmp) rows = rows.slice().sort(diceCmp);

    const shown = $('dice-shown');
    if (shown) {
      shown.textContent = rows.length === all.length
        ? `${rows.length} shown`
        : `${rows.length} of ${all.length} shown`;
    }

    // Kept so a row's actions can reach the whole play: sorting and filtering mean a row's position
    // on screen is not its position in diceData.plays.
    diceRows = rows;

    board.innerHTML = rows.length
      ? rows.map(dicePlayHtml).join('')
      : all.length
        ? `<p class="opportunity-empty">${fastOnly
            ? 'Nothing on this board turns your money around inside three weeks. Untick that filter to see the slower plays — or roll again for different categories.'
            : 'Nothing on this board is for sale anywhere right now. Untick the filter above and use “Watch for one” on the plays worth keeping — Deal Radar will say when one turns up. Or roll again for different categories.'}</p>`
        : '<p class="opportunity-empty">This roll found no product with enough sold history to stand behind. That is a real answer, not an error — roll again and the sweep moves on to different categories.</p>';

    board.querySelectorAll('.dice-hunt-btn').forEach(btn =>
      btn.addEventListener('click', () => huntPlayLocally(btn.dataset.query || '')));
    board.querySelectorAll('.dice-watch-btn').forEach(btn =>
      btn.addEventListener('click', () => watchPlay(btn)));
  }

  // Hands one play to Deal Radar and keeps it. A roll is minutes of work across four systems and
  // the next roll throws all of it away — this is the only thing on the board that outlives it, and
  // it is the tier the board has nothing else to offer: "nothing is for sale right now, buy under
  // $X". The keyword and that price become a saved search with the app's own jackpot bar on it.
  async function watchPlay(btn) {
    const play = diceRows[Number(btn.dataset.idx)];
    if (!play) return;

    const label = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Saving…';

    // safePost throws on a dropped connection and on an expired trial. Either way the button has to
    // come back — left saying "Saving…" it reads as a watch that exists and doesn't.
    let body = null;
    try {
      ({ body } = await safePost('/api/opportunities/watch-play', {
        product: play.product,
        searchQuery: play.searchQuery,
        targetBuyPrice: play.targetBuyPrice,
        maxBuyPrice: play.maxBuyPrice,
        soldCompCount: play.soldCompCount,
        terapeakCompCount: play.terapeakCompCount,
        confidenceScore: play.confidenceScore,
        // Where the roll looked, so the watch looks there too rather than somewhere never chosen.
        zipCode: $('dice-zip-input')?.value.trim() || '',
        radiusMiles: parseInt($('dice-radius-select')?.value || '40', 10),
        sources: selectedSourceIds().join(','),
      }));
    } catch (e) {
      body = { ok: false, error: errorText(e, 'That couldn\'t be saved as a watch.') };
    }

    if (!body?.ok) {
      btn.disabled = false;
      btn.textContent = label;
      toast(body?.error || 'That couldn\'t be saved as a watch.', { kind: 'warning', title: 'Not watching' });
      return;
    }

    // Remembered as well as re-labelled: re-sorting the board redraws every row from scratch, and a
    // button that forgets on a sort offers to create the watch a second time.
    diceWatchedSearches.add(searchKey(play.searchQuery));
    btn.classList.add('is-watching');
    btn.textContent = DICE_WATCHING_LABEL;

    const openRadar = { label: 'Open Deal Radar', onClick: () => showRadarSection() };
    if (body.alreadyWatching) {
      toast(`“${body.watch.name}” was already on the radar — nothing new was created.`,
        { kind: 'info', title: 'Already watching', action: openRadar });
    } else if (!body.radarRunning) {
      toast('Saved. Switch on “Watch in the background” in Deal Radar and it starts looking.',
        { kind: 'info', title: 'One more step', action: openRadar });
    } else {
      toastOk(`Deal Radar will keep looking for one at ${moneyExact(play.targetBuyPrice)} or less, and ping you when one turns up.`,
        { title: 'Watching', action: openRadar });
    }
  }

  function dicePlayHtml(play, index) {
    const tier = DICE_TIERS[play.tier] || DICE_TIERS.watch;
    // A live buy shows what it actually nets; a target shows what buying at the target would net.
    const live = play.netProfit != null;
    const headline = live ? play.netProfit : play.profitAtTarget;
    const headlineNote = live
      ? `net after fees, buying at ${moneyExact(play.bestBuyPrice)}`
      : play.targetBuyPrice > 0
        ? `net if you buy it at ${moneyExact(play.targetBuyPrice)}`
        // No price clears the jackpot bar, so the honest headline is what's left at a cost of
        // nothing — quoting "buy it at $0.00" would read as a bug.
        : `net even if it were free — break even is ${moneyExact(play.maxBuyPrice)}`;

    const facts = [
      // The number a reseller reads first: what it actually goes for. Everything else on the row is
      // arithmetic derived from it, so it gets the emphasis rather than sitting in a run of facts.
      play.ebayExpectedSale != null
        ? `<span class="sells-for">SELLS FOR: <strong>${money(play.ebayExpectedSale)}</strong></span>` : '',
      `Break even at <strong>${moneyExact(play.maxBuyPrice)}</strong>`,
      play.targetBuyPrice > 0 ? `Target buy <strong>${moneyExact(play.targetBuyPrice)}</strong>` : '',
      play.roiPercent != null ? `${Math.round(play.roiPercent)}% ROI` : '',
      // The wait, and what the money earns per day of it — the difference between a flip and a
      // shelf. Rendered as a badge so a "dead money" play can't read like a fast one.
      play.daysToCash != null
        ? `<span class="speed-badge speed-${(SPEED_TIERS[play.speedTier] || SPEED_TIERS.unknown).cls}" title="${esc(play.speedNote || '')}">` +
          `~${play.daysToCash}d to cash${play.profitPerDay > 0 ? ` · ${perDay(play.profitPerDay)}` : ''}</span>`
        : '',
    ].filter(Boolean).join(' · ');

    const evidence = [
      `${play.soldCompCount} sold comp${play.soldCompCount === 1 ? '' : 's'}`,
      play.confidenceLevel ? esc(play.confidenceLevel) : '',
      play.liquidityLevel ? esc(play.liquidityLevel) : '',
      play.estimatedMonthlySales > 0 ? `~${Math.round(play.estimatedMonthlySales)} sold/month` : '',
    ].filter(Boolean).join(' · ');

    const sources = (play.sources || []).map(src => {
      const good = src.netProfit != null && src.netProfit > 0;
      const meta = [
        src.distanceMiles != null ? `${src.distanceMiles} mi` : '',
        src.location ? esc(src.location) : '',
        src.postedAgo ? esc(src.postedAgo) : '',
      ].filter(Boolean).join(' · ');
      return `<div class="dice-source">
                <span class="local-badge local-badge-${esc(src.source)}">${esc(src.sourceLabel || src.source)}</span>
                <a class="dice-source-title" href="${esc(src.url)}" target="_blank" rel="noopener">${esc(src.title)} ↗</a>
                <span class="dice-source-buy">${moneyExact(src.buyPrice)}</span>
                <span class="dice-source-net ${good ? 'good' : 'bad'}">${src.netProfit != null ? `${good ? '+' : ''}${money(src.netProfit)} net` : '—'}</span>
                <span class="dice-source-meta">${meta}</span>
              </div>`;
    }).join('');

    // eBay's own sold-listing search for the same keyword: the seller can check the comps behind
    // the number themselves, with no API call and no trust required.
    const soldUrl = `https://www.ebay.com/sch/i.html?_nkw=${encodeURIComponent(play.searchQuery || play.product)}&LH_Sold=1&LH_Complete=1`;

    // Whether this play can be kept is the SERVER's answer (see PlayWatchBuilder.CanWatch) — the
    // board never re-derives the evidence bar, or the two would drift apart and the button would
    // start offering something the endpoint refuses.
    const watching = diceWatchedSearches.has(searchKey(play.searchQuery));
    const watchBtn = play.canWatch
      ? watching
        ? `<button class="btn btn-ghost small dice-watch-btn is-watching" type="button" disabled>${DICE_WATCHING_LABEL}</button>`
        : `<button class="btn btn-secondary small dice-watch-btn" type="button" data-idx="${index}">🔔 Watch for one at ${moneyExact(play.targetBuyPrice)}</button>`
      : '';

    // Why not, but only on a row where watching was the only thing left to do. On a row with live
    // supply the seller has somewhere to click, and on a thin row the tier note above already says
    // the evidence is thin — repeating it here is noise on the rows that need it least.
    const watchRefusal = !play.canWatch && play.watchRefusal && !(play.sources && play.sources.length)
      ? `<span class="dice-watch-refusal">🔕 ${esc(play.watchRefusal)}</span>`
      : '';

    return `
      <article class="dice-play dice-play-${tier.cls}">
        <div class="dice-play-rank">${index + 1}</div>
        ${play.imageUrl
          ? `<img class="dice-play-thumb" src="${esc(play.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" />`
          : '<div class="dice-play-thumb dice-play-thumb-empty">📦</div>'}
        <div class="dice-play-body">
          <div class="dice-play-head">
            <span class="dice-tier dice-tier-${tier.cls}">${tier.label}</span>
            <span class="dice-play-niche">${esc(play.nicheLabel)}</span>
          </div>
          <h4 class="dice-play-title">${esc(play.product)}</h4>
          <div class="dice-play-money">
            <span class="dice-play-profit ${headline > 0 ? 'good' : 'bad'}">${money(headline)}</span>
            <span class="dice-play-profit-note">${headlineNote}</span>
          </div>
          <div class="dice-play-facts">${facts}</div>
          <div class="dice-play-note">${esc(play.tierNote)}</div>
          <div class="dice-play-evidence">${evidence}${play.disagreementMessage ? ` <span class="fb-arb-flag" title="${esc(play.disagreementMessage)}">⚠</span>` : ''}</div>
          <div class="dice-play-where">${esc(play.whereToLook)}</div>
          ${sources ? `<div class="dice-sources">${sources}</div>` : ''}
          <div class="dice-play-actions">
            <button class="btn btn-secondary small dice-hunt-btn" type="button" data-query="${esc(play.searchQuery)}">📍 Hunt this locally</button>
            ${watchBtn}
            <a class="btn btn-ghost small" href="${esc(soldUrl)}" target="_blank" rel="noopener">See the sold comps ↗</a>
            ${watchRefusal}
          </div>
        </div>
      </article>`;
  }

  // Hands the play straight to the local scan below — the roll says WHAT to buy, and Local Deals is
  // already the panel that finds every one of them near you and ranks them.
  function huntPlayLocally(query) {
    if (!query) return;
    const input = $('fb-query-input');
    if (input) input.value = query;
    const diceZip = $('dice-zip-input')?.value.trim() || '';
    if (diceZip && $('fb-zip-input')) $('fb-zip-input').value = diceZip;
    $('fb-arb-btn')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    runLocalArbitrage();
  }

  // Opening Settings from the top bar lands on whichever required step is still outstanding.
  async function openSetupWithPolicies(status) {
    if (status) {
      openSetup(status);
      if (isConnected) loadPolicies(false);
      return;
    }
    openSetupAt(hasAnthropicKey ? 'policies' : 'key');
  }

  async function showLogsSection() {
    hideOverlaySections();
    $('logs-section')?.classList.remove('hidden');
    $('logs-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setActiveNavItem('logs');
    markWorkspaceTabOpen('logs');
    await loadLogs();
  }

  async function showLicenseSection() {
    hideOverlaySections();
    $('license-section')?.classList.remove('hidden');
    $('license-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setActiveNavItem('license');
    markWorkspaceTabOpen('license');
    await loadLicenseStatus();
  }

  async function loadLicenseStatus() {
    const status = await fetch('/api/license/status').then(r => r.json()).catch(() => null);
    if (status) updateLicenseUI(status);
  }

  // ── Opportunity Finder ───────────────────────────────────────────────────
  function showOpportunitySection() {
    hideOverlaySections();
    $('opportunity-section')?.classList.remove('hidden');
    setActiveNavItem('opportunity');
    markWorkspaceTabOpen('opportunity');
    loadFacebookStatus();
    // Also loaded on its own, not only off the back of the Facebook status call: Craigslist is
    // searchable whether or not that call succeeds.
    loadLocalSources();
    loadLocalCategories();
    loadHighSellThrough();
    loadLowCompetition();
    loadPricingRecommendations();
    loadSeasonalDemand();
    // Opening this screen is the ask — a panel headed "here is what's for sale near you" that
    // shows nothing until you find a button is just a button. Once per session (see fbPicksLoaded);
    // Refresh is there for a second look, and it still never runs on a timer.
    loadFacebookPicks(false);
  }

  // ── Opportunity Finder insight cards ─────────────────────────────────────
  // The market-pulse cards. Each of these was a right-aligned column of numbers, which is a bar
  // chart nobody drew: five percentages down a card are five separate reads, and the one thing the
  // eye is good at — is this one twice that one? — was thrown away. One hue per card, because each
  // card is a single series; the bar length is the whole story and colouring it by size as well
  // would burn the only channel left on information already on screen.
  function renderInsightBars(elId, rows, emptyMsg, note) {
    const el = $(elId);
    if (!el) return;
    el.innerHTML = rows.length ? vizRankBars(rows, { note }) : `<p class="opportunity-empty">${emptyMsg}</p>`;
  }

  async function loadHighSellThrough() {
    try {
      const data = await fetch('/api/insights/high-sell-through').then(r => r.json());
      // Scaled 0–100, not to the best row on the board: sell-through is a rate, and stretching the
      // top one to a full bar would make a 40% category look like everything sells.
      renderInsightBars('insight-sell-through', (data.items || []).map(it => ({
        label: it.category,
        percent: it.sellThroughPercent,
        valueText: `${it.sellThroughPercent}%`,
        tone: 'solo',
        tip: `${it.category}\n${it.sellThroughPercent}% of comparable listings sold rather than sat`,
      })), 'Not enough priced categories yet — run some Opportunity Finder searches to build this up.',
        'Bars run 0–100%: the share of listings in that category that sold rather than sat.');
    } catch { /* leave loading state — non-critical */ }
  }

  async function loadLowCompetition() {
    try {
      const data = await fetch('/api/insights/low-competition').then(r => r.json());
      const items = data.items || [];
      // Here the bar IS the competition, so a short bar is the good news. Scaled to the busiest
      // category on the card, because "few listings" only means anything next to "many".
      const busiest = Math.max(1, ...items.map(it => it.activeListings || 0));
      renderInsightBars('insight-low-competition', items.map(it => ({
        label: it.category,
        percent: ((it.activeListings || 0) / busiest) * 100,
        valueText: `${it.activeListings} listed`,
        tone: 'solo',
        tip: `${it.category}\n${it.activeListings} active listings to compete with\n${it.sellThroughPercent}% sell-through`,
      })), 'Not enough priced categories yet — run some Opportunity Finder searches to build this up.',
        'Bar length is how many listings you would be up against — shorter is less competition.');
    } catch { /* leave loading state — non-critical */ }
  }

  async function loadPricingRecommendations() {
    try {
      const data = await fetch('/api/insights/pricing-recommendations').then(r => r.json());
      renderInsightBars('insight-pricing-recs', (data.items || []).map(it => ({
        label: it.title,
        href: it.listingUrl,
        delta: it.deltaPercent,
        deltaScale: 40,
        valueText: `${it.deltaPercent > 0 ? '+' : ''}${it.deltaPercent}%`,
        tip: `${it.title}\n$${it.currentPrice.toFixed(2)} → $${it.suggestedPrice.toFixed(2)}\n${it.deltaPercent > 0 ? 'Priced under' : 'Priced over'} what the market paid`,
      })), 'No pricing gaps found yet in your active listings against cached market data.',
        'Right of centre is room to raise the price; left of centre is a price the market is not paying.');
    } catch { /* leave loading state — non-critical */ }
  }

  async function loadSeasonalDemand() {
    try {
      const data = await fetch('/api/insights/seasonal-demand').then(r => r.json());
      const el = $('insight-seasonal');
      if (!el) return;
      const cur = data.current, next = data.upcoming;
      el.innerHTML = `
        <div class="opportunity-insight-row"><span class="opportunity-insight-label">${esc(cur.monthName)} (now)</span></div>
        <p class="opportunity-empty" style="margin:-4px 0 8px">${cur.categories.map(esc).join(', ')}</p>
        <div class="opportunity-insight-row"><span class="opportunity-insight-label">${esc(next.monthName)} (upcoming)</span></div>
        <p class="opportunity-empty" style="margin:-4px 0 0">${next.categories.map(esc).join(', ')}</p>`;
    } catch { /* leave loading state — non-critical */ }
  }

  function renderUnderpricedCard(items) {
    const top = items.filter(it => it.isUnderpriced).sort((a, b) => (b.profitPercent ?? 0) - (a.profitPercent ?? 0)).slice(0, 5);
    const best = Math.max(1, ...top.map(it => it.profitPercent ?? 0));
    renderInsightBars('insight-underpriced', top.map(it => ({
      label: it.title,
      href: it.url,
      percent: ((it.profitPercent ?? 0) / best) * 100,
      valueText: `+${it.profitPercent}%`,
      tone: 'solo',
      tip: `${it.title}\n+${it.profitPercent}% against what this normally sells for`,
    })), 'No underpriced auctions in this search — try a broader keyword.',
      'Bars are relative to the best find in this search, not to a fixed scale.');
  }

  function closeOpportunitySection() {
    closeWorkspacePage('opportunity');
  }

  // ── Inventory Health ─────────────────────────────────────────────────────
  // The one screen in this app that looks at inventory the seller ALREADY owns: every live eBay
  // listing priced against real sold comps, checked against what they paid, and given a price that
  // both moves it and clears cost. See InventoryHealthAnalyzer.cs for the judgement rules and
  // ScanInventoryHealthAsync in Program.cs for the orchestration.
  let invScan     = null;   // the last InventoryHealthResult, kept so filtering never re-scans
  let invSelected = new Set();   // listing IDs ticked for repricing
  let invCosts    = new Map();   // listingId -> CostBasisEntry, so an edit re-renders without a refetch

  function showInventorySection() {
    hideOverlaySections();
    $('inventory-section')?.classList.remove('hidden');
    setActiveNavItem('inventory');
    markWorkspaceTabOpen('inventory');
    loadCostBasis();
  }

  function closeInventorySection() {
    closeWorkspacePage('inventory');
  }

  function bindInventoryHealth() {
    on('inv-scan-btn', 'click', runInventoryScan);
    on('inv-close', 'click', closeInventorySection);
    on('inv-home', 'click', goHome);
    // Filtering is a pure view over the result already in hand — changing it must never re-run a
    // scan that costs eBay calls and comp lookups.
    on('inv-verdict-filter', 'change', renderInventoryRows);
    on('inv-select-all', 'change', toggleSelectAllReprice);
    on('inv-preview-btn', 'click', () => submitReprice(true));
    on('inv-apply-btn', 'click', openRepriceConfirm);
    on('inv-confirm-cancel', 'click', () => $('inv-confirm-overlay')?.classList.add('hidden'));
    on('inv-confirm-go', 'click', () => {
      $('inv-confirm-overlay')?.classList.add('hidden');
      submitReprice(false);
    });
  }

  async function loadCostBasis() {
    try {
      const entries = await fetch('/api/inventory/cost-basis').then(r => r.json());
      invCosts = new Map((entries || []).map(e => [e.listingId || e.sku, e]));
    } catch { /* cost basis is optional — a scan without it still works, it just can't check floors */ }
  }

  async function runInventoryScan() {
    const btn = $('inv-scan-btn');
    const minDays  = $('inv-min-days')?.value || '0';
    const maxItems = $('inv-max-items')?.value || '120';

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    setInvStatus('Reading your live eBay listings…');
    $('inv-results').innerHTML = '<p class="opportunity-empty">Pricing each listing against sold comps — this takes a moment on a large inventory.</p>';

    try {
      const res  = await fetch(`/api/inventory/health?minDays=${minDays}&maxItems=${maxItems}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      invScan = data;
      invSelected.clear();
      renderInventoryScan();
    } catch (err) {
      invScan = null;
      $('inv-summary')?.classList.add('hidden');
      $('inv-bulk-bar')?.classList.add('hidden');
      $('inv-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setInvStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🔎 Scan My Listings'; }
    }
  }

  function renderInventoryScan() {
    const warn = $('inv-warning');

    if (invScan.status === 'ebay_unavailable') {
      $('inv-summary')?.classList.add('hidden');
      $('inv-bulk-bar')?.classList.add('hidden');
      warn?.classList.add('hidden');
      $('inv-results').innerHTML =
        '<p class="opportunity-empty">Your eBay account isn\'t connected, or the token has expired. Reconnect it in Settings, then scan again.</p>';
      setInvStatus('');
      return;
    }

    if (invScan.dataWarning) {
      warn.textContent = invScan.dataWarning;
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    renderInventorySummary(invScan.summary || {});
    renderInventoryRows();

    const s = invScan.summary || {};
    setInvStatus(
      `${invScan.itemsAnalyzed} of ${invScan.activeListings} active listings, ` +
      `${invScan.productsPriced} distinct product${invScan.productsPriced === 1 ? '' : 's'} priced` +
      (s.unknownAgeCount ? ` · ${s.unknownAgeCount} with no start date reported by eBay` : ''));
  }

  // The portfolio numbers. Deliberately leads with capital rather than with a count: "18 stale
  // listings" is a statistic, "$6,240 sitting in listings older than 90 days" is a decision.
  function renderInventorySummary(s) {
    const el = $('inv-summary');
    if (!el) return;

    const tiles = [
      { label: 'Capital tied up', value: money(s.totalCapitalTiedUp),
        sub: s.withCostBasis === s.listingsAnalyzed
          ? 'At what you paid'
          : `${s.withCostBasis} of ${s.listingsAnalyzed} at cost; the rest at market value`, tone: '' },
      { label: `Stuck ${90}+ days`, value: money(s.staleCapital),
        sub: `${s.staleCount} listing${s.staleCount === 1 ? '' : 's'}${s.medianDaysListed != null ? ` · median age ${s.medianDaysListed}d` : ''}`,
        tone: s.staleCount > 0 ? 'warn' : '' },
      { label: 'Dead capital', value: money(s.deadCapital),
        sub: `${s.deadCapitalCount} over 180 days, no watchers, above market`, tone: s.deadCapitalCount > 0 ? 'bad' : '' },
      { label: 'Priced above market', value: money(s.totalAboveMarket),
        sub: `${s.overpricedCount} listing${s.overpricedCount === 1 ? '' : 's'} 15%+ over comps`, tone: s.overpricedCount > 0 ? 'warn' : '' },
      { label: 'Left on the table', value: money(s.moneyLeftOnTable),
        sub: `${s.underpricedCount} listed below market — per sale`, tone: s.underpricedCount > 0 ? 'good' : '' },
      { label: 'Ready to reprice', value: String(s.repriceCandidates || 0),
        sub: s.projectedNetIfRepricedSells
          ? `${money(s.projectedNetIfRepricedSells)} net if they then sell`
          : 'Record cost basis to see net profit', tone: s.repriceCandidates > 0 ? 'good' : '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  const INV_VERDICTS = {
    underwater:   { label: '🌊 Underwater',   cls: 'inv-v-underwater' },
    dead_capital: { label: '🪦 Dead capital', cls: 'inv-v-dead' },
    stale:        { label: '🕸️ Stale',        cls: 'inv-v-stale' },
    overpriced:   { label: '⬆️ Overpriced',   cls: 'inv-v-over' },
    underpriced:  { label: '⬇️ Underpriced',  cls: 'inv-v-under' },
    selling:      { label: '🔁 Selling',      cls: 'inv-v-selling' },
    priced_right: { label: '✓ Priced right',  cls: 'inv-v-ok' },
    fresh:        { label: '🌱 Fresh',        cls: 'inv-v-ok' },
    no_data:      { label: '? No data',       cls: 'inv-v-nodata' },
  };

  function invFilterMatches(item, filter) {
    switch (filter) {
      case 'action':      return item.hasRecommendation;
      case 'stale':       return item.verdict === 'stale' || item.verdict === 'dead_capital';
      case 'selling':     return item.verdict === 'selling';
      case 'overpriced':  return item.verdict === 'overpriced';
      case 'underpriced': return item.verdict === 'underpriced';
      case 'underwater':  return item.verdict === 'underwater';
      case 'no_data':     return item.verdict === 'no_data';
      default:            return true;
    }
  }

  function renderInventoryRows() {
    if (!invScan) return;
    const filter = $('inv-verdict-filter')?.value || 'all';
    const rows = (invScan.items || []).filter(i => invFilterMatches(i, filter));
    const el = $('inv-results');

    if (rows.length === 0) {
      el.innerHTML = `<p class="opportunity-empty">${
        (invScan.items || []).length === 0
          ? 'No active listings came back from eBay for this filter.'
          : 'Nothing in your inventory matches that filter — which is good news.'}</p>`;
      $('inv-bulk-bar')?.classList.add('hidden');
      return;
    }

    el.innerHTML = `
      <table class="inv-table">
        <thead>
          <tr>
            <th class="inv-col-check"></th>
            <th>Listing</th>
            <th class="num">Age</th>
            <th class="num">Your price</th>
            <th class="num">Market</th>
            <th class="num">Gap</th>
            <th class="num">You paid</th>
            <th class="num" title="Break-even is where the sale stops losing money. Your floor is the lowest offer worth taking — set it in Settings → Fees &amp; Costs.">Break-even<div class="inv-th-sub">&amp; your floor</div></th>
            <th class="num">Suggested</th>
            <th>Verdict</th>
          </tr>
        </thead>
        <tbody>${rows.map(invRowHtml).join('')}</tbody>
      </table>`;

    el.querySelectorAll('.inv-check').forEach(cb => cb.addEventListener('change', onRepriceCheck));
    el.querySelectorAll('.inv-cost-input').forEach(inp => {
      inp.addEventListener('change', onCostBasisEdit);
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') inp.blur(); });
    });
    el.querySelectorAll('.inv-price-input').forEach(inp => inp.addEventListener('change', onSuggestedOverride));

    $('inv-bulk-bar')?.classList.remove('hidden');
    refreshSelectionNote();
  }

  function invRowHtml(item) {
    const v = INV_VERDICTS[item.verdict] || INV_VERDICTS.no_data;
    const gap = item.priceGapPercent;
    const gapCls = gap == null ? '' : gap >= 15 ? 'inv-gap-bad' : gap <= -10 ? 'inv-gap-good' : 'inv-gap-ok';
    // Only markdowns are tickable. A raise is a per-item judgement call (see SuggestPrice), and a
    // row with no recommendation has nothing to apply.
    const selectable = item.hasRecommendation && !item.requiresReview && item.listingId;
    const checked = invSelected.has(item.listingId) ? 'checked' : '';
    const cost = item.costBasis;

    const suggestedCell = item.suggestedPrice != null
      ? `<input class="inv-price-input" type="number" step="0.01" min="0.01"
                value="${Number(item.suggestedPrice).toFixed(2)}" data-id="${esc(item.listingId)}"
                title="Edit to override the suggested price" />
         <div class="inv-change ${item.suggestedChangePercent < 0 ? 'down' : 'up'}">${
           item.suggestedChangePercent > 0 ? '+' : ''}${Number(item.suggestedChangePercent ?? 0).toFixed(1)}%${
           item.requiresReview ? ' · review' : ''}${item.floorLimited ? ' · at floor' : ''}</div>`
      : '<span class="inv-dash">—</span>';

    return `
      <tr class="${item.verdict === 'dead_capital' ? 'inv-row-dead' : ''}">
        <td class="inv-col-check">${selectable
          ? `<input class="inv-check" type="checkbox" data-id="${esc(item.listingId)}" ${checked} />`
          : ''}</td>
        <td class="inv-cell-title">
          <div class="inv-title-row">
            ${item.imageUrl ? `<img class="inv-thumb" src="${esc(item.imageUrl)}" alt="" loading="lazy" />` : ''}
            <div>
              ${item.url
                ? `<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.title)}</a>`
                : esc(item.title)}
              <div class="inv-sub">${esc(item.sku || item.listingId)}${item.quantity > 1 ? ` · qty ${item.quantity}` : ''}${
                item.watchCount ? ` · ${item.watchCount} 👁` : ''}${
                item.pricedAs && item.pricedAs !== item.title ? ` · priced as "${esc(item.pricedAs)}"` : ''}</div>
            </div>
          </div>
        </td>
        <td class="num">${item.daysListed == null ? '<span class="inv-dash" title="eBay reported no start date">—</span>' : item.daysListed + 'd'}</td>
        <td class="num">${moneyExact(item.listPrice)}</td>
        <td class="num">${item.marketPrice != null
            ? `${moneyExact(item.marketPrice)}<div class="inv-sub">${item.soldCompCount + item.terapeakCompCount} comps${
                item.marketComparable === false ? ' · per unit' : ''}</div>`
            : '<span class="inv-dash">—</span>'}</td>
        <!-- A gap computed from a comparison that failed is not a fact about the listing, so it is
             struck through rather than shown as a finding. -->
        <td class="num ${item.marketComparable === false ? 'inv-gap-void' : gapCls}">${
          gap == null ? '<span class="inv-dash">—</span>'
          : item.marketComparable === false
            ? `<span title="Not comparable — see the verdict column">n/a</span>`
            : (gap > 0 ? '+' : '') + gap.toFixed(0) + '%'}</td>
        <td class="num">
          <input class="inv-cost-input" type="number" step="0.01" min="0" placeholder="cost"
                 value="${cost != null ? Number(cost).toFixed(2) : ''}"
                 data-id="${esc(item.listingId)}" data-sku="${esc(item.sku || '')}"
                 title="What you paid for this unit, all in. Sets the break-even floor." />
        </td>
        <!-- Break-even alone answers "am I losing money"; the floor answers "is this worth doing".
             A Best Offer arrives against the second number, so it belongs next to the first. -->
        <td class="num">${item.breakEvenPrice != null
            ? `${moneyExact(item.breakEvenPrice)}${item.minimumOfferPrice != null
                 && item.minimumOfferPrice > item.breakEvenPrice
                 ? `<div class="inv-sub inv-floor" title="Lowest offer worth accepting — ${
                      esc(invFloorBasis(item))}">floor ${moneyExact(item.minimumOfferPrice)}</div>`
                 : ''}`
            : '<span class="inv-dash">—</span>'}</td>
        <td class="num inv-cell-suggested">${suggestedCell}</td>
        <td class="inv-cell-verdict">
          <span class="inv-verdict ${v.cls}">${v.label}</span>
          <div class="inv-note">${esc(item.verdictNote)}</div>
          ${(item.signals || []).length ? `<div class="inv-signals">${item.signals.map(s => esc(s)).join(' ')}</div>` : ''}
        </td>
      </tr>`;
  }

  function invFloorBasis(item) {
    if (item.minimumOfferBasis === 'margin_target') return 'your minimum margin, from Fees & Costs';
    if (item.minimumOfferBasis === 'profit_target')
      return `keeps ${moneyExact(item.netProfitAtMinimumOffer ?? 0)} of profit, from Fees & Costs`;
    return 'break-even — set a minimum profit in Fees & Costs to raise it';
  }

  function invItemById(listingId) {
    return (invScan?.items || []).find(i => i.listingId === listingId) || null;
  }

  function onRepriceCheck(e) {
    const id = e.target.dataset.id;
    if (e.target.checked) invSelected.add(id); else invSelected.delete(id);
    refreshSelectionNote();
  }

  function toggleSelectAllReprice(e) {
    const filter = $('inv-verdict-filter')?.value || 'all';
    const on = e.target.checked;
    // Only what is actually on screen — a select-all that silently ticks rows behind a filter is
    // how someone reprices a listing they never looked at.
    (invScan?.items || [])
      .filter(i => invFilterMatches(i, filter) && i.hasRecommendation && !i.requiresReview && i.listingId)
      .forEach(i => { if (on) invSelected.add(i.listingId); else invSelected.delete(i.listingId); });
    document.querySelectorAll('.inv-check').forEach(cb => { cb.checked = invSelected.has(cb.dataset.id); });
    refreshSelectionNote();
  }

  function refreshSelectionNote() {
    const picked = [...invSelected].map(invItemById).filter(Boolean);
    const note = $('inv-selection-note');
    if (note) {
      note.textContent = picked.length === 0
        ? 'Nothing selected.'
        : `${picked.length} listing${picked.length === 1 ? '' : 's'} selected · average change ${
            (picked.reduce((sum, i) => sum + (i.suggestedChangePercent || 0), 0) / picked.length).toFixed(1)}%`;
    }
    const disabled = picked.length === 0;
    if ($('inv-preview-btn')) $('inv-preview-btn').disabled = disabled;
    if ($('inv-apply-btn'))   $('inv-apply-btn').disabled   = disabled;
  }

  // An overridden price is the seller's call, so it replaces the suggestion on the row it came
  // from rather than being validated away here — the server re-checks it against the break-even
  // either way, which is the check that actually matters.
  function onSuggestedOverride(e) {
    const item = invItemById(e.target.dataset.id);
    if (!item) return;
    const value = parseFloat(e.target.value);
    if (!isFinite(value) || value <= 0) {
      e.target.value = Number(item.suggestedPrice ?? item.listPrice).toFixed(2);
      return;
    }
    item.suggestedPrice = value;
    item.suggestedChangePercent = item.listPrice > 0
      ? Math.round((value - item.listPrice) / item.listPrice * 1000) / 10 : 0;
    const changeEl = e.target.parentElement?.querySelector('.inv-change');
    if (changeEl) {
      changeEl.textContent = `${item.suggestedChangePercent > 0 ? '+' : ''}${item.suggestedChangePercent.toFixed(1)}% · edited`;
      changeEl.className = `inv-change ${item.suggestedChangePercent < 0 ? 'down' : 'up'}`;
    }
    refreshSelectionNote();
  }

  async function onCostBasisEdit(e) {
    const listingId = e.target.dataset.id;
    const sku = e.target.dataset.sku || '';
    const raw = e.target.value.trim();

    try {
      if (raw === '') {
        await fetch(`/api/inventory/cost-basis?listingId=${encodeURIComponent(listingId)}&sku=${encodeURIComponent(sku)}`,
          { method: 'DELETE' });
        invCosts.delete(listingId);
      } else {
        const unitCost = parseFloat(raw);
        if (!isFinite(unitCost) || unitCost < 0) return;
        const entry = { listingId, sku, unitCost, inboundShipping: 0, note: '' };
        const res = await fetch('/api/inventory/cost-basis', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify([entry]),
        });
        if (!res.ok) throw new Error(await res.text());
        invCosts.set(listingId, entry);
      }
      // A cost basis changes the break-even, which changes the floor, which can change the
      // recommendation — so the row is re-derived by the server rather than patched here.
      setInvStatus('Cost saved — re-scan to recalculate break-even and suggested prices.');
    } catch (err) {
      setInvStatus(`Could not save that cost: ${errorText(err)}`);
    }
  }

  function openRepriceConfirm() {
    const picked = [...invSelected].map(invItemById).filter(Boolean);
    if (picked.length === 0) return;

    $('inv-confirm-list').innerHTML = picked.map(i => `
      <div class="inv-confirm-row">
        <span class="inv-confirm-title">${esc(i.title)}</span>
        <span class="inv-confirm-prices">${moneyExact(i.listPrice)} → <strong>${moneyExact(i.suggestedPrice)}</strong></span>
      </div>`).join('');
    const loss = $('inv-allow-loss');
    if (loss) loss.checked = false;
    $('inv-confirm-overlay')?.classList.remove('hidden');
  }

  async function submitReprice(dryRun) {
    const picked = [...invSelected].map(invItemById).filter(Boolean);
    if (picked.length === 0) return;

    const body = {
      items: picked.map(i => ({
        listingId: i.listingId, sku: i.sku, title: i.title,
        newPrice: i.suggestedPrice, currentPrice: i.listPrice,
        quantity: i.quantity, breakEvenPrice: i.breakEvenPrice,
      })),
      dryRun,
      confirmed: !dryRun,
      allowBelowBreakEven: !dryRun && !!$('inv-allow-loss')?.checked,
    };

    setInvStatus(dryRun ? 'Previewing…' : 'Repricing on eBay…');
    try {
      const res  = await fetch('/api/inventory/reprice', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'Repricing failed.');
      renderRepriceOutcome(data);
      if (!dryRun && data.applied > 0) {
        addActivity(`${data.applied} listing${data.applied === 1 ? '' : 's'} repriced on eBay`,
          'Prices updated from the Inventory Health scan.');
        // The scan is now stale for those rows by definition, so re-run it rather than leaving
        // the table showing prices that are no longer live.
        await runInventoryScan();
      }
    } catch (err) {
      setInvStatus(`Repricing failed: ${errorText(err)}`);
    }
  }

  function renderRepriceOutcome(data) {
    const parts = [];
    if (data.dryRun) parts.push(`Preview only — nothing sent to eBay. ${data.items.length} change${data.items.length === 1 ? '' : 's'} ready.`);
    else parts.push(`${data.applied} applied`);
    if (data.skipped) parts.push(`${data.skipped} skipped`);
    if (data.failed)  parts.push(`${data.failed} failed`);

    const problems = (data.items || []).filter(i => i.status === 'skipped' || i.status === 'failed');
    setInvStatus(parts.join(' · ') + (problems.length
      ? ' — ' + problems.map(p => `${p.title}: ${p.message}`).join('; ')
      : ''));
  }

  function setInvStatus(text) {
    const el = $('inv-status');
    if (el) el.textContent = text || '';
  }

  // ── Offers to Watchers ───────────────────────────────────────────────────
  // The warmest audience a seller gets for free: people who already found the item and hesitated.
  // eBay's Send Offer to Interested Buyers puts a private, time-limited discount in front of
  // exactly them, without moving the public price — so an offer nobody accepts costs nothing.
  // See WatcherOfferAdvisor.cs for how deep each offer goes and what stops it.
  let woScan     = null;   // last WatcherOfferResult, kept so filtering never re-scans
  let woSelected = new Set();

  function showOffersSection() {
    hideOverlaySections();
    $('offers-section')?.classList.remove('hidden');
    setActiveNavItem('offers');
    markWorkspaceTabOpen('offers');
  }

  function closeOffersSection() {
    closeWorkspacePage('offers');
  }

  function bindWatcherOffers() {
    on('wo-scan-btn', 'click', runOfferScan);
    on('wo-close', 'click', closeOffersSection);
    on('wo-home', 'click', goHome);
    on('inv-to-offers', 'click', () => { navigateTo('offers'); });
    // Filtering is a pure view over the scan already in hand — it must never re-run eBay calls.
    on('wo-filter', 'change', renderOfferRows);
    on('wo-select-all', 'change', toggleSelectAllOffers);
    on('wo-preview-btn', 'click', () => submitOffers(true));
    on('wo-send-btn', 'click', openOfferConfirm);
    on('wo-confirm-cancel', 'click', () => $('wo-confirm-overlay')?.classList.add('hidden'));
    on('wo-confirm-go', 'click', () => {
      $('wo-confirm-overlay')?.classList.add('hidden');
      submitOffers(false);
    });
    on('wo-message', 'input', updateOfferMessageCount);
  }

  async function runOfferScan() {
    const btn = $('wo-scan-btn');
    const minWatchers = $('wo-min-watchers')?.value || '1';
    const maxItems    = $('wo-max-items')?.value || '120';
    const minProfit   = Math.max(0, parseFloat($('wo-min-profit')?.value || '0') || 0);

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    setWoStatus('Reading your live listings and their watchers…');
    $('wo-results').innerHTML = '<p class="opportunity-empty">Counting watchers and pricing each listing against sold comps — this takes a moment on a large inventory.</p>';

    try {
      const res  = await fetch(`/api/offers/watchers?minWatchers=${minWatchers}&maxItems=${maxItems}&minProfit=${minProfit}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      woScan = data;
      woSelected.clear();
      renderOfferScan();
    } catch (err) {
      woScan = null;
      $('wo-summary')?.classList.add('hidden');
      $('wo-bulk-bar')?.classList.add('hidden');
      $('wo-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setWoStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '👁 Find My Watchers'; }
    }
  }

  function renderOfferScan() {
    const warn = $('wo-warning');

    if (woScan.status === 'ebay_unavailable') {
      $('wo-summary')?.classList.add('hidden');
      $('wo-bulk-bar')?.classList.add('hidden');
      warn?.classList.add('hidden');
      $('wo-results').innerHTML =
        '<p class="opportunity-empty">Your eBay account isn\'t connected, or the token has expired. Reconnect it in Settings, then scan again.</p>';
      setWoStatus('');
      return;
    }

    // A missing permission is not a failure of the scan: the watcher counts and the offers below
    // are all real, and only sending is blocked — so the board still renders behind the banner.
    const notes = [];
    if (woScan.needsReconnect) notes.push(woScan.eligibilityNote || 'Reconnect eBay to send offers.');
    else if (woScan.eligibilityNote) notes.push(woScan.eligibilityNote);
    if (woScan.dataWarning) notes.push(woScan.dataWarning);

    if (notes.length) {
      warn.textContent = notes.join(' ');
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    renderOfferSummary(woScan.summary || {});
    renderOfferRows();

    const s = woScan.summary || {};
    setWoStatus(
      `${woScan.itemsAnalyzed} watched listing${woScan.itemsAnalyzed === 1 ? '' : 's'} of ${woScan.activeListings} active · ` +
      `${s.totalWatchers} watcher${s.totalWatchers === 1 ? '' : 's'} in total` +
      (woScan.eligibilityChecked ? ' · eligibility confirmed with eBay' : ' · eligibility not confirmed'));
  }

  // Leads with the audience, not the listing count: "9 listings" is a statistic, "47 people are
  // watching your listings right now" is a reason to click send.
  function renderOfferSummary(s) {
    const el = $('wo-summary');
    if (!el) return;

    const tiles = [
      { label: 'People watching', value: String(s.totalWatchers || 0),
        sub: `${s.listingsWithWatchers || 0} listing${s.listingsWithWatchers === 1 ? '' : 's'} with an audience`,
        tone: s.totalWatchers > 0 ? 'good' : '' },
      { label: 'Offers ready', value: String(s.readyToSend || 0),
        sub: s.readyToSend ? `reaching ${s.watchersReachable} watcher${s.watchersReachable === 1 ? '' : 's'}` : 'Nothing to send yet',
        tone: s.readyToSend > 0 ? 'good' : '' },
      { label: 'Average discount', value: `${Number(s.averageDiscountPercent || 0).toFixed(1)}%`,
        sub: 'Sized per listing, never below your floor', tone: '' },
      { label: 'If one of each is taken', value: money(s.revenueIfOneEachAccepts),
        sub: s.netIfOneEachAccepts ? `${money(s.netIfOneEachAccepts)} net after fees` : 'Record cost basis to see net profit',
        tone: s.revenueIfOneEachAccepts > 0 ? 'good' : '' },
      { label: 'Margin you\'d give up', value: money(s.marginGivenUpIfAllAccept),
        sub: 'Only if every offer is accepted — otherwise nothing', tone: '' },
      { label: 'Held back', value: String((s.blockedByFloor || 0) + (s.notEligible || 0)),
        sub: `${s.blockedByFloor || 0} under your floor · ${s.notEligible || 0} not eligible on eBay`,
        tone: (s.blockedByFloor || 0) > 0 ? 'warn' : '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  const WO_VERDICTS = {
    ready:        { label: '✉️ Ready to send', cls: 'wo-v-ready' },
    no_room:      { label: '🛑 Under my floor', cls: 'inv-v-underwater' },
    not_eligible: { label: '⛔ Not eligible',   cls: 'inv-v-nodata' },
    no_watchers:  { label: '👤 No watchers',   cls: 'inv-v-nodata' },
    not_ready:    { label: '? No price',       cls: 'inv-v-nodata' },
  };

  function woFilterMatches(item, filter) {
    switch (filter) {
      case 'ready':        return item.canSend;
      case 'no_room':      return item.verdict === 'no_room';
      case 'not_eligible': return item.verdict === 'not_eligible';
      default:             return true;
    }
  }

  function renderOfferRows() {
    if (!woScan) return;
    const filter = $('wo-filter')?.value || 'ready';
    const rows = (woScan.items || []).filter(i => woFilterMatches(i, filter));
    const el = $('wo-results');

    if (rows.length === 0) {
      const total = (woScan.items || []).length;
      el.innerHTML = `<p class="opportunity-empty">${
        total === 0
          ? 'No listings with watchers came back from eBay. Watchers build up as a listing gets views — check again in a few days, or lower the watcher filter.'
          : 'Nothing matches that filter. Switch to "Everything" to see why each listing was held back.'}</p>`;
      $('wo-bulk-bar')?.classList.add('hidden');
      return;
    }

    el.innerHTML = `
      <table class="inv-table">
        <thead>
          <tr>
            <th class="inv-col-check"></th>
            <th>Listing</th>
            <th class="num">Watching</th>
            <th class="num">Age</th>
            <th class="num">Your price</th>
            <th class="num">Market</th>
            <th class="num">Offer %</th>
            <th class="num">They pay</th>
            <th class="num">Your net</th>
            <th>Verdict</th>
          </tr>
        </thead>
        <tbody>${rows.map(woRowHtml).join('')}</tbody>
      </table>`;

    el.querySelectorAll('.wo-check').forEach(cb => cb.addEventListener('change', onOfferCheck));
    el.querySelectorAll('.wo-discount-input').forEach(inp => {
      inp.addEventListener('change', onOfferDiscountEdit);
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') inp.blur(); });
    });

    $('wo-bulk-bar')?.classList.remove('hidden');
    refreshOfferSelectionNote();
  }

  function woRowHtml(item) {
    const v = WO_VERDICTS[item.verdict] || WO_VERDICTS.no_watchers;
    const checked = woSelected.has(item.listingId) ? 'checked' : '';

    const discountCell = item.discountPercent != null
      ? `<input class="wo-discount-input" type="number" step="1" min="5" max="25"
                value="${Number(item.discountPercent)}" data-id="${esc(item.listingId)}"
                title="Edit to override the suggested discount. eBay's minimum is 5%." />
         <div class="inv-change down">${item.floorLimited ? 'at floor' : 'suggested'}</div>`
      : '<span class="inv-dash">—</span>';

    return `
      <tr class="${item.canSend ? '' : 'wo-row-muted'}">
        <td class="inv-col-check">${item.canSend
          ? `<input class="wo-check" type="checkbox" data-id="${esc(item.listingId)}" ${checked} />`
          : ''}</td>
        <td class="inv-cell-title">
          <div class="inv-title-row">
            ${item.imageUrl ? `<img class="inv-thumb" src="${esc(item.imageUrl)}" alt="" loading="lazy" />` : ''}
            <div>
              ${item.url
                ? `<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.title)}</a>`
                : esc(item.title)}
              <div class="inv-sub">${esc(item.sku || item.listingId)}${item.quantity > 1 ? ` · qty ${item.quantity}` : ''}${
                item.costBasis != null ? ` · paid ${moneyExact(item.costBasis)}` : ' · no cost recorded'}</div>
            </div>
          </div>
        </td>
        <td class="num"><span class="wo-watchers ${item.watchCount >= 10 ? 'hot' : ''}">${item.watchCount} 👁</span></td>
        <td class="num">${item.daysListed == null ? '<span class="inv-dash" title="eBay reported no start date">—</span>' : item.daysListed + 'd'}</td>
        <td class="num">${moneyExact(item.listPrice)}</td>
        <td class="num">${item.marketPrice != null && item.marketComparable !== false
            ? `${moneyExact(item.marketPrice)}<div class="inv-sub">${item.soldCompCount + item.terapeakCompCount} comps</div>`
            : '<span class="inv-dash">—</span>'}</td>
        <td class="num inv-cell-suggested">${discountCell}</td>
        <td class="num">${item.offerPrice != null
            ? `<strong>${moneyExact(item.offerPrice)}</strong><div class="inv-sub">${item.marginGivenUp != null ? `−${moneyExact(item.marginGivenUp)}` : ''}</div>`
            : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${item.netProfitAtOffer != null
            ? `<span class="${item.netProfitAtOffer > 0 ? 'inv-gap-good' : 'inv-gap-bad'}">${moneyExact(item.netProfitAtOffer)}</span>${
                item.netProfitAtListPrice != null ? `<div class="inv-sub">${moneyExact(item.netProfitAtListPrice)} at full price</div>` : ''}`
            : '<span class="inv-dash" title="Record what you paid in Inventory Health to see net profit">—</span>'}</td>
        <td class="inv-cell-verdict">
          <span class="inv-verdict ${v.cls}">${v.label}</span>
          <div class="inv-note">${esc(item.verdictNote)}</div>
          ${(item.signals || []).length ? `<div class="inv-signals">${item.signals.map(s => esc(s)).join(' ')}</div>` : ''}
        </td>
      </tr>`;
  }

  function woItemById(listingId) {
    return (woScan?.items || []).find(i => i.listingId === listingId) || null;
  }

  function onOfferCheck(e) {
    const id = e.target.dataset.id;
    if (e.target.checked) woSelected.add(id); else woSelected.delete(id);
    refreshOfferSelectionNote();
  }

  function toggleSelectAllOffers(e) {
    const filter = $('wo-filter')?.value || 'ready';
    const on = e.target.checked;
    // Only what is on screen — a select-all that ticks rows hidden behind a filter is how someone
    // sends a discount on a listing they never looked at.
    (woScan?.items || [])
      .filter(i => woFilterMatches(i, filter) && i.canSend)
      .forEach(i => { if (on) woSelected.add(i.listingId); else woSelected.delete(i.listingId); });
    document.querySelectorAll('.wo-check').forEach(cb => { cb.checked = woSelected.has(cb.dataset.id); });
    refreshOfferSelectionNote();
  }

  function refreshOfferSelectionNote() {
    const picked = [...woSelected].map(woItemById).filter(Boolean);
    const note = $('wo-selection-note');
    if (note) {
      if (picked.length === 0) note.textContent = 'Nothing selected.';
      else {
        const watchers = picked.reduce((sum, i) => sum + (i.watchCount || 0), 0);
        const avg = picked.reduce((sum, i) => sum + (i.discountPercent || 0), 0) / picked.length;
        note.textContent = `${picked.length} offer${picked.length === 1 ? '' : 's'} selected · ` +
          `${watchers} watcher${watchers === 1 ? '' : 's'} reached · average ${avg.toFixed(1)}% off`;
      }
    }
    const disabled = picked.length === 0;
    if ($('wo-preview-btn')) $('wo-preview-btn').disabled = disabled;
    if ($('wo-send-btn'))    $('wo-send-btn').disabled    = disabled;
  }

  // An edited discount is the seller's call. It is clamped to what eBay will carry so a typo can't
  // produce a rejected send, and the server re-checks it against the profit floor either way.
  function onOfferDiscountEdit(e) {
    const item = woItemById(e.target.dataset.id);
    if (!item) return;
    const raw = parseInt(e.target.value, 10);
    const value = Math.min(25, Math.max(5, isFinite(raw) ? raw : (item.discountPercent || 5)));
    e.target.value = String(value);
    item.discountPercent = value;
    item.offerPrice = Math.round(item.listPrice * (100 - value)) / 100;
    item.marginGivenUp = Math.round((item.listPrice - item.offerPrice) * 100) / 100;
    const label = e.target.parentElement?.querySelector('.inv-change');
    if (label) label.textContent = 'edited';
    refreshOfferSelectionNote();
  }

  function updateOfferMessageCount() {
    const box = $('wo-message');
    const counter = $('wo-message-count');
    if (box && counter) counter.textContent = `${box.value.length}/250`;
  }

  function openOfferConfirm() {
    const picked = [...woSelected].map(woItemById).filter(Boolean);
    if (picked.length === 0) return;

    // The scale of what is about to go out, above the list — the list scrolls, and "31 offers to
    // 1,362 people" is the number the seller is actually deciding on.
    const watchers = picked.reduce((sum, i) => sum + (i.watchCount || 0), 0);
    const givenUp  = picked.reduce((sum, i) => sum + (i.marginGivenUp || 0), 0);
    $('wo-confirm-total').textContent =
      `${picked.length} offer${picked.length === 1 ? '' : 's'} to ${watchers} watcher${watchers === 1 ? '' : 's'} · ` +
      `${moneyExact(givenUp)} of margin if every one is accepted`;

    $('wo-confirm-list').innerHTML = picked.map(i => `
      <div class="inv-confirm-row">
        <span class="inv-confirm-title">${esc(i.title)}</span>
        <span class="inv-confirm-prices">${i.watchCount} 👁 &nbsp; ${moneyExact(i.listPrice)} → <strong>${moneyExact(i.offerPrice)}</strong> (−${i.discountPercent}%)</span>
      </div>`).join('');

    const box = $('wo-message');
    if (box && !box.value) box.value = woScan?.defaultMessage || '';
    updateOfferMessageCount();
    const loss = $('wo-allow-loss');
    if (loss) loss.checked = false;
    $('wo-confirm-overlay')?.classList.remove('hidden');
  }

  async function submitOffers(dryRun) {
    const picked = [...woSelected].map(woItemById).filter(Boolean);
    if (picked.length === 0) return;

    const body = {
      items: picked.map(i => ({
        listingId: i.listingId, sku: i.sku, title: i.title,
        listPrice: i.listPrice, discountPercent: i.discountPercent,
        watchCount: i.watchCount, quantity: 1,
      })),
      message: $('wo-message')?.value || '',
      allowCounterOffer: $('wo-allow-counter')?.checked !== false,
      minNetProfit: Math.max(0, parseFloat($('wo-min-profit')?.value || '0') || 0),
      dryRun,
      confirmed: !dryRun,
      allowBelowFloor: !dryRun && !!$('wo-allow-loss')?.checked,
    };

    setWoStatus(dryRun ? 'Previewing…' : 'Sending offers on eBay…');
    try {
      const res  = await fetch('/api/offers/send', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'Sending failed.');
      renderOfferOutcome(data);
      if (!dryRun && data.sent > 0) {
        addActivity(`${data.sent} offer${data.sent === 1 ? '' : 's'} sent to ${data.watchersReached} watcher${data.watchersReached === 1 ? '' : 's'}`,
          'Private discounts sent from Offers to Watchers — your public prices did not change.');
        // Those listings can't carry another offer for a while, so the board is stale for them.
        await runOfferScan();
      }
    } catch (err) {
      setWoStatus(`Sending failed: ${errorText(err)}`);
    }
  }

  function renderOfferOutcome(data) {
    const parts = [];
    if (data.dryRun) parts.push(`Preview only — nothing sent. ${data.items.length} offer${data.items.length === 1 ? '' : 's'} ready.`);
    else parts.push(`${data.sent} sent to ${data.watchersReached} watcher${data.watchersReached === 1 ? '' : 's'}`);
    if (data.skipped) parts.push(`${data.skipped} skipped`);
    if (data.failed)  parts.push(`${data.failed} failed`);

    const problems = (data.items || []).filter(i => i.status === 'skipped' || i.status === 'failed');
    setWoStatus(parts.join(' · ') + (problems.length
      ? ' — ' + problems.map(p => `${p.title}: ${p.message}`).join('; ')
      : ''));
  }

  function setWoStatus(text) {
    const el = $('wo-status');
    if (el) el.textContent = text || '';
  }

  // ── Aging-Inventory Rescue ───────────────────────────────────────────────
  // Inventory Health says what a listing should cost today and caps the cut at one revision, which
  // is right for a repricer and useless for dead stock: it depends on the seller coming back, and
  // the entire failure mode of aging inventory is that nobody comes back. This board decides the
  // whole ladder up front — dated drops, floors included — and pairs what will not move on its own
  // with something that already sells. See AgingInventoryRescuer.cs for the money rules.
  let rescueScan     = null;   // last RescueResult, kept so filtering never re-scans
  let rescueSelected = new Set();

  function showRescueSection() {
    hideOverlaySections();
    $('rescue-section')?.classList.remove('hidden');
    setActiveNavItem('rescue');
    markWorkspaceTabOpen('rescue');
  }

  function closeRescueSection() {
    closeWorkspacePage('rescue');
  }

  function bindRescue() {
    on('rsc-scan-btn', 'click', runRescueScan);
    on('rsc-close', 'click', closeRescueSection);
    on('rsc-home', 'click', goHome);
    on('inv-to-rescue', 'click', () => { navigateTo('rescue'); });
    // Filtering is a pure view over the scan already in hand — it must never re-run eBay calls.
    on('rsc-filter', 'change', renderRescuePlans);
    on('rsc-select-all', 'change', toggleSelectAllRescue);
    on('rsc-preview-btn', 'click', () => submitRescueDrops(true));
    on('rsc-apply-btn', 'click', openRescueConfirm);
    on('rsc-confirm-cancel', 'click', () => $('rsc-confirm-overlay')?.classList.add('hidden'));
    on('rsc-confirm-go', 'click', () => {
      $('rsc-confirm-overlay')?.classList.add('hidden');
      submitRescueDrops(false);
    });
  }

  async function runRescueScan() {
    const btn       = $('rsc-scan-btn');
    const staleDays = $('rsc-stale-days')?.value || '90';
    const maxItems  = $('rsc-max-items')?.value || '120';

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    setRescueStatus('Reading your live listings and pricing each one against sold comps…');
    $('rsc-results').innerHTML = '<p class="opportunity-empty">Finding what has stopped moving, and what still sells — this takes a moment on a large inventory.</p>';

    try {
      const res  = await fetch(`/api/inventory/rescue?staleAfterDays=${staleDays}&maxItems=${maxItems}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      rescueScan = data;
      rescueSelected.clear();
      renderRescueScan();
    } catch (err) {
      rescueScan = null;
      $('rsc-summary')?.classList.add('hidden');
      $('rsc-bulk-bar')?.classList.add('hidden');
      $('rsc-bundles')?.classList.add('hidden');
      $('rsc-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setRescueStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🛟 Rescue My Aging Stock'; }
    }
  }

  function renderRescueScan() {
    const warn = $('rsc-warning');

    if (rescueScan.status === 'ebay_unavailable') {
      $('rsc-summary')?.classList.add('hidden');
      $('rsc-bulk-bar')?.classList.add('hidden');
      $('rsc-bundles')?.classList.add('hidden');
      warn?.classList.add('hidden');
      $('rsc-results').innerHTML =
        '<p class="opportunity-empty">Your eBay account isn\'t connected, or the token has expired. Reconnect it in Settings, then scan again.</p>';
      setRescueStatus('');
      return;
    }

    if (rescueScan.dataWarning) {
      warn.textContent = rescueScan.dataWarning;
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    renderRescueSummary(rescueScan.summary || {});
    renderRescuePlans();
    renderRescueBundles();

    const s = rescueScan.summary || {};
    setRescueStatus(
      `${rescueScan.itemsAnalyzed} of ${rescueScan.activeListings} active listings checked · ` +
      `${s.staleListings || 0} sitting ${rescueScan.staleAfterDays}+ days` +
      (s.medianDaysListed ? ` · median ${s.medianDaysListed} days old` : ''));
  }

  // Leads with the money that is stuck, not with a listing count: "6 stale listings" is a
  // statistic, "$4,200 of your money has been sitting on a shelf for four months" is a reason to act.
  function renderRescueSummary(s) {
    const el = $('rsc-summary');
    if (!el) return;

    const tiles = [
      { label: 'Money stuck on the shelf', value: money(s.trappedCapital),
        sub: `${s.staleListings || 0} listing${s.staleListings === 1 ? '' : 's'} past ${rescueScan.staleAfterDays} days`,
        tone: s.trappedCapital > 0 ? 'warn' : '' },
      { label: 'Oldest one', value: s.oldestDaysListed ? `${s.oldestDaysListed} days` : '—',
        sub: s.medianDaysListed ? `half of them are ${s.medianDaysListed}+ days old` : 'Nothing stale yet',
        tone: s.oldestDaysListed >= 180 ? 'warn' : '' },
      { label: 'Drops to make today', value: String(s.stepsDueNow || 0),
        sub: s.plansReady ? `${s.plansReady} plan${s.plansReady === 1 ? '' : 's'} ready to run` : 'No plan needed',
        tone: s.stepsDueNow > 0 ? 'good' : '' },
      { label: 'Cash back if the plans clear', value: money(s.cashIfEveryPlanClears),
        sub: s.profitGivenUpIfEveryPlanClears
          ? `after giving up ${money(s.profitGivenUpIfEveryPlanClears)} of asking-price profit`
          : 'Record cost basis to see your take-home',
        tone: s.cashIfEveryPlanClears > 0 ? 'good' : '' },
      { label: 'Bundles found', value: String(s.bundlesFound || 0),
        sub: s.bundlesFound
          ? `freeing ${money(s.capitalFreedByBundles)} of stuck stock`
          : 'No fast mover to pair with yet',
        tone: s.bundlesFound > 0 ? 'good' : '' },
      { label: 'Bundles add', value: s.incrementalNetFromBundles
          ? money(s.incrementalNetFromBundles) : money(s.addedRevenueFromBundles),
        sub: s.incrementalNetFromBundles
          ? 'net, over selling the fast item alone'
          : 'revenue, over selling the fast item alone',
        tone: (s.incrementalNetFromBundles || s.addedRevenueFromBundles) > 0 ? 'good' : '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  const RSC_URGENCY = {
    critical: { label: '🔴 Dead capital', cls: 'inv-v-dead' },
    high:     { label: '🟠 Going stale',  cls: 'inv-v-stale' },
    watch:    { label: '🟡 Watch',        cls: 'inv-v-over' },
  };

  function rescueFilterMatches(plan, filter) {
    switch (filter) {
      case 'ready':    return plan.hasPlan;
      case 'critical': return plan.urgency === 'critical';
      case 'no_plan':  return !plan.hasPlan;
      default:         return true;
    }
  }

  function renderRescuePlans() {
    if (!rescueScan) return;
    const filter = $('rsc-filter')?.value || 'ready';
    const plans  = (rescueScan.plans || []).filter(p => rescueFilterMatches(p, filter));
    const el     = $('rsc-results');

    if (plans.length === 0) {
      const total = (rescueScan.plans || []).length;
      el.innerHTML = `<p class="opportunity-empty">${
        total === 0
          ? `Nothing has been sitting longer than ${rescueScan.staleAfterDays} days — your money is turning over. Lower the age filter to look further back.`
          : 'Nothing matches that filter. Switch to "Everything" to see the listings no plan could be built for.'}</p>`;
      $('rsc-bulk-bar')?.classList.add('hidden');
      return;
    }

    el.innerHTML = plans.map(renderRescueCard).join('');

    plans.forEach(p => {
      const box = $(`rsc-check-${p.listingId}`);
      if (box) box.addEventListener('change', () => {
        if (box.checked) rescueSelected.add(p.listingId); else rescueSelected.delete(p.listingId);
        updateRescueSelection();
      });
    });

    $('rsc-bulk-bar')?.classList.remove('hidden');
    updateRescueSelection();
  }

  function renderRescueCard(p) {
    const urgency = RSC_URGENCY[p.urgency] || RSC_URGENCY.watch;
    const age     = p.daysListed == null ? 'age unknown' : `${p.daysListed} days live`;

    // The ladder itself. Dates are the point: a drop the seller has already decided on is one they
    // will actually make, and the schedule is what turns "reprice it again sometime" into a plan.
    const steps = (p.steps || []).map(s => `
      <tr class="${s.daysFromNow === 0 ? 'rsc-step-now' : ''}">
        <td>${s.daysFromNow === 0 ? '<strong>Today</strong>' : esc(shortDate(s.onUtc))}</td>
        <td class="num"><strong>${moneyExact(s.price)}</strong></td>
        <td class="num">−${Number(s.percentOffListPrice || 0).toFixed(0)}%</td>
        <td class="num">${s.netProfit == null ? '—' : moneyExact(s.netProfit)}</td>
        <td>${esc(s.note)}${s.isFloor ? ' <span class="rsc-floor-tag">floor</span>' : ''}</td>
      </tr>`).join('');

    const ladder = p.hasPlan ? `
      <table class="inv-table rsc-ladder">
        <thead>
          <tr><th>When</th><th class="num">Price</th><th class="num">Off</th><th class="num">You keep</th><th>Why</th></tr>
        </thead>
        <tbody>${steps}</tbody>
      </table>` : '';

    const signals = (p.signals || []).length
      ? `<ul class="rsc-signals">${p.signals.map(s => `<li>${esc(s)}</li>`).join('')}</ul>` : '';

    return `
      <div class="rsc-card">
        <div class="rsc-card-head">
          ${p.hasPlan
            ? `<input id="rsc-check-${esc(p.listingId)}" type="checkbox" class="rsc-check" ${rescueSelected.has(p.listingId) ? 'checked' : ''} />`
            : '<span class="rsc-check-spacer"></span>'}
          <div class="rsc-card-title">
            <a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)}</a>
            <div class="rsc-card-meta">
              <span class="inv-verdict ${urgency.cls}">${esc(urgency.label)}</span>
              <span>${esc(age)}</span>
              <span>${money(p.capitalTiedUp)} tied up</span>
              <span>listed at ${moneyExact(p.listPrice)}</span>
              ${p.marketPrice ? `<span>market ${moneyExact(p.marketPrice)}</span>` : ''}
            </div>
          </div>
        </div>
        <p class="rsc-headline">${esc(p.headline)}</p>
        <p class="rsc-why">${esc(p.why)}</p>
        ${ladder}
        ${signals}
      </div>`;
  }

  function toggleSelectAllRescue(e) {
    const on = !!e.target.checked;
    rescueSelected.clear();
    if (on) (rescueScan?.plans || []).filter(p => p.hasPlan).forEach(p => rescueSelected.add(p.listingId));
    document.querySelectorAll('.rsc-check').forEach(box => { box.checked = on; });
    updateRescueSelection();
  }

  function updateRescueSelection() {
    const chosen = selectedRescuePlans();
    const note   = $('rsc-selection-note');

    if (note) {
      note.textContent = chosen.length === 0
        ? 'Nothing selected.'
        : `${chosen.length} listing${chosen.length === 1 ? '' : 's'} selected — ` +
          `${money(chosen.reduce((sum, p) => sum + (p.capitalTiedUp || 0), 0))} of stuck stock.`;
    }
    const preview = $('rsc-preview-btn');
    const apply   = $('rsc-apply-btn');
    if (preview) preview.disabled = chosen.length === 0;
    if (apply)   apply.disabled   = chosen.length === 0;
  }

  function selectedRescuePlans() {
    return (rescueScan?.plans || []).filter(p => p.hasPlan && rescueSelected.has(p.listingId));
  }

  function openRescueConfirm() {
    const chosen = selectedRescuePlans();
    if (chosen.length === 0) return;

    // Only the drop due today goes to eBay. The later rungs are a plan, not a scheduled job — this
    // app has no server running while it is closed, and quietly promising to cut a price in two
    // weeks would be a promise it cannot keep.
    const total = $('rsc-confirm-total');
    if (total) total.textContent =
      `${chosen.length} price${chosen.length === 1 ? '' : 's'} change now. The later steps stay here as your plan — come back and run this again when each date comes round.`;

    const list = $('rsc-confirm-list');
    if (list) list.innerHTML = chosen.map(p => `
      <div class="inv-confirm-row">
        <span class="inv-confirm-title">${esc(p.title)}</span>
        <span class="inv-confirm-prices">${moneyExact(p.listPrice)} → <strong>${moneyExact(p.firstStep.price)}</strong></span>
      </div>`).join('');

    $('rsc-confirm-overlay')?.classList.remove('hidden');
  }

  async function submitRescueDrops(dryRun) {
    const chosen = selectedRescuePlans();
    if (chosen.length === 0) return;

    // Reuses the repricer endpoint rather than adding a second way to change a live price: every
    // brake on buyer-visible changes — preview by default, explicit confirm, server-side break-even
    // re-check — stays in exactly one place.
    const body = {
      items: chosen.map(p => ({
        listingId: p.listingId, sku: p.sku, title: p.title,
        newPrice: p.firstStep.price, currentPrice: p.listPrice,
        quantity: p.quantity || 1, breakEvenPrice: p.floorPrice,
      })),
      dryRun, confirmed: !dryRun,
      allowBelowBreakEven: false,
    };

    setRescueStatus(dryRun ? 'Previewing…' : 'Dropping prices on eBay…');
    try {
      const res  = await fetch('/api/inventory/reprice', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The price drop failed.');

      const parts = [];
      if (data.dryRun) parts.push(`Preview only — nothing sent to eBay. ${data.items.length} drop${data.items.length === 1 ? '' : 's'} ready.`);
      else parts.push(`${data.applied} price${data.applied === 1 ? '' : 's'} dropped`);
      if (data.skipped) parts.push(`${data.skipped} skipped`);
      if (data.failed)  parts.push(`${data.failed} failed`);

      const problems = (data.items || []).filter(i => i.status === 'skipped' || i.status === 'failed');
      setRescueStatus(parts.join(' · ') + (problems.length
        ? ' — ' + problems.map(p => `${p.title}: ${p.message}`).join('; ') : ''));

      if (!dryRun && data.applied > 0) {
        addActivity(`${data.applied} aging listing${data.applied === 1 ? '' : 's'} marked down`,
          'Step one of the rescue plan applied from Aging-Inventory Rescue.');
        // Those rows are stale by definition now, so re-scan rather than leave the board showing
        // prices that are no longer live.
        await runRescueScan();
      }
    } catch (err) {
      setRescueStatus(`The price drop failed: ${errorText(err)}`);
    }
  }

  // The other way out: stop discounting the thing nobody is searching for, and attach it to the
  // thing they already are.
  function renderRescueBundles() {
    const el = $('rsc-bundles');
    if (!el) return;

    const bundles = rescueScan?.bundles || [];
    if (bundles.length === 0) { el.classList.add('hidden'); el.innerHTML = ''; return; }

    el.innerHTML = `
      <h3 class="rsc-bundle-heading">Bundle it out instead</h3>
      <p class="opp-hint">
        Each pair puts a slow mover in the same box as something that already sells. The slow half
        goes out at its clearance price without you publicly cutting its standalone listing, and one
        order pays the per-order costs instead of two. List these by hand — nothing here is published for you.
      </p>
      ${bundles.map(renderBundleCard).join('')}`;
    el.classList.remove('hidden');
  }

  function renderBundleCard(b) {
    const gain = b.incrementalNet != null
      ? `<strong>${money(b.incrementalNet)} more net</strong> than selling the fast one alone`
      : `<strong>${money(b.addedRevenue)} more revenue</strong> than selling the fast one alone`;

    const signals = (b.signals || []).length
      ? `<ul class="rsc-signals">${b.signals.map(s => `<li>${esc(s)}</li>`).join('')}</ul>` : '';

    return `
      <div class="rsc-card rsc-bundle-card">
        <div class="rsc-bundle-pair">
          <div class="rsc-bundle-half rsc-bundle-slow">
            <div class="rsc-bundle-tag">🐢 Stuck ${b.slowDaysListed == null ? '' : `${b.slowDaysListed} days`}</div>
            <div class="rsc-bundle-name">${esc(b.slowTitle)}</div>
            <div class="rsc-bundle-price">${moneyExact(b.slowPrice)} → <strong>${moneyExact(b.slowContribution)}</strong> in the bundle</div>
          </div>
          <div class="rsc-bundle-plus">+</div>
          <div class="rsc-bundle-half rsc-bundle-fast">
            <div class="rsc-bundle-tag">⚡ Sells — ${esc(b.fastEvidence)}</div>
            <div class="rsc-bundle-name">${esc(b.fastTitle)}</div>
            <div class="rsc-bundle-price">${moneyExact(b.fastPrice)}</div>
          </div>
        </div>
        <div class="rsc-bundle-money">
          <span>List the pair at <strong>${moneyExact(b.bundlePrice)}</strong></span>
          <span>${Number(b.discountPercent || 0).toFixed(0)}% off the two asking prices</span>
          <span>${gain}</span>
          <span>frees ${money(b.capitalFreed)} of stuck stock</span>
        </div>
        <p class="rsc-why">${esc(b.rationale)}</p>
        <div class="rsc-bundle-title">Suggested title: <code>${esc(b.suggestedTitle)}</code></div>
        ${signals}
      </div>`;
  }

  function setRescueStatus(text) {
    const el = $('rsc-status');
    if (el) el.textContent = text || '';
  }

  // ── Spend My Budget — the sourcing basket ────────────────────────────────
  // Every other sourcing board ranks deals; this one spends the money. The candidates are whatever
  // the seller is already looking at — the local scan in hand plus anything tracked at Sourced —
  // and the server solves an exact knapsack over them. Nothing is re-priced here or on the way:
  // each candidate carries the profit figure it was given on the board it came from, so the basket
  // can never quote a number the table beside it doesn't.
  let budgetPlan = null;

  function showBudgetSection() {
    hideOverlaySections();
    $('budget-section')?.classList.remove('hidden');
    setActiveNavItem('budget');
    markWorkspaceTabOpen('budget');
    renderBudgetPool();
  }

  function closeBudgetSection() {
    closeWorkspacePage('budget');
  }

  function bindBudget() {
    on('bud-plan-btn', 'click', runBudgetPlan);
    on('bud-close', 'click', closeBudgetSection);
    on('bud-home', 'click', goHome);
    // The step out of the ranked table and into an allocation, from the board itself.
    on('fb-arb-budget-btn', 'click', () => { navigateTo('budget'); });
    // Switching the definition of "best" re-solves from the same pool. It is one cheap POST over
    // numbers already computed, not a re-scan, so it can be a plain control change.
    on('bud-objective', 'change', () => { if (budgetPlan) runBudgetPlan(); });
    ['bud-amount', 'bud-reserve'].forEach(id => on(id, 'input', renderBudgetPool));
    on('bud-include-tracked', 'change', renderBudgetPool);
  }

  // One board row → one buyable thing. Everything the allocation needs and nothing it doesn't:
  // what it costs, what it nets, how long the money is gone, and what that rests on.
  function budgetCandidateFromArbRow(row) {
    return {
      id: row.itemId || row.url || row.title,
      title: row.title,
      source: row.source,
      sourceLabel: row.sourceLabel,
      url: row.url,
      imageUrl: row.imageUrl,
      location: row.location,
      distanceMiles: row.distanceMiles,
      // What the basket actually has to spend on it — sales tax included on a retail buy, or the
      // budget would buy more than the money covers.
      buyPrice: paidFor(row),
      quantity: 1,
      netProfit: row.netProfit || 0,
      maxBuyPrice: row.maxBuyPrice,
      // The drafted opening offer, so the basket can say what haggling would free up. A ceiling,
      // never counted as money in any total.
      targetOffer: row.negotiation?.openingOffer ?? null,
      daysToCash: row.daysToCash,
      compCount: (row.soldCompCount || 0) + (row.terapeakCompCount || 0),
      confidenceScore: row.confidenceScore,
      verdict: row.verdict,
      origin: 'scan',
    };
  }

  function budgetCandidates() {
    return (arbitrageData?.items || []).map(budgetCandidateFromArbRow);
  }

  // What this plan is about to be built from, said before the button is pressed — an allocation
  // over an empty pool is a confusing answer, and "you have no deals loaded" is a clear one.
  function renderBudgetPool() {
    const el = $('bud-pool');
    if (!el) return;

    const scanned = budgetCandidates().length;
    const tracked = !!$('bud-include-tracked')?.checked;
    const bits = [];

    bits.push(scanned
      ? `<strong>${scanned}</strong> deal${scanned === 1 ? '' : 's'} from your last local scan`
      : 'No local scan loaded — run one in the Opportunity Finder to allocate across fresh deals');
    if (tracked) bits.push('plus everything you\'ve tracked at <strong>Sourced</strong>');

    el.innerHTML = `Spending across: ${bits.join(', ')}.`;
  }

  async function runBudgetPlan() {
    const btn = $('bud-plan-btn');
    const budget = parseFloat($('bud-amount')?.value || '0') || 0;
    const reserve = parseFloat($('bud-reserve')?.value || '0') || 0;
    const includeTracked = !!$('bud-include-tracked')?.checked;
    const candidates = budgetCandidates();

    if (budget <= 0) return setBudgetStatus('Type what you have to spend and I\'ll work out where it goes furthest.');
    if (!candidates.length && !includeTracked)
      return setBudgetStatus('There are no deals to spend it on. Run a local scan, or tick "include deals I\'ve tracked".');

    if (btn) { btn.disabled = true; btn.textContent = 'Planning…'; }
    setBudgetStatus('Working out the best basket…');

    try {
      const res = await fetch('/api/sourcing/budget', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          budget,
          reserve,
          maxDaysToCash: parseInt($('bud-horizon')?.value || '0', 10) || 0,
          includeThin: !!$('bud-include-thin')?.checked,
          includeTrackedDeals: includeTracked,
          objective: $('bud-objective')?.value || 'profit',
          candidates,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The budget couldn\'t be planned.');
      budgetPlan = data;
      renderBudgetPlan(data);
    } catch (err) {
      budgetPlan = null;
      $('bud-summary')?.classList.add('hidden');
      $('bud-lift')?.classList.add('hidden');
      $('bud-alternatives')?.classList.add('hidden');
      $('bud-leftout')?.classList.add('hidden');
      $('bud-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The budget couldn\'t be planned.'))}</p>`;
      setBudgetStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '💵 Plan My Basket'; }
    }
  }

  function renderBudgetPlan(data) {
    setBudgetStatus('');

    // Nothing to allocate: say which of the several reasons it is, and stop. A basket of zero
    // deals rendered as a table reads like a failure; a sentence reads like an answer.
    if (data.status !== 'ok' || !data.plan?.picks?.length) {
      $('bud-summary')?.classList.add('hidden');
      $('bud-lift')?.classList.add('hidden');
      $('bud-alternatives')?.classList.add('hidden');
      $('bud-results').innerHTML =
        `<p class="opportunity-empty">${esc(data.message || 'There is no basket to build from these.')}</p>`;
      renderBudgetLeftOut(data.leftOut || []);
      return;
    }

    renderBudgetSummary(data);
    renderBudgetLift(data);
    renderBudgetBasket(data.plan);
    renderBudgetAlternatives(data);
    renderBudgetLeftOut(data.leftOut || []);
  }

  function renderBudgetSummary(data) {
    const el = $('bud-summary');
    if (!el) return;
    const plan = data.plan;

    const tiles = [
      { label: 'Buy these', value: String(plan.picks.length),
        sub: `${plan.objectiveLabel} · ${data.eligibleCount} deal${data.eligibleCount === 1 ? '' : 's'} were in play`,
        tone: 'good' },
      { label: 'Cash deployed', value: money(plan.capitalDeployed),
        sub: plan.leftover > 0 ? `${money(plan.leftover)} stays in your pocket` : 'Every dollar of it working',
        tone: '' },
      { label: 'Net profit', value: money(plan.totalNetProfit),
        sub: plan.blendedRoiPercent != null ? `${Math.round(plan.blendedRoiPercent)}% on the cash you put in` : 'after eBay fees and shipping',
        tone: 'good' },
      { label: 'All your money back', value: plan.allCashBackBy || '—',
        sub: plan.allCashBackBy
          ? `first of it around ${plan.firstCashBackBy}`
          : `${plan.unknownSpeedCount} pick${plan.unknownSpeedCount === 1 ? '' : 's'} with no measured speed — no honest date`,
        tone: plan.allCashBackBy ? 'good' : 'warn' },
      { label: 'Tied up for', value: plan.weightedDaysToCash != null ? `${plan.weightedDaysToCash} days` : '—',
        sub: plan.capitalTurnsPerYear != null ? `about ${plan.capitalTurnsPerYear} turns of this cash a year` : 'weighted by what each one costs',
        tone: '' },
      { label: 'Earning per day', value: plan.profitPerDay != null ? perDay(plan.profitPerDay) : '—',
        sub: plan.annualizedRoiPercent != null ? `${Math.round(plan.annualizedRoiPercent)}% a year at this pace` : 'while the money is out',
        tone: '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  // The claim the feature stands on. Rendered from the server's own comparison — including when
  // the answer is that buying down the list would have done just as well.
  function renderBudgetLift(data) {
    const el = $('bud-lift');
    if (!el) return;
    const c = data.comparison || {};
    const won = c.extraProfit > 0;

    const stretch = data.stretch
      ? `<p class="bud-lift-sub">${esc(data.stretch.note)}</p>` : '';
    const haggle = data.plan.negotiationUpside > 0
      ? `<p class="bud-lift-sub">And ${money(data.plan.negotiationUpside)} more still if all ${data.plan.negotiableCount}
         sellers took your opening offer — that's the buy side, and it costs you nothing but the asking.</p>`
      : '';

    el.className = `bud-lift ${won ? 'bud-lift-won' : 'bud-lift-tied'}`;
    el.innerHTML = `
      <div class="bud-lift-head">
        ${won
          ? `<span class="bud-lift-amount">+${money(c.extraProfit)}</span>
             <span class="bud-lift-label">more than buying straight down the list${c.extraProfitPercent ? ` — ${Math.round(c.extraProfitPercent)}% better` : ''}</span>`
          : `<span class="bud-lift-label">Buying straight down the list lands on the same money here. No basket beats it.</span>`}
      </div>
      <p class="bud-lift-sub">${esc(c.note || '')}</p>
      ${stretch}${haggle}`;
    el.classList.remove('hidden');
  }

  function renderBudgetBasket(plan) {
    const wrap = $('bud-results');
    if (!wrap) return;

    wrap.innerHTML = `
      <p class="bud-headline">${esc(plan.headline)}</p>
      ${plan.note ? `<p class="bud-note">${esc(plan.note)}</p>` : ''}
      <div class="fb-arb-table-wrap">
        <table class="fb-arb-table bud-table">
          <thead>
            <tr>
              <th class="fb-arb-th-rank">#</th>
              <th>Buy this</th>
              <th class="num">Pay</th>
              <th class="num dt-money">Net profit</th>
              <th class="num dt-money">ROI</th>
              <th class="num">Days to cash</th>
              <th class="num">Spent so far</th>
              <th class="num">Profit so far</th>
            </tr>
          </thead>
          <tbody>${plan.picks.map(budgetPickRowHtml).join('')}</tbody>
          <tfoot>
            <tr>
              <td colspan="2">${plan.picks.length} deal${plan.picks.length === 1 ? '' : 's'}</td>
              <td class="num"><strong>${money(plan.capitalDeployed)}</strong></td>
              <td class="num dt-money"><strong>${money(plan.totalNetProfit)}</strong></td>
              <td class="num dt-money">${plan.blendedRoiPercent != null ? `${Math.round(plan.blendedRoiPercent)}%` : '—'}</td>
              <td class="num">${plan.weightedDaysToCash != null ? `${plan.weightedDaysToCash}d avg` : '—'}</td>
              <td class="num">${money(plan.leftover)} left</td>
              <td class="num"></td>
            </tr>
          </tfoot>
        </table>
      </div>`;
    wrap.classList.remove('hidden');
  }

  function budgetPickRowHtml(pick) {
    const tier = SPEED_TIERS[pick.speedTier] || SPEED_TIERS.unknown;
    const meta = [
      pick.sourceLabel ? esc(pick.sourceLabel) : '',
      pick.distanceMiles != null ? `${pick.distanceMiles} mi` : '',
      pick.location ? esc(pick.location) : '',
      // A frozen forecast is a weaker claim than a scan run five minutes ago, and the row says so.
      pick.origin === 'tracked' ? '<span class="bud-origin">tracked — frozen forecast</span>' : '',
    ].filter(Boolean).join(' · ');

    const title = pick.url
      ? `<a href="${esc(pick.url)}" target="_blank" rel="noopener noreferrer">${esc(pick.title)}</a>`
      : esc(pick.title);

    return `
      <tr>
        <td class="fb-arb-th-rank">${pick.rank}</td>
        <td>
          <div class="bud-pick-title">${title}${pick.quantity > 1 ? ` <span class="bud-qty">×${pick.quantity}</span>` : ''}</div>
          <div class="fb-arb-meta">${meta}</div>
          <div class="bud-why">${esc(pick.why)}</div>
        </td>
        <td class="num">${money(pick.spend)}${pick.targetOffer ? `<div class="bud-sub">offer ${money(pick.targetOffer)}</div>` : ''}</td>
        <td class="num dt-money fb-arb-profit">${money(pick.totalNetProfit)}</td>
        <td class="num dt-money">${pick.roiPercent != null ? `${Math.round(pick.roiPercent)}%` : '—'}</td>
        <td class="num">${pick.daysToCash != null
          ? `<span class="speed-days speed-${tier.cls}">${pick.daysToCash}d</span>${pick.profitPerDay ? `<span class="speed-rate">${perDay(pick.profitPerDay)}</span>` : ''}`
          : '<span class="fb-arb-muted">—</span>'}</td>
        <td class="num">${money(pick.cumulativeSpend)}</td>
        <td class="num">${money(pick.cumulativeProfit)}</td>
      </tr>`;
  }

  // The same money under the other two definitions of best. Shown side by side rather than hidden
  // behind the control, because "less total money, back three weeks sooner" is a real trade the
  // seller is entitled to make with their own cash.
  function renderBudgetAlternatives(data) {
    const el = $('bud-alternatives');
    if (!el) return;

    const alts = (data.alternatives || []).filter(p => p.picks?.length);
    if (!alts.length) { el.classList.add('hidden'); return; }

    el.innerHTML = `
      <h3 class="bud-section-title">The same money, spent for something else</h3>
      <div class="bud-alt-grid">
        ${alts.map(p => `
          <div class="bud-alt">
            <div class="bud-alt-head">
              <span class="bud-alt-label">${esc(p.objectiveLabel)}</span>
              <button class="btn btn-secondary small bud-alt-btn" type="button" data-objective="${esc(p.objective)}">Use this instead</button>
            </div>
            <div class="bud-alt-money">
              <span class="bud-alt-profit">${money(p.totalNetProfit)}</span>
              <span class="bud-alt-sub">net from ${money(p.capitalDeployed)} across ${p.picks.length} deal${p.picks.length === 1 ? '' : 's'}</span>
            </div>
            <div class="bud-alt-sub">${p.allCashBackBy
              ? `All of it back by ${esc(p.allCashBackBy)}`
              : `${p.unknownSpeedCount} with no measured speed — no date on the last of it`}</div>
            <p class="bud-alt-note">${esc(p.objectiveNote)}</p>
          </div>`).join('')}
      </div>`;
    el.classList.remove('hidden');

    el.querySelectorAll('.bud-alt-btn').forEach(btn => btn.addEventListener('click', () => {
      const select = $('bud-objective');
      if (select) select.value = btn.dataset.objective;
      runBudgetPlan();
    }));
  }

  // What didn't make it, and why. A sourcing screen that silently drops deals is how a real one
  // gets missed — and "you're $30 short of this one" is the most actionable line on the page.
  function renderBudgetLeftOut(leftOut) {
    const el = $('bud-leftout');
    if (!el) return;
    if (!leftOut.length) { el.classList.add('hidden'); return; }

    el.innerHTML = `
      <h3 class="bud-section-title">Left out, and why</h3>
      <ul class="bud-leftout-list">
        ${leftOut.map(s => `
          <li class="bud-leftout-item bud-reason-${esc(s.reasonCode)}">
            <span class="bud-leftout-title">${s.url
              ? `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`
              : esc(s.title)}</span>
            <span class="bud-leftout-money">${money(s.buyPrice)}${s.netProfit != null ? ` · ${money(s.netProfit)} net` : ''}</span>
            <span class="bud-leftout-reason">${esc(s.reason)}</span>
          </li>`).join('')}
      </ul>`;
    el.classList.remove('hidden');
  }

  function setBudgetStatus(text) {
    const el = $('bud-status');
    if (el) el.textContent = text || '';
  }

  // ── Recover Lost Sales — relist + Second Chance Offers ────────────────────
  // The third view of the same inventory, and the only one that can see the listings that ENDED.
  // Two different kinds of money live on this board and they are kept visually apart, because
  // they are worth very different amounts: a relist is a second run at a maybe, and a Second
  // Chance Offer goes to a named person who publicly bid a specific number on this exact item.
  // See RelistAnalyzer.cs for what sets each price and what stops it.
  let rlScan     = null;   // last RelistRecoveryResult, kept so filtering never re-scans
  let rlSelected = new Set();   // listing IDs picked for relist
  let rlBidders  = new Set();   // "listingId||userId" picked for a Second Chance Offer

  function showRelistSection() {
    hideOverlaySections();
    $('relist-section')?.classList.remove('hidden');
    setActiveNavItem('relist');
    markWorkspaceTabOpen('relist');
  }

  function closeRelistSection() {
    closeWorkspacePage('relist');
  }

  function bindRelist() {
    on('rl-scan-btn', 'click', runRelistScan);
    on('rl-close', 'click', closeRelistSection);
    on('rl-home', 'click', goHome);
    // Filtering is a pure view over the scan already in hand — it must never re-run eBay calls.
    on('rl-filter', 'change', renderRelistRows);
    on('rl-select-all', 'change', toggleSelectAllRelists);
    on('rl-preview-btn', 'click', () => submitRelists(true));
    on('rl-relist-btn', 'click', openRelistConfirm);
    on('rl-confirm-cancel', 'click', () => $('rl-confirm-overlay')?.classList.add('hidden'));
    on('rl-confirm-go', 'click', () => {
      $('rl-confirm-overlay')?.classList.add('hidden');
      submitRelists(false);
    });
    on('rl-sc-cancel', 'click', () => $('rl-sc-overlay')?.classList.add('hidden'));
    on('rl-sc-go', 'click', () => {
      $('rl-sc-overlay')?.classList.add('hidden');
      submitSecondChance(false);
    });
    on('rl-sc-message', 'input', updateScMessageCount);
  }

  async function runRelistScan() {
    const btn = $('rl-scan-btn');
    const days      = $('rl-days')?.value || '45';
    const maxItems  = $('rl-max-items')?.value || '120';
    const minProfit = Math.max(0, parseFloat($('rl-min-profit')?.value || '0') || 0);

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    setRlStatus('Reading the listings that ended without selling…');
    $('rl-results').innerHTML = '<p class="opportunity-empty">Pricing each ended listing against sold comps and checking who bid on the auctions — this takes a moment.</p>';

    try {
      const res  = await fetch(`/api/relist/recover?days=${days}&maxItems=${maxItems}&minProfit=${minProfit}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      rlScan = data;
      rlSelected.clear();
      rlBidders.clear();
      renderRelistScan();
    } catch (err) {
      rlScan = null;
      $('rl-summary')?.classList.add('hidden');
      $('rl-bulk-bar')?.classList.add('hidden');
      $('rl-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setRlStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '♻️ Find My Lost Sales'; }
    }
  }

  function renderRelistScan() {
    const warn = $('rl-warning');

    if (rlScan.status === 'ebay_unavailable') {
      $('rl-summary')?.classList.add('hidden');
      $('rl-bulk-bar')?.classList.add('hidden');
      warn?.classList.add('hidden');
      $('rl-results').innerHTML =
        '<p class="opportunity-empty">Your eBay account isn\'t connected, or the token has expired. Reconnect it in Settings, then scan again.</p>';
      setRlStatus('');
      return;
    }

    if (rlScan.dataWarning) {
      warn.textContent = rlScan.dataWarning;
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    renderRelistSummary(rlScan.summary || {});
    renderRelistRows();

    const s = rlScan.summary || {};
    setRlStatus(
      `${s.analyzed || 0} of ${s.endedListings || 0} ended listing${s.endedListings === 1 ? '' : 's'} in the last ${rlScan.lookbackDays} days · ` +
      `${s.readyToRelist || 0} worth putting back up` +
      (s.secondChanceBidders ? ` · ${s.secondChanceBidders} lost bidder${s.secondChanceBidders === 1 ? '' : 's'} reachable` : ''));
  }

  // Leads with the size of the pile and the cash already sunk in it, because those are facts.
  // Everything conditional on a future sale is labelled as conditional, in the tile itself.
  function renderRelistSummary(s) {
    const el = $('rl-summary');
    if (!el) return;

    const tiles = [
      { label: 'Asked and never sold', value: money(s.askedAndUnsold),
        sub: `${s.analyzed || 0} listing${s.analyzed === 1 ? '' : 's'} that ended without a buyer`,
        tone: s.askedAndUnsold > 0 ? 'warn' : '' },
      { label: 'Your cash sitting in it', value: money(s.cashSunk),
        sub: s.withCostBasis ? `what you paid, across ${s.withCostBasis} recorded item${s.withCostBasis === 1 ? '' : 's'}` : 'Record what you paid to see this',
        tone: s.cashSunk > 0 ? 'warn' : '' },
      { label: 'Worth putting back up', value: String(s.readyToRelist || 0),
        sub: s.relistValue ? `${money(s.relistValue)} back on the site` : 'Nothing to relist yet',
        tone: s.readyToRelist > 0 ? 'good' : '' },
      { label: 'If those sell this time', value: money(s.netIfAllSell),
        sub: s.netIfAllSell ? 'net after fees — only on the ones that sell' : 'Record cost basis to see net profit',
        tone: s.netIfAllSell > 0 ? 'good' : '' },
      { label: 'Bidders who already said yes', value: String(s.secondChanceBidders || 0),
        sub: s.secondChanceValue
          ? `${money(s.secondChanceValue)} of offers at prices they bid`
          : 'No reachable losing bidders',
        tone: s.secondChanceBidders > 0 ? 'good' : '' },
      { label: 'Held back', value: String((s.underwater || 0) + (s.alreadyRelisted || 0)),
        sub: `${s.underwater || 0} with no profitable price · ${s.alreadyRelisted || 0} eBay already relisted`,
        tone: (s.underwater || 0) > 0 ? 'warn' : '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  const RL_VERDICTS = {
    second_chance:   { label: '🎯 Bidders waiting',   cls: 'rl-v-second' },
    relist_cheaper:  { label: '♻️ Relist cheaper',    cls: 'wo-v-ready' },
    relist_as_is:    { label: '♻️ Relist as-is',      cls: 'rl-v-asis' },
    relist:          { label: '♻️ Relist',            cls: 'wo-v-ready' },
    underwater:      { label: '🛑 No price that pays', cls: 'inv-v-underwater' },
    already_relisted:{ label: '✅ Already back up',    cls: 'inv-v-nodata' },
    ended_by_seller: { label: '⏹ You ended this',     cls: 'inv-v-nodata' },
    no_price:        { label: '? No price',           cls: 'inv-v-nodata' },
    no_data:         { label: '? No data',            cls: 'inv-v-nodata' },
  };

  function rlFilterMatches(item, filter) {
    switch (filter) {
      case 'ready':         return item.canRelist;
      case 'second_chance': return (item.sendableBidders || 0) > 0;
      case 'blocked':       return !item.canRelist;
      default:              return true;
    }
  }

  function renderRelistRows() {
    if (!rlScan) return;
    const filter = $('rl-filter')?.value || 'ready';
    const rows = (rlScan.items || []).filter(i => rlFilterMatches(i, filter));
    const el = $('rl-results');

    if (rows.length === 0) {
      const total = (rlScan.items || []).length;
      el.innerHTML = `<p class="opportunity-empty">${
        total === 0
          ? 'Nothing of yours ended unsold in that window — which is the good version of this screen being empty. Widen the window to look further back.'
          : 'Nothing matches that filter. Switch to "Everything" to see why each one was held back.'}</p>`;
      $('rl-bulk-bar')?.classList.add('hidden');
      return;
    }

    el.innerHTML = `
      <table class="inv-table">
        <thead>
          <tr>
            <th class="inv-col-check"></th>
            <th>Listing</th>
            <th class="num">Ended</th>
            <th class="num">Interest</th>
            <th class="num">Asked</th>
            <th class="num">Market</th>
            <th class="num">Put back at</th>
            <th class="num">Your net</th>
            <th>What happened</th>
          </tr>
        </thead>
        <tbody>${rows.map(rlRowHtml).join('')}</tbody>
      </table>`;

    el.querySelectorAll('.rl-check').forEach(cb => cb.addEventListener('change', onRelistCheck));
    el.querySelectorAll('.rl-price-input').forEach(inp => {
      inp.addEventListener('change', onRelistPriceEdit);
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') inp.blur(); });
    });
    el.querySelectorAll('.rl-bidder-check').forEach(cb => cb.addEventListener('change', onBidderCheck));
    el.querySelectorAll('.rl-sc-send').forEach(btn => btn.addEventListener('click', openSecondChanceConfirm));

    $('rl-bulk-bar')?.classList.remove('hidden');
    refreshRelistSelectionNote();
  }

  // "eBay didn't say" and "nobody looked" are different findings and must not render the same.
  function rlInterestHtml(item) {
    const watchers = item.watchCount;
    const views = item.hitCount;
    if (watchers == null && views == null)
      return '<span class="inv-dash" title="eBay reported no watcher or view counts for this listing">—</span>';

    const parts = [];
    if (watchers != null) parts.push(`<span class="wo-watchers ${watchers >= 5 ? 'hot' : ''}">${watchers} 👁</span>`);
    if (views != null) parts.push(`<div class="inv-sub">${views} view${views === 1 ? '' : 's'}</div>`);
    if (item.bidCount > 0) parts.push(`<div class="inv-sub rl-bids">${item.bidCount} bid${item.bidCount === 1 ? '' : 's'}</div>`);
    return parts.join('');
  }

  function rlRowHtml(item) {
    const v = RL_VERDICTS[item.verdict] || RL_VERDICTS.no_data;
    const checked = rlSelected.has(item.listingId) ? 'checked' : '';

    const priceCell = item.relistPrice != null
      ? `<input class="rl-price-input" type="number" step="0.01" min="0.01"
                value="${Number(item.relistPrice).toFixed(2)}" data-id="${esc(item.listingId)}"
                title="Edit to override the suggested relist price. The server re-checks it against your floor." />
         <div class="inv-change ${item.samePrice ? '' : 'down'}">${
           item.floorLimited ? 'at your floor' : item.samePrice ? 'unchanged' : `${Number(item.relistChangePercent || 0).toFixed(0)}%`}</div>`
      : '<span class="inv-dash">—</span>';

    return `
      <tr class="${item.canRelist ? '' : 'wo-row-muted'}">
        <td class="inv-col-check">${item.canRelist
          ? `<input class="rl-check" type="checkbox" data-id="${esc(item.listingId)}" ${checked} />`
          : ''}</td>
        <td class="inv-cell-title">
          <div class="inv-title-row">
            ${item.imageUrl ? `<img class="inv-thumb" src="${esc(item.imageUrl)}" alt="" loading="lazy" />` : ''}
            <div>
              ${item.url
                ? `<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.title)}</a>`
                : esc(item.title)}
              <div class="inv-sub">${esc(item.sku || item.listingId)}${item.isAuction ? ' · auction' : ''}${
                item.quantity > 1 ? ` · ${item.quantity} unsold` : ''}${
                item.costBasis != null ? ` · paid ${moneyExact(item.costBasis)}` : ' · no cost recorded'}</div>
            </div>
          </div>
        </td>
        <td class="num">${item.daysSinceEnded == null
            ? '<span class="inv-dash" title="eBay reported no end date">—</span>'
            : `${item.daysSinceEnded}d ago${item.daysListed != null ? `<div class="inv-sub">ran ${item.daysListed}d</div>` : ''}`}</td>
        <td class="num">${rlInterestHtml(item)}</td>
        <td class="num">${moneyExact(item.endPrice)}${item.quantity > 1 ? `<div class="inv-sub">×${item.quantity}</div>` : ''}</td>
        <td class="num">${item.marketPrice != null && item.marketComparable !== false
            ? `${moneyExact(item.marketPrice)}<div class="inv-sub">${item.soldCompCount + item.terapeakCompCount} comps</div>`
            : '<span class="inv-dash">—</span>'}</td>
        <td class="num inv-cell-suggested">${priceCell}</td>
        <td class="num">${item.netProfitAtRelist != null
            ? `<span class="${item.netProfitAtRelist > 0 ? 'inv-gap-good' : 'inv-gap-bad'}">${moneyExact(item.netProfitAtRelist)}</span>${
                item.netProfitAtEndPrice != null ? `<div class="inv-sub">${moneyExact(item.netProfitAtEndPrice)} at the old price</div>` : ''}`
            : '<span class="inv-dash" title="Record what you paid in Inventory Health to see net profit">—</span>'}</td>
        <td class="inv-cell-verdict">
          <span class="inv-verdict ${v.cls}">${v.label}</span>
          <div class="inv-note">${esc(item.verdictNote)}</div>
          ${(item.signals || []).length ? `<div class="inv-signals">${item.signals.map(s => esc(s)).join(' ')}</div>` : ''}
          ${item.bidderNote ? `<div class="inv-signals">${esc(item.bidderNote)}</div>` : ''}
          ${rlBiddersHtml(item)}
        </td>
      </tr>`;
  }

  // The bidders live inside the row rather than on their own screen: a lost bidder is a fact about
  // this listing, and splitting them apart is how a seller relists an item they could have just sold.
  function rlBiddersHtml(item) {
    const bidders = item.bidders || [];
    if (bidders.length === 0) return '';

    const sendable = bidders.filter(b => b.canSend);
    const rows = bidders.map(b => {
      const key = `${item.listingId}||${b.userId}`;
      return `
        <label class="rl-bidder ${b.canSend ? '' : 'rl-bidder-muted'}">
          ${b.canSend
            ? `<input class="rl-bidder-check" type="checkbox" data-key="${esc(key)}" ${rlBidders.has(key) ? 'checked' : ''} />`
            : '<span class="rl-bidder-spacer"></span>'}
          <span class="rl-bidder-id">${esc(b.userId || 'hidden bidder')}</span>
          <span class="rl-bidder-price">${b.offerPrice > 0 ? moneyExact(b.offerPrice) : '—'}</span>
          <span class="rl-bidder-note">${esc(b.note)}</span>
        </label>`;
    }).join('');

    return `
      <div class="rl-bidders">
        <div class="rl-bidders-head">
          <strong>${sendable.length} of ${bidders.length} losing bidder${bidders.length === 1 ? '' : 's'} reachable</strong>
          ${sendable.length ? `<button class="btn btn-secondary small rl-sc-send" type="button" data-id="${esc(item.listingId)}">Send Second Chance…</button>` : ''}
        </div>
        ${rows}
      </div>`;
  }

  function rlItemById(listingId) {
    return (rlScan?.items || []).find(i => i.listingId === listingId) || null;
  }

  function onRelistCheck(e) {
    const id = e.target.dataset.id;
    if (e.target.checked) rlSelected.add(id); else rlSelected.delete(id);
    refreshRelistSelectionNote();
  }

  function onBidderCheck(e) {
    const key = e.target.dataset.key;
    if (e.target.checked) rlBidders.add(key); else rlBidders.delete(key);
  }

  function toggleSelectAllRelists(e) {
    const filter = $('rl-filter')?.value || 'ready';
    const isOn = e.target.checked;
    // Only what is on screen — a select-all that ticks rows hidden behind a filter is how someone
    // relists an item they never looked at.
    (rlScan?.items || [])
      .filter(i => rlFilterMatches(i, filter) && i.canRelist)
      .forEach(i => { if (isOn) rlSelected.add(i.listingId); else rlSelected.delete(i.listingId); });
    document.querySelectorAll('.rl-check').forEach(cb => { cb.checked = rlSelected.has(cb.dataset.id); });
    refreshRelistSelectionNote();
  }

  function refreshRelistSelectionNote() {
    const picked = [...rlSelected].map(rlItemById).filter(Boolean);
    const note = $('rl-selection-note');
    if (note) {
      if (picked.length === 0) note.textContent = 'Nothing selected.';
      else {
        const value = picked.reduce((sum, i) => sum + (i.relistPrice || 0) * (i.quantity || 1), 0);
        const net = picked.filter(i => i.netProfitAtRelist != null)
                          .reduce((sum, i) => sum + i.netProfitAtRelist * (i.quantity || 1), 0);
        note.textContent = `${picked.length} listing${picked.length === 1 ? '' : 's'} selected · ` +
          `${moneyExact(value)} back on the site` +
          (net ? ` · ${moneyExact(net)} net if they all sell` : '');
      }
    }
    const disabled = picked.length === 0;
    if ($('rl-preview-btn')) $('rl-preview-btn').disabled = disabled;
    if ($('rl-relist-btn'))  $('rl-relist-btn').disabled  = disabled;
  }

  // An edited price is the seller's call, and the server re-checks it against the floor either way.
  function onRelistPriceEdit(e) {
    const item = rlItemById(e.target.dataset.id);
    if (!item) return;
    const raw = parseFloat(e.target.value);
    const value = isFinite(raw) && raw > 0 ? Math.round(raw * 100) / 100 : (item.relistPrice || item.endPrice);
    e.target.value = value.toFixed(2);
    item.relistPrice = value;
    item.samePrice = Math.abs(value - item.endPrice) < 0.01;
    item.relistChangePercent = item.endPrice > 0 ? ((value - item.endPrice) / item.endPrice) * 100 : 0;
    // The net shown next to it was computed for the old number, so it is cleared rather than left
    // to say something that is no longer true. The confirm screen shows the price, which is exact.
    item.netProfitAtRelist = null;
    const label = e.target.parentElement?.querySelector('.inv-change');
    if (label) label.textContent = 'edited';
    refreshRelistSelectionNote();
  }

  function openRelistConfirm() {
    const picked = [...rlSelected].map(rlItemById).filter(Boolean);
    if (picked.length === 0) return;

    const value = picked.reduce((sum, i) => sum + (i.relistPrice || 0) * (i.quantity || 1), 0);
    const cut   = picked.reduce((sum, i) => sum + Math.max(0, (i.endPrice - (i.relistPrice || 0))) * (i.quantity || 1), 0);
    $('rl-confirm-total').textContent =
      `${picked.length} listing${picked.length === 1 ? '' : 's'} back on eBay · ${moneyExact(value)} of stock` +
      (cut > 0 ? ` · ${moneyExact(cut)} off the prices that already failed` : ' · at the same prices');

    $('rl-confirm-list').innerHTML = picked.map(i => `
      <div class="inv-confirm-row">
        <span class="inv-confirm-title">${esc(i.title)}</span>
        <span class="inv-confirm-prices">${moneyExact(i.endPrice)} → <strong>${moneyExact(i.relistPrice)}</strong>${
          i.samePrice ? ' (unchanged)' : ''}</span>
      </div>`).join('');

    const loss = $('rl-allow-loss');
    if (loss) loss.checked = false;
    $('rl-confirm-overlay')?.classList.remove('hidden');
  }

  async function submitRelists(dryRun) {
    const picked = [...rlSelected].map(rlItemById).filter(Boolean);
    if (picked.length === 0) return;

    const body = {
      items: picked.map(i => ({
        listingId: i.listingId, sku: i.sku, title: i.title,
        newPrice: i.relistPrice, endPrice: i.endPrice,
        quantity: i.quantity || 1, isAuction: !!i.isAuction,
      })),
      minNetProfit: Math.max(0, parseFloat($('rl-min-profit')?.value || '0') || 0),
      dryRun,
      confirmed: !dryRun,
      allowBelowFloor: !dryRun && !!$('rl-allow-loss')?.checked,
    };

    setRlStatus(dryRun ? 'Previewing…' : 'Relisting on eBay…');
    try {
      const res = await fetch('/api/relist/run', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'Relisting failed.');
      renderRelistOutcome(data);
      if (!dryRun && data.relisted > 0) {
        addActivity(`${data.relisted} listing${data.relisted === 1 ? '' : 's'} back on eBay`,
          `${moneyExact(data.listedValue)} of stock relisted from Recover Lost Sales.`);
        // Those listings now have new item numbers, so the board is stale for them.
        await runRelistScan();
      }
    } catch (err) {
      setRlStatus(`Relisting failed: ${errorText(err)}`);
    }
  }

  function renderRelistOutcome(data) {
    const parts = [];
    if (data.dryRun) parts.push(`Preview only — nothing relisted. ${data.items.length} listing${data.items.length === 1 ? '' : 's'} ready, ${moneyExact(data.listedValue)} of stock.`);
    else parts.push(`${data.relisted} back on eBay · ${moneyExact(data.listedValue)} of stock` +
      (data.totalFees > 0 ? ` · ${moneyExact(data.totalFees)} in insertion fees` : ''));
    if (data.skipped) parts.push(`${data.skipped} skipped`);
    if (data.failed)  parts.push(`${data.failed} failed`);

    const problems = (data.items || []).filter(i => i.status === 'skipped' || i.status === 'failed');
    setRlStatus(parts.join(' · ') + (problems.length
      ? ' — ' + problems.map(p => `${p.title}: ${p.message}`).join('; ')
      : ''));
  }

  // ── Second Chance Offers ─────────────────────────────────────────────────
  // Priced at what the bidder already bid, so there is nothing to size and no slider to move. The
  // only decision is whether to send it.

  function selectedBidders() {
    const out = [];
    for (const key of rlBidders) {
      const [listingId, userId] = key.split('||');
      const item = rlItemById(listingId);
      const bidder = (item?.bidders || []).find(b => b.userId === userId);
      if (item && bidder && bidder.canSend) out.push({ item, bidder });
    }
    return out;
  }

  function openSecondChanceConfirm(e) {
    // The button belongs to one listing, so tick that listing's reachable bidders if the seller
    // hasn't ticked any of them — clicking "send" on a row should never open an empty confirm.
    const listingId = e.currentTarget.dataset.id;
    const item = rlItemById(listingId);
    if (item && !(item.bidders || []).some(b => b.canSend && rlBidders.has(`${listingId}||${b.userId}`)))
      (item.bidders || []).filter(b => b.canSend).forEach(b => rlBidders.add(`${listingId}||${b.userId}`));
    document.querySelectorAll('.rl-bidder-check').forEach(cb => { cb.checked = rlBidders.has(cb.dataset.key); });

    const picked = selectedBidders();
    if (picked.length === 0) return;

    const total = picked.reduce((sum, p) => sum + p.bidder.offerPrice, 0);
    $('rl-sc-total').textContent =
      `${picked.length} offer${picked.length === 1 ? '' : 's'} · ${moneyExact(total)} if every one is taken`;

    $('rl-sc-list').innerHTML = picked.map(p => `
      <div class="inv-confirm-row">
        <span class="inv-confirm-title">${esc(p.item.title)}</span>
        <span class="inv-confirm-prices">${esc(p.bidder.userId)} &nbsp; <strong>${moneyExact(p.bidder.offerPrice)}</strong> (their bid)</span>
      </div>`).join('');

    const box = $('rl-sc-message');
    if (box && !box.value) box.value = rlScan?.defaultSellerMessage || '';
    updateScMessageCount();
    const loss = $('rl-sc-allow-loss');
    if (loss) loss.checked = false;
    $('rl-sc-overlay')?.classList.remove('hidden');
  }

  function updateScMessageCount() {
    const box = $('rl-sc-message');
    const counter = $('rl-sc-message-count');
    if (box && counter) counter.textContent = `${box.value.length}/250`;
  }

  async function submitSecondChance(dryRun) {
    const picked = selectedBidders();
    if (picked.length === 0) return;

    const body = {
      items: picked.map(p => ({
        listingId: p.item.listingId, sku: p.item.sku, title: p.item.title,
        bidderUserId: p.bidder.userId, offerPrice: p.bidder.offerPrice,
      })),
      message: $('rl-sc-message')?.value || '',
      durationDays: parseInt($('rl-sc-duration')?.value || '3', 10),
      minNetProfit: Math.max(0, parseFloat($('rl-min-profit')?.value || '0') || 0),
      dryRun,
      confirmed: !dryRun,
      allowBelowFloor: !dryRun && !!$('rl-sc-allow-loss')?.checked,
    };

    setRlStatus(dryRun ? 'Previewing offers…' : 'Sending Second Chance Offers on eBay…');
    try {
      const res = await fetch('/api/relist/second-chance', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'Sending failed.');

      const parts = [];
      if (data.dryRun) parts.push(`Preview only — nothing sent. ${data.items.length} offer${data.items.length === 1 ? '' : 's'} ready.`);
      else parts.push(`${data.sent} Second Chance Offer${data.sent === 1 ? '' : 's'} sent · ${moneyExact(data.offeredValue)} if all are taken`);
      if (data.skipped) parts.push(`${data.skipped} skipped`);
      if (data.failed)  parts.push(`${data.failed} failed`);

      const problems = (data.items || []).filter(i => i.status === 'skipped' || i.status === 'failed');
      setRlStatus(parts.join(' · ') + (problems.length
        ? ' — ' + problems.map(p => `${p.bidderUserId}: ${p.message}`).join('; ')
        : ''));

      if (!dryRun && data.sent > 0) {
        addActivity(`${data.sent} Second Chance Offer${data.sent === 1 ? '' : 's'} sent`,
          `${moneyExact(data.offeredValue)} offered to bidders who lost your ended auctions.`);
        rlBidders.clear();
        await runRelistScan();
      }
    } catch (err) {
      setRlStatus(`Sending failed: ${errorText(err)}`);
    }
  }

  function setRlStatus(text) {
    const el = $('rl-status');
    if (el) el.textContent = text || '';
  }

  // ── Money Made — the earnings tracker ─────────────────────────────────────
  // Everything else in this file renders a forecast. This renders the past, and the difference
  // shows up in three rules the UI has to keep:
  //   * The headline is net profit, never proceeds. Sales with no recorded cost are shown in their
  //     own block with what they WOULD add — the number only ever grows by being made true.
  //   * Every assumption that flatters a row is printed next to the row, not in a footnote.
  //   * Nothing on this page is a placeholder. A seller with no sales gets an empty state, never
  //     a "$0.00 earned" hero, which reads as the app failing rather than as nothing having sold.
  let earnings = null;

  function showEarningsSection() {
    hideOverlaySections();
    $('earnings-section')?.classList.remove('hidden');
    setActiveNavItem('earnings');
    markWorkspaceTabOpen('earnings');
    if (!earnings) loadEarnings();
    // Always re-read, even when the figures are already cached: the importer may have run since
    // this tab was last looked at, and "updated 3 hours ago" is only true if it is re-checked.
    loadEarningsAutoStatus();
    startEarningsAutoPolling();
  }

  function closeEarningsSection() {
    $('er-log-modal')?.classList.add('hidden');
    stopEarningsAutoPolling();
    closeWorkspacePage('earnings');
  }

  function bindEarnings() {
    on('er-close', 'click', closeEarningsSection);
    on('er-home', 'click', goHome);
    on('er-log-btn', 'click', openFlipLogger);
    on('er-log-cancel', 'click', closeFlipLogger);
    on('er-log-cancel-2', 'click', closeFlipLogger);
    on('er-log-save', 'click', saveManualFlip);
    on('dash-earnings-open', 'click', () => { navigateTo('earnings'); });
    on('er-chart-table-toggle', 'click', () => toggleDisclosure('er-chart-table', 'er-chart-table-toggle', 'Show as table', 'Hide table'));
    on('er-ledger-toggle', 'click', () => toggleDisclosure('er-ledger', 'er-ledger-toggle', 'Show all sales', 'Hide all sales'));

    // Live net as the seller types, so the flip they're logging is priced before they commit to it.
    ['er-f-price', 'er-f-cost', 'er-f-shipcharged', 'er-f-shipcost', 'er-f-fee', 'er-f-other', 'er-f-qty']
      .forEach(id => on(id, 'input', updateFlipPreview));

    $('earnings-section')?.addEventListener('click', onEarningsClick);
    // Delegated: the awaiting-cost rows are re-rendered after every save, so a handler bound to
    // the inputs themselves would be thrown away with them.
    $('earnings-section')?.addEventListener('input', e => {
      if (e.target?.classList?.contains('er-cost-pct')) applyDropshipPct(e.target);
    });
    $('earnings-section')?.addEventListener('keydown', e => {
      if (e.key === 'Enter' && e.target?.classList?.contains('er-cost-input')) {
        e.preventDefault();
        saveFlipCost(e.target.dataset.id, e.target.value);
      }
      // Enter in the percentage box saves the row it just priced, so a flat-split seller can
      // type-tab-type down the list without reaching for the mouse.
      if (e.key === 'Enter' && e.target?.classList?.contains('er-cost-pct')) {
        e.preventDefault();
        applyDropshipPct(e.target);
        const box = $('earnings-section').querySelector(`.er-cost-input[data-id="${e.target.dataset.id}"]`);
        saveFlipCost(e.target.dataset.id, box?.value);
      }
      // The every-sale table's own cost cell. Until this existed, a cost could only be typed in
      // the awaiting-cost panel, and that panel only lists sales with NO cost — so a sale
      // recorded at $0.00 (every free-shipping accessory eBay imports that way) dropped off it
      // permanently, counted as pure profit, with nothing on screen to correct it. A cost typed
      // wrong once was equally unreachable.
      if (e.key === 'Enter' && e.target?.classList?.contains('er-cost-cell')) {
        e.preventDefault();
        saveCostCell(e.target);
      }
      if (e.key === 'Escape' && !$('er-log-modal')?.classList.contains('hidden')) closeFlipLogger();
    });
    // Leaving the cell saves it too: a seller who types a figure and clicks the next row has
    // said what they paid just as clearly as one who pressed Enter.
    $('earnings-section')?.addEventListener('focusout', e => {
      if (e.target?.classList?.contains('er-cost-cell')) saveCostCell(e.target);
    }, true);
  }

  // Accepts either a dollar amount ("180", "180.00") or a keep-percentage ("40%"), because a
  // dropshipper never paid a unit cost — they keep a share and the supplier takes the rest. One
  // box rather than two columns: the % form is rare enough per row that a second input on all 60
  // rows would cost more space than it earns.
  function saveCostCell(input) {
    const id = input.dataset.id;
    const raw = (input.value || '').trim();
    if (!id || raw === '') return;
    if (input.dataset.saving === raw) return;   // focusout after Enter would save the same value twice
    input.dataset.saving = raw;

    let value = raw;
    if (raw.endsWith('%')) {
      const cost = costFromKeepPct(Number(input.dataset.unitgross), raw.slice(0, -1));
      if (cost === null) { setEarningsStatus('That percentage needs a sale price to work from.'); return; }
      value = String(cost);
    }
    saveFlipCost(id, value);
  }

  function toggleDisclosure(panelId, buttonId, closedLabel, openLabel) {
    const panel = $(panelId);
    const btn = $(buttonId);
    if (!panel || !btn) return;
    const nowHidden = panel.classList.toggle('hidden');
    btn.textContent = nowHidden ? closedLabel : openLabel;
    btn.setAttribute('aria-expanded', nowHidden ? 'false' : 'true');
  }

  function onEarningsClick(e) {
    const save = e.target.closest?.('.er-cost-save');
    if (save) {
      const input = $('earnings-section').querySelector(`.er-cost-input[data-id="${save.dataset.id}"]`);
      saveFlipCost(save.dataset.id, input?.value);
      return;
    }
    const del = e.target.closest?.('.er-flip-delete');
    if (del) deleteFlip(del.dataset.id, del.dataset.title);
  }

  function setEarningsStatus(text) {
    const el = $('er-status');
    if (el) el.textContent = text || '';
    // The panel that holds it used to carry the import window picker as well. With that gone it is
    // an empty white box on a screen whose whole job is to look like money, so it only takes up
    // room when it has something to say.
    $('er-status-panel')?.classList.toggle('hidden', !text);
  }

  function showEarningsNotice(text, tone) {
    const el = $('er-notice');
    if (!el) return;
    if (!text) { el.classList.add('hidden'); return; }
    el.textContent = text;
    el.classList.toggle('er-notice-good', tone === 'good');
    el.classList.remove('hidden');
  }

  async function loadEarnings(quiet) {
    try {
      const res = await fetch('/api/earnings');
      if (!res.ok) throw new Error('Could not read your earnings.');
      earnings = await res.json();
      renderEarnings();
      renderDashboardEarnings();
    } catch (err) {
      if (!quiet) setEarningsStatus(errorText(err, 'Could not read your earnings.'));
    }
  }

  // ── The automatic import ───────────────────────────────────────────────────
  // There is no import button any more. EarningsAutoImport pulls sold orders as soon as eBay is
  // connected and refreshes every few hours, so the screen's job is not to offer the action — it is
  // to say whether the figures below are current, which is the one thing a button could never tell
  // you. Read-only: this polls a status the server already keeps, and starts nothing.
  let earningsAutoTimer = null;
  const EARNINGS_AUTO_POLL_MS = 30000;

  async function loadEarningsAutoStatus() {
    const el = $('er-auto-status');
    if (!el) return null;

    const { data } = await localFetchJson('/api/earnings/auto-status', 15000);
    if (!data) { el.textContent = ''; return null; }

    renderEarningsAutoStatus(data);
    return data;
  }

  function renderEarningsAutoStatus(s) {
    const el = $('er-auto-status');
    if (!el) return;

    // Not connected is the only state with something for the seller to DO, so it is the only one
    // that reads as a prompt rather than as a report.
    if (!s.ebayConnected) {
      el.textContent = 'Connect eBay and your sales appear here on their own';
      el.className = 'er-auto-status is-waiting';
      return;
    }

    // A failure that has already been retried is not worth alarming anyone about; a failure with
    // nothing behind it is, because then the totals below are empty for a reason.
    if (s.lastStatus && s.lastStatus !== 'ok' && !s.lastSuccessUtc) {
      el.textContent = s.lastMessage || 'eBay could not be reached — retrying on its own';
      el.className = 'er-auto-status is-problem';
      return;
    }

    if (!s.lastSuccessUtc) {
      el.textContent = 'Reading your eBay sales…';
      el.className = 'er-auto-status is-waiting';
      return;
    }

    el.textContent = `✓ Sales updated ${radarAgo(s.lastSuccessUtc)} — this keeps itself current`;
    el.className = 'er-auto-status is-ok';
  }

  function startEarningsAutoPolling() {
    stopEarningsAutoPolling();
    // Only while the screen is open. The importer runs whether anyone is looking or not; this is
    // just the readout, and a readout nobody can see is a timer for nothing.
    earningsAutoTimer = setInterval(async () => {
      if ($('earnings-section')?.classList.contains('hidden')) { stopEarningsAutoPolling(); return; }
      const before = earnings?.summary?.salesAllTime ?? 0;
      const status = await loadEarningsAutoStatus();
      // A finished import means new rows underneath — reload them rather than leaving a screen that
      // says "updated just now" above figures from before the update.
      if (status?.lastSuccessUtc && status.lastSuccessUtc !== lastEarningsSuccessSeen) {
        lastEarningsSuccessSeen = status.lastSuccessUtc;
        if (before >= 0) await loadEarnings(true);
      }
    }, EARNINGS_AUTO_POLL_MS);
  }

  function stopEarningsAutoPolling() {
    if (earningsAutoTimer) { clearInterval(earningsAutoTimer); earningsAutoTimer = null; }
  }

  let lastEarningsSuccessSeen = null;

  function renderEarnings() {
    if (!earnings) return;
    const s = earnings.summary || {};
    const hasSales = (s.salesAllTime || 0) > 0;

    $('er-results')?.classList.toggle('hidden', hasSales);
    $('er-stats')?.classList.toggle('hidden', !hasSales);
    $('er-chart-card')?.classList.toggle('hidden', !hasSales);
    $('er-composition-card')?.classList.toggle('hidden', !hasSales);
    $('er-ledger-card')?.classList.toggle('hidden', !hasSales);
    $('er-honesty')?.classList.toggle('hidden', !hasSales);

    renderEarningsHero(s, hasSales);
    renderEarningsAwaiting();
    if (!hasSales) {
      ['er-best', 'er-returns'].forEach(id => { const el = $(id); if (el) el.innerHTML = ''; });
      return;
    }

    renderEarningsStats(s);
    renderEarningsChart();
    renderEarningsComposition(s);
    renderEarningsLeaders();
    renderEarningsLedger();

    const honesty = $('er-honesty');
    if (honesty) honesty.innerHTML = (earnings.honesty || []).map(line => `<p>${esc(line)}</p>`).join('');
  }

  function renderEarningsHero(s, hasSales) {
    const figure = $('er-hero-month');
    if (figure) {
      figure.textContent = moneyExact(s.netProfitThisMonth || 0);
      figure.classList.toggle('er-negative', (s.netProfitThisMonth || 0) < 0);
    }
    setText('er-hero-alltime', moneyExact(s.netProfitAllTime || 0));
    setText('er-hero-30', moneyExact(s.netProfitLast30Days || 0));
    setText('er-hero-best', s.bestMonthLabel ? `${money(s.bestMonthProfit)} · ${s.bestMonthLabel}` : '—');

    const sub = $('er-hero-sub');
    if (!sub) return;
    if (!hasSales) {
      sub.textContent = 'this month — your eBay sales appear here on their own';
      return;
    }

    const parts = [`this month, across ${s.salesThisMonth || 0} sale${s.salesThisMonth === 1 ? '' : 's'}`];
    if (s.monthOverMonthPercent != null) {
      const up = s.monthOverMonthPercent >= 0;
      parts.push(`${up ? '▲' : '▼'} ${Math.abs(s.monthOverMonthPercent).toFixed(1)}% vs ${moneyExact(s.netProfitLastMonth)} last month`);
    } else if ((s.netProfitLastMonth || 0) === 0 && (s.salesAllTime || 0) > (s.salesThisMonth || 0)) {
      parts.push('nothing recorded last month');
    }
    sub.textContent = parts.join(' · ');
  }

  function renderEarningsStats(s) {
    const el = $('er-stats');
    if (!el) return;

    // Deliberately not a stat tile: "gross sales" next to "net profit" is how a seller ends up
    // quoting the bigger number to themselves. Gross is here as context for the net, sized down.
    const tiles = [
      ['Net profit, all time', moneyExact(s.netProfitAllTime || 0), `${s.salesAllTime || 0} sale${s.salesAllTime === 1 ? '' : 's'} · ${s.unitsAllTime || 0} unit${s.unitsAllTime === 1 ? '' : 's'}`, (s.netProfitAllTime || 0) < 0],
      ['Average per sale', s.averageProfitPerSale != null ? moneyExact(s.averageProfitPerSale) : '—', 'across every sale with a recorded cost', (s.averageProfitPerSale || 0) < 0],
      ['Return on money spent', s.averageRoiPercent != null ? `${s.averageRoiPercent.toFixed(1)}%` : '—', `${moneyExact(s.costOfGoodsAllTime || 0)} of buying turned into profit`, (s.averageRoiPercent || 0) < 0],
      ['Margin', s.averageMarginPercent != null ? `${s.averageMarginPercent.toFixed(1)}%` : '—', 'of every dollar taken in that you kept', (s.averageMarginPercent || 0) < 0],
      ['Gross sales', moneyExact(s.grossRevenueAllTime || 0), 'before fees, shipping and what you paid', false],
      ['eBay fees paid', moneyExact(s.feesAllTime || 0), s.profitFromEstimatedFees ? 'part measured, part estimated' : 'as charged by eBay', false],
    ];

    el.innerHTML = tiles.map(([label, value, note, negative]) => `
      <div class="er-stat">
        <span class="er-stat-label">${esc(label)}</span>
        <span class="er-stat-value${negative ? ' er-negative' : ''}">${esc(value)}</span>
        <span class="er-stat-note">${esc(note)}</span>
      </div>`).join('');
  }

  // Monthly net profit. One series, so no legend — the card title names what is plotted. Columns
  // grow from a single zero baseline and go below it when a month lost money, which is the one
  // thing a "money made" chart must be able to show without arguing about it.
  function renderEarningsChart() {
    const host = $('er-chart');
    const months = earnings?.months || [];
    if (!host || !months.length) return;

    const W = 760, H = 240;
    const padL = 62, padR = 16, padT = 16, padB = 44;
    const plotW = W - padL - padR, plotH = H - padT - padB;

    const values = months.map(m => m.netProfit || 0);
    const maxV = Math.max(0, ...values);
    const minV = Math.min(0, ...values);
    const span = (maxV - minV) || 1;
    const y = v => padT + plotH - ((v - minV) / span) * plotH;
    const zeroY = y(0);

    const band = plotW / months.length;
    const barW = Math.min(24, band - 2); // capped, and the leftover band stays as air

    const ticks = niceTicks(minV, maxV, 4);
    const grid = ticks.map(t => `
      <line x1="${padL}" y1="${y(t).toFixed(1)}" x2="${W - padR}" y2="${y(t).toFixed(1)}" class="er-grid" />
      <text x="${padL - 10}" y="${(y(t) + 4).toFixed(1)}" class="er-axis er-axis-y">${money(t)}</text>`).join('');

    const best = Math.max(...values);
    const bars = months.map((m, i) => {
      const v = m.netProfit || 0;
      const x = padL + i * band + (band - barW) / 2;
      const top = v >= 0 ? y(v) : zeroY;
      const h = Math.max(v === 0 ? 0 : 1.5, Math.abs(y(v) - zeroY));
      const cls = v < 0 ? 'er-bar er-bar-loss' : 'er-bar';
      // 4px rounded data-end, square at the baseline — rounding both ends makes a short bar read
      // as a pill rather than as a quantity.
      const r = Math.min(4, h);
      const path = v >= 0
        ? `M${x} ${top + h} L${x} ${top + r} Q${x} ${top} ${x + r} ${top} L${x + barW - r} ${top} Q${x + barW} ${top} ${x + barW} ${top + r} L${x + barW} ${top + h} Z`
        : `M${x} ${top} L${x} ${top + h - r} Q${x} ${top + h} ${x + r} ${top + h} L${x + barW - r} ${top + h} Q${x + barW} ${top + h} ${x + barW} ${top + h - r} L${x + barW} ${top} Z`;

      // Two lines: the month, then the money. The shared chart tooltip renders the first line as
      // its title, which is what makes every tooltip in the app read the same way.
      const tip = `${m.label}\n${moneyExact(v)} net from ${m.sales} sale${m.sales === 1 ? '' : 's'}`
        + (m.salesAwaitingCost ? `\n${m.salesAwaitingCost} more still waiting on a cost` : '');

      // Only the peak is directly labelled. A value on every column is noise, and the tooltip and
      // the table view carry the rest.
      const label = (v === best && v > 0)
        ? `<text x="${(x + barW / 2).toFixed(1)}" y="${(y(v) - 8).toFixed(1)}" class="er-bar-label">${money(v)}</text>`
        : '';

      return `<g class="er-bar-group viz-band" tabindex="0" role="img"
          aria-label="${esc(tip.replaceAll('\n', '. '))}" data-viz-tip="${esc(tip)}">
        <rect x="${(padL + i * band).toFixed(1)}" y="${padT}" width="${band.toFixed(1)}" height="${plotH}" class="er-bar-hit viz-hit" />
        <path d="${path}" class="${cls}" />${label}
        <text x="${(x + barW / 2).toFixed(1)}" y="${H - 26}" class="er-axis er-axis-x">${esc(m.label.split(' ')[0])}</text>
        <text x="${(x + barW / 2).toFixed(1)}" y="${H - 14}" class="er-axis er-axis-x er-axis-year">${esc(m.label.split(' ')[1] || '')}</text>
      </g>`;
    }).join('');

    host.innerHTML = `<svg viewBox="0 0 ${W} ${H}" class="er-chart-svg" role="img"
        aria-label="Net profit by month. Use Show as table for the values.">
      ${grid}
      ${bars}
      <line x1="${padL}" y1="${zeroY.toFixed(1)}" x2="${W - padR}" y2="${zeroY.toFixed(1)}" class="er-zero" />
    </svg>`;

    const table = $('er-chart-table');
    if (table) table.innerHTML = `
      <table class="er-table">
        <thead><tr><th>Month</th><th class="num">Net profit</th><th class="num">Gross sales</th><th class="num">Sales</th><th class="num">Awaiting cost</th></tr></thead>
        <tbody>${months.map(m => `<tr>
          <td>${esc(m.label)}${m.isCurrentMonth ? ' <span class="er-chip">so far</span>' : ''}</td>
          <td class="num${(m.netProfit || 0) < 0 ? ' er-negative' : ''}">${moneyExact(m.netProfit || 0)}</td>
          <td class="num">${moneyExact(m.grossRevenue || 0)}</td>
          <td class="num">${m.sales || 0}</td>
          <td class="num">${m.salesAwaitingCost || 0}</td>
        </tr>`).join('')}</tbody>
      </table>`;
  }

  // Where every dollar taken in ended up. The stat tiles report gross, fees, cost and net as six
  // separate figures; this is the one relationship between them, which is the only thing a seller
  // actually wants from those numbers — how much of what came in they kept.
  //
  // Two honesty rules govern it, and they are why this is not a two-line chart:
  //
  //   * Net profit only counts sales whose cost is known. So gross minus fees, shipping and cost
  //     of goods does NOT equal net on a real account — the difference is proceeds sitting behind
  //     a missing cost. That difference is drawn, in grey, as its own segment. Silently folding it
  //     into profit is exactly the lie this whole screen exists not to tell.
  //   * A loss cannot be a share of revenue. When costs came to more than everything taken in,
  //     there is no whole to divide, and the card says that in a sentence rather than drawing a
  //     bar whose parts sum past 100%.
  function renderEarningsComposition(s) {
    const host = $('er-composition');
    const sub = $('er-composition-sub');
    if (!host) return;

    const gross    = Number(s.grossRevenueAllTime) || 0;
    const fees     = Math.max(0, Number(s.feesAllTime) || 0);
    const shipping = Math.max(0, Number(s.shippingCostAllTime) || 0);
    const cogs     = Math.max(0, Number(s.costOfGoodsAllTime) || 0);
    const net      = Number(s.netProfitAllTime) || 0;

    if (gross <= 0 || net < 0) {
      host.innerHTML = '';
      if (sub) {
        sub.textContent = net < 0
          ? 'Costs came to more than everything taken in, so there is no share of revenue to break down yet. The chart above shows which months that happened in.'
          : 'Nothing has come in yet, so there is nothing to break down.';
      }
      return;
    }

    // Whatever the four measured parts do not account for. On an account where every sale has a
    // cost this rounds to nothing and the segment never renders.
    const unaccounted = Math.max(0, gross - fees - shipping - cogs - net);
    const kept = (net / gross) * 100;

    const segments = [
      { name: 'What you paid for it', value: cogs, slot: 1, tip: 'The landed cost of the goods that sold' },
      { name: 'eBay fees', value: fees, slot: 2, tip: s.profitFromEstimatedFees ? 'Part measured from eBay, part estimated from your fee settings' : "eBay's own figures" },
      { name: 'Shipping you paid', value: shipping, slot: 3, tip: 'What it cost you to send it, not what the buyer paid' },
      { name: 'Waiting on a cost', value: unaccounted, slot: 'none', tip: 'Proceeds from sales with no cost recorded — this is not profit until you enter what you paid' },
      { name: 'Net profit, kept', value: net, slot: 4, tip: 'What was left after every cost above' },
    ].filter(seg => seg.value > 0);

    host.innerHTML = vizStack(segments, { total: gross });
    vizFitSegmentLabels(host);

    if (sub) {
      sub.textContent = `Of ${moneyExact(gross)} taken in, you kept ${moneyExact(net)} — ${kept.toFixed(1)}¢ of every dollar.`
        + (unaccounted > 0
          ? ` ${moneyExact(unaccounted)} is still waiting on a cost and is not counted as profit.`
          : '');
    }
  }

  // Round tick values so the axis reads 0 / 500 / 1,000 rather than 0 / 487 / 974.
  function niceTicks(min, max, count) {
    const span = (max - min) || 1;
    const raw = span / Math.max(1, count);
    const mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= raw) || mag * 10;
    const ticks = [];
    for (let t = Math.ceil(min / step) * step; t <= max + step / 2; t += step) ticks.push(Math.round(t * 100) / 100);
    if (!ticks.includes(0) && min <= 0 && max >= 0) ticks.push(0);
    return ticks;
  }

  function renderEarningsLeaders() {
    const losses = earnings.worstFlips || [];

    renderFlipList('er-best', earnings.bestFlips || [], f => moneyExact(f.netProfit || 0),
      (earnings.summary?.salesAwaitingCost || 0) > 0
        ? 'Nothing with a recorded cost has turned a profit yet. Enter costs above and the winners show up here.'
        : 'No sale has turned a profit yet.');

    // The second column changes job when there is nothing to celebrate. A "best returns" list is
    // meaningless with no profitable sales, and the losses are the rows worth reading instead.
    const showLosses = !(earnings.bestReturns || []).length && losses.length > 0;
    setText('er-returns-title', showLosses ? '🩹 Sold below cost' : '📈 Best returns');

    if (showLosses) {
      renderFlipList('er-returns', losses, f => moneyExact(f.netProfit || 0), '');
      return;
    }

    renderFlipList('er-returns', earnings.bestReturns || [], f => `${(f.roiPercent || 0).toFixed(0)}%`,
      'No sale yet clears $10 profit with a recorded cost — that is the bar for a return worth repeating.');
  }

  function renderFlipList(hostId, flips, valueOf, emptyText) {
    const el = $(hostId);
    if (!el) return;
    if (!flips.length) { el.innerHTML = `<p class="er-empty">${esc(emptyText)}</p>`; return; }

    el.innerHTML = flips.map(f => `
      <div class="er-row">
        <div class="er-row-main">
          <span class="er-row-title" title="${esc(f.title)}">${esc(f.title)}</span>
          <span class="er-row-meta">${esc(shortDate(f.soldUtc))} · sold ${moneyExact(f.grossRevenue || 0)}${f.costOfGoods != null ? ` · paid ${moneyExact(f.costOfGoods)}` : ''}${f.source === 'manual' ? ' · logged by you' : ''}</span>
        </div>
        <span class="er-row-value${(f.netProfit || 0) < 0 ? ' er-negative' : ''}">${esc(valueOf(f))}</span>
      </div>`).join('');
  }

  // Every sale, checkable against the seller's own eBay statement. A running total nobody can audit
  // is a marketing claim; this is what turns it into a record. The "Fee" column says whether eBay
  // reported the number or the app estimated it, per row, because that is exactly the distinction
  // someone reconciling against a payout will want.
  function renderEarningsLedger() {
    const el = $('er-ledger');
    const flips = earnings?.flips || [];
    if (!el) return;

    const title = $('er-ledger-title');
    if (title) title.textContent = `${flips.length} sale${flips.length === 1 ? '' : 's'} on record`;

    el.innerHTML = `
      <table class="er-table">
        <thead><tr>
          <th>Sold</th><th>Item</th><th class="num">Took in</th><th class="num">Fee</th>
          <th class="num">You paid</th><th class="num">Net</th><th>Source</th><th></th>
        </tr></thead>
        <tbody>${flips.map(f => {
          const caveats = (f.caveats || []).join(' ');
          const netCell = f.netProfit == null
            ? '<span class="er-muted">needs a cost</span>'
            : `${moneyExact(f.netProfit)}${f.roiPercent != null ? ` <span class="er-muted">${f.roiPercent.toFixed(0)}%</span>` : ''}`;
          return `<tr${f.status !== 'paid' ? ' class="er-row-void"' : ''}>
            <td>${esc(shortDate(f.soldUtc))}</td>
            <td class="er-cell-item" title="${esc(f.title)}${caveats ? ' — ' + esc(caveats) : ''}">${esc(f.title)}${f.quantity > 1 ? ` <span class="er-muted">×${f.quantity}</span>` : ''}${f.status !== 'paid' ? ` <span class="er-chip">${esc(f.status)}</span>` : ''}</td>
            <td class="num">${moneyExact(f.grossRevenue || 0)}</td>
            <td class="num" title="${f.feesAreActual ? "eBay's own figure for this sale" : 'Estimated from your fee settings — eBay did not report a fee'}">${moneyExact(f.fees || 0)}${f.feesAreActual ? '' : ' <span class="er-muted">est</span>'}</td>
            <td class="num"><input class="er-cost-cell" data-id="${f.id}" data-unitgross="${unitGross(f)}"
                   type="text" inputmode="decimal" value="${f.costOfGoods != null ? Number(f.costOfGoods).toFixed(2) : ''}"
                   placeholder="—" aria-label="What you paid for ${esc(f.title)}"
                   title="What you paid, per unit. Type a dollar amount, or a percentage like 40% for the share of the sale you keep. Enter to save." /></td>
            <td class="num${(f.netProfit || 0) < 0 ? ' er-negative' : ''}">${netCell}</td>
            <td>${f.source === 'ebay' ? 'eBay' : 'You'}</td>
            <td class="num"><button class="er-flip-delete" data-id="${f.id}" data-title="${esc(f.title)}" type="button" title="Stop counting this sale" aria-label="Remove ${esc(f.title)} from earnings">✕</button></td>
          </tr>`;
        }).join('')}</tbody>
      </table>`;
  }

  // The growth path, and the only ask this page makes of the seller. Framed as money they have
  // already earned but haven't proved, because that is exactly what it is.
  function renderEarningsAwaiting() {
    const el = $('er-awaiting');
    if (!el) return;
    const s = earnings?.summary || {};
    const pending = earnings?.awaitingCost || [];

    if (!pending.length) { el.classList.add('hidden'); el.innerHTML = ''; return; }

    el.classList.remove('hidden');

    // Two kinds of row land here and they are not the same claim. One has no cost at all and is
    // genuinely missing from the totals. The other is recorded at $0.00 — usually an eBay import
    // of something that shipped free — and IS in the totals, counted as pure profit. Saying
    // "isn't counted above" over a list containing both would be false for half of it.
    const uncounted = pending.filter(f => f.netProfit == null);
    const zeroCost = pending.filter(f => f.netProfit != null);
    const title = uncounted.length
      ? `${moneyExact(s.proceedsAwaitingCost || 0)} after fees isn't counted above`
      : `${zeroCost.length} sale${zeroCost.length === 1 ? '' : 's'} counted as pure profit`;
    const sub = [
      uncounted.length
        ? `${uncounted.length} sale${uncounted.length === 1 ? ' has' : 's have'} no record of what you paid. Type the cost and the profit lands in your total.`
        : '',
      zeroCost.length
        ? `${zeroCost.length} sale${zeroCost.length === 1 ? ' is' : 's are'} recorded at $0.00, so ${zeroCost.length === 1 ? 'it is' : 'they are'} being counted as if the goods were free — type what ${zeroCost.length === 1 ? 'it' : 'they'} actually cost, or save $0.00 to confirm ${zeroCost.length === 1 ? 'it was' : 'they were'} free and stop being asked.`
        : '',
      pending.length < s.salesAwaitingCost
        ? `Showing the ${pending.length} biggest; the rest appear as you work through these.`
        : '',
    ].filter(Boolean).join(' ');

    el.innerHTML = `
      <div class="er-awaiting-head">
        <div>
          <p class="er-awaiting-title">${title}</p>
          <p class="er-awaiting-sub">${sub}</p>
        </div>
      </div>
      <div class="er-awaiting-list">
        ${pending.map(f => `
          <div class="er-awaiting-row">
            <div class="er-row-main">
              <span class="er-row-title" title="${esc(f.title)}">${esc(f.title)}</span>
              <span class="er-row-meta">${esc(shortDate(f.soldUtc))} · sold ${moneyExact(f.grossRevenue || 0)} · ${moneyExact(f.netProceeds || 0)} after fees${f.quantity > 1 ? ` · ${f.quantity} units` : ''}${f.netProfit != null ? ' · <span class="er-row-flag">counted at $0.00 cost</span>' : ''}</span>
            </div>
            <div class="er-cost-entry">
              <label class="er-cost-label" for="er-cost-${f.id}">You paid ($ each)</label>
              <input id="er-cost-${f.id}" class="er-cost-input" data-id="${f.id}" type="number" min="0" step="0.01" placeholder="0.00" />
              <button class="btn btn-secondary small er-cost-save" data-id="${f.id}" type="button">Save</button>
              <!-- Dropshipping doesn't have a per-unit cost the seller ever paid — they keep a cut
                   of the sale and the supplier takes the rest. Typing that cut fills the box above
                   with what the goods effectively cost, so the same Save writes the same field and
                   nothing downstream has to learn a second kind of cost. -->
              <label class="er-cost-label er-pct-label" for="er-pct-${f.id}">Dropshippers — % of the sale you keep</label>
              <input id="er-pct-${f.id}" class="er-cost-pct" data-id="${f.id}"
                     data-unitgross="${unitGross(f)}" type="number" min="0" max="100" step="0.5" placeholder="40" />
              <span class="er-pct-hint" data-hint="${f.id}"></span>
            </div>
          </div>`).join('')}
      </div>`;

    prefillDropshipPct();
  }

  // ── Dropship percentage ───────────────────────────────────────────────────
  // A dropshipper never pays a unit cost — they keep a share of each sale and the supplier keeps
  // the rest. So the cost of the goods IS the rest: keep 40% of a $2,100 sale and those goods
  // effectively cost $1,260. Computing it from the sale price rather than asking for a dollar
  // figure is the difference between a number they know and one they'd have to work out per row.
  //
  // It writes into the existing "you paid" box rather than being a second kind of cost, so the
  // server, the profit maths and Inventory Health all stay exactly as they were.
  const DROPSHIP_PCT_KEY = 'dropshipKeepPct';

  function unitGross(f) {
    const qty = Math.max(1, Number(f.quantity) || 1);
    return (Number(f.grossRevenue) || 0) / qty;
  }

  // Percentage is OF THE SALE PRICE, before eBay's fee — that is how a dropship split is written,
  // and quietly using the after-fee figure would understate the cost on every row.
  function costFromKeepPct(unitGrossValue, keepPct) {
    const pct = Math.min(100, Math.max(0, Number(keepPct)));
    if (!isFinite(pct) || !isFinite(unitGrossValue) || unitGrossValue <= 0) return null;
    return Math.round(unitGrossValue * (1 - pct / 100) * 100) / 100;
  }

  function applyDropshipPct(input) {
    const id = input.dataset.id;
    const gross = Number(input.dataset.unitgross);
    const hint = $('earnings-section')?.querySelector(`.er-pct-hint[data-hint="${id}"]`);
    const costBox = $('earnings-section')?.querySelector(`.er-cost-input[data-id="${id}"]`);
    const raw = input.value.trim();

    if (raw === '') {
      if (hint) hint.textContent = '';
      return;
    }

    const cost = costFromKeepPct(gross, raw);
    if (cost === null) {
      if (hint) hint.textContent = '';
      return;
    }

    // Remembered so a seller on a flat split types it once, not once per sale.
    localStorage.setItem(DROPSHIP_PCT_KEY, raw);

    if (costBox) costBox.value = cost.toFixed(2);
    if (hint) {
      hint.textContent = `Keeping ${Number(raw)}% of ${moneyExact(gross)} → cost ${moneyExact(cost)} each. Press Save.`;
    }
  }

  // Prefill every row with the remembered split, without touching the cost box — filling in 48
  // dollar figures the seller never typed would look like the app inventing costs.
  function prefillDropshipPct() {
    const saved = localStorage.getItem(DROPSHIP_PCT_KEY);
    if (!saved) return;
    $('earnings-section')?.querySelectorAll('.er-cost-pct').forEach(el => {
      if (!el.value) el.placeholder = saved;
    });
  }

  async function saveFlipCost(id, raw) {
    const value = parseFloat(raw);
    if (!id || !isFinite(value) || value < 0) { setEarningsStatus('Enter what you paid for it — zero or more.'); return; }

    try {
      const { res, body } = await safePost('/api/earnings/cost', { id: Number(id), unitCost: value });
      if (!res.ok) throw new Error(typeof body === 'string' ? body : (body.error || 'That cost could not be saved.'));
      const before = earnings?.summary?.netProfitAllTime || 0;
      earnings = body.earnings;
      renderEarnings();
      renderDashboardEarnings();

      // One cost basis can price several sales of the same listing at once. That is the right
      // answer — but moving thousands of dollars off one typed number without saying how many
      // sales it landed on is how a seller decides the total is made up.
      const also = body.alsoAffected || 0;
      const scope = also
        ? ` It also priced ${also} other sale${also === 1 ? '' : 's'} of the same item.`
        : '';
      const delta = (earnings.summary?.netProfitAllTime || 0) - before;
      setEarningsStatus((delta >= 0
        ? `Cost saved — ${moneyExact(delta)} of real profit added to your total.`
        : `Cost saved — that works out to a ${moneyExact(Math.abs(delta))} loss, and the total now says so.`) + scope);
    } catch (err) {
      setEarningsStatus(errorText(err, 'That cost could not be saved.'));
    }
  }

  async function deleteFlip(id, title) {
    if (!id) return;
    if (!confirm(`Remove "${title || 'this sale'}" from your earnings? It stays on eBay — this only stops counting it here.`)) return;
    try {
      const res = await fetch(`/api/earnings/flips/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('That sale could not be removed.');
      earnings = await res.json();
      renderEarnings();
      renderDashboardEarnings();
      setEarningsStatus('Removed.');
    } catch (err) {
      setEarningsStatus(errorText(err, 'That sale could not be removed.'));
    }
  }

  function openFlipLogger() {
    const modal = $('er-log-modal');
    if (!modal) return;
    ['er-f-title', 'er-f-price', 'er-f-cost', 'er-f-shipcharged', 'er-f-shipcost', 'er-f-fee', 'er-f-other']
      .forEach(id => { const el = $(id); if (el) el.value = ''; });
    setVal('er-f-qty', '1');
    const today = new Date();
    setVal('er-f-date', `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`);
    $('er-log-error')?.classList.add('hidden');
    updateFlipPreview();
    modal.classList.remove('hidden');
    $('er-f-title')?.focus();
  }

  function closeFlipLogger() { $('er-log-modal')?.classList.add('hidden'); }

  function updateFlipPreview() {
    const el = $('er-log-preview');
    if (!el) return;
    const num = id => parseFloat($(id)?.value) || 0;
    const price = num('er-f-price'), cost = num('er-f-cost');
    if (price <= 0) { el.textContent = 'Fill in what it sold for and what you paid to see the net.'; el.classList.remove('er-negative'); return; }

    const qty = Math.max(1, parseInt($('er-f-qty')?.value, 10) || 1);
    const shipCharged = num('er-f-shipcharged'), shipCost = num('er-f-shipcost');
    const feeRaw = $('er-f-fee')?.value;
    // Mirrors the server's fee estimate closely enough to be useful while typing; the saved figure
    // is always the server's, computed from the seller's real Fees & Costs settings.
    const fee = feeRaw !== '' && feeRaw != null ? (parseFloat(feeRaw) || 0) : (price + shipCharged) * 0.1325 + 0.40;
    const net = (price + shipCharged) - fee - shipCost - num('er-f-other') - cost * qty;

    el.classList.toggle('er-negative', net < 0);
    el.textContent = cost > 0
      ? `Net ${moneyExact(net)}${cost > 0 ? ` · ${((net / (cost * qty)) * 100).toFixed(0)}% return on the ${moneyExact(cost * qty)} you paid` : ''}${feeRaw ? '' : ` (fees estimated at ${moneyExact(fee)})`}`
      : `${moneyExact(net + 0)} after fees — add what you paid to turn this into profit.`;
  }

  async function saveManualFlip() {
    const err = $('er-log-error');
    const num = id => { const v = $(id)?.value; return v === '' || v == null ? null : (parseFloat(v) || 0); };
    const title = ($('er-f-title')?.value || '').trim();

    if (!title) { showFlipError('What did you sell?'); return; }
    const price = num('er-f-price');
    if (price == null || price < 0) { showFlipError('What did it sell for?'); return; }

    const dateVal = $('er-f-date')?.value;
    const payload = {
      title,
      // Parsed as local midday rather than midnight UTC: a sale on the 1st logged from a western
      // timezone would otherwise land in the previous month and vanish from "this month".
      soldUtc: dateVal ? new Date(`${dateVal}T12:00:00`).toISOString() : new Date().toISOString(),
      quantity: Math.max(1, parseInt($('er-f-qty')?.value, 10) || 1),
      salePrice: price,
      shippingCharged: num('er-f-shipcharged') || 0,
      shippingCost: num('er-f-shipcost'),
      marketplaceFee: num('er-f-fee'),
      otherCosts: num('er-f-other') || 0,
      unitCost: num('er-f-cost'),
      status: 'paid',
    };

    const btn = $('er-log-save');
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    try {
      const { res, body } = await safePost('/api/earnings/flips', payload);
      if (!res.ok) throw new Error(typeof body === 'string' ? body : (body.error || 'That flip could not be saved.'));
      earnings = body;
      renderEarnings();
      renderDashboardEarnings();
      closeFlipLogger();
      setEarningsStatus(`"${title}" added to your earnings.`);
    } catch (e) {
      showFlipError(errorText(e, 'That flip could not be saved.'));
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Save this flip'; }
    }
    if (err) { /* keeps the error visible until the next attempt */ }
  }

  function showFlipError(message) {
    const el = $('er-log-error');
    if (!el) return;
    el.textContent = message;
    el.classList.remove('hidden');
  }

  // The front-page band. Only ever rendered when there is a real, non-zero figure behind it.
  function renderDashboardEarnings() {
    const band = $('dash-earnings');
    if (!band) return;
    const s = earnings?.summary;
    if (!s || (s.salesAllTime || 0) === 0 || (s.netProfitAllTime || 0) === 0) { band.classList.add('hidden'); return; }

    band.classList.remove('hidden');
    const figure = $('dash-earnings-figure');
    if (figure) {
      figure.classList.toggle('er-negative', s.netProfitAllTime < 0);
      countUp(figure, s.netProfitAllTime, moneyExact);
    }

    const bits = [`${moneyExact(s.netProfitThisMonth || 0)} this month`, `${s.salesAllTime} sale${s.salesAllTime === 1 ? '' : 's'} tracked`];
    if (s.salesAwaitingCost) bits.push(`${moneyExact(s.proceedsAwaitingCost || 0)} still waiting on a cost`);
    setText('dash-earnings-sub', bits.join(' · '));

    renderEarningsSparkline();
  }

  // 12-point sparkline in the stat-tile idiom: de-emphasised history, the current month in the
  // accent. No axes — it carries shape, and the page it links to carries the numbers.
  function renderEarningsSparkline() {
    const host = $('dash-earnings-spark');
    const months = earnings?.months || [];
    if (!host || months.length < 2) { if (host) host.innerHTML = ''; return; }

    const W = 180, H = 44, pad = 4;
    const values = months.map(m => m.netProfit || 0);
    const max = Math.max(0, ...values), min = Math.min(0, ...values);
    const span = (max - min) || 1;
    const band = (W - pad * 2) / months.length;
    const barW = Math.max(2, band - 3);

    const zeroY = pad + (H - pad * 2) * (1 - (0 - min) / span);
    const bars = months.map((m, i) => {
      const v = values[i];
      const vy = pad + (H - pad * 2) * (1 - (v - min) / span);
      const top = Math.min(vy, zeroY), h = Math.max(1, Math.abs(vy - zeroY));
      const cls = m.isCurrentMonth ? 'er-spark-bar er-spark-now' : (v < 0 ? 'er-spark-bar er-spark-loss' : 'er-spark-bar');
      return `<rect x="${(pad + i * band).toFixed(1)}" y="${top.toFixed(1)}" width="${barW.toFixed(1)}" height="${h.toFixed(1)}" rx="1" class="${cls}" />`;
    }).join('');

    host.innerHTML = `<svg viewBox="0 0 ${W} ${H}" class="er-spark-svg" aria-hidden="true">${bars}</svg>`;
  }

  function shortDate(value) {
    if (!value) return '';
    const d = new Date(value);
    return isNaN(d) ? '' : d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
  }

  // ── The Tax Pack ──────────────────────────────────────────────────────────
  // Money Made renders what the seller earned. This renders the share of it that was never theirs,
  // and it is allowed to print a different net profit for the same year — see TaxPackCalculator for
  // why both are right. Three rules the UI has to keep on top of that:
  //   * The hero is the SET-ASIDE, not the bill. It is the only number here that is an instruction:
  //     move this much out of the account. A bill is something to dread; a set-aside is something
  //     to do, and the seller who does it monthly never has the bad February.
  //   * The block that makes the total go DOWN leads. Sales with no recorded cost are priced at the
  //     top of the page, above everything they explain, because that is the one thing on this
  //     screen the seller can fix today.
  //   * Every figure says what it assumed, next to itself. A tax number with an unexplained gap in
  //     it doesn't read as cautious — it reads as broken, and one distrusted figure here poisons
  //     all of them.
  let taxPack = null;
  let taxYearWanted = null;

  function showTaxSection() {
    hideOverlaySections();
    $('tax-section')?.classList.remove('hidden');
    setActiveNavItem('tax');
    markWorkspaceTabOpen('tax');
    if (!taxPack) loadTaxPack();
  }

  function closeTaxSection() { closeWorkspacePage('tax'); }

  function bindTax() {
    on('tx-close', 'click', closeTaxSection);
    on('tx-home', 'click', goHome);
    on('tx-year', 'change', e => { taxYearWanted = e.target.value; loadTaxPack(); });
    on('tx-rate-save', 'click', saveTaxRate);
    // Enter in the bracket box applies it. Typing a number and pressing Enter is what everybody
    // does, and a screen that silently ignores it looks like it didn't take the change.
    on('tx-rate', 'keydown', e => { if (e.key === 'Enter') { e.preventDefault(); saveTaxRate(); } });
    on('tx-schedule-toggle', 'click', () => {
      const host = $('tx-schedule'), btn = $('tx-schedule-toggle');
      if (!host || !btn) return;
      const bare = host.classList.toggle('tx-schedule-bare');
      btn.textContent = bare ? 'Show workings' : 'Hide workings';
      btn.setAttribute('aria-expanded', bare ? 'false' : 'true');
    });

    // Delegated, because the prompt inside the cost-gap block is re-rendered on every reload.
    $('tax-section')?.addEventListener('click', e => {
      if (e.target.closest?.('.tx-gap-action')) navigateTo('earnings');
    });
  }

  async function loadTaxPack(quiet) {
    const query = taxYearWanted ? `?year=${encodeURIComponent(taxYearWanted)}` : '';
    try {
      const res = await fetch('/api/tax' + query);
      if (!res.ok) throw new Error('Could not work out your tax position.');
      taxPack = await res.json();
      renderTaxPack();
    } catch (err) {
      if (!quiet) setTaxRateNote(errorText(err, 'Could not work out your tax position.'), true);
    }
  }

  async function saveTaxRate() {
    const raw = parseFloat($('tx-rate')?.value);
    if (!isFinite(raw) || raw < 0 || raw > 50) {
      setTaxRateNote('Enter your bracket as a percentage between 0 and 50.', true);
      return;
    }

    const query = taxYearWanted ? `?year=${encodeURIComponent(taxYearWanted)}` : '';
    try {
      const res = await fetch('/api/tax/rate' + query, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ incomeTaxRatePercent: raw }),
      });
      if (!res.ok) throw new Error(await res.text() || 'That rate could not be saved.');
      taxPack = await res.json();
      renderTaxPack();
    } catch (err) {
      setTaxRateNote(errorText(err, 'That rate could not be saved.'), true);
    }
  }

  function setTaxRateNote(text, isError) {
    const el = $('tx-rate-note');
    if (!el) return;
    el.textContent = text;
    el.classList.toggle('tx-rate-note-error', !!isError);
  }

  function renderTaxPack() {
    if (!taxPack) return;
    const p = taxPack;
    const has = !!p.hasSales;

    $('tx-results')?.classList.toggle('hidden', has);
    $('tx-quarters-card')?.classList.toggle('hidden', !has);
    $('tx-schedule-card')?.classList.toggle('hidden', !has);
    $('tx-1099-card')?.classList.toggle('hidden', !has);
    $('tx-honesty')?.classList.toggle('hidden', !(p.honesty || []).length);

    renderTaxYearPicker(p);
    renderTaxHero(p, has);
    renderTaxGap(p, has);

    const rate = $('tx-rate');
    if (rate && document.activeElement !== rate) rate.value = p.assumptions?.incomeTaxRatePercent ?? 12;

    setTaxRateNote(has
      ? `Every provable dollar of expense is worth about ${(p.assumptions?.deductionValuePercent ?? 0).toFixed(1)}¢ off this bill at your rate. Self-employment tax is added on top automatically — it is the same 15.3% for everybody.`
      : 'Most side-income resellers sit at 12% or 22%. Self-employment tax is added on top automatically — it is the same 15.3% for everybody.', false);

    const honesty = $('tx-honesty');
    if (honesty) honesty.innerHTML = (p.honesty || []).map(line => `<p>${esc(line)}</p>`).join('');

    if (!has) {
      ['tx-quarters', 'tx-schedule', 'tx-1099'].forEach(id => { const el = $(id); if (el) el.innerHTML = ''; });
      return;
    }

    renderTaxQuarters(p);
    renderTaxScheduleC(p);
    renderTax1099(p);
  }

  // The picker doubles as the export target, so the two links always hand over the year on screen
  // rather than whatever the server last defaulted to.
  function renderTaxYearPicker(p) {
    const select = $('tx-year');
    if (select) {
      const years = (p.availableYears || [p.year]);
      select.innerHTML = years.map(y =>
        `<option value="${y}"${y === p.year ? ' selected' : ''}>${y}</option>`).join('');
    }

    const summary = $('tx-export-summary'), ledger = $('tx-export-ledger');
    if (summary) summary.href = `/api/tax/export?kind=summary&year=${p.year}`;
    if (ledger) ledger.href = `/api/tax/export?kind=ledger&year=${p.year}`;
    [summary, ledger].forEach(a => a?.classList.toggle('is-disabled', !p.hasSales));
  }

  function renderTaxHero(p, has) {
    setText('tx-hero-figure', moneyExact(p.totalTax || 0));
    setText('tx-hero-profit', moneyExact(p.netProfit || 0));

    const sub = $('tx-hero-sub');
    if (sub) {
      sub.textContent = !has
        ? `nothing is on record for ${p.year} yet — your eBay sales arrive on their own`
        : `${p.yearInProgress ? 'so far in' : 'for'} ${p.year} — ${moneyExact(p.selfEmploymentTax || 0)} self-employment tax and ${moneyExact(p.incomeTax || 0)} income tax`;
    }

    // Cents in the dollar rather than a percentage: "27¢ of every profit dollar" is a rule a seller
    // can apply to the next sale without a calculator, which a "27.4% effective rate" is not.
    setText('tx-hero-rate', has && (p.netProfit || 0) > 0
      ? `${Math.round(p.effectiveRatePercent || 0)}¢` : '—');

    const next = (p.quarters || []).find(q => !q.isPast);
    setText('tx-hero-due', has && next
      ? `${moneyExact(next.setAside)} · ${taxDueLabel(next.dueDate)}`
      : '—');
  }

  // A due date is a calendar date, not an instant. The server stamps it in the seller's offset at
  // the time of the request, so a January payment computed in July arrives an hour off in standard
  // time and shortDate() renders "Jan 14" for the 15th. Read the date parts straight off the
  // string and no offset can move a payment by a day.
  function taxDueLabel(value) {
    const parts = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(value || ''));
    if (!parts) return shortDate(value);
    return new Date(+parts[1], +parts[2] - 1, +parts[3])
      .toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
  }

  // The block that makes the number go down. It is rendered above everything it explains because
  // it is the only thing on this page the seller can act on today.
  function renderTaxGap(p, has) {
    const el = $('tx-gap');
    if (!el) return;
    const gap = p.costGap || {};
    if (!has || !(gap.sales > 0) || !(gap.taxAtRisk > 0)) { el.classList.add('hidden'); el.innerHTML = ''; return; }

    el.classList.remove('hidden');
    el.innerHTML = `
      <div class="tx-gap-figure">${esc(moneyExact(gap.taxAtRisk))}</div>
      <div class="tx-gap-body">
        <p class="tx-gap-lead">of this bill is tax on goods the IRS thinks were free.</p>
        <p class="tx-gap-detail">${gap.sales} sale${gap.sales === 1 ? '' : 's'} worth ${esc(moneyExact(gap.taxableProceeds))} after fees ${gap.sales === 1 ? 'has' : 'have'} no record of what you paid, so all of it counts as profit. Money Made leaves those sales out of your earnings for exactly the same reason — the cost is missing — but the tax is charged either way.</p>
        <button class="btn btn-primary tx-gap-action" type="button">Enter what you paid →</button>
      </div>`;
  }

  function renderTaxQuarters(p) {
    const el = $('tx-quarters');
    if (!el) return;

    el.innerHTML = (p.quarters || []).map(q => {
      const classes = ['tx-quarter'];
      if (q.isPast) classes.push('is-past');
      if (q.isCurrent) classes.push('is-current');
      return `
        <div class="${classes.join(' ')}">
          <div class="tx-q-head">
            <span class="tx-q-name">${esc(q.name)}</span>
            ${q.isCurrent ? '<span class="tx-q-tag">earning into this now</span>' : ''}
            ${q.isPast && !q.isCurrent ? '<span class="tx-q-tag tx-q-tag-past">due date passed</span>' : ''}
          </div>
          <div class="tx-q-amount">${esc(moneyExact(q.setAside))}</div>
          <div class="tx-q-due">pay by ${esc(taxDueLabel(q.dueDate))}</div>
          <div class="tx-q-meta">${esc(q.covers)} · ${q.sales} sale${q.sales === 1 ? '' : 's'} · ${esc(moneyExact(q.netProfit))} profit</div>
        </div>`;
    }).join('');
  }

  function renderTaxScheduleC(p) {
    const el = $('tx-schedule');
    if (!el) return;

    const lines = (p.scheduleC || []).map(line => `
      <div class="tx-line${line.isSubtotal ? ' is-subtotal' : ''}">
        <span class="tx-line-no">${esc(line.line)}</span>
        <span class="tx-line-label">${esc(line.label)}${line.measured ? '' : ' <span class="tx-line-chip">partly estimated</span>'}</span>
        <span class="tx-line-amount">${esc(moneyExact(line.amount))}</span>
      </div>
      <p class="tx-line-basis">${esc(line.basis)}</p>`).join('');

    // The estimate sits under the form rather than inside it: lines 1–31 are figures anybody can
    // copy onto a return, and the tax below them is this app's arithmetic, not the IRS's.
    const estimate = `
      <div class="tx-estimate">
        <div class="tx-line"><span class="tx-line-no"></span><span class="tx-line-label">Self-employment tax</span><span class="tx-line-amount">${esc(moneyExact(p.selfEmploymentTax || 0))}</span></div>
        <div class="tx-line"><span class="tx-line-no"></span><span class="tx-line-label">Federal income tax at ${esc(String(p.assumptions?.incomeTaxRatePercent ?? 0))}%</span><span class="tx-line-amount">${esc(moneyExact(p.incomeTax || 0))}</span></div>
        <div class="tx-line is-subtotal"><span class="tx-line-no"></span><span class="tx-line-label">Set aside</span><span class="tx-line-amount">${esc(moneyExact(p.totalTax || 0))}</span></div>
        <p class="tx-line-basis">Claiming the ${esc(moneyExact(p.deductionsTotal || 0))} of costs above is what keeps ${esc(moneyExact(p.taxSavedByDeductions || 0))} of tax off this figure. State and local tax is not included.</p>
      </div>`;

    el.innerHTML = lines + estimate;
  }

  function renderTax1099(p) {
    const check = p.form1099K || {};
    setText('tx-1099-figure', moneyExact(check.expectedGross || 0));
    const el = $('tx-1099');
    if (el) el.innerHTML = (check.notes || []).map(n => `<p>${esc(n)}</p>`).join('');
  }

  // ── The Store Plan ────────────────────────────────────────────────────────
  // The third screen built on "what do you actually keep", and the only one whose answer is a single
  // click on eBay that then pays every month for as long as the seller trades.
  //
  // Three rules, all of which are easy to "tidy" into their opposite:
  //   * The hero is the ANNUAL saving. $17 a month reads as noise; $204 a year is what gets somebody
  //     to open eBay's subscription page. The monthly figure is on the side, where it belongs.
  //   * Every row prints its own arithmetic. The rate card lives in code and eBay changes it, so a
  //     row a seller cannot check against eBay's fee page is a row they are right to distrust.
  //   * This screen changes nothing on eBay, and says so on the screen rather than in a tooltip. It
  //     is a recommendation about a subscription, and one that could start a $299/mo commitment on
  //     its own should not exist.
  let storePlan = null;
  let storePlanRates = null;

  function showStorePlanSection() {
    hideOverlaySections();
    $('storeplan-section')?.classList.remove('hidden');
    setActiveNavItem('storeplan');
    markWorkspaceTabOpen('storeplan');
    if (!storePlan) loadStorePlan(); else renderStorePlan();
  }

  function closeStorePlanSection() { closeWorkspacePage('storeplan'); }

  function bindStorePlan() {
    on('sp-close', 'click', closeStorePlanSection);
    on('sp-home', 'click', goHome);
    on('sp-refresh', 'click', () => loadStorePlan());
    on('sp-save', 'click', saveStorePlanSettings);

    // The plan and the billing cycle are two-option choices; making the seller press Apply after
    // picking one is a step with nothing in it. The listing box still needs Apply — re-costing on
    // every keystroke of "1200" would flash three different answers on the way.
    on('sp-plan', 'change', saveStorePlanSettings);
    on('sp-billing', 'change', saveStorePlanSettings);
    on('sp-listings', 'keydown', e => { if (e.key === 'Enter') { e.preventDefault(); saveStorePlanSettings(); } });

    on('sp-rates-toggle', 'click', () => {
      const card = $('sp-rates-card'), btn = $('sp-rates-toggle');
      if (!card || !btn) return;
      const shown = !card.classList.toggle('hidden');
      btn.textContent = shown ? 'Hide eBay\'s rate card' : 'Show eBay\'s rate card';
      btn.setAttribute('aria-expanded', shown ? 'true' : 'false');
      if (shown) loadStorePlanRates();
    });
  }

  async function loadStorePlan() {
    // The only path that asks eBay for the listing count. Everything else on this screen re-costs
    // from the count already in hand, so changing a plan is instant and eBay is asked once.
    try {
      const res = await fetch('/api/store-plan');
      if (!res.ok) throw new Error('Could not work out your store plan.');
      storePlan = await res.json();
      renderStorePlan();
    } catch (err) {
      setStorePlanNote(errorText(err, 'Could not work out your store plan.'), true);
    }
  }

  async function loadStorePlanRates() {
    if (storePlanRates) return;
    try {
      const res = await fetch('/api/store-plan/rates');
      if (!res.ok) return;
      storePlanRates = await res.json();
      renderStorePlanRates();
    } catch { /* the card is a cross-check, not the feature — a failed fetch stays quiet */ }
  }

  async function saveStorePlanSettings() {
    const typed = num('sp-listings');
    const body = {
      planKey: $('sp-plan')?.value || 'none',
      annualBilling: ($('sp-billing')?.value || 'annual') === 'annual',
      // Zero and empty are the same gesture — "stop planning against a number I made up".
      listingsOverride: typed !== null && typed > 0 ? Math.round(typed) : 0,
      // What the screen already knows, so eBay is not asked again for a figure nothing changed.
      // Null when eBay never answered: sending a 0 would have the server report a count it never
      // measured as measured, and put the wrong footnote under the whole screen.
      activeListings: storePlan?.listingCountMeasured ? (storePlan.activeListings ?? 0) : null,
    };

    try {
      const res = await fetch('/api/store-plan/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      if (!res.ok) throw new Error(await res.text() || 'That could not be saved.');
      storePlan = await res.json();
      renderStorePlan();
    } catch (err) {
      setStorePlanNote(errorText(err, 'That could not be saved.'), true);
    }
  }

  function setStorePlanNote(text, isError) {
    const el = $('sp-controls-note');
    if (!el) return;
    el.textContent = text;
    el.classList.toggle('sp-note-error', !!isError);
  }

  function renderStorePlan() {
    if (!storePlan) return;
    const p = storePlan;
    const known = p.listingsPerMonth > 0;

    $('sp-results')?.classList.toggle('hidden', known);
    $('sp-plans-card')?.classList.toggle('hidden', !known);
    $('sp-detail')?.classList.toggle('hidden', !known);
    $('sp-honesty')?.classList.toggle('hidden', !(p.honesty || []).length);

    renderStorePlanControls(p);
    renderStorePlanHero(p, known);

    setText('sp-next', known ? (p.nextStep || '') : '');
    const detail = $('sp-detail');
    if (detail) detail.textContent = p.detail || '';

    renderStorePlanBillingWin(p, known);

    const honesty = $('sp-honesty');
    if (honesty) honesty.innerHTML = (p.honesty || []).map(line => `<p>${esc(line)}</p>`).join('');

    if (!known) { const host = $('sp-plans'); if (host) host.innerHTML = ''; return; }
    renderStorePlanRows(p);
  }

  function renderStorePlanControls(p) {
    const select = $('sp-plan');
    if (select && !select.options.length) {
      // Built from the options the server costed, so the picker can never offer a tier the
      // comparison below does not have a row for.
      select.innerHTML = (p.options || [])
        .map(o => `<option value="${esc(o.key)}">${esc(o.name)}</option>`).join('');
    }
    if (select && document.activeElement !== select) select.value = p.currentPlanKey || 'none';

    const billing = $('sp-billing');
    if (billing && document.activeElement !== billing) billing.value = p.billingCycle || 'annual';

    const listings = $('sp-listings');
    if (listings && document.activeElement !== listings)
      listings.value = p.usingOverride ? p.listingsPerMonth : '';

    if (p.status === 'ebay_unavailable') {
      setStorePlanNote('eBay could not be reached, so the listing count could not be read. '
        + 'Type how many listings you keep live and everything on this screen works from that.', true);
      return;
    }

    setStorePlanNote('Nothing here changes anything on eBay. Switching plans is done on eBay\'s own '
      + 'Store page — this only tells you which one to be on.', false);
  }

  function renderStorePlanHero(p, known) {
    const worth = p.totalAnnualSaving || 0;

    setText('sp-hero-label', worth > 0 ? 'Worth switching, over a year' : 'You are on the right plan');
    setText('sp-hero-figure', moneyExact(worth));
    setText('sp-hero-sub', p.headline || '');
    setText('sp-hero-listings', known ? p.listingsPerMonth.toLocaleString() : '—');
    setText('sp-hero-now', known ? `${moneyExact(p.currentMonthlyCost || 0)}/mo` : '—');
    setText('sp-hero-best', known ? p.bestPlanName || '—' : '—');

    // Gold when there is money on the table, plain when there is not. A hero that always looks
    // urgent is one a seller stops reading.
    $('storeplan-section')?.querySelector('.sp-hero')?.classList.toggle('sp-hero-win', worth > 0);
  }

  function renderStorePlanBillingWin(p, known) {
    const el = $('sp-billing-win');
    if (!el) return;
    const show = known && (p.billingMonthlySaving || 0) > 0 && !!p.billingNote;
    el.classList.toggle('hidden', !show);
    if (show) el.textContent = p.billingNote;
  }

  function renderStorePlanRows(p) {
    const host = $('sp-plans');
    if (!host) return;

    host.innerHTML = (p.options || []).map(o => {
      const tags = [
        o.isCurrent ? '<span class="sp-tag sp-tag-current">You are here</span>' : '',
        o.isBest ? '<span class="sp-tag sp-tag-best">Cheapest for you</span>' : '',
        o.annualBillingOnly ? '<span class="sp-tag sp-tag-note">Annual only</span>' : '',
      ].join('');

      // The delta is the number the seller acts on, so it is signed and stated in plain words
      // rather than left as a bare figure they have to work out the direction of.
      const delta = o.isCurrent
        ? '<span class="sp-delta sp-delta-flat">what you pay today</span>'
        : (o.monthlyDelta < 0
          ? `<span class="sp-delta sp-delta-down">${moneyExact(Math.abs(o.monthlyDelta))} a month less</span>`
          : (o.monthlyDelta > 0
            ? `<span class="sp-delta sp-delta-up">${moneyExact(o.monthlyDelta)} a month more</span>`
            : '<span class="sp-delta sp-delta-flat">the same as today</span>'));

      return `
        <div class="sp-plan${o.isCurrent ? ' is-current' : ''}${o.isBest ? ' is-best' : ''}">
          <div class="sp-plan-head">
            <span class="sp-plan-name">${esc(o.name)}</span>
            ${tags}
          </div>
          <div class="sp-plan-cost">${moneyExact(o.monthlyCost)}<span class="sp-plan-per">/mo</span></div>
          <div class="sp-plan-year">${moneyExact(o.annualCost)} a year</div>
          ${delta}
          <p class="sp-basis">${esc(o.basis)}</p>
          <p class="sp-band">${esc(storePlanBand(o))}</p>
          <p class="sp-unlocks">${esc(o.unlocks)}</p>
        </div>`;
    }).join('');
  }

  // The band is the half of this screen that keeps working after the switch: it says where the next
  // change lands, so a seller grows into a new tier on purpose rather than finding it in a statement.
  function storePlanBand(o) {
    if (o.neverCheapest)
      return 'Never the cheapest plan at any listing count — something else always beats it.';
    if (o.cheapestTo === null || o.cheapestTo === undefined)
      return `Cheapest from ${o.cheapestFrom.toLocaleString()} listings up, with nothing above it.`;
    return `Cheapest between ${o.cheapestFrom.toLocaleString()} and ${o.cheapestTo.toLocaleString()} listings.`;
  }

  function renderStorePlanRates() {
    const host = $('sp-rates');
    if (!host || !storePlanRates) return;

    host.innerHTML = (storePlanRates.tiers || []).map(t => `
      <div class="sp-rate">
        <span class="sp-rate-name">${esc(t.name)}</span>
        <span class="sp-rate-cell">${t.annualBilling > 0 ? `${moneyExact(t.annualBilling)}/mo billed annually` : 'free'}</span>
        <span class="sp-rate-cell">${t.monthlyBilling === null || t.monthlyBilling === undefined
          ? 'annual commitment only'
          : (t.monthlyBilling > 0 ? `${moneyExact(t.monthlyBilling)}/mo billed monthly` : 'free')}</span>
        <span class="sp-rate-cell">${t.freeListings.toLocaleString()} free listings a month</span>
        <span class="sp-rate-cell">${moneyExact(t.insertionFeeAfter)} each after that</span>
      </div>`).join('')
      + `<p class="sp-rates-note">${esc(storePlanRates.note || '')}</p>`;
  }

  // ── The Restock List ──────────────────────────────────────────────────────
  // Money Made says what the seller earned. This says what to go and buy with it, out of the same
  // completed sales — so a row here can always be traced back to sales on that screen.
  //
  // Three rules the screen has to keep, all of them from RestockAnalyzer:
  //   * The hero is money NOT being made. Proven lines with nothing listed is the one figure here
  //     that is an instruction, and it is the reason a seller opens this on a Saturday morning.
  //   * A caution is never netted off a headline. "$180 a month" and "one of the four came back"
  //     are both true and they go on the same card, because the seller is about to spend money.
  //   * Nothing here is a market forecast, and the screen says so rather than looking like one.
  //     Every figure is a sale that already happened, and prices move.
  let restock = null;
  let restockSort = 'month';

  function showRestockSection() {
    hideOverlaySections();
    $('restock-section')?.classList.remove('hidden');
    setActiveNavItem('restock');
    markWorkspaceTabOpen('restock');
    if (!restock) loadRestock(); else renderRestock();
  }

  function closeRestockSection() { closeWorkspacePage('restock'); }

  function bindRestock() {
    on('rs-close', 'click', closeRestockSection);
    on('rs-home', 'click', goHome);
    on('rs-refresh', 'click', () => loadRestock());

    // Delegated: every row on this board is re-rendered on load and on every change of order.
    $('restock-section')?.addEventListener('click', e => {
      const sort = e.target.closest?.('.rs-sort-btn');
      if (sort) {
        restockSort = sort.dataset.sort || 'month';
        renderRestock();
        return;
      }

      const hunt = e.target.closest?.('.rs-hunt');
      if (hunt) { huntForRestockLine(hunt.dataset.query || ''); return; }

      const copy = e.target.closest?.('.rs-copy');
      if (copy) {
        navigator.clipboard?.writeText(copy.dataset.query || '');
        copy.textContent = 'Copied';
        setTimeout(() => { copy.textContent = 'Copy search'; }, 1500);
      }
    });
  }

  // The whole point of the board in one click: a line the seller has proved they can sell, handed
  // to the screen that finds one to buy. The search waits a tick because navigateTo() opens the
  // Opportunity Finder on the next hashchange — searching now would run against a hidden page.
  function huntForRestockLine(query) {
    if (!query) return;
    navigateTo('opportunity');
    setTimeout(() => {
      const input = $('opp-search-input');
      if (!input) return;
      input.value = query;
      input.scrollIntoView({ block: 'center', behavior: 'smooth' });
      findOpportunities();
    }, 80);
  }

  async function loadRestock() {
    const btn = $('rs-refresh');
    if (btn) { btn.disabled = true; btn.textContent = 'Reading your sales…'; }
    try {
      const res = await fetch('/api/restock');
      if (!res.ok) throw new Error('Could not build your restock list.');
      restock = await res.json();
      renderRestock();
    } catch (err) {
      setRestockNotice(errorText(err, 'Could not build your restock list.'), true);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Refresh'; }
    }
  }

  function setRestockNotice(text, isError) {
    const el = $('rs-notice');
    if (!el) return;
    el.textContent = text || '';
    el.classList.toggle('hidden', !text);
    el.classList.toggle('rs-notice-error', !!isError);
  }

  function renderRestock() {
    if (!restock) return;
    const r = restock;
    const s = r.summary || {};
    const ranked = r.restock || [];
    const has = (r.status !== 'no_sales') && (ranked.length || (r.stop || []).length || (r.needsCost || []).length || (r.watch || []).length);

    $('rs-results')?.classList.toggle('hidden', !!has);
    $('rs-board')?.classList.toggle('hidden', !ranked.length);
    $('rs-stop-card')?.classList.toggle('hidden', !(r.stop || []).length);
    $('rs-cost-card')?.classList.toggle('hidden', !(r.needsCost || []).length);
    $('rs-watch-card')?.classList.toggle('hidden', !(r.watch || []).length);
    $('rs-honesty')?.classList.toggle('hidden', !(r.honesty || []).length);

    renderRestockHero(r, s, ranked);
    setRestockNotice(r.stockNote || '', false);

    const list = $('rs-list');
    if (list) list.innerHTML = sortedRestockLines(ranked).map(restockCard).join('');

    const stop = $('rs-stop');
    if (stop) stop.innerHTML = (r.stop || []).map(restockCard).join('');

    const cost = $('rs-cost');
    if (cost) cost.innerHTML = (r.needsCost || []).map(restockCard).join('');
    setText('rs-cost-title', (r.needsCost || []).length === 1
      ? 'One product sold with no record of what it cost'
      : `${(r.needsCost || []).length} products sold with no record of what they cost`);

    const watch = $('rs-watch');
    if (watch) watch.innerHTML = (r.watch || []).map(restockCard).join('');

    const honesty = $('rs-honesty');
    if (honesty) honesty.innerHTML = (r.honesty || []).map(line => `<p>${esc(line)}</p>`).join('');

    document.querySelectorAll('.rs-sort-btn').forEach(btn =>
      btn.classList.toggle('active', btn.dataset.sort === restockSort));
  }

  function renderRestockHero(r, s, ranked) {
    const idle = s.monthlyProfitOffTheShelf || 0;
    const soldOut = s.soldOutLines || 0;

    // The hero only claims idle money when the live listings were actually read. With eBay down
    // the honest headline is what the proven lines earn, not a zero that reads like "nothing to do".
    const stockKnown = r.stockStatus === 'read';
    setText('rs-hero-figure', money(stockKnown ? idle : (s.provenMonthlyProfit || 0)));
    setText('rs-hero-proven', money(s.provenMonthlyProfit || 0));
    setText('rs-hero-lines', String(s.rankedLines || 0));
    setText('rs-hero-cash', s.cashToRestockSoldOut ? money(s.cashToRestockSoldOut) : '—');

    setText('rs-hero-label', stockKnown ? 'Sitting idle — proven lines with nothing listed' : 'Your proven lines earn, a month');

    let sub;
    if (!ranked.length && r.status === 'no_sales') sub = 'your sales appear here on their own once eBay is connected';
    else if (!ranked.length) sub = 'nothing has sold twice yet, so nothing is ranked — the lists below say what is there';
    else if (!stockKnown) sub = 'your live listings could not be read, so this board can\'t say which of these you have none of';
    else if (soldOut) sub = `${soldOut} product${soldOut === 1 ? '' : 's'} you have sold before, and have none of right now`;
    else sub = 'everything you have proved sells is listed — nothing is sitting idle';
    setText('rs-hero-sub', sub);

    if (s.topLineTitle && s.topLineShareOfProfitPercent >= 50 && ranked.length > 1)
      setText('rs-board-title', `${Math.round(s.topLineShareOfProfitPercent)}% of this comes from one product — ${s.topLineTitle}`);
    else
      setText('rs-board-title', 'Ranked by what each one earns you a month');
  }

  // Sorting is a display choice, so it happens here rather than costing a round trip. The server's
  // own order is money per month; the other two re-order the same ranked lines and never add one.
  function sortedRestockLines(lines) {
    const copy = lines.slice();
    if (restockSort === 'cash') return copy.sort((a, b) => (b.annualReturnOnCashPercent ?? -1) - (a.annualReturnOnCashPercent ?? -1));
    if (restockSort === 'unit') return copy.sort((a, b) => (b.averageProfitPerUnit ?? 0) - (a.averageProfitPerUnit ?? 0));
    return copy.sort((a, b) => (b.profitPerMonth ?? 0) - (a.profitPerMonth ?? 0));
  }

  function restockCard(line) {
    const badges = [];
    if (line.soldOut && line.verdict === 'restock') badges.push('<span class="rs-badge rs-badge-out">None listed</span>');
    else if (line.activeListings > 0) badges.push(`<span class="rs-badge rs-badge-live">${line.activeListings} listed</span>`);
    if (line.verdict === 'stop') badges.push('<span class="rs-badge rs-badge-stop">Stop buying</span>');
    if (line.verdict === 'needs_cost') badges.push('<span class="rs-badge rs-badge-cost">Needs a cost</span>');

    const stats = [];
    if (line.profitPerMonth != null) stats.push(['A month', moneyExact(line.profitPerMonth)]);
    if (line.averageProfitPerUnit != null) stats.push(['Profit each', moneyExact(line.averageProfitPerUnit)]);
    // Zero means "no rate can be measured", not "sells nothing" — one sale has no rate, and
    // printing 1.0 a month beside "one sale is not a pattern" would contradict the card.
    if (line.salesPerMonth > 0) stats.push(['Sells', `${line.salesPerMonth.toFixed(1)} a month`]);
    if (line.averageUnitCost != null) stats.push(['You paid', moneyExact(line.averageUnitCost)]);
    if (line.roiPercent != null) stats.push(['Return', `${Math.round(line.roiPercent)}%`]);
    // Only ever shown when the seller recorded when they bought it — see RestockAnalyzer.
    if (line.annualReturnOnCashPercent != null) stats.push(['Cash back', `${Math.round(line.annualReturnOnCashPercent).toLocaleString()}% a year`]);
    if (line.medianDaysHeld != null) stats.push(['Held', `${line.medianDaysHeld} days`]);
    stats.push(['Sold', `${line.unitsSold} in total`]);
    stats.push(['Last one', line.daysSinceLastSale === 0 ? 'today' : `${line.daysSinceLastSale} days ago`]);
    if (line.proceedsAwaitingCost > 0 && line.verdict === 'needs_cost') stats.push(['Proceeds', moneyExact(line.proceedsAwaitingCost)]);

    const cautions = (line.cautions || []).map(c => `<li>${esc(c)}</li>`).join('');

    // "Find one to buy" belongs only on a line the board is recommending. On the stop list it would
    // offer to go and buy more of the thing the card is telling the seller to stop buying, and on a
    // line with no cost recorded nothing here knows yet whether buying another is a good idea.
    const hunt = line.verdict === 'restock' || line.verdict === 'watch';

    return `
      <article class="rs-card rs-card-${esc(line.verdict)}">
        <div class="rs-card-head">
          <div class="rs-card-title">
            <h4>${esc(line.title)}</h4>
            <div class="rs-badges">${badges.join('')}</div>
          </div>
          <div class="rs-card-actions">
            ${hunt ? `<button class="btn btn-primary small rs-hunt" type="button" data-query="${esc(line.searchQuery)}">Find one to buy</button>` : ''}
            <button class="btn btn-ghost small rs-copy" type="button" data-query="${esc(line.searchQuery)}">Copy search</button>
          </div>
        </div>
        <p class="rs-headline">${esc(line.headline)}</p>
        <div class="rs-stats">
          ${stats.map(([label, value]) => `<div class="rs-stat"><span class="rs-stat-label">${esc(label)}</span><span class="rs-stat-value">${esc(value)}</span></div>`).join('')}
        </div>
        ${cautions ? `<ul class="rs-cautions">${cautions}</ul>` : ''}
      </article>`;
  }

  // ── Price Position ────────────────────────────────────────────────────────
  // The shelf a buyer actually sees. Three rules this screen has to keep, all of them decided in
  // Services/PricePositionAnalyzer.cs rather than here:
  //   * The card leads with the BLOCKER, not the rank. "7th of 9" is a fact; "four cheaper ones are
  //     seen before yours" is the same fact with the reason the listing has not sold attached, and
  //     the seller is reading this to decide what to do next.
  //   * A price cut is never the answer to a listing nobody has seen. The server decides that —
  //     the browser never re-derives it — and the visibility rows get sent to Listing Copilot
  //     instead of being shown a number to cut to.
  //   * Every price on this page is a number to consider. Nothing here writes to eBay, and the
  //     screen says so rather than looking like a repricer.
  let pricePosition = null;
  let ppFilter = 'all';

  function showPricePositionSection() {
    hideOverlaySections();
    $('position-section')?.classList.remove('hidden');
    setActiveNavItem('position');
    markWorkspaceTabOpen('position');
    if (!pricePosition) loadPricePosition(); else renderPricePosition();
  }

  function closePricePositionSection() { closeWorkspacePage('position'); }

  function bindPricePosition() {
    on('pp-close', 'click', closePricePositionSection);
    on('pp-home', 'click', goHome);
    on('pp-refresh', 'click', () => loadPricePosition());

    // Delegated: every row is re-rendered on load and on every change of filter.
    $('position-section')?.addEventListener('click', e => {
      const filter = e.target.closest?.('.pp-filter-btn');
      if (filter) {
        ppFilter = filter.dataset.filter || 'all';
        renderPricePosition();
        return;
      }

      const copilot = e.target.closest?.('.pp-to-copilot');
      if (copilot) { navigateTo('copilot'); return; }

      const offers = e.target.closest?.('.pp-to-offers');
      if (offers) { navigateTo('offers'); return; }

      const copy = e.target.closest?.('.pp-copy-price');
      if (copy) {
        navigator.clipboard?.writeText(copy.dataset.price || '');
        copy.textContent = 'Copied';
        setTimeout(() => { copy.textContent = 'Copy price'; }, 1500);
      }
    });
  }

  async function loadPricePosition() {
    const btn = $('pp-refresh');
    if (btn) { btn.disabled = true; btn.textContent = 'Reading the shelf…'; }
    setPricePositionNotice('Reading your live listings, then the listings competing with each one. This takes a few seconds.', false);
    try {
      const res = await fetch('/api/price-position');
      if (!res.ok) throw new Error('Could not read where your listings sit.');
      pricePosition = await res.json();
      renderPricePosition();
    } catch (err) {
      setPricePositionNotice(errorText(err, 'Could not read where your listings sit.'), true);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Refresh'; }
    }
  }

  function setPricePositionNotice(text, isError) {
    const el = $('pp-notice');
    if (!el) return;
    el.textContent = text || '';
    el.classList.toggle('hidden', !text);
    el.classList.toggle('rs-notice-error', !!isError);
  }

  function renderPricePosition() {
    if (!pricePosition) return;
    const r = pricePosition;
    const s = r.summary || {};
    const rows = r.rows || [];

    $('pp-results')?.classList.toggle('hidden', !!rows.length);
    $('pp-board')?.classList.toggle('hidden', !rows.length);
    $('pp-honesty')?.classList.toggle('hidden', !(r.honesty || []).length);

    renderPricePositionHero(r, s, rows);

    if (r.status === 'ebay_unavailable') setPricePositionNotice(r.error || 'eBay could not be read.', true);
    else if (r.status === 'no_listings') setPricePositionNotice('You have no active listings for this board to place.', false);
    else setPricePositionNotice('', false);

    const shown = filteredPricePositionRows(rows);
    const list = $('pp-list');
    if (list) {
      list.innerHTML = shown.length
        ? shown.map(pricePositionCard).join('')
        : '<p class="pp-empty">Nothing in your inventory matches that filter — which is the good version of this screen.</p>';
    }

    const honesty = $('pp-honesty');
    if (honesty) honesty.innerHTML = (r.honesty || []).map(line => `<p>${esc(line)}</p>`).join('');

    document.querySelectorAll('.pp-filter-btn').forEach(btn =>
      btn.classList.toggle('active', btn.dataset.filter === ppFilter));
  }

  function renderPricePositionHero(r, s, rows) {
    setText('pp-hero-figure', money(s.capitalBehindTheShelf || 0));
    setText('pp-hero-leading', String(s.leading || 0));
    setText('pp-hero-unseen', String(s.visibilityBlocked || 0));

    // What the seller still takes home if the priced-out listings move to the front — never the
    // size of the cut, which is a cost, and printing it as a headline would be selling somebody
    // their own markdown. A dash rather than $0 when no priced-out row has a cost recorded: zero
    // there would read as "there is nothing left in these", which is not what is known.
    setText('pp-hero-profit', s.profitStillOnTheTable != null ? money(s.profitStillOnTheTable) : '—');

    let sub;
    if (r.status === 'ebay_unavailable') sub = 'your live listings could not be read, so nothing here has a position yet';
    else if (!rows.length) sub = 'your live listings appear here once eBay is connected';
    else if (!s.pricedOut) sub = `nothing you listed is sitting behind a cheaper copy of itself — ${r.itemsAnalyzed} listing${r.itemsAnalyzed === 1 ? '' : 's'} checked`;
    else if (s.worstPremiumPercent != null) sub = `${s.pricedOut} listing${s.pricedOut === 1 ? '' : 's'} behind the front of the shelf — the worst by ${Math.round(s.worstPremiumPercent)}%, ${s.worstPremiumTitle}`;
    else sub = `${s.pricedOut} listing${s.pricedOut === 1 ? '' : 's'} behind the front of the shelf`;
    setText('pp-hero-sub', sub);

    // The "still yours at the front" figure quietly excludes any priced-out listing with no cost
    // recorded, and a seller reading a number needs to know what is not inside it.
    if (s.pricedOutWithoutCost > 0)
      setText('pp-hero-label', `Listed behind cheaper copies of itself — ${s.pricedOutWithoutCost} with no cost recorded`);
    else
      setText('pp-hero-label', 'Listed behind cheaper copies of itself');

    setText('pp-board-title', s.cantWin > 0
      ? `${s.cantWin} of these cannot be won on price — somebody is buying them cheaper than you are`
      : 'Most money sitting behind the front of its shelf, first');
  }

  // A filter, not a sort. The board's own order is what the money says and it never changes here.
  function filteredPricePositionRows(rows) {
    if (ppFilter === 'price') return rows.filter(r => r.blocker === 'price');
    if (ppFilter === 'visibility') return rows.filter(r => r.blocker === 'visibility');
    return rows;
  }

  const PP_BLOCKER_LABEL = {
    price: 'Your price',
    supply: 'What you paid',
    visibility: 'Nobody is seeing it',
    none: '',
  };

  function pricePositionCard(row) {
    const badges = [];
    if (row.rank != null && row.rivalsCounted >= 3)
      badges.push(`<span class="pp-badge pp-badge-rank">${esc(String(row.rank))} of ${esc(String(row.rivalsCounted + 1))} on price</span>`);
    // "Only one listed" is true when the search found nobody, and a lie when it found nine and
    // none of them were the item. The card underneath says "2 other listings left out of the
    // ranking", and a badge that contradicts the line below it is the screen arguing with itself.
    if (row.verdict === 'alone')
      badges.push(row.rivalsFound > 0
        ? '<span class="pp-badge pp-badge-alone">Nothing comparable</span>'
        : '<span class="pp-badge pp-badge-alone">Only one listed</span>');
    if (row.verdict === 'thin_market') badges.push('<span class="pp-badge pp-badge-alone">Too few to compare</span>');
    if (row.verdict === 'lookup_failed') badges.push('<span class="pp-badge pp-badge-alone">Shelf unread</span>');
    if (PP_BLOCKER_LABEL[row.blocker]) badges.push(`<span class="pp-badge pp-badge-${esc(row.blocker)}">${esc(PP_BLOCKER_LABEL[row.blocker])}</span>`);

    const stats = [];
    stats.push(['Yours', row.basis === 'delivered'
      ? `${moneyExact(row.myComparedPrice)} delivered`
      : `${moneyExact(row.myPrice)} + shipping`]);
    if (row.targetRival != null) stats.push(['Front of the shelf', moneyExact(row.targetRival)]);
    if (row.premiumPercent != null && row.premiumPercent > 0) stats.push(['You are over by', `${row.premiumPercent.toFixed(1)}%`]);
    if (row.medianRival != null) stats.push(['Middle of the shelf', moneyExact(row.medianRival)]);
    // Withheld rather than shown as zero when the server could not measure it — see ViewsKnown.
    if (row.viewsKnown) stats.push(['Seen', `${row.viewCount.toLocaleString()} time${row.viewCount === 1 ? '' : 's'}`]);
    if (row.watchCount > 0) stats.push(['Watching', String(row.watchCount)]);
    if (row.daysListed != null) stats.push(['Listed', `${row.daysListed} days`]);
    if (row.hasCostBasis && row.netProfitNow != null) stats.push(['Profit at your price', moneyExact(row.netProfitNow)]);

    // The one number the seller might actually type, and it is only ever offered on a row where
    // moving is the recommendation. Never on cant_win, where the same number is a loss, and never
    // on a visibility row, where cutting fixes nothing.
    const offerPrice = row.blocker === 'price' && row.itemPriceToLead != null;
    const priceBox = offerPrice ? `
        <div class="pp-target">
          <div class="pp-target-main">
            <span class="pp-target-label">To be the cheapest on this shelf, ask</span>
            <span class="pp-target-price">${esc(moneyExact(row.itemPriceToLead))}</span>
            ${row.basis === 'delivered' && row.myShipping > 0 ? `<span class="pp-target-note">plus your ${esc(moneyExact(row.myShipping))} shipping</span>` : ''}
          </div>
          <div class="pp-target-side">
            ${row.netProfitAtLeadPrice != null
              ? `<span class="pp-target-profit ${row.netProfitAtLeadPrice > 0 ? '' : 'pp-target-profit-thin'}">${esc(moneyExact(row.netProfitAtLeadPrice))} still yours</span>`
              : '<span class="pp-target-profit pp-target-profit-thin">no cost recorded</span>'}
            ${row.floorPrice != null ? `<span class="pp-target-floor">your floor is ${esc(moneyExact(row.floorPrice))}</span>` : ''}
            <button class="btn btn-ghost small pp-copy-price" type="button" data-price="${esc(String(row.itemPriceToLead))}">Copy price</button>
          </div>
        </div>` : '';

    const rivals = (row.rivals || []).filter(v => v.counted).slice(0, 5).map(v => `
        <li class="pp-rival">
          <a href="${esc(v.url)}" target="_blank" rel="noopener">${esc(v.title)}</a>
          <span class="pp-rival-price">${esc(moneyExact(v.deliveredPrice != null ? v.deliveredPrice : v.price))}</span>
          <span class="pp-rival-seller">${esc(v.sellerUsername || 'seller unknown')} · ${esc(String(v.sellerFeedbackScore))}</span>
        </li>`).join('');

    // Grouped rather than listed one by one. "9 not compared" is a number the seller cannot check;
    // "4 were a lot of 10, 3 were for parts" is the board showing its working.
    const skipped = pricePositionSkipSummary(row.rivals || []);

    const cautions = (row.cautions || []).map(c => `<li>${esc(c)}</li>`).join('');
    const shelfUrl = `https://www.ebay.com/sch/i.html?_nkw=${encodeURIComponent(row.searchQuery || row.title)}&_sop=15`;

    return `
      <article class="pp-card pp-card-${esc(row.blocker)}${row.rank == null ? ' pp-card-unjudged' : ''}">
        <div class="pp-card-head">
          <div class="pp-card-title">
            ${row.thumbnailUrl ? `<img class="pp-thumb" src="${esc(row.thumbnailUrl)}" alt="" loading="lazy" />` : ''}
            <div>
              <h4>${row.listingUrl ? `<a href="${esc(row.listingUrl)}" target="_blank" rel="noopener">${esc(row.title)}</a>` : esc(row.title)}</h4>
              <div class="pp-badges">${badges.join('')}</div>
            </div>
          </div>
          <div class="pp-card-actions">
            ${row.blocker === 'visibility' ? '<button class="btn btn-primary small pp-to-copilot" type="button">Fix the title</button>' : ''}
            ${row.blocker === 'price' && row.watchCount > 0 ? '<button class="btn btn-secondary small pp-to-offers" type="button">Offer the watchers</button>' : ''}
            <a class="btn btn-ghost small" href="${esc(shelfUrl)}" target="_blank" rel="noopener">See the shelf</a>
          </div>
        </div>
        <p class="pp-headline">${esc(row.headline)}</p>
        ${priceBox}
        <div class="pp-stats">
          ${stats.map(([label, value]) => `<div class="pp-stat"><span class="pp-stat-label">${esc(label)}</span><span class="pp-stat-value">${esc(value)}</span></div>`).join('')}
        </div>
        ${rivals ? `<ul class="pp-rivals">${rivals}</ul>` : ''}
        ${skipped ? `<p class="pp-skipped">${esc(skipped)}</p>` : ''}
        ${cautions ? `<ul class="pp-cautions">${cautions}</ul>` : ''}
      </article>`;
  }

  function pricePositionSkipSummary(rivals) {
    const skipped = rivals.filter(v => !v.counted && v.skipReason);
    if (!skipped.length) return '';
    const counts = new Map();
    skipped.forEach(v => counts.set(v.skipReason, (counts.get(v.skipReason) || 0) + 1));
    const parts = [...counts.entries()]
      .sort((a, b) => b[1] - a[1]).slice(0, 3)
      .map(([reason, n]) => `${n} × ${reason.replace(/\.$/, '')}`);
    return `${skipped.length} other listing${skipped.length === 1 ? '' : 's'} left out of the ranking — ${parts.join('; ')}.`;
  }

  // ── Deal Pipeline ─────────────────────────────────────────────────────────
  // Sourced → Bought → Listed → Sold. The thread between every other screen: the forecast that
  // justified the buy, the cash that actually left, the listing it went into, and the sale that
  // settled it, all on one card.
  //
  // Three rules this UI must never break, all inherited from DealPipelineCalculator:
  //   * A projection is never money. Projected and realized profit live in different places, wear
  //     different colours, and are never summed into one figure.
  //   * The hero is capital at RISK — real money already spent — not the projected upside, which
  //     is the number a dishonest version of this page would lead with.
  //   * A card that has nothing wrong with it gets no prompt. A board that nags about everything
  //     is a board where the genuinely stuck $1,200 goes unnoticed.
  let pipeline = null;

  // The seller's own fee rates, for the rough net this page shows while a hand-entered deal is
  // being typed. Fetched once; the published defaults stand in if the call fails, and the preview
  // says out loud that it's an estimate either way.
  let dealFeeProfile = null;

  async function loadDealFeeProfile() {
    if (dealFeeProfile) return;
    try { dealFeeProfile = await fetch('/api/fees/profile').then(r => r.json()); }
    catch { /* the defaults below are the server's defaults too */ }
  }

  const DP_STAGES = {
    sourced: { label: 'Sourced', icon: '🔍', blurb: 'Found it. Haven\'t paid yet.' },
    bought:  { label: 'Bought',  icon: '💵', blurb: 'Your money is in it.' },
    listed:  { label: 'Listed',  icon: '🏷️', blurb: 'Live and working.' },
    sold:    { label: 'Sold',    icon: '✅', blurb: 'Money came back.' },
  };

  const DP_NEXT_STAGE = { sourced: 'bought', bought: 'listed', listed: 'sold' };

  function showPipelineSection() {
    hideOverlaySections();
    $('pipeline-section')?.classList.remove('hidden');
    setActiveNavItem('pipeline');
    markWorkspaceTabOpen('pipeline');
    if (!pipeline) loadPipeline(); else renderPipeline();
  }

  function closePipelineSection() {
    closeDealForm();
    closeStageForm();
    closeWorkspacePage('pipeline');
  }

  function bindPipeline() {
    on('dp-close', 'click', closePipelineSection);
    on('dp-home', 'click', goHome);
    on('dp-refresh-btn', 'click', () => loadPipeline());
    on('dp-add-btn', 'click', () => openDealForm(null));
    on('dp-add-cancel', 'click', closeDealForm);
    on('dp-add-cancel-2', 'click', closeDealForm);
    on('dp-add-save', 'click', saveDealForm);
    on('dp-stage-cancel', 'click', closeStageForm);
    on('dp-stage-cancel-2', 'click', closeStageForm);
    on('dp-stage-save', 'click', saveStageForm);
    on('dash-pipeline-open', 'click', () => { navigateTo('pipeline'); });
    on('dp-actions-toggle', 'click', () => toggleDisclosure('dp-actions', 'dp-actions-toggle', 'Show', 'Hide'));

    // Live projected profit as the seller types, so a deal is priced before it's committed to.
    ['dp-f-ask', 'dp-f-paid', 'dp-f-extra', 'dp-f-resale', 'dp-f-qty']
      .forEach(id => on(id, 'input', updateDealPreview));
    on('dp-f-stage', 'change', updateDealPreview);

    $('pipeline-section')?.addEventListener('click', onPipelineClick);
  }

  async function loadPipeline(quiet) {
    try {
      const res = await fetch('/api/deals');
      if (!res.ok) throw new Error(await res.text());
      pipeline = await res.json();
      if (!quiet) renderPipeline();
      renderDashboardPipeline();
    } catch (err) {
      renderDashboardPipeline();
      if (!quiet) setPipelineNotice(`Couldn't load the pipeline: ${errorText(err)}`);
    }
  }

  function setPipelineNotice(message) {
    const el = $('dp-notice');
    if (!el) return;
    if (!message) { el.classList.add('hidden'); el.textContent = ''; return; }
    el.textContent = message;
    el.classList.remove('hidden');
  }

  function renderPipeline() {
    const s = pipeline?.summary;
    const deals = pipeline?.deals || [];
    const empty = deals.length === 0;

    $('dp-results')?.classList.toggle('hidden', !empty);
    $('dp-hero')?.classList.toggle('hidden', empty);
    $('dp-board')?.classList.toggle('hidden', empty);
    $('dp-stats')?.classList.toggle('hidden', empty);
    $('dp-honesty')?.classList.toggle('hidden', empty);
    $('dp-actions-card')?.classList.toggle('hidden', empty || !(pipeline?.nextActions || []).length);
    if (empty) return;

    renderPipelineHero(s);
    renderPipelineStats(s);
    renderPipelineActions(pipeline.nextActions || []);
    renderPipelineBoard(pipeline.stages || [], deals);

    const honesty = $('dp-honesty');
    if (honesty) honesty.innerHTML = (pipeline.honesty || []).map(h => `<p>${esc(h)}</p>`).join('');
  }

  function renderPipelineHero(s) {
    setText('dp-hero-figure', moneyExact(s.capitalAtRisk || 0));

    // The subline is what the hero figure is made of, because "$4,180 at risk" only means
    // something once you can see it's four deals and which stage they're stuck in.
    const bits = [];
    if (s.activeDeals) bits.push(`${s.activeDeals} deal${s.activeDeals === 1 ? '' : 's'} in play`);
    if (s.stalledCapital > 0) bits.push(`${moneyExact(s.stalledCapital)} bought but not listed`);
    if (s.overdueCapital > 0) bits.push(`${moneyExact(s.overdueCapital)} listed longer than forecast`);
    if (!bits.length) bits.push('nothing is tying up cash right now');
    setText('dp-hero-sub', bits.join(' · '));

    setText('dp-hero-projected', moneyExact(s.projectedProfitInMotion || 0));
    setText('dp-hero-realized', moneyExact(s.realizedProfit || 0));
    setText('dp-hero-realized-note',
      s.dealsClosed ? `${s.dealsClosed} deal${s.dealsClosed === 1 ? '' : 's'} closed` : 'from completed sales');

    const acc = $('dp-hero-accuracy');
    if (acc) {
      if (s.forecastAccuracyPercent != null) {
        acc.textContent = `${Math.round(s.forecastAccuracyPercent)}%`;
        // Green only for a forecast that came in at or above what it promised. A projection that
        // overshot the outcome is the failure mode this figure exists to expose.
        acc.className = `dp-hero-stat-value ${s.forecastAccuracyPercent >= 95 ? 'dp-realized' : 'dp-under'}`;
        setText('dp-hero-accuracy-note',
          `${moneyExact(s.gradedRealizedProfit)} made vs ${moneyExact(s.gradedForecastProfit)} projected`);
      } else {
        acc.textContent = '—';
        acc.className = 'dp-hero-stat-value';
        setText('dp-hero-accuracy-note', 'needs one closed deal with a cost');
      }
    }
  }

  function renderPipelineStats(s) {
    const tiles = [
      ['Capital deployed', moneyExact(s.capitalDeployedAllTime || 0), 'everything ever put into tracked deals'],
      ['Sales revenue back', moneyExact(s.realizedRevenue || 0), `${s.dealsClosed || 0} closed`],
      ['Won / lost', `${s.dealsProfitable || 0} / ${s.dealsAtALoss || 0}`, 'closed deals that made money, and that didn\'t'],
      ['Median cash cycle', s.medianDaysToCash != null ? `${s.medianDaysToCash} days` : '—',
        s.medianDaysToCash != null ? 'money out to money back' : 'needs three closed deals'],
      ['Projected on the shelf', moneyExact(s.projectedProfitSourced || 0), 'forecast on deals not bought yet'],
      // Scoped to this board on purpose — Money Made owns the count across every sale, and two
      // different numbers under the same label in two places is how a seller stops trusting both.
      ['Board sales missing a cost', String(s.salesAwaitingCost || 0), 'sales on these deals whose profit isn\'t counted yet'],
    ];

    const host = $('dp-stats');
    if (host) host.innerHTML = tiles.map(([label, value, note]) => `
      <div class="er-stat">
        <span class="er-stat-label">${esc(label)}</span>
        <span class="er-stat-value">${esc(value)}</span>
        <span class="er-stat-note">${esc(note)}</span>
      </div>`).join('');
  }

  function renderPipelineActions(actions) {
    const host = $('dp-actions');
    if (!host) return;

    setText('dp-actions-title', actions.length
      ? `${actions.length} thing${actions.length === 1 ? '' : 's'} your money is waiting on`
      : 'Nothing is waiting on you');

    host.innerHTML = actions.map(a => `
      <div class="dp-action dp-action-${esc(a.urgency)}">
        <span class="dp-action-money">${a.amountAtStake > 0 ? money(a.amountAtStake) : ''}</span>
        <span class="dp-action-text">
          <span class="dp-action-label">${esc(a.label)} — ${esc(a.title)}</span>
          <span class="dp-action-detail">${esc(a.detail)}</span>
        </span>
        <span class="dp-action-go">${actionButtonHtml(a)}</span>
      </div>`).join('');
  }

  // The prompt has to land somewhere useful. A repricing nudge belongs in Inventory Health, an
  // unlisted buy belongs in the listing form; only the pipeline's own fixes stay on this page.
  function actionButtonHtml(a) {
    if (a.target === 'inventory')
      return `<button class="btn btn-secondary small dp-go-inventory" type="button">Open Inventory Health</button>`;
    if (a.label === 'Apply what you paid')
      return `<button class="btn btn-primary small dp-apply-cost" type="button" data-id="${a.dealId}">Apply it</button>`;
    const next = DP_NEXT_STAGE[a.stage];
    if (next)
      return `<button class="btn btn-secondary small dp-move" type="button" data-id="${a.dealId}" data-stage="${next}">Mark ${esc(DP_STAGES[next].label.toLowerCase())}</button>`;
    return `<button class="btn btn-ghost small dp-edit" type="button" data-id="${a.dealId}">Open</button>`;
  }

  function renderPipelineBoard(stages, deals) {
    const host = $('dp-board');
    if (!host) return;

    host.innerHTML = stages.map(col => {
      const cards = deals.filter(d => d.stage === col.stage);
      // Money means a different thing per column, and one shared label would be wrong in three of
      // the four: what's at risk on the way in, what came back at the end.
      // Blank on an empty column: the dashed placeholder below already carries the blurb, and
      // printing it twice makes an empty column look like a rendering fault.
      const moneyLine = !col.count ? ''
        : col.stage === 'sold'
        ? (col.realizedProfit ? `${moneyExact(col.realizedProfit)} realized` : `${moneyExact(col.capital)} deployed`)
        : col.capital > 0 ? `${moneyExact(col.capital)} at risk`
        : col.projectedProfit > 0 ? `${moneyExact(col.projectedProfit)} projected`
        : DP_STAGES[col.stage]?.blurb || '';

      return `
        <div class="dp-col dp-col-${esc(col.stage)}">
          <div class="dp-col-head">
            <span class="dp-col-title">${DP_STAGES[col.stage]?.icon || ''} ${esc(col.label)}</span>
            <span class="dp-col-count">${col.count}</span>
          </div>
          <p class="dp-col-money">${esc(moneyLine)}</p>
          <div class="dp-col-body">
            ${cards.length ? cards.map(dealCardHtml).join('')
              : `<p class="dp-col-empty">${esc(DP_STAGES[col.stage]?.blurb || '')}</p>`}
          </div>
        </div>`;
    }).join('');
  }

  function dealCardHtml(c) {
    const d = c.deal || {};
    const next = DP_NEXT_STAGE[c.stage];

    // Projected and realized never share a row and never share a colour. On a closed deal the
    // realized figure leads and the forecast becomes context for it.
    const moneyRows = [];
    if (c.realizedProfit != null)
      moneyRows.push(`<span class="dp-money-row"><span>Made</span><b class="${c.realizedProfit < 0 ? 'dp-loss' : 'dp-realized'}">${moneyExact(c.realizedProfit)}</b></span>`);
    if (c.expectedProfit != null && c.realizedProfit == null)
      moneyRows.push(`<span class="dp-money-row"><span>Projected</span><b class="dp-projected">${moneyExact(c.expectedProfit)}</b></span>`);
    else if (c.forecastProfit != null && c.realizedProfit == null && c.expectedProfit == null)
      moneyRows.push(`<span class="dp-money-row"><span>Projected</span><b class="dp-projected">${moneyExact(c.forecastProfit)}</b></span>`);
    if (c.realizedProfit != null && c.expectedProfit != null)
      moneyRows.push(`<span class="dp-money-row dp-money-quiet"><span>Was projected</span><b>${moneyExact(c.expectedProfit)}</b></span>`);
    if (c.capitalAtRisk > 0)
      moneyRows.push(`<span class="dp-money-row dp-money-quiet"><span>Your cash in it</span><b>${moneyExact(c.capitalAtRisk)}</b></span>`);

    const meta = [
      d.quantity > 1 ? `×${d.quantity}` : '',
      d.sourceLabel || (d.source && d.source !== 'manual' ? d.source : ''),
      c.daysInStage > 0 ? `${c.daysInStage}d in ${esc(c.stageLabel.toLowerCase())}` : 'today',
      c.daysToCashActual != null ? `${c.daysToCashActual}d to cash` : '',
    ].filter(Boolean).join(' · ');

    return `
      <article class="dp-card${c.nextAction ? ` dp-card-${esc(c.nextAction.urgency)}` : ''}" data-id="${d.id}">
        <header class="dp-card-head">
          ${d.sourceUrl
            ? `<a class="dp-card-title" href="${esc(d.sourceUrl)}" target="_blank" rel="noopener">${esc(d.title)} ↗</a>`
            : `<span class="dp-card-title">${esc(d.title)}</span>`}
          <button class="btn btn-ghost small dp-del" type="button" data-id="${d.id}" title="Remove this deal from the board">✕</button>
        </header>
        <p class="dp-card-meta">${esc(meta)}${c.stageAutoDerived ? ' · <span class="dp-auto">moved by an imported sale</span>' : ''}</p>
        <div class="dp-card-money">${moneyRows.join('')}</div>
        ${(c.flags || []).map(f => `<p class="dp-card-flag">${esc(f)}</p>`).join('')}
        ${d.projectedBasis ? `<p class="dp-card-basis">Forecast from ${esc(d.projectedBasis)}</p>` : ''}
        <footer class="dp-card-foot">
          ${next ? `<button class="btn btn-secondary small dp-move" type="button" data-id="${d.id}" data-stage="${next}">${esc(dpMoveLabel(next))}</button>` : ''}
          <button class="btn btn-ghost small dp-edit" type="button" data-id="${d.id}">Edit</button>
          ${c.stage !== 'sold' ? `<button class="btn btn-ghost small dp-drop" type="button" data-id="${d.id}" title="Didn't happen, or written off">Drop</button>` : ''}
        </footer>
      </article>`;
  }

  function dpMoveLabel(stage) {
    return { bought: 'I bought it', listed: 'It\'s listed', sold: 'It sold' }[stage] || 'Move';
  }

  function onPipelineClick(e) {
    const move = e.target.closest?.('.dp-move');
    if (move) { openStageForm(Number(move.dataset.id), move.dataset.stage); return; }

    const drop = e.target.closest?.('.dp-drop');
    if (drop) { openStageForm(Number(drop.dataset.id), 'dropped'); return; }

    const edit = e.target.closest?.('.dp-edit');
    if (edit) { openDealForm(Number(edit.dataset.id)); return; }

    const del = e.target.closest?.('.dp-del');
    if (del) { deleteDeal(Number(del.dataset.id)); return; }

    const apply = e.target.closest?.('.dp-apply-cost');
    if (apply) { applyDealCost(Number(apply.dataset.id)); return; }

    if (e.target.closest?.('.dp-go-inventory')) { navigateTo('inventory'); return; }
  }

  // ── Add / edit ────────────────────────────────────────────────────────────

  let dealFormId = null;

  function openDealForm(id) {
    dealFormId = id || null;
    const c = id ? (pipeline?.deals || []).find(x => x.id === id) : null;
    const d = c?.deal;

    setText('dp-add-title', d ? 'Edit this deal' : 'Add a deal');
    const save = $('dp-add-save');
    if (save) save.textContent = d ? 'Save changes' : 'Track this deal';

    setVal('dp-f-title', d?.title || '');
    setVal('dp-f-stage', c?.stage === 'sold' || c?.stage === 'dropped' ? 'listed' : (c?.stage || 'sourced'));
    setVal('dp-f-qty', d?.quantity || 1);
    setVal('dp-f-ask', d?.askPrice ?? '');
    setVal('dp-f-paid', d?.purchasePrice ?? '');
    setVal('dp-f-extra', d?.purchaseExtraCost || '');
    setVal('dp-f-resale', d?.projectedSalePrice ?? '');
    setVal('dp-f-listing', d?.listingId || '');
    setVal('dp-f-sku', d?.sku || '');
    setVal('dp-f-url', d?.sourceUrl || '');
    setVal('dp-f-note', d?.note || '');

    // The stage picker is disabled on an existing deal: moving a card is the stage modal's job,
    // which asks for what that move actually needs. Two ways to do it is how one of them ends up
    // recording a purchase with no price.
    const stage = $('dp-f-stage');
    if (stage) stage.disabled = !!d;

    $('dp-add-error')?.classList.add('hidden');
    updateDealPreview();
    loadDealFeeProfile().then(updateDealPreview);
    $('dp-add-modal')?.classList.remove('hidden');
    $('dp-f-title')?.focus();
  }

  function closeDealForm() {
    $('dp-add-modal')?.classList.add('hidden');
    dealFormId = null;
  }

  // The same one-dollar-per-dollar identity the server uses, so the number the seller sees while
  // typing is the number the board will show.
  function updateDealPreview() {
    const qty = Math.max(1, num('dp-f-qty') || 1);
    const ask = num('dp-f-ask');
    const paid = num('dp-f-paid');
    const resale = num('dp-f-resale');
    const extra = num('dp-f-extra') || 0;
    const cost = paid != null ? paid : ask;
    const el = $('dp-add-preview');
    if (!el) return;

    if (resale == null || cost == null) {
      el.textContent = 'Enter what you\'d pay and what it should sell for to see the projected profit.';
      el.className = 'er-log-preview';
      return;
    }

    // Deliberately a rough net, and labelled as one: this form has no comps behind it, so it uses
    // the fee rate from the seller's own Fees & Costs settings and says the number is an estimate.
    const fees = resale * (dealFeeProfile?.ebayFinalValueFeePercent ?? 13.25) / 100
      + (dealFeeProfile?.ebayFinalValueFeeFixed ?? 0.4);
    const net = (resale - cost - fees) * qty - extra;
    el.textContent = `About ${moneyExact(net)} net across ${qty} unit${qty === 1 ? '' : 's'} — ${moneyExact(resale)} sale less ${moneyExact(cost)} cost and roughly ${moneyExact(fees)} of eBay fees${extra ? `, less ${moneyExact(extra)} of extras` : ''}. Estimated from your fee settings, not from sold comps.`;
    el.className = `er-log-preview ${net > 0 ? 'er-preview-good' : 'er-preview-bad'}`;
  }

  async function saveDealForm() {
    const title = ($('dp-f-title')?.value || '').trim();
    if (!title) { showDealError('Give it a name so you can find it on the board.'); return; }

    const stage = dealFormId ? undefined : ($('dp-f-stage')?.value || 'sourced');
    const paid = num('dp-f-paid');
    if (!dealFormId && (stage === 'bought' || stage === 'listed') && paid == null) {
      showDealError('Record what you paid — that\'s the number that tells you what\'s at risk.');
      return;
    }

    const resale = num('dp-f-resale');
    const ask = num('dp-f-ask');
    const qty = Math.max(1, num('dp-f-qty') || 1);
    const cost = paid != null ? paid : ask;
    const fees = resale != null
      ? resale * (dealFeeProfile?.ebayFinalValueFeePercent ?? 13.25) / 100 + (dealFeeProfile?.ebayFinalValueFeeFixed ?? 0.4)
      : null;

    const payload = {
      id: dealFormId || undefined,
      stage,
      title,
      quantity: qty,
      askPrice: ask ?? undefined,
      purchasePrice: paid ?? undefined,
      purchaseExtraCost: num('dp-f-extra') ?? undefined,
      projectedSalePrice: resale ?? undefined,
      // A hand-entered deal has no comps behind it, so the basis says exactly that rather than
      // borrowing the credibility of the sourced-from-comps forecasts on the same board.
      projectedNetProfit: (resale != null && cost != null) ? round2(resale - cost - fees) : undefined,
      projectedBasis: (resale != null && cost != null) ? 'your own estimate, at your fee settings' : undefined,
      listingId: ($('dp-f-listing')?.value || '').trim(),
      sku: ($('dp-f-sku')?.value || '').trim(),
      sourceUrl: ($('dp-f-url')?.value || '').trim(),
      note: ($('dp-f-note')?.value || '').trim(),
    };

    try {
      const res = await fetch('/api/deals', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error(await res.text());
      pipeline = await res.json();
      closeDealForm();
      renderPipeline();
      renderDashboardPipeline();
      setPipelineNotice('');
      addActivity(dealFormId ? 'Deal updated' : 'Deal tracked', title);
    } catch (e) {
      showDealError(errorText(e));
    }
  }

  function showDealError(message) {
    const el = $('dp-add-error');
    if (!el) return;
    el.textContent = message;
    el.classList.remove('hidden');
  }

  // ── Moving a card ─────────────────────────────────────────────────────────

  let stageFormId = null;
  let stageFormTarget = null;

  function openStageForm(id, stage) {
    const c = (pipeline?.deals || []).find(x => x.id === id);
    if (!c) return;
    stageFormId = id;
    stageFormTarget = stage;
    const d = c.deal;

    setText('dp-stage-title', `${d.title} → ${DP_STAGES[stage]?.label || 'Dropped'}`);

    const hints = {
      bought: 'What you actually paid is the number everything else on this board is measured against — it sets your capital at risk, your real profit when it sells, and the break-even floor Inventory Health uses.',
      listed: 'The eBay listing ID is what lets the sale find its way back to this deal. Adding it also records what you paid as the listing\'s cost basis, so the profit gets counted in Money Made without you typing the price twice.',
      sold: 'Only for a sale this app can\'t see — a local cash deal, or another marketplace. eBay sales move this card by themselves once they\'re imported into Money Made.',
      dropped: 'Takes it off the board. If you already paid for it, the money stays counted as spent — a write-off is a real loss, not a deal that never happened.',
    };
    setText('dp-stage-hint', hints[stage] || '');

    document.querySelectorAll('.dp-stage-buy').forEach(el => el.classList.toggle('hidden', stage !== 'bought'));
    document.querySelectorAll('.dp-stage-list').forEach(el => el.classList.toggle('hidden', stage !== 'listed'));
    document.querySelectorAll('.dp-stage-sold').forEach(el => el.classList.toggle('hidden', stage !== 'sold'));
    document.querySelectorAll('.dp-stage-drop').forEach(el => el.classList.toggle('hidden', stage !== 'dropped'));

    // Pre-filled from what the deal already knows: the ask is the obvious opening guess at what
    // was paid, and the projected sale price at what it'll be listed for.
    setVal('dp-s-paid', d.purchasePrice ?? d.askPrice ?? '');
    setVal('dp-s-extra', d.purchaseExtraCost || '');
    setVal('dp-s-bought', todayInputValue());
    setVal('dp-s-listing', d.listingId || '');
    setVal('dp-s-sku', d.sku || '');
    setVal('dp-s-price', d.listedPrice ?? d.projectedSalePrice ?? '');
    setVal('dp-s-sold', todayInputValue());
    setVal('dp-s-note', d.note || '');

    const preview = $('dp-stage-preview');
    if (preview) {
      // Says out loud what pressing the button will do to a number somewhere else in the app.
      const willWrite = stage === 'listed' && (d.purchasePrice != null);
      preview.textContent = willWrite
        ? `This will also record ${moneyExact(d.purchasePrice)} as what this listing cost you, which is what makes any sale of it count as real profit.`
        : '';
      preview.classList.toggle('hidden', !willWrite);
    }

    $('dp-stage-error')?.classList.add('hidden');
    $('dp-stage-modal')?.classList.remove('hidden');
  }

  function closeStageForm() {
    $('dp-stage-modal')?.classList.add('hidden');
    stageFormId = null;
    stageFormTarget = null;
  }

  async function saveStageForm() {
    if (!stageFormId || !stageFormTarget) return;
    const payload = { stage: stageFormTarget };

    if (stageFormTarget === 'bought') {
      const paid = num('dp-s-paid');
      if (paid == null) { showStageError('Enter what you paid — that\'s what puts a number on your risk.'); return; }
      payload.purchasePrice = paid;
      payload.purchaseExtraCost = num('dp-s-extra') ?? 0;
      payload.boughtUtc = dateInputToUtc('dp-s-bought');
    } else if (stageFormTarget === 'listed') {
      payload.listingId = ($('dp-s-listing')?.value || '').trim();
      payload.sku = ($('dp-s-sku')?.value || '').trim();
      payload.listedPrice = num('dp-s-price') ?? undefined;
      payload.listedUtc = new Date().toISOString();
    } else if (stageFormTarget === 'sold') {
      payload.soldUtc = dateInputToUtc('dp-s-sold');
    } else if (stageFormTarget === 'dropped') {
      payload.note = ($('dp-s-note')?.value || '').trim();
    }

    try {
      const res = await fetch(`/api/deals/${stageFormId}/stage`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error(await res.text());
      const result = await res.json();
      pipeline = result.pipeline;
      closeStageForm();
      renderPipeline();
      renderDashboardPipeline();
      setPipelineNotice(result.message || '');
    } catch (e) {
      showStageError(errorText(e));
    }
  }

  function showStageError(message) {
    const el = $('dp-stage-error');
    if (!el) return;
    el.textContent = message;
    el.classList.remove('hidden');
  }

  async function applyDealCost(id) {
    try {
      const res = await fetch(`/api/deals/${id}/apply-cost`, { method: 'POST' });
      if (!res.ok) throw new Error(await res.text());
      const result = await res.json();
      pipeline = result.pipeline;
      renderPipeline();
      renderDashboardPipeline();
      setPipelineNotice(result.message || '');
      // The money it just unlocked lives on the other page, so that page's copy is now stale.
      loadEarnings(true);
    } catch (e) {
      setPipelineNotice(`Couldn't apply that cost: ${errorText(e)}`);
    }
  }

  async function deleteDeal(id) {
    const c = (pipeline?.deals || []).find(x => x.id === id);
    if (!confirm(`Remove "${c?.deal?.title || 'this deal'}" from the board? Any completed sales stay in Money Made.`)) return;
    try {
      const res = await fetch(`/api/deals/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error(await res.text());
      pipeline = await res.json();
      renderPipeline();
      renderDashboardPipeline();
    } catch (e) {
      setPipelineNotice(`Couldn't remove that deal: ${errorText(e)}`);
    }
  }

  // The front-page band. Same rule as the earnings band: hidden until there is real money behind
  // it, because "$0 in motion" on a fresh install reads as the app being broken.
  function renderDashboardPipeline() {
    const band = $('dash-pipeline');
    if (!band) return;
    const s = pipeline?.summary;
    if (!s || (s.capitalAtRisk || 0) <= 0) { band.classList.add('hidden'); return; }

    band.classList.remove('hidden');
    countUpText('dash-pipeline-figure', s.capitalAtRisk, moneyExact);

    const bits = [`${s.activeDeals} deal${s.activeDeals === 1 ? '' : 's'} in play`];
    if (s.projectedProfitInMotion > 0) bits.push(`${moneyExact(s.projectedProfitInMotion)} projected on it`);
    if (s.realizedProfit > 0) bits.push(`${moneyExact(s.realizedProfit)} already realized`);
    setText('dash-pipeline-sub', bits.join(' · '));

    const top = (pipeline.nextActions || [])[0];
    const host = $('dash-pipeline-next');
    if (host) {
      host.innerHTML = top
        ? `<span class="dash-pipeline-next-label">Next</span><span class="dash-pipeline-next-text">${esc(top.label)} — ${esc(top.title)}</span>`
        : '';
    }
  }

  function num(id) {
    const raw = ($(id)?.value ?? '').trim();
    if (raw === '') return null;
    const value = parseFloat(raw);
    return isNaN(value) ? null : value;
  }

  function round2(value) {
    return Math.round(value * 100) / 100;
  }

  function todayInputValue() {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }

  // A date input is a local calendar day. Sent as local noon so a UTC conversion can never move it
  // to the day before, which would silently misdate a purchase and skew every day-count on the board.
  function dateInputToUtc(id) {
    const raw = ($(id)?.value || '').trim();
    if (!raw) return undefined;
    const [y, m, d] = raw.split('-').map(Number);
    if (!y || !m || !d) return undefined;
    return new Date(y, m - 1, d, 12, 0, 0).toISOString();
  }

  // ── Rising-Demand / Price-Trend Radar ─────────────────────────────────────
  // Every other screen in this app prices the present tense. This one reads the sold-comps database
  // as a time series and answers "what is on its way up?" — because a sourcer's cheapest margin is
  // buying at last month's price. Everything below comes from /api/trends/radar, which measures the
  // trend itself and then prices the survivors through the same pipeline the rest of the app uses.
  //
  // Two things this UI must never do, both of which would turn it into a horoscope:
  //   * show a trend without showing how much of it was actually measured (the corpus banner, the
  //     sold counts and the tentative badge are all load-bearing, not decoration), and
  //   * let the projected price sit anywhere near the "max to pay" column. What to pay comes from
  //     today's price; the climb is reported separately, as upside.
  let trendScan = null;

  // ── Ship Smart — the Shipping Profit Engine ────────────────────────────────────────────────
  // Two views of one number. The quote panel prices a single package end to end; the leak scan
  // runs the same maths over every live listing and reports the gap against the one flat shipping
  // figure the rest of the app has been assuming. Both are read-only — no labels, no listing edits.

  let shipScan = null;   // last ShippingScanResult, kept so filtering never re-scans

  async function showShippingSection() {
    hideOverlaySections();
    $('shipping-section')?.classList.remove('hidden');
    setActiveNavItem('shipping');
    markWorkspaceTabOpen('shipping');

    // Zones only exist relative to an origin, and the seller already told us theirs once. Filling
    // it in beats asking again — a blank ZIP silently falls back to the national average, which is
    // the right default but the wrong answer for anyone on a coast.
    const zip = $('ship-zip');
    if (zip && !zip.value) {
      try {
        const res = await fetch('/api/setup/fields');
        if (res.ok) zip.value = (await res.json())?.defaultPostalCode || '';
      } catch { /* the quote still works without it */ }
    }
  }

  function closeShippingSection() {
    closeWorkspacePage('shipping');
  }

  // ── WhatsNot: embedded live-feed browser ─────────────────────────────────────
  // An <iframe> pointed at a live-selling feed, with the three things a frame in a
  // panel is otherwise missing: somewhere to go back to, the address it was left on
  // last time, and an answer when it comes up blank.
  //
  // That last one is the whole reason this is more than an <iframe>. A site that
  // sends X-Frame-Options / CSP frame-ancestors is blocked BEFORE anything renders
  // and the embedding page is told nothing — no error, no event, no readable
  // document. Blank looks exactly like a slow feed, a signed-out feed, or a bug in
  // this app. So the app asks the site itself, server-side, and says which it is.
  //
  // Back/Forward walk THIS panel's list of loaded addresses. They cannot be the
  // frame's own history: a page may not read, or move, where a cross-origin frame
  // has navigated. Claiming otherwise would be a button that silently does the
  // wrong thing, which is worse than not having it.
  const WN_HOME_URL = 'https://www.whatnot.com/live';
  const WN_URL_KEY = 'whatsnotFeedUrl';
  const WN_RECENT_KEY = 'whatsnotRecentUrls';
  const WN_RECENT_MAX = 8;
  // Long enough that a heavy live page isn't accused of being blocked; short enough
  // to still be useful while the item on screen is being bid on.
  const WN_SLOW_MS = 12000;

  let wnHistory = [];
  let wnHistoryAt = -1;
  let wnSlowTimer = null;
  let wnCheckToken = 0;

  function wnNormalizeUrl(raw) {
    let u = (raw || '').trim();
    if (!u) return '';
    if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
    return u;
  }

  function wnHost(url) {
    try { return new URL(url).host; } catch { return url; }
  }

  // ── What the panel remembers ─────────────────────────────────────────────────
  // The seller watches the same one or two feeds. Retyping the address every time
  // the tab is opened is the kind of small friction that stops a screen being used.
  // Where the panel is NOW, saved on every load including Back and Forward — reopening the tab
  // should put back the feed that was on screen, not the last one that happened to be typed.
  function wnSaveLastUrl(url) {
    try { localStorage.setItem(WN_URL_KEY, url); }
    catch { /* private mode — the panel still works, it just forgets */ }
  }

  // The recent list is addresses the seller CHOSE, so retracing steps with Back doesn't reorder it.
  function wnAddRecent(url) {
    try {
      const recents = wnRecentUrls().filter(u => u !== url);
      recents.unshift(url);
      localStorage.setItem(WN_RECENT_KEY, JSON.stringify(recents.slice(0, WN_RECENT_MAX)));
    } catch { /* as above */ }
    wnRenderRecents();
  }

  function wnRecentUrls() {
    try {
      const list = JSON.parse(localStorage.getItem(WN_RECENT_KEY) || '[]');
      return Array.isArray(list) ? list.filter(u => typeof u === 'string' && u) : [];
    } catch { return []; }
  }

  function wnRenderRecents() {
    const list = $('wn-recent');
    if (!list) return;
    list.innerHTML = wnRecentUrls().map(u => `<option value="${esc(u)}"></option>`).join('');
  }

  function wnLastUrl() {
    try { return localStorage.getItem(WN_URL_KEY) || ''; } catch { return ''; }
  }

  // ── The status strip ─────────────────────────────────────────────────────────
  function wnStatus(kind, text) {
    const el = $('wn-status');
    if (!el) return;
    if (!text) { el.classList.add('hidden'); el.textContent = ''; return; }
    el.className = `wn-status wn-status-${kind}`;
    el.textContent = text;
  }

  function wnShowBlocked(check) {
    const panel = $('wn-blocked');
    if (!panel) return;
    if (!check) { panel.classList.add('hidden'); return; }
    setText('wn-blocked-title', check.headline || 'This site refuses to be embedded.');
    setText('wn-blocked-detail', check.detail || '');
    setText('wn-blocked-header', check.header || '');
    $('wn-blocked-header')?.classList.toggle('hidden', !check.header);
    panel.classList.remove('hidden');
  }

  // Asks the site — via the app, which is not a frame and so is not refused on those
  // grounds — whether a browser will let this embed happen at all.
  async function wnCheckEmbed(url) {
    const token = ++wnCheckToken;
    wnStatus('checking', `Checking whether ${wnHost(url)} allows embedding…`);
    let check = null;
    try {
      const res = await fetch('/api/whatsnot/embed-check?url=' + encodeURIComponent(url));
      if (res.ok) check = await res.json();
    } catch { /* the frame is loading regardless; the check is advice, not a gate */ }

    // A slower answer about a page the seller has already navigated away from is noise.
    if (token !== wnCheckToken) return;

    // No answer, or one with no verdict in it. Either way the honest report is "couldn't tell" —
    // silence here is the failure this whole check exists to remove.
    if (!check || !check.status) {
      wnStatus('unknown', `Couldn't check whether ${wnHost(url)} allows embedding. The frame may still load.`);
      return;
    }

    if (check.status === 'refused') {
      wnStatus('refused', check.headline + (check.header ? ` (${check.header})` : ''));
      wnShowBlocked(check);
      if (wnSlowTimer) { clearTimeout(wnSlowTimer); wnSlowTimer = null; }
      return;
    }

    wnShowBlocked(null);
    const said = `${check.headline || ''} ${check.detail || ''}`.trim();
    wnStatus(check.status === 'allowed' ? 'ok' : 'unknown',
             said || `${wnHost(url)} didn't say whether it allows embedding.`);
  }

  function wnLoad(url, options) {
    const frame = $('wn-frame');
    const target = wnNormalizeUrl(url || $('wn-url')?.value);
    if (!frame || !target) return;
    const box = $('wn-url');
    if (box) box.value = target;

    // A fresh address truncates anything that was ahead of it, exactly like a browser.
    if (!options || options.push !== false) {
      if (wnHistory[wnHistoryAt] !== target) {
        wnHistory = wnHistory.slice(0, wnHistoryAt + 1);
        wnHistory.push(target);
        wnHistoryAt = wnHistory.length - 1;
      }
      wnAddRecent(target);
    }
    wnSaveLastUrl(target);
    wnUpdateNav();

    wnShowBlocked(null);
    wnStatus('checking', `Loading ${wnHost(target)}…`);
    // Assigning the same src doesn't always reload, so the frame is blanked first —
    // which also stops the previous stream before the next one starts.
    frame.src = 'about:blank';
    frame.src = target;

    if (wnSlowTimer) clearTimeout(wnSlowTimer);
    wnSlowTimer = setTimeout(() => {
      const el = $('wn-status');
      // Only if the check hasn't already said something more definite.
      if (el && el.classList.contains('wn-status-checking')) {
        wnStatus('unknown', `${wnHost(target)} hasn't finished loading. A feed that never renders is ` +
                            'usually a site that refuses to be embedded — try Open in browser.');
      }
    }, WN_SLOW_MS);

    wnCheckEmbed(target);
  }

  function wnUpdateNav() {
    const back = $('wn-back'), forward = $('wn-forward');
    if (back) back.disabled = wnHistoryAt <= 0;
    if (forward) forward.disabled = wnHistoryAt < 0 || wnHistoryAt >= wnHistory.length - 1;
  }

  function wnGo(step) {
    const next = wnHistoryAt + step;
    if (next < 0 || next >= wnHistory.length) return;
    wnHistoryAt = next;
    wnLoad(wnHistory[next], { push: false });
  }

  async function showWhatsNotSection() {
    hideOverlaySections();
    $('whatsnot-section')?.classList.remove('hidden');
    setActiveNavItem('whatsnot');
    markWorkspaceTabOpen('whatsnot');
    wnRenderRecents();
    // What has already been spent tonight. Read on every open rather than once, because the
    // sheet outlives the session — a restart mid-show must come back to the money, not to a
    // blank panel that reads as a night nobody has bought anything on.
    wnLoadSheet();
    // Load the feed on first open; a frame already showing a live stream is left alone on
    // return so tabbing away and back doesn't tear down what the seller is watching.
    const frame = $('wn-frame');
    if (frame && (!frame.src || frame.src === 'about:blank')) {
      const box = $('wn-url');
      const remembered = wnLastUrl();
      if (remembered && box) box.value = remembered;
      wnLoad();
    }

    // A show starts and there are seconds. Opening the tab puts the cursor where the first thing
    // typed has to go — but only when nothing is priced yet, so coming back to a card that is
    // being bid on does not pull the keyboard off whatever was being read.
    if ($('wn-card')?.classList.contains('hidden')) $('wn-item')?.focus();
  }

  function closeWhatsNotSection() {
    // Blank the frame on close so a live stream stops spending bandwidth/CPU unseen.
    const frame = $('wn-frame');
    if (frame) frame.src = 'about:blank';
    if (wnSlowTimer) { clearTimeout(wnSlowTimer); wnSlowTimer = null; }
    wnCheckToken++;
    // A lot list still being priced is a dozen eBay reads for a screen nobody is on.
    // The rows already priced survive the close; the ones behind them are dropped.
    wnStopLotRun();
    closeWorkspacePage('whatsnot');
  }

  // ── WhatsNot: the live-auction arbitrage card ────────────────────────────────
  // While an item is on screen and the bidding is running, this asks /api/whatsnot/bid
  // for the ceiling and the eBay statistics behind it. The numbers are the app's own
  // sold-comps + sell-through path (the same one the Opportunity Finder runs) — nothing
  // here computes money, it only lays it out.
  //
  // The three settings that don't change between items — shipping, the platform's buyer
  // premium and the target return — are remembered, because during a live sale there is
  // time to type the item's name and nothing else.
  const WN_SETTINGS_KEY = 'whatsnotBidSettings';

  function wnLoadSettings() {
    let saved = {};
    try { saved = JSON.parse(localStorage.getItem(WN_SETTINGS_KEY) || '{}') || {}; }
    catch { saved = {}; }
    if (saved.ship != null) setVal('wn-ship', saved.ship);
    if (saved.fee != null) setVal('wn-fee', saved.fee);
    if (saved.target != null) setVal('wn-target', saved.target);
  }

  function wnSaveSettings() {
    try {
      localStorage.setItem(WN_SETTINGS_KEY, JSON.stringify({
        ship: $('wn-ship')?.value ?? '',
        fee: $('wn-fee')?.value ?? '',
        target: $('wn-target')?.value ?? '',
      }));
    } catch { /* private mode — the fields still work, they just don't persist */ }
  }

  // Empty means "not stated", which is a different answer from zero and has to reach the
  // server as null: the card warns about an unstated buyer premium and cannot warn about
  // one the browser quietly turned into 0.
  function wnNumber(id) {
    const raw = ($(id)?.value ?? '').trim();
    if (!raw) return null;
    const n = parseFloat(raw);
    return Number.isFinite(n) ? n : null;
  }

  // ── Moving the bid ───────────────────────────────────────────────────────────
  // The auctioneer raises the bid every two or three seconds. Re-reading eBay for
  // each one would spend the seconds the decision is made in to arrive at the same
  // resale price the card already had — sold comps do not change while a lot is
  // being sold. So the server holds them and /api/whatsnot/rebid recomputes the
  // whole card against them: the same ceiling function, no network beyond
  // localhost. The card says how old the held comps are, every time.
  //
  // The token is dropped the moment the ITEM changes, because then it is a
  // different question and the held comps are the wrong answer to it.
  let wnToken = '';
  let wnTokenItem = '';
  let wnRebidTimer = null;
  let wnRebidSeq = 0;
  // Long enough to swallow a burst of arrow-key presses, short enough to feel like
  // the number moved when you pressed the button.
  const WN_REBID_DEBOUNCE_MS = 90;

  /// What a bid step is worth at this level. A live sale goes up in dollars at $12
  /// and in twenties at $600, so a fixed step is wrong at one end or useless at the
  /// other. Presentation only — nothing here decides what anything is worth.
  function wnBidStep(bid) {
    const at = Math.max(0, bid || 0);
    if (at < 25) return 1;
    if (at < 100) return 5;
    if (at < 500) return 10;
    if (at < 2000) return 25;
    return 100;
  }

  function wnStepBid(direction) {
    const box = $('wn-bid');
    if (!box) return;
    const current = Math.max(0, wnNumber('wn-bid') || 0);
    const step = wnBidStep(current);
    // Down snaps to the step below rather than subtracting from an odd number, so
    // stepping up and down again lands somewhere predictable.
    const next = direction > 0
      ? current + step
      : Math.max(0, Math.ceil((current - step) / step) * step);
    box.value = String(Math.round(next * 100) / 100);
    wnScheduleRebid();
  }

  /// A held quote answers for one item. Anything that changes what is being priced
  /// throws it away rather than repricing somebody else's comps under a new name.
  function wnDropToken() {
    wnToken = '';
    wnTokenItem = '';
    if (wnRebidTimer) { clearTimeout(wnRebidTimer); wnRebidTimer = null; }
    wnRebidSeq++;
  }

  function wnScheduleRebid() {
    if (!wnToken) return;                       // nothing priced yet — Price it reads eBay
    if (wnRebidTimer) clearTimeout(wnRebidTimer);
    wnRebidTimer = setTimeout(wnRebid, WN_REBID_DEBOUNCE_MS);
  }

  async function wnRebid() {
    wnRebidTimer = null;
    if (!wnToken) return;

    const seq = ++wnRebidSeq;
    try {
      const { res, body } = await safePost('/api/whatsnot/rebid', {
        token: wnToken,
        title: wnTokenItem,
        currentBid: wnNumber('wn-bid'),
        shippingCost: wnNumber('wn-ship'),
        buyerFeePercent: wnNumber('wn-fee'),
        targetRoiPercent: wnNumber('wn-target'),
      });
      // The bid moved again while this was in flight. An older answer painted over a
      // newer one is the one failure that would make the card lie about the number
      // on screen, which is the whole point of it.
      if (seq !== wnRebidSeq) return;

      if (!res.ok) {
        // The comps were let go. Say so on the card and stop re-pricing against a
        // token the server has forgotten — the way back is an explicit fresh read.
        wnDropToken();
        wnSaveSettings();
        wnHeldNote(body.failure?.whatToDo || body.error || 'Press Price it to read eBay again.');
        return;
      }
      wnRenderCard(body);
    } catch {
      // A dropped local request is not worth a red card; the numbers on screen are
      // still the ones from the last answer, and the next keystroke tries again.
    }
  }

  /// Replaces the held-comps line with a plain sentence when a re-price could not
  /// happen. Leaves every number on the card alone — they were true when priced.
  function wnHeldNote(text) {
    const el = $('wn-held');
    if (!el) return;
    el.className = 'wn-held wn-held-stale';
    el.textContent = text;
  }

  async function wnPriceItem() {
    const item = ($('wn-item')?.value || '').trim();
    const card = $('wn-card');
    if (!card) return;

    if (!item) {
      // The empty ask is the one failure the seller caused, so it is said in the live region
      // too — a message painted only into the card is silent to somebody who pressed the
      // button from the keyboard and never looked away from the stream.
      card.classList.remove('hidden');
      card.innerHTML = '<p class="wn-empty">Type what\'s on screen — the brand and model are what the sold search runs on.</p>';
      wnSayLine("Nothing to price — type what's on screen.");
      $('wn-item')?.focus();
      return;
    }

    wnSaveSettings();
    // A fresh read supersedes anything held, including an answer still in flight.
    wnDropToken();
    const btn = $('wn-price');
    // Disabling the focused button drops the keyboard to <body>, which during a live sale is a
    // seller pressing keys at nothing. The button is put back under the same finger afterwards.
    const btnHadFocus = document.activeElement === btn;
    if (btn) { btn.disabled = true; btn.setAttribute('aria-busy', 'true'); btn.textContent = 'Pricing…'; }
    card.classList.remove('hidden');
    card.innerHTML = `<p class="wn-empty">Checking eBay sold comps for <strong>${esc(item)}</strong>…</p>`;
    wnSayLine(`Checking eBay sold comps for ${item}…`);

    try {
      const { res, body } = await safePost('/api/whatsnot/bid', {
        title: item,
        currentBid: wnNumber('wn-bid'),
        shippingCost: wnNumber('wn-ship'),
        buyerFeePercent: wnNumber('wn-fee'),
        targetRoiPercent: wnNumber('wn-target'),
      });
      if (!res.ok) {
        // The headline alone is a diagnosis with no next move — "Nothing to price" without the
        // sentence that says what to type. The server always sends both; the card was only ever
        // reading the first one.
        const headline = body.error || 'That didn\'t price.';
        const whatToDo = body.failure?.whatToDo || '';
        card.innerHTML = `<p class="wn-empty wn-empty-bad">${esc(headline)}</p>` +
          (whatToDo ? `<p class="wn-empty wn-empty-do">${esc(whatToDo)}</p>` : '');
        wnSayLine(whatToDo ? `${headline} ${whatToDo}` : headline);
        return;
      }
      // The comps behind this answer are now held server-side; from here the bid,
      // the shipping, the fee and the target all move without touching eBay.
      wnToken = body.token || '';
      wnTokenItem = item;
      wnRenderCard(body);
    } catch (err) {
      const said = errorText(err, 'That didn\'t price.');
      card.innerHTML = `<p class="wn-empty wn-empty-bad">${esc(said)}</p>`;
      wnSayLine(said);
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.removeAttribute('aria-busy');
        btn.textContent = '⚡ Price it';
        if (btnHadFocus) btn.focus();
      }
    }
  }

  /// ── The one line ────────────────────────────────────────────────────────────
  /// The card is replaced whole on every arrow key, so it is not a live region and
  /// must not become one: a screen reader given the ladder, five stat tiles and a
  /// comp table three times a lot is a screen reader saying nothing usable. This
  /// single line is, and it is also the only part of the answer that stays in the
  /// same place while the bidding climbs.
  ///
  /// The sentence is `card.say`, painted verbatim. Nothing here assembles it — see
  /// Services/LiveBidSpeech.cs for why the words about money live next to the money.
  function wnSayLine(text, call) {
    const el = $('wn-say');
    if (!el) return;
    const said = (text || '').trim();
    el.textContent = said;
    // The call colours the stripe, using the same four names the badge and the lot
    // rows use. Anything else that arrives is dropped rather than turned into a class.
    const known = ['bid', 'risky', 'stop', 'no_data'].includes(call) ? ` wn-say-${call}` : '';
    el.className = `wn-say${known}${said ? '' : ' hidden'}`;
  }

  function wnStat(label, value, note) {
    return `<div class="wn-stat"><div class="wn-stat-label">${esc(label)}</div>` +
           `<div class="wn-stat-value">${esc(value)}</div>` +
           `<div class="wn-stat-note">${esc(note || '')}</div></div>`;
  }

  // ── WhatsNot: your own record with this thing ────────────────────────────────
  // Everything else on the card is the market's evidence. This is the seller's own:
  // what THEY got for the last ones after the fee eBay actually charged them, how
  // long it took, and how many of these they are already sitting on unsold.
  //
  // It renders what the server decided and computes nothing. The second ceiling, the
  // comparison sentence and the headline are all written next to the arithmetic in
  // Services/OwnTrackRecord.cs, because a "your ceiling is $48" assembled here out of
  // an average would be a second opinion about money that nothing tests.
  function wnOwnBlock(own) {
    if (!own) return '';

    const money2 = v => (v == null ? '—' : moneyExact(v));
    const has = own.verdict === 'proven' || own.verdict === 'once';

    // Nothing sold and nothing held: one quiet line. It still earns its place — "you
    // have never sold one of these" is the difference between a repeat buy and a punt,
    // and a blank space says neither.
    if (!has && !own.unitsHeld) {
      return `<p class="wn-own-empty">${esc(own.headline)}</p>`;
    }

    const tiles = has ? `
      <div class="wn-own-tiles">
        ${wnStat("You've sold", `${own.unitsSold}`, own.daysSinceLastSale == null ? ''
          : (own.daysSinceLastSale === 0 ? 'last one today' : `last one ${own.daysSinceLastSale}d ago`))}
        ${wnStat('You got', money2(own.averageSalePrice), 'each, before fees')}
        ${wnStat('Your net each', money2(own.averageNetProfit),
          own.averageUnitCost == null ? 'no cost recorded' : `on ${moneyExact(own.averageUnitCost)} of stock`)}
        ${wnStat('Your sell time', own.medianDaysToSell == null ? '—' : `${own.medianDaysToSell} days`,
          own.medianDaysToSell == null ? 'no purchase dates recorded' : 'bought to sold, median')}
        ${own.unitsHeld ? wnStat('Still holding', `${own.unitsHeld}`,
          own.oldestHeldDays == null ? 'bought, not sold' : `oldest ${own.oldestHeldDays}d ago`) : ''}
      </div>` : (own.unitsHeld ? `
      <div class="wn-own-tiles">
        ${wnStat('Still holding', `${own.unitsHeld}`,
          own.oldestHeldDays == null ? 'bought, not sold' : `oldest ${own.oldestHeldDays}d ago`)}
        ${wnStat('Your money in it', money2(own.capitalHeld), 'before tonight')}
      </div>` : '');

    // The seller's own ceiling, beside the badge's. Only ever the server's sentence,
    // and flagged when it is the LOWER of the two — that is the case that costs money,
    // because the badge is then the optimistic number.
    const ceiling = own.ceilingComparison
      ? `<p class="wn-own-ceiling${own.ceilingIsLower ? ' wn-own-ceiling-low' : ''}${own.ownIsTheOnlyCeiling ? ' wn-own-ceiling-only' : ''}">
           ${own.ownMaxBid > 0 ? `<strong>Your ceiling ${moneyExact(own.ownMaxBid)}</strong> — ` : ''}${esc(own.ceilingComparison)}
         </p>`
      : '';

    const notes = (own.notes || []).length
      ? `<ul class="wn-own-notes">${own.notes.map(n => `<li>${esc(n)}</li>`).join('')}</ul>`
      : '';

    const sales = (own.sales || []).length ? `
      <details class="wn-own-sales">
        <summary>Your ${own.sales.length} most recent ${own.sales.length === 1 ? 'sale' : 'sales'} of this</summary>
        <table class="wn-own-table"><tbody>
          ${own.sales.map(s => `<tr>
            <td class="wn-own-cell-title">${esc(s.title)}</td>
            <td class="wn-own-cell-price">${moneyExact(s.salePrice)}</td>
            <td class="wn-own-cell-net">${s.netProfit == null ? '—' : `${moneyExact(s.netProfit)} net`}</td>
            <td class="wn-own-cell-age">${s.daysAgo === 0 ? 'today' : `${s.daysAgo}d ago`}${s.daysHeld == null ? '' : ` · held ${s.daysHeld}d`}</td>
          </tr>`).join('')}
        </tbody></table>
      </details>` : '';

    return `
      <div class="wn-own wn-own-${esc(own.verdict)}">
        <div class="wn-own-head">👤 Your own record — <span class="wn-own-headline">${esc(own.headline)}</span></div>
        ${tiles}
        ${ceiling}
        ${notes}
        ${sales}
      </div>`;
  }

  function wnRenderCard(c) {
    const card = $('wn-card');
    if (!card) return;

    wnSayLine(c.say, c.call);

    const priced = c.call !== 'no_data';
    const spread = (c.priceLow > 0 && c.priceHigh > 0)
      ? `${money(c.priceLow)} – ${money(c.priceHigh)}`
      : '—';

    // The rate has no denominator when nothing comparable is listed. A dash is the honest
    // rendering; a 100% off zero active listings is how thin data wears a green badge.
    const sellThrough = c.sellThroughUnbounded ? '—'
      : (c.sellThroughRate == null ? '—' : `${c.sellThroughRate.toFixed(1)}%`);
    const velocity = c.daysToSell ? `${c.daysToSell} days` : '—';
    const velocityNote = c.estimatedMonthlySales > 0
      ? `about ${c.estimatedMonthlySales.toFixed(1)} sell a month`
      : (c.speedLabel || 'no dated sold history');

    const money2 = v => (v == null ? '—' : moneyExact(v));

    const ladder = priced ? `
      <div class="wn-ladder">
        <div class="wn-rung"><span>Bid now</span><strong>${c.bidWasKnown ? money2(c.currentBid) : 'not started'}</strong></div>
        <div class="wn-rung wn-rung-stop"><span>Stop at</span><strong>${money2(c.maxBid)}</strong></div>
        <div class="wn-rung"><span>Break-even</span><strong>${money2(c.breakEvenBid)}</strong></div>
        <div class="wn-rung"><span>Room left</span><strong class="${c.headroom < 0 ? 'wn-neg' : ''}">${money2(c.headroom)}</strong></div>
        <div class="wn-rung"><span>Resells for</span><strong>${money2(c.resalePrice)}</strong></div>
      </div>` : '';

    // ── The meter ──────────────────────────────────────────────────────────────
    // The ladder has the numbers; this is for the two seconds there are to read
    // them. One track from nothing to the walk-away line, the ceiling marked on it,
    // and the bid on screen sitting somewhere along it — so "how close am I?" is
    // answered by a glance instead of by comparing two dollar figures.
    //
    // Positions only. Every boundary drawn here is a number the server computed;
    // this divides them to get a percentage of a bar and does no other arithmetic.
    const meter = (priced && c.breakEvenBid > 0) ? (() => {
      const pct = v => Math.max(0, Math.min(100, (v / c.breakEvenBid) * 100));
      const ceiling = pct(c.maxBid);
      const bidPct = c.bidWasKnown ? pct(c.currentBid) : null;
      const past = c.bidWasKnown && c.currentBid > c.maxBid;
      return `
      <div class="wn-meter" role="img" aria-label="${esc(
        (c.bidWasKnown ? `Bid ${moneyExact(c.currentBid)}. ` : '') +
        `Stop at ${moneyExact(c.maxBid)}. Break-even ${moneyExact(c.breakEvenBid)}.`)}">
        <div class="wn-meter-track">
          <div class="wn-meter-good" style="width:${ceiling.toFixed(2)}%"></div>
          <div class="wn-meter-edge" style="left:${ceiling.toFixed(2)}%"></div>
          ${bidPct === null ? '' :
            `<div class="wn-meter-bid${past ? ' wn-meter-bid-past' : ''}" style="left:${bidPct.toFixed(2)}%"></div>`}
        </div>
        <div class="wn-meter-legend">
          <span>${c.bidWasKnown ? `bid ${moneyExact(c.currentBid)}` : 'no bid yet'}</span>
          <span class="wn-meter-mid">stop at ${moneyExact(c.maxBid)}</span>
          <span>loses money past ${moneyExact(c.breakEvenBid)}</span>
        </div>
      </div>`;
    })() : '';

    // ── The hammer ─────────────────────────────────────────────────────────────
    // Only while the comps are held, because that is what the server records a win
    // against: a win with no sold history behind it would be a real spend sitting
    // next to an invented resale price, and the night's totals would carry it.
    //
    // The label tracks the bid box, so the button always says the price it is about
    // to write down. Past the ceiling it says so — a lot can be won above it, and
    // the sheet's whole discipline half depends on that being recorded rather than
    // refused.
    const overCeiling = c.bidWasKnown && c.maxBid > 0 && c.currentBid > c.maxBid;
    const won = c.token ? `
      <div class="wn-won">
        <button type="button" data-won="1"
                class="btn wn-won-btn${overCeiling ? ' wn-won-btn-over' : ''}"
                title="Record this lot as won at the bid above — it goes on tonight's buy sheet">
          🔨 Won it${c.bidWasKnown ? ` at ${moneyExact(c.currentBid)}` : ''}
        </button>
        <span class="wn-won-note">${overCeiling
          ? `That's ${moneyExact(c.currentBid - c.maxBid)} over your ceiling — it will be recorded as such.`
          : 'Costed at the bid you paid, against these same comps. No eBay read.'}</span>
      </div>` : '';

    // Where the resale price came from, and when. A re-priced card is the same
    // computation as a fresh one — what it is not is a fresh READ, and the seller
    // has to be able to see the difference without being told twice.
    const held = c.token ? (c.repricedFromHeldComps
      ? `<p class="wn-held" id="wn-held">Bid moved without re-reading eBay — these sold comps were read ` +
        `${c.compsAgeSeconds < 60 ? `${Math.max(1, c.compsAgeSeconds)}s` : `${Math.round(c.compsAgeSeconds / 60)} min`} ago. ` +
        `<strong>Price it</strong> reads them again.</p>`
      : `<p class="wn-held" id="wn-held">Comps read just now and held — moving the bid, shipping, fee or target ` +
        `re-answers instantly against this same sold history.</p>`) : '';

    const warnings = (c.warnings || []).length
      ? `<ul class="wn-warnings">${c.warnings.map(w => `<li>${esc(w)}</li>`).join('')}</ul>`
      : '';

    const comps = (c.comps || []).length ? `
      <details class="wn-comps">
        <summary>The ${c.comps.length} sold comps behind this</summary>
        <table class="wn-comps-table"><tbody>
          ${c.comps.map(x => `<tr>
            <td class="wn-comp-title">${x.url ? `<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a>` : esc(x.title)}</td>
            <td class="wn-comp-price">${moneyExact(x.totalPrice)}</td>
            <td class="wn-comp-age">${x.ageDays == null ? 'undated' : (x.ageDays === 0 ? 'today' : `${x.ageDays}d ago`)}</td>
          </tr>`).join('')}
        </tbody></table>
      </details>` : '';

    card.innerHTML = `
      <div class="wn-call wn-call-${esc(c.call)}">
        <div class="wn-call-badge">${esc(c.callLabel)}</div>
        <div class="wn-call-body">
          <div class="wn-call-item">${esc(c.item)}${c.categoryLabel ? ` · ${esc(c.categoryLabel)}` : ''}</div>
          <p class="wn-call-reason">${esc(c.reason)}</p>
        </div>
      </div>
      ${ladder}
      ${meter}
      ${wnOwnBlock(c.ownHistory)}
      ${won}
      <div class="wn-stats">
        ${wnStat('eBay resale', money2(c.resalePrice), c.medianPrice ? `median ${money(c.medianPrice)}` : '')}
        ${wnStat('Middle half of sales', spread, 'where these actually land')}
        ${wnStat('Sell-through', sellThrough, c.sellThroughLabel || '')}
        ${wnStat('Sells in', velocity, velocityNote)}
        ${wnStat('Evidence', `${c.compCount} comp${c.compCount === 1 ? '' : 's'}`, `confidence ${c.confidenceScore} · ${c.confidenceLevel || '—'}`)}
      </div>
      <p class="wn-evidence wn-evidence-${esc(c.evidenceTier)}">${esc(c.evidenceNote)}</p>
      ${c.freshnessNote ? `<p class="wn-fresh">${esc(c.freshnessNote)}</p>` : ''}
      ${held}
      ${warnings}
      ${comps}
      ${priced && c.ceilingNote ? `<p class="wn-ceiling-note">${esc(c.ceilingNote)}</p>` : ''}
      <p class="wn-foot">
        ${c.soldSearchUrl ? `<a href="${esc(c.soldSearchUrl)}" target="_blank" rel="noopener noreferrer">See the sold listings on eBay ↗</a> · ` : ''}
        answered in ${Math.max(1, Math.round(c.elapsedMs || 0))} ms
      </p>`;
  }

  // ── WhatsNot: the show's buy sheet ───────────────────────────────────────────
  // Everything above stops at the hammer. This is what happened after it.
  //
  // Pressing Won it sends the token and the hammer price to /api/whatsnot/won, which
  // re-asks the SAME card at that price against the comps already held and writes the
  // row. So nothing here computes money: the row's cost, resale, profit and return are
  // the card's own figures, and the two sentences this screen speaks about a win —
  // the row's and the night's — are both written on the server, next to the
  // arithmetic they describe. See Services/LiveBuySheet.cs.
  //
  // There is no second live region for any of it. The one line above the card says
  // what was recorded and what the night now stands at, because a seller who pressed
  // Won it from the keyboard with a stream running is not looking down here.

  function wnSheetTile(label, value, note, mod) {
    return `<div class="wn-sheet-tile${mod ? ` wn-sheet-tile-${mod}` : ''}">` +
           `<div class="wn-sheet-tile-label">${esc(label)}</div>` +
           `<div class="wn-sheet-tile-value">${esc(value)}</div>` +
           `<div class="wn-sheet-tile-note">${esc(note || '')}</div></div>`;
  }

  function wnRenderSheet(sheet) {
    const head = $('wn-sheet-head');
    const totals = $('wn-sheet-totals');
    const rows = $('wn-sheet-rows');
    if (!head || !totals || !rows) return;

    const lots = sheet?.lots || [];

    // The collapsed line is the server's own sentence, painted verbatim — the same rule
    // the card's line follows. A summary assembled here out of spent and profit would be
    // a second opinion about the night's money, and it would be the one on screen while
    // the panel is shut.
    head.textContent = lots.length ? (sheet.say || '') : 'nothing won yet';

    if (!lots.length) {
      totals.innerHTML = '';
      rows.innerHTML = '<p class="wn-sheet-empty">Nothing recorded yet. When you win a lot, press ' +
        '<strong>🔨 Won it</strong> on its card and it lands here, costed against the comps it was priced on.</p>';
      return;
    }

    const roi = sheet.projectedRoiPercent == null ? '—' : `${sheet.projectedRoiPercent.toFixed(0)}%`;
    // None of the resale figure above arrives while the lots are in boxes, so how many are still
    // unlisted sits beside it as a number rather than as something to notice row by row.
    const toList = Math.max(0, (sheet.lotCount || 0) - (sheet.listedCount || 0));
    totals.innerHTML =
      wnSheetTile('Spent', money(sheet.spent),
        `${sheet.lotCount} lot${sheet.lotCount === 1 ? '' : 's'}, everything in`) +
      wnSheetTile('Resells for', money(sheet.projectedResale),
        sheet.unpricedCount > 0
          ? `${sheet.unpricedCount} lot${sheet.unpricedCount === 1 ? '' : 's'} nothing could price`
          : 'on the comps behind each lot') +
      wnSheetTile('Projected profit', money(sheet.projectedProfit),
        `${roi} return on the priced lots`, sheet.projectedProfit >= 0 ? 'good' : 'bad') +
      wnSheetTile('Still to list', `${toList}`,
        toList === 0
          ? 'every lot is a draft'
          : `${sheet.listedCount || 0} drafted — none of the resale price arrives until they're listed`,
        toList === 0 ? 'good' : '') +
      wnSheetTile('Over the ceiling', money(sheet.overpaidBy),
        sheet.overpaidCount > 0
          ? `${sheet.overpaidCount} lot${sheet.overpaidCount === 1 ? '' : 's'} won above the app's maximum`
          : 'every lot stayed inside its ceiling',
        sheet.overpaidCount > 0 ? 'bad' : 'good');

    // A real list, so a screen reader says "3 of 9" rather than reading nine unnumbered
    // paragraphs. Each row's accessible name is the server's own sentence about it.
    rows.innerHTML = `<ul class="wn-sheet-list">${lots.map(l => {
      const when = l.wonAtUtc
        ? new Date(l.wonAtUtc).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })
        : '';
      const profit = l.projectedProfit == null ? '—' : moneyExact(l.projectedProfit);
      const sub = [
        `paid ${moneyExact(l.winningBid)}${l.landedCost > l.winningBid ? `, ${moneyExact(l.landedCost)} all in` : ''}`,
        l.resalePrice == null ? 'no resale figure' : `resells ${money(l.resalePrice)}`,
        l.projectedRoiPercent == null ? '' : `${l.projectedRoiPercent.toFixed(0)}% return`,
        l.paidOverCeiling > 0 ? `${moneyExact(l.paidOverCeiling)} over the ceiling` : '',
        when,
      ].filter(Boolean).join(' · ');

      // A row is either still a box in a hallway or already a draft. The listed one offers the
      // draft rather than the button that made it, because pressing it twice is how a seller ends
      // up with two listings of one item.
      const listed = !!l.listedDraftFile;
      const action = listed
        ? `<button type="button" class="wn-sheet-draft wn-sheet-draft-done" data-open-draft="${esc(l.listedDraftFile)}"
                   title="Open the draft this lot became"
                   aria-label="Open the draft for ${esc(l.item)}${l.listedPrice == null ? '' : `, asking ${moneyExact(l.listedPrice)}`}">📄 Draft${
                     l.listedPrice == null ? '' : ` ${moneyExact(l.listedPrice)}`}</button>`
        : `<button type="button" class="wn-sheet-draft" data-list="${esc(l.id)}"
                   title="Make a listing draft from this lot"
                   aria-label="List ${esc(l.item)}${l.resalePrice == null ? '' : `, comps say ${money(l.resalePrice)}`}">🏷 List it</button>`;

      return `<li class="wn-sheet-row${l.paidOverCeiling > 0 ? ' wn-sheet-row-over' : ''}${listed ? ' wn-sheet-row-listed' : ''}"
                  aria-label="${esc(l.say || l.item)}">
        <span class="wn-sheet-row-main">
          <span class="wn-sheet-row-title">${esc(l.item)}</span>
          <span class="wn-sheet-row-sub">${esc(sub)}</span>
        </span>
        <span class="wn-sheet-row-profit${(l.projectedProfit ?? 0) < 0 ? ' wn-neg' : ''}">${esc(profit)}</span>
        ${action}
        <button type="button" class="wn-sheet-remove" data-unwin="${esc(l.id)}"
                title="Take this lot off the sheet"
                aria-label="Remove ${esc(l.item)} from tonight's buys">✕</button>
      </li>`;
    }).join('')}</ul>`;

    rows.querySelectorAll('[data-unwin]').forEach(el => {
      el.addEventListener('click', () => wnRemoveWin(el.dataset.unwin));
    });
    rows.querySelectorAll('[data-list]').forEach(el => {
      el.addEventListener('click', () => wnListLot(el.dataset.list));
    });
    rows.querySelectorAll('[data-open-draft]').forEach(el => {
      el.addEventListener('click', () => wnOpenDraft(el.dataset.openDraft));
    });
  }

  // ── WhatsNot: the won lot becomes a listing ──────────────────────────────────
  // The only thing on this screen that turns the night's projected resale into money
  // actually coming back. Everything the listing editor would ask for is already on
  // the row, so this is one press: /api/whatsnot/list writes the draft with the
  // comps-derived price on it and puts the cash already spent on the deal board.
  //
  // No pricing happens here. The ask is the same resale figure the bid was made on,
  // charm-rounded on the server next to the arithmetic — see Services/WonLotListing.cs.

  async function wnListLot(id) {
    if (!id) return;

    const btn = $('wn-sheet-rows')?.querySelector(`[data-list="${CSS.escape(id)}"]`);
    if (btn) { btn.disabled = true; btn.setAttribute('aria-busy', 'true'); }

    try {
      const { res, body } = await safePost('/api/whatsnot/list', { id });

      if (!res.ok) {
        const headline = body.error || "That didn't become a draft.";
        wnSayLine(`${headline} ${body.failure?.whatToDo || ''}`.trim());
        return;
      }

      // The sheet comes back with the row already marked, so the button that was just
      // pressed is replaced by the draft it made — there is nothing to re-derive here.
      if (body.sheet) wnRenderSheet(body.sheet);
      wnSayLine([body.say, ...(body.notes || [])].filter(Boolean).join(' '));
      $('wn-sheet')?.setAttribute('open', '');

      addActivity(`Drafted ${body.title || 'a won lot'}`,
                  body.price == null
                    ? 'No comps priced it — set a price before you publish'
                    : `Asking ${moneyExact(body.price)}, on the sold comps it was bought against`);

      // The keyboard was on a button that no longer exists. Hand it to the draft that
      // replaced it, which is also the thing to press next.
      $('wn-sheet-rows')?.querySelector(`[data-open-draft]`)?.focus();
    } catch (err) {
      wnSayLine(errorText(err, "That didn't become a draft."));
    } finally {
      if (btn && btn.isConnected) { btn.disabled = false; btn.removeAttribute('aria-busy'); }
    }
  }

  /// The draft opens in the listing editor through the SAME path the Copilot's rewrites
  /// use — tab, form, policies and focus — so a WhatsNot draft and any other local draft
  /// are the same screen with the same behaviour.
  function wnOpenDraft(filename) {
    if (!filename) return;
    openCopilotDrafts([filename], {
      title: 'Opened a won lot',
      detail: 'Add photos, set the condition, check the price, then publish',
    });
  }

  /// Read when the tab opens. A show runs for hours and the app may be restarted in the
  /// middle of one; coming back to an empty sheet would quietly understate what has
  /// already been spent, which is the one thing this panel exists to get right.
  async function wnLoadSheet() {
    try {
      const sheet = await fetch('/api/whatsnot/sheet').then(r => (r.ok ? r.json() : null));
      if (sheet) wnRenderSheet(sheet);
    } catch {
      // Offline or mid-restart. The panel keeps whatever it last showed rather than
      // announcing an empty night.
    }
  }

  async function wnRecordWin() {
    // No held comps, so the server has nothing to cost the win against and will say so.
    // Said here first because the answer is the same and this way it costs no round trip.
    if (!wnToken) {
      wnSayLine('Those comps have been let go — press Price it to read eBay again, then record the win.');
      return;
    }

    const bid = wnNumber('wn-bid');
    if (!bid || bid <= 0) {
      wnSayLine('What did it go for? Put the hammer price in the bid box, then press Won it.');
      $('wn-bid')?.focus();
      return;
    }

    const btn = $('wn-card')?.querySelector('[data-won]');
    const hadFocus = document.activeElement === btn;
    if (btn) { btn.disabled = true; btn.setAttribute('aria-busy', 'true'); }

    try {
      const { res, body } = await safePost('/api/whatsnot/won', {
        token: wnToken,
        title: wnTokenItem,
        winningBid: bid,
        shippingCost: wnNumber('wn-ship'),
        buyerFeePercent: wnNumber('wn-fee'),
        targetRoiPercent: wnNumber('wn-target'),
      });

      if (!res.ok) {
        const headline = body.error || "That didn't record.";
        const whatToDo = body.failure?.whatToDo || '';
        wnSayLine(whatToDo ? `${headline} ${whatToDo}` : headline);
        return;
      }

      wnRenderSheet(body);
      $('wn-sheet')?.setAttribute('open', '');
      // Both halves of this are the server's own sentences: what was just written down,
      // and what the night now stands at.
      const just = (body.lots || [])[0];
      wnSayLine(`${just?.say ? `${just.say} ` : ''}${body.say || ''}`.trim());
    } catch (err) {
      wnSayLine(errorText(err, "That didn't record."));
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.removeAttribute('aria-busy');
        // The card is not re-rendered by a win, so this is the same button — but focus is
        // handed back the same way Price it hands it back, because a disabled focused
        // button drops the keyboard to <body> mid-show.
        if (hadFocus) btn.focus();
      }
    }
  }

  async function wnRemoveWin(id) {
    if (!id) return;
    try {
      const { res, body } = await safePost('/api/whatsnot/sheet/remove', { id });
      if (res.ok) {
        wnRenderSheet(body);
        // The keyboard was on a button that no longer exists. Hand it somewhere real.
        $('wn-sheet-clear')?.focus();
      }
    } catch { /* the row is still on screen and still true */ }
  }

  /// The one button here that throws away something no other press can bring back, so it
  /// asks first — and says what it is about to discard, in the night's own numbers.
  async function wnClearSheet() {
    const head = $('wn-sheet-head')?.textContent || '';
    if (!confirm(`Clear tonight's buy sheet?\n\n${head}\n\nThis cannot be undone.`)) return;
    try {
      const { res, body } = await safePost('/api/whatsnot/sheet/clear', {});
      if (res.ok) wnRenderSheet(body);
    } catch { /* nothing was cleared, and the sheet on screen is still the truth */ }
  }

  // ── WhatsNot: the show's lot list ────────────────────────────────────────────
  // The card answers "should I bid on this". This answers the question before it:
  // which of the next dozen lots is worth being here for.
  //
  // Every lot is priced through the SAME /api/whatsnot/bid the typed item uses.
  // There is no bulk endpoint and deliberately no second pricing path — a lot on
  // this list and the same item typed by hand must be the same card, or the app
  // holds two opinions about one item and the seller acts on whichever it saw.
  //
  // One at a time, in the order they were listed, because the first answer in one
  // second is worth more during a live show than all twelve in twelve.
  const WN_LOT_QUEUED = 'queued';
  const WN_LOT_PRICING = 'pricing';
  const WN_LOT_PRICED = 'priced';
  const WN_LOT_FAILED = 'failed';

  let wnLots = [];         // { lot, state, card, error }
  let wnLotRun = 0;        // the run in flight; bumping it stops the previous one
  let wnLotRunning = false;
  // Whether a list has been READ, which is not the same as whether there are rows. An empty
  // rows area after Clear is empty; an empty rows area after a paste that yielded nothing is a
  // result, and has to say so or it reads as a screen that ignored the button.
  let wnLotsTried = false;

  /// Bumping the run number is how a run is stopped: the loop checks it after every
  /// answer and walks away rather than painting a row from a list nobody is on.
  function wnStopLotRun() {
    wnLotRun++;
    wnLotButton(false);
  }

  function wnLotButton(running) {
    wnLotRunning = running;
    const btn = $('wn-lots-price');
    if (btn) btn.textContent = running ? '■ Stop' : '⚡ Price the list';
    // Rows appear one at a time over ten or twenty seconds. aria-busy is what stops a screen
    // reader reading a half-built list as if it were the finished one.
    $('wn-lots-rows')?.setAttribute('aria-busy', String(!!running));
  }

  function wnLotsNote(text) {
    const el = $('wn-lots-note');
    if (el) el.textContent = text || '';
  }

  async function wnPriceLotList() {
    // The button is the stop button while a run is in flight. A seller whose lot came
    // up early should not have to wait out eleven more reads to get their hands back.
    if (wnLotRunning) {
      wnStopLotRun();
      wnLotsNote('Stopped. The lots already priced are still here.');
      return;
    }

    const text = ($('wn-lots')?.value || '').trim();
    if (!text) {
      wnLotsNote('Paste what the show says is coming — one lot per line.');
      $('wn-lots')?.focus();
      return;
    }

    wnSaveSettings();
    wnLotsTried = true;
    const run = ++wnLotRun;
    wnLotButton(true);
    wnLotsNote('Reading the list…');

    let plan;
    try {
      const { res, body } = await safePost('/api/whatsnot/lots', { text });
      if (run !== wnLotRun) return;
      if (!res.ok) {
        wnLotButton(false);
        // Headline plus what to do about it — the second half is the only part that is
        // actionable, and it was being dropped.
        wnLotsNote([body.error || "That list didn't read.", body.failure?.whatToDo].filter(Boolean).join(' '));
        return;
      }
      plan = body;
    } catch (err) {
      if (run !== wnLotRun) return;
      wnLotButton(false);
      wnLotsNote(errorText(err, "That list didn't read."));
      return;
    }

    wnLots = (plan.lots || []).map(lot => ({ lot, state: WN_LOT_QUEUED, card: null, error: '' }));
    wnLotsNote(plan.note || '');
    wnRenderLotRows();
    if (!wnLots.length) { wnLotButton(false); return; }

    for (let i = 0; i < wnLots.length; i++) {
      if (run !== wnLotRun) return;
      const row = wnLots[i];
      row.state = WN_LOT_PRICING;
      wnRenderLotRows();

      try {
        const { res, body } = await safePost('/api/whatsnot/bid', {
          title: row.lot.title,
          // The price off the line is where the bidding starts, not what the lot is
          // worth. It goes in as the current bid so the row's room-left means
          // something before the auctioneer has said anything.
          currentBid: row.lot.openingBid ?? null,
          shippingCost: wnNumber('wn-ship'),
          buyerFeePercent: wnNumber('wn-fee'),
          targetRoiPercent: wnNumber('wn-target'),
        });
        if (run !== wnLotRun) return;
        if (res.ok) { row.state = WN_LOT_PRICED; row.card = body; }
        else { row.state = WN_LOT_FAILED; row.error = body.error || body.failure?.headline || "Didn't price."; }
      } catch (err) {
        if (run !== wnLotRun) return;
        row.state = WN_LOT_FAILED;
        row.error = errorText(err, "Didn't price.");
      }
      wnRenderLotRows();
    }

    if (run !== wnLotRun) return;

    // Sorted once, at the end. Re-ordering as answers arrive would move rows out from
    // under the pointer of somebody reading them, and the order is not meaningful
    // until every lot has a card anyway.
    //
    // lotRank is computed on the server, next to the ceiling it is made of. Nothing
    // here decides which lot is worth waiting for; this compares two numbers.
    wnLots.sort((a, b) => (b.card?.lotRank ?? -1) - (a.card?.lotRank ?? -1));
    wnLotButton(false);
    wnRenderLotRows();

    const best = wnLots.find(r => r.card && r.card.call === 'bid');
    wnLotsNote(best
      ? `Sorted by what each lot is worth at its own ceiling. Best of the list: ${best.card.item}.`
      : 'Sorted by what each lot is worth at its own ceiling. Nothing on this list clears the bar.');
  }

  function wnLotStateLabel(row) {
    if (row.state === WN_LOT_QUEUED) return 'waiting';
    if (row.state === WN_LOT_PRICING) return 'checking eBay…';
    if (row.state === WN_LOT_FAILED) return row.error;
    return '';
  }

  function wnRenderLotRows() {
    const host = $('wn-lots-rows');
    if (!host) return;

    if (!wnLots.length) {
      // Two different nothings. After Clear there is nothing because the seller emptied it;
      // after a paste that yielded no lots there is nothing because the paste said nothing the
      // app could read, and a blank area would read as a button that did not fire.
      host.innerHTML = wnLotsTried
        ? '<p class="wn-lots-empty">No lots came off those lines. One lot per line — a lot number ' +
          'and an asking price are fine, they come off on the way past.</p>'
        : '';
      return;
    }

    // The rows are replaced wholesale each time an answer arrives. Keyboard focus lives on a DOM
    // node, so a seller who has tabbed to the third row loses it — silently, to <body> — every
    // time a later lot finishes pricing. Put it back on the LOT it was on, not on the position:
    // the last render of a run re-orders the list, and a position-based restore would quietly
    // move the keyboard onto a different lot at exactly the moment the seller stops watching it.
    const focusedLot = host.contains(document.activeElement) && document.activeElement?.dataset?.lot
      ? wnLots[parseInt(document.activeElement.dataset.lot, 10)]
      : null;

    host.innerHTML = wnLots.map((row, i) => {
      const c = row.card;
      if (!c) {
        return `<div class="wn-lot-row wn-lot-${esc(row.state)}">
          <div class="wn-lot-call">${row.state === WN_LOT_FAILED ? '—' : '…'}</div>
          <div class="wn-lot-main">
            <div class="wn-lot-title">${esc(row.lot.title)}</div>
            <div class="wn-lot-sub">${esc(wnLotStateLabel(row))}</div>
          </div>
        </div>`;
      }

      // Every figure below is one the server put on the card. The row is the card at a
      // glance, not a summary of it computed somewhere else.
      const ceiling = c.call === 'no_data' ? '—' : moneyExact(c.maxBid);
      const resale = c.resalePrice == null ? '—' : money(c.resalePrice);
      const st = c.sellThroughUnbounded || c.sellThroughRate == null
        ? '—' : `${c.sellThroughRate.toFixed(0)}%`;
      const room = c.call === 'no_data' || !c.bidWasKnown ? '' :
        `<span class="${c.headroom < 0 ? 'wn-neg' : ''}">${moneyExact(c.headroom)} room</span> · `;

      // A real <button>, not a div wearing role="button": Enter, Space, the focus ring and the
      // "button" a screen reader announces all come with it, and none of them is a handler that
      // can be dropped. The row's spoken name is the card's own one-line answer, so hearing the
      // row and opening it say the same thing about the same lot.
      return `<button type="button" class="wn-lot-row wn-lot-priced wn-lot-call-${esc(c.call)}"
                   data-lot="${i}" aria-label="${esc(`${c.item}. ${c.say || ''}`.trim())}"
                   title="Open this lot's card — instantly, off comps already read">
        <span class="wn-lot-call">${esc(c.call === 'no_data' ? 'NO DATA' : (c.call === 'bid' ? 'BID' : c.call.toUpperCase()))}</span>
        <span class="wn-lot-main">
          <span class="wn-lot-title">${esc(c.item)}</span>
          <span class="wn-lot-sub">${room}resells ${esc(resale)} · ${esc(st)} sell-through ·
            ${c.compCount} comp${c.compCount === 1 ? '' : 's'}</span>
        </span>
        <span class="wn-lot-max"><span>up to</span><strong>${esc(ceiling)}</strong></span>
      </button>`;
    }).join('');

    host.querySelectorAll('[data-lot]').forEach(el => {
      el.addEventListener('click', () => wnOpenLot(parseInt(el.dataset.lot, 10)));
    });

    if (focusedLot) {
      const moved = wnLots.indexOf(focusedLot);
      if (moved >= 0) host.querySelector(`[data-lot="${moved}"]`)?.focus();
    }
  }

  /// The lot reached the block. Its card is already in hand and its comps are still
  /// held server-side, so this is the whole point of the list: no eBay read, no wait.
  ///
  /// The card is painted from what the list already has, and then a re-price is
  /// scheduled — because shipping, the buyer's premium or the target may have moved
  /// since the list was priced, and that runs off the held comps in milliseconds. If
  /// the comps have been let go the re-price says so on the card, which is the same
  /// sentence any other stale token gets.
  function wnOpenLot(index) {
    const row = wnLots[index];
    if (!row || !row.card) return;

    setVal('wn-item', row.card.item);
    setVal('wn-bid', row.card.bidWasKnown ? row.card.currentBid : '');
    wnToken = row.card.token || '';
    wnTokenItem = row.card.item;
    wnRebidSeq++;
    const card = $('wn-card');
    card?.classList.remove('hidden');
    wnRenderCard(row.card);
    wnScheduleRebid();
    // The keyboard follows the answer. Without this, Enter on a row leaves focus back in the
    // list while the thing the seller asked for is somewhere above it — and the next Tab walks
    // further down the lots instead of into the card. preventScroll because the scroll below is
    // the deliberate one, and it honours reduced motion.
    card?.focus({ preventScroll: true });
    card?.scrollIntoView({ block: 'nearest', behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
  }

  function wnClearLotList() {
    wnStopLotRun();
    wnLots = [];
    wnLotsTried = false;
    setVal('wn-lots', '');
    wnLotsNote('');
    wnRenderLotRows();
    $('wn-lots')?.focus();
  }

  function bindWhatsNot() {
    on('wn-home', 'click', goHome);
    on('wn-close', 'click', closeWhatsNotSection);
    on('wn-go', 'click', () => wnLoad());
    on('wn-back', 'click', () => wnGo(-1));
    on('wn-forward', 'click', () => wnGo(1));
    // Reload re-runs the same address, including the embed check — a site's headers can
    // change, and a stream that dropped is the commonest reason to press this at all.
    on('wn-reload', 'click', () => wnLoad(wnHistory[wnHistoryAt] || $('wn-url')?.value, { push: false }));
    on('wn-feed-home', 'click', () => wnLoad(WN_HOME_URL));
    const openInBrowser = () => {
      const target = wnNormalizeUrl($('wn-url')?.value);
      if (target) window.open(target, '_blank', 'noopener,noreferrer');
    };
    on('wn-open-browser', 'click', openInBrowser);
    on('wn-blocked-open', 'click', openInBrowser);
    const box = $('wn-url');
    if (box) box.addEventListener('keydown', e => { if (e.key === 'Enter') wnLoad(); });

    // A blocked embed fires load too, so this cannot be read as "it worked" — it only
    // retires the "still loading" warning, which is now answered by the header check.
    $('wn-frame')?.addEventListener('load', () => {
      if (wnSlowTimer) { clearTimeout(wnSlowTimer); wnSlowTimer = null; }
    });

    const remembered = wnLastUrl();
    if (remembered && box) box.value = remembered;
    wnRenderRecents();

    on('wn-price', 'click', wnPriceItem);
    on('wn-bid-up', 'click', () => wnStepBid(1));
    on('wn-bid-down', 'click', () => wnStepBid(-1));

    // The lot list. Note what is NOT here: nothing re-prices the list when shipping,
    // the fee or the target change. Twelve fresh eBay reads on a keystroke is exactly
    // the cost this whole screen exists to avoid — the rows keep the numbers they were
    // priced at, and opening one re-prices that lot alone off its held comps.
    on('wn-lots-price', 'click', wnPriceLotList);
    on('wn-lots-clear', 'click', wnClearLotList);

    // The buy sheet. Won it lives inside the card, which is replaced whole every time the
    // bid moves — so the click is caught on the card itself rather than on a button that
    // stops existing two seconds after it was bound.
    $('wn-card')?.addEventListener('click', e => {
      if (e.target.closest('[data-won]')) wnRecordWin();
    });
    on('wn-sheet-clear', 'click', wnClearSheet);

    // Enter always reads eBay again. Everything cheap already happens as you type, so
    // the one keystroke left is the expensive one — and it is also the way back when
    // the held comps have been let go.
    ['wn-item', 'wn-bid', 'wn-ship', 'wn-fee', 'wn-target'].forEach(id => {
      $(id)?.addEventListener('keydown', e => { if (e.key === 'Enter') wnPriceItem(); });
    });

    // The four boxes that change the ceiling but not the comps. Typing in any of them
    // re-answers off the held sold history — no eBay, no spinner, no round trip past
    // this machine. Before anything is priced there is no token and this does nothing.
    ['wn-bid', 'wn-ship', 'wn-fee', 'wn-target'].forEach(id => {
      $(id)?.addEventListener('input', wnScheduleRebid);
    });

    // Up/down on the bid box steps by what the bidding is worth at that level rather
    // than by the input's own 1, and re-answers on the way — hands on the auction, not
    // on the keyboard.
    $('wn-bid')?.addEventListener('keydown', e => {
      if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
      e.preventDefault();
      wnStepBid(e.key === 'ArrowUp' ? 1 : -1);
    });

    // A different item is a different question, and the comps in hand are the answer
    // to the old one.
    $('wn-item')?.addEventListener('input', () => {
      if (wnToken && ($('wn-item').value || '').trim() !== wnTokenItem) wnDropToken();
    });

    // ── Escape ────────────────────────────────────────────────────────────────
    // Every other overlay here closes on Escape and this one did not, which left the screen
    // reachable by keyboard and only leaveable by mouse. But it is also the one screen you type
    // into with a stream running: closing it blanks the frame and stops a lot run mid-list, and
    // that is too much for a stray key. So the first Escape leaves the field and the second
    // closes the tab — the same two-step a text field in any dialog gets.
    document.addEventListener('keydown', e => {
      if (e.key !== 'Escape') return;
      const section = $('whatsnot-section');
      if (!section || section.classList.contains('hidden')) return;
      const active = document.activeElement;
      if (active && section.contains(active) && /^(INPUT|TEXTAREA)$/.test(active.tagName)) {
        active.blur();
        return;
      }
      closeWhatsNotSection();
    });

    wnLoadSettings();
  }

  function bindShipping() {
    on('ship-close', 'click', closeShippingSection);
    on('ship-home', 'click', goHome);
    on('ship-quote-btn', 'click', runShippingQuote);
    on('ship-scan-btn', 'click', () => { showShipPanel('leaks'); runShippingLeakScan(); });
    on('ship-tab-quote', 'click', () => showShipPanel('quote'));
    on('ship-tab-leaks', 'click', () => showShipPanel('leaks'));
    // Filtering is a pure view over the scan already in hand — it must never re-run the scan.
    on('ship-filter', 'change', renderShipLeaks);

    // Enter anywhere in the package form prices it, so the whole panel is keyboard-usable.
    ['ship-title', 'ship-price', 'ship-cost', 'ship-zip', 'ship-lb', 'ship-oz', 'ship-len', 'ship-wid', 'ship-hgt']
      .forEach(id => on(id, 'keydown', e => { if (e.key === 'Enter') runShippingQuote(); }));
  }

  function showShipPanel(which) {
    const isQuote = which === 'quote';
    $('ship-quote-panel')?.classList.toggle('hidden', !isQuote);
    $('ship-leaks-panel')?.classList.toggle('hidden', isQuote);
    $('ship-tab-quote')?.classList.toggle('active', isQuote);
    $('ship-tab-leaks')?.classList.toggle('active', !isQuote);
    $('ship-tab-quote')?.setAttribute('aria-selected', String(isQuote));
    $('ship-tab-leaks')?.setAttribute('aria-selected', String(!isQuote));
  }

  // ── One package ─────────────────────────────────────────────────────────────────────────────

  async function runShippingQuote() {
    const title = ($('ship-title')?.value || '').trim();
    const btn = $('ship-quote-btn');
    const status = $('ship-quote-status');

    // A title is the one thing that cannot be defaulted — it is what the package is inferred from.
    if (!title && !shipNum('ship-lb') && !shipNum('ship-oz')) {
      if (status) status.textContent = 'Say what the item is, or enter a weight.';
      $('ship-title')?.focus();
      return;
    }

    if (btn) { btn.disabled = true; btn.textContent = 'Pricing…'; }
    if (status) status.textContent = '';
    $('ship-quote-results').innerHTML = '<p class="opportunity-empty">Pricing every service across every zone…</p>';

    try {
      const res = await fetch('/api/shipping/quote', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          price: shipNum('ship-price'),
          unitCost: shipNum('ship-cost') || null,
          originZip: ($('ship-zip')?.value || '').trim(),
          weightLbs: shipNum('ship-lb'),
          weightOz: shipNum('ship-oz'),
          packageLengthIn: shipNum('ship-len'),
          packageWidthIn: shipNum('ship-wid'),
          packageHeightIn: shipNum('ship-hgt'),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'The quote failed.');
      renderShippingQuote(data);
    } catch (err) {
      $('ship-quote-results').innerHTML =
        `<p class="opportunity-empty">${esc(errorText(err, 'The quote failed.'))}</p>`;
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Price this package'; }
    }
  }

  // Deliberately not the file's num(): that one returns null for a blank field, and every package
  // field here means "not measured" when empty, which the server reads as a zero.
  function shipNum(id) {
    return parseFloat($(id)?.value) || 0;
  }

  function renderShippingQuote(r) {
    const el = $('ship-quote-results');
    if (!el) return;

    if (r.status === 'no_service' || !r.best) {
      el.innerHTML = `
        <div class="ship-headline ship-headline-bad">
          <div class="ship-headline-main">${esc(r.headline || 'No service will carry this package.')}</div>
          <div class="ship-headline-sub">${esc(r.note || '')}</div>
        </div>
        ${renderShipServices(r)}`;
      return;
    }

    el.innerHTML = [
      renderShipHeadline(r),
      renderShipPackage(r),
      renderShipModes(r),
      renderShipServices(r),
      renderShipTips(r),
      renderShipZoneMix(r),
    ].join('');
  }

  function renderShipHeadline(r) {
    const heavy = (r.shippingLoadPercent || 0) >= 30;
    return `
      <div class="ship-headline ${heavy ? 'ship-headline-warn' : 'ship-headline-good'}">
        <div class="ship-headline-main">${esc(r.headline || '')}</div>
        <div class="ship-headline-sub">${esc(r.note || '')}</div>
      </div>`;
  }

  // The package gets its own strip, always labelled with where it came from. An inferred 4 lb and
  // a weighed 4 lb produce identical numbers downstream and deserve very different confidence.
  function renderShipPackage(r) {
    const p = r.package || {};
    const measured = p.source === 'measured';
    const chip = measured
      ? '<span class="ship-chip ship-chip-measured">measured</span>'
      : `<span class="ship-chip ship-chip-estimated">${p.source === 'fallback' ? 'guessed' : 'estimated'}</span>`;

    return `
      <div class="ship-package">
        <div class="ship-package-head">The package ${chip}</div>
        <div class="ship-package-figures">
          <span><strong>${(p.weightLb ?? 0).toFixed(2)} lb</strong> actual</span>
          <span>${(p.lengthIn ?? 0)}&quot; &times; ${(p.widthIn ?? 0)}&quot; &times; ${(p.heightIn ?? 0)}&quot;</span>
          <span>${Math.round(p.volumeCubicIn ?? 0).toLocaleString()} cu in</span>
          ${r.best?.dimWeightApplied
            ? `<span class="ship-dim-flag">billed at ${((r.best.billableWeightOz || 0) / 16).toFixed(1)} lb — dimensional weight</span>`
            : ''}
        </div>
        <div class="ship-package-basis">${esc(p.basis || '')}</div>
      </div>`;
  }

  // The centrepiece. Sellers overwhelmingly believe charging shipping separately dodges eBay's cut
  // on it; it does not, and at a constant buyer outlay every mode nets within pennies. What the
  // table is really showing is who carries the risk that the buyer lives far away.
  function renderShipModes(r) {
    if (!r.modes?.length) {
      return `<p class="ship-modes-empty">Enter an asking price to see how free, flat and calculated shipping compare.</p>`;
    }

    const rows = r.modes.map(m => `
      <tr class="${m.recommended ? 'ship-mode-pick' : ''}">
        <td>
          <div class="ship-mode-name">${esc(m.name)}${m.recommended ? '<span class="ship-pick-tag">recommended</span>' : ''}</div>
          <div class="ship-mode-desc">${esc(m.description)}</div>
          <div class="ship-mode-verdict">${esc(m.verdict)}</div>
        </td>
        <td class="ship-num">${moneyExact(m.itemPrice)}<div class="ship-sub">${shipModeShippingLine(m)}</div></td>
        <td class="ship-num">${moneyExact(m.netExpected)}</td>
        <td class="ship-num">
          ${moneyExact(m.zoneRisk)}
          <div class="ship-sub">${moneyExact(m.netNear)} near / ${moneyExact(m.netFar)} far</div>
        </td>
        <td class="ship-num ${m.underwaterBuyerPercent > 0 ? 'ship-num-bad' : 'ship-num-ok'}">
          ${m.underwaterBuyerPercent > 0 ? `${m.underwaterBuyerPercent}%` : 'none'}
        </td>
      </tr>`).join('');

    return `
      <div class="ship-block">
        <h3 class="ship-block-title">How to charge for it</h3>
        <p class="ship-block-sub">
          All four are priced at the <strong>same buyer total</strong>, which is why the take-home column barely
          moves: eBay charges its final value fee on the shipping line too, so charging separately saves you
          nothing. What changes is the last two columns — what you stand to lose if the buyer is far away.
        </p>
        <div class="ship-table-wrap">
          <table class="ship-table">
            <thead>
              <tr>
                <th>Way of charging</th>
                <th class="ship-num">Listed at</th>
                <th class="ship-num">You keep (typical)</th>
                <th class="ship-num">Your zone risk</th>
                <th class="ship-num">Buyers you lose on</th>
              </tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
      </div>`;
  }

  // Calculated shipping carries no single shipping figure — that is the entire point of it — so it
  // gets the range the buyer will actually see. Reporting its zero as "free shipping" would say the
  // opposite of what the mode does.
  function shipModeShippingLine(m) {
    if (m.mode === 'calculated') {
      const near = m.buyerOutlayNear - m.itemPrice;
      const far  = m.buyerOutlayFar - m.itemPrice;
      return `+ ${moneyExact(near)}–${moneyExact(far)} by zone`;
    }
    return m.buyerPaidShipping > 0 ? `+ ${moneyExact(m.buyerPaidShipping)} shipping` : 'free shipping';
  }

  function renderShipServices(r) {
    const services = r.services || [];
    if (!services.length) return '';

    const rows = services.map(s => {
      if (!s.eligible) {
        return `
          <tr class="ship-service-out">
            <td>
              <div class="ship-mode-name">${esc(s.name)}</div>
              <div class="ship-mode-desc">${esc(s.carrier)}</div>
            </td>
            <td colspan="4" class="ship-out-reason">${esc(s.ineligibleReason)}</td>
          </tr>`;
      }
      return `
        <tr class="${s.recommended ? 'ship-mode-pick' : ''}">
          <td>
            <div class="ship-mode-name">${esc(s.name)}${s.recommended ? '<span class="ship-pick-tag">cheapest</span>' : ''}</div>
            <div class="ship-mode-desc">${esc(s.note)}</div>
            ${s.surchargeAmount > 0 ? `<div class="ship-mode-verdict">${esc(s.surchargeReason)}</div>` : ''}
          </td>
          <td class="ship-num"><strong>${moneyExact(s.expectedCost)}</strong>${s.extraVsBest > 0 ? `<div class="ship-sub">+${moneyExact(s.extraVsBest)}</div>` : ''}</td>
          <td class="ship-num">${s.isFlatRate ? 'same everywhere' : `${moneyExact(s.nearestZoneCost)} – ${moneyExact(s.farthestZoneCost)}`}</td>
          <td class="ship-num">${((s.billableWeightOz || 0) / 16).toFixed(2)} lb${s.dimWeightApplied ? '<div class="ship-sub">dimensional</div>' : ''}</td>
          <td class="ship-num">${s.transitDaysMin}–${s.transitDaysMax} days</td>
        </tr>`;
    }).join('');

    return `
      <div class="ship-block">
        <h3 class="ship-block-title">Every service, priced</h3>
        <p class="ship-block-sub">Services that can't carry this package are listed with the reason, because
          "two inches from a flat-rate box" is worth knowing.</p>
        <div class="ship-table-wrap">
          <table class="ship-table">
            <thead>
              <tr>
                <th>Service</th>
                <th class="ship-num">Average label</th>
                <th class="ship-num">Near – far</th>
                <th class="ship-num">Billable</th>
                <th class="ship-num">Transit</th>
              </tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
      </div>`;
  }

  function renderShipTips(r) {
    if (!r.tips?.length) return '';
    return `
      <div class="ship-block">
        <h3 class="ship-block-title">Money in the box, not in the price</h3>
        <div class="ship-tips">
          ${r.tips.map(t => `
            <div class="ship-tip">
              <div class="ship-tip-save">${moneyExact(t.savingPerSale)}<span>a sale</span></div>
              <div class="ship-tip-body">
                <div class="ship-tip-head">${esc(t.headline)}</div>
                <div class="ship-tip-detail">${esc(t.detail)}</div>
              </div>
            </div>`).join('')}
        </div>
      </div>`;
  }

  // Shown because the expected cost is otherwise a number the seller has to take on faith. This is
  // the distribution it was averaged over, and it makes the coastal-seller penalty visible.
  function renderShipZoneMix(r) {
    if (!r.zoneMix?.length) return '';
    const best = r.best;
    return `
      <details class="ship-zones">
        <summary>Where your buyers are${r.originZip ? `, shipping from ${esc(r.originZip)}` : ''}</summary>
        <table class="ship-table ship-zone-table">
          <thead><tr><th>Zone</th><th class="ship-num">Share of US buyers</th><th class="ship-num">Label</th><th>Reaches</th></tr></thead>
          <tbody>
            ${r.zoneMix.map(z => `
              <tr>
                <td>Zone ${z.zone}</td>
                <td class="ship-num">${z.sharePercent}%</td>
                <td class="ship-num">${best?.zoneCosts?.[z.zone] != null ? moneyExact(best.zoneCosts[z.zone]) : '—'}</td>
                <td class="ship-zone-regions">${esc(z.regions || '—')}</td>
              </tr>`).join('')}
          </tbody>
        </table>
        <p class="ship-zones-note">
          Zones are worked out from your ZIP against a population-weighted map of where US buyers live, so the
          "average label" above is what a typical month actually costs — not one zone's price.
        </p>
      </details>`;
  }

  // ── Everything already live ─────────────────────────────────────────────────────────────────

  async function runShippingLeakScan() {
    const btn = $('ship-scan-btn');
    const maxItems = $('ship-max-items')?.value || '250';

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    $('ship-status').textContent = '';
    $('ship-results').innerHTML =
      '<p class="opportunity-empty">Pricing a real label for every live listing — this is all local, so it is quick.</p>';

    try {
      const res = await fetch(`/api/shipping/leaks?maxItems=${encodeURIComponent(maxItems)}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'The scan failed.');
      shipScan = data;
      renderShipScan();
    } catch (err) {
      shipScan = null;
      $('ship-summary')?.classList.add('hidden');
      $('ship-warning')?.classList.add('hidden');
      $('ship-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '📦 Find My Shipping Leaks'; }
    }
  }

  function renderShipScan() {
    if (!shipScan) return;
    const warn = $('ship-warning');

    if (shipScan.status === 'ebay_unavailable') {
      $('ship-summary')?.classList.add('hidden');
      warn?.classList.add('hidden');
      $('ship-results').innerHTML =
        '<p class="opportunity-empty">Couldn\'t read your eBay listings. Reconnect eBay in Settings, then scan again. '
        + 'The one-item calculator works without eBay.</p>';
      return;
    }

    if (shipScan.dataWarning) {
      warn.textContent = shipScan.dataWarning;
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    const s = shipScan.summary || {};
    $('ship-status').textContent =
      `${s.listingsScanned || 0} of ${shipScan.activeListings || 0} active listings priced · `
      + `${s.measuredPackages || 0} weighed, ${s.estimatedPackages || 0} estimated`;

    renderShipSummary(s);
    renderShipLeaks();
  }

  // Leads with the money, not the listing count. "23 leaks" is a statistic; "$118 a sale is
  // walking out of the door" is a reason to keep reading.
  function renderShipSummary(s) {
    const el = $('ship-summary');
    if (!el) return;

    const tiles = [
      { label: 'Leaking, per sale', value: moneyExact(s.totalPerSaleImpact),
        sub: `${s.leaksFound || 0} listing${s.leaksFound === 1 ? '' : 's'} out of ${s.listingsScanned || 0}`,
        tone: s.totalPerSaleImpact > 0 ? 'warn' : 'good' },
      { label: 'Across the stock you hold', value: moneyExact(s.totalAtRisk),
        sub: 'per-sale gap times the units listed',
        tone: s.totalAtRisk > 0 ? 'warn' : '' },
      { label: 'Costing you the most', value: String(s.criticalCount || 0),
        sub: s.criticalCount ? 'worth fixing before you list anything else' : 'nothing critical',
        tone: s.criticalCount > 0 ? 'warn' : 'good' },
      { label: 'Average real label', value: moneyExact(s.averageLabelCost),
        sub: `your profit numbers assume ${moneyExact(shipScan.assumedLabelCost)}`,
        tone: s.averageLabelCost > shipScan.assumedLabelCost ? 'warn' : 'good' },
      { label: 'Packages weighed', value: `${s.measuredPackages || 0} / ${s.listingsScanned || 0}`,
        sub: s.estimatedPackages ? `${s.estimatedPackages} estimated from the title` : 'all measured',
        tone: s.estimatedPackages > (s.measuredPackages || 0) ? 'warn' : 'good' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  const SHIP_KIND = {
    underpriced_label: { label: '💸 Costs more than assumed', cls: 'inv-v-dead' },
    wrong_service:     { label: '📦 A cheaper box works',      cls: 'inv-v-over' },
    dim_weight:        { label: '💨 Paying to ship air',        cls: 'inv-v-over' },
    oversize:          { label: '🚚 Oversize',                  cls: 'inv-v-dead' },
    zone_risk:         { label: '🗺️ Depends on the buyer',      cls: 'inv-v-stale' },
    shipping_heavy:    { label: '⚖️ Shipping eats the price',   cls: 'inv-v-stale' },
  };

  function shipFilterMatches(leak, filter) {
    switch (filter) {
      case 'critical': return leak.severity === 'critical';
      case 'all':      return true;
      default:         return leak.kind === filter;
    }
  }

  function renderShipLeaks() {
    if (!shipScan) return;
    const filter = $('ship-filter')?.value || 'all';
    const leaks = (shipScan.leaks || []).filter(l => shipFilterMatches(l, filter));
    const el = $('ship-results');
    if (!el) return;

    if (!leaks.length) {
      el.innerHTML = shipScan.leaks?.length
        ? '<p class="opportunity-empty">Nothing matches that filter. Try "Everything found".</p>'
        : '<p class="opportunity-empty">No shipping leaks found — every live listing\'s real label is inside '
          + 'what your profit numbers already assume. That is the good outcome.</p>';
      return;
    }

    el.innerHTML = leaks.map(l => {
      const kind = SHIP_KIND[l.kind] || { label: l.kind, cls: '' };
      return `
        <div class="ship-leak">
          <div class="ship-leak-main">
            <div class="ship-leak-top">
              <span class="inv-verdict ${kind.cls}">${kind.label}</span>
              ${l.packageEstimated ? '<span class="ship-chip ship-chip-estimated">package estimated</span>' : '<span class="ship-chip ship-chip-measured">weighed</span>'}
            </div>
            <div class="ship-leak-title">
              ${l.listingUrl ? `<a href="${esc(l.listingUrl)}" target="_blank" rel="noopener">${esc(l.title)}</a>` : esc(l.title)}
            </div>
            <div class="ship-leak-head">${esc(l.headline)}</div>
            <div class="ship-leak-detail">${esc(l.detail)}</div>
            <div class="ship-leak-fix">→ ${esc(l.fix)}</div>
          </div>
          <div class="ship-leak-money">
            <div class="ship-leak-impact">${moneyExact(l.perSaleImpact)}</div>
            <div class="ship-leak-impact-label">a sale</div>
            ${l.quantity > 1 ? `<div class="ship-leak-atrisk">${moneyExact(l.atRisk)} across ${l.quantity}</div>` : ''}
            <div class="ship-leak-price">listed at ${moneyExact(l.price)}</div>
          </div>
        </div>`;
    }).join('');
  }

  // ══ Deal Radar ═══════════════════════════════════════════════════════════
  // The only feature in this app that keeps working when its screen is closed. The server does the
  // scanning; everything here is (a) managing the saved searches, (b) rendering what was found, and
  // (c) getting a find onto the desktop when the tray couldn't do it.
  //
  // Two notification paths, deliberately not one. When the app is running with its tray icon, the
  // server raises a Windows balloon and marks the alert `notified` — that reaches the seller with no
  // browser open at all. When it can't (a headless Windows service install), this page's own
  // Notification API is the channel, and it fires only for alerts the tray did NOT already announce.
  // Double-notifying is exactly how a good alert becomes an annoying one.

  let radarStatus = null;
  let radarAlerts = [];
  let radarEditingId = null;       // null while creating
  let radarCategories = [];
  let radarSourceList = [];
  let radarOpenTimer = null;       // fast poll, only while the screen is open
  let radarBackgroundTimer = null; // slow poll, always — the badge and the notifications
  const RADAR_LAST_SEEN_KEY = 'ing-radar-last-alert-id';
  const RADAR_OPEN_POLL_MS = 15000;
  const RADAR_BACKGROUND_POLL_MS = 60000;

  function showRadarSection() {
    hideOverlaySections();
    $('radar-section')?.classList.remove('hidden');
    setActiveNavItem('radar');
    markWorkspaceTabOpen('radar');
    refreshRadar();
  }

  function closeRadarSection() {
    closeWorkspacePage('radar');
  }

  function bindDealRadar() {
    on('rad-close', 'click', closeRadarSection);
    on('rad-home', 'click', goHome);
    on('rad-add', 'click', () => openRadarForm(null));
    on('rad-form-cancel', 'click', closeRadarForm);
    on('rad-save', 'click', saveRadarWatch);
    on('rad-delete', 'click', deleteRadarWatch);
    on('rad-settings-toggle', 'click', () =>
      toggleDisclosure('rad-settings', 'rad-settings-toggle', 'Alert settings', 'Hide settings'));
    on('rad-desktop-permit', 'click', requestRadarNotificationPermission);
    on('rad-read-all', 'click', markAllRadarAlertsRead);
    on('rad-clear', 'click', clearRadarFeed);

    // The master switch and the four alert settings all post the same object, so there is one
    // server-side shape to reason about rather than five partial ones.
    ['rad-enabled', 'rad-quiet-enabled', 'rad-desktop-on', 'rad-quiet-from', 'rad-quiet-to']
      .forEach(id => on(id, 'change', saveRadarSettings));

    fillRadarHourSelects();
    $('rad-watches')?.addEventListener('click', onRadarWatchClick);
    $('rad-alerts')?.addEventListener('click', onRadarAlertClick);

    // Runs whether or not the screen is open: the badge and the notification are the whole point,
    // and both have to work while the seller is looking at the editor.
    startRadarBackgroundPolling();
  }

  // ── Reading the server ───────────────────────────────────────────────────

  async function refreshRadar() {
    await Promise.all([loadRadarStatus(), loadRadarAlerts()]);
    if (!radarCategories.length) loadRadarPickers();
  }

  async function loadRadarStatus() {
    const { data } = await localFetchJson('/api/radar/status', 15000);
    if (!data) return null;
    radarStatus = data;
    renderRadarStatus();
    renderRadarWatches();
    // The feed's empty state is chosen by whether any watch exists, which is knowledge that arrives
    // here rather than with the alerts. refreshRadar loads both at once, so on a first paint the
    // alert render can win the race, read no watches, and leave "Create your first watch" standing
    // above a watch that is already running. Re-rendering once the watch list is known settles it.
    renderRadarAlerts();
    return data;
  }

  async function loadRadarAlerts() {
    const { data } = await localFetchJson('/api/radar/alerts?limit=60', 15000);
    if (!Array.isArray(data)) return;
    radarAlerts = data;
    renderRadarAlerts();
  }

  // The category list and the source list, for the watch editor. Loaded once — they don't change
  // while the app is running, and the editor opens often.
  async function loadRadarPickers() {
    const [cats, sources] = await Promise.all([
      localFetchJson('/api/local/categories', 15000),
      localFetchJson('/api/local/sources', 15000),
    ]);
    if (Array.isArray(cats.data)) radarCategories = cats.data;
    if (Array.isArray(sources.data)) radarSourceList = sources.data;
  }

  // ── The master strip ─────────────────────────────────────────────────────

  function renderRadarStatus() {
    if (!radarStatus) return;
    const s = radarStatus.settings || {};
    const watches = radarStatus.watches || [];
    const live = watches.filter(w => w.enabled).length;

    const enabledBox = $('rad-enabled');
    if (enabledBox) enabledBox.checked = !!s.enabled;
    const quietBox = $('rad-quiet-enabled');
    if (quietBox) quietBox.checked = !!s.quietHoursEnabled;
    const desktopBox = $('rad-desktop-on');
    if (desktopBox) desktopBox.checked = !!s.desktopNotifications;
    setValue('rad-quiet-from', String(s.quietFromHour ?? 23));
    setValue('rad-quiet-to', String(s.quietToHour ?? 7));

    // Says what is happening now, in this order of usefulness: a scan in flight, then the reason
    // nothing is, then when the next one lands. "On" with no watches is the trap this avoids.
    let state;
    if (!s.enabled) {
      state = watches.length
        ? 'Off — your watches are saved but nothing is scanning.'
        : 'Off — add a watch, then switch this on.';
    } else if (radarStatus.scanning) {
      const which = watches.find(w => w.id === radarStatus.scanningWatchId);
      state = `Scanning ${which ? `“${which.name}”` : 'now'}…`;
    } else if (!live) {
      state = 'On, but every watch is paused.';
    } else {
      const next = radarStatus.nextScanUtc ? radarAgo(radarStatus.nextScanUtc, true) : 'shortly';
      state = `On · ${live} watch${live === 1 ? '' : 'es'} · next sweep ${next}`;
      if (radarStatus.inQuietHours) state += ' · quiet hours — finds are collected silently';
    }
    setText('rad-state', state);

    renderRadarChannelNote();
    updateRadarBadge();

    const hasAlerts = (radarStatus.totalAlertCount || 0) > 0;
    $('rad-feed-head')?.classList.toggle('hidden', !hasAlerts);
    setText('rad-feed-title', hasAlerts
      ? `${radarStatus.totalAlertCount} deal${radarStatus.totalAlertCount === 1 ? '' : 's'} found` +
        (radarStatus.unreadAlertCount ? ` · ${radarStatus.unreadAlertCount} new` : '')
      : 'Deals');
  }

  // Where a notification can actually come from, said out loud. The server knows whether a tray icon
  // is attached; the browser knows whether it has permission. Neither alone can answer the seller's
  // real question, which is "will I actually hear about this".
  function renderRadarChannelNote() {
    const el = $('rad-channel');
    const permitBtn = $('rad-desktop-permit');
    if (!el) return;

    const supported = 'Notification' in window;
    const granted = supported && Notification.permission === 'granted';
    const denied = supported && Notification.permission === 'denied';
    const tray = radarStatus?.desktopChannel === 'tray';

    permitBtn?.classList.toggle('hidden', !supported || granted || denied || tray);

    let html = '';
    if (tray) {
      html = '✓ <strong>Windows notifications are on.</strong> Finds appear from the tray icon even ' +
             'with this tab closed — you only need the app running.';
      el.className = 'rad-channel rad-channel--ok';
    } else if (granted) {
      html = '✓ <strong>Browser notifications are on.</strong> This app is running without its tray ' +
             'icon, so <strong>leave this tab open</strong> to be told about a find as it happens. ' +
             'Everything is waiting in the feed either way.';
      el.className = 'rad-channel rad-channel--ok';
    } else if (denied) {
      html = 'Notifications are <strong>blocked for this site</strong> in your browser, and this app ' +
             'is running without its tray icon. The radar still scans and the feed still fills — ' +
             'you just won\'t be interrupted. Re-allow notifications in the padlock menu to change that.';
      el.className = 'rad-channel rad-channel--warn';
    } else if (supported) {
      html = 'The radar will keep finding deals, but nothing will pop until you allow notifications.';
      el.className = 'rad-channel rad-channel--warn';
    } else {
      html = 'This browser can\'t show notifications. The radar still scans and the feed still fills.';
      el.className = 'rad-channel rad-channel--warn';
    }
    el.innerHTML = html;
    el.classList.remove('hidden');
  }

  function fillRadarHourSelects() {
    const hours = Array.from({ length: 24 }, (_, h) => {
      const label = h === 0 ? '12am' : h === 12 ? '12pm' : h < 12 ? `${h}am` : `${h - 12}pm`;
      return `<option value="${h}">${label}</option>`;
    }).join('');
    const from = $('rad-quiet-from');
    const to = $('rad-quiet-to');
    if (from) from.innerHTML = hours;
    if (to) to.innerHTML = hours;
  }

  async function saveRadarSettings() {
    const body = {
      enabled: !!$('rad-enabled')?.checked,
      quietHoursEnabled: !!$('rad-quiet-enabled')?.checked,
      desktopNotifications: !!$('rad-desktop-on')?.checked,
      quietFromHour: parseInt($('rad-quiet-from')?.value ?? '23', 10),
      quietToHour: parseInt($('rad-quiet-to')?.value ?? '7', 10),
    };

    const { body: res } = await safePost('/api/radar/settings', body);
    if (!res?.ok) { toastErr(res?.error || 'The setting couldn\'t be saved.', { title: 'Deal Radar' }); return; }

    radarStatus = res.status || radarStatus;
    renderRadarStatus();
    renderRadarWatches();

    // Asking for permission at the moment the seller turns the feature on, rather than on page load
    // — a permission prompt with no context attached is the one people click Block on.
    if (body.enabled && body.desktopNotifications) requestRadarNotificationPermission({ quiet: true });
  }

  // ── The watch cards ──────────────────────────────────────────────────────

  function renderRadarWatches() {
    const el = $('rad-watches');
    if (!el) return;

    const watches = radarStatus?.watches || [];
    if (!watches.length) {
      el.innerHTML = '';
      return;
    }

    el.innerHTML = watches.map(radarWatchCard).join('');
  }

  function radarWatchCard(w) {
    const paused = !w.enabled;
    const scanning = radarStatus?.scanning && radarStatus.scanningWatchId === w.id;
    const pill = scanning ? { cls: 'scan', text: 'Scanning…' }
      : paused ? { cls: 'paused', text: 'Paused' }
      : w.lastStatus === 'error' ? { cls: 'error', text: 'Couldn\'t scan' }
      : w.lastStatus === 'ok' ? { cls: 'ok', text: `${w.lastMatchCount} found` }
      : w.lastStatus === 'no_matches' ? { cls: 'quiet', text: 'Nothing yet' }
      : { cls: 'quiet', text: 'Not run yet' };

    const terms = [
      w.query ? `“${esc(w.query)}”` : '',
      w.categoryLabel || radarCategoryLabel(w.categoryId),
      w.zipCode ? `${w.radiusMiles} mi of ${esc(w.zipCode)}` : '',
      esc(radarSourceLabels(w.sources)),
    ].filter(Boolean).join(' · ');

    const bar = [
      `at least ${money(w.minNetProfit)} profit`,
      w.minRoiPercent > 0 ? `${Math.round(w.minRoiPercent)}% ROI` : '',
      w.maxAsk > 0 ? `asks under ${money(w.maxAsk)}` : '',
      w.maxDistanceMiles > 0 ? `within ${Math.round(w.maxDistanceMiles)} mi` : '',
      w.requireConfidentEvidence ? 'solid comps only' : 'thin comps allowed',
    ].filter(Boolean).join(' · ');

    // The last run's own sentence. It is the difference between a seller lowering a threshold and a
    // seller assuming the feature is broken, so it is never summarised away to "0".
    const last = w.lastRunUtc
      ? `Checked ${radarAgo(w.lastRunUtc)} — ${esc(w.lastNote || 'nothing to report.')}`
      : paused ? 'Paused before its first scan.'
      : 'Waiting for its first scan.';

    const next = !paused && radarStatus?.settings?.enabled && w.nextRunUtc
      ? ` Next ${radarAgo(w.nextRunUtc, true)}.`
      : '';

    const found = w.totalAlertCount > 0
      ? `<p class="rad-watch-found">${w.totalAlertCount} deal${w.totalAlertCount === 1 ? '' : 's'} found so far, worth ${money(w.totalProfitFound)} in projected profit.</p>`
      : '';

    return `
      <article class="rad-watch${paused ? ' is-paused' : ''}" data-id="${w.id}">
        <div class="rad-watch-head">
          <h4>${esc(w.name)}</h4>
          <span class="rad-pill rad-pill--${pill.cls}">${esc(pill.text)}</span>
        </div>
        <p class="rad-watch-terms">${terms}</p>
        <p class="rad-watch-bar">Alerts on ${esc(bar)} · every ${radarInterval(w.intervalMinutes)}</p>
        <p class="rad-watch-last">${last}${next}</p>
        ${found}
        <div class="rad-watch-actions">
          <button class="btn btn-secondary small" type="button" data-act="run" ${scanning ? 'disabled' : ''}>Scan now</button>
          <button class="btn btn-ghost small" type="button" data-act="toggle">${paused ? 'Resume' : 'Pause'}</button>
          <button class="btn btn-ghost small" type="button" data-act="edit">Edit</button>
        </div>
      </article>`;
  }

  async function onRadarWatchClick(e) {
    const btn = e.target.closest?.('button[data-act]');
    const card = e.target.closest?.('.rad-watch');
    if (!btn || !card) return;

    const id = Number(card.dataset.id);
    const watch = (radarStatus?.watches || []).find(w => w.id === id);
    if (!watch) return;

    if (btn.dataset.act === 'edit') { openRadarForm(watch); return; }

    if (btn.dataset.act === 'toggle') {
      const { body } = await safePost('/api/radar/watches', { id, enabled: !watch.enabled });
      if (!body?.ok) { toastErr(body?.error || 'That didn\'t save.', { title: 'Deal Radar' }); return; }
      radarStatus = body.status || radarStatus;
      renderRadarStatus();
      renderRadarWatches();
      return;
    }

    if (btn.dataset.act === 'run') {
      const original = btn.textContent;
      btn.disabled = true;
      btn.textContent = 'Scanning…';
      try {
        // Deliberately un-timed on this side: this is the full pricing pipeline over live
        // classifieds, the same minutes-long wait the local board asks for, and the server already
        // bounds it (DealRadarService.RunTimeout).
        const { body: data } = await safePost(`/api/radar/watches/${id}/run`, {});
        if (!data) throw new Error('The scan didn\'t answer.');
        radarStatus = data.status || radarStatus;
        await loadRadarAlerts();
        renderRadarStatus();
        renderRadarWatches();

        const found = (data.alerts || []).length;
        if (found) toastOk(`${found} new deal${found === 1 ? '' : 's'} cleared your bar.`, { title: watch.name });
        else toast(data.note || 'Nothing new this time.', { kind: 'info', title: watch.name });
      } catch (err) {
        toastErr(errorText(err, 'Unknown error.'), { title: 'The scan couldn\'t be run' });
      } finally {
        btn.disabled = false;
        btn.textContent = original;
      }
    }
  }

  // ── The watch editor ─────────────────────────────────────────────────────

  function openRadarForm(watch) {
    // The pickers are loaded once and cached. On the very first open they may not be back yet, so
    // the form is filled now with what there is and re-filled when they arrive — rather than making
    // the seller wait on two requests before the box they came to type in appears.
    if (!radarCategories.length) loadRadarPickers().then(() => fillRadarForm(watch));

    radarEditingId = watch?.id ?? null;
    fillRadarForm(watch);

    setText('rad-form-title', watch ? 'Edit watch' : 'New watch');
    $('rad-delete')?.classList.toggle('hidden', !watch);
    $('rad-form-error')?.classList.add('hidden');
    $('rad-form')?.classList.remove('hidden');
    $('rad-form')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    $('rad-query')?.focus();
  }

  function fillRadarForm(watch) {
    renderRadarCategorySelect(watch?.categoryId);
    renderRadarSourceChecks(watch?.sources);

    setVal('rad-name', watch?.name ?? '');
    setVal('rad-query', watch?.query ?? '');
    setVal('rad-zip', watch?.zipCode ?? radarDefaultZip());
    setVal('rad-radius', String(watch?.radiusMiles ?? 40));
    setVal('rad-min-profit', String(watch?.minNetProfit ?? 75));
    setVal('rad-min-roi', String(watch?.minRoiPercent ?? 40));
    setVal('rad-max-ask', watch?.maxAsk > 0 ? String(watch.maxAsk) : '');
    setVal('rad-max-distance', watch?.maxDistanceMiles > 0 ? String(watch.maxDistanceMiles) : '');
    setVal('rad-interval', String(watch?.intervalMinutes ?? 180));

    const confident = $('rad-confident');
    if (confident) confident.checked = watch ? !!watch.requireConfidentEvidence : true;
    const notify = $('rad-notify');
    if (notify) notify.checked = watch ? !!watch.notifyDesktop : true;
  }

  // The ZIP the seller already told the app about, so a second watch isn't a blank form. Three
  // places have it, in descending order of how recently they were right: the local board's search
  // box, its saved value, and a watch that is already running.
  function radarDefaultZip() {
    const known = $('fb-zip')?.value || localStorage.getItem('fbZip') || '';
    if (known.trim()) return known.trim();
    return ((radarStatus?.watches || []).find(w => w.zipCode)?.zipCode || '').trim();
  }

  function renderRadarCategorySelect(selected) {
    const sel = $('rad-category');
    if (!sel) return;
    if (!radarCategories.length) {
      sel.innerHTML = '<option value="anything">Anything</option>';
      return;
    }
    const groups = [...new Set(radarCategories.map(c => c.group))];
    sel.innerHTML = groups.map(group => {
      const inGroup = radarCategories.filter(c => c.group === group);
      const options = inGroup.map(c => `<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('');
      return inGroup.length === 1 && group === 'Anything' ? options : `<optgroup label="${esc(group)}">${options}</optgroup>`;
    }).join('');
    sel.value = selected || 'anything';
  }

  // Craigslist is ticked by default and Facebook is not, on purpose: a watch runs unattended, and a
  // login-gated site should only be read on a schedule because the seller said so.
  function renderRadarSourceChecks(csv) {
    const el = $('rad-sources');
    if (!el) return;

    const chosen = (csv || '').split(',').map(s => s.trim()).filter(Boolean);
    const list = radarSourceList.length ? radarSourceList : [{ id: 'craigslist', label: 'Craigslist', available: true, note: '' }];

    // Every registered source is offered, nationwide ones included. This used to filter on
    // `locationBased !== false`, which quietly hid eBay and the retail deal feeds — the watch form
    // has a zip and a radius, so anything that ignores them looked like it didn't belong. It does:
    // the scan pipeline is written against ILocalSupplySource and never asks which site a row came
    // from, LocalSupplySources.Resolve already accepts any id, and DealRadarMatcher's driving-
    // distance rule only applies to rows that actually carry a distance. The one real difference is
    // that the zip and radius mean nothing to them, so say that on the row rather than removing it.
    el.innerHTML = list.map(s => {
      const on = chosen.length ? chosen.includes(s.id) : s.id === 'craigslist';
      const note = !s.available ? (s.note || 'not connected')
                 : s.locationBased === false ? 'nationwide — zip and radius don\'t apply'
                 : '';
      return `<label class="rad-check rad-source">
                <input type="checkbox" value="${esc(s.id)}" ${on ? 'checked' : ''} />
                ${esc(s.label)}${note ? ` <span class="rad-source-note">${esc(note)}</span>` : ''}
              </label>`;
    }).join('');
  }

  function radarSelectedSources() {
    return [...($('rad-sources')?.querySelectorAll('input:checked') || [])].map(i => i.value).join(',');
  }

  function closeRadarForm() {
    radarEditingId = null;
    $('rad-form')?.classList.add('hidden');
  }

  async function saveRadarWatch() {
    const err = $('rad-form-error');
    err?.classList.add('hidden');

    const payload = {
      id: radarEditingId ?? undefined,
      name: ($('rad-name')?.value ?? '').trim(),
      query: ($('rad-query')?.value ?? '').trim(),
      categoryId: $('rad-category')?.value ?? 'anything',
      zipCode: ($('rad-zip')?.value ?? '').trim(),
      radiusMiles: parseInt($('rad-radius')?.value ?? '40', 10),
      sources: radarSelectedSources(),
      minNetProfit: parseFloat($('rad-min-profit')?.value || '0') || 0,
      minRoiPercent: parseFloat($('rad-min-roi')?.value || '0') || 0,
      maxAsk: parseFloat($('rad-max-ask')?.value || '0') || 0,
      maxDistanceMiles: parseFloat($('rad-max-distance')?.value || '0') || 0,
      intervalMinutes: parseInt($('rad-interval')?.value ?? '180', 10),
      requireConfidentEvidence: !!$('rad-confident')?.checked,
      notifyDesktop: !!$('rad-notify')?.checked,
      enabled: true,
    };

    const btn = $('rad-save');
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }

    try {
      const { body } = await safePost('/api/radar/watches', payload);
      if (!body?.ok) {
        // The server's refusals are sentences, not codes — shown where the seller is looking rather
        // than as a toast they have to remember while fixing the field.
        if (err) { err.textContent = body?.error || 'That watch couldn\'t be saved.'; err.classList.remove('hidden'); }
        return;
      }

      radarStatus = body.status || radarStatus;
      closeRadarForm();
      renderRadarStatus();
      renderRadarWatches();

      if (!radarStatus?.settings?.enabled) {
        toast('Watch saved. Switch on “Watch in the background” and it starts running.',
          { kind: 'info', title: 'One more step' });
      } else {
        toastOk(`“${body.watch.name}” is running. First sweep within a few minutes.`, { title: 'Watch saved' });
      }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Save watch'; }
    }
  }

  async function deleteRadarWatch() {
    if (!radarEditingId) return;
    const watch = (radarStatus?.watches || []).find(w => w.id === radarEditingId);
    if (!confirm(`Delete “${watch?.name ?? 'this watch'}”? Its alerts go with it.`)) return;

    const res = await fetch(`/api/radar/watches/${radarEditingId}`, { method: 'DELETE' });
    const body = await res.json().catch(() => null);
    radarStatus = body?.status || radarStatus;
    closeRadarForm();
    await loadRadarAlerts();
    renderRadarStatus();
    renderRadarWatches();
  }

  // ── The feed ─────────────────────────────────────────────────────────────

  function renderRadarAlerts() {
    const el = $('rad-alerts');
    if (!el) return;

    if (!radarAlerts.length) {
      // Two different empty states, because they mean different things. With no watches saved the
      // screen's job is to explain the feature; with watches running and nothing found, the job is
      // to say that finding nothing IS the radar working. The first is the markup already in
      // index.html, so it survives a page load with no server call.
      if ((radarStatus?.watches || []).length) el.innerHTML = radarEmptyFeed();
      return;
    }

    el.innerHTML = radarAlerts.map(radarAlertCard).join('');
  }

  function radarEmptyFeed() {
    return `
      <div class="state">
        <div class="state-icon"><svg aria-hidden="true"><use href="#i-radar"/></svg></div>
        <div class="state-title">Nothing has cleared your bar yet.</div>
        <p class="state-body">That is the radar working, not the radar failing — it only interrupts you for deals that beat the thresholds you set. Each watch above says what its last sweep actually saw.</p>
      </div>`;
  }

  function radarAlertCard(a) {
    const figures = [
      ['Ask', money(a.localAsk)],
      ['Resells for', a.resalePrice ? money(a.resalePrice) : '—'],
      ['Net profit', a.netProfit != null ? money(a.netProfit) : '—'],
      ['ROI', a.roiPercent != null ? `${Math.round(a.roiPercent)}%` : '—'],
      ['Pay no more than', a.maxBuyPrice != null ? money(a.maxBuyPrice) : '—'],
      ['Cash back in', a.daysToCash != null ? `${a.daysToCash} days` : '—'],
    ].map(([label, value]) =>
      `<div class="rad-figure"><span class="rad-figure-label">${label}</span><span class="rad-figure-value">${esc(value)}</span></div>`).join('');

    const meta = [
      esc(a.watchName),
      esc(a.sourceLabel || a.source),
      a.location ? esc(a.location) : '',
      `found ${radarAgo(a.foundUtc)}`,
      a.compCount ? `${a.compCount} sold comps` : '',
    ].filter(Boolean).join(' · ');

    const evidence = a.evidenceNote
      ? `<p class="rad-alert-evidence">${esc(a.evidenceNote)}</p>` : '';

    const image = a.imageUrl
      ? `<img class="rad-alert-img" src="${esc(a.imageUrl)}" alt="" loading="lazy" />`
      : '<div class="rad-alert-img rad-alert-img--none" aria-hidden="true"></div>';

    return `
      <article class="rad-alert${a.read ? '' : ' is-new'}" data-id="${a.id}">
        ${image}
        <div class="rad-alert-body">
          <div class="rad-alert-top">
            <p class="rad-alert-headline">${esc(a.headline || a.title)}</p>
            ${a.read ? '' : '<span class="rad-pill rad-pill--new">NEW</span>'}
          </div>
          <p class="rad-alert-meta">${meta}</p>
          <div class="rad-alert-figures">${figures}</div>
          ${evidence}
          <div class="rad-alert-actions">
            ${a.url
              ? `<a class="btn btn-primary small" href="${esc(a.url)}" target="_blank" rel="noopener" data-act="open">See the listing ↗</a>`
              : '<span class="rad-alert-nolink">The listing didn\'t publish a link.</span>'}
            <button class="btn btn-secondary small" type="button" data-act="track">Track this deal</button>
            <button class="btn btn-ghost small" type="button" data-act="dismiss">Dismiss</button>
          </div>
        </div>
      </article>`;
  }

  async function onRadarAlertClick(e) {
    const trigger = e.target.closest?.('[data-act]');
    const card = e.target.closest?.('.rad-alert');
    if (!card) return;

    const id = Number(card.dataset.id);
    const alert = radarAlerts.find(a => a.id === id);
    if (!alert) return;

    // Opening the listing is reading it. Marking it read there rather than only on Dismiss is what
    // keeps the badge honest — a seller who clicked through has been told.
    if (!trigger || trigger.dataset.act === 'open') {
      if (!alert.read) markRadarAlertRead(alert, card);
      return;
    }

    if (trigger.dataset.act === 'dismiss') {
      await fetch(`/api/radar/alerts/${id}/dismiss`, { method: 'POST' });
      radarAlerts = radarAlerts.filter(a => a.id !== id);
      renderRadarAlerts();
      loadRadarStatus();
      return;
    }

    if (trigger.dataset.act === 'track') trackRadarAlert(alert, trigger);
  }

  async function markRadarAlertRead(alert, card) {
    alert.read = true;
    card?.classList.remove('is-new');
    card?.querySelector('.rad-pill--new')?.remove();
    await fetch(`/api/radar/alerts/${alert.id}/read`, { method: 'POST' });
    loadRadarStatus();
  }

  // Straight into the Deal Pipeline, with the forecast frozen exactly as the alert quoted it — so
  // the flip can later be graded against the number that justified driving out for it.
  async function trackRadarAlert(alert, btn) {
    const original = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Tracking…';

    try {
      const res = await fetch('/api/deals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: alert.title,
          stage: 'sourced',
          source: alert.source,
          sourceLabel: alert.sourceLabel,
          sourceUrl: alert.url,
          sourceItemId: alert.itemKey,
          askPrice: alert.localAsk,
          maxBuyPrice: alert.maxBuyPrice,
          projectedSalePrice: alert.resalePrice,
          projectedNetProfit: alert.netProfit,
          projectedRoiPercent: alert.roiPercent,
          projectedDaysToCash: alert.daysToCash,
          projectedBasis: [
            alert.compCount ? `${alert.compCount} sold comps` : '',
            alert.evidenceTier ? `${alert.evidenceTier} evidence` : '',
            'found by Deal Radar',
          ].filter(Boolean).join(' · '),
          note: alert.location ? `Local pickup: ${alert.location}` : '',
        }),
      });
      if (!res.ok) throw new Error(await res.text());

      btn.textContent = '✓ Tracked';
      toastOk('Tracked at Sourced. The Deal Pipeline will grade it against this forecast.',
        { title: 'In the pipeline', action: { label: 'Open pipeline', onClick: () => navigateTo('pipeline') } });
      if (!alert.read) markRadarAlertRead(alert, btn.closest('.rad-alert'));
    } catch (e) {
      btn.disabled = false;
      btn.textContent = original;
      toastErr(errorText(e, 'Unknown error.'), { title: 'Couldn\'t track that deal' });
    }
  }

  async function markAllRadarAlertsRead() {
    await safePost('/api/radar/alerts/read-all', {});
    radarAlerts.forEach(a => { a.read = true; });
    renderRadarAlerts();
    loadRadarStatus();
  }

  async function clearRadarFeed() {
    if (!confirm('Clear the feed? Nothing already found will be shown to you again — the radar remembers every listing it has alerted on.')) return;
    await safePost('/api/radar/alerts/clear', {});
    radarAlerts = [];
    renderRadarAlerts();
    loadRadarStatus();
  }

  // ── The badge, the polling and the notifications ─────────────────────────

  function startRadarWatchPolling() {
    stopRadarWatchPolling();
    radarOpenTimer = setInterval(() => {
      if ($('radar-section')?.classList.contains('hidden')) { stopRadarWatchPolling(); return; }
      loadRadarStatus();
      loadRadarAlerts();
    }, RADAR_OPEN_POLL_MS);
  }

  function stopRadarWatchPolling() {
    if (radarOpenTimer) { clearInterval(radarOpenTimer); radarOpenTimer = null; }
  }

  // The one timer that runs for the whole session. Cheap: a status read is a few SQLite counts, and
  // it only pulls the alert list when the unread count actually moved.
  function startRadarBackgroundPolling() {
    if (radarBackgroundTimer) return;
    const tick = async () => {
      const before = radarStatus?.unreadAlertCount ?? 0;
      const status = await loadRadarStatus().catch(() => null);
      if (!status) return;
      if ((status.unreadAlertCount || 0) > before) await announceNewRadarAlerts();
    };
    radarBackgroundTimer = setInterval(tick, RADAR_BACKGROUND_POLL_MS);
    tick();
  }

  function updateRadarBadge() {
    const badge = $('nav-radar-badge');
    if (!badge) return;
    const count = radarStatus?.unreadAlertCount || 0;
    badge.dataset.count = count > 99 ? '99+' : String(count);
    badge.classList.toggle('hidden', count === 0);
  }

  // Fires only for finds the tray did NOT already announce (a.notified), so the seller is never told
  // the same thing twice by two channels.
  async function announceNewRadarAlerts() {
    const { data } = await localFetchJson('/api/radar/alerts?limit=20', 15000);
    if (!Array.isArray(data)) return;
    radarAlerts = data;
    renderRadarAlerts();

    const lastSeen = Number(localStorage.getItem(RADAR_LAST_SEEN_KEY) || 0);
    const fresh = data.filter(a => a.id > lastSeen && !a.read && !a.dismissed);
    if (!fresh.length) return;
    localStorage.setItem(RADAR_LAST_SEEN_KEY, String(Math.max(...data.map(a => a.id))));

    // In-app first: it works with no permission at all, and it is the only one that can offer a
    // button that goes straight to the deal.
    const best = fresh[0];
    toastOk(best.headline, {
      title: fresh.length > 1 ? `Deal Radar · ${fresh.length} new deals` : 'Deal Radar',
      action: { label: 'Open Deal Radar', onClick: () => navigateTo('radar') },
    });

    if (!('Notification' in window) || Notification.permission !== 'granted') return;
    fresh.filter(a => !a.notified).slice(0, 2).forEach(a => {
      try {
        const note = new Notification(a.watchName || 'Deal Radar', {
          body: a.headline,
          icon: 'favicon.svg',
          // Tagged per alert so the same find can never stack up as two notifications.
          tag: `ing-radar-${a.id}`,
        });
        note.onclick = () => { window.focus(); navigateTo('radar'); note.close(); };
      } catch { /* a browser that refuses to construct one is not worth breaking the poll over */ }
    });
  }

  async function requestRadarNotificationPermission(opts = {}) {
    if (!('Notification' in window)) {
      if (!opts.quiet) toast('This browser can\'t show desktop notifications. The feed still fills.',
        { kind: 'warning', title: 'Not supported here' });
      return;
    }
    if (Notification.permission === 'granted') { renderRadarChannelNote(); return; }
    if (Notification.permission === 'denied') {
      if (!opts.quiet) toast('Notifications are blocked for this site. Re-allow them in the padlock menu next to the address bar.',
        { kind: 'warning', title: 'Blocked by the browser' });
      return;
    }

    const result = await Notification.requestPermission().catch(() => 'default');
    renderRadarChannelNote();
    if (result === 'granted' && !opts.quiet) {
      toastOk('You\'ll be told the moment a deal clears your bar.', { title: 'Desktop alerts on' });
    }
  }

  // ── Small formatters ─────────────────────────────────────────────────────

  function radarCategoryLabel(id) {
    if (!id || id === 'anything') return '';
    return radarCategories.find(c => c.id === id)?.label || '';
  }

  function radarSourceLabels(csv) {
    const ids = (csv || 'craigslist').split(',').map(s => s.trim()).filter(Boolean);
    return ids.map(id => radarSourceList.find(s => s.id === id)?.label || id).join(' + ');
  }

  function radarInterval(minutes) {
    if (!minutes || minutes < 60) return `${minutes || 0} min`;
    if (minutes === 1440) return 'day';
    const hours = minutes / 60;
    return `${Number.isInteger(hours) ? hours : hours.toFixed(1)} hours`;
  }

  // "12 min ago" / "in 2 hours". One helper for both directions, because a card shows the last run
  // and the next one side by side and two different phrasings would read as two different clocks.
  function radarAgo(iso, future = false) {
    const then = new Date(iso).getTime();
    if (!then || Number.isNaN(then)) return future ? 'soon' : 'recently';

    const diff = Math.abs(Date.now() - then);
    const mins = Math.round(diff / 60000);
    const text = mins < 1 ? 'less than a minute'
      : mins < 60 ? `${mins} min`
      : mins < 1440 ? `${Math.round(mins / 60)} hour${Math.round(mins / 60) === 1 ? '' : 's'}`
      : `${Math.round(mins / 1440)} day${Math.round(mins / 1440) === 1 ? '' : 's'}`;

    if (!future) return `${text} ago`;
    return Date.now() >= then ? 'any moment' : `in ${text}`;
  }

  function showTrendsSection() {
    hideOverlaySections();
    $('trends-section')?.classList.remove('hidden');
    setActiveNavItem('trends');
    markWorkspaceTabOpen('trends');
  }

  function closeTrendsSection() {
    closeWorkspacePage('trends');
  }

  function bindTrendRadar() {
    on('tr-scan-btn', 'click', () => runTrendScan({ nextSeed: false }));
    on('tr-scan-again', 'click', () => runTrendScan({ nextSeed: true }));
    // The dashboard's market-pulse panel. Its scan button is the same scan, started from the
    // front page: open the board first so the seller can watch it fill rather than waiting a
    // minute on a dashboard that looks like nothing happened.
    on('dash-pulse-open', 'click', () => navigateTo('trends'));
    on('dash-pulse-scan', 'click', () => { navigateTo('trends'); runTrendScan({ nextSeed: false }); });
    on('tr-close', 'click', closeTrendsSection);
    on('tr-home', 'click', goHome);
    on('tr-pulse-table-toggle', 'click', () => toggleDisclosure('tr-pulse-table', 'tr-pulse-table-toggle', 'Show as table', 'Hide table'));
    // Direction is a pure view over the scan in hand when we already have everything; it only
    // re-runs when the previous scan was narrowed server-side and the seller now wants it all.
    on('tr-direction', 'change', () => {
      if (!trendScan) return;
      // A scan that already fetched everything can be re-filtered in the browser. Widening one that
      // was narrowed server-side has to go back — but on the SAME seed, so the seller gets the same
      // categories with more of them shown, not a different scan wearing the same question.
      if (trendScan.direction === 'all') renderTrendRows();
      else runTrendScan({ seed: trendScan.seed });
    });
  }

  function setTrendStatus(text) {
    const el = $('tr-status');
    if (el) el.textContent = text || '';
  }

  async function runTrendScan({ nextSeed = false, seed = null } = {}) {
    const btn = $('tr-scan-btn');
    const again = $('tr-scan-again');
    const windowDays = $('tr-window')?.value || '45';
    const niches = $('tr-niches')?.value || '5';
    const direction = $('tr-direction')?.value || 'rising';
    // "Scan different categories" is the seed advancing — the same rotation Roll the Dice uses, so
    // a second scan digs categories the first one never touched instead of repeating itself.
    const useSeed = nextSeed ? trendScan?.nextSeed : seed;
    const seedArg = useSeed != null ? `&seed=${useSeed}` : '';

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    if (again) again.disabled = true;
    setDashPulseScanning(true);
    setTrendStatus('Reading sold history across several categories…');
    $('tr-results').innerHTML = '<p class="opportunity-empty">Sweeping sold comps, splitting each product\'s sales into two windows, then pricing only the ones that moved. This takes a moment.</p>';

    try {
      const res = await fetch(`/api/trends/radar?window=${windowDays}&niches=${niches}&direction=${direction}${seedArg}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      trendScan = data;
      renderTrendScan();
    } catch (err) {
      trendScan = null;
      $('tr-summary')?.classList.add('hidden');
      $('tr-pulse')?.classList.add('hidden');
      $('tr-corpus')?.classList.add('hidden');
      $('tr-warning')?.classList.add('hidden');
      $('tr-more-bar')?.classList.add('hidden');
      $('tr-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setTrendStatus('');
      renderDashPulse();
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '📈 Find What\'s Climbing'; }
      if (again) again.disabled = false;
      setDashPulseScanning(false);
    }
  }

  // The front-page panel while its own button is what started the scan. The seller has been sent
  // to the board by then, so this is only what they come back to if they navigate home mid-scan.
  function setDashPulseScanning(on) {
    const btn = $('dash-pulse-scan');
    if (!btn) return;
    if (on) {
      btn.dataset.restLabel = btn.dataset.restLabel || btn.textContent;
      btn.disabled = true;
      btn.textContent = 'Scanning the market…';
    } else {
      btn.disabled = false;
      btn.textContent = btn.dataset.restLabel || 'Scan the market';
    }
  }

  function renderTrendScan() {
    if (trendScan.status === 'error') {
      $('tr-summary')?.classList.add('hidden');
      $('tr-pulse')?.classList.add('hidden');
      $('tr-corpus')?.classList.add('hidden');
      $('tr-more-bar')?.classList.add('hidden');
      $('tr-results').innerHTML = `<p class="opportunity-empty">${esc(trendScan.error || 'The scan failed.')}</p>`;
      setTrendStatus('');
      renderDashPulse();
      return;
    }

    renderTrendCorpus();

    const warn = $('tr-warning');
    if (trendScan.dataWarning && trendScan.status === 'ok') {
      warn.textContent = trendScan.dataWarning;
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    // A refused scan has no rows and no summary — the banner above IS the answer, and padding it
    // out with zeroed tiles would read as "we looked and found nothing" rather than "we couldn't look".
    if (trendScan.status !== 'ok') {
      $('tr-summary')?.classList.add('hidden');
      $('tr-pulse')?.classList.add('hidden');
      $('tr-results').innerHTML = '<p class="opportunity-empty">Nothing can be read as a trend until the sold-comps data above is sorted out.</p>';
      renderDashPulse();
      renderTrendMoreBar();
      setTrendStatus('');
      return;
    }

    renderTrendSummary();
    renderTrendPulse();
    renderDashPulse();
    renderTrendRows();
    renderTrendMoreBar();

    const w = trendScan.windowDays;
    setTrendStatus(
      `${trendScan.compsScanned.toLocaleString()} sold comps · ${trendScan.productsMeasured} product${trendScan.productsMeasured === 1 ? '' : 's'} measured · ` +
      `${trendScan.productsRising} climbing · last ${w} days vs the ${w} before`);
  }

  // The scan reporting on its own data. This is the banner that stops the feature lying: if the
  // comps database stopped being updated, every product looks like demand collapsed, and that
  // reads as market news unless it is said plainly and first.
  function renderTrendCorpus() {
    const el = $('tr-corpus');
    const c = trendScan.corpus || {};
    if (!el) return;

    if (!c.isReadable) {
      el.innerHTML = `<strong>This scan can't be read as a trend.</strong> ${esc(trendScan.dataWarning || c.note || '')}`;
      el.classList.remove('hidden');
      return;
    }

    // Only worth the space when the database's own volume moved enough to distort every product's
    // velocity — otherwise it's noise about noise.
    if (c.note) {
      el.innerHTML = `<strong>Baseline:</strong> ${esc(c.note)}`;
      el.classList.remove('hidden');
      return;
    }

    el.classList.add('hidden');
  }

  function renderTrendSummary() {
    const el = $('tr-summary');
    if (!el) return;

    const c = trendScan.corpus || {};
    const rows = trendScan.rows || [];
    const buys = rows.filter(r => r.verdict === 'buy_now');
    const topClimb = rows.reduce((best, r) => {
      const pct = Number(r.trend?.priceChangePercent);
      return Number.isFinite(pct) && pct > best ? pct : best;
    }, 0);

    const tiles = [
      { label: 'Worth buying now', value: String(trendScan.buyNowCount || 0),
        sub: buys.length ? `Climbing, and the money already works at today's price` : 'Nothing cleared both bars this scan',
        tone: trendScan.buyNowCount > 0 ? 'good' : '' },
      { label: 'What the climb is worth', value: money(trendScan.totalTrendHeadroom),
        sub: 'Extra per unit across those buys, if the move holds one more window',
        tone: trendScan.totalTrendHeadroom > 0 ? 'good' : '' },
      { label: 'Biggest move', value: topClimb > 0 ? `+${topClimb.toFixed(1)}%` : '—',
        sub: topClimb > 0 ? `Median sold price, last ${trendScan.windowDays} days vs the ${trendScan.windowDays} before` : 'No product on this board is climbing',
        tone: topClimb >= 15 ? 'good' : '' },
      { label: 'Products climbing', value: `${trendScan.productsRising} of ${trendScan.productsMeasured}`,
        sub: 'Measured across the categories this scan swept' },
      { label: 'Evidence behind it', value: `${(c.datedComps || 0).toLocaleString()} dated sales`,
        sub: `${c.datedCoveragePercent || 0}% of the comps scanned carry a sale date`,
        tone: (c.datedCoveragePercent || 0) < 60 ? 'warn' : '' },
      { label: 'Freshest sale', value: c.newestCompAgeDays == null ? '—' : `${c.newestCompAgeDays}d ago`,
        sub: 'How current the comps database is — everything above rests on this',
        tone: (c.newestCompAgeDays ?? 99) > 14 ? 'warn' : '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  // ── Market pulse ──────────────────────────────────────────────────────────
  // One column per measured product, drawn from a shared zero line: above it the price rose,
  // below it the price fell. Position carries the sign before colour does, which is what makes
  // this readable to a reader who cannot tell the green from the red.
  //
  // The tiles above report "3 climbing of 21". That sentence is true of a board where everything
  // crept up 2% and one thing fell off a cliff, and of a board where three things doubled and the
  // rest did nothing — and a sourcer should behave completely differently in those two markets.
  // This is the shape those numbers were hiding.
  const TREND_PULSE_MAX_COLUMNS = 60;

  function renderTrendPulse() {
    const panel = $('tr-pulse');
    const host = $('tr-pulse-chart');
    const sub = $('tr-pulse-sub');
    if (!panel || !host) return;

    const measured = (trendScan.rows || [])
      .map(r => ({ row: r, pct: Number(r.trend?.priceChangePercent) }))
      .filter(m => Number.isFinite(m.pct))
      .sort((a, b) => b.pct - a.pct);

    // Two columns cannot show a distribution; the tiles above already say what happened.
    if (measured.length < 3) {
      panel.classList.add('hidden');
      return;
    }

    // On a very wide sweep the columns would be sub-pixel hairlines, which is a texture rather than
    // a chart. The biggest movers in each direction are what the shape is about, so the tail is
    // dropped and said out loud rather than drawn at a width nobody can hover.
    const dropped = Math.max(0, measured.length - TREND_PULSE_MAX_COLUMNS);
    const shown = dropped
      ? [...measured].sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct))
          .slice(0, TREND_PULSE_MAX_COLUMNS).sort((a, b) => b.pct - a.pct)
      : measured;

    const W = 940, H = 210;
    const padL = 54, padR = 18, padT = 22, padB = 30;
    const plotW = W - padL - padR, plotH = H - padT - padB;

    const values = shown.map(m => m.pct);
    const maxV = Math.max(0, ...values);
    const minV = Math.min(0, ...values);
    const span = (maxV - minV) || 1;
    const y = v => padT + plotH - ((v - minV) / span) * plotH;
    const zeroY = y(0);

    // niceTicks rounds outward, so it can hand back a tick above the tallest column — which would
    // be drawn off the top of the plot and clipped to half a label. Only ticks the chart actually
    // spans are drawn; the axis is allowed to stop below the peak.
    const ticks = niceTicks(minV, maxV, 4).filter(t => t >= minV && t <= maxV);
    const grid = ticks.map(t => `
      <line x1="${padL}" y1="${y(t).toFixed(1)}" x2="${W - padR}" y2="${y(t).toFixed(1)}" class="viz-grid" />
      <text x="${padL - 10}" y="${(y(t) + 4).toFixed(1)}" class="viz-axis viz-axis-y">${t > 0 ? '+' : ''}${Number.isInteger(t) ? t : t.toFixed(1)}%</text>`).join('');

    const band = plotW / shown.length;
    const barW = Math.max(2, Math.min(18, band - 2));   // capped; the leftover band stays as air

    const best = values[0], worst = values[values.length - 1];
    const columns = shown.map((m, i) => {
      const v = m.pct;
      const r = m.row;
      const x = padL + i * band + (band - barW) / 2;
      const top = v >= 0 ? y(v) : zeroY;
      const h = Math.max(v === 0 ? 0 : 1.5, Math.abs(y(v) - zeroY));
      const rad = Math.min(3, barW / 2, h);
      // 3px rounded data-end, square where it meets the zero line — rounding both ends turns a
      // small move into a pill that reads as a shape rather than as a quantity.
      const path = v >= 0
        ? `M${x} ${top + h} L${x} ${top + rad} Q${x} ${top} ${x + rad} ${top} L${x + barW - rad} ${top} Q${x + barW} ${top} ${x + barW} ${top + rad} L${x + barW} ${top + h} Z`
        : `M${x} ${top} L${x} ${top + h - rad} Q${x} ${top + h} ${x + rad} ${top + h} L${x + barW - rad} ${top + h} Q${x + barW} ${top + h} ${x + barW} ${top + h - rad} L${x + barW} ${top} Z`;

      const sig = TREND_SIGNALS[r.trend?.signal] || TREND_SIGNALS.unreadable;
      const tip = `${r.product}\n${v > 0 ? '+' : ''}${v.toFixed(1)}% median sold price\n`
        + `${r.trend?.prior?.soldCount ?? 0} → ${r.trend?.recent?.soldCount ?? 0} sold · ${sig.label}`;

      // Only the two ends are labelled. A percentage over every column is chaos and goes unread;
      // the axis carries the middle and the table carries all of it.
      const label = (v === best && v > 0) || (v === worst && v < 0)
        ? `<text x="${(x + barW / 2).toFixed(1)}" y="${(v >= 0 ? y(v) - 7 : y(v) + 14).toFixed(1)}" class="viz-value-label">${v > 0 ? '+' : ''}${v.toFixed(0)}%</text>`
        : '';

      // The tooltip hangs off the group, not off the hit rect. The column paints on top of its own
      // hit rect, so a reader hovering the actual bar — the obvious thing to do — would otherwise
      // land on an element with no tooltip on it and get nothing.
      return `<g class="viz-band" tabindex="0" role="img"
          aria-label="${esc(tip.replaceAll('\n', '. '))}" data-viz-tip="${esc(tip)}">
        <rect class="viz-hit" x="${(padL + i * band).toFixed(1)}" y="${padT}" width="${band.toFixed(1)}" height="${plotH}" />
        <path d="${path}" class="${v >= 0 ? 'tr-pulse-up' : 'tr-pulse-down'}" />${label}
      </g>`;
    }).join('');

    host.innerHTML = `<svg viewBox="0 0 ${W} ${H}" class="viz-svg" role="img"
        aria-label="Change in median sold price for each of ${shown.length} measured products. Use Show as table for the values.">
      ${grid}
      ${columns}
      <line x1="${padL}" y1="${zeroY.toFixed(1)}" x2="${W - padR}" y2="${zeroY.toFixed(1)}" class="viz-zero" />
      <text x="${padL}" y="${H - 10}" class="viz-axis">Each column is one product · sorted by how far it moved</text>
    </svg>`;

    const rising = values.filter(v => v > 0).length;
    if (sub) {
      const w = trendScan.windowDays;
      sub.textContent =
        `${rising} of ${shown.length} products sold for more than they did a window ago. `
        + `Median sold price, last ${w} days against the ${w} before`
        + (dropped ? `, showing the ${TREND_PULSE_MAX_COLUMNS} biggest movers of ${measured.length} measured.` : '.');
    }

    const table = $('tr-pulse-table');
    if (table) table.innerHTML = `
      <table class="viz-table">
        <thead><tr><th>Product</th><th>Category</th><th class="num">Price change</th><th class="num">Sold before</th><th class="num">Sold now</th><th>Signal</th></tr></thead>
        <tbody>${measured.map(({ row: r, pct }) => `<tr>
          <td><strong>${esc(r.product)}</strong></td>
          <td>${esc(r.nicheLabel)}</td>
          <td class="num"><strong>${pct > 0 ? '+' : ''}${pct.toFixed(1)}%</strong></td>
          <td class="num">${r.trend?.prior?.soldCount ?? 0}</td>
          <td class="num">${r.trend?.recent?.soldCount ?? 0}</td>
          <td>${esc((TREND_SIGNALS[r.trend?.signal] || TREND_SIGNALS.unreadable).label)}</td>
        </tr>`).join('')}</tbody>
      </table>`;

    panel.classList.remove('hidden');
  }

  // ── Market pulse, on the dashboard ────────────────────────────────────────
  // The same measurement as the band above, at the size the front page can carry: the headline
  // sentence, the share climbing, the three biggest movers, and the distribution those numbers
  // came out of. It is only ever drawn from a scan the seller has already run — the dashboard
  // never fetches the radar, because a sweep is a minute of eBay and comp lookups and nobody
  // asked for it by opening the app.
  const DASH_PULSE_MAX_COLUMNS = 44;

  function renderDashPulse() {
    const rest = $('dash-pulse-rest');
    const live = $('dash-pulse-live');
    if (!live) return;

    const measured = (trendScan?.rows || [])
      .map(r => ({ row: r, pct: Number(r.trend?.priceChangePercent) }))
      .filter(m => Number.isFinite(m.pct))
      .sort((a, b) => b.pct - a.pct);

    // Same floor as the full-size band: two columns are not a distribution, and a headline
    // fraction off two products is not a market.
    if (measured.length < 3) {
      live.classList.add('hidden');
      live.innerHTML = '';
      rest?.classList.remove('hidden');
      return;
    }

    const dropped = Math.max(0, measured.length - DASH_PULSE_MAX_COLUMNS);
    const shown = dropped
      ? [...measured].sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct))
          .slice(0, DASH_PULSE_MAX_COLUMNS).sort((a, b) => b.pct - a.pct)
      : measured;

    const rising = measured.filter(m => m.pct > 0).length;
    const w = trendScan.windowDays;
    const share = (rising / measured.length) * 100;

    // The three furthest from flat in either direction — a mover is a mover whichever way it
    // went, and a board where the biggest news is a 40% collapse should say so on the front page.
    const movers = [...measured].sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct)).slice(0, 3);
    const moverRows = movers.map(({ row: r, pct }) => `
      <div class="dash-pulse-mover">
        <span class="dash-pulse-mover-name">${esc(r.product)}</span>
        <span class="dash-pulse-mover-pct ${pct >= 0 ? 'up' : 'down'}">${pct > 0 ? '+' : ''}${pct.toFixed(1)}%</span>
      </div>`).join('');

    live.innerHTML = `
      <div class="dash-pulse-side">
        <p class="dash-pulse-figure">${rising}<span class="dash-pulse-figure-of">/${measured.length}</span></p>
        <p class="dash-pulse-label">products sold for more than they did a window ago — median sold
          price over the last ${w} days against the ${w} before.</p>
        ${vizMeter(share, { tone: 'solo', valueText: `${Math.round(share)}%`, label: `${rising} of ${measured.length} products climbing` })}
        <div class="dash-pulse-movers">${moverRows}</div>
      </div>
      <div class="dash-pulse-chart">${dashPulseChart(shown, dropped, measured.length)}</div>`;

    live.classList.remove('hidden');
    rest?.classList.add('hidden');
  }

  // One column per product from a shared zero line, as on Rising Now: position carries the sign
  // before colour does. No y-axis here — the front page is answering "which way and how spread
  // out", and the panel it links to carries every value.
  function dashPulseChart(shown, dropped, measuredCount) {
    const W = 720, H = 168, padT = 16, padB = 22;
    const plotH = H - padT - padB;

    const values = shown.map(m => m.pct);
    const maxV = Math.max(0, ...values);
    const minV = Math.min(0, ...values);
    const span = (maxV - minV) || 1;
    const y = v => padT + plotH - ((v - minV) / span) * plotH;
    const zeroY = y(0);

    const band = W / shown.length;
    const barW = Math.max(2, Math.min(16, band - 3));

    const columns = shown.map((m, i) => {
      const v = m.pct, r = m.row;
      const x = i * band + (band - barW) / 2;
      const top = v >= 0 ? y(v) : zeroY;
      const h = Math.max(v === 0 ? 0 : 1.5, Math.abs(y(v) - zeroY));
      const rad = Math.min(3, barW / 2, h);
      const path = v >= 0
        ? `M${x} ${top + h} L${x} ${top + rad} Q${x} ${top} ${x + rad} ${top} L${x + barW - rad} ${top} Q${x + barW} ${top} ${x + barW} ${top + rad} L${x + barW} ${top + h} Z`
        : `M${x} ${top} L${x} ${top + h - rad} Q${x} ${top + h} ${x + rad} ${top + h} L${x + barW - rad} ${top + h} Q${x + barW} ${top + h} ${x + barW} ${top + h - rad} L${x + barW} ${top} Z`;

      const sig = TREND_SIGNALS[r.trend?.signal] || TREND_SIGNALS.unreadable;
      const tip = `${r.product}\n${v > 0 ? '+' : ''}${v.toFixed(1)}% median sold price\n${sig.label}`;
      return `<g class="viz-band" tabindex="0" role="img"
          aria-label="${esc(tip.replaceAll('\n', '. '))}" data-viz-tip="${esc(tip)}">
        <rect class="viz-hit" x="${(i * band).toFixed(1)}" y="${padT}" width="${band.toFixed(1)}" height="${plotH}" />
        <path d="${path}" class="${v >= 0 ? 'tr-pulse-up' : 'tr-pulse-down'}" />
      </g>`;
    }).join('');

    const foot = dropped
      ? `the ${shown.length} biggest movers of ${measuredCount} measured`
      : `each column is one of ${shown.length} products measured`;

    return `<svg viewBox="0 0 ${W} ${H}" class="viz-svg" role="img"
        aria-label="Change in median sold price per product, sorted by how far it moved. Open Rising Now for the values.">
      ${columns}
      <line x1="0" y1="${zeroY.toFixed(1)}" x2="${W}" y2="${zeroY.toFixed(1)}" class="viz-zero" />
      <text x="0" y="${H - 6}" class="viz-axis">${esc(foot)} · sorted by how far it moved</text>
    </svg>`;
  }

  function renderTrendMoreBar() {
    const bar = $('tr-more-bar');
    const note = $('tr-more-note');
    if (!bar || !note) return;

    const names = (trendScan.niches || []).map(n => n.label).join(', ');
    note.textContent = names
      ? `Swept ${names}. ${trendScan.rollsToCoverEverything} scan${trendScan.rollsToCoverEverything === 1 ? '' : 's'} covers all ${trendScan.nichesInUniverse} categories.`
      : 'Scan again to sweep different categories.';
    bar.classList.remove('hidden');
  }

  const TREND_VERDICTS = {
    buy_now:      { label: '🔥 Buy now',      cls: 'tr-v-buy' },
    get_in_early: { label: '🌱 Get in early', cls: 'tr-v-early' },
    watch:        { label: '👀 Watch',        cls: 'tr-v-watch' },
    thin:         { label: '⚠️ Thin data',    cls: 'tr-v-thin' },
    pass:         { label: '✕ Pass',          cls: 'tr-v-pass' },
  };

  const TREND_SIGNALS = {
    rising_demand:   { label: 'Rising demand',   cls: 'tr-s-up' },
    price_climbing:  { label: 'Price climbing',  cls: 'tr-s-up' },
    demand_building: { label: 'Volume building', cls: 'tr-s-early' },
    supply_squeeze:  { label: 'Supply squeeze',  cls: 'tr-s-squeeze' },
    steady:          { label: 'Flat',            cls: 'tr-s-flat' },
    cooling:         { label: 'Cooling',         cls: 'tr-s-down' },
    unreadable:      { label: 'Not readable',    cls: 'tr-s-flat' },
  };

  function renderTrendRows() {
    if (!trendScan) return;
    const showAll = ($('tr-direction')?.value || 'rising') === 'all';
    const rows = (trendScan.rows || []).filter(r => showAll || r.trend?.isRising);
    const el = $('tr-results');

    if (rows.length === 0) {
      el.innerHTML = `<p class="opportunity-empty">${esc(
        trendScan.dataWarning ||
        'Nothing in these categories is climbing right now. That is a real answer — scan again to sweep different ones.')}</p>`;
      return;
    }

    el.innerHTML = `
      <table class="inv-table tr-table">
        <thead>
          <tr>
            <th>Product</th>
            <th>Trend</th>
            <th class="num">Sold price</th>
            <th class="num">Sales</th>
            <th class="num">Max to pay today</th>
            <th class="num">Buy under</th>
            <th class="num">Upside if it holds</th>
            <th>Verdict</th>
          </tr>
        </thead>
        <tbody>${rows.map(trendRowHtml).join('')}</tbody>
      </table>`;

    el.querySelectorAll('.tr-hunt-btn').forEach(btn =>
      btn.addEventListener('click', () => huntTrendProduct(btn.dataset.query)));
  }

  function trendRowHtml(row) {
    const t = row.trend || {};
    const v = TREND_VERDICTS[row.verdict] || TREND_VERDICTS.watch;
    const s = TREND_SIGNALS[t.signal] || TREND_SIGNALS.unreadable;
    const pct = Number(t.priceChangePercent);
    const pctText = Number.isFinite(pct) ? `${pct > 0 ? '+' : ''}${pct.toFixed(1)}%` : '—';
    const rel = Number(t.relativeVelocityChangePercent);

    // "Tentative" is shown, never hidden — it is the difference between a measurement and a guess,
    // and the seller is about to spend money on which one this is.
    const tentative = t.reliability === 'tentative'
      ? '<span class="tr-tentative" title="Measured, but on thin or noisy evidence — see the note below.">tentative</span>' : '';

    const projected = t.projectedPrice != null
      ? `<div class="tr-sub">${money(t.projectedPrice)} if it holds</div>` : '';

    return `
      <tr class="tr-row ${row.verdict === 'buy_now' ? 'tr-row-buy' : ''}">
        <td class="tr-product">
          <div class="tr-name">${esc(row.product)}</div>
          <div class="tr-sub">${esc(row.nicheLabel)} · ${esc(row.resaleSource)} · ${row.soldCompCount + row.terapeakCompCount} comps · ${esc(row.confidenceLevel)}</div>
          <div class="tr-note">${esc(row.verdictNote)}</div>
          <div class="tr-note tr-note-quiet">${esc(t.note || '')}</div>
        </td>
        <td class="tr-trend">
          <span class="tr-signal ${s.cls}">${esc(s.label)}</span>${tentative}
          ${trendSparkline(t)}
          <div class="tr-sub">${Number.isFinite(pct) ? `${vizDelta(pct, { scale: 25, label: `Median sold price ${pctText}` })} ` : ''}${esc(pctText)} median${t.slopePerMonth ? ` · ${Number(t.slopePerMonth) > 0 ? '+' : ''}${money(t.slopePerMonth)}/mo trend` : ''}</div>
        </td>
        <td class="num">
          <div class="tr-strong">${money(row.ebayExpectedSale ?? row.ebayMedian)}</div>
          ${projected}
        </td>
        <td class="num">
          <div>${t.prior?.soldCount ?? 0} → ${t.recent?.soldCount ?? 0}</div>
          <div class="tr-sub">${Number.isFinite(rel) ? `${rel > 0 ? '+' : ''}${rel.toFixed(0)}% vs scan` : 'no baseline'}</div>
        </td>
        <td class="num"><div class="tr-strong">${money(row.maxBuyToday)}</div><div class="tr-sub">break-even today</div></td>
        <td class="num">${row.targetBuyPrice > 0
          ? `<div class="tr-strong">${money(row.targetBuyPrice)}</div><div class="tr-sub">${money(row.profitAtTarget)} net · ${Number(row.marginAtTargetPercent).toFixed(0)}%</div>` +
            // A climbing price is worth less if the money is stuck for five months getting it.
            (row.daysToCash != null
              ? `<div class="tr-sub"><span class="speed-days speed-${(SPEED_TIERS[row.speedTier] || SPEED_TIERS.unknown).cls}" title="${esc(row.speedNote || '')}">${row.daysToCash}d to cash</span>` +
                `${row.profitPerDay > 0 ? ` <span class="speed-rate">${perDay(row.profitPerDay)}</span>` : ''}</div>`
              : '')
          : '<span class="tr-sub">no price clears the bar</span>'}</td>
        <td class="num">${row.trendHeadroom > 0
          ? `<div class="tr-strong tr-up">+${money(row.trendHeadroom)}</div><div class="tr-sub">per unit</div>`
          : '<span class="tr-sub">—</span>'}</td>
        <td>
          <span class="tr-verdict ${v.cls}">${esc(v.label)}</span>
          <button class="btn btn-secondary small tr-hunt-btn" type="button" data-query="${esc(row.searchQuery)}">Find one</button>
        </td>
      </tr>`;
  }

  // Weekly medians, oldest left. Weeks with no sale are gaps in the line rather than points on it —
  // joining straight through them would draw a steady seller out of an intermittent one.
  //
  // Drawn through the shared spark primitive so it carries the same marks as every other line in
  // the app: a 2px stroke, a 10% wash under it, and one end dot ringed in the surface colour so it
  // stays legible where it lands on the line. The intermediate dots this used to draw are gone —
  // at 32px tall they were ink on top of the shape rather than points you could read — and each
  // week now has a full-height hover band instead, which is a target a mouse can actually hit.
  function trendSparkline(trend) {
    const points = Array.isArray(trend?.series) ? trend.series : [];
    const priced = points.filter(p => p.soldCount > 0 && p.medianPrice > 0);
    if (priced.length < 2) return '<div class="tr-spark-empty">not enough weeks to draw</div>';

    const w = 120, h = 32, pad = 4;
    const values = priced.map(p => Number(p.medianPrice));
    const min = Math.min(...values), max = Math.max(...values);

    const marks = points.map(p => ({
      value: Number(p.medianPrice),
      gap: !(p.soldCount > 0 && p.medianPrice > 0),
    }));
    const body = vizSparkPaths(marks, { w, h, pad });

    const step = points.length > 1 ? (w - pad * 2) / (points.length - 1) : 0;
    const hits = points.map((p, i) => {
      const weeks = p.weeksAgo === 0 ? 'This week' : `${p.weeksAgo} week${p.weeksAgo === 1 ? '' : 's'} ago`;
      const tip = marks[i].gap
        ? `${weeks}\nNo sales recorded`
        : `${weeks}\n${money(p.medianPrice)} median · ${p.soldCount} sold`;
      return `<rect class="viz-hit" x="${Math.max(0, pad + i * step - step / 2).toFixed(1)}" y="0"
        width="${Math.max(4, step).toFixed(1)}" height="${h}" data-viz-tip="${esc(tip)}" />`;
    }).join('');

    // Coloured from the server's signal, not re-derived from first-vs-last here — the picture has
    // to agree with the badge sitting beside it. A supply squeeze drawn in "rising green" because
    // its newest week happened to be high is the picture arguing with the sentence.
    const tone = (TREND_SIGNALS[trend.signal] || TREND_SIGNALS.unreadable).cls.replace('tr-s-', 'viz-spark-');

    return `<svg class="tr-spark viz-spark ${tone}" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img"
      aria-label="Weekly median sold price, ${money(min)} to ${money(max)}">${body}${hits}</svg>`;
  }

  // Hands the product straight to Local Deals — the radar says WHAT to buy, that screen finds WHERE.
  // The keyword is the same short query the server built, so the two screens search the same thing.
  function huntTrendProduct(query) {
    if (!query) return;
    closeTrendsSection();
    showOpportunitySection();
    const box = $('fb-query-input');
    if (box) {
      box.value = query;
      box.scrollIntoView({ behavior: 'smooth', block: 'center' });
      box.focus();
    }
  }

  // ── Snap & Source ─────────────────────────────────────────────────────────
  // Off /api/snap. The only screen in this app built for a phone held in one hand, and the rules it
  // renders by follow from that:
  //   * the verdict is the first and largest thing on the page, readable at arm's length;
  //   * the number under it is the one to ACT on — what to pay — not the one that is most flattering;
  //   * a photo verdict says it came from a photo, every time, because the app cannot see a cracked
  //     screen or a missing charger and the seller can;
  //   * the identified name is editable in place: the fastest fix for a wrong price is a right name,
  //     and re-pricing a corrected name must never pay for a second look at the same picture.
  let snapResult = null;
  let snapImageBase64 = '';
  let snapMimeType = '';
  let snapRunning = false;

  function showSnapSection() {
    hideOverlaySections();
    $('snap-section')?.classList.remove('hidden');
    setActiveNavItem('snap');
    markWorkspaceTabOpen('snap');
  }

  function closeSnapSection() {
    closeWorkspacePage('snap');
  }

  function bindSnapSource() {
    on('snap-run-btn', 'click', runSnap);
    on('snap-go', 'click', runSnap);
    on('snap-close', 'click', closeSnapSection);
    on('snap-home', 'click', goHome);
    on('snap-what', 'keydown', e => { if (e.key === 'Enter') runSnap(); });
    on('snap-ask', 'keydown', e => { if (e.key === 'Enter') runSnap(); });

    on('snap-drop', 'click', () => $('snap-file')?.click());
    on('snap-drop', 'keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); $('snap-file')?.click(); }
    });
    on('snap-file', 'change', e => { if (e.target.files?.[0]) readSnapPhoto(e.target.files[0]); });

    on('snap-clear-photo', 'click', e => { e.stopPropagation(); clearSnapPhoto(); });

    const drop = $('snap-drop');
    if (drop) {
      drop.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('snap-drop-over'); });
      drop.addEventListener('dragleave', () => drop.classList.remove('snap-drop-over'));
      drop.addEventListener('drop', e => {
        e.preventDefault();
        drop.classList.remove('snap-drop-over');
        const file = e.dataTransfer?.files?.[0];
        if (file) readSnapPhoto(file);
      });
    }

    // A screenshot of a listing pasted straight in is the desk-bound half of this feature, and it
    // is one keystroke. Scoped to this screen being open so it can't steal a paste from a form.
    document.addEventListener('paste', e => {
      if ($('snap-section')?.classList.contains('hidden')) return;
      const item = [...(e.clipboardData?.items || [])].find(i => i.type?.startsWith('image/'));
      if (!item) return;
      const file = item.getAsFile();
      if (file) { e.preventDefault(); readSnapPhoto(file); }
    });
  }

  function readSnapPhoto(file) {
    const reader = new FileReader();
    reader.onload = ev => {
      const data = String(ev.target.result);
      snapImageBase64 = data.split(',')[1] || '';
      snapMimeType = file.type || 'image/jpeg';

      const thumb = $('snap-thumb');
      if (thumb) { thumb.src = data; thumb.classList.remove('hidden'); }
      $('snap-drop-prompt')?.classList.add('hidden');
      $('snap-clear-photo')?.classList.remove('hidden');
      setSnapStatus('Photo ready. Add what they want for it, then hit the button.');
    };
    reader.readAsDataURL(file);
  }

  function clearSnapPhoto() {
    snapImageBase64 = '';
    snapMimeType = '';
    const thumb = $('snap-thumb');
    if (thumb) { thumb.src = ''; thumb.classList.add('hidden'); }
    $('snap-drop-prompt')?.classList.remove('hidden');
    $('snap-clear-photo')?.classList.add('hidden');
    if ($('snap-file')) $('snap-file').value = '';
  }

  function setSnapStatus(text) {
    const el = $('snap-status');
    if (el) el.textContent = text || '';
  }

  async function runSnap() {
    if (snapRunning) return;

    const what = $('snap-what')?.value.trim() || '';
    const askRaw = $('snap-ask')?.value.trim() || '';

    if (!what && !snapImageBase64) {
      setSnapStatus('Paste a link, type what it is, or add a photo first.');
      $('snap-what')?.focus();
      return;
    }

    // The server decides whether a typed string is a link or an item name — one rule, not two.
    const body = { title: what || null, imageBase64: snapImageBase64 || null, mimeType: snapMimeType || null };
    if (askRaw !== '') {
      const ask = parseFloat(askRaw);
      if (Number.isFinite(ask) && ask >= 0) body.askPrice = ask;
    }

    snapRunning = true;
    const buttons = ['snap-run-btn', 'snap-go'].map($).filter(Boolean);
    buttons.forEach(b => { b.disabled = true; b.textContent = 'Checking…'; });
    setSnapStatus(snapImageBase64 && !what
      ? 'Reading the photo, then the sold comps…'
      : 'Reading the sold comps…');
    $('snap-result').innerHTML = '<div class="snap-working"><span class="snap-spinner" aria-hidden="true"></span>Pricing it against real sold listings…</div>';

    try {
      const res = await fetch('/api/snap', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.whatHappened || data?.error || data?.headline || 'That didn\'t price.');
      snapResult = data;
      renderSnap();
    } catch (err) {
      snapResult = null;
      $('snap-result').innerHTML = `<div class="snap-error">${esc(errorText(err, 'That didn\'t price.'))}</div>`;
      setSnapStatus('');
    } finally {
      snapRunning = false;
      buttons.forEach(b => { b.disabled = false; b.textContent = '⚡ Should I buy it?'; });
    }
  }

  // The five answers, and nothing in between. The label text comes from the server so the badge and
  // the log say the same word — this only decides how loud it is.
  const SNAP_CALLS = {
    buy:       { cls: 'snap-call-buy',     sub: 'Worth buying at that price.' },
    buy_under: { cls: 'snap-call-buy',     sub: 'Nobody has named a price — this is the one to stop at.' },
    close:     { cls: 'snap-call-close',   sub: 'Real money, thin margin. Only if the buy gets cheaper.' },
    pass:      { cls: 'snap-call-pass',    sub: 'Walk away.' },
    unknown:   { cls: 'snap-call-unknown', sub: 'Nothing priced it — check the sold listings yourself.' },
  };

  function renderSnap() {
    const el = $('snap-result');
    if (!el || !snapResult) return;

    const r = snapResult;
    const call = SNAP_CALLS[r.call] || SNAP_CALLS.unknown;

    // "What to pay" leads every priced answer, including the ones where a profit figure exists.
    // The profit is the reason; the price is the decision, and the decision is what the seller is
    // holding the phone to make.
    const money = [];
    if (r.payUpTo > 0) {
      money.push(tile('Pay up to', moneyExact(r.payUpTo), 'snap-tile-hero',
        r.profitAtPayUpTo > 0 ? `keeps ${moneyExact(r.profitAtPayUpTo)}` : ''));
    }
    if (r.askWasKnown && r.netProfit != null) {
      money.push(tile('Profit at ' + moneyExact(r.askPrice), moneyExact(r.netProfit),
        r.netProfit > 0 ? 'snap-tile-good' : 'snap-tile-bad',
        r.roiPercent != null ? `${Math.round(r.roiPercent)}% ROI` : ''));
    }
    if (r.resalePrice > 0) {
      money.push(tile('Sells for', moneyExact(r.resalePrice), '',
        r.quickSalePrice > 0 ? `quick sale ${moneyExact(r.quickSalePrice)}` : ''));
    }
    if (r.buyMax > 0) {
      money.push(tile('Break even', moneyExact(r.buyMax), '', 'lose money above this'));
    }
    if (r.daysToCash != null) {
      money.push(tile('Cash back in', `${r.daysToCash}d`, '', r.speedLabel || ''));
    }

    // Evidence is never a footnote here. A seller about to hand over cash on a phone screen has room
    // for one line about how much the number is worth, and this is it.
    const tierWord = { confident: 'Backed', low: 'Thin', none: 'No data' }[r.evidenceTier] || 'No data';
    const evidence = `
      <div class="snap-evidence snap-ev-${esc(r.evidenceTier || 'none')}">
        <span class="snap-ev-pill">${esc(tierWord)}</span>
        <span class="snap-ev-text">${esc(r.evidenceNote || `${r.compCount} sold comp${r.compCount === 1 ? '' : 's'}.`)}</span>
      </div>`;

    const warnings = (r.warnings || []).length
      ? `<ul class="snap-warnings">${r.warnings.map(w => `<li>${esc(w)}</li>`).join('')}</ul>`
      : '';

    // The name is an input, not a label. When the price is wrong the name is usually why, and the
    // seller can see that faster than any confidence score can tell them.
    const identity = r.identity
      ? `<div class="snap-id-note">Read off the photo · ${esc(r.identity.certainty)} confidence${
          r.identity.conditionNote ? ` · ${esc(r.identity.conditionNote)}` : ''}</div>`
      : '';

    el.innerHTML = `
      <div class="snap-card">
        <div class="snap-verdict ${call.cls}">
          <div class="snap-call">${esc(r.callLabel || '')}</div>
          <div class="snap-call-sub">${esc(call.sub)}</div>
        </div>

        <div class="snap-reason">${esc(r.reason || '')}</div>

        <div class="snap-item">
          ${r.imageUrl ? `<img class="snap-item-img" src="${esc(r.imageUrl)}" alt="" loading="lazy" />` : ''}
          <div class="snap-item-body">
            <label class="snap-item-label" for="snap-item-name">Priced as — fix it and snap again if it's wrong</label>
            <input id="snap-item-name" class="snap-item-name" type="text" value="${esc(r.pricedAs || r.item || '')}" />
            <div class="snap-item-meta">
              ${esc(r.sourceLabel || '')}${r.categoryLabel ? ` · ${esc(r.categoryLabel)}` : ''}
              ${r.elapsedMs ? ` · ${(r.elapsedMs / 1000).toFixed(1)}s` : ''}
            </div>
            ${identity}
          </div>
        </div>

        ${money.length ? `<div class="snap-tiles">${money.join('')}</div>` : ''}
        ${evidence}
        ${warnings}

        <div class="snap-actions">
          <button class="btn btn-primary" type="button" onclick="snapRepriceFromCard()">Re-price this name</button>
          ${r.soldSearchUrl ? `<a class="btn btn-ghost" href="${esc(r.soldSearchUrl)}" target="_blank" rel="noopener">See the sold listings</a>` : ''}
          ${r.sourceUrl ? `<a class="btn btn-ghost" href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Open the listing</a>` : ''}
        </div>
      </div>`;

    setSnapStatus(r.compCount > 0
      ? `Priced off ${r.compCount} sold comp${r.compCount === 1 ? '' : 's'}.`
      : 'No sold comps matched.');

    function tile(label, value, cls, foot) {
      return `<div class="snap-tile ${cls}">
                <div class="snap-tile-label">${esc(label)}</div>
                <div class="snap-tile-value">${esc(value)}</div>
                ${foot ? `<div class="snap-tile-foot">${esc(foot)}</div>` : ''}
              </div>`;
    }
  }

  // Corrected name, same photo. The photo is deliberately NOT re-sent: the seller has already told
  // the app what it is, so paying for a second look at the picture would buy nothing and cost a
  // wait — see the server's own guard on the same rule.
  function snapRepriceFromCard() {
    const name = $('snap-item-name')?.value.trim();
    if (!name) return;
    const box = $('snap-what');
    if (box) box.value = name;
    clearSnapPhoto();
    runSnap();
  }
  window.snapRepriceFromCard = snapRepriceFromCard;

  // ── Where to Sell Highest ─────────────────────────────────────────────────
  // Off /api/where-to-sell. The whole screen is one comparison, so the rules it renders by are
  // about not overstating it:
  //   * the evidence word ("sold" vs "asking") is on every price, never a footnote — they are not
  //     the same kind of number and the seller is deciding on the difference;
  //   * a venue with thin evidence is drawn as thin even when its number is the biggest on screen;
  //   * a venue that could not be searched shows why, rather than an empty column that reads as a
  //     venue which lost;
  //   * "the price it has to fetch to beat eBay" is shown everywhere, including where there is no
  //     price data at all — it is fee arithmetic and it is always true.
  let wtsReport = null;

  function showWhereToSellSection() {
    hideOverlaySections();
    $('wts-section')?.classList.remove('hidden');
    setActiveNavItem('wheretosell');
    markWorkspaceTabOpen('wheretosell');
  }

  function closeWhereToSellSection() {
    closeWorkspacePage('wheretosell');
  }

  function bindWhereToSell() {
    on('wts-run-btn', 'click', runWhereToSell);
    on('wts-close', 'click', closeWhereToSellSection);
    on('wts-home', 'click', goHome);
    on('wts-query', 'keydown', e => { if (e.key === 'Enter') runWhereToSell(); });
    on('wts-zip', 'keydown', e => { if (e.key === 'Enter') runWhereToSell(); });

    // The same remembered zip and radius every other local search uses — a seller types their zip
    // code once for the whole app, not once per screen.
    const zip = localStorage.getItem('fbZip');
    const radius = localStorage.getItem('fbRadius');
    if (zip && $('wts-zip')) $('wts-zip').value = zip;
    if (radius && $('wts-radius')) $('wts-radius').value = radius;
  }

  function setWtsStatus(text) {
    const el = $('wts-status');
    if (el) el.textContent = text || '';
  }

  async function runWhereToSell() {
    const query = $('wts-query')?.value.trim() || '';
    const zip = $('wts-zip')?.value.trim() || '';
    const radius = $('wts-radius')?.value || '40';
    const cost = $('wts-cost')?.value.trim() || '';
    const btn = $('wts-run-btn');

    if (!query) {
      setWtsStatus('Tell me what the item is first.');
      $('wts-query')?.focus();
      return;
    }
    if (zip) localStorage.setItem('fbZip', zip);
    localStorage.setItem('fbRadius', radius);

    const qs = `q=${encodeURIComponent(query)}&zip=${encodeURIComponent(zip)}&radius=${encodeURIComponent(radius)}` +
      (cost ? `&cost=${encodeURIComponent(cost)}` : '');

    if (btn) { btn.disabled = true; btn.textContent = 'Comparing…'; }
    setWtsStatus(zip ? `Pricing on eBay, then searching within ${radius} miles of ${zip}…`
                     : 'Pricing on eBay… add a zip code to price the local venues too.');
    $('wts-banner')?.classList.add('hidden');
    $('wts-warnings')?.classList.add('hidden');
    $('wts-results').innerHTML = '<p class="opportunity-empty">Reading sold history, then what people near you are asking. The local sites are searched one at a time, so give it a moment.</p>';

    try {
      const res = await fetch(`/api/where-to-sell?${qs}`);
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || 'The comparison failed.');
      wtsReport = data;
      renderWhereToSell();
    } catch (err) {
      wtsReport = null;
      $('wts-banner')?.classList.add('hidden');
      $('wts-warnings')?.classList.add('hidden');
      $('wts-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The comparison failed.'))}</p>`;
      setWtsStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🧭 Compare Venues'; }
    }
  }

  const WTS_VERDICTS = {
    best:        { label: '🏆 Sell it here', cls: 'wts-v-best' },
    close:       { label: 'About the same',  cls: 'wts-v-close' },
    lower:       { label: 'Pays less',       cls: 'wts-v-lower' },
    thin:        { label: '⚠️ Thin data',    cls: 'wts-v-thin' },
    no_data:     { label: 'No price data',   cls: 'wts-v-none' },
    unavailable: { label: 'Not searched',    cls: 'wts-v-none' },
  };

  const WTS_EVIDENCE = {
    sold:   { label: 'what buyers PAID',   cls: 'wts-e-sold' },
    asking: { label: 'what sellers ASK',   cls: 'wts-e-ask' },
    none:   { label: 'no price data',      cls: 'wts-e-none' },
  };

  function renderWhereToSell() {
    if (!wtsReport) return;

    if (wtsReport.status === 'error') {
      $('wts-banner')?.classList.add('hidden');
      $('wts-results').innerHTML = `<p class="opportunity-empty">${esc(wtsReport.error || 'The comparison failed.')}</p>`;
      setWtsStatus('');
      return;
    }

    renderWtsBanner();
    renderWtsWarnings();
    renderWtsVenues();

    const priced = (wtsReport.venues || []).filter(v => v.netProceeds != null).length;
    setWtsStatus(`${priced} of ${(wtsReport.venues || []).length} venues priced` +
      (wtsReport.zipCode ? ` · within ${wtsReport.radiusMiles} miles of ${wtsReport.zipCode}` : ' · no zip, so eBay only'));
  }

  // The one sentence the screen exists for, with the money in it.
  function renderWtsBanner() {
    const el = $('wts-banner');
    if (!el) return;

    const tone = { move: 'wts-banner-move', stay_on_ebay: 'wts-banner-stay',
                   too_close: 'wts-banner-close', no_data: 'wts-banner-none' }[wtsReport.verdict] || '';

    // Only a real, material gap gets the money strip — a two-dollar edge dressed up as a headline
    // figure is exactly how this feature would start lying.
    const extra = wtsReport.verdict === 'move' && wtsReport.extraVsEbay > 0
      ? `<div class="wts-banner-extra"><span class="wts-extra-value">+${moneyExact(wtsReport.extraVsEbay)}</span>
           <span class="wts-extra-label">more on this one item</span></div>`
      : '';

    el.className = `wts-banner ${tone}`;
    el.innerHTML = `
      <div class="wts-banner-text">
        <div class="wts-banner-head">${esc(wtsReport.headline || '')}</div>
        <div class="wts-banner-sub">${esc(wtsReport.subhead || '')}</div>
      </div>
      ${extra}`;
    el.classList.remove('hidden');
  }

  function renderWtsWarnings() {
    const el = $('wts-warnings');
    if (!el) return;
    const warnings = wtsReport.warnings || [];
    if (warnings.length === 0) { el.classList.add('hidden'); return; }

    el.innerHTML = warnings.map(w => `<div>${esc(w)}</div>`).join('');
    el.classList.remove('hidden');
  }

  function renderWtsVenues() {
    const el = $('wts-results');
    const venues = wtsReport.venues || [];
    if (venues.length === 0) {
      el.innerHTML = '<p class="opportunity-empty">Nothing to compare.</p>';
      return;
    }
    el.innerHTML = `<div class="wts-grid">${venues.map(wtsVenueHtml).join('')}</div>`;
  }

  function wtsVenueHtml(v) {
    const verdict = WTS_VERDICTS[v.verdict] || WTS_VERDICTS.no_data;
    const evidence = WTS_EVIDENCE[v.evidenceKind] || WTS_EVIDENCE.none;

    // The headline number is the take-home, never the price. The price is shown under it, as the
    // input it is.
    const takeHome = v.netProceeds != null
      ? `<div class="wts-take">${moneyExact(v.netProceeds)}</div>
         <div class="wts-take-label">${wtsReport.hasCostBasis && v.netProfit != null
            ? `${moneyExact(v.netProfit)} profit after what you paid`
            : 'in your pocket'}</div>`
      : `<div class="wts-take wts-take-none">—</div><div class="wts-take-label">not priced here</div>`;

    const gap = v.venue !== 'ebay' && v.netVsEbay != null
      ? `<div class="wts-gap ${v.netVsEbay > 0 ? 'wts-gap-up' : 'wts-gap-down'}">${v.netVsEbay > 0 ? '+' : ''}${moneyExact(v.netVsEbay)} vs eBay</div>`
      : '';

    const price = v.expectedPrice != null
      ? `<div class="wts-line"><span>Likely sale price</span><strong>${moneyExact(v.expectedPrice)}</strong></div>` +
        (v.buyerPaidShipping > 0
          ? `<div class="wts-line wts-line-quiet"><span>Buyer also pays shipping</span><span>${moneyExact(v.buyerPaidShipping)}</span></div>` : '')
      : '';

    const costs = (v.costs || []).filter(c => c.amount > 0);
    const costLines = v.netProceeds != null
      ? (costs.length
          ? costs.map(c => `<div class="wts-line wts-line-cost" title="${esc(c.detail)}"><span>${esc(c.label)}</span><span>−${moneyExact(c.amount)}</span></div>`).join('')
          : '<div class="wts-line wts-line-free"><span>Taken out of the sale</span><strong>nothing</strong></div>')
      : '';

    const beat = v.priceToBeatEbay != null
      ? `<div class="wts-beat" title="${esc(v.priceToBeatEbayNote || '')}">Beat eBay here at <strong>${moneyExact(v.priceToBeatEbay)}</strong></div>`
      : '';

    // A venue with no price has no speed either — an "unknown" clock under an empty column is
    // noise pretending to be a measurement.
    const speed = v.netProceeds == null ? ''
      : v.daysToCash != null
        ? `<div class="wts-speed" title="${esc(v.speedNote || '')}">${v.daysToCash}d to cash${v.netPerDay > 0 ? ` · ${perDay(v.netPerDay)}` : ''}</div>`
        : `<div class="wts-speed wts-speed-quiet" title="${esc(v.speedNote || '')}">${esc(v.speedLabel || 'Speed unknown')}</div>`;

    const evidenceBits = [
      v.sampleCount > 0 ? `${v.sampleCount} ${v.evidenceKind === 'sold' ? 'sold' : 'listed'}` : null,
      v.confidenceLevel && v.sampleCount > 0 ? v.confidenceLevel : null,
    ].filter(Boolean).join(' · ');

    return `
      <div class="wts-card ${v.verdict === 'best' ? 'wts-card-best' : ''} ${v.netProceeds == null ? 'wts-card-quiet' : ''}">
        <div class="wts-card-head">
          <div>
            <div class="wts-venue">${esc(v.venueLabel)}</div>
            <div class="wts-mode">${esc(v.saleModeLabel)}</div>
          </div>
          <span class="wts-verdict ${verdict.cls}">${esc(verdict.label)}</span>
        </div>

        <div class="wts-money">
          ${takeHome}
          ${gap}
        </div>

        <div class="wts-evidence">
          <span class="wts-ev ${evidence.cls}">${esc(evidence.label)}</span>
          ${evidenceBits ? `<span class="wts-ev-sub">${esc(evidenceBits)}</span>` : ''}
        </div>

        <div class="wts-lines">
          ${price}
          ${costLines}
        </div>

        ${beat}
        <div class="wts-note">${esc(v.priceBasis || v.note || '')}</div>
        ${speed}
        <div class="wts-fee-note">${esc(v.feeNote || '')}</div>
        ${v.createUrl ? `<a class="btn btn-secondary small wts-go" href="${esc(v.createUrl)}" target="_blank" rel="noopener noreferrer">List it on ${esc(v.venueLabel)} ↗</a>` : ''}
      </div>`;
  }

  // ── The Undervalued-Auction Sniper ────────────────────────────────────────
  // Every other sourcing screen sends the seller somewhere else to buy. This one buys on eBay and
  // sells on eBay, hours apart, off /api/snipes — which prices live listings against the same sold
  // comps the rest of the app uses and returns the one number a bidder needs: the most to bid.
  //
  // Three things this UI must never do, all of which would make it a slot machine:
  //   * show profit at a current bid as though it were profit. The board leads with the ceiling and
  //     what winning THERE pays, because that is the worst case of a bid you'd actually place;
  //   * let a "too early" row look like a live one. Their prices aren't real yet, they carry no
  //     money into any total, and the badge says so;
  //   * hide the reasons something is cheap. The risks list is rendered in full on every row.
  let snipeScan = null;
  let snipeTicker = null;

  function showSnipeSection() {
    hideOverlaySections();
    $('snipe-section')?.classList.remove('hidden');
    setActiveNavItem('snipe');
    markWorkspaceTabOpen('snipe');
    startSnipeTicker();
  }

  // The ticker is stopped by the tab machinery (onHide) whether this screen is closed or merely
  // switched away from — a countdown ticking for a screen nobody is looking at is wasted work.
  function closeSnipeSection() {
    closeWorkspacePage('snipe');
  }

  function bindSniper() {
    on('sn-scan-btn', 'click', () => runSnipeScan());
    on('sn-close', 'click', () => closeSnipeSection());
    on('sn-home', 'click', goHome);
    on('dash-snipe-open', 'click', () => { navigateTo('snipe'); });
    // Ranking is the server's, so re-ordering means asking it again rather than re-implementing the
    // rules here — two sort orders that disagree is two answers to "what should I bid on first".
    on('sn-sort', 'change', () => { if (snipeScan) runSnipeScan(); });
    on('sn-mode', 'change', () => { if (snipeScan) runSnipeScan(); });
    on('sn-terms', 'keydown', e => { if (e.key === 'Enter') runSnipeScan(); });
  }

  function setSnipeStatus(text) {
    const el = $('sn-status');
    if (el) el.textContent = text || '';
  }

  async function runSnipeScan() {
    const btn = $('sn-scan-btn');
    const terms = ($('sn-terms')?.value || '').trim();
    const mode = $('sn-mode')?.value || 'auctions';
    const sort = $('sn-sort')?.value || 'urgency';

    if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
    setSnipeStatus(terms ? 'Searching eBay and pricing what comes back…' : 'Working out what you already sell, then searching eBay…');
    $('sn-results').innerHTML = '<p class="opportunity-empty">Searching live listings, then pricing each one against real sold comps. This takes a moment.</p>';

    try {
      const q = terms ? `&q=${encodeURIComponent(terms)}` : '';
      const res = await fetch(`/api/snipes?mode=${encodeURIComponent(mode)}&sort=${encodeURIComponent(sort)}${q}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      snipeScan = data;
      renderSnipeScan();
    } catch (err) {
      snipeScan = null;
      ['sn-summary', 'sn-warning', 'sn-terms-bar', 'sn-honesty'].forEach(id => $(id)?.classList.add('hidden'));
      $('sn-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setSnipeStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🎯 Find Underpriced Auctions'; }
    }
  }

  function renderSnipeScan() {
    if (!snipeScan) return;

    if (snipeScan.status === 'error') {
      ['sn-summary', 'sn-terms-bar'].forEach(id => $(id)?.classList.add('hidden'));
      $('sn-results').innerHTML = `<p class="opportunity-empty">${esc(snipeScan.error || 'The scan failed.')}</p>`;
      renderSnipeHonesty();
      setSnipeStatus('');
      return;
    }

    const warn = $('sn-warning');
    if (snipeScan.dataWarning) {
      warn.textContent = snipeScan.dataWarning;
      warn.classList.remove('hidden');
    } else {
      warn?.classList.add('hidden');
    }

    // Nothing to hunt for is not an empty board — it is a board that hasn't been told what to look
    // at, and the fix is one sentence long. Zeroed tiles above it would read as "we looked".
    if (snipeScan.status === 'no_terms') {
      $('sn-summary')?.classList.add('hidden');
      $('sn-terms-bar')?.classList.add('hidden');
      $('sn-results').innerHTML = '<p class="opportunity-empty">Type what you\'re hunting for above, or import your eBay sales in Money Made — this hunts the products you\'ve already sold.</p>';
      renderSnipeHonesty();
      setSnipeStatus('');
      return;
    }

    renderSnipeSummary();
    renderSnipeTerms();
    renderSnipeRows();
    renderSnipeHonesty();
    renderDashboardSnipes();
    startSnipeTicker();

    const s = snipeScan.summary || {};
    setSnipeStatus(
      `${s.listingsScanned || 0} live listing${s.listingsScanned === 1 ? '' : 's'} across ${s.termsScanned || 0} ` +
      `search${s.termsScanned === 1 ? '' : 'es'} · ${s.listingsRejected || 0} dropped as not the same item · ` +
      `${s.snipeCount || 0} worth bidding on`);
  }

  function renderSnipeSummary() {
    const el = $('sn-summary');
    if (!el) return;
    const s = snipeScan.summary || {};

    const tiles = [
      { label: 'Worth bidding on now', value: String(s.snipeCount || 0),
        sub: s.snipeCount ? 'Priced under market, and close enough to the end that the price is real' : 'Nothing live cleared the bar this scan',
        tone: s.snipeCount > 0 ? 'good' : '' },
      { label: 'If you won them all at your ceiling', value: money(s.profitAtCeilings),
        sub: 'An upper bound on what is on the board right now — it falls every time somebody bids',
        tone: s.profitAtCeilings > 0 ? 'good' : '' },
      { label: 'Best single row', value: money(s.bestProfit),
        sub: 'Net profit at that row\'s max bid, after every fee' },
      { label: 'Cash to win all of them', value: money(s.capitalToWinAll),
        sub: 'What bidding to every ceiling would cost, shipping included' },
      { label: 'Closing within the hour', value: String(s.closingWithinTheHour || 0),
        sub: s.nextEndUtc ? `Soonest closes ${snipeClock(s.nextEndUtc)}` : 'Nothing on the clock right now',
        tone: s.closingWithinTheHour > 0 ? 'warn' : '' },
      { label: 'Too early to price', value: String(s.tooEarlyCount || 0),
        sub: `Auctions more than ${snipeScan.priceIsRealHours}h out — their prices aren't real yet` },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  // What was actually searched, and why. When the terms came from the seller's own sales this is
  // the most persuasive line on the page — the board is hunting things they have already sold.
  function renderSnipeTerms() {
    const el = $('sn-terms-bar');
    if (!el) return;
    const terms = snipeScan.terms || [];
    if (terms.length === 0) { el.classList.add('hidden'); return; }

    const chips = terms.map(t => {
      const detail = t.error
        ? `couldn't be searched: ${t.error}`
        : !t.priced ? 'no sold history to price it'
        : `${t.kept} kept${t.listingsRejected ? `, ${t.listingsRejected} dropped` : ''}`;
      return `<span class="sn-chip ${t.error || !t.priced ? 'sn-chip-quiet' : ''}" title="${esc(detail)}">
        <strong>${esc(t.term)}</strong><span class="sn-chip-sub">${esc(t.reason)} · ${esc(detail)}</span></span>`;
    }).join('');

    el.innerHTML = `<span class="sn-terms-label">${snipeScan.termsWereTyped ? 'Searched' : 'Hunting what you\'ve already sold'}</span>${chips}`;
    el.classList.remove('hidden');
  }

  function renderSnipeHonesty() {
    const el = $('sn-honesty');
    if (!el) return;
    const lines = snipeScan?.honesty || [];
    if (lines.length === 0) { el.classList.add('hidden'); return; }
    el.innerHTML = lines.map(l => `<li>${esc(l)}</li>`).join('');
    el.classList.remove('hidden');
  }

  const SNIPE_VERDICTS = {
    snipe:     { label: '🎯 Bid on it',   cls: 'sn-v-snipe' },
    too_early: { label: '⏳ Too early',   cls: 'sn-v-early' },
    watch:     { label: '👀 Watch',       cls: 'sn-v-watch' },
    thin:      { label: '⚠️ Thin data',   cls: 'sn-v-thin' },
    pass:      { label: '✕ Pass',         cls: 'sn-v-pass' },
    ended:     { label: '· Ended',        cls: 'sn-v-pass' },
    no_data:   { label: '? No comps',     cls: 'sn-v-pass' },
  };

  function renderSnipeRows() {
    const el = $('sn-results');
    const rows = snipeScan.candidates || [];

    if (rows.length === 0) {
      el.innerHTML = `<p class="opportunity-empty">${esc(
        snipeScan.dataWarning ||
        'Nothing live is priced under what these sell for right now. That is the normal answer most of the time.')}</p>`;
      return;
    }

    el.innerHTML = `
      <table class="inv-table sn-table">
        <thead>
          <tr>
            <th>Listing</th>
            <th>Closes</th>
            <th class="num">Price now</th>
            <th class="num">Sells for</th>
            <th class="num">Your max bid</th>
            <th class="num">If you win there</th>
            <th>Verdict</th>
            <th>Track</th>
          </tr>
        </thead>
        <tbody>${rows.map(snipeRowHtml).join('')}</tbody>
      </table>`;

    el.querySelectorAll('.sn-track-btn').forEach(btn =>
      btn.addEventListener('click', () => trackSnipeRow(btn.dataset.itemId, btn)));
    updateSnipeClocks();
  }

  function snipeRowHtml(row) {
    const v = SNIPE_VERDICTS[row.verdict] || SNIPE_VERDICTS.no_data;
    const comps = (row.soldCompCount || 0) + (row.terapeakCompCount || 0);
    const speed = SPEED_TIERS[row.speedTier] || SPEED_TIERS.unknown;

    const risks = (row.risks || []).length
      ? `<ul class="sn-risks">${row.risks.map(r => `<li>${esc(r)}</li>`).join('')}</ul>` : '';

    // The countdown is the only thing on this board that changes while you look at it, so it ticks
    // in the browser rather than being frozen at whatever the server said a minute ago.
    const clock = row.endUtc
      ? `<div class="sn-clock sn-clock-${esc(row.timeTier)}" data-ends="${esc(row.endUtc)}">${esc(snipeClock(row.endUtc))}</div>`
      : '<div class="sn-clock sn-clock-none">Buy It Now</div>';

    const bids = row.buyingOption === 'AUCTION'
      ? `<div class="sn-sub">${row.bidCount || 0} bid${row.bidCount === 1 ? '' : 's'}</div>` : '';

    const snipeAt = row.snipeAtUtc && row.verdict === 'snipe'
      ? `<div class="sn-sub sn-snipe-at">bid at ${esc(snipeLocalTime(row.snipeAtUtc))}</div>` : '';

    const headroom = row.bidHeadroom != null && row.buyingOption === 'AUCTION'
      ? `<div class="sn-sub ${row.bidHeadroom >= 0 ? '' : 'sn-over'}">${row.bidHeadroom >= 0
          ? `${money(row.bidHeadroom)} of room left`
          : `${money(Math.abs(row.bidHeadroom))} past it`}</div>`
      : '';

    const discount = row.discountPercent != null
      ? `<div class="sn-sub">${row.discountPercent > 0
          ? `${Number(row.discountPercent).toFixed(0)}% under market`
          : `${Number(Math.abs(row.discountPercent)).toFixed(0)}% over market`}</div>`
      : '';

    const shipping = row.shippingCost > 0
      ? `<div class="sn-sub">+ ${money(row.shippingCost)} shipping</div>`
      : row.shippingStated ? '<div class="sn-sub">free shipping</div>' : '<div class="sn-sub sn-over">shipping not stated</div>';

    // Only rows with a real price and real evidence are worth freezing a forecast against — see
    // the Deal Pipeline, which grades every forecast it is given against what actually happened.
    const track = row.verdict === 'snipe' || row.verdict === 'too_early'
      ? `<button class="btn btn-secondary small sn-track-btn" type="button" data-item-id="${esc(row.itemId)}">＋ Track</button>`
      : '<span class="sn-sub">—</span>';

    return `
      <tr class="sn-row ${row.verdict === 'snipe' ? 'sn-row-snipe' : ''}">
        <td class="sn-item">
          <a class="sn-name" href="${esc(row.url)}" target="_blank" rel="noopener">${esc(row.title)}</a>
          <div class="sn-sub">${esc(row.condition || 'condition not stated')} · seller ${esc(row.sellerUsername || '—')} (${row.sellerFeedbackScore || 0})</div>
          <div class="sn-sub">priced as “${esc(row.pricedAs)}” · ${comps} sold comp${comps === 1 ? '' : 's'} · ${esc(row.confidenceLevel)}${row.pricedPerItem ? ' · <span class="sn-tag">priced off this listing</span>' : ''}</div>
          <div class="sn-note">${esc(row.verdictNote)}</div>
          ${risks}
        </td>
        <td class="sn-time">${clock}${bids}${snipeAt}</td>
        <td class="num">
          <div class="sn-strong">${money(row.currentPrice)}</div>
          ${shipping}
        </td>
        <td class="num">
          <div class="sn-strong">${money(row.expectedSale ?? row.marketMedian)}</div>
          ${discount}
        </td>
        <td class="num">
          ${row.maxBid > 0
            // To the cent, deliberately. money() rounds to whole dollars, which would print a
            // $133.65 ceiling as $134 — a number above the ceiling, in the one column somebody
            // copies straight into a bid box. The server truncates for the same reason.
            ? `<div class="sn-strong sn-max">${moneyExact(row.maxBid)}</div>${headroom}`
            : '<span class="sn-sub">—</span>'}
        </td>
        <td class="num">
          ${row.profitAtMaxBid > 0
            ? `<div class="sn-strong sn-profit">${money(row.profitAtMaxBid)}</div>` +
              (row.daysToCash != null
                ? `<div class="sn-sub"><span class="speed-days speed-${speed.cls}" title="${esc(row.speedNote || '')}">${row.daysToCash}d to cash</span></div>`
                : '<div class="sn-sub">speed unknown</div>')
            : '<span class="sn-sub">—</span>'}
        </td>
        <td><span class="sn-verdict ${v.cls}">${esc(v.label)}</span></td>
        <td>${track}</td>
      </tr>`;
  }

  // ── The clock ─────────────────────────────────────────────────────────────

  function snipeClock(endUtc) {
    const ms = new Date(endUtc).getTime() - Date.now();
    if (!Number.isFinite(ms)) return '—';
    if (ms <= 0) return 'ended';

    const s = Math.floor(ms / 1000);
    const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600);
    const m = Math.floor((s % 3600) / 60), sec = s % 60;

    if (d > 0) return `${d}d ${h}h`;
    if (h > 0) return `${h}h ${String(m).padStart(2, '0')}m`;
    // Inside the hour the seconds matter — that is the whole window a snipe happens in.
    return `${m}m ${String(sec).padStart(2, '0')}s`;
  }

  function snipeLocalTime(utc) {
    const d = new Date(utc);
    return Number.isNaN(d.getTime()) ? '' : d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit', second: '2-digit' });
  }

  function updateSnipeClocks() {
    document.querySelectorAll('#sn-results [data-ends]').forEach(el => {
      const text = snipeClock(el.dataset.ends);
      el.textContent = text;
      const ms = new Date(el.dataset.ends).getTime() - Date.now();
      // A row that runs out under the seller's eyes says so, rather than sitting at "0m 00s"
      // looking winnable.
      el.classList.toggle('sn-clock-ended', ms <= 0);
      if (ms > 0 && ms <= 60 * 60 * 1000) {
        el.classList.remove('sn-clock-today', 'sn-clock-open');
        el.classList.add('sn-clock-closing');
      }
    });
    renderDashboardSnipes();
  }

  function startSnipeTicker() {
    stopSnipeTicker();
    if (!snipeScan || $('snipe-section')?.classList.contains('hidden')) return;
    snipeTicker = setInterval(() => {
      // Self-cancelling: navigating away hides the section without going through the close button,
      // and a timer left running against a hidden board is a leak nobody would ever notice.
      if ($('snipe-section')?.classList.contains('hidden')) { stopSnipeTicker(); return; }
      updateSnipeClocks();
    }, 1000);
  }

  function stopSnipeTicker() {
    if (snipeTicker) { clearInterval(snipeTicker); snipeTicker = null; }
  }

  // ── Tracking a snipe ──────────────────────────────────────────────────────
  // Freezes the forecast that justified bidding, at the ASK that matters — the ceiling, not the
  // current bid, because the ceiling is what the seller is actually deciding to spend. The Deal
  // Pipeline grades it against what the flip really made.
  async function trackSnipeRow(itemId, btn) {
    const row = (snipeScan?.candidates || []).find(r => r.itemId === itemId);
    if (!row || !btn) return;

    const original = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Tracking…';

    try {
      const res = await fetch('/api/deals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: row.title,
          stage: 'sourced',
          source: 'ebay_auction',
          sourceLabel: row.buyingOption === 'AUCTION' ? 'eBay auction' : 'eBay Buy It Now',
          sourceUrl: row.url,
          sourceItemId: row.itemId,
          // The ask is the ceiling: bidding to it is the decision being tracked, and the pipeline
          // rebases the projection on whatever is actually paid the moment it's entered.
          askPrice: row.maxBid,
          maxBuyPrice: row.maxBid,
          projectedSalePrice: row.expectedSale ?? row.marketMedian,
          projectedNetProfit: row.profitAtMaxBid,
          projectedRoiPercent: row.maxBid > 0 ? round2(row.profitAtMaxBid / (row.maxBid + row.shippingCost) * 100) : null,
          projectedDaysToCash: row.daysToCash,
          projectedBasis: [
            `${(row.soldCompCount || 0) + (row.terapeakCompCount || 0)} sold comps`,
            row.confidenceLevel,
            row.speedLabel,
            row.buyingOption === 'AUCTION' ? 'at the max bid' : 'Buy It Now',
          ].filter(Boolean).join(' · '),
          note: row.endUtc ? `Closes ${new Date(row.endUtc).toLocaleString()}` : '',
        }),
      });

      if (!res.ok) throw new Error(await res.text());
      pipeline = await res.json();
      renderDashboardPipeline();
      btn.textContent = '✓ Tracked';
      btn.classList.add('fb-arb-tracked');
      setSnipeStatus(`Tracking "${row.title}" — it's on the Deal Pipeline with ${moneyExact(row.maxBid)} as the ceiling you decided on.`);
      addActivity('Snipe tracked', `${row.title} — ${money(row.profitAtMaxBid || 0)} projected at the ceiling`);
    } catch (err) {
      btn.disabled = false;
      btn.textContent = original;
      setSnipeStatus(`Couldn't track that one: ${errorText(err)}`);
    }
  }

  // The dashboard band. Driven entirely by the last scan held in memory — a countdown on the front
  // page must never mean an eBay search on every page load, and a stale clock would be worse than
  // no clock at all.
  function renderDashboardSnipes() {
    const band = $('dash-snipe');
    if (!band) return;

    const s = snipeScan?.summary;
    const live = (snipeScan?.candidates || []).filter(r => r.verdict === 'snipe' && (!r.endUtc || new Date(r.endUtc) > new Date()));
    if (!s || live.length === 0) { band.classList.add('hidden'); return; }

    band.classList.remove('hidden');
    countUpText('dash-snipe-figure', live.reduce((sum, r) => sum + (r.profitAtMaxBid || 0), 0), moneyExact);
    setText('dash-snipe-sub',
      `${live.length} listing${live.length === 1 ? '' : 's'} under market · if you won each at your ceiling`);

    const soonest = live.filter(r => r.endUtc).sort((a, b) => new Date(a.endUtc) - new Date(b.endUtc))[0];
    const host = $('dash-snipe-next');
    if (host) {
      host.innerHTML = soonest
        ? `<span class="dash-pipeline-next-label">Closes in ${esc(snipeClock(soonest.endUtc))}</span><span class="dash-pipeline-next-text">${esc(soonest.title)}</span>`
        : '';
    }
  }

  // ── Promoted Listings: the ad rate that keeps the most money ──────────────
  // eBay's suggested ad rate is worked out from what the rest of the category pays — it has never
  // seen what this seller paid for the item, so on a thin margin it will suggest a rate bigger than
  // the profit and call it a recommendation. Everything below comes from /api/promoted/board, which
  // costs each listing with the same ProfitCalculator + FeeProfile the editor and the sourcing
  // screens use, so the margin an ad rate is judged against is the margin the rest of the app shows.
  let adScan = null;

  function showPromotedSection() {
    hideOverlaySections();
    $('promoted-section')?.classList.remove('hidden');
    setActiveNavItem('promoted');
    markWorkspaceTabOpen('promoted');
    prefillAdRateFromFeeProfile();
  }

  function closePromotedSection() {
    closeWorkspacePage('promoted');
  }

  // ── Listing Copilot ─────────────────────────────────────────────────────────
  // Scan-first, always. This renders the full list of proposed changes and applies nothing on its
  // own; each apply is a separate deliberate click on that action's own button. A bulk edit across
  // a live store that ran on page load would be indistinguishable from an accident.
  let copilotBound = false;
  let copilotScan = null;

  function showCopilotSection() {
    hideOverlaySections();
    $('copilot-section')?.classList.remove('hidden');
    setActiveNavItem('copilot');
    markWorkspaceTabOpen('copilot');
    if (!copilotBound) { bindCopilot(); copilotBound = true; }
    // Put the last run back on screen. The server remembers it; the panel did not, so closing the
    // tab after a rewrite took away the only link to the drafts it had just made. If a run is
    // still going, this picks the polling back up where it left off.
    refreshCopilotSeoStatus().then(() => {
      if (copilotSeoRunning && !copilotSeoPoll) pollCopilotSeo();
    });
  }

  function closeCopilotSection() {
    closeWorkspacePage('copilot');
  }

  function bindCopilot() {
    on('copilot-scan-btn', 'click', runCopilotScan);
    on('copilot-close', 'click', closeCopilotSection);
    on('copilot-home', 'click', goHome);
    on('copilot-seo-apply', 'click', () => runCopilotSeoRewrite([]));
    on('copilot-seo-apply-selected', 'click', () => runCopilotSeoRewrite(selectedCopilotSeoIds()));
    on('copilot-seo-pick', 'click', openCopilotSeoPicker);
    // Clicking the card itself picks listings too. The seller's first move is "I want to rewrite
    // my listings", not "I want to audit my account" — making them find the scan button first was
    // an extra step between them and the thing the card advertises.
    document.querySelector('.copilot-card[data-action="seo"]')
      ?.addEventListener('click', (e) => {
        // Anything already interactive keeps its own behaviour: the two Rewrite buttons, the
        // checkboxes in the picker, the collapse toggle.
        if (e.target.closest('button, input, label, a')) return;
        openCopilotSeoPicker();
      });
    on('copilot-seo-stop', 'click', stopCopilotSeoRewrite);
    on('copilot-seo-all', 'change', () => {
      const on_ = $('copilot-seo-all')?.checked;
      $('copilot-seo-list')?.querySelectorAll('input[type=checkbox]').forEach(c => { c.checked = on_; });
      syncCopilotSeoSelection();
    });
  }

  // Open the picker from one click on the card, scanning first if that hasn't happened yet.
  // The scan is read-only and free (it is what the panel's own footnote promises), so running it
  // on demand costs the seller nothing and saves them a step they should never have had to find.
  async function openCopilotSeoPicker() {
    const wrap = $('copilot-seo-picker');
    if (!copilotScan) {
      const err = $('copilot-error');
      if (err) {
        err.classList.remove('hidden');
        err.innerHTML = '<p class="failure-what">Reading your listings from eBay…</p>';
      }
      await runCopilotScan({ keepNotice: true });
      // runCopilotScan writes its own failure into #copilot-error when it fails; leave that alone.
      if (!copilotScan) return;
      hideFailure(err);
    }
    wrap?.classList.remove('hidden');
    wrap?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }

  // One at a time, or the lot. Listed in full rather than only what the title audit flagged: the
  // pass also rewrites the description and fills item specifics, and a listing with a good title is
  // often the one whose description needs it most.
  function renderCopilotSeoPicker(all) {
    const wrap = $('copilot-seo-picker');
    const list = $('copilot-seo-list');
    if (!wrap || !list) return;

    if (!all.length) { wrap.classList.add('hidden'); return; }
    wrap.classList.remove('hidden');

    list.innerHTML = all.map(l =>
      '<label class="copilot-pick"><input type="checkbox" value="' + esc(l.listingId) + '">' +
      '<span class="copilot-pick-title">' + esc(l.title || '(no title)') + '</span>' +
      (l.needsWork ? '<span class="copilot-pick-flag">title needs work</span>' : '') +
      '</label>').join('');

    list.querySelectorAll('input[type=checkbox]')
        .forEach(c => c.addEventListener('change', syncCopilotSeoSelection));
    syncCopilotSeoSelection();
  }

  function selectedCopilotSeoIds() {
    return [...($('copilot-seo-list')?.querySelectorAll('input[type=checkbox]:checked') || [])]
      .map(c => c.value);
  }

  function syncCopilotSeoSelection() {
    const n = selectedCopilotSeoIds().length;
    setText('copilot-seo-selcount', n + ' selected');
    const btn = $('copilot-seo-apply-selected');
    if (btn) {
      btn.disabled = n === 0;
      btn.textContent = n ? 'Rewrite ' + n + ' selected' : 'Rewrite selected';
    }
  }

  // The AI rewrite: every live listing, rewritten for search - title, subtitle, the full HTML
  // description and the item specifics - and saved as eBay drafts. Started once and polled, because
  // a whole account runs for minutes: holding a fetch open that long loses the completed work, and
  // the seller would have paid for every rewrite and received none of them.
  let copilotSeoPoll = null;
  // Set from the last status read, so reopening the tab can resume polling a live run.
  let copilotSeoRunning = false;
  // Drafts this session has already popped open by itself, so a poll that repeats — or reopening
  // the Copilot tab — cannot open the same rewrite twice.
  const copilotDraftsAutoOpened = new Set();
  // A whole-account run makes eighty-odd drafts. Opening eighty-odd tabs is not "it opened for
  // you", it is a mess to close. Past this the button below does it on request instead.
  const AUTO_OPEN_DRAFT_LIMIT = 10;

  async function runCopilotSeoRewrite(ids) {
    const picked = (ids && ids.length) ? ids : [];
    const count = picked.length || (copilotScan ? copilotScan.scannedListings : 0);

    if (!confirm(
      'Rewrite ' + (count || 'all') + ' listing' + (count === 1 ? '' : 's') + ' with AI?\n\n' +
      'Each gets a new title, a new HTML description and filled-in item specifics, saved as a ' +
      'draft for you to publish.\n\nYour original photos are kept exactly as they are.\n\n' +
      'No live listing is changed. This takes a few minutes and costs one Claude call per listing.')) return;

    hideFailure('copilot-error');
    const { ok, failure } = await callApi('/api/copilot/improve-seo/start', {
      method: 'POST',
      body: { listingIds: picked },  // empty = every live listing
    });

    if (!ok) {
      showCopilotFailure(withEbayHint(failure), () => runCopilotSeoRewrite(ids));
      // Nothing was started, so nothing was paid for — the retry is safe to arm for the moment the
      // app comes back, but it stays a button rather than firing on its own. A rewrite costs money
      // and the seller confirmed this one against a count that may now be stale.
      return;
    }
    pollCopilotSeo();
  }

  // Stop means stop, and says what it really does. The listing in the middle of being rewritten has
  // already been paid for, so it is finished rather than abandoned, and every draft made so far
  // stays. A button that claimed to halt instantly would be lying about both.
  async function stopCopilotSeoRewrite() {
    const btn = $('copilot-seo-stop');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Stopping…'; }

    const { ok, failure } = await callApi('/api/copilot/improve-seo/cancel', { method: 'POST' });
    if (!ok) {
      if (btn) { btn.disabled = false; btn.textContent = 'Stop after this listing'; }
      // The run lives in the app's own process. If the app is gone the run is gone with it, which is
      // the outcome Stop was asking for — say that rather than leaving a button that looks broken.
      showCopilotFailure(
        failure.kind === 'Network'
          ? { ...failure, whatHappened: failure.whatHappened + ' The rewrite ran inside the app, so it has stopped too — every draft it had already made is saved.' }
          : failure,
        stopCopilotSeoRewrite);
      return;
    }
    refreshCopilotSeoStatus();
  }

  function pollCopilotSeo() {
    if (copilotSeoPoll) clearInterval(copilotSeoPoll);
    copilotSeoPoll = setInterval(refreshCopilotSeoStatus, 2500);
    refreshCopilotSeoStatus();
  }

  async function refreshCopilotSeoStatus() {
    const out = $('copilot-seo-result');
    const btn = $('copilot-seo-apply');

    try {
      // A dropped poll is not worth interrupting a run that is still going, so this one stays quiet
      // — but it still goes through the shared layer, which is what notices the app has gone and
      // starts watching for it to come back. The poll then heals itself on the next tick.
      const { ok, data: s } = await callApi('/api/copilot/improve-seo/status');
      if (!ok) return;
      copilotSeoRunning = !!s.running;
      if (!s.everRun) return;

      if (btn) {
        btn.disabled = s.running;
        btn.textContent = s.running
          ? '⏳ Rewriting…'
          : 'Rewrite every listing' + (copilotScan?.scannedListings ? ' (' + copilotScan.scannedListings + ')' : '');
      }
      // Picking listings mid-run would set up a second start the server refuses anyway; the one
      // control that stays live is Stop.
      const selBtn = $('copilot-seo-apply-selected');
      if (selBtn && s.running) selBtn.disabled = true;
      else if (selBtn) syncCopilotSeoSelection();

      const stopBtn = $('copilot-seo-stop');
      if (stopBtn) {
        stopBtn.classList.toggle('hidden', !s.running);
        if (!s.running) { stopBtn.disabled = false; stopBtn.textContent = 'Stop after this listing'; }
        else if (!stopBtn.disabled) stopBtn.textContent = 'Stop after this listing';
      }

      if (!s.running && copilotSeoPoll) { clearInterval(copilotSeoPoll); copilotSeoPoll = null; }

      const pct = s.total ? Math.round((s.done / s.total) * 100) : 0;

      // Where the drafts actually went, rather than where they were expected to go. eBay's draft
      // API is a Limited Release most accounts are not approved for, and when it answers 404 the
      // rewrite lands in the app's own drafts instead. Telling that seller to "publish from eBay
      // Seller Hub" sends them to look for something that was never put there.
      const appDrafts = (s.results || []).filter(r => r.ok && r.draftFile);
      const hubDrafts = (s.results || []).filter(r => r.ok && r.sellerHubUrl);
      const whereText = appDrafts.length && !hubDrafts.length
        ? ' Open them below — they are saved as drafts in this app, ready to review and publish.'
        : hubDrafts.length && !appDrafts.length
          ? ' Publish them from eBay Seller Hub — nothing live was changed.'
          : appDrafts.length
            ? ' Some are in eBay Seller Hub, the rest are drafts in this app — open those below.'
            : ' Nothing live was changed.';

      const head = s.running
        ? '<p class="copilot-clean"><strong>' + s.done + ' of ' + s.total + '</strong> (' + pct + '%) — ' +
          esc(s.stage) + '. ' + s.drafted + ' drafted, ' + s.skipped + ' already good' +
          (s.failed ? ', ' + s.failed + ' failed' : '') + '.</p>'
        : '<p class="copilot-clean"><strong>' + s.drafted + '</strong> draft' + (s.drafted === 1 ? '' : 's') +
          ' created, ' + s.skipped + ' already good' + (s.failed ? ', <strong>' + s.failed + '</strong> failed' : '') +
          '.' + whereText + '</p>' +
          (appDrafts.length
            ? '<p class="copilot-clean"><button type="button" class="btn btn-primary small" id="copilot-seo-open-drafts">' +
              '📄 Open ' + (appDrafts.length === 1 ? 'the draft' : 'all ' + appDrafts.length + ' drafts') +
              '</button></p>'
            : '');

      if (out) {
        out.innerHTML = head +
          '<div class="copilot-bar"><span style="width:' + pct + '%"></span></div>' +
          '<ul class="copilot-list">' + (s.results || []).map(r =>
            r.ok
              ? '<li><span class="copilot-was">' + esc(r.before || '') + '</span>' +
                '<span class="copilot-arrow">→</span>' +
                '<span class="copilot-now">' + esc(r.after || '') + '</span>' +
                (r.note ? '<span class="copilot-issue">' + esc(r.note) + '</span>' : '') +
                copilotChangeSummary(r.changes) +
                // Straight to the rewrite this row is describing, rather than making the seller
                // work out which of N drafts it became.
                (r.draftFile
                  ? '<button type="button" class="btn btn-secondary small copilot-open-draft" ' +
                    'data-draft="' + esc(r.draftFile) + '">Open this draft</button>'
                  : '') +
                (r.sellerHubUrl
                  ? '<a class="copilot-open-draft" href="' + esc(r.sellerHubUrl) + '" target="_blank" ' +
                    'rel="noopener">Open in Seller Hub ↗</a>'
                  : '') + '</li>'
              : '<li><span class="copilot-title">' + esc(r.listingId) + '</span>' +
                '<span class="copilot-issue">' + esc(r.note || 'failed') + '</span></li>'
          ).join('') + '</ul>';

        on('copilot-seo-open-drafts', 'click', () => openCopilotDrafts(appDrafts.map(r => r.draftFile)));

        // The rewrite opens itself. The seller picked the listing and pressed go; making them then
        // find a button to see what they paid for is the step this feature kept being asked for.
        // Only once the run is FINISHED, so tabs do not appear one at a time mid-sweep.
        if (!s.running) {
          const fresh = appDrafts.map(r => r.draftFile).filter(f => f && !copilotDraftsAutoOpened.has(f));
          if (fresh.length && fresh.length <= AUTO_OPEN_DRAFT_LIMIT) {
            fresh.forEach(f => copilotDraftsAutoOpened.add(f));
            openCopilotDrafts(fresh);
          } else {
            // Too many to open unasked — but never offer the same ones again on the next poll.
            fresh.forEach(f => copilotDraftsAutoOpened.add(f));
          }
        }
        out.querySelectorAll('.copilot-open-draft[data-draft]').forEach(b =>
          b.addEventListener('click', () => openCopilotDrafts([b.dataset.draft])));
      }
    } catch { /* a malformed status body must not kill the poll that is tracking a live run */ }
  }

  // The whole change, not just the title. The panel promises the seller the full list of changes,
  // and the title diff above hides the two things that took the most work: the description was
  // replaced and the item specifics were filled in. Collapsed by default — eighty listings with
  // twenty filled specifics each is a wall of text nobody reads, so each row states what happened in
  // one line and opens on demand.
  function copilotChangeSummary(changes) {
    const lines = (changes && changes.lines) || [];
    if (!changes || !lines.length) return '';

    const row = (c) =>
      '<li><span class="copilot-chg-field">' + esc(c.field) + '</span>' +
      (c.kind === 'filled'
        ? '<span class="copilot-now">' + esc(c.after) + '</span>' +
          '<span class="copilot-chg-tag copilot-chg-filled">filled in</span>'
        : c.kind === 'removed'
          ? '<span class="copilot-was">' + esc(c.before) + '</span>' +
            '<span class="copilot-chg-tag copilot-chg-removed">removed</span>'
          : '<span class="copilot-was">' + esc(c.before) + '</span>' +
            '<span class="copilot-arrow">→</span>' +
            '<span class="copilot-now">' + esc(c.after) + '</span>') +
      '</li>';

    return '<details class="copilot-changes">' +
      '<summary>' + esc(changes.headline || 'What changed') + '</summary>' +
      '<ul>' + lines.map(row).join('') +
      (changes.moreCount > 0
        ? '<li class="copilot-more">…and ' + changes.moreCount + ' more — all of it is in the draft</li>'
        : '') +
      '</ul></details>';
  }

  // Open rewritten drafts as tabs in the listing editor — the same tabs the seller already knows
  // from saved drafts, so a rewrite lands somewhere familiar instead of somewhere new.
  // ── A listing's own seller policies ──────────────────────────────────────
  // The three Seller Policies dropdowns were WRITE-ONLY: publish reads them (see the
  // fulfillmentPolicyId/paymentPolicyId/returnPolicyId lines in the outgoing request), and
  // nothing ever read a draft's policies back INTO them. Two consequences, both visible on
  // screen as three empty "- Select policy -" boxes:
  //   * the list itself was never fetched on any route that skips openNewListingModal, so
  //     there was nothing to choose from until the seller found "Reload Policies";
  //   * even once loaded it defaulted to the account defaults from Settings, so a draft made
  //     from a live listing lost the policies that listing was actually published under.
  // Publishing with a blank policy is not a cosmetic problem, so this loads the list from eBay
  // and then selects what the listing itself carries.
  async function applyListingPolicies(data) {
    if (!cachedPolicies && isConnected) await loadPolicies(false);
    fillNlPolicySelects();
    if (!data) return;

    const pick = (selectId, id) => {
      const sel = $(selectId);
      if (!sel || !id) return;
      if (![...sel.options].some(o => o.value === id)) {
        // eBay no longer lists it (renamed, deleted, or a different account). Keep the id rather
        // than silently switching the seller to a policy they did not choose.
        const opt = document.createElement('option');
        opt.value = id;
        opt.textContent = '(on this listing: ' + id + ')';
        sel.insertBefore(opt, sel.children[1] || null);
      }
      sel.value = id;
    };

    pick('nl-fulfillment-sel', data.fulfillmentPolicyId);
    pick('nl-payment-sel',     data.paymentPolicyId);
    pick('nl-return-sel',      data.returnPolicyId);
  }

  // `said` lets a second caller describe its own drafts in the activity feed. The Copilot's are
  // rewrites of live listings; WhatsNot's are lots won an hour ago. Everything else about opening a
  // local draft — the tab, the form, the policies, where the keyboard lands — is identical, and a
  // second copy of it is a second set of bugs.
  async function openCopilotDrafts(filenames, said) {
    const wanted = (filenames || []).filter(Boolean);
    if (!wanted.length) return;

    let opened = 0;
    let lastFailure = null;
    let firstDraftData = null;
    for (const filename of wanted) {
      if (draftTabs.some(t => t.filename === filename)) continue;   // already open
      const { ok, data: draft, failure } = await callApi('/api/local-drafts/load/' + encodeURIComponent(filename));
      if (!ok) { lastFailure = failure; continue; }
      const tab = newDraftTab(draft.title, draft.filename, draft.data,
                              draft.imageBase64, draft.mimeType, draft.visualDescription);
      tab.saved = true;
      opened++;
      if (!firstDraftData) firstDraftData = draft.data;
    }

    if (!opened && !draftTabs.some(t => wanted.includes(t.filename))) {
      // The rewrite is paid for and on disk either way. Which of the two problems this is decides
      // what the seller does next — restart the app, or go and load the drafts by hand.
      toast(lastFailure?.kind === 'Network' ? UNREACHABLE_SENTENCE
            : 'They are still on disk — try Load all drafts.',
            { kind: 'warning', title: 'Could not open the drafts' });
      return;
    }

    const first = draftTabs.find(t => wanted.includes(t.filename));
    if (first) { activeDraftTabId = first.id; loadTabIntoForm(first); }
    renderDraftTabs();
    // Show it the way every other route into this screen does — hide the other overlays, and
    // register the workspace tab up top. Revealing the overlay on its own left the rewrite open
    // underneath the Copilot with no tab in the bar, so there was nothing to click back to.
    hideOverlaySections();
    const overlay = $('new-listing-overlay');
    overlay?.classList.remove('hidden');
    // Reviewing a rewrite is not starting a listing. The top of this screen is the intake block —
    // AI Product Research, Import From URL, Bulk Catalog Import — so opening here dropped the
    // seller on three ways to begin something new, with the draft they had just paid for sitting
    // below the fold. It read as "it opened the AI Listing window instead of my draft".
    overlay?.classList.add('nl-review-draft');
    setActiveNavItem('ai');
    markWorkspaceTabOpen('ai');
    await applyListingPolicies(firstDraftData);
    // Land on the listing itself. rAF so the scroll happens after the form has been filled and
    // laid out, otherwise it measures the old height and lands short.
    requestAnimationFrame(() => {
      overlay?.querySelector('.nl-form-panel')?.scrollIntoView({ block: 'start' });
      $('nl-title')?.focus({ preventScroll: true });
    });
    addActivity(said?.title || `Opened ${wanted.length} rewritten draft${wanted.length === 1 ? '' : 's'}`,
                said?.detail || 'Review the new title, description and item specifics, then publish');
  }

  // Reading a whole account is eBay's bulk listing call plus three policy calls — seconds on a small
  // account, a while on a large one, but bounded. Past this it is not slow, it is not coming.
  const COPILOT_SCAN_TIMEOUT_MS = 3 * 60 * 1000;

  // Every Copilot failure lands in the one red panel, rendered by the shared layer: what happened,
  // what to do about it, the button that does it, and the evidence folded away underneath. This
  // panel is where the old handler pasted the browser's own rejection message straight at the seller,
  // at sellers, which told them nothing and read as "the app is broken".
  function showCopilotFailure(failure, onRetry) {
    renderFailure('copilot-error', failure, { onRetry });
  }

  // An eBay connection the app never had is a trip to Settings, not a retry. The server says so when
  // it can; when all it gave back was a sentence, this reads it and puts the right button underneath.
  function withEbayHint(failure) {
    if (!failure || failure.fixAction) return failure;
    const said = `${failure.whatHappened || ''} ${failure.technical || ''}`;
    if (!/token|auth|sign ?in|connect/i.test(said)) return failure;
    return { ...failure, fixAction: 'connect-ebay', whatToDo: 'Log into eBay, then run the scan again.' };
  }

  async function runCopilotScan(options) {
    const btn = $('copilot-scan-btn');
    const summary = $('copilot-summary');

    // The picker puts its own "reading your listings" note in this panel before calling in, so a
    // scan started from the card still says what it is doing.
    if (!options?.keepNotice) hideFailure('copilot-error');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Reading your account…'; }

    try {
      const { ok, data, failure } = await callApi('/api/copilot/scan', { timeoutMs: COPILOT_SCAN_TIMEOUT_MS });

      if (!ok) {
        copilotScan = null;
        showCopilotFailure(withEbayHint(failure), () => runCopilotScan());
        // When the app itself was the missing piece, the seller restarts it and the scan they asked
        // for runs — rather than them having to find this button a second time.
        if (failure.kind === 'Network') whenBackendReturns(() => runCopilotScan());
        return;
      }

      copilotScan = data;
      renderCopilotScan(data);

      if (summary) {
        summary.classList.remove('hidden');
        summary.innerHTML =
          '<strong>' + data.scannedListings + '</strong> live listings read. ' +
          '<strong>' + data.listingsNeedingWork + '</strong> need work, ' +
          '<strong>' + data.policies.total + '</strong> policies would be renamed. ' +
          '<em>Nothing has been changed.</em>';
      }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🔍 Scan My Account'; }
    }
  }

  function renderCopilotScan(data) {
    // Policies
    const pol = (data.policies.shipping || [])
      .concat(data.policies.payment || [], data.policies.returns || []);
    setText('copilot-policies-count', pol.length ? pol.length + ' to rename' : 'all tidy');
    $('copilot-policies-result').innerHTML = pol.length
      ? '<ul class="copilot-list">' + pol.map(p =>
          '<li><span class="copilot-was">' + esc(p.currentName) + '</span>' +
          '<span class="copilot-arrow">→</span>' +
          '<span class="copilot-now">' + esc(p.proposedName) + '</span></li>').join('') + '</ul>'
      : '<p class="copilot-clean">Every policy name is already consistent.</p>';

    // Categories and titles are split apart so neither action claims credit for the other's
    // findings — the counts on the two cards have to mean what they say.
    // "Not loaded" is a gap in what eBay's bulk call returns, not a fault in the account. Saying
    // so plainly beats reporting every listing as broken, which is what confident-and-wrong looks
    // like from the seller's side.
    const cat = (data.listings || []).filter(l =>
      (l.issues || []).some(i => i.code.indexOf('category_') === 0 && i.code !== 'category_unknown'));
    const unknown = data.categoryUnknown || 0;

    setText('copilot-categories-count',
      cat.length ? cat.length + ' listings' : (unknown ? 'needs a deeper scan' : 'all placed well'));

    $('copilot-categories-result').innerHTML = cat.length
      ? '<ul class="copilot-list">' + cat.slice(0, 25).map(l =>
          '<li><span class="copilot-title">' + esc(l.title || '(no title)') + '</span>' +
          '<span class="copilot-issue">' + esc(
            (l.issues.find(i => i.code.indexOf('category_') === 0) || {}).summary || '') + '</span></li>')
          .join('') + '</ul>' +
        (cat.length > 25 ? '<p class="copilot-more">…and ' + (cat.length - 25) + ' more</p>' : '')
      : unknown
        ? '<p class="copilot-clean">eBay\'s bulk listing call does not return the category, so ' +
          unknown + ' listings could not be judged from this scan. Checking them needs a per-item ' +
          'lookup — not run automatically, because it is one eBay call per listing.</p>'
        : '<p class="copilot-clean">Every listing sits in a real category.</p>';

    const seo = (data.listings || []).filter(l =>
      (l.issues || []).some(i => i.code.indexOf('title_') === 0));
    // The count is every listing that CAN be rewritten, not just the ones whose titles the scan
    // flagged. The rewrite covers description and item specifics too, so "all good" on titles is
    // not "nothing to do here" — and a count of 8 next to a button offering 89 read as a bug.
    setText('copilot-seo-count',
      data.scannedListings ? data.scannedListings + ' listings' : '—');
    $('copilot-seo-result').innerHTML = seo.length
      ? '<ul class="copilot-list">' + seo.slice(0, 25).map(l =>
          '<li><span class="copilot-was">' + esc(l.title || '') + '</span>' +
          (l.tidiedTitle && l.tidiedTitle !== l.title
            ? '<span class="copilot-arrow">→</span><span class="copilot-now">' + esc(l.tidiedTitle) + '</span>'
            : '') +
          '<span class="copilot-issue">' + esc(
            l.issues.filter(i => i.code.indexOf('title_') === 0).map(i => i.summary).join(' · ')) +
          '</span></li>').join('') + '</ul>' +
        (seo.length > 25 ? '<p class="copilot-more">…and ' + (seo.length - 25) + ' more</p>' : '') +
        // Titles are the only part this free scan can judge — eBay's bulk listing call returns no
        // description and no item specifics. Saying so stops the list above reading as the whole
        // job, which is how the card came to look like a title fixer in the first place.
        '<p class="copilot-more">Titles are all this scan can see. The rewrite also replaces the ' +
        'description and fills in the item specifics on every listing you pick — each one lists ' +
        'exactly what it changed once it has run.</p>'
      : '<p class="copilot-clean">Every title already uses its keyword budget well. The rewrite still '
        + 'has work to do on the description and item specifics, which this scan cannot judge from '
        + 'eBay\'s bulk listing call.</p>';

    // Only the AI rewrite has a working apply path today, so only its button comes alive. The
    // other two stay disabled rather than looking clickable and doing nothing.
    // The rewrite runs over the whole account, not just the titles this scan flagged: the pass also
    // rewrites descriptions and fills item specifics, and a listing whose title is already fine is
    // exactly the one whose description most often is not.
    const seoBtn = $('copilot-seo-apply');
    if (seoBtn) {
      seoBtn.disabled = !data.scannedListings;
      seoBtn.textContent = data.scannedListings
        ? 'Rewrite every listing (' + data.scannedListings + ')'
        : 'No listings found';
    }
    renderCopilotSeoPicker(data.allListings || []);
  }

  function bindPromoted() {
    on('ad-scan-btn', 'click', runAdRateScan);
    on('ad-close', 'click', closePromotedSection);
    on('ad-home', 'click', goHome);
    // Filtering is a pure view over the scan already in hand — changing it must never re-run a
    // multi-minute inventory scan.
    on('ad-filter', 'change', renderAdRows);
    on('ad-apply-default', 'click', applyBlendedAdRate);
    on('ad-ladder-close', 'click', () => $('ad-ladder-overlay')?.classList.add('hidden'));
    $('ad-ladder-overlay')?.addEventListener('click', e => {
      if (e.target.id === 'ad-ladder-overlay') $('ad-ladder-overlay').classList.add('hidden');
    });
  }

  // The rate the app already assumes on every net figure it prints, so the board opens comparing
  // against something real rather than against zero.
  async function prefillAdRateFromFeeProfile() {
    const box = $('ad-current-rate');
    if (!box || box.value !== '') return;
    try {
      const fees = await fetch('/api/fees/profile').then(r => r.json());
      box.value = String(Number(fees.promotedListingRatePercent) || 0);
    } catch { /* leave it blank — the server falls back to the same profile anyway */ }
  }

  async function runAdRateScan() {
    const btn = $('ad-scan-btn');
    const maxItems = $('ad-max-items')?.value || '120';
    const rateBox  = $('ad-current-rate')?.value.trim();
    const rateArg  = rateBox === '' ? '' : `&currentRate=${Math.max(0, parseFloat(rateBox) || 0)}`;

    if (btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
    setAdStatus('Reading your live listings and costing each one…');
    $('ad-results').innerHTML = '<p class="opportunity-empty">Pricing every listing against sold comps, then testing each ad rate against its margin — this takes a moment on a large inventory.</p>';

    try {
      const res  = await fetch(`/api/promoted/board?maxItems=${maxItems}${rateArg}`);
      const data = await res.json();
      if (!res.ok) throw new Error(typeof data === 'string' ? data : 'The scan failed.');
      adScan = data;
      renderAdScan();
    } catch (err) {
      adScan = null;
      $('ad-summary')?.classList.add('hidden');
      $('ad-blend-bar')?.classList.add('hidden');
      $('ad-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The scan failed.'))}</p>`;
      setAdStatus('');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '📣 Check My Ad Rates'; }
    }
  }

  function renderAdScan() {
    const warn = $('ad-warning');

    if (adScan.status === 'ebay_unavailable') {
      $('ad-summary')?.classList.add('hidden');
      $('ad-blend-bar')?.classList.add('hidden');
      warn?.classList.add('hidden');
      $('ad-results').innerHTML =
        '<p class="opportunity-empty">Your eBay account isn\'t connected, or the token has expired. Reconnect it in Settings, then check again.</p>';
      setAdStatus('');
      return;
    }

    const s = adScan.summary || {};
    const notes = [];
    if (adScan.dataWarning) notes.push(adScan.dataWarning);
    // A rate can only be sized against a margin, and the margin needs a cost basis. Saying which
    // listings are missing one beats silently advising on a subset.
    const missing = (s.listingsAnalyzed || 0) - (s.withCostBasis || 0);
    if (missing > 0) notes.push(`${missing} listing${missing === 1 ? ' has' : 's have'} no recorded cost, so no ad rate can be sized for ${missing === 1 ? 'it' : 'them'} — add what you paid in Inventory Health or the listing editor.`);

    if (notes.length) { warn.textContent = notes.join(' '); warn.classList.remove('hidden'); }
    else warn?.classList.add('hidden');

    renderAdSummary(s);
    // With nothing sizeable there is nothing in the "worth changing" view, and an empty table over a
    // board full of listings reads as a broken scan. Show the working instead.
    if (!s.advised && $('ad-filter')) $('ad-filter').value = 'all';
    renderAdRows();
    renderAdBlendBar(s);

    setAdStatus(
      `${adScan.itemsAnalyzed} listing${adScan.itemsAnalyzed === 1 ? '' : 's'} of ${adScan.activeListings} active · ` +
      `judged against the ${Number(adScan.comparedRatePercent ?? adScan.defaultRatePercent ?? 0).toFixed(1)}% you said you run today`);
  }

  // Leads with the bill, not the listing count. "You pay $312 in ad fees on one sale of each" is a
  // number a seller reacts to; "48 listings analyzed" is not.
  function renderAdSummary(s) {
    const el = $('ad-summary');
    if (!el) return;

    const delta = Number(s.adFeePerRoundAtRecommended || 0) - Number(s.adFeePerRoundAtCurrent || 0);
    const tiles = [
      { label: 'Ad fees, one sale of each', value: money(s.adFeePerRoundAtCurrent),
        sub: 'At the rate you run today, charged on the whole sale',
        tone: s.adFeePerRoundAtCurrent > 0 ? 'warn' : '' },
      { label: 'At the recommended rates', value: money(s.adFeePerRoundAtRecommended),
        sub: delta === 0 ? 'No change' : `${delta < 0 ? money(Math.abs(delta)) + ' less' : money(delta) + ' more'} per round of sales`,
        tone: delta < 0 ? 'good' : '' },
      { label: 'Spent past what it earns', value: money(s.overspendPerRound),
        sub: `${s.overPromoted || 0} over-promoted · ${s.shouldNotPromote || 0} shouldn't run ads at all`,
        tone: s.overspendPerRound > 0 ? 'bad' : '' },
      { label: 'Extra take-home', value: money(s.netGainPer100),
        sub: 'Per 100 sales of each listing, at the recommended rates',
        tone: s.netGainPer100 > 0 ? 'good' : '' },
      { label: 'Under-promoted', value: String(s.underPromoted || 0),
        sub: 'Margin that can carry a higher rate than it runs', tone: s.underPromoted > 0 ? 'warn' : '' },
      { label: 'Monthly, where known', value: money(s.extraProfitPerMonth),
        sub: s.withSalesHistory ? `Across the ${s.withSalesHistory} listing${s.withSalesHistory === 1 ? '' : 's'} with a sales history` : 'No listing has sold yet, so no monthly figure is honest',
        tone: s.extraProfitPerMonth > 0 ? 'good' : '' },
    ];

    el.innerHTML = tiles.map(t => `
      <div class="inv-tile ${t.tone ? 'inv-tile-' + t.tone : ''}">
        <div class="inv-tile-label">${esc(t.label)}</div>
        <div class="inv-tile-value">${esc(t.value)}</div>
        <div class="inv-tile-sub">${esc(t.sub)}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  // The blended rate is revenue-weighted, so a $1,400 miner's rate counts for more than a $9
  // cable's. Applying it only changes what THIS APP assumes — eBay campaigns are set in Seller Hub,
  // and the button says so rather than implying it pushed anything.
  function renderAdBlendBar(s) {
    const bar = $('ad-blend-bar');
    const note = $('ad-blend-note');
    if (!bar || !note) return;

    if (s.blendedRecommendedPercent == null || !s.advised) { bar.classList.add('hidden'); return; }

    note.textContent =
      `Across the ${s.advised} listing${s.advised === 1 ? '' : 's'} that could be sized, the revenue-weighted answer is ` +
      `${Number(s.blendedRecommendedPercent).toFixed(1)}%. Saving it updates what this app assumes on every net figure — ` +
      `your eBay campaigns are set in Seller Hub → Marketing.`;
    $('ad-apply-default').textContent = `Assume ${Number(s.blendedRecommendedPercent).toFixed(1)}% everywhere`;
    bar.classList.remove('hidden');
  }

  async function applyBlendedAdRate() {
    const rate = Number(adScan?.summary?.blendedRecommendedPercent);
    if (!Number.isFinite(rate)) return;

    const btn = $('ad-apply-default');
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    try {
      // Read-modify-write the whole profile: the endpoint takes a full profile, and posting a bare
      // ad rate would silently zero the shipping, packaging and floor settings alongside it.
      const fees = await fetch('/api/fees/profile').then(r => r.json());
      fees.promotedListingRatePercent = rate;
      const { res, body } = await safePost('/api/fees/profile', fees);
      if (!res.ok) throw new Error(body?.error || 'Save failed.');

      setAdStatus(`Every net figure in the app now assumes ${Number(body.promotedListingRatePercent).toFixed(1)}% of ad spend.`);
      addActivity('Default ad rate updated', `${Number(body.promotedListingRatePercent).toFixed(1)}% — set your real campaign rate in eBay Seller Hub`);
      loadFeeProfile();
      ['nl', 'f'].forEach(p => { if ($(`${p}-th-panel`)) scheduleTakeHome(p); });
    } catch (err) {
      setAdStatus(`Could not save the default rate: ${errorText(err)}`);
    } finally {
      if (btn) { btn.disabled = false; renderAdBlendBar(adScan?.summary || {}); }
    }
  }

  const AD_VERDICTS = {
    under_promoted:  { label: '📈 Raise the rate',   cls: 'ad-v-under' },
    over_promoted:   { label: '💸 Overpaying',       cls: 'ad-v-over' },
    on_target:       { label: '✓ Right where it is', cls: 'ad-v-ok' },
    dont_promote:    { label: '🚫 Do not promote',   cls: 'ad-v-none' },
    no_margin:       { label: '🛑 No margin',        cls: 'inv-v-underwater' },
    fix_price_first: { label: '⚠️ Price first',      cls: 'ad-v-price' },
    no_cost_basis:   { label: '? No cost recorded',  cls: 'inv-v-nodata' },
    no_price:        { label: '? No price',          cls: 'inv-v-nodata' },
  };

  function adFilterMatches(item, filter) {
    switch (filter) {
      case 'change': return item.needsChange || item.verdict === 'no_margin';
      case 'all':    return true;
      default:       return item.verdict === filter;
    }
  }

  function renderAdRows() {
    if (!adScan) return;
    const filter = $('ad-filter')?.value || 'change';
    const rows = (adScan.items || []).filter(i => adFilterMatches(i, filter));
    const el = $('ad-results');

    if (rows.length === 0) {
      const total = (adScan.items || []).length;
      el.innerHTML = `<p class="opportunity-empty">${
        total === 0
          ? 'No live listings came back from eBay to check.'
          : !(adScan.summary?.advised)
            ? 'None of these listings has a recorded cost, so there is no margin to size an ad rate against. Add what you paid — in the listing editor or Inventory Health — and check again.'
          : filter === 'change'
            ? 'Nothing to change — every listing that could be sized is already at the rate its margin supports. Switch to "Everything" to see the working.'
            : 'Nothing matches that filter. Switch to "Everything" to see every listing.'}</p>`;
      return;
    }

    el.innerHTML = `
      <table class="inv-table">
        <thead>
          <tr>
            <th>Listing</th>
            <th class="num">Price</th>
            <th class="num">Net / sale</th>
            <th class="num">Category pays</th>
            <th class="num">You run</th>
            <th class="num">Should run</th>
            <th class="num">Ad fee / sale</th>
            <th class="num">Needs / expects</th>
            <th>Verdict</th>
          </tr>
        </thead>
        <tbody>${rows.map(adRowHtml).join('')}</tbody>
      </table>`;

    el.querySelectorAll('.ad-ladder-btn').forEach(btn =>
      btn.addEventListener('click', () => openAdLadder(btn.dataset.id)));
  }

  function adRowHtml(item) {
    const v = AD_VERDICTS[item.verdict] || AD_VERDICTS.no_price;
    const rec = item.recommendedRatePercent;
    const pct = n => `${Number(n).toFixed(1)}%`;

    // "Needs / expects" is the honest heart of the row: the first number is arithmetic (extra sales
    // the rate must buy to pay for itself), the second is a model. Shown side by side so the seller
    // can see whether the recommendation depends on the model or survives without it.
    const liftCell = rec == null || rec <= 0
      ? '<span class="inv-dash">—</span>'
      : item.breakEvenLiftAtRecommendedPercent == null
        ? '<span class="ad-lift-bad" title="The ad fee is bigger than the profit on the sale">impossible</span>'
        : `<strong>+${pct(item.breakEvenLiftAtRecommendedPercent)}</strong>
           <div class="inv-sub">model expects +${pct(item.modeledLiftAtRecommendedPercent)}</div>`;

    return `
      <tr class="${item.needsChange ? '' : 'wo-row-muted'}">
        <td class="inv-cell-title">
          <div class="inv-title-row">
            ${item.imageUrl ? `<img class="inv-thumb" src="${esc(item.imageUrl)}" alt="" loading="lazy" />` : ''}
            <div>
              ${item.url ? `<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.title)}</a>` : esc(item.title)}
              <div class="inv-sub">${esc(item.categoryLabel || item.category || 'Uncategorised')}${
                item.quantitySold > 0 ? ` · ${item.quantitySold} sold` : ''}${
                item.daysListed != null ? ` · ${item.daysListed}d live` : ''}</div>
            </div>
          </div>
        </td>
        <td class="num">${moneyExact(item.listPrice)}</td>
        <td class="num">${item.netPerSaleNoAds != null
            ? `<span class="${item.netPerSaleNoAds > 0 ? 'inv-gap-good' : 'inv-gap-bad'}">${moneyExact(item.netPerSaleNoAds)}</span>${
                item.marginPercent != null ? `<div class="inv-sub">${Number(item.marginPercent).toFixed(1)}% margin</div>` : ''}`
            : '<span class="inv-dash" title="Record what you paid to size an ad rate against it">—</span>'}</td>
        <td class="num">${pct(item.categoryRatePercent)}<div class="inv-sub">${esc(item.categoryCompetition)}</div></td>
        <td class="num">${pct(item.currentRatePercent)}</td>
        <td class="num inv-cell-suggested">${rec == null
            ? '<span class="inv-dash">—</span>'
            : `<strong class="${rec > item.currentRatePercent ? 'inv-gap-good' : rec < item.currentRatePercent ? 'ad-rate-down' : ''}">${rec <= 0 ? 'none' : pct(rec)}</strong>${
                item.maxSustainableRatePercent != null
                  ? `<div class="inv-sub" title="Above this the ad fee is bigger than the whole profit on the sale">ceiling ${pct(item.maxSustainableRatePercent)}</div>` : ''}`}</td>
        <td class="num">${moneyExact(item.adFeeAtCurrent)}${
            item.adFeeAtRecommended != null && item.adFeeChangePerSale !== 0
              ? `<div class="inv-sub">→ ${moneyExact(item.adFeeAtRecommended)}</div>` : ''}</td>
        <td class="num">${liftCell}</td>
        <td class="inv-cell-verdict">
          <span class="inv-verdict ${v.cls}">${v.label}</span>
          <div class="inv-note">${esc(item.note)}</div>
          ${(item.signals || []).length ? `<div class="inv-signals">${item.signals.map(sig => esc(sig)).join(' ')}</div>` : ''}
          ${(item.ladder || []).length
            ? `<button class="btn btn-secondary small ad-ladder-btn" type="button" data-id="${esc(item.listingId || item.title)}">See the tradeoff</button>` : ''}
        </td>
      </tr>`;
  }

  function adItemById(id) {
    return (adScan?.items || []).find(i => (i.listingId || i.title) === id) || null;
  }

  // Every rate, side by side. This is the screen eBay does not have: what the fee costs, what it
  // has to buy back, and what it is actually worth once both are counted.
  function openAdLadder(id) {
    const item = adItemById(id);
    if (!item) return;

    $('ad-ladder-title').textContent = item.title;
    $('ad-ladder-sub').textContent =
      `${moneyExact(item.grossPerSale)} sale` +
      (item.netPerSaleNoAds != null ? ` · ${moneyExact(item.netPerSaleNoAds)} net before ads` : '') +
      ` · ${item.categoryLabel} typically pays ${Number(item.categoryRatePercent).toFixed(1)}% ` +
      `(${item.categoryCompetition} competition)`;

    const a = item.assumptions || {};
    $('ad-ladder-body').innerHTML = `
      <table class="inv-table ad-ladder-table">
        <thead>
          <tr>
            <th class="num">Ad rate</th>
            <th class="num">Fee per sale</th>
            <th class="num">You keep</th>
            <th class="num">Sales lift needed</th>
            <th class="num">Model expects</th>
            <th class="num">Per 100 sales</th>
            <th class="num">vs no ads</th>
          </tr>
        </thead>
        <tbody>${(item.ladder || []).map(p => adLadderRowHtml(p)).join('')}</tbody>
      </table>
      <p class="ad-assumptions">
        <strong>Sales lift needed</strong> is arithmetic: at this rate you also pay the fee on the
        ${Number(a.cannibalizationPercent || 0).toFixed(0)}% of sales you would have made anyway, so the ads have to
        replace that before they add anything. <strong>Model expects</strong> is an estimate — up to
        ${Number(a.maxLiftPercent || 0).toFixed(0)}% more sales, half of it bought by the
        ${Number(a.halfLiftRatePercent || 0).toFixed(1)}% category rate, with diminishing returns above that.
        ${esc(a.basis || '')} Where the two columns cross is where the rate stops paying for itself.
      </p>`;

    $('ad-ladder-overlay')?.classList.remove('hidden');
  }

  function adLadderRowHtml(p) {
    const cls = [p.isRecommended ? 'ad-rung-best' : '', p.isCurrent ? 'ad-rung-current' : '',
                 p.aboveCeiling ? 'ad-rung-over' : ''].filter(Boolean).join(' ');
    const tag = [p.isRecommended ? '<span class="ad-tag ad-tag-best">best</span>' : '',
                 p.isCurrent ? '<span class="ad-tag">you</span>' : ''].join('');

    return `
      <tr class="${cls}">
        <td class="num"><strong>${p.ratePercent === 0 ? 'No ads' : Number(p.ratePercent).toFixed(1) + '%'}</strong>${tag}</td>
        <td class="num">${moneyExact(p.adFeePerSale)}</td>
        <td class="num">${p.netPerSale != null ? moneyExact(p.netPerSale) : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${p.breakEvenLiftPercent == null
            ? (p.netPerSale == null ? '<span class="inv-dash">—</span>'
               : '<span class="ad-lift-bad">impossible</span>')
            : `+${Number(p.breakEvenLiftPercent).toFixed(1)}%`}</td>
        <td class="num">+${Number(p.modeledLiftPercent).toFixed(1)}%</td>
        <td class="num">${p.netPer100Sales != null ? moneyExact(p.netPer100Sales) : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${p.netChangePer100 == null ? '<span class="inv-dash">—</span>'
            : `<span class="${p.netChangePer100 > 0 ? 'inv-gap-good' : p.netChangePer100 < 0 ? 'inv-gap-bad' : ''}">${
                p.netChangePer100 > 0 ? '+' : ''}${moneyExact(p.netChangePer100)}</span>`}</td>
      </tr>`;
  }

  function setAdStatus(text) {
    const el = $('ad-status');
    if (el) el.textContent = text || '';
  }

  // ── Representative Photo Library ─────────────────────────────────────────
  // Manages photos/<model>/ — the seller's own shots of each used model, taken once and reused
  // (with disclosure) on every identical unit they list. See PhotoLibrary.cs for the server side.
  let plFolders  = [];   // [{ modelKey, imageCount, photos: [url] }] as returned by the API
  let plSelected = '';   // modelKey of the folder currently shown on the right

  function showPhotoLibrarySection() {
    hideOverlaySections();
    $('photo-library-section')?.classList.remove('hidden');
    setActiveNavItem('photos');
    markWorkspaceTabOpen('photos');
    setPlUploadMsg('');
    loadPhotoLibrary();
  }

  function closePhotoLibrarySection() {
    closeWorkspacePage('photos');
  }

  function bindPhotoLibrary() {
    const dropZone  = $('pl-drop-zone');
    const fileInput = $('pl-file-input');

    dropZone?.addEventListener('click', e => {
      if (e.target !== fileInput) fileInput?.click();
    });
    dropZone?.addEventListener('dragover', e => {
      e.preventDefault();
      dropZone.classList.add('drag-over');
    });
    dropZone?.addEventListener('dragleave', e => {
      if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over');
    });
    dropZone?.addEventListener('drop', e => {
      e.preventDefault();
      dropZone.classList.remove('drag-over');
      plUploadFiles(e.dataTransfer.files);
    });
    fileInput?.addEventListener('change', () => {
      plUploadFiles(fileInput.files);
      fileInput.value = '';
    });
    // The zone is contenteditable purely so it can receive a paste — never let it be typed into.
    dropZone?.addEventListener('beforeinput', e => e.preventDefault());
    dropZone?.addEventListener('paste', e => {
      e.preventDefault();
      e.stopPropagation();
      const files = [...(e.clipboardData?.items || [])]
        .filter(i => i.kind === 'file' && i.type.startsWith('image/'))
        .map(i => i.getAsFile())
        .filter(Boolean);
      if (files.length) plUploadFiles(files);
    });

    on('pl-create-btn', 'click', createPhotoFolder);
    on('pl-new-model', 'keydown', e => { if (e.key === 'Enter') createPhotoFolder(); });
    on('pl-refresh', 'click', () => loadPhotoLibrary());
    on('pl-close', 'click', closePhotoLibrarySection);
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && !$('photo-library-section')?.classList.contains('hidden')) closePhotoLibrarySection();
    });
  }

  async function loadPhotoLibrary() {
    const list = $('pl-folder-list');
    try {
      plFolders = await fetch('/api/photos/library').then(r => r.json());
    } catch (err) {
      if (list) list.innerHTML = `<p class="opportunity-empty">Could not load the photo library: ${esc(errorText(err))}</p>`;
      return;
    }
    // Keep the seller on the folder they were working in; fall back to the first one.
    if (!plFolders.some(f => f.modelKey === plSelected)) plSelected = plFolders[0]?.modelKey || '';
    renderPhotoFolders();
    renderPhotoFolderDetail();
  }

  function renderPhotoFolders() {
    const list = $('pl-folder-list');
    if (!list) return;
    if (!plFolders.length) {
      list.innerHTML = '<p class="opportunity-empty">No model folders yet — create one above.</p>';
      return;
    }
    list.innerHTML = plFolders.map(f => `
      <button class="pl-folder${f.modelKey === plSelected ? ' active' : ''}" type="button" data-model="${esc(f.modelKey)}">
        <span class="pl-folder-name">${esc(f.modelKey)}</span>
        <span class="pl-folder-count${f.imageCount ? '' : ' empty'}">${f.imageCount}</span>
      </button>`).join('');
    list.querySelectorAll('.pl-folder').forEach(btn => btn.addEventListener('click', () => {
      plSelected = btn.dataset.model;
      setPlUploadMsg('');
      renderPhotoFolders();
      renderPhotoFolderDetail();
    }));
  }

  function renderPhotoFolderDetail() {
    const folder = plFolders.find(f => f.modelKey === plSelected);
    const title  = $('pl-detail-title');
    const grid   = $('pl-photo-grid');

    $('pl-drop-zone')?.classList.toggle('hidden', !folder);
    if (title) title.textContent = folder ? folder.modelKey : 'Select a model';
    if (!grid) return;

    if (!folder) {
      grid.innerHTML = '<p class="opportunity-empty">Pick a model on the left, or create a new one above.</p>';
      return;
    }
    const photos = folder.photos || [];
    grid.innerHTML = photos.length
      ? photos.map(url => `
        <figure class="pl-photo">
          <img src="${esc(url)}" alt="${esc(folder.modelKey)} representative photo" loading="lazy" data-view="${esc(url)}" />
          <figcaption class="pl-photo-actions">
            <span class="pl-photo-name">${esc(url.split('/').pop())}</span>
            <button class="btn btn-ghost small pl-photo-delete" type="button" data-delete="${esc(url)}">Delete</button>
          </figcaption>
        </figure>`).join('')
      // Borderless: it sits directly under a dashed drop zone, and two dashed
      // rectangles in a column read as two drop targets.
      : stateBlockHtml({
          compact: true,
          inline: true,
          icon: 'i-photos',
          title: 'No photos in this model yet',
          body: 'Drop your own photos of this model above. Every used listing that matches it reuses them, with the representative-photo disclosure, instead of a per-unit shoot.'
        });

    grid.querySelectorAll('[data-view]').forEach(img => img.addEventListener('click', () => showLightbox(img.dataset.view)));
    grid.querySelectorAll('[data-delete]').forEach(btn => btn.addEventListener('click', () => deleteLibraryPhoto(btn.dataset.delete)));
  }

  function setPlUploadMsg(text, kind = '') {
    const el = $('pl-upload-msg');
    if (!el) return;
    el.textContent = text;
    el.className = `sd-test-msg${kind ? ' ' + kind : ''}`;
  }

  async function createPhotoFolder() {
    const input = $('pl-new-model');
    const msg   = $('pl-create-msg');
    const name  = input?.value.trim();
    if (!name) {
      if (msg) { msg.textContent = 'Enter a model name first.'; msg.className = 'sd-test-msg error'; }
      return;
    }
    try {
      const res  = await fetch('/api/photos/library/create', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ modelKey: name })
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body.error || 'Could not create the folder');
      // The server sanitizes the name, so select whatever key it actually created.
      plSelected = body.modelKey;
      if (input) input.value = '';
      if (msg) { msg.textContent = `Created ${body.modelKey}`; msg.className = 'sd-test-msg ok'; }
      addActivity('Photo library folder created', body.modelKey);
      await loadPhotoLibrary();
    } catch (err) {
      if (msg) { msg.textContent = errorText(err); msg.className = 'sd-test-msg error'; }
    }
  }

  // /api/photos/remove-bg writes the cutout to /generated-photos and hands back a URL, but the
  // library upload takes base64 — so pull the cleaned bytes back before saving them to the model.
  async function plRemoveBackground(imageBase64, mimeType) {
    const res  = await fetch('/api/photos/remove-bg', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ imageBase64, mimeType })
    });
    const body = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(body.error || 'Background removal failed');
    const blob = await fetch(body.url).then(r => r.blob());
    return { imageBase64: await blobToBase64(blob), mimeType: blob.type || 'image/png' };
  }

  async function plUploadFiles(fileList) {
    const images = [...(fileList || [])].filter(f => (f.type || '').startsWith('image/'));
    if (!images.length) return;
    if (!plSelected) { setPlUploadMsg('Pick or create a model folder first.', 'error'); return; }

    const model    = plSelected;
    const removeBg = !!$('pl-remove-bg')?.checked;
    let saved = 0;
    const failures = [];

    for (const [i, file] of images.entries()) {
      const label = file.name || 'Pasted photo';
      setPlUploadMsg(`Saving ${i + 1} of ${images.length}${removeBg ? ' — removing background, this takes a few seconds…' : '…'}`);
      try {
        let payload = { imageBase64: await blobToBase64(file), mimeType: file.type || 'image/jpeg' };
        if (removeBg) payload = await plRemoveBackground(payload.imageBase64, payload.mimeType);

        const res  = await fetch('/api/photos/library/upload', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ modelKey: model, ...payload })
        });
        const body = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(body.error || 'Upload failed');
        saved++;
      } catch (err) {
        failures.push(`${label}: ${errorText(err)}`);
      }
    }

    if (saved) addActivity('Representative photos added', `${saved} photo(s) saved to ${model}`);
    await loadPhotoLibrary();
    setPlUploadMsg(
      failures.length ? `Saved ${saved} of ${images.length}. ${failures.join(' · ')}` : `Saved ${saved} photo(s) to ${model}.`,
      failures.length ? 'error' : 'ok');
  }

  async function deleteLibraryPhoto(url) {
    const fileName = url.split('/').pop();
    if (!confirm(`Remove ${fileName} from ${plSelected}?\n\nFuture listings of this model stop using it; already-published listings keep their copy.`)) return;
    try {
      const res  = await fetch('/api/photos/library/delete', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ modelKey: plSelected, fileName })
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body.error || 'Delete failed');
      addActivity('Representative photo deleted', `${plSelected}/${fileName}`);
      await loadPhotoLibrary();
    } catch (err) {
      setPlUploadMsg(`Could not delete ${fileName}: ${errorText(err)}`, 'error');
    }
  }

  function formatEndsIn(iso) {
    if (!iso) return 'Unknown end time';
    const ms = new Date(iso).getTime() - Date.now();
    if (ms <= 0) return 'Ending now';
    const mins = Math.floor(ms / 60000);
    if (mins < 60) return `Ends in ${mins}m`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 48) return `Ends in ${hrs}h ${mins % 60}m`;
    return `Ends in ${Math.floor(hrs / 24)}d`;
  }

  function renderOpportunityStatsCards(data) {
    const grid = $('opp-stats-grid');
    if (!grid) return;

    const pct = (v, withSign) => v == null ? '—' : `${withSign && v > 0 ? '+' : ''}${v}%`;
    const pctClass = v => v == null ? '' : v > 0 ? 'good' : v < 0 ? 'bad' : '';
    const sourceLabel = data.soldSource === 'local_market_data' ? 'Local market research'
      : data.soldSource === 'terapeak' ? 'Terapeak sold comps'
      : data.soldSource === 'marketplace_insights' ? 'eBay sold comps' : 'No sold-comp data';
    const listingLabel = data.listingType === 'FIXED_PRICE' ? 'Fixed price' : data.listingType === 'BOTH' ? 'Auctions + fixed price' : 'Auctions ending soon';

    const best = data.bestOpportunity;
    const bestTag  = best ? 'a' : 'div';
    const bestAttr = best ? `href="${esc(best.url)}" target="_blank" rel="noopener"` : '';
    const bestPrefix = !best ? ''
      : best.sellThroughUnverified ? '⚠ Low confidence — thin data — '
      : best.isVerified ? '✓ Terapeak-matched — ' : '(rough estimate) ';
    const bestNote = best ? `${bestPrefix}${esc(best.title)}` : 'No priced opportunities';

    grid.innerHTML = `
      <${bestTag} class="stat-card" ${bestAttr}>
        <span class="stat-label">Best Opportunity</span>
        <strong class="${pctClass(best?.profitPercent)}">${best ? pct(best.profitPercent, true) : '—'}</strong>
        <span class="stat-note">${bestNote}</span>
      </${bestTag}>
      <div class="stat-card">
        <span class="stat-label">Average Market Price</span>
        <strong>${data.averagePrice > 0 ? `$${data.averagePrice.toFixed(2)}` : '—'}</strong>
        <span class="stat-note">${sourceLabel}</span>
      </div>
      <div class="stat-card">
        <span class="stat-label">Lowest Total Cost</span>
        <strong>${data.lowestPrice != null ? `$${data.lowestPrice.toFixed(2)}` : '—'}</strong>
        <span class="stat-note">Price + shipping, among ${data.count}</span>
      </div>
      <div class="stat-card">
        <span class="stat-label">Active Listings</span>
        <strong>${data.count}</strong>
        <span class="stat-note">${listingLabel}</span>
      </div>
      <div class="stat-card">
        <span class="stat-label">Est. Sell-Through</span>
        <strong>${data.sellThroughPercent != null ? `${data.sellThroughPercent}%` : '—'}</strong>
        <span class="stat-note">${data.sellThroughPercent != null ? 'eBay sell-through rate' : 'Not available for this search'}</span>
      </div>
      <div class="stat-card">
        <span class="stat-label">Avg. Profit Potential</span>
        <strong class="${pctClass(data.avgProfitPercent)}">${pct(data.avgProfitPercent, true)}</strong>
        <span class="stat-note">${data.avgProfitPercent != null ? 'Across priced listings' : 'No sold-comp data'}</span>
      </div>`;
  }

  let lastOpportunityData = null;

  // Shown wherever a row's sell-through couldn't be verified — sold comps with no active listings
  // to divide by, so the rate (and the profit built on it) is a guess, not a measurement.
  const THIN_DATA_TITLE = 'Sell-through could not be verified for this item — too few comparable sold and active listings to measure. Treat the profit estimate as unproven.';

  const OPP_FILTERS = [
    ['opp-filter-underpriced',  it => it.isUnderpriced],
    ['opp-filter-ending-soon',  it => it.isEndingSoon],
    ['opp-filter-poor-titles',  it => it.hasPoorTitle],
    ['opp-filter-misspelled',   it => it.hasMisspelledTitle],
    ['opp-filter-poor-photos',  it => it.hasPoorPhoto],
    ['opp-filter-high-demand',  it => it.isHighDemand],
    ['opp-filter-high-profit',  it => it.isHighProfitMargin],
    ['opp-filter-high-throughput', it => it.isHighThroughput],
    ['opp-filter-newly-listed', it => it.isNewlyListed],
    ['opp-filter-low-competition', it => it.competitionLevel === 'Low'],
    ['opp-filter-exclude-low-confidence', it => (it.confidenceScore ?? 0) >= 40],
    ['opp-filter-exclude-parts-only', it => !(it.warnings || []).some(w => /parts|broken|accessor/i.test(w))],
    ['opp-filter-exclude-no-exact-model', it => (it.scoreReasons || []).some(r => /model|identifier/i.test(r)) || (it.confidenceScore ?? 0) >= 65],
  ];

  // Numeric "at least / at most" filters — a separate array from OPP_FILTERS since these read
  // from number inputs instead of checkboxes.
  const OPP_RANGE_FILTERS = [
    ['opp-min-roi', 'min', it => it.roiPercent],
    ['opp-min-net-profit', 'min', it => it.estimatedProfit],
    ['opp-min-confidence', 'min', it => it.confidenceScore],
    ['opp-min-sell-through', 'min', it => it.sellThroughPercent],
    ['opp-max-days-to-sell', 'max', it => it.estimatedDaysToSell],
  ];

  const OPP_SORTERS = {
    opportunityScore: it => it.opportunityScore ?? -999,
    confidenceScore:  it => it.confidenceScore ?? -1,
    totalProfit:      it => it.estimatedProfit ?? -999999,
    netProfit:        it => it.estimatedProfit ?? -999999,
    roiPercent:       it => it.roiPercent ?? -999,
    sellThroughPercent: it => it.sellThroughPercent ?? -1,
    velocity:         it => it.estimatedMonthlySales ?? -1,
    totalCost:        it => -(it.totalCost ?? 0),
    expectedSalePrice: it => it.estimatedResalePrice ?? -1,
    daysToSell:       it => it.estimatedDaysToSell ?? 999999,
  };

  // Default composite sort: Opportunity Score -> Confidence -> Total profit -> Net profit/unit -> ROI.
  function defaultOpportunitySort(items) {
    return [...items].sort((a, b) =>
      (b.opportunityScore ?? -999) - (a.opportunityScore ?? -999) ||
      (b.confidenceScore ?? -1) - (a.confidenceScore ?? -1) ||
      (b.estimatedProfit ?? -999999) - (a.estimatedProfit ?? -999999) ||
      (b.roiPercent ?? -999) - (a.roiPercent ?? -999));
  }

  function applyOpportunityFilters() {
    if (!lastOpportunityData) return;
    const active = OPP_FILTERS.filter(([id]) => $(id)?.checked);
    let items = active.length
      ? lastOpportunityData.items.filter(it => active.every(([, test]) => test(it)))
      : lastOpportunityData.items;

    for (const [id, kind, getter] of OPP_RANGE_FILTERS) {
      const raw = $(id)?.value;
      if (raw === '' || raw == null) continue;
      const bound = parseFloat(raw);
      if (Number.isNaN(bound)) continue;
      items = items.filter(it => {
        const v = getter(it);
        if (v == null) return false;
        return kind === 'min' ? v >= bound : v <= bound;
      });
    }

    const sortKey = $('opp-sort-select')?.value;
    items = sortKey && OPP_SORTERS[sortKey]
      ? [...items].sort((a, b) => OPP_SORTERS[sortKey](b) - OPP_SORTERS[sortKey](a))
      : defaultOpportunitySort(items);

    renderOpportunityList(items, lastOpportunityData.items.length);
  }

  function renderOpportunityList(items, totalCount) {
    const list = $('opp-results-list');
    if (!list) return;

    if (!items.length) {
      list.innerHTML = `<div class="opp-results-empty">No matching listings right now — try a broader keyword or looser filters.</div>`;
      return;
    }

    const filterNote = items.length < totalCount
      ? `<div class="opp-results-filtered-note">Showing ${items.length} of ${totalCount} listings</div>` : '';

    list.innerHTML = filterNote + items.map(buildOpportunityRowHtml).join('');
    list.querySelectorAll('.opp-details-toggle').forEach(btn =>
      btn.addEventListener('click', () => btn.closest('.opp-result-row')?.querySelector('.opp-result-details')?.classList.toggle('hidden')));
  }

  function confidenceBadgeClass(level) {
    if (!level) return '';
    if (level.startsWith('High')) return 'good';
    if (level.startsWith('Good')) return 'mid-good';
    if (level.startsWith('Limited')) return 'mid';
    return 'bad';
  }

  function buildOpportunityRowHtml(it) {
    const profitClass = it.profitPercent == null ? 'flat' : it.profitPercent > 0 ? 'good' : 'bad';
    const profitPct    = it.profitPercent == null ? '—' : `${it.profitPercent > 0 ? '+' : ''}${it.profitPercent}%`;
    const profitAmount = it.estimatedProfit == null ? '' : ` (${it.estimatedProfit > 0 ? '+' : ''}$${Math.abs(it.estimatedProfit).toFixed(2)})`;
    const isAuction    = it.buyingOption === 'AUCTION';
    const listingLabel = isAuction ? 'Auction' : 'Fixed Price';
    const bidsText     = isAuction ? `${it.bidCount} bid${it.bidCount === 1 ? '' : 's'}` : '—';
    const timeText     = isAuction ? formatEndsIn(it.endDate) : '—';
    // A row whose sell-through couldn't be measured (no active comps to divide by) never gets the
    // green "matched" badge — the profit number rests on thin data, so say so instead of letting it
    // read as a guaranteed flip.
    const verifiedTag  = it.profitPercent == null ? ''
      : it.sellThroughUnverified ? `<span class="opp-verified-tag opp-thin-data" title="${esc(THIN_DATA_TITLE)}">⚠ Low confidence — thin data</span>`
      : it.isVerified ? '<span class="opp-verified-tag opp-verified">✓ Terapeak-matched</span>'
      : '<span class="opp-verified-tag opp-estimate">rough estimate</span>';
    const scoreClass = it.opportunityScore == null ? '' : it.opportunityScore >= 60 ? 'good' : it.opportunityScore >= 35 ? 'mid' : 'bad';
    const scoreText  = it.opportunityScore == null ? '—' : it.opportunityScore;
    const confClass  = confidenceBadgeClass(it.confidenceLevel);
    const money = v => v != null ? `$${v.toFixed(2)}` : '—';

    // Sell-through is the one number on this row that is a share of a whole, so it is the one that
    // can be drawn. A row whose sell-through could not be verified gets the neutral tone rather
    // than the confident green one — the bar must not look more certain than the badge above it.
    const sellThroughMeter = it.sellThroughPercent == null ? '' : `<div class="opp-sth-meter">${vizMeter(it.sellThroughPercent, {
      tone: it.sellThroughUnverified ? 'flat' : undefined,
      valueText: '',
      label: `Sell-through ${it.sellThroughPercent}%`,
      tip: `Sell-through ${it.sellThroughPercent}%\n` + (it.sellThroughUnverified
        ? 'Could not be verified — too few comparable sold and active listings to measure'
        : 'Share of comparable listings that sold rather than sat'),
    })}</div>`;

    const warnings = (it.warnings || []).map(w => `<li class="opp-warning">⚠ ${esc(w)}</li>`).join('');
    const reasons  = (it.scoreReasons || []).map(r => `<li class="opp-reason">✓ ${esc(r)}</li>`).join('');
    const disagreement = it.marketDataDisagreement
      ? `<div class="opp-disagreement">⚠ ${esc(it.disagreementMessage || 'Local and Terapeak pricing disagree — treat with caution.')}</div>` : '';

    return `<div class="opp-result-row">
      <img class="opp-result-thumb" src="${esc(it.imageUrl || '')}" alt="" onerror="this.style.visibility='hidden'">
      <div class="opp-result-info">
        <div class="opp-result-title"><a href="${esc(it.url)}" target="_blank" rel="noopener">${esc(it.title)}</a></div>
        <div class="opp-result-meta">
          <span class="opp-result-listing-type">${listingLabel}</span>
          ${esc(it.sellerUsername || 'Unknown seller')} · ${it.sellerFeedbackScore.toLocaleString()} feedback · ${bidsText} · ${timeText}
        </div>
        <button type="button" class="opp-details-toggle link">Show scoring details ▾</button>
      </div>
      <div class="opp-result-costs">
        <div class="opp-cost-line"><span>Price</span><strong>$${it.price.toFixed(2)}</strong></div>
        <div class="opp-cost-line"><span>Shipping</span><strong>${it.shippingCost > 0 ? `$${it.shippingCost.toFixed(2)}` : 'Free'}</strong></div>
        <div class="opp-cost-line total"><span>Total cost</span><strong>$${it.totalCost.toFixed(2)}</strong></div>
      </div>
      <div class="opp-result-value">
        <div class="opp-cost-line"><span>Market avg</span><strong>${it.marketAverage != null ? `$${it.marketAverage.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Recommended price</span><strong>${money(it.recommendedListingPrice)}</strong></div>
        <div class="opp-cost-line"><span>Net resale</span><strong>${it.estimatedResalePrice != null ? `$${it.estimatedResalePrice.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Sell-through</span><strong>${it.sellThroughPercent != null ? `${it.sellThroughPercent}%` : '—'}</strong></div>
        ${sellThroughMeter}
        <div class="opp-cost-line"><span>ROI</span><strong>${it.roiPercent != null ? `${it.roiPercent}%` : '—'}</strong></div>
        <div class="opp-cost-line profit ${profitClass}"><span>Est. profit</span><strong>${profitPct}${profitAmount}</strong></div>
        ${verifiedTag}
      </div>
      <div class="opp-result-score">
        <div class="opp-score-badge ${scoreClass}">${scoreText}</div>
        <span class="opp-result-score-label">Score</span>
        ${it.confidenceLevel ? `<div class="opp-confidence-badge ${confClass}" title="${esc(it.confidenceLevel)}">${it.confidenceScore}</div><span class="opp-result-score-label">Confidence</span>` : ''}
      </div>
      <div class="opp-result-details hidden">
        ${disagreement}
        <div class="opp-details-grid">
          <div><span>Quick-sale price</span><strong>${money(it.quickSalePrice)}</strong></div>
          <div><span>Expected sale price</span><strong>${money(it.estimatedResalePrice)}</strong></div>
          <div><span>High-price target</span><strong>${money(it.highPriceTarget)}</strong></div>
          <div><span>Break-even price</span><strong>${money(it.breakEvenSalePrice)}</strong></div>
          <div><span>Margin</span><strong>${it.marginPercent != null ? `${it.marginPercent}%` : '—'}</strong></div>
          <div><span>Est. monthly sales</span><strong>${it.estimatedMonthlySales != null ? it.estimatedMonthlySales.toFixed(1) : '—'}</strong></div>
          <div><span>Est. days to sell</span><strong>${it.estimatedDaysToSell ?? '—'}</strong></div>
          <div><span>Price stability</span><strong>${it.priceStabilityScore ?? '—'}/100 (${esc(it.priceTrend || 'Unknown')})</strong></div>
          <div><span>Competition</span><strong>${esc(it.competitionLevel || 'Unknown')} (${it.closeActiveComparableCount ?? 0})</strong></div>
          <div><span>Local / Terapeak comps</span><strong>${it.localComparableCount ?? 0} / ${it.terapeakComparableCount ?? 0}</strong></div>
          <div><span>Source weighting</span><strong>${(it.localWeightPercent ?? 0).toFixed(0)}% local / ${(it.terapeakWeightPercent ?? 0).toFixed(0)}% Terapeak</strong></div>
        </div>
        ${reasons || warnings ? `<ul class="opp-score-explanation">${reasons}${warnings}</ul>` : ''}
        ${/* The same trail the deals board shows, from the same pipeline — one explanation of a
              price, not a second friendlier one on the screen that found it. */''}
        ${priceBasisHtml(it.priceBasis)}
      </div>
    </div>`;
  }

  function renderOpportunityResults(data) {
    const summary = $('opp-results-summary');
    if (!summary) return;

    lastOpportunityData = data;
    renderOpportunityStatsCards(data);

    const valueNote = data.marketValue > 0
      ? `Estimated market value <strong>$${data.marketValue.toFixed(2)}</strong> (${data.soldSource === 'local_market_data' ? 'local market research' : data.soldSource === 'terapeak' ? 'Terapeak sold comps' : 'recent sold comps'})`
      : `No sold-comp data found for this keyword yet — profit % isn't available, but listings are still shown below.`;
    const listingLabel = data.listingType === 'FIXED_PRICE' ? 'fixed-price listings' : data.listingType === 'BOTH' ? 'listings' : 'auctions ending soon';
    const queryLabel = data.query.startsWith('seller:') ? `seller "${esc(data.query.slice(7))}"` : `"${esc(data.query)}"`;
    const illiquidNote = data.excludedIlliquidCount > 0
      ? ` <span class="opp-results-filtered-note">(${data.excludedIlliquidCount} slow/stale-moving result${data.excludedIlliquidCount === 1 ? '' : 's'} hidden — check "Include slow/stale-moving results" to see ${data.excludedIlliquidCount === 1 ? 'it' : 'them'})</span>`
      : '';
    summary.innerHTML = `Found <strong>${data.count}</strong> ${listingLabel} for ${queryLabel}. ${valueNote}${illiquidNote}`;

    applyOpportunityFilters();
    renderUnderpricedCard(data.items || []);
  }

  async function findOpportunities() {
    const q      = $('opp-search-input')?.value.trim();
    const seller = $('opp-seller-input')?.value.trim();
    if (!q && !seller) { $('opp-search-input')?.focus(); return; }
    const category    = $('opp-category-input')?.value.trim();
    const condition   = $('opp-condition-select')?.value;
    const minPrice    = $('opp-min-price-input')?.value;
    const maxPrice    = $('opp-max-price-input')?.value;
    const listingType = $('opp-listing-type-select')?.value || 'AUCTION';
    const includeIlliquid = $('opp-include-illiquid')?.checked;

    const btn   = $('opp-find-btn');
    const results = $('opp-results');
    const summary = $('opp-results-summary');
    const list    = $('opp-results-list');
    const stats   = $('opp-stats-grid');
    if (btn) { btn.disabled = true; btn.textContent = 'Searching…'; }
    results?.classList.remove('hidden');
    if (summary) summary.innerHTML = seller
      ? 'Pulling this seller\'s listings and checking sold comps — verifying the top candidates can take up to a minute…'
      : 'Searching live listings and checking sold comps — verifying the top candidates can take up to a minute…';
    if (list) list.innerHTML = '';
    if (stats) stats.innerHTML = '';
    OPP_FILTERS.forEach(([id]) => { const el = $(id); if (el) el.checked = false; });
    OPP_RANGE_FILTERS.forEach(([id]) => { const el = $(id); if (el) el.value = ''; });

    try {
      const params = new URLSearchParams({ listingType });
      if (q)         params.set('q', q);
      if (seller)    params.set('seller', seller);
      if (category)  params.set('category', category);
      if (condition) params.set('condition', condition);
      if (minPrice)  params.set('minPrice', minPrice);
      if (maxPrice)  params.set('maxPrice', maxPrice);
      if (includeIlliquid) params.set('includeIlliquid', 'true');

      const res = await guardedFetch(`/api/opportunities/search?${params.toString()}`);
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Search failed');
      renderOpportunityResults(data);
    } catch (err) {
      if (summary) summary.textContent = `Search failed: ${errorText(err)}`;
      if (list) list.innerHTML = '';
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🔍 Search'; }
    }
  }

  function bindOpportunitySearch() {
    on('opp-find-btn', 'click', findOpportunities);
    on('opp-search-input',    'keydown', e => { if (e.key === 'Enter') findOpportunities(); });
    on('opp-seller-input',    'keydown', e => { if (e.key === 'Enter') findOpportunities(); });
    on('opp-category-input',  'keydown', e => { if (e.key === 'Enter') findOpportunities(); });
    on('opp-min-price-input', 'keydown', e => { if (e.key === 'Enter') findOpportunities(); });
    on('opp-max-price-input', 'keydown', e => { if (e.key === 'Enter') findOpportunities(); });
    OPP_FILTERS.forEach(([id]) => on(id, 'change', applyOpportunityFilters));
    OPP_RANGE_FILTERS.forEach(([id]) => on(id, 'input', applyOpportunityFilters));
    on('opp-sort-select', 'change', applyOpportunityFilters);
    on('opp-close', 'click', closeOpportunitySection);
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && !$('opportunity-section')?.classList.contains('hidden')) closeOpportunitySection();
    });
  }

  // ── Supplier File Analyzer (dropship profit calculator) ─────────────────
  let oppSupplierImageBase64 = '';
  let oppSupplierMimeType = 'image/jpeg';

  // ── Liquidation Lot / Manifest Analyzer ────────────────────────────────────────────────────
  // Paste a manifest, give the ask, get a buy/skip call. See LotAnalyzer.cs for the recovery
  // assumptions, the exact max-bid solve and every case where it refuses to make a call.
  let lotGrades       = [];
  let lotImageBase64  = '';
  let lotImageMime    = '';
  let lotScan         = null;   // last LotAnalysisResult, kept so re-sorting never re-analyzes

  const LOT_SAMPLE = [
    'Description,Qty,Unit Retail,Condition',
    'DeWalt DCD771C2 20V MAX Cordless Drill Driver Kit,4,169.00,Customer Return',
    'Ninja BL610 Professional 72oz Countertop Blender,6,89.99,Shelf Pull',
    'Sony WH-1000XM4 Wireless Noise Cancelling Headphones,2,348.00,Open Box',
    'Instant Pot Duo 7-in-1 6 Quart Pressure Cooker,5,99.95,Customer Return',
    'Anker PowerCore 10000 Portable Charger,20,25.99,New',
    'Assorted phone cases mixed models,40,19.99,New',
    'Keurig K-Classic K55 Single Serve Coffee Maker,3,129.99,Customer Return',
    'TOTAL,80,4021.55,',
  ].join('\n');

  function showLotsSection() {
    hideOverlaySections();
    $('lots-section')?.classList.remove('hidden');
    setActiveNavItem('lots');
    markWorkspaceTabOpen('lots');
    loadLotGrades();
  }

  function closeLotsSection() {
    closeWorkspacePage('lots');
  }

  function bindLotAnalyzer() {
    on('lot-close', 'click', closeLotsSection);
    on('lot-home',  'click', goHome);
    on('lot-analyze-btn', 'click', runLotAnalysis);
    on('lot-run-btn',     'click', runLotAnalysis);
    on('lot-sample-btn',  'click', () => {
      const box = $('lot-manifest');
      if (box) { box.value = LOT_SAMPLE; box.focus(); }
      if ($('lot-ask') && !parseFloat($('lot-ask').value)) $('lot-ask').value = '650';
      refreshLotCostLine();
    });
    on('lot-grade', 'change', () => applyLotGrade($('lot-grade').value, true));
    on('lot-clear-image', 'click', lotClearImage);

    ['lot-ask', 'lot-premium', 'lot-freight', 'lot-tax'].forEach(id => on(id, 'input', refreshLotCostLine));
    ['lot-grade', 'lot-handling', 'lot-target-roi'].forEach(id => on(id, 'change', saveLotPrefs));

    const zone  = $('lot-drop-zone');
    const input = $('lot-file-input');
    zone?.addEventListener('click', e => { if (e.target !== input) input?.click(); });
    zone?.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('drag-over'); });
    zone?.addEventListener('dragleave', e => { if (!zone.contains(e.relatedTarget)) zone.classList.remove('drag-over'); });
    zone?.addEventListener('drop', e => {
      e.preventDefault();
      zone.classList.remove('drag-over');
      const file = e.dataTransfer?.files?.[0];
      if (file) lotLoadFile(file);
    });
    input?.addEventListener('change', () => { if (input.files[0]) lotLoadFile(input.files[0]); });

    restoreLotPrefs();
    refreshLotCostLine();
  }

  // A CSV or text file is read as text and dropped straight into the paste box, because the
  // deterministic column parser is both free and unable to invent a line that wasn't on the
  // pallet. Only a photo needs the AI path.
  function lotLoadFile(file) {
    const mime = file.type || '';
    const name = (file.name || '').toLowerCase();
    const isText = mime.startsWith('text/') || /\.(csv|tsv|txt)$/.test(name);

    const reader = new FileReader();
    if (isText) {
      reader.onload = ev => {
        const box = $('lot-manifest');
        if (box) box.value = String(ev.target.result || '');
        addActivity('Manifest loaded', file.name || 'Manifest file');
        setLotStatus('Manifest file loaded — set the ask price and analyze.');
      };
      reader.readAsText(file);
      return;
    }
    if (!mime.startsWith('image/')) {
      setLotStatus('That file type can\'t be read. Use a CSV, a text file, or a photo of the manifest.');
      return;
    }
    lotImageMime = mime;
    reader.onload = ev => {
      lotImageBase64 = String(ev.target.result).split(',')[1];
      $('lot-preview-img').src = ev.target.result;
      $('lot-drop-zone')?.classList.add('hidden');
      $('lot-preview-wrap')?.classList.remove('hidden');
      addActivity('Manifest photo loaded', file.name || 'Manifest photo');
    };
    reader.readAsDataURL(file);
  }

  function lotClearImage() {
    lotImageBase64 = '';
    lotImageMime = '';
    $('lot-drop-zone')?.classList.remove('hidden');
    $('lot-preview-wrap')?.classList.add('hidden');
    if ($('lot-file-input')) $('lot-file-input').value = '';
  }

  async function loadLotGrades() {
    if (lotGrades.length) return;
    try {
      const res = await fetch('/api/lots/grades');
      const data = await res.json();
      lotGrades = data.grades || [];
    } catch { lotGrades = []; }

    const sel = $('lot-grade');
    if (!sel || !lotGrades.length) return;
    sel.innerHTML = lotGrades.map(g => `<option value="${esc(g.id)}">${esc(g.label)}</option>`).join('');
    // The grades are listed best-recovery first, so the first option is also the rosiest set of
    // assumptions in the app. Defaulting a pallet tool to that is how it flatters a bad lot, so
    // the default matches the server's: tested customer returns, the honest middle.
    const saved = localStorage.getItem('lotGrade');
    sel.value = saved && lotGrades.some(g => g.id === saved) ? saved
      : (lotGrades.some(g => g.id === 'customer_returns') ? 'customer_returns' : sel.value);
    applyLotGrade(sel.value, true);
  }

  // The two recovery numbers are shown, not hidden in the server — a buyer who has opened forty
  // of these pallets knows their own rate. Changing the grade resets them to that grade's default.
  function applyLotGrade(id, resetOverrides) {
    const grade = lotGrades.find(g => g.id === id);
    if (!grade) return;
    if (resetOverrides) {
      if ($('lot-sellable'))     $('lot-sellable').value     = grade.sellableRatePercent;
      if ($('lot-price-factor')) $('lot-price-factor').value = grade.priceFactorPercent;
    }
    const note = $('lot-grade-note');
    if (note) note.textContent = `${grade.note} Defaults: ${grade.sellableRatePercent}% of units sellable, at ${grade.priceFactorPercent}% of the sold-comp price. Edit either if you know better.`;
  }

  function saveLotPrefs() {
    localStorage.setItem('lotGrade', $('lot-grade')?.value || '');
    localStorage.setItem('lotHandling', $('lot-handling')?.value || '');
    localStorage.setItem('lotTargetRoi', $('lot-target-roi')?.value || '');
  }

  function restoreLotPrefs() {
    const handling = localStorage.getItem('lotHandling');
    const roi = localStorage.getItem('lotTargetRoi');
    if (handling && $('lot-handling')) $('lot-handling').value = handling;
    if (roi && $('lot-target-roi'))    $('lot-target-roi').value = roi;
  }

  function lotNum(id, fallback = 0) {
    const value = parseFloat($(id)?.value);
    return isFinite(value) ? value : fallback;
  }

  // Mirrors LotAnalyzer.CostOf exactly: tax follows the hammer plus the premium (which is how
  // auction houses bill it), freight is invoiced separately.
  function refreshLotCostLine() {
    const ask = Math.max(0, lotNum('lot-ask'));
    const premium = Math.round(ask * Math.max(0, lotNum('lot-premium')) / 100 * 100) / 100;
    const tax = Math.round((ask + premium) * Math.max(0, lotNum('lot-tax')) / 100 * 100) / 100;
    const freight = Math.max(0, lotNum('lot-freight'));
    const total = ask + premium + tax + freight;
    const el = $('lot-cost-line');
    if (!el) return;
    const parts = [];
    if (premium > 0) parts.push(`${moneyExact(premium)} premium`);
    if (tax > 0)     parts.push(`${moneyExact(tax)} tax`);
    if (freight > 0) parts.push(`${moneyExact(freight)} freight`);
    el.innerHTML = `All-in cost: <strong>${moneyExact(total)}</strong>${parts.length ? ` <span class="lot-cost-parts">(${parts.join(' · ')})</span>` : ''}`;
  }

  function setLotStatus(text) {
    const el = $('lot-status');
    if (el) el.textContent = text || '';
  }

  async function runLotAnalysis() {
    const manifest = ($('lot-manifest')?.value || '').trim();
    if (!manifest && !lotImageBase64) {
      setLotStatus('Paste the manifest, or drop a photo of it, first.');
      $('lot-manifest')?.focus();
      return;
    }

    const buttons = ['lot-analyze-btn', 'lot-run-btn'].map(id => $(id)).filter(Boolean);
    buttons.forEach(b => { b.disabled = true; b.textContent = 'Analyzing…'; });
    setLotStatus('Reading the manifest and pricing every line against sold comps…');
    $('lot-results').innerHTML = '<p class="opportunity-empty">Pricing each product against real sold listings. A long manifest takes a minute.</p>';

    const body = {
      manifestText: manifest,
      imageBase64: lotImageBase64 || null,
      mimeType: lotImageMime || 'image/jpeg',
      askPrice: Math.max(0, lotNum('lot-ask')),
      buyerPremiumPercent: Math.max(0, lotNum('lot-premium')),
      freightCost: Math.max(0, lotNum('lot-freight')),
      salesTaxPercent: Math.max(0, lotNum('lot-tax')),
      conditionGrade: $('lot-grade')?.value || 'customer_returns',
      sellableRatePercent: lotNum('lot-sellable', 0) || null,
      conditionPriceFactorPercent: lotNum('lot-price-factor', 0) || null,
      perUnitHandlingCost: Math.max(0, lotNum('lot-handling', 8)),
      targetRoiPercent: Math.max(0, lotNum('lot-target-roi', 40)),
      maxLines: parseInt($('lot-max-lines')?.value || '60', 10),
    };

    try {
      const res = await guardedFetch('/api/lots/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'The analysis failed.');
      lotScan = data;
      renderLot(data);
    } catch (err) {
      lotScan = null;
      ['lot-verdict', 'lot-summary', 'lot-concentration'].forEach(id => $(id)?.classList.add('hidden'));
      $('lot-results').innerHTML = `<p class="opportunity-empty">${esc(errorText(err, 'The analysis failed.'))}</p>`;
      setLotStatus('');
    } finally {
      buttons.forEach(b => { b.disabled = false; });
      if ($('lot-analyze-btn')) $('lot-analyze-btn').textContent = '📦 Analyze This Lot';
      if ($('lot-run-btn'))     $('lot-run-btn').textContent     = '📦 Analyze This Lot';
    }
  }

  const LOT_VERDICTS = {
    buy:       { label: '✅ BUY IT',        cls: 'lot-v-buy' },
    buy_below: { label: '💰 BUY IT LOWER',  cls: 'lot-v-below' },
    thin:      { label: '⚠️ THIN',          cls: 'lot-v-thin' },
    skip:      { label: '⛔ SKIP',          cls: 'lot-v-skip' },
    dead:      { label: '☠️ DEAD LOT',      cls: 'lot-v-skip' },
    no_ask:    { label: '💵 ADD THE ASK',   cls: 'lot-v-thin' },
    no_data:   { label: '❓ CAN’T CALL IT', cls: 'lot-v-nodata' },
  };

  function renderLot(data) {
    const note = $('lot-source-note');
    if (note) note.textContent = data.sourceNote || '';

    const notes = [];
    if (data.error) notes.push(data.error);
    if (data.dataWarning) notes.push(data.dataWarning);
    (data.warnings || []).forEach(w => notes.push(w));
    const warn = $('lot-warning');
    if (notes.length) { warn.textContent = notes.join(' '); warn.classList.remove('hidden'); }
    else warn?.classList.add('hidden');

    renderLotVerdict(data);
    renderLotSummary(data);
    renderLotConcentration(data);
    renderLotRows(data);

    setLotStatus(
      `${data.linesExtracted} line${data.linesExtracted === 1 ? '' : 's'} read · ${data.linesPriced} priced · ` +
      `${data.productsPriced} distinct product${data.productsPriced === 1 ? '' : 's'} looked up` +
      (data.linesExcluded ? ` · ${data.linesExcluded} held out of the totals` : '') +
      (data.terapeakScrapesUsed ? ` · ${data.terapeakScrapesUsed} Terapeak check${data.terapeakScrapesUsed === 1 ? '' : 's'}` : ''));
  }

  function renderLotVerdict(data) {
    const el = $('lot-verdict');
    if (!el) return;
    const v = LOT_VERDICTS[data.verdict] || LOT_VERDICTS.no_data;
    const t = data.totals || {};

    // The two prices worth walking into a negotiation with. Both are exact arithmetic on the
    // manifest, not a rule of thumb — see LotAnalyzer.MaxAsk.
    const chips = [];
    if (data.maxBid != null)
      chips.push(`<span class="lot-chip lot-chip-strong">Pay up to <strong>${moneyExact(data.maxBid)}</strong> for ${Number(data.targetRoiPercent).toFixed(0)}% ROI</span>`);
    if (data.breakEvenAsk != null)
      chips.push(`<span class="lot-chip">Break-even at <strong>${moneyExact(data.breakEvenAsk)}</strong></span>`);
    if (t.totalCost > 0)
      chips.push(`<span class="lot-chip">You'd pay <strong>${moneyExact(t.totalCost)}</strong> all-in</span>`);
    chips.push(`<span class="lot-chip">${Number(data.coveragePercent || 0).toFixed(0)}% of the manifest's value priced</span>`);

    el.className = `lot-verdict ${v.cls}`;
    el.innerHTML = `
      <div class="lot-verdict-head">
        <span class="lot-verdict-badge">${v.label}</span>
        <span class="lot-verdict-net">${t.netProfit != null && (t.totalCost > 0) ? moneyExact(t.netProfit) + ' net' : ''}</span>
      </div>
      <p class="lot-verdict-note">${esc(data.verdictNote || '')}</p>
      <div class="lot-chips">${chips.join('')}</div>`;
    el.classList.remove('hidden');
  }

  function renderLotSummary(data) {
    const el = $('lot-summary');
    if (!el) return;
    const t = data.totals || {};
    const a = data.assumptions || {};

    const tiles = [
      { label: 'Net profit on the lot', value: t.totalCost > 0 ? moneyExact(t.netProfit) : '—',
        sub: t.roiPercent != null ? `${Number(t.roiPercent).toFixed(1)}% ROI · ${t.marginPercent != null ? Number(t.marginPercent).toFixed(0) + '% margin' : ''}` : 'Enter the ask price',
        tone: t.totalCost > 0 ? (t.netProfit > 0 ? 'good' : 'bad') : '' },
      { label: 'What it resells for', value: money(t.grossResale),
        sub: `${Number(t.sellableUnits || 0).toFixed(0)} sellable of ${t.manifestUnits || 0} units on the manifest`, tone: '' },
      { label: 'eBay fees + shipping', value: money((t.estimatedFees || 0) + (t.estimatedShipCost || 0)),
        sub: `${money(t.estimatedFees)} fees · ${money(t.estimatedShipCost)} to ship every unit`, tone: 'warn' },
      { label: 'Clears after selling costs', value: money(t.netRecovery),
        sub: 'Before you pay for the lot', tone: '' },
      { label: 'Cost per sellable unit', value: t.costPerSellableUnit > 0 ? moneyExact(t.costPerSellableUnit) : '—',
        sub: 'What each usable item costs you', tone: '' },
      { label: 'Manifest "retail value"', value: t.manifestRetailTotal > 0 ? money(t.manifestRetailTotal) : '—',
        sub: t.resalePercentOfRetail != null
          ? `Really worth ${Number(t.resalePercentOfRetail).toFixed(0)}% of that on eBay`
          : 'No retail column on this manifest',
        tone: t.resalePercentOfRetail != null && t.resalePercentOfRetail < 40 ? 'warn' : '' },
      { label: 'Time to clear the lot', value: t.daysToSellSlowestLine != null ? `${t.daysToSellSlowestLine}d` : '—',
        sub: t.medianDaysToSell != null ? `Typical line ${t.medianDaysToSell}d · slowest line sets the date` : 'No velocity data',
        tone: t.daysToSellSlowestLine != null && t.daysToSellSlowestLine > 180 ? 'warn' : '' },
      { label: 'Recovery assumed', value: `${Number(a.sellableRatePercent || 0).toFixed(0)}%`,
        sub: `${esc(a.label || '')} · sells at ${Number(a.priceFactorPercent || 0).toFixed(0)}% of comps`, tone: '' },
    ];

    el.innerHTML = tiles.map(t2 => `
      <div class="inv-tile ${t2.tone ? 'inv-tile-' + t2.tone : ''}">
        <div class="inv-tile-label">${esc(t2.label)}</div>
        <div class="inv-tile-value">${esc(t2.value)}</div>
        <div class="inv-tile-sub">${t2.sub}</div>
      </div>`).join('');
    el.classList.remove('hidden');
  }

  function renderLotConcentration(data) {
    const el = $('lot-concentration');
    if (!el) return;
    const c = data.concentration || {};
    if (!c.linesForEightyPercent) { el.classList.add('hidden'); return; }

    const key = (data.items || []).filter(i => i.carriesTheValue).slice(0, 6);
    el.innerHTML = `
      <div class="lot-conc-head">💎 ${c.linesForEightyPercent} line${c.linesForEightyPercent === 1 ? '' : 's'} carry 80% of this lot's value</div>
      ${c.warning ? `<p class="lot-conc-warn">${esc(c.warning)}</p>` : ''}
      <ol class="lot-conc-list">${key.map(i => `
        <li><span class="lot-conc-name">${esc(i.description)}</span>
            <span class="lot-conc-share">${Number(i.valueSharePercent).toFixed(1)}% · ${money(i.netRecovery)}</span></li>`).join('')}</ol>
      <p class="lot-conc-foot">These are the items to physically check before you pay. Everything else on the manifest is padding by value.</p>`;
    el.classList.remove('hidden');
  }

  const LOT_STATUS = {
    priced:   { label: 'Priced',   cls: 'lot-s-priced' },
    thin:     { label: 'Thin data', cls: 'lot-s-thin' },
    excluded: { label: 'Held out', cls: 'lot-s-excluded' },
    no_data:  { label: 'No comps', cls: 'lot-s-nodata' },
  };

  function renderLotRows(data) {
    const el = $('lot-results');
    const rows = data.items || [];
    if (!rows.length) {
      el.innerHTML = '<p class="opportunity-empty">No product lines could be read from that. Paste it as a table (description, quantity, retail), or drop a photo of the manifest.</p>';
      return;
    }

    el.innerHTML = `
      <table class="inv-table lot-table">
        <thead>
          <tr>
            <th>Item</th>
            <th class="num">Qty</th>
            <th class="num">Retail ea.</th>
            <th class="num">Resale ea.</th>
            <th class="num">Sellable</th>
            <th class="num">Clears</th>
            <th class="num">Cost share</th>
            <th class="num">Net</th>
            <th class="num">% of lot</th>
            <th>Evidence</th>
          </tr>
        </thead>
        <tbody>${rows.map(lotRowHtml).join('')}</tbody>
      </table>`;
  }

  function lotRowHtml(item) {
    const s = LOT_STATUS[item.status] || LOT_STATUS.no_data;
    const priced = item.status === 'priced' || item.status === 'thin';
    // "Priced as" is only worth saying when the lookup ran on different words than the line's own —
    // otherwise it implies a match that wasn't made against this exact wording.
    const pricedAs = item.pricedAs && item.pricedAs !== item.description
      ? `<div class="inv-sub">priced as “${esc(item.pricedAs)}”</div>` : '';

    return `
      <tr class="${item.carriesTheValue ? 'lot-row-key' : ''} ${priced ? '' : 'wo-row-muted'}">
        <td class="inv-cell-title">
          <div>${esc(item.description)}${item.carriesTheValue ? ' <span class="lot-key-flag">carries the value</span>' : ''}</div>
          ${pricedAs}
          ${item.condition ? `<div class="inv-sub">${esc(item.condition)}</div>` : ''}
        </td>
        <td class="num">${item.quantity}</td>
        <td class="num">${item.unitRetail != null ? moneyExact(item.unitRetail) : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${item.unitResale != null
            ? `${moneyExact(item.unitResale)}${item.compUnitPrice != null && item.compUnitPrice !== item.unitResale
                ? `<div class="inv-sub">comps ${moneyExact(item.compUnitPrice)}</div>` : ''}`
            : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${priced ? Number(item.sellableUnits).toFixed(1) : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${priced ? money(item.netRecovery) : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${item.allocatedCost > 0 ? money(item.allocatedCost) : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${item.allocatedCost > 0
            ? `<span class="${item.netProfit > 0 ? 'inv-gap-good' : 'inv-gap-bad'}">${money(item.netProfit)}</span>${
                item.roiPercent != null ? `<div class="inv-sub">${Number(item.roiPercent).toFixed(0)}% ROI</div>` : ''}`
            : '<span class="inv-dash">—</span>'}</td>
        <td class="num">${item.valueSharePercent > 0 ? Number(item.valueSharePercent).toFixed(1) + '%' : '<span class="inv-dash">—</span>'}</td>
        <td class="inv-cell-verdict">
          <span class="inv-verdict ${s.cls}">${s.label}</span>
          <div class="inv-note">${esc(item.statusNote || '')}</div>
          ${item.estimatedDaysToSell != null && priced
            ? `<div class="inv-signals">~${item.estimatedDaysToSell}d to clear this line</div>` : ''}
        </td>
      </tr>`;
  }

  function bindSupplierAnalyzer() {
    const dropZone  = $('opp-supplier-drop-zone');
    const fileInput = $('opp-supplier-file-input');

    dropZone?.addEventListener('click', e => {
      if (e.target !== fileInput) fileInput?.click();
    });
    dropZone?.addEventListener('dragover', e => {
      e.preventDefault();
      dropZone.classList.add('drag-over');
    });
    dropZone?.addEventListener('dragleave', e => {
      if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over');
    });
    dropZone?.addEventListener('drop', e => {
      e.preventDefault();
      dropZone.classList.remove('drag-over');
      const file = e.dataTransfer.files[0] ||
        [...(e.dataTransfer.items || [])].find(i => i.kind === 'file' && i.type.startsWith('image/'))?.getAsFile();
      if (file) oppSupplierLoadFile(file);
    });
    fileInput?.addEventListener('change', () => {
      if (fileInput.files[0]) oppSupplierLoadFile(fileInput.files[0]);
    });
    dropZone?.addEventListener('beforeinput', e => e.preventDefault());
    dropZone?.addEventListener('paste', e => {
      e.preventDefault();
      e.stopPropagation();
      const imageItem = [...(e.clipboardData?.items || [])].find(i => i.type.startsWith('image/'));
      const file = imageItem?.getAsFile();
      if (file) oppSupplierLoadFile(file, 'Pasted supplier file');
    });

    on('opp-supplier-btn-clear', 'click', oppSupplierClear);
    on('opp-supplier-btn-reanalyze', 'click', () => oppSupplierAnalyze());
  }

  function oppSupplierLoadFile(file, label = file.name || 'Supplier file') {
    const mime = file.type || 'image/png';
    if (mime && !mime.startsWith('image/')) return;
    oppSupplierMimeType = mime;
    const reader = new FileReader();
    reader.onload = ev => {
      oppSupplierImageBase64 = ev.target.result.split(',')[1];
      $('opp-supplier-preview-img').src = ev.target.result;
      $('opp-supplier-drop-zone')?.classList.add('hidden');
      $('opp-supplier-preview-wrap')?.classList.remove('hidden');
      addActivity('Supplier file loaded', label);
      oppSupplierAnalyze();
    };
    reader.readAsDataURL(file);
  }

  function oppSupplierClear() {
    oppSupplierImageBase64 = '';
    $('opp-supplier-drop-zone')?.classList.remove('hidden');
    $('opp-supplier-preview-wrap')?.classList.add('hidden');
    $('opp-supplier-results')?.classList.add('hidden');
    $('opp-supplier-btn-reanalyze')?.classList.add('hidden');
    if ($('opp-supplier-file-input')) $('opp-supplier-file-input').value = '';
  }

  async function oppSupplierAnalyze() {
    if (!oppSupplierImageBase64) return;
    const results = $('opp-supplier-results');
    const summary = $('opp-supplier-summary');
    const list    = $('opp-supplier-list');
    const reanalyzeBtn = $('opp-supplier-btn-reanalyze');

    results?.classList.remove('hidden');
    if (summary) summary.innerHTML = 'Reading the file and checking sold comps for each product — this can take a minute…';
    if (list) list.innerHTML = '';
    if (reanalyzeBtn) reanalyzeBtn.classList.add('hidden');

    try {
      const res = await guardedFetch('/api/opportunities/analyze-supplier-file', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageBase64: oppSupplierImageBase64, mimeType: oppSupplierMimeType })
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || 'Analysis failed');
      renderSupplierResults(data);
    } catch (err) {
      if (summary) summary.textContent = `Analysis failed: ${errorText(err)}`;
    } finally {
      reanalyzeBtn?.classList.remove('hidden');
    }
  }

  function confidenceLabel(score) {
    if (score == null) return null;
    if (score >= 70) return 'High';
    if (score >= 40) return 'Medium';
    return 'Low';
  }

  function buildComparableRowHtml(c) {
    const titleCell = c.itemUrl
      ? `<a href="${esc(c.itemUrl)}" target="_blank" rel="noopener">${esc(c.title)}</a>`
      : esc(c.title);
    return `<tr>
      <td>${titleCell}</td>
      <td>$${(c.soldPrice ?? 0).toFixed(2)}</td>
      <td>${c.shipping != null ? `$${c.shipping.toFixed(2)}` : '—'}</td>
      <td>${esc(c.condition || '—')}</td>
      <td>${c.soldDate ? esc(new Date(c.soldDate).toLocaleDateString()) : '—'}</td>
      <td>${c.matchScore ?? '—'}</td>
    </tr>`;
  }

  function buildSupplierRowHtml(it, idx) {
    const hasPricing  = it.estimatedProfitPercent != null;
    const profitClass = !hasPricing ? 'flat' : it.estimatedProfitPercent > 0 ? 'good' : 'bad';
    const profitPct    = hasPricing ? `${it.estimatedProfitPercent > 0 ? '+' : ''}${it.estimatedProfitPercent}%` : '—';
    const profitAmount = it.estimatedProfit == null ? '' : ` (${it.estimatedProfit > 0 ? '+' : ''}$${Math.abs(it.estimatedProfit).toFixed(2)})`;
    const resalePrice = it.estimatedResalePrice ?? it.ebaySoldMedian ?? it.ebaySoldAverage;

    // Generic labels only — never mention the underlying database/table/provider.
    let sourceTag;
    if (it.localDataAvailable) {
      const conf = confidenceLabel(it.confidenceScore);
      sourceTag = `<span class="opp-verified-tag opp-verified">✓ Local market research match${conf ? ` · ${conf} confidence` : ''}</span>`;
    } else if (it.isVerified) {
      sourceTag = '<span class="opp-verified-tag opp-verified">✓ Sold-history match</span>';
    } else {
      sourceTag = `<span class="opp-verified-tag opp-estimate">${esc(it.localDataMessage || 'No reliable sold-history matches found.')}</span>`;
    }

    const comparables = it.comparableListings || [];
    const compToggle = comparables.length > 0
      ? `<button type="button" class="btn btn-ghost small opp-comp-toggle" data-comp-idx="${idx}">View comparable sold listings (${comparables.length})</button>`
      : '';
    const compPanel = comparables.length > 0
      ? `<div class="opp-comp-panel hidden" id="opp-comp-panel-${idx}">
          <table class="opp-comp-table">
            <thead><tr><th>Title</th><th>Sold price</th><th>Shipping</th><th>Condition</th><th>Sold date</th><th>Match</th></tr></thead>
            <tbody>${comparables.map(buildComparableRowHtml).join('')}</tbody>
          </table>
        </div>`
      : '';

    return `<div class="opp-result-row opp-supplier-row">
      <div class="opp-result-info">
        <div class="opp-result-title" title="${esc(it.productName)}">${esc(it.productName)}</div>
        <div class="opp-result-meta">${esc(it.notes || it.searchQuery)}</div>
        ${it.localDataAvailable ? `<div class="opp-result-meta">${it.comparableCount} comparable sold listing${it.comparableCount === 1 ? '' : 's'} found in local market research</div>` : ''}
        ${compToggle}
        ${compPanel}
      </div>
      <div class="opp-result-costs">
        <div class="opp-cost-line"><span>Wholesale cost</span><strong>${it.wholesaleCostUsd > 0 ? `$${it.wholesaleCostUsd.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Estimated resale price</span><strong>${resalePrice != null ? `$${resalePrice.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Average sold price</span><strong>${it.ebaySoldAverage != null ? `$${it.ebaySoldAverage.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Median sold price</span><strong>${it.ebaySoldMedian != null ? `$${it.ebaySoldMedian.toFixed(2)}` : '—'}</strong></div>
        ${it.sellThroughPercent != null ? `<div class="opp-cost-line"><span>Sell-through</span><strong>${it.sellThroughPercent}%</strong></div>` : ''}
        ${it.liquidityLevel != null
          ? `<div class="opp-cost-line"><span>Est. time to sell</span><strong>${it.liquidityLevel}${it.estimatedDaysToSell != null ? ` · ~${it.estimatedDaysToSell}d` : ''}</strong></div>`
          : it.liquidityMessage ? `<div class="opp-cost-line"><span>Est. time to sell</span><strong class="opp-liquidity-unknown">${esc(it.liquidityMessage)}</strong></div>` : ''}
      </div>
      <div class="opp-result-value">
        <div class="opp-cost-line"><span>eBay fees (est.)</span><strong>${it.estimatedFees != null ? `$${it.estimatedFees.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Shipping (est.)</span><strong>${it.avgShipping != null ? `$${it.avgShipping.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>Quick-sale / High-price target</span><strong>${it.quickSalePrice != null ? `$${it.quickSalePrice.toFixed(2)}` : '—'} / ${it.highPriceTarget != null ? `$${it.highPriceTarget.toFixed(2)}` : '—'}</strong></div>
        <div class="opp-cost-line"><span>ROI / Margin</span><strong>${it.roiPercent != null ? `${it.roiPercent}%` : '—'} / ${it.marginPercent != null ? `${it.marginPercent}%` : '—'}</strong></div>
        <div class="opp-cost-line profit ${profitClass}"><span>Est. net profit / ROI</span><strong>${profitPct}${profitAmount}</strong></div>
        ${sourceTag}
        ${(it.warnings || []).length > 0 ? `<ul class="opp-score-explanation">${it.warnings.map(w => `<li class="opp-warning">⚠ ${esc(w)}</li>`).join('')}</ul>` : ''}
      </div>
      <div class="opp-result-score">
        ${it.opportunityScore != null ? `<div class="opp-score-badge ${it.opportunityScore >= 60 ? 'good' : it.opportunityScore >= 35 ? 'mid' : 'bad'}">${it.opportunityScore}</div><span class="opp-result-score-label">Score</span>` : ''}
        <a href="${esc(it.terapeakUrl)}" target="_blank" rel="noopener" class="btn btn-ghost small">Research ↗</a>
        <button type="button" class="btn btn-primary small" onclick="window.__oppListSupplierItem(${JSON.stringify(it.productName).replace(/"/g, '&quot;')})">List this</button>
      </div>
    </div>`;
  }

  function renderSupplierResults(data) {
    const summary = $('opp-supplier-summary');
    const list = $('opp-supplier-list');
    if (!summary || !list) return;

    const items = data.items || [];
    if (items.length === 0) {
      summary.innerHTML = 'No products could be extracted from that file. Try a clearer photo of a price list or product.';
      list.innerHTML = '';
      return;
    }

    const priced = data.productsPriced || 0;
    summary.innerHTML = `Extracted <strong>${data.productsExtracted}</strong> product${data.productsExtracted === 1 ? '' : 's'} — ` +
      `<strong>${priced}</strong> priced against real sold comps. Ranked by estimated profit.`;
    list.innerHTML = items.map(buildSupplierRowHtml).join('');

    list.querySelectorAll('.opp-comp-toggle').forEach(btn => {
      btn.addEventListener('click', () => {
        const panel = $(`opp-comp-panel-${btn.dataset.compIdx}`);
        panel?.classList.toggle('hidden');
      });
    });
  }

  // Jumps to AI Listing and reuses the existing quick-fill-by-name pipeline so a profitable
  // supplier find goes straight to a drafted listing without any new listing-creation code.
  window.__oppListSupplierItem = function (productName) {
    navigateTo('ai');
    setTimeout(() => {
      const input = $('nl-quickfill-input');
      if (input) {
        input.value = productName;
        nlQuickFillByName();
      }
    }, 150);
  };

  // Home is now a *switch*, not an exit: it brings the Dashboard tab forward and leaves the
  // screen it was clicked from open on the bar. Closing is what the ✕ is for.
  function goHome() { navigateTo('dashboard'); }

  function bindHomeButtons() {
    on('nl-home',  'click', goHome);
    on('opp-home', 'click', goHome);
    on('pl-home',  'click', goHome);
  }

  async function activateLicensePage() {
    const keyInput = $('lp-key-input');
    const msg      = $('lp-activate-msg');
    const btn      = $('lp-activate-btn');
    const key      = keyInput?.value.trim();
    if (!key) { if (msg) { msg.textContent = 'Enter a license key first.'; msg.className = 'sd-test-msg error'; } return; }

    if (btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
    if (msg) { msg.textContent = 'Contacting license server…'; msg.className = 'sd-test-msg'; }

    try {
      await fetch('/api/setup/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ licenseKey: key })
      });
      const status = await fetch('/api/license/activate', { method: 'POST' }).then(r => r.json());
      updateLicenseUI(status);
      addActivity('License activated', status.message || status.tier);
      if (status.valid && keyInput) { keyInput.value = ''; keyInput.placeholder = '(saved — leave blank to keep)'; }
    } catch (err) {
      if (msg) { msg.textContent = 'Activation failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Activate'; }
    }
  }

  async function buyProLicense(annual = false) {
    const btn = annual ? $('lp-buy-annual-btn') : $('lp-buy-pro-btn');
    const msg = $('lp-buy-msg');
    const endpoint = annual ? '/api/stripe/checkout/annual' : '/api/stripe/checkout';
    const label    = 'Get License Key';
    if (btn) { btn.disabled = true; btn.textContent = 'Opening checkout…'; }
    if (msg) { msg.textContent = ''; }
    try {
      const res = await fetch(endpoint, { method: 'POST' }).then(r => r.json());
      if (res.url) {
        window.open(res.url, '_blank');
        if (msg) { msg.textContent = 'Stripe checkout opened. After payment, check your email for your Pro license key.'; msg.className = 'sd-test-msg ok'; }
      } else {
        if (msg) { msg.textContent = res.error || 'Could not start checkout.'; msg.className = 'sd-test-msg error'; }
      }
    } catch (err) {
      if (msg) { msg.textContent = 'Checkout failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = label; }
    }
  }

  function setViewMode(mode) {
    viewMode = mode;
    localStorage.setItem('ingListingViewMode', mode);
    $('btn-card-view')?.classList.toggle('active', mode === 'cards');
    $('btn-table-view')?.classList.toggle('active', mode === 'table');
    $('btn-card-view')?.setAttribute('aria-pressed', String(mode === 'cards'));
    $('btn-table-view')?.setAttribute('aria-pressed', String(mode === 'table'));
    $('listings-section')?.classList.toggle('table-mode', mode === 'table');
    // The table needs ~1,000px to show twelve columns without a horizontal
    // scrollbar, and the dashboard's two-column grid leaves it ~880. Table
    // view drops the activity rail below the table instead of beside it.
    $('listings-section')?.closest('.content-grid')?.classList.toggle('table-mode', mode === 'table');
  }

  function restoreListingViewMode() {
    const saved = localStorage.getItem('ingListingViewMode');
    setViewMode(saved === 'table' ? 'table' : 'cards');
  }

  async function checkLicenseStatus() {
    try {
      const status = await fetch('/api/license/status').then(r => r.json());
      updateLicenseUI(status);
    } catch { /* non-fatal */ }
  }

  async function checkTrialStatus() {
    // Freeware — always active, hide trial badge, show Freeware badge
    const trialBadge   = $('trial-badge');
    const licenseBadge = $('license-badge');
    if (trialBadge) trialBadge.classList.add('hidden');
    if (licenseBadge) { licenseBadge.textContent = 'Freeware'; licenseBadge.className = 'badge badge-on'; }
    $('license-nag')?.classList.add('hidden');
  }

  function updateLicenseUI(status) {
    const badge = $('license-badge');
    if (!status?.checked) return;

    const dot = $('nav-license-dot');
    if (status.valid) {
      const label = status.tier === 'pro' ? 'Pro License'
                  : status.tier === 'free' ? 'Free License'
                  : 'Licensed';
      if (badge) { badge.textContent = label; badge.className = 'badge badge-on'; }
      if (dot) dot.className = `nav-license-dot ${status.tier === 'unverified' ? 'dot-warn' : 'dot-on'}`;
      $('license-nag')?.classList.add('hidden');
    } else {
      if (badge) { badge.textContent = 'Freeware'; badge.className = 'badge badge-on'; }
      if (dot) dot.className = 'nav-license-dot dot-on';
      $('license-nag')?.classList.add('hidden');
    }
    const activateMsg = $('license-activate-msg');
    if (activateMsg && status.message) {
      activateMsg.textContent = status.message;
      activateMsg.className = 'sd-test-msg ' + (status.valid ? 'ok' : 'error');
    }

    // Update the license page status banner
    const banner    = $('lp-status-banner');
    const tierLabel = $('lp-tier-label');
    const statusMsg = $('lp-status-msg');
    const pageMsg   = $('lp-activate-msg');
    if (banner) {
      banner.className = 'lp-status-banner ' +
        (status.valid ? (status.tier === 'unverified' ? 'lp-unverified' : 'lp-licensed') : 'lp-unlicensed');
    }
    if (tierLabel) {
      tierLabel.textContent = status.valid
        ? (status.tier === 'pro' ? 'Pro License Active' : status.tier === 'free' ? 'Free License Active' : 'License Active (offline)')
        : 'Freeware';
    }
    if (statusMsg) statusMsg.textContent = status.message || (status.valid ? 'Your license is valid.' : 'ING Listing Engine™ is Freeware — use key ING-BETA-2025.');
    if (pageMsg && status.message) {
      pageMsg.textContent = status.message;
      pageMsg.className = 'sd-test-msg ' + (status.valid ? 'ok' : 'error');
    }
  }

  async function activateLicense() {
    const keyInput = $('s-license-key');
    const msg      = $('license-activate-msg');
    const btn      = $('btn-activate-license');
    const key      = keyInput?.value.trim();
    if (!key) { if (msg) { msg.textContent = 'Enter a license key first.'; msg.className = 'sd-test-msg error'; } return; }

    if (btn) { btn.disabled = true; btn.textContent = 'Checking…'; }
    if (msg) { msg.textContent = 'Contacting license server…'; msg.className = 'sd-test-msg'; }

    try {
      // Save key first, then activate
      await fetch('/api/setup/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ licenseKey: key })
      });
      const status = await fetch('/api/license/activate', { method: 'POST' }).then(r => r.json());
      updateLicenseUI(status);
      addActivity('License activated', status.message || status.tier);
      if (status.valid) { if (keyInput) { keyInput.value = ''; keyInput.placeholder = '(saved — leave blank to keep)'; } }
    } catch (err) {
      if (msg) { msg.textContent = 'Activation failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Activate'; }
    }
  }

  async function checkSetupOnLoad() {
    // If returning from the eBay OAuth server relay, show connected state
    const params = new URLSearchParams(location.search);
    if (params.get('ebay_connected') === '1') {
      history.replaceState({}, '', '/');
      updateAuthUI(true);
      // The server records how the sign-in ended, including the endings that are "connected, but":
      // an eBay grant issued without a refresh token works for two hours and then stops.
      const signIn = await fetch('/api/ebay/status').then(r => r.json()).then(s => s.signIn).catch(() => null);
      addActivity('eBay connected', signIn?.message || 'OAuth login completed successfully.');
      showResult(signIn?.code === 'no_refresh_token' ? 'error' : 'ok',
        signIn?.code === 'no_refresh_token'
          ? `${esc(signIn.message)} ${esc(signIn.nextAction)}`
          : '✓ Connected to eBay successfully!');
    } else if (params.get('ebay_error')) {
      history.replaceState({}, '', '/');
      // The code in the URL is for the log; the sentence the seller needs is on the server, which
      // is where it was decided. Falling back to the bare code beats showing nothing.
      const code = params.get('ebay_error');
      const signIn = await fetch('/api/ebay/status').then(r => r.json()).then(s => s.signIn).catch(() => null);
      const detail = signIn && signIn.code === code
        ? `${esc(signIn.message)} ${esc(signIn.nextAction)}`
        : `The sign-in stopped at: ${esc(code)}. Open Settings → eBay and click Connect eBay Account to try again.`;
      addActivity('eBay sign-in failed', detail);
      showResult('error', `eBay sign-in didn't finish. ${detail}`);
    }

    try {
      const status = await fetch('/api/setup/status').then(r => r.json());
      await populateSetupFields(status);
      renderRequiredState(!!status.hasAnthropicKey, !!status.hasBusinessPolicies);
      if (!status.isReadyToList) {
        addActivity('Finish setup', 'Two steps on the home page — your Claude key and your eBay business policies.');
      }
      // No startup pop-up: the home-page "2 steps to activate" checklist handles
      // entering the Claude key and connecting eBay directly on the dashboard.
    } catch {
      addActivity('Setup status unavailable', 'Could not read local credential status.');
    }
  }

  async function populateSetupFields(status) {
    if ($('s-sandbox')) $('s-sandbox').checked = status?.ebaySandbox ?? true;
    try {
      const f = await fetch('/api/setup/fields').then(r => r.json());
      $('s-sandbox').checked = f.ebaySandbox ?? true;
      setValue('s-client-id', f.ebayClientId);
      setValue('s-dev-id',    f.ebayDevId);
      setValue('s-runame',    f.ebayRuName);
      setValue('s-fulfillment', f.ebayFulfillmentPolicyId);
      setValue('s-payment', f.ebayPaymentPolicyId);
      setValue('s-return', f.ebayReturnPolicyId);
      if ($('s-license-key')) $('s-license-key').placeholder = f.hasLicenseKey ? `(saved: ${f.licenseKeyPreview} — leave blank to keep)` : 'ING-FREE-XXXX or ING-PRO-XXXX';
      $('s-anthropic-key').placeholder = f.hasAnthropicKey ? '(saved — leave blank to keep)' : 'sk-ant-...';
      if ($('s-openai-key')) $('s-openai-key').placeholder = f.hasOpenAiKey ? '(saved — leave blank to keep)' : 'sk-...';
      // Image generation is optional and lives in its own strip on the Settings page — nowhere
      // in this modal, so it can never read as a step between a new seller and their first listing.
      const pgMode = computePgImggenMode(f.imageGenMode, f.localSdBackend);
      setVal('pg-imggen-mode', pgMode);
      applyPgImggenVisibility(pgMode);
      setVal('pg-imggen-endpoint', f.localSdEndpoint || 'http://127.0.0.1:7860');
      setModelSelect('pg-imggen-model', f.localSdModelName || '');
      setValue('pg-image-prompt', f.imagePromptTemplate || '');
      renderImageGenState(pgMode);
      $('s-client-secret').placeholder = f.hasEbayClientSecret ? '(saved — leave blank to keep)' : 'PRD-abc123...';
      $('s-user-token').placeholder = f.hasEbayUserToken ? '(saved — leave blank to keep)' : 'AgAAAA...';
      // The eBay developer block hides entirely when the build ships with app credentials — those
      // are ING's keys, not the seller's, and an empty box for them reads as homework.
      const ebayPreconfigured = f.hasEbayClientId && f.hasEbayClientSecret;
      document.getElementById('setup-ebay-developer')?.classList.toggle('hidden', ebayPreconfigured);
      $('btn-paste-token')?.classList.toggle('hidden', ebayPreconfigured);
      const notice = document.getElementById('setup-preconfigured-notice');
      if (ebayPreconfigured && !f.hasAnthropicKey) {
        notice?.classList.remove('hidden');
        if (notice) notice.innerHTML = '<strong>✓ eBay app access is already set up for you.</strong> Step 1 below is the only key you have to fetch yourself.';
      } else {
        notice?.classList.add('hidden');
      }

      renderRequiredState(!!f.hasAnthropicKey, !!f.hasBusinessPolicies);
      // Listing defaults — Settings page
      setVal('pg-default-zip',          f.defaultPostalCode      || '');
      setVal('pg-default-country',      f.defaultCountry         || 'US');
      setVal('pg-default-package-type', f.defaultPackageType     || 'PACKAGE_THICK_ENVELOPE');
      setVal('pg-default-handling',     String(f.defaultHandlingTimeDays || 1));
      setVal('pg-default-weight-lbs',   String(f.defaultWeightLbs  || 0));
      setVal('pg-default-weight-oz',    String(f.defaultWeightOz   || 0));
      setVal('pg-default-length',       String(f.defaultLengthIn   || 0));
      setVal('pg-default-width',        String(f.defaultWidthIn    || 0));
      setVal('pg-default-height',       String(f.defaultHeightIn   || 0));
      setVal('pg-default-fulfillment',  f.defaultFulfillmentPolicyId || '');
      if ($('pg-default-best-offer')) $('pg-default-best-offer').checked = !!f.defaultBestOffer;
      // Show the policy name next to the ID
      if (f.defaultFulfillmentPolicyId) {
        const nameEl = $('pg-default-fulfillment-name');
        if (nameEl) {
          const match = window._ebayPolicies?.fulfillmentPolicies?.find(p => p.id === f.defaultFulfillmentPolicyId);
          if (match) nameEl.textContent = match.name;
        }
      }
    } catch {}
  }

  /**
   * The two required steps, painted wherever they are reported: the numbered cards in the setup
   * modal, the "Required setup" card on the Settings page, and the dashboard checklist. One
   * function so those three can't drift — a green tick on the dashboard over an empty key field
   * in the modal is worse than no tick at all.
   */
  function renderRequiredState(keyDone, policiesDone) {
    hasAnthropicKey     = !!keyDone;
    hasBusinessPolicies = !!policiesDone;

    paintRequiredPill('setup-req-key',      'setup-req-key-state',      hasAnthropicKey,     'Saved', 'Needed');
    paintRequiredPill('setup-req-policies', 'setup-req-policies-state', hasBusinessPolicies, 'Chosen', 'Needed');
    paintRequiredPill('pg-required-key',      'pg-required-key-state',      hasAnthropicKey,     'Saved', 'Needed');
    paintRequiredPill('pg-required-policies', 'pg-required-policies-state', hasBusinessPolicies, 'Chosen', 'Needed');

    updateSetupChecklist(hasAnthropicKey, isConnected, hasBusinessPolicies);
  }

  function paintRequiredPill(rowId, pillId, done, doneText, pendingText) {
    $(rowId)?.classList.toggle('is-done', done);
    const pill = $(pillId);
    if (!pill) return;
    pill.textContent = done ? `✓ ${doneText}` : pendingText;
    pill.classList.toggle('is-done', done);
  }

  // Re-reads the server rather than trusting what was just typed: a save can be partially
  // accepted (a key that saved, policies that didn't), and the pills have to show what's stored.
  async function refreshRequiredState() {
    try {
      const status = await fetch('/api/setup/status').then(r => r.json());
      renderRequiredState(!!status.hasAnthropicKey, !!status.hasBusinessPolicies);
    } catch { /* leave the last known state up rather than blanking it */ }
  }

  // ── Fees & Costs (Settings) ────────────────────────────────────────────────
  // These eleven numbers are the difference between a net profit figure and a guess. They live on
  // the server in one FeeProfile, so saving them re-prices every screen at once — no re-scan, no
  // restart.
  const FEE_FIELDS = {
    'pg-fee-fvf':        'ebayFinalValueFeePercent',
    'pg-fee-fixed':      'ebayFinalValueFeeFixed',
    'pg-fee-promoted':   'promotedListingRatePercent',
    'pg-fee-payment':    'paymentProcessingPercent',
    'pg-fee-shipping':   'defaultShippingCost',
    'pg-fee-packaging':  'defaultPackagingCost',
    'pg-fee-labor':      'defaultLaborCost',
    'pg-fee-returns':    'returnReservePercent',
    'pg-fee-testing':    'testingReservePercent',
    'pg-fee-min-profit': 'minimumNetProfit',
    'pg-fee-min-margin': 'minimumMarginPercent',
  };

  async function loadFeeProfile() {
    if (!$('pg-fee-fvf')) return;
    try {
      const fees = await fetch('/api/fees/profile').then(r => r.json());
      Object.entries(FEE_FIELDS).forEach(([id, key]) => setVal(id, String(fees[key] ?? 0)));
      renderFeeSummary(fees);
    } catch { /* the form keeps its defaults, which are the server's defaults too */ }
  }

  async function saveFeeProfile() {
    const msg = $('pg-fees-msg');
    if (msg) { msg.textContent = 'Saving…'; msg.className = 'sd-test-msg'; }
    try {
      const body = {};
      Object.entries(FEE_FIELDS).forEach(([id, key]) => { body[key] = parseFloat($(id)?.value) || 0; });

      const { res, body: saved } = await safePost('/api/fees/profile', body);
      if (!res.ok) throw new Error(saved?.error || 'Save failed.');

      // Echo back what was stored, not what was typed — the server clamps rates the math can't
      // survive, and the form must show the number actually in force.
      Object.entries(FEE_FIELDS).forEach(([id, key]) => setVal(id, String(saved[key] ?? 0)));
      renderFeeSummary(saved);
      if (msg) { msg.textContent = 'Saved — every price in the app now uses these.'; msg.className = 'sd-test-msg ok'; }
      addActivity('Fees & costs saved', `${Number(saved.revenueFeePercent).toFixed(2)}% of each sale plus fixed costs`);

      // Anything currently open is now quoting stale numbers.
      ['nl', 'f'].forEach(p => { if ($(`${p}-th-panel`)) scheduleTakeHome(p); });
    } catch (err) {
      if (msg) { msg.textContent = 'Save failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    }
  }

  function renderFeeSummary(fees) {
    const el = $('pg-fees-summary');
    if (!el) return;
    const fixed = (Number(fees.defaultShippingCost) || 0) + (Number(fees.defaultPackagingCost) || 0)
                + (Number(fees.defaultLaborCost) || 0) + (Number(fees.ebayFinalValueFeeFixed) || 0);
    const floor = Number(fees.minimumNetProfit) || 0;
    const margin = Number(fees.minimumMarginPercent) || 0;
    el.innerHTML =
      `<strong>${Number(fees.revenueFeePercent || 0).toFixed(2)}%</strong> of every sale, plus
       <strong>${moneyExact(fixed)}</strong> per order. On a ${moneyExact(100)} sale that is
       <strong>${moneyExact((Number(fees.revenueFeePercent) || 0) + fixed)}</strong> gone before
       you count what the item cost. ` +
      (floor > 0 || margin > 0
        ? `You won't be shown an offer worth less than ${floor > 0 ? moneyExact(floor) : ''}${
             floor > 0 && margin > 0 ? ' or ' : ''}${margin > 0 ? margin.toFixed(1) + '% margin' : ''}.`
        : `No profit floor set — the app will only stop you at break-even.`);
  }

  async function saveListingDefaults() {
    const msg = $('pg-defaults-msg');
    if (msg) { msg.textContent = 'Saving…'; msg.className = 'sd-test-msg'; }
    try {
      const body = {
        defaultPostalCode:         $('pg-default-zip')?.value.trim()             || '',
        defaultCountry:            $('pg-default-country')?.value                || 'US',
        defaultPackageType:        $('pg-default-package-type')?.value           || 'PACKAGE_THICK_ENVELOPE',
        defaultHandlingTimeDays:   parseInt($('pg-default-handling')?.value)     || 1,
        defaultWeightLbs:          parseFloat($('pg-default-weight-lbs')?.value) || 0,
        defaultWeightOz:           parseFloat($('pg-default-weight-oz')?.value)  || 0,
        defaultLengthIn:           parseFloat($('pg-default-length')?.value)     || 0,
        defaultWidthIn:            parseFloat($('pg-default-width')?.value)      || 0,
        defaultHeightIn:           parseFloat($('pg-default-height')?.value)     || 0,
        defaultFulfillmentPolicyId: $('pg-default-fulfillment')?.value.trim()   || '',
        defaultBestOffer:           !!$('pg-default-best-offer')?.checked,
      };
      const res = await fetch('/api/setup/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
      });
      if (!res.ok) throw new Error(await res.text());
      if (msg) { msg.textContent = 'Defaults saved.'; msg.className = 'sd-test-msg ok'; }
      addActivity('Listing defaults saved', `ZIP: ${body.defaultPostalCode || '(none)'}`);
    } catch (err) {
      if (msg) { msg.textContent = 'Save failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    }
  }

  function bindSetup() {
    // Token paste modal
    on('btn-paste-token', 'click', () => $('token-overlay')?.classList.remove('hidden'));
    on('btn-close-token',  'click', () => $('token-overlay')?.classList.add('hidden'));
    on('btn-save-token', 'click', async () => {
      const token = $('token-input')?.value.trim();
      const msg   = $('token-msg');
      if (!token) { if (msg) { msg.textContent = 'Paste a token first.'; msg.style.color = 'var(--danger)'; } return; }

      // Detect OAuth redirect URL (contains a code= parameter from inglisting.com)
      // and route to the exchange endpoint instead of saving the raw URL as a token
      const isOAuthRedirect = token.startsWith('https://') && token.includes('code=');
      if (isOAuthRedirect) {
        if (msg) { msg.textContent = 'OAuth redirect URL detected — exchanging for access token...'; msg.style.color = ''; }
        try {
          const res = await fetch('/api/ebay/exchange-redirect-url', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ redirectUrl: token })
          });
          if (!res.ok) {
            let errorText;
            try { const b = await res.json(); errorText = b.error || JSON.stringify(b); } catch { errorText = await res.text(); }
            throw new Error(errorText);
          }
          const result = await res.json();
          updateAuthUI(true);
          $('token-overlay')?.classList.add('hidden');
          $('token-input').value = '';
          addActivity('eBay OAuth connected', result.hasRefreshToken
            ? 'Access token and refresh token saved.'
            : (result.message || 'Access token saved.'));
          loadPolicies(false);
          await loadListings('eBay OAuth connected');
        } catch (err) {
          if (msg) { msg.textContent = `OAuth exchange failed: ${errorText(err)}`; msg.style.color = 'var(--danger)'; }
          addActivity('OAuth exchange failed', errorText(err));
        }
        return;
      }

      // Raw bearer token (e.g. from eBay developer portal)
      if (msg) { msg.textContent = 'Saving…'; msg.style.color = ''; }
      try {
        await fetch('/api/setup/save', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ebayUserToken: token })
        });
        updateAuthUI(true);
        $('token-overlay')?.classList.add('hidden');
        $('token-input').value = '';
        addActivity('eBay connected', 'Bearer token saved successfully.');
        await loadListings('eBay token saved');
      } catch (err) {
        if (msg) { msg.textContent = `Error: ${errorText(err)}`; msg.style.color = 'var(--danger)'; }
      }
    });

    on('s-oauth-redirect-url', 'input', previewOAuthRedirectUrl);
    on('btn-exchange-oauth-redirect', 'click', exchangeOAuthRedirectUrl);
    on('btn-paste-and-connect', 'click', pasteAndConnect);
    on('btn-settings', 'click', () => openSetupWithPolicies(null));
    on('btn-open-credentials', 'click', () => openSetupWithPolicies(null));
    on('btn-activate-license', 'click', activateLicense);
    on('lp-activate-btn',     'click', activateLicensePage);
    on('lp-buy-pro-btn',      'click', () => buyProLicense(false));
    on('lp-buy-annual-btn',   'click', () => buyProLicense(true));
    on('btn-close-setup', 'click', () => $('setup-overlay')?.classList.add('hidden'));
    on('setup-overlay', 'click', e => {
      if (e.target === $('setup-overlay')) $('setup-overlay')?.classList.add('hidden');
    });
    // Escape closes it, like every other overlay here — the modal is now something a seller opens
    // to read as much as to type in, and a screen you can only leave with the mouse is a trap.
    $('setup-overlay')?.addEventListener('keydown', e => {
      if (e.key === 'Escape') $('setup-overlay')?.classList.add('hidden');
    });

    on('btn-connect', 'click', startEbayConnect);

    on('btn-disconnect', 'click', async () => {
      ebayToken = '';
      await fetch('/api/ebay/disconnect', { method: 'POST' });
      cachedListings = [];
      updateAuthUI(false);
      renderListings();
      updateStats();
      addActivity('eBay disconnected', 'Local user token was cleared.');
    });

    on('btn-save-setup', 'click', saveSetup);
    on('btn-load-policies', 'click', () => loadPolicies(true));

    // Sync policy selects → text inputs
    on('s-fulfillment-sel', 'change', () => { const v = $('s-fulfillment-sel')?.value; if (v) set('s-fulfillment', v); });
    on('s-payment-sel',     'change', () => { const v = $('s-payment-sel')?.value;     if (v) set('s-payment',     v); });
    on('s-return-sel',      'change', () => { const v = $('s-return-sel')?.value;      if (v) set('s-return',      v); });

    // An API key is a long opaque string that is easy to paste twice or mistype the end of, and
    // it saves masked, so there has to be a way to look at what you typed. Toggling the input
    // type keeps the value and the label, and aria-pressed says which state the button is in.
    on('s-anthropic-reveal', 'click', () => {
      const input = $('s-anthropic-key');
      const btn   = $('s-anthropic-reveal');
      if (!input || !btn) return;
      const show = input.type === 'password';
      input.type = show ? 'text' : 'password';
      btn.textContent = show ? 'Hide' : 'Show';
      btn.setAttribute('aria-pressed', String(show));
      input.focus();
    });

    // "Set these up separately" has to actually go somewhere, or it's just a sentence.
    on('setup-goto-optional', 'click', () => {
      $('setup-overlay')?.classList.add('hidden');
      navigateTo('settings');
      setTimeout(() => focusSettingsCard('pg-imggen-card'), 400);
    });
  }

  // ── Dashboard setup checklist ──────────────────────────────────────────────
  // Bound here rather than with inline onclick handlers: step 1 has to open the modal *and* land
  // the cursor in the key field, which is the whole difference between "here is a settings screen"
  // and "type your key here".
  function bindSetupChecklist() {
    on('setup-checklist-dismiss', 'click', () => {
      const checklist = $('setup-checklist');
      if (!checklist) return;
      // Recorded, not just hidden: the two optional status calls re-run the visibility check, and
      // a dismissed panel that reappears a second later reads as a bug.
      checklist.dataset.dismissed = '1';
      checklist.classList.add('hidden');
    });
    on('step1-btn', 'click', () => openSetupAt('key'));
    // Step 2 is the eBay login only now — it no longer routes to the policy picker, which lives in
    // Settings -> eBay Seller Policies and in the New Listing form.
    on('step2-btn', 'click', () => { if (!isConnected) $('btn-connect')?.click(); });
    on('setup-extras-btn', 'click', () => {
      navigateTo('settings');
      setTimeout(() => focusSettingsCard('pg-imggen-card'), 400);
    });
    // The same two logins as the Settings strips, connected from where people first look for
    // them. paintFacebookBanner drives both copies off one status call,
    // so connecting here leaves Settings and the Opportunity Finder already correct.
    on('setup-facebook-connect', 'click', facebookConnect);
    on('setup-facebook-disconnect', 'click', facebookDisconnect);
    on('pg-open-required', 'click', () => openSetupAt(hasAnthropicKey ? 'policies' : 'key'));
  }

  function openSetup(status) {
    $('setup-overlay')?.classList.remove('hidden');
    // Connected sellers are here to change a setting, not to log in again — the button says which.
    setText('btn-save-setup', isConnected ? 'Save Settings' : 'Save and Connect eBay');
    if (status) populateSetupFields(status);
    else refreshRequiredState();
  }

  // Opens the modal already scrolled and focused on the step being asked for, so the button that
  // said "Enter Key" leads to a caret in the key box rather than to a screen to search.
  function openSetupWithFocus(step) {
    openSetup(null);
    const card = step === 'policies' ? $('setup-req-policies') : $('setup-req-key');
    setTimeout(() => {
      if (!card) return;
      card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      // The first control that can actually take focus — Load Policies is disabled while it
      // fetches, and focusing a disabled or hidden element silently leaves focus where it was,
      // back on the dashboard button behind the modal.
      const control = [...card.querySelectorAll('input, select, textarea, button')]
        .find(el => !el.disabled && el.offsetParent !== null);
      (control || card).focus();
    }, 120);
  }

  function openSetupAt(step) {
    openSetupWithFocus(step);
    if (isConnected) loadPolicies(false);
  }

  // Brings one of the optional connect strips into view and gives it focus, so arriving from the
  // dashboard or the modal lands on the card that was promised.
  function focusSettingsCard(cardId) {
    const card = $(cardId);
    if (!card) return;
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
    card.classList.add('is-flagged');
    setTimeout(() => card.classList.remove('is-flagged'), 1600);
    card.querySelector('select, input, button')?.focus();
  }

  async function saveSetup() {
    const msg = $('setup-status-msg');
    msg.textContent = 'Saving...';
    msg.className = '';

    const body = {
      licenseKey: $('s-license-key')?.value.trim() || '',
      anthropicApiKey: $('s-anthropic-key').value.trim(),
      openAiApiKey: $('s-openai-key')?.value.trim() || '',
      ebayClientId: $('s-client-id').value.trim(),
      ebayDevId:    $('s-dev-id').value.trim(),
      ebayClientSecret: $('s-client-secret').value.trim(),
      ebayRuName: $('s-runame').value.trim(),
      ebaySandbox: $('s-sandbox').checked,
      ebayFulfillmentPolicyId: $('s-fulfillment').value.trim(),
      ebayPaymentPolicyId: $('s-payment').value.trim(),
      ebayReturnPolicyId: $('s-return').value.trim(),
      ebayUserToken: $('s-user-token').value.trim(),
      // Image generation is saved from its own strip on the Settings page and is deliberately
      // absent here — an omitted field is left untouched by the server (see CredentialsPatch).
    };

    // If the user pasted an OAuth redirect URL into the token field, exchange it first
    const rawToken = body.ebayUserToken || '';
    if (rawToken.startsWith('https://') && rawToken.includes('code=')) {
      msg.textContent = 'OAuth redirect URL detected in token field — exchanging...';
      msg.className = '';
      try {
        const res = await fetch('/api/ebay/exchange-redirect-url', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ redirectUrl: rawToken })
        });
        if (!res.ok) {
          let errText;
          try { const b = await res.json(); errText = b.error || JSON.stringify(b); } catch { errText = await res.text(); }
          throw new Error(errText);
        }
        const result = await res.json();
        msg.textContent = result.hasRefreshToken ? 'Access and refresh tokens saved.' : (result.message || 'Access token saved.');
        msg.className = 'ok';
        updateAuthUI(true);
        addActivity('eBay OAuth connected', msg.textContent);
        setTimeout(() => $('setup-overlay')?.classList.add('hidden'), 700);
        await loadListings('eBay OAuth connected');
      } catch (err) {
        msg.textContent = `OAuth exchange failed: ${errorText(err)}`;
        msg.className = 'error';
        addActivity('OAuth exchange failed', errorText(err));
      }
      return;
    }

    try {
      const res = await fetch('/api/setup/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      if (!res.ok) throw new Error(await res.text());
      const status = await res.json();

      // The key box empties on a successful save so the "(saved)" placeholder is what's left —
      // a field still holding the typed key implies it wasn't stored.
      if (status.hasAnthropicKey && $('s-anthropic-key')) {
        $('s-anthropic-key').value = '';
        $('s-anthropic-key').placeholder = '(saved — leave blank to keep)';
      }
      renderRequiredState(!!status.hasAnthropicKey, !!status.hasBusinessPolicies);

      const hasEbayCreds = status.hasEbayClientId && status.hasEbayClientSecret;
      if (!hasEbayCreds) {
        const missing = [];
        if (!status.hasEbayClientId) missing.push('eBay Client ID');
        if (!status.hasEbayClientSecret) missing.push('eBay Client Secret');
        if (status.ebaySandbox && !status.hasEbayRuName) missing.push('eBay RuName');
        msg.textContent = `Still missing: ${missing.join(', ')}`;
        msg.className = 'error';
        addActivity('Settings incomplete', msg.textContent);
        return;
      }

      const tokenStatus = await fetch('/api/ebay/token-status').then(r => r.json());
      if (tokenStatus.hasToken) {
        msg.textContent = tokenStatus.hasRefreshToken
          ? 'Saved. eBay access and refresh tokens are active.'
          : 'Saved. eBay access token is active.';
        msg.className = 'ok';
        updateAuthUI(true);
        addActivity('Settings saved', 'eBay token is active.');
        setTimeout(() => $('setup-overlay')?.classList.add('hidden'), 700);
      } else {
        msg.textContent = 'Saved. Redirecting to eBay login...';
        msg.className = 'ok';
        addActivity('Settings saved', 'Starting eBay OAuth login.');
        setTimeout(async () => {
          // Not "await ... .url" straight into location.href: when the URL can't be built the
          // server answers with the reason, and navigating to `undefined` showed the seller a 404
          // for a problem that had already been diagnosed one line earlier.
          const body = await fetch('/api/ebay/auth-url').then(r => r.json()).catch(() => null);
          if (!body?.url) {
            msg.textContent = body?.error
              ? `${body.error} ${body.nextAction || ''}`
              : 'Saved, but the eBay sign-in URL could not be built.';
            msg.className = 'error';
            addActivity('eBay sign-in not started', msg.textContent);
            return;
          }
          $('setup-overlay')?.classList.add('hidden');
          window.location.href = body.url;
        }, 700);
      }
    } catch (err) {
      msg.textContent = `Error: ${errorText(err)}`;
      msg.className = 'error';
      addActivity('Settings error', errorText(err));
    }
  }

  async function loadPolicies(userTriggered = false) {
    const msg = $('policy-load-msg');
    const btn = $('btn-load-policies');
    if (msg) { msg.textContent = 'Loading…'; msg.className = 'sd-test-msg'; }
    if (btn) btn.disabled = true;

    try {
      const res  = await fetch('/api/ebay/policies');
      const data = await res.json();

      if (!res.ok) {
        const errText = data.error || 'Failed to load policies';
        if (msg) { msg.textContent = errText; msg.className = 'sd-test-msg error'; }
        if (userTriggered) addActivity('Policy load failed', errText);
        return;
      }

      const { fulfillmentPolicies = [], paymentPolicies = [], returnPolicies = [], error } = data;
      const total = fulfillmentPolicies.length + paymentPolicies.length + returnPolicies.length;

      if (total === 0) {
        const noPolMsg = 'No eBay business policies found. Create them in Seller Hub first.';
        if (msg) { msg.textContent = noPolMsg; msg.className = 'sd-test-msg error'; }
        return;
      }

      cachedPolicies = { fulfillmentPolicies, paymentPolicies, returnPolicies };

      populatePolicySelect('s-fulfillment-sel', fulfillmentPolicies, $('s-fulfillment')?.value);
      populatePolicySelect('s-payment-sel',     paymentPolicies,     $('s-payment')?.value);
      populatePolicySelect('s-return-sel',      returnPolicies,      $('s-return')?.value);

      $('policy-selects')?.classList.remove('hidden');
      fillNlPolicySelects();

      const warnText = error ? ' (some policies may be missing: ' + error + ')' : '';
      if (msg) {
        msg.textContent = fulfillmentPolicies.length + ' fulfillment, ' + paymentPolicies.length + ' payment, ' + returnPolicies.length + ' return policies loaded' + warnText;
        msg.className = 'sd-test-msg ok';
      }
      if (userTriggered) addActivity('eBay policies loaded', total + ' policies found');
      const nlMsg = $('nl-policy-msg');
      if (nlMsg) { nlMsg.textContent = ''; nlMsg.className = 'sd-test-msg'; }
    } catch (err) {
      if (msg) { msg.textContent = 'Error: ' + errorText(err); msg.className = 'sd-test-msg error'; }
      const nlMsg = $('nl-policy-msg');
      if (nlMsg) { nlMsg.textContent = 'Error: ' + errorText(err); nlMsg.className = 'sd-test-msg error'; }
      if (userTriggered) addActivity('Policy load error', errorText(err));
    } finally {
      if (btn) btn.disabled = false;
    }
  }

  function populatePolicySelect(selectId, policies, currentId) {
    const sel = $(selectId);
    if (!sel) return;

    sel.innerHTML = '<option value="">— Select policy —</option>';
    let matched = false;
    policies.forEach(p => {
      const opt = document.createElement('option');
      opt.value = p.id;
      opt.textContent = p.name + ' (' + p.id + ')';
      if (p.id === currentId) { opt.selected = true; matched = true; }
      sel.appendChild(opt);
    });

    // If current saved ID isn't in the list, add it as a placeholder so it's not lost
    if (currentId && !matched) {
      const opt = document.createElement('option');
      opt.value = currentId;
      opt.textContent = '(saved: ' + currentId + ')';
      opt.selected = true;
      sel.insertBefore(opt, sel.children[1]);
    }

    // Sync the text input to match whatever is selected
    const selVal = sel.value;
    const inputMap = { 's-fulfillment-sel': 's-fulfillment', 's-payment-sel': 's-payment', 's-return-sel': 's-return' };
    if (selVal && inputMap[selectId]) set(inputMap[selectId], selVal);
  }

  function fillNlPolicySelects() {
    if (!cachedPolicies) return;
    fillNlPolicySelect('nl-fulfillment-sel', cachedPolicies.fulfillmentPolicies, $('s-fulfillment')?.value || '');
    fillNlPolicySelect('nl-payment-sel',     cachedPolicies.paymentPolicies,     $('s-payment')?.value     || '');
    fillNlPolicySelect('nl-return-sel',      cachedPolicies.returnPolicies,      $('s-return')?.value      || '');
    const msg = $('nl-policy-msg');
    if (msg) { msg.textContent = ''; msg.className = 'sd-test-msg'; }
  }

  function fillNlPolicySelect(selectId, policies, savedId) {
    const sel = $(selectId);
    if (!sel) return;
    const current = sel.value; // preserve user's current pick across refreshes
    const activeId = current || savedId;
    sel.innerHTML = '<option value="">— Select policy —</option>';
    let matched = false;
    policies.forEach(p => {
      const opt = document.createElement('option');
      opt.value = p.id;
      opt.textContent = p.name + ' (' + p.id + ')';
      if (p.id === activeId) { opt.selected = true; matched = true; }
      sel.appendChild(opt);
    });
    if (activeId && !matched) {
      const opt = document.createElement('option');
      opt.value = activeId;
      opt.textContent = '(saved: ' + activeId + ')';
      opt.selected = true;
      sel.insertBefore(opt, sel.children[1]);
    }
  }

  function previewOAuthRedirectUrl() {
    const msg = $('oauth-redirect-msg');
    if (!msg) return;

    const raw = $('s-oauth-redirect-url')?.value.trim();
    if (!raw) {
      msg.textContent = '';
      msg.className = '';
      return;
    }

    try {
      const details = parseOAuthRedirectUrl(raw);
      msg.textContent = `Code detected${details.state ? `; state: ${details.state}` : ''}.`;
      msg.className = 'ok';
    } catch (err) {
      msg.textContent = errorText(err);
      msg.className = 'error';
    }
  }

  async function exchangeOAuthRedirectUrl() {
    const msg = $('oauth-redirect-msg');
    const raw = $('s-oauth-redirect-url')?.value.trim();
    if (!raw) {
      if (msg) {
        msg.textContent = 'Paste the full eBay OAuth redirect URL first.';
        msg.className = 'error';
      }
      return;
    }

    let details;
    try {
      details = parseOAuthRedirectUrl(raw);
    } catch (err) {
      if (msg) {
        msg.textContent = errorText(err);
        msg.className = 'error';
      }
      return;
    }

    const btn = $('btn-exchange-oauth-redirect');
    if (btn) {
      btn.disabled = true;
      btn.textContent = 'Exchanging...';
    }
    if (msg) {
      msg.textContent = `Exchanging production OAuth code${details.state ? ` with state ${details.state}` : ''}...`;
      msg.className = '';
    }

    try {
      const res = await fetch('/api/ebay/exchange-redirect-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ redirectUrl: raw })
      });
      if (!res.ok) throw new Error(await res.text());
      const result = await res.json();
      if (msg) {
        msg.textContent = result.hasRefreshToken
          ? 'Production eBay OAuth access and refresh tokens saved locally.'
          : (result.message || 'Production eBay OAuth access token saved locally.');
        msg.className = 'ok';
      }
      $('s-oauth-redirect-url').value = '';
      updateAuthUI(true);
      addActivity('Production eBay connected', `OAuth redirect exchanged${result.state ? `; state ${result.state}` : ''}.`);
      loadPolicies(false);
      await loadListings('Production eBay connected');
    } catch (err) {
      if (msg) {
        msg.textContent = `OAuth exchange failed: ${errorText(err)}`;
        msg.className = 'error';
      }
      addActivity('Production OAuth failed', errorText(err));
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.textContent = 'Exchange Production OAuth URL';
      }
    }
  }

  let ebayCallbackWatcherActive = false;

  async function pasteAndConnect() {
    const msg = $('oauth-redirect-msg');
    const btn = $('btn-paste-and-connect');
    if (btn) { btn.disabled = true; btn.textContent = 'Connecting…'; }
    try {
      let text = '';
      try { text = await navigator.clipboard.readText(); } catch { /* permission denied */ }
      if (!text || !text.includes('code=')) {
        text = $('s-oauth-redirect-url')?.value.trim() || '';
      }
      if (!text || !text.includes('code=')) {
        if (msg) { msg.textContent = 'No eBay code found. Make sure you copied the URL from your browser after logging in.'; msg.className = 'error'; }
        return;
      }
      const ta = $('s-oauth-redirect-url');
      if (ta) ta.value = text;
      await exchangeOAuthRedirectUrl();
      ebayCallbackWatcherActive = false;
      $('ebay-oauth-step')?.classList.add('hidden');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '📋 I\'ve Logged In — Paste & Connect'; }
    }
  }

  function startEbayCallbackWatcher() {
    if (ebayCallbackWatcherActive) return;
    ebayCallbackWatcherActive = true;

    async function tryAutoConnect() {
      if (!ebayCallbackWatcherActive) return;
      try {
        const text = await navigator.clipboard.readText();
        if (text && text.includes('code=') && text.includes('state=')) {
          ebayCallbackWatcherActive = false;
          document.removeEventListener('visibilitychange', onVisible);
          const ta = $('s-oauth-redirect-url');
          if (ta) ta.value = text;
          await exchangeOAuthRedirectUrl();
          $('ebay-oauth-step')?.classList.add('hidden');
        }
      } catch { /* clipboard permission denied — user clicks the button manually */ }
    }

    function onVisible() {
      if (document.visibilityState === 'visible') tryAutoConnect();
    }

    document.addEventListener('visibilitychange', onVisible);
  }

  function parseOAuthRedirectUrl(raw) {
    const url = new URL(raw);
    if (url.protocol !== 'https:') throw new Error('Redirect URL must be an https:// URL.');
    const code = url.searchParams.get('code') || '';
    const state = url.searchParams.get('state') || '';
    if (!code) throw new Error('Redirect URL is missing the code= parameter. Complete the eBay login first, then paste the full URL you were redirected to.');
    return { code, state };
  }

  async function loadSettingsStatus() {
    const el = $('settings-status');
    if (!el) return;
    el.innerHTML = settingRow('Status', 'Loading local settings...');

    try {
      const [db, folders] = await Promise.all([
        fetch('/api/local-db/status').then(r => r.json()),
        fetch('/api/photos/default-folders').then(r => r.json())
      ]);
      const folderSummary = (Array.isArray(folders) ? folders : [])
        .map(f => `${f.modelKey}: ${f.imageCount} image${f.imageCount === 1 ? '' : 's'}`)
        .join(' | ');

      el.innerHTML = [
        settingRow('Local Database', db.databasePath || '-'),
        settingRow('Saved Local Edits', db.listingCount ?? 0),
        settingRow('Photo Folders', folderSummary || 'No folders found'),
        settingRow('Safety Mode', 'Drafts and revisions require manual action')
      ].join('');
    } catch (err) {
      el.innerHTML = settingRow('Status', `Unable to load settings: ${errorText(err)}`);
    }
  }

  function settingRow(label, value) {
    return `<div class="settings-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;
  }

  async function loadLogs() {
    const el = $('logs-list');
    if (!el) return;
    // A log row saying "Loading" is indistinguishable from a log entry that
    // says Loading. Skeletons can't be mistaken for content.
    el.innerHTML = skeletonRowsHtml(5);

    try {
      const entries = await fetch('/api/logs/recent').then(r => r.json());
      if (!Array.isArray(entries) || entries.length === 0) {
        renderState(el, {
          compact: true,
          icon: 'i-logs',
          title: 'No activity logged yet',
          body: 'Every import, AI analysis, price change and publish is recorded here with its full request detail — useful when something goes wrong.'
        });
        return;
      }

      el.innerHTML = entries.map(logRow).join('');
    } catch (err) {
      renderState(el, {
        variant: 'error',
        compact: true,
        title: "Couldn't read the log",
        body: 'The app is running but the log endpoint did not answer.',
        detail: errorText(err),
        actions: [{ label: 'Try again', id: 'retry', kind: 'btn-primary' }]
      }, { retry: () => loadLogs() });
    }
  }

  function logRow(entry) {
    const level = entry.level || 'Info';
    const time = entry.timestamp ? new Date(entry.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';
    return `
      <div class="log-row">
        <span class="log-level ${esc(level.toLowerCase())}">${esc(level)}</span>
        <strong class="log-title">${esc(entry.title || 'Action')}<br><small>${esc(time)}</small></strong>
        <span class="log-detail">${esc(entry.detail || '')}</span>
      </div>`;
  }

  async function loadListings(activityTitle = 'Listings imported') {
    setListingsFeedback('Loading active eBay listings…', 'busy');
    showListingsSkeleton();

    try {
      const res = await fetch('/api/ebay/listings');
      if (!res.ok) {
        let errorText;
        try { const body = await res.json(); errorText = body.error || JSON.stringify(body); }
        catch { errorText = await res.text(); }
        throw new Error(`HTTP ${res.status}: ${errorText}`);
      }
      const listings = await res.json();
      cachedListings = Array.isArray(listings) ? listings : [];
      renderListings();
      updateStats();
      addActivity(activityTitle, `${cachedListings.length} listing${cachedListings.length === 1 ? '' : 's'} loaded from eBay.`);
    } catch (err) {
      const errorDetail = errorText(err, 'Unknown eBay API error.');
      if (isConnected) {
        // Connected but import failed — show the real error, never fall back to samples
        cachedListings = [];
        updateStats();
        const grid = $('listings-grid');
        const tbody = $('listings-table-body');
        if (grid) grid.innerHTML = '';
        if (tbody) tbody.innerHTML = '';
        setListingsFeedback('Import failed.', 'error');
        // The failure gets the whole panel rather than one line of red text:
        // it is the only thing on this screen the seller can act on, and the
        // two things worth trying are right there.
        renderState('listings-state', {
          variant: 'error',
          title: "Couldn't import your eBay listings",
          body: 'eBay accepted the connection but refused the request. This is usually an expired token — reconnecting fixes it.',
          detail: errorDetail,
          actions: [
            { label: 'Try again', id: 'retry', kind: 'btn-primary' },
            { label: 'Open logs', id: 'logs' }
          ]
        }, {
          retry: () => loadListings(),
          logs: () => showLogsSection()
        });
        addActivity('eBay import failed', errorDetail);
        showResult('error', `eBay import failed: ${esc(errorDetail)} — Check the Logs section for details.`);
        return;
      }
      // Not yet connected — fall back to sample listings
      if (await loadPlaceholderListings('Sample listings loaded')) {
        addActivity('eBay not connected', 'Showing sample listings. Connect eBay to import real listings.');
        return;
      }
      setListingsFeedback(errorDetail, 'error');
      addActivity('Import failed', errorDetail);
    } finally {
      // updateStats() clears this on every path that reaches it, but the ones
      // that don't — a sample load that also failed — would leave four tiles
      // shimmering forever. A loading state that cannot end is a hang.
      setStatsLoading(false);
    }
  }

  function showListingsSkeleton() {
    const grid = $('listings-grid');
    const tbody = $('listings-table-body');
    clearListingsState();
    if (grid) grid.innerHTML = skeletonCardsHtml(8);
    if (tbody) tbody.innerHTML = `<tr><td colspan="12" class="skeleton-cell">${skeletonRowsHtml(6)}</td></tr>`;
    // The tiles above the grid were the last stale thing on the page during a
    // reload: four confident numbers from the previous account, sitting over a
    // shimmering grid. updateStats() clears this when the real numbers land.
    setStatsLoading(true);
  }

  function clearListingsState() {
    const el = $('listings-state');
    if (el) el.innerHTML = '';
  }

  async function loadPlaceholderListings(activityTitle = 'Sample listings loaded') {
    setListingsFeedback('Loading sample listings…', 'busy');

    try {
      const listings = await fetch('/api/local-listings/placeholder').then(r => {
        if (!r.ok) return r.text().then(t => { throw new Error(t); });
        return r.json();
      });
      cachedListings = Array.isArray(listings) ? listings : [];
      renderListings();
      updateStats();
      setListingsFeedback(`${cachedListings.length} sample listing${cachedListings.length === 1 ? '' : 's'} shown until eBay is connected.`);
      addActivity(activityTitle, `${cachedListings.length} local sample listing${cachedListings.length === 1 ? '' : 's'} loaded.`);
      return true;
    } catch (err) {
      setListingsFeedback('Connect eBay, then import listings.');
      addActivity('Sample listings unavailable', errorText(err, 'Unable to load local sample listings.'));
      return false;
    }
  }

  function renderListings() {
    const grid = $('listings-grid');
    const tbody = $('listings-table-body');
    if (!grid || !tbody) return;

    const search = ($('global-search')?.value || '').trim().toLowerCase();
    const listings = cachedListings.filter(l => listingSearchText(l).includes(search));

    grid.innerHTML = '';
    tbody.innerHTML = '';
    clearListingsState();

    // Nothing loaded at all. Whether that is a first run or a genuinely empty
    // store changes what the seller should do next, so the two say so
    // differently and each offers the step that moves them forward.
    if (!cachedListings.length) {
      setListingsFeedback(isConnected
        ? 'No active listings found on this account.'
        : 'Not connected to eBay yet.');
      renderState('listings-state', isConnected ? {
        icon: 'i-inbox',
        title: 'No active listings on this account',
        body: 'Nothing is live on eBay right now. Create one with AI from a photo or a product name — the app writes the title, description, item specifics and price from real sold comps.',
        actions: [
          { label: 'Create an AI listing', id: 'ai', kind: 'btn-primary' },
          { label: 'Import again', id: 'import' }
        ],
        hint: 'Listings you create elsewhere show up here after an import.'
      } : {
        icon: 'i-plug',
        title: 'Connect eBay to see your listings',
        body: 'Log in once and the app imports your live listings, then keeps prices, quantities and photos in sync from here.',
        actions: [
          { label: 'Log into eBay', id: 'connect', kind: 'btn-primary' },
          { label: 'Create an AI listing', id: 'ai' }
        ],
        hint: 'Nothing is published to eBay without your confirmation.'
      }, {
        connect: () => $('btn-connect')?.click(),
        ai: () => $('btn-new-ai-listing')?.click(),
        import: () => loadListings()
      });
      return;
    }

    // Loaded fine, filtered to nothing — a search result, not a problem.
    if (!listings.length) {
      setListingsFeedback(`No listings match “${search}”.`);
      renderState('listings-state', {
        compact: true,
        icon: 'i-search',
        title: `No listings match “${search}”`,
        body: `Searched title, SKU, listing ID and category across ${cachedListings.length} listing${cachedListings.length === 1 ? '' : 's'}.`,
        actions: [{ label: 'Clear search', id: 'clear', kind: 'btn-secondary' }]
      }, {
        clear: () => {
          const box = $('global-search');
          if (box) { box.value = ''; box.focus(); }
          renderListings();
        }
      });
      return;
    }

    const sampleOnly = listings.every(l => (l.status || '').toUpperCase() === 'SAMPLE');
    setListingsFeedback(sampleOnly
      ? `${listings.length} sample listing${listings.length === 1 ? '' : 's'} shown until eBay is connected.`
      : `${listings.length} listing${listings.length === 1 ? '' : 's'} shown.`);

    listings.forEach(listing => {
      grid.appendChild(renderListingCard(listing));
      tbody.appendChild(renderListingRow(listing));
    });
  }

  function renderListingCard(listing) {
    const card = document.createElement('article');
    card.className = 'listing-card';
    card.dataset.offerId = listing.offerId || '';

    const img = listing.thumbnailUrl
      ? `<img src="${esc(listing.thumbnailUrl)}" alt="" loading="lazy" />`
      : '<div class="listing-media"><strong>ING Mining</strong><span>No photo</span></div>';

    // Watchers ride on the photo rather than in the footer. Four items on one
    // footer line wrapped at card width, and a watch count is a property of
    // the listing, not an action — it belongs with the picture.
    const watchBadge = listing.watchCount > 0
      ? `<span class="watch-badge" title="${listing.watchCount} watcher${listing.watchCount === 1 ? '' : 's'}">👁 ${listing.watchCount}</span>`
      : '';
    const viewLink = listing.listingUrl
      ? `<a class="view-ebay-link" href="${esc(listing.listingUrl)}" target="_blank" rel="noopener noreferrer" title="Open this listing on eBay">eBay ↗</a>`
      : '';

    card.innerHTML = `
      <div class="listing-thumb">${img}${watchBadge}</div>
      <div class="listing-title">${esc(listing.title || 'Untitled listing')}</div>
      <div class="listing-meta">
        <span>Price<strong>${money(listing.price)}</strong></span>
        <span>Quantity<strong>${listing.quantity ?? 0}</strong></span>
        <span>SKU<strong>${esc(listing.sku || '-')}</strong></span>
        <span>Listing ID<strong>${esc(listing.listingId || '-')}</strong></span>
        <span>Category<strong>${esc(listingCategory(listing))}</strong></span>
        <span>Updated<strong>${esc(listingUpdated(listing))}</strong></span>
      </div>
      <div class="listing-footer">
        <span class="${statusClass(listing.status)}">${esc(displayStatus(listing.status))}</span>
        <span class="listing-footer-actions">
          ${viewLink}
          <button class="btn btn-secondary small" type="button">Edit</button>
        </span>
      </div>`;

    card.querySelector('button')?.addEventListener('click', event => {
      event.stopPropagation();
      loadListingIntoForm(listing, card);
    });
    card.addEventListener('dblclick', () => loadListingIntoForm(listing, card));
    return card;
  }

  function renderListingRow(listing) {
    const row = document.createElement('tr');
    const img = listing.thumbnailUrl
      ? `<img class="table-img" src="${esc(listing.thumbnailUrl)}" alt="" loading="lazy" />`
      : '<div class="table-img"></div>';

    const rowViewLink = listing.listingUrl
      ? `<a href="${esc(listing.listingUrl)}" target="_blank" rel="noopener noreferrer">View</a>`
      : '-';

    row.innerHTML = `
      <td>${img}</td>
      <td><strong>${esc(listing.title || 'Untitled listing')}</strong></td>
      <td class="dt-money">${money(listing.price)}</td>
      <td>${listing.quantity ?? 0}</td>
      <td>${esc(listing.sku || '-')}</td>
      <td>${esc(listing.listingId || '-')}</td>
      <td><span class="${statusClass(listing.status)}">${esc(displayStatus(listing.status))}</span></td>
      <td>${esc(listingCategory(listing))}</td>
      <td>${esc(listingUpdated(listing))}</td>
      <td>${listing.watchCount > 0 ? listing.watchCount : '-'}</td>
      <td>${rowViewLink}</td>
      <td><button class="btn btn-secondary small" type="button">Edit</button></td>`;

    row.querySelector('button')?.addEventListener('click', () => loadListingIntoForm(listing, row));
    row.addEventListener('dblclick', () => loadListingIntoForm(listing, row));
    return row;
  }

  // A placeholder/SAMPLE listing (see PlaceholderListings.cs) has no real offerId and a
  // fabricated listingId — it was never actually published to eBay, so it must never be
  // eligible for a live revision call. Status is what identifies one: every placeholder is
  // built with Status = "SAMPLE", and they carry a SKU of their own, so the SKU proves nothing.
  //
  // An eBay ItemID on its own is enough to revise. This used to demand `listingId && sku`, which
  // is not what the server requires and not what eBay requires: UpdateListingAsync routes a
  // listing with no offerId to ReviseFixedPriceItemAsync, whose XML targets <ItemID> and never
  // mentions a SKU. GetMyeBaySelling only reports a SKU when the seller set a custom label, so
  // for a normal imported catalogue this test failed on nearly every row — and a failed test
  // hid the Save Changes button, leaving an edited listing with no way to publish it at all.
  function canReviseOnEbay(listing) {
    if ((listing.status || '').toUpperCase() === 'SAMPLE') return false;
    return !!(listing.offerId || listing.listingId);
  }

  // ── Take-home: all-in net, break-even and the offer floor ──────────────────
  // The listing editor used to show a price and nothing else, so a seller could type $120 and bank
  // $91 without ever seeing the $29. This panel puts the real number next to the price field in
  // both editors, and it is not a second opinion: every figure comes from /api/pricing/net-quote,
  // which runs the same NetProceedsCalculator that costs local arbitrage, lot analysis, inventory
  // health and watcher offers. One calculation, one answer, every screen.

  const TAKE_HOME_DEBOUNCE_MS = 350;
  const takeHomeTimers = {};     // prefix -> debounce handle
  const takeHomeState  = {};     // prefix -> last response, so the floor buttons have something to apply
  let   costBasisCache = null;   // /api/inventory/cost-basis, fetched once per drawer session

  const thNum = id => { const v = parseFloat($(id)?.value); return Number.isFinite(v) && v >= 0 ? v : 0; };

  function bindTakeHome(prefix) {
    if (!$(`${prefix}-th-panel`)) return;

    // Anything that moves the money re-costs the sale. Quantity is included because the panel
    // reports the total across the run as well as the per-unit profit.
    ['price', 'quantity', 'unit-cost', 'ship-cost', 'buyer-shipping']
      .forEach(field => on(`${prefix}-${field}`, 'input', () => scheduleTakeHome(prefix)));

    // A cost typed against a live listing is the same cost Inventory Health and Watcher Offers
    // need, so it is written through to the shared store. On blur rather than per keystroke.
    if (prefix === 'f') on('f-unit-cost', 'change', () => saveCostBasisFromDrawer(drawerListing));

    $(`${prefix}-th-panel`)?.addEventListener('click', e => {
      if (e.target.closest('[data-th-fees]')) { handleNav('settings'); $('fees-costs')?.scrollIntoView({ behavior: 'smooth' }); return; }

      // Turning the floor into eBay's own auto-decline rule is the point of computing it: below
      // this price the seller never has to see the offer, let alone be tempted by it.
      const declineBtn = e.target.closest('[data-th-decline]');
      if (declineBtn) {
        const floor = Number(declineBtn.dataset.floor);
        if (!Number.isFinite(floor) || floor <= 0) return;
        if ($(`${prefix}-best-offer`) && !$(`${prefix}-best-offer`).checked) {
          $(`${prefix}-best-offer`).checked = true;
          $(`${prefix}-best-offer`).dispatchEvent(new Event('change', { bubbles: true }));
        }
        set(`${prefix}-auto-decline`, floor.toFixed(2));
        $(`${prefix}-auto-decline`)?.dispatchEvent(new Event('input', { bubbles: true }));
        addActivity('Auto-decline set to your floor', moneyExact(floor));
      }
    });

    renderTakeHome(prefix, null);
    refreshAdRateStrip(prefix, 0, 0);
  }

  function scheduleTakeHome(prefix) {
    clearTimeout(takeHomeTimers[prefix]);
    takeHomeTimers[prefix] = setTimeout(() => refreshTakeHome(prefix), TAKE_HOME_DEBOUNCE_MS);
  }

  async function refreshTakeHome(prefix) {
    const panel = $(`${prefix}-th-panel`);
    if (!panel) return;

    const price = thNum(`${prefix}-price`);
    const cost  = thNum(`${prefix}-unit-cost`);
    const ship  = $(`${prefix}-ship-cost`)?.value.trim();

    try {
      const { res, body } = await safePost('/api/pricing/net-quote', {
        prices: [price],
        unitCost: cost > 0 ? cost : null,
        buyerPaidShipping: thNum(`${prefix}-buyer-shipping`),
        quantity: Math.max(1, parseInt($(`${prefix}-quantity`)?.value, 10) || 1),
        shippingCost: ship ? (parseFloat(ship) || 0) : null,
      });
      if (!res.ok) throw new Error(body?.error || 'Could not price this sale.');
      takeHomeState[prefix] = body;
      renderTakeHome(prefix, body);
      refreshAdRateStrip(prefix, price, cost);
    } catch (err) {
      // A pricing panel that silently shows nothing is worse than one that says it is stale:
      // the seller would read the blank space as "no fees on this sale".
      $(`${prefix}-th-body`).innerHTML =
        `<div class="th-verdict th-error"><strong class="th-headline">Take-home unavailable</strong>
         <span class="th-note">${esc(errorText(err, 'The fee calculation could not be reached.'))}
         Your price is unchanged — but it has not been checked against your costs.</span></div>`;
    }
  }

  function renderTakeHome(prefix, data) {
    const body = $(`${prefix}-th-body`);
    if (!body) return;

    const q = data?.quotes?.[0];
    if (!q) {
      body.innerHTML = `<div class="th-verdict th-idle"><strong class="th-headline">Enter a price</strong>
        <span class="th-note">Type an asking price and what you paid, and this shows exactly what
        reaches your bank after eBay's cut, shipping and every other fee.</span></div>`;
      return;
    }

    const qty = Number(q.quantity) || 1;
    const floors = q.hasCostBasis ? `
      <div class="th-floors">
        <div class="th-floor">
          <span>Break even at</span><strong>${moneyExact(q.breakEvenPrice)}</strong>
          <em>Sell for less and this listing costs you money.</em>
        </div>
        <div class="th-floor th-floor-min">
          <span>Never accept less than</span><strong>${moneyExact(q.minimumOfferPrice)}</strong>
          <em>${esc(floorBasisText(q))}</em>
          <button type="button" class="th-floor-btn" data-th-decline data-floor="${q.minimumOfferPrice}">
            Use as auto-decline
          </button>
        </div>
      </div>` : '';

    const lines = (q.lines || []).map(l => `
      <div class="th-line${Number(l.amount) > 0 ? '' : ' th-line-zero'}" title="${esc(l.detail)}">
        <span>${esc(l.label)}</span><span>−${moneyExact(l.amount)}</span>
      </div>`).join('');

    body.innerHTML = `
      <div class="th-verdict th-${esc(q.verdict)}">
        <strong class="th-headline">${esc(q.headline)}</strong>
        <span class="th-note">${esc(q.note)}</span>
      </div>
      ${floors}
      ${qty > 1 && q.hasCostBasis
        ? `<div class="th-total">${moneyExact(q.totalNetProfit)} across all ${qty} units</div>` : ''}
      <details class="th-lines">
        <summary>Where ${moneyExact(q.totalDeductions)} of a ${moneyExact(q.grossRevenue)} sale goes
          (${Number(q.feeLoadPercent).toFixed(1)}%)</summary>
        <div class="th-line th-line-gross"><span>Sale price + buyer shipping</span><span>${moneyExact(q.grossRevenue)}</span></div>
        ${lines}
        <div class="th-line th-line-total"><span>Lands in your account</span><span>${moneyExact(q.netProceeds)}</span></div>
        ${q.hasCostBasis
          ? `<div class="th-line th-line-cost"><span>What you paid</span><span>−${moneyExact(q.unitCost)}</span></div>
             <div class="th-line th-line-net"><span>Net profit${q.marginPercent != null
                ? ` · ${Number(q.marginPercent).toFixed(1)}% margin` : ''}${q.roiPercent != null
                ? ` · ${Number(q.roiPercent).toFixed(0)}% ROI` : ''}</span><span>${moneyExact(q.netProfit)}</span></div>`
          : ''}
      </details>`;
  }

  // ── The ad rate this margin can carry, in the editor ──────────────────────
  // Promoted Listings is the one cost a seller opts into after the price is set, and eBay's own
  // suggested rate is computed with no knowledge of what the item cost. Sizing it here — against
  // the net just calculated above, live as the price changes — is the difference between choosing a
  // rate and accepting one. Same endpoint and same math as the Ad Rate Advisor page.
  async function refreshAdRateStrip(prefix, price, cost) {
    const el = $(`${prefix}-th-ads`);
    if (!el) return;

    if (!(price > 0) || !(cost > 0)) {
      el.innerHTML = '<div class="th-ads-idle">Add what you paid to see the Promoted Listings ad rate this margin can carry.</div>';
      return;
    }

    try {
      const { res, body } = await safePost('/api/promoted/advise', {
        title: $(`${prefix}-title`)?.value || '',
        category: $(`${prefix}-category`)?.value || '',
        price,
        unitCost: cost,
        buyerPaidShipping: thNum(`${prefix}-buyer-shipping`),
        shippingCost: $(`${prefix}-ship-cost`)?.value.trim() ? thNum(`${prefix}-ship-cost`) : null,
      });
      if (!res.ok) throw new Error(body?.error || 'Could not size an ad rate.');
      renderAdRateStrip(el, body);
    } catch {
      // A blank strip would read as "ads are free on this one". Say what actually happened.
      el.innerHTML = '<div class="th-ads-idle">The ad-rate check could not be reached — your price and take-home above are unaffected.</div>';
    }
  }

  function renderAdRateStrip(el, a) {
    const rec = a.recommendedRatePercent;
    const pct = n => `${Number(n).toFixed(1)}%`;

    if (rec == null) {
      el.innerHTML = `<div class="th-ads-idle">${esc(a.note || '')}</div>`;
      return;
    }

    // Below zero the server's own copy is the right copy — "this sale already loses money" and
    // "the margin is too thin to carry ads" are different problems and must not read the same.
    const headline = rec > 0
      ? `Run ads at ${pct(rec)} — ${moneyExact(a.adFeeAtRecommended)} a sale`
      : a.verdict === 'no_margin' ? 'No margin to advertise' : 'Don\'t promote this one';

    const detail = rec <= 0
      ? (a.note || '')
      : `Leaves ${moneyExact(a.netPerSaleAtRecommended)} of your ${moneyExact(a.netPerSaleNoAds)}. ` +
        (a.breakEvenLiftAtRecommendedPercent != null
          ? `It has to lift sales ${pct(a.breakEvenLiftAtRecommendedPercent)} to pay for itself.`
          : '');

    el.innerHTML = `
      <div class="th-ads-row th-ads-${rec > 0 ? 'on' : 'off'}">
        <div>
          <strong class="th-ads-headline">${esc(headline)}</strong>
          <span class="th-ads-note">${esc(detail)}</span>
        </div>
        <div class="th-ads-meta">
          <span title="Published typical ad rate for this category — override it with what your Seller Hub shows">${esc(a.categoryLabel)} pays ${pct(a.categoryRatePercent)}</span>
          ${a.maxSustainableRatePercent != null
            ? `<span class="th-ads-ceiling" title="Above this the ad fee is bigger than the whole profit on the sale">ceiling ${pct(a.maxSustainableRatePercent)}</span>` : ''}
        </div>
      </div>`;
  }

  function floorBasisText(q) {
    if (q.minimumOfferBasis === 'margin_target')
      return `Your ${Number(q.minimumMarginPercent).toFixed(1)}% minimum margin. Set it in Fees & Costs.`;
    if (q.minimumOfferBasis === 'profit_target')
      return `Keeps the ${moneyExact(q.minimumNetProfit)} per sale you said you won't go under.`;
    return 'Your floor is break-even — set a minimum profit in Fees & Costs to raise it.';
  }

  // The cost the seller types in the drawer is the same cost Inventory Health and Watcher Offers
  // need, so it is written to the shared cost-basis store rather than living in the form. Entering
  // it once in the place they are already looking at the price is the whole reason those screens
  // ever have a break-even to work with.
  async function loadCostBasisInto(prefix, listing) {
    if (!$(`${prefix}-unit-cost`)) return;
    set(`${prefix}-unit-cost`, '');

    const listingId = listing?.listingId || '';
    const sku = listing?.sku || '';
    if (!listingId && !sku) return scheduleTakeHome(prefix);

    try {
      costBasisCache ??= await fetch('/api/inventory/cost-basis').then(r => r.json());
      const match = (costBasisCache || []).find(e =>
        (listingId && e.listingId === listingId) || (sku && e.sku && e.sku === sku));
      if (match) set(`${prefix}-unit-cost`, Number(match.unitCost + match.inboundShipping).toFixed(2));
    } catch { /* no saved cost — the panel just asks for one */ }

    scheduleTakeHome(prefix);
  }

  async function saveCostBasisFromDrawer(listing) {
    const cost = thNum('f-unit-cost');
    const listingId = listing?.listingId || '';
    const sku = listing?.sku || '';
    if (cost <= 0 || (!listingId && !sku)) return;

    try {
      await safePost('/api/inventory/cost-basis',
        [{ listingId, sku, unitCost: cost, inboundShipping: 0, note: 'Entered in the listing editor' }]);
      costBasisCache = null;   // next drawer open re-reads it
    } catch { /* saving the cost is a convenience; never block the listing save on it */ }
  }

  // ── Market Research (inside the Edit Listing drawer) ───────────────────────
  // Reuses the existing /api/sold-comps endpoint, which already layers Terapeak
  // (when the seller's session is connected) over Marketplace Insights and falls
  // back to eBay research deep links. Nothing is duplicated here.

  let lastResearch = null;   // most recent /api/sold-comps payload

  // Strongest available identifier wins — a UPC/EAN/ISBN/MPN match is far more
  // precise than a title match, which is mostly marketing words.
  function buildResearchQuery() {
    const v = id => ($(id)?.value || '').trim();
    const upc = v('f-upc'), ean = v('f-ean'), isbn = v('f-isbn'), mpn = v('f-mpn');
    if (upc)  return { q: upc,  basis: 'UPC' };
    if (ean)  return { q: ean,  basis: 'EAN' };
    if (isbn) return { q: isbn, basis: 'ISBN' };

    const brand = v('f-brand');
    if (mpn)          return { q: (brand ? brand + ' ' : '') + mpn, basis: brand ? 'Brand + MPN' : 'MPN' };
    const title = v('f-title');
    if (brand && title) return { q: `${brand} ${title}`.slice(0, 120), basis: 'Brand + Title' };
    if (title)          return { q: title.slice(0, 120), basis: 'Title' };
    return { q: '', basis: '' };
  }

  function bindMarketResearch() {
    if (!$('mr-panel')) return;

    on('btn-mr-sold', 'click', runSoldResearch);


    on('btn-mr-active', 'click', () => {
      const { q } = buildResearchQuery();
      if (!q) return setResearchStatus('Add a title, brand, MPN or UPC first.', 'empty');
      window.open('https://www.ebay.com/sch/i.html?_nkw=' + encodeURIComponent(q) + '&_sop=12',
                  '_blank', 'noopener');
    });

    on('btn-mr-finder', 'click', () => {
      const { q } = buildResearchQuery();
      if (q) sessionStorage.setItem('opportunityPrefill', q);
      handleNav('opportunity');
    });

    on('btn-mr-apply', 'click', () => {
      const price = recommendedPrice();
      if (price == null) return;
      set('f-price', price.toFixed(2));
      $('f-price')?.dispatchEvent(new Event('input', { bubbles: true }));
      setResearchStatus(`Price set to ${money(price)} locally — not sent to eBay until you update the listing.`, '');
      addActivity('Recommended price applied', money(price));
    });

    on('btn-mr-copy', 'click', async () => {
      const avg = lastResearch?.average;
      if (!avg) return;
      try { await navigator.clipboard.writeText(Number(avg).toFixed(2)); setResearchStatus('Average sold price copied.', ''); }
      catch { setResearchStatus('Could not access the clipboard.', 'error'); }
    });
  }

  function setResearchStatus(msg, kind) {
    const el = $('mr-status');
    if (!el) return;
    el.textContent = msg || '';
    el.className = 'mr-status' + (kind ? ' ' + kind : '');
  }

  // The one failure in this panel a seller fixes in a single click, and eBay only accepts a real
  // sign-in in a real browser — so it gets the button that opens one rather than a Retry that
  // would be handed the same sign-in page every time. Appended after the status text rather than
  // replacing it, so the sentence explaining what happened stays on screen beside the button.

  // Median is the anchor rather than the mean: a couple of parts-only or
  // mislabelled comps skew an average badly on low sold counts.
  function recommendedPrice() {
    if (!lastResearch || !lastResearch.count) return null;
    const median = Number(lastResearch.median) || 0;
    const avg    = Number(lastResearch.average) || 0;
    const base   = median > 0 ? median : avg;
    return base > 0 ? Math.round(base * 100) / 100 : null;
  }

  async function runSoldResearch() {
    const { q, basis } = buildResearchQuery();
    const results = $('mr-results');

    if (!q) {
      results?.classList.add('hidden');
      return setResearchStatus('Add a title, brand, MPN or UPC before researching.', 'empty');
    }

    setText('mr-query', '');
    $('mr-query').innerHTML = `Searching by <strong>${esc(basis)}</strong>: ${esc(q)}`;
    setResearchStatus('Searching sold listings…', 'working');
    $('btn-mr-sold')?.setAttribute('disabled', 'disabled');

    try {
      // Cost and current ask ride along so the answer comes back already costed — a median is a
      // gross number, and the seller pricing off it needs to see what is left of it.
      const params = new URLSearchParams({ q });
      const cost = thNum('f-unit-cost');
      const ask  = thNum('f-price');
      if (cost > 0) params.set('cost', String(cost));
      if (ask  > 0) params.set('ask',  String(ask));
      const buyerShipping = thNum('f-buyer-shipping');
      if (buyerShipping > 0) params.set('buyerShipping', String(buyerShipping));

      const res = await fetch('/api/sold-comps?' + params.toString());
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || `Request failed (${res.status})`);
      lastResearch = data;
      renderResearch(data);
    } catch (err) {
      results?.classList.add('hidden');
      setResearchStatus('Research failed: ' + (errorText(err, 'unknown error')) +
                        ' — you can still open Terapeak or eBay search above.', 'error');
    } finally {
      $('btn-mr-sold')?.removeAttribute('disabled');
    }
  }

  function renderResearch(d) {
    const results = $('mr-results');
    const count = Number(d.count) || 0;

    if (!count) {
      results?.classList.add('hidden');
      // The server's own sentence wins when it has one. "No comparable sales" is a fact about the
      // item; "your Terapeak session expired" is a fact about the app, and the two used to be the
      // same blank panel — so a seller with a dead session concluded the product had never sold.
      setResearchStatus(
        d.dataNote ||
        (d.source === 'none'
          ? 'No comparable sales available for this query — eBay may not have approved sold-data access for this account. Use the buttons above to research manually.'
          : 'No comparable sold listings found for this query.'),
        'empty');
      return;
    }

    results?.classList.remove('hidden');

    // Where these numbers came from, on screen with the numbers. Live Terapeak, the sold-comps
    // database and eBay Insights are not equally current, and a median means something different
    // depending on which one produced it — the server names the source, so nothing here has to
    // guess from a slug.
    const srcLabel = d.sourceLabel ||
      { marketplace_insights: 'eBay Insights', hosted_comps: 'Sold-comps database', none: 'Links only' }[d.source] ||
      d.source || '—';

    // A source that answered does not mean every source did. When Terapeak dropped out and the
    // sold-comps database caught the fall, the numbers are real but they are not the ones the
    // seller thinks they are looking at, so the swap is stated rather than silently absorbed.
    setResearchStatus(d.dataNote ? `${d.dataNote} Showing ${srcLabel} instead.` : '', d.dataNote ? 'empty' : '');
    setText('mr-avg',    money(d.average));
    setText('mr-median', money(d.median));
    setText('mr-min',    money(d.min));
    setText('mr-max',    money(d.max));
    setText('mr-count',  String(count));
    setText('mr-source', srcLabel);

    const reco = recommendedPrice();
    setText('mr-reco-price', reco == null ? '—' : money(reco));

    // The recommendation is a gross price; what matters is what survives it. The server already
    // costed the median against the seller's fee profile, so say the net here rather than leaving
    // "Recommended Price $120" to be read as $120 of income.
    const confidence = count < 3
      ? `Low confidence — only ${count} comparable sale${count === 1 ? '' : 's'}.`
      : `Based on the median of ${count} sold listings.`;
    const netAtMedian = d.pricing?.quotes?.median;
    setText('mr-reco-note', netAtMedian
      ? `${confidence} ${netAtMedian.hasCostBasis
          ? `Sell at this and you keep ${moneyExact(netAtMedian.netProfit)} after fees`
            + `${d.pricing.minimumOfferPrice ? `; don't accept under ${moneyExact(d.pricing.minimumOfferPrice)}` : ''}.`
          : `${moneyExact(netAtMedian.netProceeds)} of it reaches your account after fees and shipping.`}`
      : confidence);

    // Flag comps far from the median so a skewed sample is visible rather than silent.
    const median = Number(d.median) || 0;
    const items = Array.isArray(d.items) ? d.items.slice(0, 12) : [];
    const box = $('mr-comps');
    if (!box) return;

    if (!items.length) { box.innerHTML = ''; return; }

    let outliers = 0;
    box.innerHTML = items.map(it => {
      const price = Number(it.price ?? it.Price) || 0;
      const title = it.title ?? it.Title ?? 'Comparable sale';
      const url   = it.url ?? it.Url ?? it.itemUrl ?? '';
      const isOutlier = median > 0 && price > 0 && (price > median * 2 || price < median * 0.5);
      if (isOutlier) outliers++;
      const label = esc(String(title)).slice(0, 140);
      return `<div class="mr-comp${isOutlier ? ' outlier' : ''}">
        <span class="mr-comp-title">${url ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>` : label}</span>
        <span class="mr-comp-price">${money(price)}</span>
      </div>`;
    }).join('') + (outliers
      ? `<div class="mr-outlier-note">${outliers} comparable${outliers === 1 ? '' : 's'} priced far from the median — highlighted above.</div>`
      : '');
  }

  // ── Cross-List to other marketplaces ───────────────────────────────────────
  // Reformats the open draft for Facebook Marketplace, Mercari and Amazon via
  // /api/crosslist/export. Everything here is local text and CSV — no request
  // ever reaches those sites, and the eBay listing is never touched.

  let lastCrossList = null;   // most recent /api/crosslist/export payload
  let xlActiveTab   = '';

  function bindCrossListing() {
    if (!$('xl-panel')) return;

    on('btn-xl-generate', 'click', runCrossListing);

    $('xl-tabs')?.addEventListener('click', e => {
      const tab = e.target.closest('.xl-tab');
      if (!tab) return;
      xlActiveTab = tab.dataset.market;
      renderCrossListTabs();
      renderCrossListCard();
    });

    $('xl-body')?.addEventListener('click', e => {
      const btn = e.target.closest('[data-xl-action]');
      if (!btn) return;
      const listing = xlActiveListing();
      if (!listing) return;

      if (btn.dataset.xlAction === 'copy-title')  xlCopy(listing.title, 'Title');
      if (btn.dataset.xlAction === 'copy-desc')   xlCopy(listing.description, 'Description');
      if (btn.dataset.xlAction === 'copy-price')  xlCopy(Number(listing.netParityPrice || 0).toFixed(2), 'Price');
      if (btn.dataset.xlAction === 'download')    xlDownloadCsv(listing);
      if (btn.dataset.xlAction === 'open')        window.open(listing.createUrl, '_blank', 'noopener');
    });
  }

  function xlActiveListing() {
    return lastCrossList?.listings?.find(l => l.marketplace === xlActiveTab) || null;
  }

  function setCrossListStatus(msg, kind) {
    const el = $('xl-status');
    if (!el) return;
    el.textContent = msg || '';
    el.className = 'xl-status' + (kind ? ' ' + kind : '');
  }

  async function runCrossListing() {
    const targets = Array.from(document.querySelectorAll('[data-xl-target]'))
      .filter(cb => cb.checked)
      .map(cb => cb.dataset.xlTarget);

    if (!targets.length) {
      $('xl-results')?.classList.add('hidden');
      return setCrossListStatus('Pick at least one marketplace to export to.', 'empty');
    }

    setCrossListStatus('Building marketplace listings…', 'working');
    $('btn-xl-generate')?.setAttribute('disabled', 'disabled');

    try {
      const res = await fetch('/api/crosslist/export', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...buildPayload(), targets }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data?.error || `Request failed (${res.status})`);

      lastCrossList = data;
      if (!data.listings?.some(l => l.marketplace === xlActiveTab))
        xlActiveTab = data.listings?.[0]?.marketplace || '';

      renderCrossList();
      addActivity('Cross-listings generated', `${data.listings?.length || 0} marketplace(s)`);
    } catch (err) {
      $('xl-results')?.classList.add('hidden');
      setCrossListStatus('Could not build the cross-listings: ' + (errorText(err, 'unknown error')), 'error');
    } finally {
      $('btn-xl-generate')?.removeAttribute('disabled');
    }
  }

  function renderCrossList() {
    const results = $('xl-results');
    if (!lastCrossList?.listings?.length) {
      results?.classList.add('hidden');
      return setCrossListStatus('Nothing to export from this draft yet.', 'empty');
    }

    results?.classList.remove('hidden');
    setCrossListStatus(
      `Ready. Your eBay listing at ${moneyExact(lastCrossList.ebayPrice)} nets you ` +
      `${moneyExact(lastCrossList.ebayNet)} after ${moneyExact(lastCrossList.ebayFees)} in eBay fees — ` +
      `each marketplace below is priced to match that.`, '');

    $('xl-warnings').innerHTML = (lastCrossList.warnings || [])
      .map(w => `<div class="xl-warning">${esc(w)}</div>`).join('');

    renderCrossListTabs();
    renderCrossListCard();
  }

  function renderCrossListTabs() {
    const box = $('xl-tabs');
    if (!box) return;
    box.innerHTML = (lastCrossList?.listings || []).map(l => {
      const count = (l.warnings || []).length;
      return `<button type="button" class="xl-tab${l.marketplace === xlActiveTab ? ' active' : ''}"
        role="tab" aria-selected="${l.marketplace === xlActiveTab}" data-market="${esc(l.marketplace)}">
        ${esc(l.displayName)}${count ? `<span class="xl-tab-flag" title="${count} thing${count === 1 ? '' : 's'} to check">${count}</span>` : ''}
      </button>`;
    }).join('');
  }

  // The number that makes this worth doing: what the seller actually takes home
  // on each site, and how far the price has to move to keep it level with eBay.
  function crossListPriceNote(l) {
    const ebayPrice = Number(lastCrossList?.ebayPrice) || 0;
    const ebayNet   = Number(lastCrossList?.ebayNet) || 0;
    const parity    = Number(l.netParityPrice) || 0;
    const atSame    = Number(l.netAtSamePrice) || 0;

    if (ebayPrice <= 0) return 'Set a price on this draft to see fee-adjusted pricing.';

    const gap = Math.round((parity - ebayPrice) * 100) / 100;

    if (Math.abs(gap) < 0.01)
      return `${l.displayName}'s fees land within a cent of eBay's — list at the same ${moneyExact(ebayPrice)}.`;

    if (gap < 0)
      return `${l.displayName} takes ${moneyExact(ebayPrice - parity)} less than eBay in fees on this item. ` +
             `You can undercut your own eBay price and list at ${moneyExact(parity)} while still taking home ` +
             `${moneyExact(ebayNet)} — or list at ${moneyExact(ebayPrice)} and pocket ${moneyExact(atSame - ebayNet)} more.`;

    return `Listing at your eBay price of ${moneyExact(ebayPrice)} here would only net ${moneyExact(atSame)} — ` +
           `${moneyExact(ebayNet - atSame)} less than eBay, because of ${l.feePercent}% fees. ` +
           `List at ${moneyExact(parity)} to take home the same ${moneyExact(ebayNet)}.`;
  }

  function renderCrossListCard() {
    const box = $('xl-body');
    const l = xlActiveListing();
    if (!box) return;
    if (!l) { box.innerHTML = ''; return; }

    const titleOver = l.titleTruncated ? ' over' : '';
    const descOver  = l.descriptionTruncated ? ' over' : '';
    const importLabel = l.importSupport === 'manual' ? 'Download Worksheet CSV' : 'Download Import CSV';

    box.innerHTML = `
      <div class="xl-card">
        <div class="xl-card-head">
          <h4>${esc(l.displayName)}</h4>
          <div class="xl-card-actions">
            <button type="button" class="btn btn-secondary small" data-xl-action="open">Open ${esc(l.displayName)}</button>
            <button type="button" class="btn btn-ghost small" data-xl-action="download">${esc(importLabel)}</button>
          </div>
        </div>

        <div class="xl-price">
          <div class="xl-price-cell">
            <span>List at your eBay price</span><strong>${moneyExact(l.samePrice)}</strong>
          </div>
          <div class="xl-price-cell">
            <span>You'd net</span><strong>${moneyExact(l.netAtSamePrice)}</strong>
          </div>
          <div class="xl-price-cell headline">
            <span>Price to match eBay take-home</span><strong>${moneyExact(l.netParityPrice)}</strong>
          </div>
          <div class="xl-price-note">${esc(crossListPriceNote(l))}</div>
          <div class="xl-price-note">${esc(l.feeNote)}</div>
        </div>

        <div class="xl-block">
          <div class="xl-block-head">
            <label>Title</label>
            <span class="xl-count${titleOver}">${l.title.length} / ${l.titleLimit}</span>
          </div>
          <textarea rows="2" readonly>${esc(l.title)}</textarea>
          <div class="xl-card-actions">
            <button type="button" class="btn btn-primary small" data-xl-action="copy-title">Copy Title</button>
            <button type="button" class="btn btn-ghost small" data-xl-action="copy-price">Copy Price</button>
          </div>
        </div>

        <div class="xl-block">
          <div class="xl-block-head">
            <label>Description</label>
            <span class="xl-count${descOver}">${l.description.length} / ${l.descriptionLimit}</span>
          </div>
          <textarea rows="9" readonly>${esc(l.description)}</textarea>
          <div class="xl-card-actions">
            <button type="button" class="btn btn-primary small" data-xl-action="copy-desc">Copy Description</button>
          </div>
        </div>

        <div class="xl-fields">
          ${(l.fields || []).map(f => `
            <div class="xl-field${f.required && !f.value ? ' missing' : ''}">
              <span>${esc(f.name)}${f.required ? ' *' : ''}</span>
              <strong title="${esc(f.value || 'Missing')}">${esc(f.value || 'Missing')}</strong>
            </div>`).join('')}
        </div>

        ${(l.warnings || []).length
          ? `<div class="xl-warnings">${l.warnings.map(w => `<div class="xl-warning">${esc(w)}</div>`).join('')}</div>`
          : ''}

        <p class="xl-import-note">${esc(l.importNote)}</p>
      </div>`;
  }

  async function xlCopy(text, label) {
    try {
      await navigator.clipboard.writeText(text || '');
      setCrossListStatus(`${label} copied — paste it straight into ${xlActiveListing()?.displayName || 'the marketplace'}.`, '');
    } catch {
      setCrossListStatus('Could not access the clipboard. Select the text and copy it manually.', 'error');
    }
  }

  function xlDownloadCsv(listing) {
    // BOM so Excel opens the UTF-8 text with accents and symbols intact.
    const blob = new Blob(['﻿' + (listing.csv || '')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = listing.csvFilename || 'cross-listing.csv';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    setCrossListStatus(`${listing.csvFilename} downloaded.`, '');
  }

  // ── Edit Listing drawer ────────────────────────────────────────────────────
  // Rather than duplicating the (large, working) listing form, the existing
  // #form-section node is relocated into the drawer body once at startup. Every
  // field id, collector and save handler therefore keeps working unchanged —
  // the drawer only controls visibility, focus and unsaved-change safety.

  let drawerReturnFocusEl = null;   // element that had focus before opening
  let drawerScrollY       = 0;      // page scroll to restore on close
  let drawerListing       = null;   // listing being edited, so its cost basis can be written back
  let drawerBaseline      = '';     // serialised form state at open, for dirty check

  function initEditDrawer() {
    const body = $('edit-drawer-body');
    const form = $('form-section');
    if (!body || !form) return;     // markup missing — leave legacy inline behaviour

    body.appendChild(form);         // move, not clone: preserves all live listeners

    on('edit-drawer-close', 'click', () => closeEditDrawer());
    $('edit-drawer-overlay')?.addEventListener('click', () => closeEditDrawer());

    document.addEventListener('keydown', e => {
      if (!isEditDrawerOpen()) return;
      // Let nested overlays (photo editor, modals) consume keys first.
      if (document.querySelector('.modal-overlay:not(.hidden), .photo-editor-overlay')) return;

      if (e.key === 'Escape') { closeEditDrawer(); return; }

      // Ctrl/Cmd+S saves the draft — deliberately bound to the draft-preview
      // action, never to the live eBay revision, which must stay an explicit,
      // confirmed click.
      if ((e.ctrlKey || e.metaKey) && !e.shiftKey && (e.key === 's' || e.key === 'S')) {
        e.preventDefault();
        const btn = $('btn-post');
        if (btn && !btn.classList.contains('hidden') && !btn.disabled) btn.click();
        else setResearchStatus?.('', '');
        return;
      }

      // Ctrl/Cmd+R runs sold-price research without reaching for the mouse.
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === 'r' || e.key === 'R')) {
        e.preventDefault();
        $('mr-panel')?.setAttribute('open', 'open');
        $('btn-mr-sold')?.click();
      }
    });

    // Keep focus inside the drawer while it is modal.
    document.addEventListener('focusin', e => {
      if (!isEditDrawerOpen()) return;
      const drawer = $('edit-drawer');
      if (drawer && !drawer.contains(e.target)) drawer.focus();
    });

    // Any edit inside the drawer marks it dirty.
    body.addEventListener('input',  () => refreshDrawerDirty());
    body.addEventListener('change', () => refreshDrawerDirty());
  }

  function isEditDrawerOpen() {
    return !!$('edit-drawer')?.classList.contains('open');
  }

  // A cheap, order-stable snapshot of every control in the drawer. Used only to
  // detect "has the user touched anything", never to persist listing data.
  function snapshotDrawerState() {
    const body = $('edit-drawer-body');
    if (!body) return '';
    return [...body.querySelectorAll('input, select, textarea')]
      .map(el => (el.type === 'checkbox' || el.type === 'radio') ? (el.checked ? '1' : '0') : (el.value ?? ''))
      .join('');
  }

  function refreshDrawerDirty() {
    const drawer = $('edit-drawer');
    if (!drawer) return;
    drawer.classList.toggle('dirty', snapshotDrawerState() !== drawerBaseline);
  }

  function markDrawerClean() {
    drawerBaseline = snapshotDrawerState();
    $('edit-drawer')?.classList.remove('dirty');
  }

  function openEditDrawer(listing) {
    const drawer  = $('edit-drawer');
    const overlay = $('edit-drawer-overlay');
    if (!drawer || !overlay) return;

    drawerReturnFocusEl = document.activeElement;
    drawerScrollY = window.scrollY;

    const title = listing?.title || listing?.sku || listing?.listingId || 'Listing';
    setText('edit-drawer-title', title);
    const bits = [];
    if (listing?.sku)       bits.push(`SKU ${listing.sku}`);
    if (listing?.listingId) bits.push(`ID ${listing.listingId}`);
    if (listing?.status)    bits.push(String(listing.status).toUpperCase());
    setText('edit-drawer-sub', bits.join('  ·  '));

    overlay.classList.add('open');
    drawer.classList.add('open');
    drawer.setAttribute('aria-hidden', 'false');
    drawer.setAttribute('tabindex', '-1');
    document.body.classList.add('drawer-open');

    $('edit-drawer-body').scrollTop = 0;
    // Pull the cost the seller already recorded for this listing (Inventory Health, or a previous
    // visit here) so the take-home panel opens with a real break-even instead of asking again.
    drawerListing = listing || null;
    loadCostBasisInto('f', listing);
    refreshEditorOverview();         // the panels describe THIS listing, not the last one
    markDrawerClean();               // baseline AFTER the form has been filled
    setTimeout(() => drawer.focus(), 30);
  }

  function closeEditDrawer(force) {
    const drawer = $('edit-drawer');
    if (!drawer || !isEditDrawerOpen()) return;

    if (!force && drawer.classList.contains('dirty') &&
        !confirm('You have unsaved changes to this listing.\n\nClose the editor and discard them?')) return;

    drawer.classList.remove('open', 'dirty');
    drawer.setAttribute('aria-hidden', 'true');
    $('edit-drawer-overlay')?.classList.remove('open');
    document.body.classList.remove('drawer-open');

    // Restore the caller's scroll position and keyboard focus.
    window.scrollTo({ top: drawerScrollY, behavior: 'auto' });
    if (drawerReturnFocusEl?.isConnected) {
      try { drawerReturnFocusEl.focus({ preventScroll: true }); } catch { /* non-focusable */ }
    }
    drawerReturnFocusEl = null;
  }

  // ── Editing a listing: what is in the panels you closed ────────────────────
  //
  // The editor is ten collapsible panels. Collapsed, one of them said nothing at
  // all — the seller opened Photos to find out whether there were photos, and
  // scrolled past all ten to reach Save. Every summary now carries the state of
  // its own panel, and the action bar is pinned to the foot of the drawer with
  // what is still missing printed beside the button that saves it.
  //
  // This layer reads the form controls and writes only to the chips and the bar.
  // It never sets a field, never calls the server and never infers a value, so
  // it cannot change what gets published.
  //
  // The severities are ListingReadinessAnalyzer's, and the thresholds are its
  // constants:
  //   is-empty   a Blocker — title, category, price, photo. eBay's own rule.
  //   is-thin    a Warning — short title, under four photos, no description,
  //              no identifier, no brand. The app's opinion about what sells.
  //   no class   a Tip, or plain information.
  // The server check knows things this one cannot — required Item Specifics need
  // a category lookup — which is why the bar says "the four things eBay requires
  // are filled" and never "ready to publish".

  const EDITOR_TITLE_THIN  = 45;   // ListingReadinessAnalyzer.ThinTitleLength
  const EDITOR_PHOTOS_THIN = 4;    // ListingReadinessAnalyzer.GoodPhotoCount

  // The four blockers, in the analyzer's order. `focus` is the control the seller
  // is sent to, which for photos is the button that makes a row — there is no row
  // to focus when the answer is "none".
  const EDITOR_BLOCKERS = [
    { label: 'Title',    focus: 'f-title',           filled: () => editorField('f-title') !== '' },
    { label: 'Category', focus: 'f-category-id',     filled: () => editorField('f-category-id') !== '' },
    { label: 'Price',    focus: 'f-price',           filled: () => editorPrice() > 0 },
    { label: 'Photos',   focus: 'btn-add-photo-url', filled: () => editorPhotoCount() > 0 },
  ];

  function initEditorOverview() {
    const form = $('form-section');
    if (!form) return;

    let timer = null;
    const schedule = () => {
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => { timer = null; refreshEditorOverview(); }, 80);
    };

    // Delegated, and click as well as input: photo and specifics rows are added
    // and removed by buttons, and a row that is removed fires no input event.
    ['input', 'change', 'click'].forEach(evt => form.addEventListener(evt, schedule));

    $('fa-state')?.addEventListener('click', e => {
      const btn = e.target.closest('.fa-jump');
      if (btn) editorJumpTo(btn.dataset.focus);
    });

    refreshEditorOverview();
  }

  function editorField(id) {
    return ($(id)?.value || '').trim();
  }

  function editorPrice() {
    return parseFloat($('f-price')?.value) || 0;
  }

  // Scoped to the editor's own containers: the New Listing overlay has photo and
  // specifics rows of its own, and a document-wide count would add them in.
  function editorPhotoCount() {
    return [...document.querySelectorAll('#photo-url-list .photo-url-row input')]
      .filter(input => input.value.trim()).length;
  }

  function editorSpecificCount() {
    return [...document.querySelectorAll('#specifics-list .specific-row')]
      .filter(row => (row.querySelector('input')?.value || '').trim()).length;
  }

  // The plain-text tab is only merged into the HTML field on a tab switch, so
  // while it is open the field behind it lags what is being typed. Read the live
  // one — and never call descCommitText() here, which would write to a field and
  // make a listing look edited because a chip was refreshed.
  function editorDescriptionLength() {
    const plain = descActiveTab('f') === 'text' ? ($('f-desc-text')?.value || '') : '';
    const text  = plain.trim() ? plain : ($('f-description')?.value || '').replace(/<[^>]*>/g, ' ');
    return text.replace(/\s+/g, ' ').trim().length;
  }

  function setEditorChip(id, text, state) {
    const el = $(id);
    if (!el) return;
    el.textContent = text;
    el.className = 'fp-chip' + (state ? ' ' + state : '');
    // Only a blocker marks the panel. A mark that also fires on an opinion is a
    // mark sellers learn to scroll past.
    el.closest('details.form-panel')?.classList.toggle('is-incomplete', state === 'is-empty');
  }

  function refreshEditorOverview() {
    if (!$('form-section')) return;

    // Title and Category share a panel, so its chip has to answer for both.
    const title   = editorField('f-title');
    const catId   = editorField('f-category-id');
    const catName = editorField('f-category');
    setEditorChip('fp-title',
      [title ? `${title.length} / 80` : 'no title',
       catId ? (catName || `category ${catId}`) : 'no category'].join(' · '),
      (!title || !catId) ? 'is-empty' : (title.length < EDITOR_TITLE_THIN ? 'is-thin' : ''));

    const condition = $('f-condition');
    const condText  = condition?.options[condition.selectedIndex]?.text || '—';
    setEditorChip('fp-condition',
      editorField('f-condition-desc') ? `${condText} · described` : condText, '');

    const brand = editorField('f-brand');
    const codes = ['f-mpn', 'f-upc', 'f-ean', 'f-isbn'].filter(id => editorField(id));
    const idBits = [];
    if (brand) idBits.push(brand);
    if (codes.length) idBits.push(`${codes.length} identifier${codes.length === 1 ? '' : 's'}`);
    setEditorChip('fp-ids', idBits.length ? idBits.join(' · ') : 'none set',
      (brand && codes.length) ? '' : 'is-thin');

    const specifics = editorSpecificCount();
    setEditorChip('fp-specifics', specifics ? `${specifics} filled` : 'none', '');

    const photos = editorPhotoCount();
    setEditorChip('fp-photos',
      photos ? `${photos} photo${photos === 1 ? '' : 's'}` : 'no photos',
      photos === 0 ? 'is-empty' : (photos < EDITOR_PHOTOS_THIN ? 'is-thin' : ''));

    const descLen = editorDescriptionLength();
    setEditorChip('fp-description',
      descLen ? `${descLen.toLocaleString()} characters` : 'empty', descLen ? '' : 'is-thin');

    const price = editorPrice();
    const qty   = parseInt($('f-quantity')?.value, 10) || 1;
    const priceBits = [price > 0 ? moneyExact(price) : 'no price'];
    if (qty > 1) priceBits.push(`qty ${qty}`);
    if ($('f-best-offer')?.checked) priceBits.push('best offer');
    setEditorChip('fp-pricing', priceBits.join(' · '), price > 0 ? '' : 'is-empty');

    const lbs = parseFloat($('f-weight-lbs')?.value) || 0;
    const oz  = parseFloat($('f-weight-oz')?.value) || 0;
    const zip = editorField('f-location-zip');
    const shipBits = [];
    if (lbs || oz) shipBits.push(`${lbs} lb ${oz} oz`);
    if (zip) shipBits.push(zip);
    setEditorChip('fp-shipping', shipBits.length ? shipBits.join(' · ') : 'no weight or ZIP', '');

    const format  = $('f-format');
    const fmtText = format?.options[format.selectedIndex]?.text || '';
    const days    = parseInt($('f-duration')?.value, 10) || 0;
    setEditorChip('fp-options', days ? `${fmtText} · ${days} days` : fmtText, '');

    renderEditorActionState();
  }

  // No aria-live on this: it is rewritten on every keystroke, and a region that
  // announces the character count of a title being typed is a region that gets
  // switched off. The same facts are on the panel each field lives in.
  function renderEditorActionState() {
    const bar = $('fa-state');
    if (!bar) return;

    const missing = EDITOR_BLOCKERS.filter(b => !b.filled());

    if (missing.length === 0) {
      const photos = editorPhotoCount();
      bar.innerHTML =
        '<span class="fa-dot"></span>' +
        '<span><strong>The four things eBay requires are filled.</strong> ' +
        `${esc(moneyExact(editorPrice()))} · ${photos} photo${photos === 1 ? '' : 's'}</span>`;
      return;
    }

    // Each one is a button, not a word: the panel it lives in may be four screens
    // down the form and closed.
    bar.innerHTML =
      '<span class="fa-dot is-empty"></span>' +
      '<span>eBay won’t accept this yet — still empty:</span>' +
      missing.map(b =>
        `<button type="button" class="fa-jump" data-focus="${esc(b.focus)}">${esc(b.label)}</button>`
      ).join('');
  }

  function editorJumpTo(id) {
    const el = $(id);
    if (!el) return;
    el.closest('details')?.setAttribute('open', '');
    el.scrollIntoView({ block: 'center', behavior: 'smooth' });
    // Focus after the scroll settles, or the ring lands off-screen and the pane
    // jumps a second time to catch up with it.
    setTimeout(() => { try { el.focus({ preventScroll: true }); } catch { /* not focusable */ } }, 220);
  }

  function loadListingIntoForm(listing, sourceEl) {
    document.querySelectorAll('.listing-card.active, .listings-table tr.active').forEach(c => c.classList.remove('active'));
    sourceEl?.classList?.add('active');

    activeOfferId = listing.offerId || '';
    activeListingId = listing.listingId || '';
    activeSku = listing.sku || '';
    activeListingStatus = listing.status || '';
    pendingDraftPayload = null;
    hideDraftPreview();

    $('btn-post')?.classList.add('hidden');
    $('btn-create-ebay-draft')?.classList.add('hidden');
    $('btn-new-listing')?.classList.remove('hidden');

    // Shown and disabled rather than hidden when a listing can't be revised. Hiding it left the
    // editor with nothing but "New Listing" under a form full of edits, which reads as "this app
    // cannot publish" rather than "this particular listing was never on eBay". The reason belongs
    // on the button that isn't working.
    const revisable  = canReviseOnEbay(listing);
    const updateBtn  = $('btn-update');
    if (updateBtn) {
      updateBtn.classList.remove('hidden');
      updateBtn.disabled = !revisable;
      updateBtn.title = revisable
        ? 'Push these changes to your live eBay listing'
        : 'This is a sample listing — it was never published to eBay, so there is nothing to revise.';
    }

    const d = listing.data || {};
    fillForm(d);
    set('f-format', d.listingFormat || 'FIXED_PRICE');
    $('form-section')?.classList.remove('hidden');

    // Present the form in the right-side drawer when that markup is present;
    // fall back to the original inline scroll behaviour if it is not.
    if ($('edit-drawer')) openEditDrawer(listing);
    else $('form-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });

    // The grid's data is a summary — no description, no specifics, no condition. Go and get the
    // real thing, or the seller is editing a listing they cannot see. Deliberately after the drawer
    // is already open and populated: the fields it CAN fill appear instantly, and the rest arrive a
    // moment later rather than the whole editor waiting on one eBay call.
    hydrateListingFromEbay(listing);

    addActivity('Edit opened', listing.title || listing.sku || listing.listingId || 'Listing selected');
  }

  /**
   * Fills in what GetMyeBaySelling could not: description, condition, category, brand/MPN and item
   * specifics, read from the live listing with GetItem.
   *
   * Only ever fills fields the summary left BLANK. It is not a refresh and must not behave like one
   * — price and quantity in particular are current in the grid and stale in nothing, and quietly
   * overwriting a figure the seller is looking at is worse than the gap this closes.
   *
   * A failure here is not fatal and is not shouted about: nothing is lost, because a blank field is
   * omitted from the revise entirely (EbayService.BuildReviseFixedPriceItemXml) rather than sent as
   * an empty value. The seller is told, because "the description box is empty" and "the description
   * box could not be loaded" call for different reactions.
   */
  async function hydrateListingFromEbay(listing) {
    const itemId = listing?.listingId || '';
    if (!itemId || (listing?.status || '').toUpperCase() === 'SAMPLE') return;

    // Nothing to go and get if the grid already carried the detail (a locally-created listing).
    const d = listing.data || {};
    if (d.description && Object.keys(d.itemSpecifics || {}).length) return;

    setDrawerDetailStatus('Reading the full listing from eBay…', 'busy');

    const { data, error } = await localFetchJson(
      `/api/ebay/listing-detail?itemId=${encodeURIComponent(itemId)}`, 45000);

    if (!data?.ok || !data.data) {
      setDrawerDetailStatus(
        `Couldn't read this listing's description and specifics from eBay${error ? ` — ${error}` : ''}. ` +
        'Anything you leave blank is left alone on eBay, not cleared.', 'warn');
      return;
    }

    // The drawer may have been closed, or a different listing opened, while eBay was answering.
    if (activeListingId !== itemId) return;

    const full = data.data;

    // Filled when the SUMMARY had nothing, not when the box looks empty. The two differ on the
    // condition dropdown, which fillForm always sets to a default — reading the DOM there would
    // see "USED_EXCELLENT" and conclude the seller had chosen it, when nobody had.
    const summary = listing.data || {};
    const filled = [];
    const fillFrom = (id, summaryValue, liveValue, label) => {
      if (summaryValue || !liveValue) return;
      const el = $(id);
      if (!el) return;
      el.value = liveValue;
      // The description is three tabs, not one box — refill it through the tabs so the readable
      // view shows what eBay just sent back rather than the empty box it replaced.
      if (id === 'f-description') descSetHtml('f', liveValue);
      filled.push(label);
    };

    fillFrom('f-description', summary.description, full.description, 'description');
    fillFrom('f-category-id', summary.categoryId, full.categoryId, 'category');
    fillFrom('f-category', summary.category, full.category, 'category name');
    fillFrom('f-condition', summary.condition, full.condition, 'condition');
    fillFrom('f-condition-desc', summary.conditionDescription, full.conditionDescription, 'condition notes');
    fillFrom('f-brand', summary.brand, full.brand, 'brand');
    fillFrom('f-mpn', summary.mpn, full.mpn, 'MPN');

    // Item specifics are rows, not a field. Only added when there are none on screen — the seller
    // may have started typing their own in the seconds this call was in flight.
    const specifics = full.itemSpecifics || {};
    const count = Object.keys(specifics).length;
    if (count && !Object.keys(collectSpecifics()).length) {
      const list = $('specifics-list');
      if (list) {
        Object.entries(specifics).forEach(([k, v]) => addSpecificRow(k, v));
        filled.push(`${count} item specific${count === 1 ? '' : 's'}`);
      }
    }

    // Re-baseline: these values came from eBay, not from the seller, so the drawer must not claim
    // unsaved changes and must not prompt on close.
    markDrawerClean();

    setDrawerDetailStatus(
      filled.length
        ? `Loaded from your live listing: ${filled.join(', ')}.`
        : 'This listing is already showing everything eBay has for it.',
      'ok');
  }

  function setDrawerDetailStatus(text, kind) {
    const el = $('edit-drawer-detail-status');
    if (!el) return;
    el.textContent = text || '';
    el.className = 'edit-drawer-detail-status' + (kind ? ` is-${kind}` : '');
    el.classList.toggle('hidden', !text);
  }

  function updateStats() {
    const active = cachedListings.filter(l => ['ACTIVE', 'PUBLISHED'].includes((l.status || '').toUpperCase())).length;
    const qty = cachedListings.reduce((sum, l) => sum + (parseInt(l.quantity, 10) || 0), 0);
    const value = cachedListings.reduce((sum, l) => sum + ((parseFloat(l.price) || 0) * (parseInt(l.quantity, 10) || 0)), 0);
    const review = cachedListings.filter(l => !l.thumbnailUrl || !l.title || (l.status || '').toUpperCase() !== 'PUBLISHED').length;

    // Counted, not swapped. An import that adds 40 listings should be visibly
    // an import that added 40 listings, not a number that was one thing and is
    // now another. setStatsLoading(false) first, or the figures would count up
    // underneath the shimmer that was covering them.
    setStatsLoading(false);
    countUpText('stat-active', active);
    countUpText('stat-quantity', qty);
    countUpText('stat-value', value, money);
    countUpText('stat-review', review);
  }

  function addActivity(title, detail) {
    const list = $('activity-list');
    if (!list) return;
    // The "no activity yet" block is markup, not a row — the first real entry
    // retires it.
    list.querySelector('.state')?.remove();
    const item = document.createElement('div');
    item.className = 'activity-item';
    item.innerHTML = `<strong>${esc(title)}</strong><span>${esc(detail)} - ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>`;
    list.prepend(item);
    while (list.children.length > 6) list.lastElementChild?.remove();
  }

  function updateAuthUI(connected) {
    isConnected = connected;
    if (connected) {
      $('auth-status')?.classList.remove('hidden');
      $('btn-connect')?.classList.add('hidden');
      $('btn-disconnect')?.classList.remove('hidden');
    } else {
      $('auth-status')?.classList.add('hidden');
      $('btn-connect')?.classList.remove('hidden');
      $('btn-disconnect')?.classList.add('hidden');
    }
    updateSetupChecklist(null, connected, null);
  }

  /**
   * The dashboard checklist: exactly the two required steps, and nothing optional.
   *
   * Step 2 is eBay *and* its business policies, because the policies can't be loaded until the
   * account is connected — splitting them into two rows would show a new seller a step they are
   * not yet allowed to do. The row's copy and button swap between the two halves instead.
   */
  function updateSetupChecklist(keyDone, hasEbay, policiesDone) {
    const checklist = $('setup-checklist');
    if (!checklist) return;

    // A partial refresh (e.g. eBay-only, which passes null for the other two) must not wipe a
    // step it knows nothing about, so an omitted argument keeps the last known state.
    const step1Done   = keyDone      != null ? !!keyDone      : hasAnthropicKey;
    const connected   = hasEbay      != null ? !!hasEbay      : isConnected;
    const hasPolicies = policiesDone != null ? !!policiesDone : hasBusinessPolicies;
    // The done look lives in .setup-step.is-done, so a step can go back to pending if the key is
    // later cleared — the old inline styles were one-way and left a green tick on a step that no
    // longer applied.
    markSetupStep('step1', step1Done, 'Key saved');

    // Step 2 is the eBay connection only. Picking business policies was taken off this checklist at
    // the seller's request, so `hasPolicies` no longer gates the step - a connected seller is done
    // here whether or not they have chosen policies. The picker lives in Settings now.
    markSetupStep('step2', connected, 'Connected');
    setText('step2-copy', connected
      ? 'eBay is connected.'
      : 'Log into eBay so the app can read your listings and publish for you.');

    const step2Btn = $('step2-btn');
    if (step2Btn && !connected) {
      step2Btn.textContent = 'Log into eBay →';
      step2Btn.dataset.pendingLabel = step2Btn.textContent;
      step2Btn.disabled = false;
    }
    void hasPolicies;   // still read above for the hero chips and the Settings page

    refreshChecklistVisibility();

    renderDashStatus();
  }

  /**
   * The panel goes away when there is nothing left in it — all four rows ticked — rather than as
   * soon as the two required ones are. Picking your policies used to take steps 3 and 4 off the
   * screen with it, which is the whole reason those two logins were hard to find.
   *
   * State is read off the rows themselves, so this needs no second copy of what is already known.
   * An optional row whose status hasn't come back yet counts as done, or a seller with everything
   * finished would see the panel flash on every page load while the two status calls are in
   * flight. Dismissing is final: a later status refresh must not put the panel back.
   */
  function refreshChecklistVisibility() {
    const checklist = $('setup-checklist');
    if (!checklist) return;
    if (checklist.dataset.dismissed === '1') { checklist.classList.add('hidden'); return; }

    const settled = id => {
      const row = $(id);
      if (!row) return true;
      if (row.classList.contains('setup-step--optional') && row.dataset.known !== '1') return true;
      return row.classList.contains('is-done');
    };

    // Explicit dismissal only. This used to hide itself the moment every row was ticked, which
    // meant finishing the last step made the whole panel vanish - the seller had not asked for
    // that and read it as the app losing a section. The X above is how it goes away now.
    void settled;
    checklist.classList.remove('hidden');
  }

  /**
   * The three chips in the hero. Once setup is finished the checklist hides itself and the only
   * remaining report on the front page was a badge in the top bar, so a seller who had never
   * connected eBay saw a dashboard that said nothing about it. State is read off what is already
   * on the page rather than kept in a second variable that can drift from it.
   */
  function renderDashStatus() {
    // Connection only. This chip used to read "eBay connected · policies needed" and stay amber
    // until policies were chosen — the same nag the seller asked to be rid of, in a second place.
    setDashChip('dash-chip-ebay', isConnected,
      'eBay connected', 'eBay not connected');
    setDashChip('dash-chip-ai', hasAnthropicKey,
      'Claude key saved', 'Claude key needed');
  }

  function setDashChip(id, on, onText, offText) {
    const chip = $(id);
    if (!chip) return;
    chip.classList.toggle('is-on', !!on);
    chip.classList.toggle('is-off', !on);
    const text = chip.querySelector('.dash-chip-text');
    if (text) text.textContent = on ? onText : offText;
  }

  function markSetupStep(prefix, done, doneLabel) {
    const row  = $(`${prefix}-row`);
    const icon = $(`${prefix}-icon`);
    const btn  = $(`${prefix}-btn`);
    const step = prefix.replace('step', '');

    row?.classList.toggle('is-done', done);
    if (icon) icon.textContent = done ? '✓' : step;
    if (btn) {
      if (done) {
        if (!btn.dataset.pendingLabel) btn.dataset.pendingLabel = btn.textContent;
        btn.textContent = `✓ ${doneLabel}`;
        btn.disabled = true;
      } else if (btn.dataset.pendingLabel) {
        btn.textContent = btn.dataset.pendingLabel;
        btn.disabled = false;
      }
    }
  }

  // ── Draft Tabs ────────────────────────────────────────────────

  let draftTabs = [];
  let activeDraftTabId = null;
  let draftTabCounter = 0;

  function newDraftTab(title, filename, data, imageBase64, mimeType, visualDesc) {
    draftTabCounter++;
    const tab = {
      id: draftTabCounter,
      title: title || 'New Draft',
      filename: filename || null,
      saved: !!filename,
      data: data || {},
      imageBase64: imageBase64 || '',
      mimeType: mimeType || 'image/jpeg',
      visualDescription: visualDesc || ''
    };
    draftTabs.push(tab);
    return tab;
  }

  function captureCurrentTab() {
    const tab = draftTabs.find(t => t.id === activeDraftTabId);
    if (!tab) return;
    tab.data = buildNlPayload();
    tab.title = tab.data.title || 'New Draft';
    tab.imageBase64 = nlImageBase64 || '';
    tab.mimeType = nlMimeType || 'image/jpeg';
    tab.visualDescription = window._nlVisualDescription || '';
    tab.saved = false;
  }

  function loadTabIntoForm(tab) {
    nlClearForm();
    nlImageBase64 = tab.imageBase64 || '';
    nlMimeType    = tab.mimeType || 'image/jpeg';
    window._nlVisualDescription = tab.visualDescription || '';

    if (nlImageBase64) {
      const img = $('nl-preview-img');
      if (img) img.src = 'data:' + nlMimeType + ';base64,' + nlImageBase64;
      $('nl-drop-zone')?.classList.add('hidden');
      $('nl-preview-wrap')?.classList.remove('hidden');
    } else {
      $('nl-drop-zone')?.classList.remove('hidden');
      $('nl-preview-wrap')?.classList.add('hidden');
    }

    if (tab.data && tab.data.title) fillNlForm(tab.data);
  }

  function switchDraftTab(id) {
    if (activeDraftTabId === id) return;
    captureCurrentTab();
    activeDraftTabId = id;
    const tab = draftTabs.find(t => t.id === id);
    if (tab) loadTabIntoForm(tab);
    renderDraftTabs();
  }

  function renderDraftTabs() {
    const bar = $('nl-tab-bar');
    if (!bar) return;
    const newBtn = $('nl-tab-new-btn');

    // Remove old tab buttons
    bar.querySelectorAll('.nl-tab').forEach(el => el.remove());

    draftTabs.forEach(tab => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'nl-tab' + (tab.id === activeDraftTabId ? ' active' : '');
      const displayTitle = tab.title.length > 24 ? tab.title.slice(0, 24) + '…' : tab.title;
      btn.innerHTML =
        '<span class="nl-tab-favicon">' + (tab.saved ? '💾' : '📄') + '</span>' +
        '<span class="nl-tab-title">' + esc(displayTitle) + '</span>' +
        '<span class="nl-tab-close" data-tabid="' + tab.id + '" title="Close">✕</span>';

      btn.addEventListener('click', e => {
        if (e.target.closest('.nl-tab-close')) return;
        switchDraftTab(tab.id);
      });
      bar.insertBefore(btn, newBtn);
    });

    bar.querySelectorAll('.nl-tab-close').forEach(x => {
      x.addEventListener('click', e => { e.stopPropagation(); closeDraftTab(parseInt(x.dataset.tabid)); });
    });
  }

  function closeDraftTab(id) {
    const idx = draftTabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    draftTabs.splice(idx, 1);
    if (activeDraftTabId === id) {
      const next = draftTabs[Math.min(idx, draftTabs.length - 1)];
      if (next) { activeDraftTabId = next.id; loadTabIntoForm(next); }
      else addNewDraftTab();
    }
    renderDraftTabs();
  }

  async function clearAllSavedDrafts() {
    try {
      const r = await fetch('/api/local-drafts/list');
      if (!r.ok) return;
      const list = await r.json();
      for (const summary of list) {
        try {
          await fetch('/api/local-drafts/delete/' + encodeURIComponent(summary.filename), { method: 'DELETE' });
        } catch { /* skip failed deletes */ }
      }
    } catch { /* non-fatal */ }
  }

  async function clearAllDraftsAndTabs() {
    if (!confirm('Delete all saved drafts and clear all tabs? This cannot be undone.')) return;
    await clearAllSavedDrafts();
    draftTabs = [];
    activeDraftTabId = null;
    const tab = newDraftTab();
    activeDraftTabId = tab.id;
    nlClearAll();
    renderDraftTabs();
    addActivity('All drafts cleared', 'Ready for a new import');
  }

  async function loadAllDraftsAsTabs() {
    const btn = $('nl-load-all-drafts-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Loading…'; }
    try {
      const res   = await fetch('/api/local-drafts/list');
      const list  = await res.json();   // [{filename, title, savedAt}]
      if (!list.length) {
        toast('No saved drafts found in Desktop\\eBayListing.', { kind: 'warning' });
        return;
      }

      // Close any blank tabs first
      draftTabs = draftTabs.filter(t => t.title !== 'New Draft' || t.saved);

      let loaded = 0;
      for (const summary of list) {
        // Skip if already open
        if (draftTabs.some(t => t.filename === summary.filename)) continue;
        try {
          const r2   = await fetch('/api/local-drafts/load/' + encodeURIComponent(summary.filename));
          if (!r2.ok) continue;
          const draft = await r2.json();
          const tab   = newDraftTab(draft.title, draft.filename, draft.data,
                                    draft.imageBase64, draft.mimeType, draft.visualDescription);
          tab.saved = true;
          loaded++;
        } catch { /* skip bad file */ }
      }

      if (loaded === 0) {
        toast('Every saved draft is already open in a tab.', { kind: 'info', title: 'Nothing to open' });
        return;
      }

      // Switch to the first newly loaded tab
      const firstNew = draftTabs[draftTabs.length - loaded];
      if (firstNew) { activeDraftTabId = firstNew.id; loadTabIntoForm(firstNew); }
      renderDraftTabs();
      $('new-listing-overlay')?.classList.remove('hidden');
      addActivity(`Loaded ${loaded} drafts as tabs`, 'Review and publish each one');
      toastOk(`${loaded} draft${loaded === 1 ? '' : 's'} opened — review and publish each one.`,
              { title: 'Drafts loaded' });
    } catch (e) {
      toastErr(errorText(e, 'Unknown error.'), {
        title: "Couldn't open your drafts",
        action: { label: 'Try again', onClick: loadAllDraftsAsTabs },
      });
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Open All Drafts'; }
    }
  }

  function addNewDraftTab() {
    const tab = newDraftTab();
    activeDraftTabId = tab.id;
    nlClearForm();
    nlImageBase64 = ''; nlMimeType = 'image/jpeg'; window._nlVisualDescription = '';
    $('nl-drop-zone')?.classList.remove('hidden');
    $('nl-preview-wrap')?.classList.add('hidden');
    renderDraftTabs();
  }

  // Saves straight to the server-managed Desktop\eBayListing folder via DraftStore (the same
  // endpoint the Bulk Catalog Import already uses) instead of letting the browser's native save
  // dialog put the file wherever the user navigates to. The dialog approach (previously
  // window.showSaveFilePicker with startIn:'desktop') only opens ON the Desktop — it doesn't
  // force saving INTO the eBayListing subfolder DraftStore actually scans, so a draft saved via
  // the dialog could land right next to that folder and still be invisible to "Open All Drafts".
  async function saveDraftLocal() {
    captureCurrentTab();
    const tab = draftTabs.find(t => t.id === activeDraftTabId);
    if (!tab) return;

    const btn = $('nl-btn-save-local');
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }

    const payload = {
      filename: tab.filename || null,
      title: tab.title,
      data: tab.data,
      imageBase64: tab.imageBase64 || null,
      mimeType: tab.mimeType || 'image/jpeg',
      visualDescription: tab.visualDescription || null
    };

    try {
      const res = await fetch('/api/local-drafts/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error('Save failed (HTTP ' + res.status + ')');
      const { filename } = await res.json();

      tab.filename = filename;
      tab.saved    = true;
      addActivity('Draft saved', filename + ' — Desktop\\eBayListing\\' + filename);
      renderDraftTabs();
      if (btn) { btn.textContent = '✓ Saved'; setTimeout(() => { if (btn) { btn.disabled = false; btn.textContent = '💾 Save Draft'; } }, 1200); }

      // Open a fresh blank tab for the next listing
      addNewDraftTab();

    } catch (err) {
      if (btn) { btn.disabled = false; btn.textContent = '💾 Save Draft'; }
      // Unsaved work is the one failure the seller must not be able to click
      // past, so the retry that would rescue it rides along on the toast.
      toastErr(errorText(err, 'Unknown error.'), {
        title: 'Draft not saved',
        action: { label: 'Try again', onClick: saveDraftLocal },
      });
    }
  }

  // ── New AI Listing modal ─────────────────────────────────────

  function bindNewListingModal() {
    const dropZone = $('nl-drop-zone');
    const fileInput = $('nl-file-input');

    dropZone?.addEventListener('click', e => {
      if (e.target !== fileInput) fileInput?.click();
    });
    dropZone?.addEventListener('dragover', e => {
      e.preventDefault();
      dropZone.classList.add('drag-over');
    });
    dropZone?.addEventListener('dragleave', e => {
      // Only remove drag-over when leaving the drop zone itself, not a child element
      if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over');
    });
    dropZone?.addEventListener('drop', e => {
      e.preventDefault();
      dropZone.classList.remove('drag-over');
      // Try files first (file system drops), then items fallback (browser drags, screenshot tools)
      const file = e.dataTransfer.files[0] ||
        [...(e.dataTransfer.items || [])].find(i => i.kind === 'file' && i.type.startsWith('image/'))?.getAsFile();
      if (file) nlLoadFile(file);
    });
    fileInput?.addEventListener('change', () => {
      if (fileInput.files[0]) nlLoadFile(fileInput.files[0]);
    });

    // The drop zone is contenteditable=true purely so the browser's native right-click
    // menu offers "Paste" (Chrome only shows that item for editable elements). Block every
    // other editing operation so it never actually behaves like a text field.
    dropZone?.addEventListener('beforeinput', e => e.preventDefault());
    dropZone?.addEventListener('paste', e => {
      e.preventDefault();
      e.stopPropagation(); // handled here — don't let the global paste listener double-fire
      const imageItem = [...(e.clipboardData?.items || [])].find(i => i.type.startsWith('image/'));
      const file = imageItem?.getAsFile();
      if (file) nlLoadFile(file, 'Pasted screenshot');
    });

    // Global paste — load image when clipboard contains an image
    // Only skip if focus is in a text-entry field that legitimately consumes text paste
    const TEXT_PASTE_IDS = new Set(['nl-title','nl-description','nl-desc-text','nl-ai-modify-input','nl-url-input','nl-bulk-input']);
    document.addEventListener('paste', e => {
      const imageItem = [...(e.clipboardData?.items || [])].find(i => i.type.startsWith('image/'));
      if (!imageItem) return;
      const focused = document.activeElement;
      if (focused && TEXT_PASTE_IDS.has(focused.id)) return;
      const file = imageItem.getAsFile();
      if (!file) return;
      e.preventDefault();
      // Route to whichever paste-aware page is actually on screen — pasting while the
      // Opportunity Finder is open should feed the Supplier File Analyzer, not silently
      // jump to the AI Listing modal.
      if (!$('opportunity-section')?.classList.contains('hidden')) {
        oppSupplierLoadFile(file, 'Pasted supplier file');
        return;
      }
      openNewListingModal();
      nlLoadFile(file, 'Pasted screenshot');
    });

    on('nl-btn-clear', 'click', nlClearImage);
    on('nl-btn-reanalyze', 'click', nlAnalyze);
    on('nl-btn-retry', 'click', nlAnalyze);
    on('nl-btn-improve-seo', 'click', nlImproveSeo);

    // Description edit/preview tabs — same three tabs as the listing edit drawer, same code.
    initDescTabs('nl');
    on('nl-close', 'click', closeNewListingModal);
    on('nl-btn-cancel', 'click', closeNewListingModal);
    on('nl-btn-save-local', 'click', saveDraftLocal);
    on('nl-tab-new-btn', 'click', addNewDraftTab);
    on('nl-load-all-drafts-btn', 'click', loadAllDraftsAsTabs);
    on('nl-clear-drafts-btn', 'click', clearAllDraftsAndTabs);
    on('nl-btn-load-policies', 'click', () => loadPolicies(true));
    on('nl-btn-add-specific', 'click', () => nlAddSpecificRow('', ''));
    on('nl-best-offer', 'change', e => nlToggleBestOffer(e.target.checked));
    on('nl-format', 'change', e => {
      $('nl-duration-wrap').style.display = e.target.value === 'AUCTION' ? '' : 'none';
    });
    on('nl-title', 'input', () => { nlUpdateCharCount('nl-title', 'nl-title-count', 80); $('nl-title').classList.remove('field-flagged'); });
    on('nl-subtitle', 'input', () => nlUpdateCharCount('nl-subtitle', 'nl-subtitle-count', 55));

    bindCategorySearch('nl-category', 'nl-category-id', 'nl-category-dropdown', 'nl-cat-selected', 'nl-cat-selected-name', 'nl-cat-id-badge', 'nl-cat-clear');
    on('nl-url-go',    'click', nlAnalyzeUrl);
    on('nl-url-input', 'keydown', e => { if (e.key === 'Enter') nlAnalyzeUrl(); });
    $('nl-url-input')?.addEventListener('paste', e => {
      setTimeout(() => {
        const val = $('nl-url-input')?.value.trim() || '';
        if (val.startsWith('http')) nlAnalyzeUrl();
      }, 50);
    });
    on('nl-quickfill-go', 'click', nlQuickFillByName);
    on('nl-quickfill-input', 'keydown', e => { if (e.key === 'Enter') nlQuickFillByName(); });
    on('nl-sold-comps-close', 'click', () => $('nl-sold-comps-strip')?.classList.add('hidden'));
    on('nl-sold-comps-connect-btn', 'click', nlSoldCompsConnect);
    on('nl-bulk-go', 'click', nlBulkImport);
    on('nl-bulk-url-input', 'keydown', e => { if (e.key === 'Enter') nlBulkImport(); });
    on('nl-ai-modify-go', 'click', nlAiModify);
    on('nl-ai-modify-input', 'keydown', e => { if (e.key === 'Enter') nlAiModify(); });

    initListingReadiness();
    initKeywordGap();

    on('nl-btn-publish', 'click', () => nlSubmit('publish'));

    on('nl-btn-draft', 'click', () => nlSubmit('draft'));

    on('btn-new-from-edit', 'click', openNewListingModal);

    $('new-listing-overlay')?.addEventListener('keydown', e => {
      if (e.key === 'Escape') closeNewListingModal();
    });
  }

  function openNewListingModal(keepTabs = false) {
    // Starting a listing, not reviewing a rewrite: the intake block comes back.
    $('new-listing-overlay')?.classList.remove('nl-review-draft');
    // The AI Listing screen is a workspace tab like any other, and it opens by several routes
    // that never went through the sidebar — a pasted screenshot, a recovered draft, the dashboard
    // button. Clearing the other screens here means every one of those routes behaves the same.
    hideOverlaySections();
    if (!$('nl-photo-grid')?.querySelector('.nl-photo-slot')) initPhotoGrid();
    // Always start fresh unless explicitly told to keep existing tabs (e.g. bulk import)
    if (!keepTabs) {
      draftTabs = [];
      activeDraftTabId = null;
      const tab = newDraftTab();
      activeDraftTabId = tab.id;
      renderDraftTabs();
    } else if (draftTabs.length === 0) {
      const tab = newDraftTab();
      activeDraftTabId = tab.id;
      renderDraftTabs();
    }
    nlClearAll();
    applyListingDefaults();
    $('new-listing-overlay')?.classList.remove('hidden');
    $('new-listing-overlay')?.focus();
    nlRefreshSoldCompsConnect();   // show/hide the Connect-to-Terapeak prompt in the bar
    nlRunReadiness(true);          // score the blank form so the bar is there from the start
    setActiveNavItem('ai');
    markWorkspaceTabOpen('ai');
    if (cachedPolicies) {
      fillNlPolicySelects();
    } else if (isConnected) {
      const msg = $('nl-policy-msg');
      if (msg) { msg.textContent = 'Loading policies…'; msg.className = 'sd-test-msg'; }
      loadPolicies(false);
    } else {
      const msg = $('nl-policy-msg');
      if (msg) { msg.textContent = 'Connect eBay to load policies'; msg.className = 'sd-test-msg'; }
    }
  }

  function applyListingDefaults() {
    const zip         = $('pg-default-zip')?.value;
    const country     = $('pg-default-country')?.value || 'US';
    const pkgType     = $('pg-default-package-type')?.value || 'PACKAGE_THICK_ENVELOPE';
    const handling    = $('pg-default-handling')?.value || '1';
    const wLbs        = $('pg-default-weight-lbs')?.value || '0';
    const wOz         = $('pg-default-weight-oz')?.value  || '0';
    const len         = $('pg-default-length')?.value || '0';
    const wid         = $('pg-default-width')?.value  || '0';
    const hgt         = $('pg-default-height')?.value || '0';
    const fulfillment = $('pg-default-fulfillment')?.value.trim() || '';
    const bestOffer   = !!$('pg-default-best-offer')?.checked;

    if (zip)  setVal('nl-location-zip', zip);
    setVal('nl-location-country', country);
    setVal('nl-package-type',     pkgType);
    setVal('nl-handling-time',    handling);
    if (parseFloat(wLbs) > 0) setVal('nl-weight-lbs', wLbs);
    if (parseFloat(wOz)  > 0) setVal('nl-weight-oz',  wOz);
    if (parseFloat(len)  > 0) setVal('nl-length', len);
    if (parseFloat(wid)  > 0) setVal('nl-width',  wid);
    if (parseFloat(hgt)  > 0) setVal('nl-height', hgt);
    if (fulfillment) setVal('nl-fulfillment', fulfillment);
    if (bestOffer) {
      const boEl = $('nl-best-offer');
      if (boEl) { boEl.checked = true; nlToggleBestOffer(true); }
    }
  }

  function closeNewListingModal() {
    closeWorkspacePage('ai');
  }

  function nlClearAll() {
    nlClearImage();
    nlClearForm();
    nlSetResult('', '');
    // Keep the sold-comps bar visible (it hosts the Connect-to-Terapeak prompt); just
    // reset its data. nlRefreshSoldCompsConnect() re-evaluates the prompt on open.
    $('nl-sold-comps-stats')?.classList.add('hidden');
    if ($('nl-sold-comp-list')) $('nl-sold-comp-list').innerHTML = '';
    if ($('nl-sold-comps-summary')) $('nl-sold-comps-summary').textContent = '';
    if ($('nl-quickfill-input')) $('nl-quickfill-input').value = '';
  }

  function nlClearImage() {
    nlImageBase64 = '';
    nlMimeType = 'image/jpeg';
    const fi = $('nl-file-input');
    if (fi) fi.value = '';
    if ($('nl-preview-img')) $('nl-preview-img').src = '';
    $('nl-drop-zone')?.classList.remove('hidden');
    $('nl-preview-wrap')?.classList.add('hidden');
    $('nl-cutout-wrap')?.classList.add('hidden');
    $('nl-ai-status')?.classList.add('hidden');
    $('nl-ai-done')?.classList.add('hidden');
    $('nl-ai-error')?.classList.add('hidden');
    $('nl-photos-section')?.classList.add('hidden');
    $('nl-imggen-status-bar')?.classList.add('hidden');
    if ($('nl-imggen-status-text')) $('nl-imggen-status-text').textContent = '';
    $('nl-imggen-setup-link')?.classList.add('hidden');
    $('nl-photos-generating')?.classList.add('hidden');
    if ($('nl-photos-grid')) $('nl-photos-grid').innerHTML = '';
    $('nl-photos-error')?.classList.add('hidden');
  }

  // The SKU a draft arrived with, and the one line about it the seller ever needs to read.
  //
  // Hidden field plus a sentence, rather than another box to fill in: this code was minted by the
  // screen that knew what the lot cost, and retyping it is how the join between the listing and
  // that cost gets broken. The line is shown only when there IS one, because most listings have no
  // SKU and a permanently empty note is noise on the busiest form in the app.
  function nlSetSku(sku) {
    const field = $('nl-sku');
    if (field) field.value = sku || '';

    const note = $('nl-sku-note');
    if (!note) return;
    if (!sku) { note.classList.add('hidden'); note.textContent = ''; return; }
    note.textContent = `SKU ${sku} — publishing this records what you paid for it, so Money Made `
                     + `counts the sale as real profit.`;
    note.classList.remove('hidden');
  }

  function nlClearForm() {
    const sets = [
      ['nl-title', ''], ['nl-subtitle', ''], ['nl-category', ''], ['nl-category-id', ''],
      ['nl-secondary-category-id', ''], ['nl-condition', 'USED_EXCELLENT'], ['nl-condition-desc', ''],
      ['nl-brand', ''], ['nl-mpn', ''], ['nl-upc', ''], ['nl-ean', ''], ['nl-isbn', ''],
      ['nl-description', ''], ['nl-price', ''], ['nl-quantity', '1'], ['nl-qty-limit', ''],
      ['nl-auto-accept', ''], ['nl-auto-decline', ''], ['nl-package-type', 'PACKAGE_THICK_ENVELOPE'],
      ['nl-handling-time', '1'], ['nl-weight-lbs', '0'], ['nl-weight-oz', '0'],
      ['nl-length', ''], ['nl-width', ''], ['nl-height', ''], ['nl-location-zip', ''],
      ['nl-location-country', 'US'], ['nl-format', 'FIXED_PRICE'], ['nl-duration', '7'],
      ['nl-charity-pct', '0'], ['nl-charity-id', ''],
    ];
    sets.forEach(([id, val]) => set(id, val));
    nlSetSku('');
    if ($('nl-best-offer')) $('nl-best-offer').checked = false;
    if ($('nl-private')) $('nl-private').checked = false;
    nlToggleBestOffer(false);
    if ($('nl-duration-wrap')) $('nl-duration-wrap').style.display = 'none';
    if ($('nl-specifics-list')) $('nl-specifics-list').innerHTML = '';
    nlResetReadiness();
    nlResetKeywordGap();
    nlClearAllPhotoSlots();
    // Empty description, back on the text tab (the default)
    descSetHtml('nl', '');
    nlUpdateCharCount('nl-title', 'nl-title-count', 80);
    nlUpdateCharCount('nl-subtitle', 'nl-subtitle-count', 55);
    if ($('nl-cat-selected')) $('nl-cat-selected').hidden = true;
  }

  function nlLoadFile(file, label = file.name || 'Product photo') {
    // Accept files with no type (some screenshot tools omit MIME); reject known non-images
    const mime = file.type || 'image/png';
    if (mime && !mime.startsWith('image/')) return;
    nlMimeType = mime;
    const reader = new FileReader();
    reader.onload = ev => {
      nlImageBase64 = ev.target.result.split(',')[1];
      $('nl-preview-img').src = ev.target.result;
      $('nl-drop-zone')?.classList.add('hidden');
      $('nl-preview-wrap')?.classList.remove('hidden');
      $('nl-ai-done')?.classList.add('hidden');
      $('nl-ai-error')?.classList.add('hidden');
      addActivity('Photo loaded', label);
      nlAnalyze();
    };
    reader.readAsDataURL(file);
  }

  // ── Category search autocomplete ─────────────────────────────────────────

  function bindCategorySearch(inputId, hiddenId, dropdownId, selectedId, nameId, badgeId, clearId) {
    const input    = $(inputId);
    const hidden   = $(hiddenId);
    const dropdown = $(dropdownId);
    const selected = $(selectedId);
    const nameEl   = $(nameId);
    const badge    = $(badgeId);
    const clearBtn = $(clearId);
    if (!input || !dropdown) return;

    let debounce = null;
    let activeIdx = -1;
    let currentSuggestions = [];

    // The hidden input is written directly rather than typed into, so it never fires `change`
    // on its own. Announcing it lets anything that depends on the category react — the
    // readiness check needs to, since the category is what decides which Item Specifics exist.
    function announce() {
      hidden.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function showSelected(name, id) {
      input.value = '';
      input.placeholder = 'Search to change category…';
      hidden.value  = id;
      if (nameEl) nameEl.textContent = name;
      if (badge)  badge.textContent  = 'ID: ' + id;
      if (selected) selected.hidden = false;
      closeDropdown();
      announce();
    }

    function clearSelection() {
      hidden.value = '';
      input.value = '';
      input.placeholder = 'Type to search eBay categories…';
      if (selected) selected.hidden = true;
      input.focus();
      announce();
    }

    function closeDropdown() {
      dropdown.hidden = true;
      activeIdx = -1;
    }

    function renderDropdown(items, loading = false) {
      dropdown.innerHTML = '';
      if (loading) {
        dropdown.innerHTML = '<li class="cat-loading">Searching eBay categories…</li>';
        dropdown.hidden = false;
        return;
      }
      if (!items.length) {
        dropdown.innerHTML = '<li class="cat-no-results">No categories found — try different keywords</li>';
        dropdown.hidden = false;
        return;
      }
      currentSuggestions = items;
      items.forEach((item, i) => {
        const li = document.createElement('li');
        li.innerHTML = `<span class="cat-id-tag">${esc(item.id)}</span><span class="cat-name">${esc(item.name)}</span><span class="cat-path">${esc(item.breadcrumb)}</span>`;
        li.addEventListener('mousedown', e => {
          e.preventDefault();
          showSelected(item.name, item.id);
        });
        dropdown.appendChild(li);
      });
      dropdown.hidden = false;
      activeIdx = -1;
    }

    async function fetchSuggestions(q) {
      if (q.length < 2) { closeDropdown(); return; }
      renderDropdown([], true);
      try {
        const res  = await fetch('/api/ebay/category-suggestions?q=' + encodeURIComponent(q));
        const data = await res.json();
        if (Array.isArray(data)) renderDropdown(data);
        else closeDropdown();
      } catch { closeDropdown(); }
    }

    // ── Category tree browser ──────────────────────────────────────────────
    const browseBtn  = $(`${inputId.replace('nl-category','nl-cat-browse-btn').replace('f-category','f-cat-browse-btn')}`);
    const browser    = $(`${inputId.replace('nl-category','nl-cat-browser').replace('f-category','f-cat-browser')}`);
    const browserList  = browser ? browser.querySelector('.cat-browser-list')  : null;
    const browserTrail = browser ? browser.querySelector('.cat-browser-trail') : null;
    let   browserStack = []; // [{id, name}] — breadcrumb trail

    function closeBrowser() { if (browser) browser.hidden = true; }

    async function loadBrowserLevel(catId, catName) {
      if (!browser || !browserList) return;
      browserList.innerHTML = '<li class="cat-loading">Loading categories…</li>';
      browser.hidden = false;
      try {
        const res  = await fetch(`/api/ebay/category-children?id=${encodeURIComponent(catId || '0')}`);
        const cats = await res.json();
        browserList.innerHTML = '';
        // Back button
        if (browserStack.length > 0) {
          const back = document.createElement('li');
          back.className = 'cat-browser-back';
          back.textContent = '← Back';
          back.addEventListener('mousedown', e => {
            e.preventDefault();
            browserStack.pop();
            const prev = browserStack.length > 0 ? browserStack[browserStack.length - 1] : { id: '0', name: '' };
            updateTrail();
            loadBrowserLevel(prev.id, prev.name);
          });
          browserList.appendChild(back);
        }
        cats.forEach(cat => {
          const li = document.createElement('li');
          const isLeaf = cat.breadcrumb === 'leaf';
          li.innerHTML = `<span class="cat-name">${esc(cat.name)}</span><span class="cat-id-tag">${esc(cat.id)}</span>${isLeaf ? '' : '<span class="cat-arrow">›</span>'}`;
          li.addEventListener('mousedown', e => {
            e.preventDefault();
            if (isLeaf) {
              showSelected(cat.name, cat.id);
              closeBrowser();
              browserStack = [];
              updateTrail();
            } else {
              browserStack.push({ id: cat.id, name: cat.name });
              updateTrail();
              loadBrowserLevel(cat.id, cat.name);
            }
          });
          browserList.appendChild(li);
        });
      } catch { browserList.innerHTML = '<li class="cat-no-results">Failed to load — try searching instead</li>'; }
    }

    function updateTrail() {
      if (!browserTrail) return;
      browserTrail.innerHTML = ['All Categories', ...browserStack.map(s => s.name)]
        .map((n, i, arr) => i < arr.length - 1 ? `<span class="trail-crumb">${esc(n)}</span> ›` : `<strong>${esc(n)}</strong>`)
        .join(' ');
    }

    if (browseBtn) {
      browseBtn.addEventListener('click', e => {
        e.preventDefault();
        if (browser && !browser.hidden) { closeBrowser(); return; }
        browserStack = [];
        updateTrail();
        loadBrowserLevel('0', '');
        closeDropdown();
      });
    }

    input.addEventListener('input', () => {
      clearTimeout(debounce);
      closeBrowser();
      const q = input.value.trim();
      if (!q) { closeDropdown(); return; }
      debounce = setTimeout(() => fetchSuggestions(q), 280);
    });

    input.addEventListener('keydown', e => {
      const items = dropdown.querySelectorAll('li:not(.cat-loading):not(.cat-no-results)');
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        activeIdx = Math.min(activeIdx + 1, items.length - 1);
        items.forEach((li, i) => li.classList.toggle('active', i === activeIdx));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeIdx = Math.max(activeIdx - 1, 0);
        items.forEach((li, i) => li.classList.toggle('active', i === activeIdx));
      } else if (e.key === 'Enter' && activeIdx >= 0) {
        e.preventDefault();
        if (currentSuggestions[activeIdx]) {
          const s = currentSuggestions[activeIdx];
          showSelected(s.name, s.id);
        }
      } else if (e.key === 'Escape') {
        closeDropdown();
      }
    });

    input.addEventListener('blur', () => setTimeout(closeDropdown, 150));
    if (browseBtn) browseBtn.addEventListener('blur', () => setTimeout(closeBrowser, 200));

    if (clearBtn) clearBtn.addEventListener('click', clearSelection);
  }

  // ── When AI fills form — sync category display ─────────────────────────

  function nlSyncCategoryDisplay() {
    const id   = $('nl-category-id')?.value || '';
    const name = $('nl-category')?.value || '';
    const selected = $('nl-cat-selected');
    const nameEl   = $('nl-cat-selected-name');
    const badge    = $('nl-cat-id-badge');
    if (!id) { if (selected) selected.hidden = true; return; }
    if (nameEl) nameEl.textContent = name || 'Category ' + id;
    if (badge)  badge.textContent  = 'ID: ' + id;
    if (selected) {
      selected.hidden = false;
      // Clear the search input so it shows the selected bar
      const inp = $('nl-category');
      if (inp) { inp.value = ''; inp.placeholder = 'Search to change category…'; }
    }
  }

  async function nlBulkImport() {
    const input = $('nl-bulk-url-input');
    const btn   = $('nl-bulk-go');
    const url   = input?.value.trim();
    if (!url || !url.startsWith('http')) return;

    if (btn) { btn.disabled = true; btn.textContent = 'Clearing old drafts…'; }

    // Always wipe old drafts and tabs before importing a new collection
    await clearAllSavedDrafts();
    draftTabs = [];
    activeDraftTabId = null;
    const blankTab = newDraftTab();
    activeDraftTabId = blankTab.id;
    nlClearAll();
    renderDraftTabs();

    if (btn) { btn.textContent = 'Scanning…'; }

    try {
      const res2 = await fetch('/api/bulk-import/extract-links', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url })
      });
      if (!res2.ok) throw new Error('Could not extract product links from that page');
      const { links } = await res2.json();
      if (!links?.length) throw new Error('No product links found on that page');

      addActivity(`Bulk import started`, `Found ${links.length} products on page`);
      if (btn) btn.textContent = `Importing 0 / ${links.length}…`;

      let done = 0;
      for (const productUrl of links) {
        try {
          const r = await fetch('/api/analyze-url', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ url: productUrl })
          });
          if (!r.ok) continue;
          const data = await r.json();

          // Image code — same as single-URL browser
          let imageUrls = data.imageUrls || [];
          const firstImgUrl = imageUrls.find(u => u && (u.startsWith('http') || u.startsWith('/')));
          if (firstImgUrl && firstImgUrl.startsWith('http')) {
            try {
              const fr = await fetch('/api/photos/fetch-url', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ url: firstImgUrl })
              });
              if (fr.ok) {
                const { url: localUrl } = await fr.json();
                imageUrls = [window.location.origin + localUrl, ...imageUrls.filter(u => u !== firstImgUrl)];
              }
            } catch { /* non-fatal */ }
          } else if (firstImgUrl && firstImgUrl.startsWith('/')) {
            imageUrls = [window.location.origin + firstImgUrl, ...imageUrls.filter(u => u !== firstImgUrl)];
          }

          // Save as draft
          const draft = {
            title: data.title || productUrl,
            data: { ...data, imageUrls, listingFormat: 'FIXED_PRICE', durationDays: 30,
                    fulfillmentPolicyId: '236920894018', bestOfferEnabled: true,
                    itemLocationCountry: data.itemLocationCountry || 'CN',
                    weightLbs: data.weightLbs || 32 },
            visualDescription: data.visualDescription || ''
          };
          await fetch('/api/local-drafts/save', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(draft)
          });
          done++;
          if (btn) btn.textContent = `Importing ${done} / ${links.length}…`;
          addActivity('Draft saved', data.title || productUrl);
        } catch { /* skip failed product */ }
      }

      addActivity(`Bulk import complete`, `${done} of ${links.length} saved as drafts — opening all as tabs`);
      await loadAllDraftsAsTabs();
    } catch (e) {
      toastErr(errorText(e, 'Unknown error.'), { title: 'Bulk import failed' });
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Import All'; }
    }
  }

  async function nlAiModify() {
    const input = $('nl-ai-modify-input');
    const btn   = $('nl-ai-modify-go');
    const instruction = input?.value.trim();
    if (!instruction) return;

    const payload = buildNlPayload();
    if (!payload.title && !payload.description) {
      toast('Fill in a title or description first — there is nothing here for the AI to change yet.',
            { kind: 'warning', title: 'Nothing to modify' });
      return;
    }

    if (btn) { btn.disabled = true; btn.classList.add('loading'); btn.textContent = 'Applying…'; }
    if (input) input.classList.add('loading');

    try {
      const res = await guardedFetch('/api/ai-modify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...payload, instruction })
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error(b.error || 'Modification failed');
      }
      const data = await res.json();
      fillNlForm(data);
      if (input) { input.value = ''; input.placeholder = '✓ Done — ask Claude for another change'; }
      addActivity('AI modification applied', instruction);
    } catch (e) {
      // The instruction is still in the box behind the toast, so retrying is
      // one click and nothing the seller typed is lost.
      toastErr(errorText(e, 'Unknown error.'), { title: "AI couldn't apply that change" });
    } finally {
      if (btn) { btn.disabled = false; btn.classList.remove('loading'); btn.textContent = 'Apply'; }
      if (input) input.classList.remove('loading');
    }
  }

  async function nlAnalyzeUrl() {
    const input = $('nl-url-input');
    const btn   = $('nl-url-go');
    const url   = input?.value.trim();
    if (!url) return;

    // Validate it looks like a URL
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
      input.value = 'https://' + url;
    }

    input?.classList.add('loading');
    if (btn) { btn.disabled = true; btn.textContent = 'Analyzing…'; }
    $('nl-ai-status')?.classList.remove('hidden');
    $('nl-ai-done')?.classList.add('hidden');
    $('nl-ai-error')?.classList.add('hidden');
    if ($('nl-ai-msg')) $('nl-ai-msg').textContent = 'Reading page and analyzing with AI…';

    try {
      const res = await guardedFetch('/api/analyze-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: input.value.trim() })
      });
      if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        throw new Error(b.error || 'URL analysis failed');
      }
      const data = await res.json();

      nlClearAllPhotoSlots();
      fillNlForm(data);
      window._nlVisualDescription = data.visualDescription || '';
      window._nlImageType = 'webpage_screenshot';
      if (data.title) nlLoadSoldComps(data.title);

      // Use only the first product image — show in preview and remove background
      const firstImgUrl = (data.imageUrls || []).find(u => u && (u.startsWith('http') || u.startsWith('/')));
      if (firstImgUrl) {
        const absUrl = firstImgUrl.startsWith('/') ? window.location.origin + firstImgUrl : firstImgUrl;
        // Show in main product photo preview
        const previewImg = $('nl-preview-img');
        if (previewImg) previewImg.src = absUrl;
        $('nl-drop-zone')?.classList.add('hidden');
        $('nl-preview-wrap')?.classList.remove('hidden');
        // Also kick off background removal → Picture 1
        nlAutoRemoveBg(absUrl);
      }

      const activeTab = draftTabs.find(t => t.id === activeDraftTabId);
      if (activeTab) { activeTab.title = data.title || 'New Draft'; renderDraftTabs(); }

      $('nl-ai-status')?.classList.add('hidden');
      $('nl-ai-done')?.classList.remove('hidden');
      addActivity('URL analyzed', data.title || input.value);
    } catch (err) {
      $('nl-ai-status')?.classList.add('hidden');
      $('nl-ai-error')?.classList.remove('hidden');
      if ($('nl-ai-error-msg')) $('nl-ai-error-msg').textContent = `URL analysis failed: ${errorText(err)}`;
      addActivity('URL analysis failed', errorText(err));
    } finally {
      input?.classList.remove('loading');
      if (btn) { btn.disabled = false; btn.textContent = 'Analyze'; }
    }
  }

  // Show the "Connect to Terapeak" prompt in the sold-comps bar unless a session is
  // already connected. Runs when the AI Listing view opens.
  async function nlRefreshSoldCompsConnect() {
    const connect = $('nl-sold-comps-connect');
    if (!connect) return;
    try {
      const s = await fetch('/api/terapeak/status').then(r => r.json());
      connect.classList.toggle('hidden', !!s.connected);
    } catch { /* leave the prompt visible if status can't be checked */ }
  }

  // Kick off the Terapeak browser login from the bar's Connect button, then poll until
  // the login window closes and hide the prompt once connected.
  async function nlSoldCompsConnect() {
    const btn = $('nl-sold-comps-connect-btn');
    const msg = $('nl-sold-comps-connect-msg');
    if (!btn) return;
    btn.disabled = true;
    if (msg) msg.textContent = 'Opening the eBay login window…';
    try {
      const data = await fetch('/api/terapeak/connect', { method: 'POST' }).then(r => r.json());
      if (msg) msg.textContent = data.message || 'Log in to eBay in the window that opened (Alt+Tab if you don\'t see it), then come back here.';
      const poll = setInterval(async () => {
        const s = await fetch('/api/terapeak/status').then(r => r.json()).catch(() => null);
        if (s && !s.loginInProgress) {
          clearInterval(poll);
          btn.disabled = false;
          if (s.connected) {
            $('nl-sold-comps-connect')?.classList.add('hidden');
            if (msg) msg.textContent = '';
                  } else if (msg) {
            msg.textContent = s.lastError || 'Login was not completed. Try again.';
          }
        }
      }, 3000);
    } catch (err) {
      btn.disabled = false;
      if (msg) msg.textContent = `Connect failed: ${errorText(err)}`;
    }
  }

  async function nlLoadSoldComps(itemName) {
    const strip    = $('nl-sold-comps-strip');
    const summary  = $('nl-sold-comps-summary');
    const link     = $('nl-sold-comps-link');
    const terapeak = $('nl-sold-comps-terapeak');
    const stats    = $('nl-sold-comps-stats');
    const list     = $('nl-sold-comp-list');
    if (!strip || !summary || !link || !terapeak || !stats || !list) return;

    strip.classList.remove('hidden');
    strip.classList.add('loading');
    summary.textContent = '';
    stats.classList.add('hidden');
    list.innerHTML = '';
    link.classList.add('hidden');
    terapeak.classList.add('hidden');

    try {
      // Same costing ride-along as the Market Research panel — see runSoldResearch.
      const params = new URLSearchParams({ q: itemName });
      const nlCost = thNum('nl-unit-cost');
      const nlAsk  = thNum('nl-price');
      if (nlCost > 0) params.set('cost', String(nlCost));
      if (nlAsk  > 0) params.set('ask',  String(nlAsk));
      const nlBuyerShipping = thNum('nl-buyer-shipping');
      if (nlBuyerShipping > 0) params.set('buyerShipping', String(nlBuyerShipping));

      const res  = await fetch(`/api/sold-comps?${params.toString()}`);
      const data = await res.json().catch(() => ({}));
      strip.classList.remove('loading');

      if (data.fallbackUrl) { link.href = data.fallbackUrl; link.classList.remove('hidden'); }
      if (data.terapeakUrl) { terapeak.href = data.terapeakUrl; terapeak.classList.remove('hidden'); }

      if (!res.ok || !data.count) {
        summary.textContent = ''; // links alone are enough — no need to announce the absence of data
        return;
      }

      $('nl-sold-comps-connect')?.classList.add('hidden');   // real data — drop the connect prompt
      // Four gross stats and no net is how a seller talks themselves into the median. Say what the
      // median is actually worth, right where they read it.
      const atMedian = data.pricing?.quotes?.median;
      summary.textContent = atMedian
        ? `Recently sold — "${itemName}" · list at the ${moneyExact(data.median)} median and you `
          + (atMedian.hasCostBasis
              ? `keep ${moneyExact(atMedian.netProfit)} after fees`
                + (data.pricing.minimumOfferPrice ? `, floor ${moneyExact(data.pricing.minimumOfferPrice)}` : '')
              : `bank ${moneyExact(atMedian.netProceeds)} after fees`)
        : `Recently sold — "${itemName}"`;
      $('nl-sold-comps-stat-avg').textContent    = `$${data.average.toFixed(2)}`;
      $('nl-sold-comps-stat-median').textContent = `$${data.median.toFixed(2)}`;
      $('nl-sold-comps-stat-min').textContent     = `$${data.min.toFixed(2)}`;
      $('nl-sold-comps-stat-max').textContent     = `$${data.max.toFixed(2)}`;
      $('nl-sold-comps-stat-count').textContent   = data.count;
      stats.classList.remove('hidden');

      // Show the 7 most recent sold items, newest first, centered in the bar
      const sorted = [...data.items].sort((a, b) => new Date(b.soldDate) - new Date(a.soldDate)).slice(0, 7);
      list.innerHTML = sorted.map(it => `
        <a class="nl-sold-comp-row" href="${it.url}" target="_blank" rel="noopener">
          ${it.imageUrl
            ? `<img class="nl-sold-comp-thumb" src="${it.imageUrl}" alt="" loading="lazy" />`
            : `<span class="nl-sold-comp-thumb nl-sold-comp-thumb-empty">📦</span>`}
          <span class="nl-sold-comp-title">${esc(it.title)}</span>
          <span class="nl-sold-comp-date">${new Date(it.soldDate).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</span>
          <span class="nl-sold-comp-price">$${it.price.toFixed(2)}</span>
        </a>`).join('');
    } catch (err) {
      strip.classList.remove('loading');
      summary.textContent = `Sold-comp lookup failed: ${errorText(err)}`;
    }
  }

  async function nlQuickFillByName() {
    const input    = $('nl-quickfill-input');
    const btn      = $('nl-quickfill-go');
    const itemName = input?.value.trim();
    if (!itemName) return;

    input?.classList.add('loading');
    if (btn) { btn.disabled = true; btn.textContent = 'Researching…'; }
    $('nl-ai-status')?.classList.remove('hidden');
    $('nl-ai-done')?.classList.add('hidden');
    $('nl-ai-error')?.classList.add('hidden');
    if ($('nl-ai-msg')) $('nl-ai-msg').textContent = 'Researching the product and finding photos online…';

    nlLoadSoldComps(itemName); // runs in parallel — independent of the listing fill below

    hideFailure('nl-failure');
    try {
      const { ok, data, failure } = await callApi('/api/quick-fill', {
        method: 'POST', body: { itemName }, timeoutMs: AI_TIMEOUT_MS,
      });

      if (!ok) {
        $('nl-ai-status')?.classList.add('hidden');
        // The typed name is left in the box on purpose, so Try again costs nothing.
        renderFailure('nl-failure', failure, { onRetry: () => nlQuickFillByName() });
        addActivity('Quick-fill failed', failure?.headline || 'Unknown error');
        return;
      }

      nlClearAllPhotoSlots();
      fillNlForm(data);
      scheduleAutosave();

      // Quick-fill searches the web for a product photo and often finds none. That used to be a log
      // line the seller never saw, leaving them a complete listing with an empty photo grid.
      if (!(data.imageUrls || []).some(Boolean)) {
        nlPhotoNotice('No product photo could be found online for this item. Add one before publishing — '
                    + 'a listing with no picture rarely sells.');
      }
      window._nlVisualDescription = data.visualDescription || '';
      window._nlImageType = 'product_photo';

      // Condition-aware: NEW items may use a found stock photo; USED items must show the seller's
      // REAL unit (representative-photo library or a prompt) — never a stock image.
      const foundUrls = (data.imageUrls || []).filter(u => u && (u.startsWith('http') || u.startsWith('/')));
      const absUrls = foundUrls.map(u => u.startsWith('/') ? window.location.origin + u : u);
      await nlApplyResearchPhotos(data, absUrls, itemName);

      const activeTab = draftTabs.find(t => t.id === activeDraftTabId);
      if (activeTab) { activeTab.title = data.title || 'New Draft'; renderDraftTabs(); }

      $('nl-ai-status')?.classList.add('hidden');
      $('nl-ai-done')?.classList.remove('hidden');
      addActivity('Quick-fill complete', data.title || itemName);
      if (input) { input.value = ''; }
    } catch (err) {
      $('nl-ai-status')?.classList.add('hidden');
      renderFailure('nl-failure', {
        kind: 'Unknown',
        headline: 'The app hit an unexpected error after quick-fill',
        whatHappened: 'The listing may be partly filled in; check the fields before publishing.',
        whatToDo: 'Try again, or fill in what is missing by hand.',
        retryable: true, workPreserved: true, technical: technicalDetail(err),
      }, { onRetry: () => nlQuickFillByName() });
      addActivity('Quick-fill failed', technicalDetail(err));
    } finally {
      input?.classList.remove('loading');
      if (btn) { btn.disabled = false; btn.textContent = 'Auto-Fill'; }
    }
  }

  // Condition-aware photo application for AI research results. NEW items may use a found stock
  // photo; USED items must show the seller's REAL unit — so pull from the representative-photo
  // library for the model, or prompt the seller to add a real photo. Never a stock image on used.
  async function nlApplyResearchPhotos(data, absUrls, nameHint) {
    if (nlIsUsedListing(data, nameHint)) {
      // No library set for this model yet — refuse the stock image, prompt for a real photo.
      const applied = await nlApplyUsedLibraryPhotos(data, nameHint);
      if (!applied) nlPromptUsedPhoto();
      return;
    }

    // NEW item — a found stock photo is acceptable (existing behavior).
    if (absUrls[0]) {
      const previewImg = $('nl-preview-img');
      if (previewImg) previewImg.src = absUrls[0];
      $('nl-drop-zone')?.classList.add('hidden');
      $('nl-preview-wrap')?.classList.remove('hidden');
      nlAutoRemoveBg(absUrls[0]);
      absUrls.slice(1).forEach((u, i) => setPhotoSlotUrl(i + 1, u));
    } else {
      addActivity('No photos found online', 'Drop or paste a photo manually, or try a more specific item name');
    }
  }

  // A listing is treated as USED — stock photos not allowed — when the AI (or the form) says so,
  // or when the item name itself says "used".
  function nlIsUsedListing(data, nameHint) {
    const cond = (data.condition || $('nl-condition')?.value || '').toUpperCase();
    return cond.startsWith('USED') || cond === 'FOR_PARTS' || /\bused\b/i.test(nameHint || data.title || '');
  }

  // Pull the seller's representative photos for this model out of the photo library. Returns true
  // when real photos were applied (preview + slots + disclosure), false when no library exists yet.
  async function nlApplyUsedLibraryPhotos(data, nameHint) {
    try {
      const q = new URLSearchParams({ model: data.model || '', title: data.title || nameHint || '' });
      const lib = await fetch('/api/photos/library/for-listing?' + q).then(r => r.json()).catch(() => ({}));
      if (lib && lib.matched && (lib.photos || []).length) {
        const urls = lib.photos.map(u => u.startsWith('/') ? window.location.origin + u : u);
        const previewImg = $('nl-preview-img');
        if (previewImg) previewImg.src = urls[0];
        $('nl-drop-zone')?.classList.add('hidden');
        $('nl-preview-wrap')?.classList.remove('hidden');
        urls.forEach((u, i) => setPhotoSlotUrl(i, u));
        if (lib.disclosure) nlAppendDisclosure(lib.disclosure);
        addActivity('Used item — pulled your library photos', `${urls.length} real photo(s) for ${lib.modelKey}`);
        return true;
      }
    } catch (e) { /* non-fatal */ }
    return false;
  }

  // Used item with no library photos: clear any stock image, reveal + highlight the drop zone so
  // the seller adds a real photo of their actual unit.
  function nlPromptUsedPhoto() {
    $('nl-preview-wrap')?.classList.add('hidden');
    const drop = $('nl-drop-zone');
    if (drop) {
      drop.classList.remove('hidden');
      drop.classList.add('field-flagged');
      setTimeout(() => drop.classList.remove('field-flagged'), 5000);
    }
    addActivity('Used item — add a real photo',
      "Stock photos aren't allowed for used items. Drop a photo of your actual unit (or add it to this model's photo library).");
  }

  // Append the representative-photo disclosure to the plain-text description once.
  function nlAppendDisclosure(text) {
    const t = $('nl-desc-text');
    if (!t || !text || t.value.includes(text)) return;
    t.value = (t.value ? t.value + '\n\n' : '') + text;
    if (typeof nlUpdateDescCount === 'function') nlUpdateDescCount();
  }

  async function nlAnalyze() {
    if (!nlImageBase64) return;

    $('nl-ai-status')?.classList.remove('hidden');
    $('nl-ai-done')?.classList.add('hidden');
    $('nl-ai-error')?.classList.add('hidden');
    hideFailure('nl-failure');
    if ($('nl-ai-msg')) $('nl-ai-msg').textContent = 'Analyzing with AI…';

    try {
      const { ok, failure, data } = await callApi('/api/analyze', {
        method: 'POST',
        body: { imageBase64: nlImageBase64, mimeType: nlMimeType },
        timeoutMs: AI_TIMEOUT_MS,
      });

      if (!ok) {
        // The uploaded photo is still held in nlImageBase64, so Try again re-runs the analysis
        // without asking the seller to find and drop the file a second time.
        $('nl-ai-status')?.classList.add('hidden');
        renderFailure('nl-failure', failure, { onRetry: () => nlAnalyze() });
        addActivity('AI analysis failed', failure?.headline || 'Unknown error');
        return;
      }

      fillNlForm(data);
      scheduleAutosave();
      window._nlVisualDescription = data.visualDescription || '';
      window._nlImageType = data.imageType || 'webpage_screenshot';
      if (data.title) nlLoadSoldComps(data.title);

      // Reset photo slots before populating from analysis result
      nlClearAllPhotoSlots();

      const isProductPhoto = (data.imageType || '') === 'product_photo';
      // Condition-aware, same gate as the Auto-Fill path: images scraped off a screenshot are
      // stock/online photos. NEW items may use one; USED items must show the seller's REAL unit,
      // so pull from the photo library or prompt for a real photo. An uploaded product photo IS
      // the seller's own unit, so it stays allowed either way.
      const usedNeedsRealPhoto = !isProductPhoto && nlIsUsedListing(data);
      let firstPhotoUrl = null;

      // Every branch below used to swallow its failure as `catch { /* non-fatal */ }`. It is not
      // non-fatal: the analysis carries on, the photo grid stays empty, and the seller finds out when
      // a photoless listing fails to sell. The analysis really has succeeded, so these are notices
      // rather than failure panels — but they are shown, and they do not fade away.
      if (isProductPhoto && nlImageBase64) {
        // Clean product photo — save the uploaded image directly
        const saved = await callApi('/api/photos/save-uploaded', {
          method: 'POST',
          body: { imageBase64: nlImageBase64, mimeType: nlMimeType || 'image/jpeg' },
        });
        if (saved.ok && saved.data?.url) { firstPhotoUrl = saved.data.url; nlAddPhotoRow(saved.data.url); }
        else nlPhotoNotice('Your photo could not be saved — add it again before publishing. '
                         + (saved.failure?.whatToDo || ''));
      } else if (usedNeedsRealPhoto) {
        const applied = await nlApplyUsedLibraryPhotos(data);
        if (!applied) nlPromptUsedPhoto();
      } else if ((data.imageUrls || []).length > 0) {
        // Only use the first product image — one clean photo is all we need
        const firstUrl = (data.imageUrls || []).find(u => u && (u.startsWith('http') || u.startsWith('/')));
        if (firstUrl) {
          if (firstUrl.startsWith('/')) {
            firstPhotoUrl = window.location.origin + firstUrl;
          } else {
            const fetched = await callApi('/api/photos/fetch-url', { method: 'POST', body: { url: firstUrl } });
            if (fetched.ok && fetched.data?.url) firstPhotoUrl = window.location.origin + fetched.data.url;
            else nlPhotoNotice('The product photo from that page could not be downloaded — add a photo '
                             + 'before publishing. ' + (fetched.failure?.whatToDo || ''));
          }
        }
      } else {
        nlPhotoNotice('No photo came back with this analysis. Add at least one before publishing — '
                    + 'listings without pictures rarely sell.');
      }

      // Update the active tab title
      const activeTab = draftTabs.find(t => t.id === activeDraftTabId);
      if (activeTab) { activeTab.title = data.title || 'New Draft'; activeTab.saved = false; renderDraftTabs(); }
      $('nl-ai-status')?.classList.add('hidden');
      $('nl-ai-done')?.classList.remove('hidden');
      addActivity('AI analysis complete', data.title || 'Form filled — review before publishing.');

      // Auto remove background — use first fetched photo, or fall back to the uploaded image
      // directly. Skipped on the used-item path: library photos are already curated, and the
      // uploaded screenshot must never end up as the listing photo.
      if (!usedNeedsRealPhoto) {
        if (firstPhotoUrl) nlAutoRemoveBg(firstPhotoUrl);
        else if (nlImageBase64) nlAutoRemoveBgFromBase64(nlImageBase64, nlMimeType || 'image/jpeg');
      }
    } catch (err) {
      // Reached only on a bug in the code above — callApi itself never throws.
      $('nl-ai-status')?.classList.add('hidden');
      renderFailure('nl-failure', {
        kind: 'Unknown',
        headline: 'The app hit an unexpected error after the analysis',
        whatHappened: 'The listing may be partly filled in; check the fields before publishing.',
        whatToDo: 'Try the analysis again, or fill in what is missing by hand.',
        retryable: true,
        workPreserved: true,
        technical: technicalDetail(err),
      }, { onRetry: () => nlAnalyze() });
      addActivity('AI analysis failed', technicalDetail(err));
    }
  }

  // A photo problem that does not stop the listing but must not be missed either. Deliberately does
  // not auto-hide: a notice that disappears after four seconds is how a listing reaches eBay with no
  // picture and nobody remembers being told.
  function nlPhotoNotice(message, tone = 'warn') {
    const el = $('nl-photo-upload-status');
    if (!el) return;
    el.classList.remove('hidden');
    el.className = 'nl-photo-upload-status ' + tone;
    el.textContent = message;
  }

  async function nlGeneratePhotos(title, description, visualDescription = '', imageType = '') {
    let mode;
    try {
      const modeRes = await fetch('/api/image-gen/mode').then(r => r.json());
      mode = modeRes.mode || 'disabled';
    } catch { return; }

    const section   = $('nl-photos-section');
    const grid      = $('nl-photos-grid');
    const spinner   = $('nl-photos-generating');
    const errorEl   = $('nl-photos-error');
    const errorMsg  = $('nl-photos-error-msg');
    const statusBar = $('nl-imggen-status-bar');
    const statusTxt = $('nl-imggen-status-text');
    const setupLink = $('nl-imggen-setup-link');

    if (!section || !grid) return;

    const setStatus = (text, showSetup = false) => {
      if (statusBar) statusBar.classList.remove('hidden');
      if (statusTxt) statusTxt.textContent = text;
      if (setupLink) setupLink.classList.toggle('hidden', !showSetup);
    };

    if (mode === 'disabled') {
      section.classList.remove('hidden');
      setStatus('Image generation is disabled — enable it in Settings → Image Generation', true);
      return;
    }

    section.classList.remove('hidden');
    spinner?.classList.add('hidden');
    grid.innerHTML = '';
    errorEl?.classList.add('hidden');

    // For local SD, detect server first so we show a clear "not running" status
    if (mode === 'local_sd') {
      setStatus('Checking for local image server...');
      try {
        const detect = await fetch('/api/image-gen/detect').then(r => r.json());
        if (!detect.a1111Online && !detect.comfyOnline) {
          // Neither default port; also test configured endpoint in case it's a custom port
          const test = await fetch('/api/image-gen/test').then(r => r.json());
          if (!test.online) {
            setStatus('Local image server not detected — start your server, then click Regenerate', true);
            addActivity('Image server not detected', 'Start AUTOMATIC1111 or ComfyUI, then click Regenerate.');
            return;
          }
        }
      } catch { /* detection failed — attempt generation anyway */ }
      setStatus('Generating images locally...');
    } else {
      setStatus('Generating images with DALL-E...');
    }

    spinner?.classList.remove('hidden');


    try {
      const isProductPhoto = (imageType || window._nlImageType || '') === 'product_photo';
      const reqBody = { title, description, visualDescription, imageType: imageType || window._nlImageType || '' };
      if (isProductPhoto && nlImageBase64) {
        reqBody.imageBase64 = nlImageBase64;
        reqBody.mimeType    = nlMimeType || 'image/jpeg';
      }
      const res = await fetch('/api/generate-photos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(reqBody)
      });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error || JSON.stringify(body));

      const labels = ['Front View', 'Angle View', 'Detail View'];
      (body.urls || []).forEach((url, i) => {
        const wrap = document.createElement('div');
        wrap.className = 'nl-photo-thumb-wrap';
        const label = labels[i] || ('Photo ' + (i + 1));
        wrap.title = 'Click to add ' + label + ' to listing';
        const img = document.createElement('img');
        img.src = esc(url); img.alt = 'AI generated ' + esc(label); img.loading = 'lazy';
        img.addEventListener('click', e => { e.stopPropagation(); showLightbox(url); });
        wrap.appendChild(img);
        wrap.insertAdjacentHTML('beforeend',
          '<div class="nl-photo-thumb-badge">✓</div>'
          + '<div class="nl-photo-thumb-label">' + esc(label) + '</div>');

        wrap.addEventListener('click', () => {
          const alreadyAdded = nlCollectPhotoUrls().includes(url);
          if (!alreadyAdded) {
            nlAddPhotoRow(url);
            wrap.classList.add('selected');
          } else {
            // Remove this URL from whichever slot holds it
            const grid = $('nl-photo-grid');
            if (grid) {
              grid.querySelectorAll('.nl-photo-slot.has-image').forEach(slot => {
                if (slot.dataset.url === url) clearPhotoSlot(parseInt(slot.dataset.slotIndex));
              });
            }
            wrap.classList.remove('selected');
          }
        });

        nlAddPhotoRow(url);
        wrap.classList.add('selected');
        grid.appendChild(wrap);
      });

      const count = (body.urls || []).length;
      setStatus(count + ' image' + (count === 1 ? '' : 's') + ' generated');
      addActivity('AI photos generated', count + ' product photos added to listing.');
    } catch (err) {
      spinner?.classList.add('hidden');
      setStatus('Image generation failed — listing can still be submitted');
      errorEl?.classList.remove('hidden');
      if (errorMsg) errorMsg.textContent = errorText(err);
      addActivity('AI photo generation failed', errorText(err));
      return;
    }

    spinner?.classList.add('hidden');
  }

  function fillNlForm(d) {
    nlSetSku(d.sku || '');
    set('nl-title', d.title || '');
    set('nl-subtitle', d.subtitle || '');
    set('nl-category', d.category || '');
    set('nl-category-id', d.categoryId || '');
    nlSyncCategoryDisplay();
    set('nl-secondary-category-id', d.secondaryCategoryId || '');
    set('nl-condition', d.condition || 'USED_EXCELLENT');
    set('nl-condition-desc', d.conditionDescription || '');
    set('nl-brand', d.brand || '');
    set('nl-mpn', d.mpn || '');
    set('nl-upc', d.upc || '');
    set('nl-ean', d.ean || '');
    set('nl-isbn', d.isbn || '');
    descSetHtml('nl', d.description || '');   // all three tabs, landing on the readable one
    set('nl-price', d.price || '');
    set('nl-quantity', d.quantity || 1);
    set('nl-qty-limit', d.quantityLimitPerBuyer || '');
    set('nl-package-type', d.packageType || 'PACKAGE_THICK_ENVELOPE');
    set('nl-weight-lbs', d.weightLbs || 0);
    set('nl-weight-oz', d.weightOz || 0);
    set('nl-length', d.packageLengthIn || '');
    set('nl-width', d.packageWidthIn || '');
    set('nl-height', d.packageHeightIn || '');
    set('nl-handling-time', d.handlingTimeBusinessDays || 1);
    if (d.itemLocationPostalCode) set('nl-location-zip', d.itemLocationPostalCode);
    set('nl-location-country', d.itemLocationCountry || 'US');
    set('nl-charity-pct', d.charityDonationPercentage || 0);
    set('nl-charity-id', d.charityId || '');

    const bestOffer = !!d.bestOfferEnabled;
    if ($('nl-best-offer')) $('nl-best-offer').checked = bestOffer;
    nlToggleBestOffer(bestOffer);
    if (bestOffer) {
      set('nl-auto-accept', '');
      set('nl-auto-decline', '');
    }
    if ($('nl-private')) $('nl-private').checked = !!d.privateListing;

    if ($('nl-specifics-list')) $('nl-specifics-list').innerHTML = '';
    if (d.itemSpecifics) Object.entries(d.itemSpecifics).forEach(([k, v]) => nlAddSpecificRow(k, v));

    nlClearAllPhotoSlots();
    // Only use the first product image — skip webpage screenshots (saved-photo paths)
    const firstImg = (d.imageUrls || []).find(u => u && (u.startsWith('http') || u.startsWith('/')));
    if (firstImg) {
      const abs = firstImg.startsWith('/') ? window.location.origin + firstImg : firstImg;
      nlAutoRemoveBg(abs);
    }

    nlUpdateCharCount('nl-title', 'nl-title-count', 80);
    nlUpdateCharCount('nl-subtitle', 'nl-subtitle-count', 55);
    nlSyncDescPreview();
    nlUpdateDescCount();

    // The listing has just been written by AI — this is the moment to say what eBay still needs,
    // while the seller is looking at it, rather than after a failed publish.
    nlRdOverride = false;
    nlRunReadiness(true);
    scheduleTakeHome('nl');   // and what the AI's suggested price is actually worth
  }

  function buildNlPayload() {
    descCommitText('nl');   // words typed on the text tab, before the HTML field is read
    return {
      title: $('nl-title')?.value || '',
      // Carried, never invented here. A draft made from a won lot arrives with the SKU its deal
      // card is filed under, and that is what lets the publish record what the item cost. A listing
      // typed from scratch sends an empty string, and the server publishes without a SKU.
      sku: ($('nl-sku')?.value || '').trim(),
      subtitle: $('nl-subtitle')?.value || '',
      // Once a category is chosen the search box is emptied and the name moves to the chip beside
      // it, so reading the input alone sent a blank name on every finished listing. The chip is
      // read as the fallback: the ID is what publishes, but the name is what gets remembered and
      // shown back the next time an item like this is listed.
      category: $('nl-category')?.value || nlSelectedCategoryName(),
      categoryId: $('nl-category-id')?.value || '',
      secondaryCategoryId: $('nl-secondary-category-id')?.value || '',
      condition: $('nl-condition')?.value || 'USED_EXCELLENT',
      conditionDescription: $('nl-condition-desc')?.value || '',
      brand: $('nl-brand')?.value || '',
      mpn: $('nl-mpn')?.value || '',
      upc: $('nl-upc')?.value || '',
      ean: $('nl-ean')?.value || '',
      isbn: $('nl-isbn')?.value || '',
      description: $('nl-description')?.value || '',
      price: parseFloat($('nl-price')?.value) || 0,
      quantity: parseInt($('nl-quantity')?.value, 10) || 1,
      quantityLimitPerBuyer: parseInt($('nl-qty-limit')?.value, 10) || null,
      bestOfferEnabled: $('nl-best-offer')?.checked || false,
      autoAcceptPrice: $('nl-best-offer')?.checked ? parseFloat($('nl-auto-accept')?.value) || null : null,
      autoDeclinePrice: $('nl-best-offer')?.checked ? parseFloat($('nl-auto-decline')?.value) || null : null,
      packageType: $('nl-package-type')?.value || 'PACKAGE_THICK_ENVELOPE',
      weightLbs: parseFloat($('nl-weight-lbs')?.value) || 0,
      weightOz: parseFloat($('nl-weight-oz')?.value) || 0,
      packageLengthIn: parseFloat($('nl-length')?.value) || 0,
      packageWidthIn: parseFloat($('nl-width')?.value) || 0,
      packageHeightIn: parseFloat($('nl-height')?.value) || 0,
      handlingTimeBusinessDays: parseInt($('nl-handling-time')?.value, 10) || 1,
      itemLocationPostalCode: $('nl-location-zip')?.value || '',
      itemLocationCountry: $('nl-location-country')?.value || 'US',
      privateListing: $('nl-private')?.checked || false,
      charityDonationPercentage: parseInt($('nl-charity-pct')?.value, 10) || 0,
      charityId: $('nl-charity-id')?.value || '',
      listingFormat: $('nl-format')?.value || 'FIXED_PRICE',
      durationDays: parseInt($('nl-duration')?.value, 10) || 7,
      itemSpecifics: nlCollectSpecifics(),
      imageUrls: nlCollectPhotoUrls(),
      fulfillmentPolicyId: $('nl-fulfillment-sel')?.value || null,
      paymentPolicyId:     $('nl-payment-sel')?.value     || null,
      returnPolicyId:      $('nl-return-sel')?.value       || null,
    };
  }

  function nlCollectSpecifics() {
    const out = {};
    // Free-text rows first, so a value that has been matched onto one of eBay's own aspects
    // wins over a stale row the seller typed under a different name for the same field.
    document.querySelectorAll('#nl-specifics-list .specific-row').forEach(row => {
      const [k, v] = row.querySelectorAll('input');
      if (k?.value.trim()) out[k.value.trim()] = v?.value.trim() || '';
    });
    Object.assign(out, nlCollectAspectValues());
    return out;
  }

  // ── Listing Readiness ────────────────────────────────────────────
  //
  // eBay does not say what a category requires until a publish fails. This asks it up front
  // (POST /api/listing/readiness → Taxonomy get_item_aspects_for_category) and turns the answer
  // into fields, so the seller fills in a labelled "Chipset/GPU Model" dropdown instead of
  // guessing at a blank name/value row and finding out minutes later.
  //
  // Everything here is advisory. The seller's own values are never overwritten, suggestions are
  // applied only when clicked, and a blocker warns rather than locks — the app's opinion of a
  // listing is not eBay's, and it is the seller's account.

  let nlRdState    = null;   // last result from the server
  let nlRdTimer    = null;   // debounce handle
  let nlRdSeq      = 0;      // race guard: only the newest response may render
  let nlRdOverride = false;  // seller chose to publish past the blockers

  // Must match ListingReadinessAnalyzer.AspectFieldId — the fix list on one side generates
  // these, the fields on the other side carry them, and a mismatch silently breaks "Fix".
  function nlAspectFieldId(name) {
    let slug = String(name || '').toLowerCase().replace(/[^a-z0-9]/g, '-');
    while (slug.includes('--')) slug = slug.replace(/--/g, '-');
    return 'nl-aspect-' + slug.replace(/^-+/, '').replace(/-+$/, '');
  }

  function nlCollectAspectValues() {
    const out = {};
    document.querySelectorAll('#nl-aspects-panel [data-aspect-name]').forEach(el => {
      const name = el.dataset.aspectName;
      const val  = (el.value || '').trim();
      if (name && val) out[name] = val;
    });
    return out;
  }

  function initListingReadiness() {
    on('nl-rd-toggle', 'click', () => {
      const list = $('nl-rd-list');
      const btn  = $('nl-rd-toggle');
      if (!list || !btn) return;
      const open = list.hidden;
      list.hidden = !open;
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      btn.classList.toggle('is-open', open);
    });
    on('nl-aspects-refresh', 'click', () => nlRunReadiness(true));
    on('nl-aspects-autofill', 'click', nlAutofillAspects);
    on('nl-rd-fill', 'click', nlFillEverything);

    // Re-check as the listing is written. Debounced, because these fire per keystroke.
    ['nl-title', 'nl-price', 'nl-brand', 'nl-mpn', 'nl-upc', 'nl-ean', 'nl-isbn',
     'nl-desc-text', 'nl-description', 'nl-condition-desc', 'nl-location-zip', 'nl-weight-lbs']
      .forEach(id => on(id, 'input', () => nlRunReadiness()));
    ['nl-condition', 'nl-best-offer'].forEach(id => on(id, 'change', () => nlRunReadiness()));

    // The category picker writes the hidden input directly, so it announces itself (see
    // bindCategorySearch). A category change is the one edit that changes which specifics
    // exist at all, so it re-checks immediately rather than on the debounce.
    on('nl-category-id', 'change', () => nlRunReadiness(true));
  }

  function nlResetReadiness() {
    nlRdState = null;
    nlRdOverride = false;
    if (nlRdTimer) { clearTimeout(nlRdTimer); nlRdTimer = null; }
    ['nl-aspects-required', 'nl-aspects-recommended', 'nl-aspects-optional']
      .forEach(id => { const el = $(id); if (el) el.innerHTML = ''; });
    const optWrap = $('nl-aspects-optional-wrap'); if (optWrap) optWrap.hidden = true;
    const badge = $('nl-aspects-badge'); if (badge) badge.hidden = true;
    const bar = $('nl-readiness'); if (bar) bar.hidden = true;
    const fill = $('nl-aspects-autofill'); if (fill) fill.hidden = true;
    const fillRow = $('nl-rd-fill-row'); if (fillRow) fillRow.hidden = true;
    const status = $('nl-aspects-status');
    if (status) {
      status.textContent = 'Pick a category and eBay’s required Item Specifics appear here.';
      status.className = 'asp-status';
    }
  }

  async function nlRunReadiness(immediate = false) {
    if (nlRdTimer) { clearTimeout(nlRdTimer); nlRdTimer = null; }
    if (!immediate) {
      nlRdTimer = setTimeout(() => nlRunReadiness(true), 600);
      return;
    }

    const overlay = $('new-listing-overlay');
    if (!overlay || overlay.classList.contains('hidden')) return;

    const seq = ++nlRdSeq;
    const bar = $('nl-readiness');
    if (bar) bar.hidden = false;

    let payload;
    try { payload = buildNlPayload(); }
    catch { return; }

    // While the plain-text tab is open, the HTML field is only synced on a tab switch, so the
    // payload's description lags behind what the seller is actually typing. The server strips
    // markup for this check anyway, so the live text is the truer input.
    const textTabActive = descActiveTab('nl') === 'text';
    if (textTabActive) {
      const plain = $('nl-desc-text')?.value || '';
      if (plain.trim()) payload.description = plain;
    }

    let data;
    try {
      const res = await fetch('/api/listing/readiness', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      data = await res.json();
    } catch (err) {
      // A readiness check that fails must never be in the way of listing.
      if (seq !== nlRdSeq) return;
      const grade = $('nl-rd-grade'), headline = $('nl-rd-headline');
      if (grade)    grade.textContent = 'Check unavailable';
      if (headline) headline.textContent = 'Couldn’t reach the app for the pre-publish check — publishing still works.';
      // The offers came from that answer; leaving the button up would promise values nobody has.
      const fillRow = $('nl-rd-fill-row'); if (fillRow) fillRow.hidden = true;
      return;
    }

    if (seq !== nlRdSeq) return;   // a newer edit already asked; this answer is stale
    nlRdState = data;
    nlRenderAspects(data);
    nlRenderReadiness(data);
  }

  // ── Rendering: the Item Specifics eBay actually asks for ─────────

  function nlRenderAspects(r) {
    const status = $('nl-aspects-status');
    const badge  = $('nl-aspects-badge');
    const fill   = $('nl-aspects-autofill');

    const groups = {
      required:    $('nl-aspects-required'),
      recommended: $('nl-aspects-recommended'),
      optional:    $('nl-aspects-optional'),
    };
    Object.values(groups).forEach(el => { if (el) el.innerHTML = ''; });

    const aspects = r.aspects || [];

    if (r.aspectStatus !== 'ok') {
      if (status) {
        status.textContent = r.aspectMessage || 'eBay’s Item Specifics couldn’t be checked.';
        status.className = 'asp-status ' + (r.aspectStatus === 'no_category' ? 'is-hint' : 'is-warn');
      }
      if (badge) badge.hidden = true;
      if (fill)  fill.hidden = true;
      const optWrap = $('nl-aspects-optional-wrap'); if (optWrap) optWrap.hidden = true;
      return;
    }

    if (aspects.length === 0) {
      if (status) {
        status.textContent = r.aspectMessage || 'eBay lists no Item Specifics for this category.';
        status.className = 'asp-status is-hint';
      }
      if (badge) badge.hidden = true;
      if (fill)  fill.hidden = true;
      return;
    }

    const missingRequired = aspects.filter(a => a.state === 'missing_required' || a.state === 'invalid_value').length;
    const missingRec      = aspects.filter(a => a.state === 'missing_recommended').length;
    const filled          = aspects.filter(a => a.state === 'filled').length;

    if (status) {
      status.textContent = missingRequired > 0
        ? `${missingRequired} required by eBay still to fill — ${filled} of ${aspects.length} done.`
        : missingRec > 0
          ? `All required specifics done. ${missingRec} more that buyers filter searches by.`
          : `All ${aspects.length} of eBay’s specifics for this category are filled.`;
      status.className = 'asp-status ' + (missingRequired > 0 ? 'is-blocker' : missingRec > 0 ? 'is-warn' : 'is-ok');
    }

    if (badge) {
      if (missingRequired > 0) {
        badge.textContent = missingRequired + ' required missing';
        badge.className = 'asp-summary-badge is-blocker';
        badge.hidden = false;
      } else if (missingRec > 0) {
        badge.textContent = missingRec + ' recommended empty';
        badge.className = 'asp-summary-badge is-warn';
        badge.hidden = false;
      } else {
        badge.textContent = 'complete';
        badge.className = 'asp-summary-badge is-ok';
        badge.hidden = false;
      }
      // Force the panel open the moment eBay says something is missing — a required specific
      // hidden inside a collapsed section is a required specific nobody fills.
      if (missingRequired > 0) $('nl-aspects-panel')?.setAttribute('open', '');
    }

    const fillable = r.autoFillableCount || 0;
    if (fill) {
      fill.hidden = fillable === 0;
      fill.textContent = `Fill ${fillable} from my listing`;
    }

    aspects.forEach(a => {
      const bucket = a.required ? 'required' : a.recommended ? 'recommended' : 'optional';
      groups[bucket]?.appendChild(nlAspectRow(a, bucket));
    });

    const optCount = aspects.filter(a => !a.required && !a.recommended).length;
    const optWrap  = $('nl-aspects-optional-wrap');
    const optLabel = $('nl-aspects-optional-count');
    if (optWrap)  optWrap.hidden = optCount === 0;
    if (optLabel) optLabel.textContent = optCount ? `(${optCount})` : '';

    // A value the seller typed under their own name for an eBay field now lives in that field.
    // Leaving the original row behind would send the same fact twice under two names.
    const claimed = new Set((r.customAspectNames || []).map(n => n.toLowerCase()));
    document.querySelectorAll('#nl-specifics-list .specific-row').forEach(row => {
      const key = row.querySelector('input')?.value.trim();
      if (key && !claimed.has(key.toLowerCase())) row.remove();
    });
  }

  function nlAspectRow(a, bucket) {
    const wrap = document.createElement('div');
    wrap.className = 'asp-row is-' + bucket + (a.state === 'missing_required' || a.state === 'invalid_value' ? ' is-blocker' : '');

    const id = nlAspectFieldId(a.name);
    const pill = a.required
      ? '<span class="asp-pill is-required">Required</span>'
      : a.recommended ? '<span class="asp-pill is-rec">Buyers filter by this</span>' : '';

    const renamed = a.matchedFromKey
      ? `<span class="asp-renamed" title="You typed this as &quot;${esc(a.matchedFromKey)}&quot;">was “${esc(a.matchedFromKey)}”</span>`
      : '';

    // A fixed list gets a dropdown — typing anything else into a SELECTION_ONLY aspect is a
    // publish failure, so the control shouldn't allow it. Everything else is free text with
    // eBay's popular values offered as completions rather than imposed.
    let control;
    if (a.selectionOnly && !a.multiSelect && (a.values || []).length) {
      const opts = ['<option value="">— choose —</option>']
        .concat((a.values || []).map(v =>
          `<option value="${esc(v)}"${v === a.value ? ' selected' : ''}>${esc(v)}</option>`));
      control = `<select id="${id}" data-aspect-name="${esc(a.name)}" class="asp-control">${opts.join('')}</select>`;
    } else {
      const listId = id + '-list';
      const datalist = (a.values || []).length
        ? `<datalist id="${listId}">${(a.values || []).slice(0, 200).map(v => `<option value="${esc(v)}"></option>`).join('')}</datalist>`
        : '';
      const hint = a.multiSelect ? ' placeholder="Separate several with |"' : '';
      const max  = a.maxLength > 0 ? ` maxlength="${a.maxLength}"` : '';
      control = `<input id="${id}" type="text" data-aspect-name="${esc(a.name)}" class="asp-control"
                   value="${esc(a.value || '')}"${(a.values || []).length ? ` list="${listId}"` : ''}${hint}${max} />${datalist}`;
    }

    const note = a.note ? `<span class="asp-note">${esc(a.note)}</span>` : '';

    wrap.innerHTML = `
      <label class="asp-label" for="${id}">${esc(a.name)} ${pill} ${renamed}</label>
      ${control}
      <div class="asp-under">${note}</div>`;

    // The suggestion. Rendered as an offer with its source stated, never written silently —
    // an Item Specific the seller didn't choose is a claim about the item made on their behalf.
    if (a.suggestedValue && a.suggestedValue !== a.value) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'asp-suggest' + (a.suggestionConfidence === 'low' ? ' is-low' : '');
      btn.innerHTML = `Use “${esc(a.suggestedValue)}” <span class="asp-suggest-src">${esc(a.suggestionSource || '')}</span>`;
      btn.addEventListener('click', () => {
        const el = $(id);
        if (el) { el.value = a.suggestedValue; el.classList.add('asp-just-filled'); }
        nlRunReadiness();
      });
      wrap.querySelector('.asp-under')?.appendChild(btn);
    }

    wrap.querySelector('.asp-control')?.addEventListener('change', () => nlRunReadiness());
    return wrap;
  }

  // Writes the high/medium aspect suggestions into their fields and says how many landed.
  // Deliberately side-effect-free beyond the fields themselves — the activity line and the
  // re-check belong to whoever asked, so filling everything at once reports once.
  function nlApplyAspectSuggestions() {
    const r = nlRdState;
    if (!r || !(r.aspects || []).length) return 0;
    let applied = 0;
    (r.aspects || []).forEach(a => {
      if (!a.suggestedValue) return;
      if (a.suggestionConfidence !== 'high' && a.suggestionConfidence !== 'medium') return;
      // Never overwrite something the seller supplied — unless eBay would reject it outright.
      if (a.value && a.state !== 'invalid_value') return;
      const el = $(nlAspectFieldId(a.name));
      if (!el) return;
      el.value = a.suggestedValue;
      el.classList.add('asp-just-filled');
      applied++;
    });
    return applied;
  }

  function nlAutofillAspects() {
    const applied = nlApplyAspectSuggestions();
    if (applied) {
      addActivity('Item Specifics filled', applied + ' filled from the listing’s own title, description and identifier fields');
      nlRunReadiness(true);
    }
  }

  // ── Keyword gap: the words the competition uses ──────────────────
  //
  // Everything above works from the seller's own listing. This is the one thing in the editor that
  // reads the market: POST /api/listing/search-terms searches eBay for what the seller has written,
  // counts the words in the listings Best Match puts on top and in the ones that sold, and hands
  // back the ones this title is missing with their counts attached.
  //
  // Nothing is written without a click, and the reason is not politeness. The app does not know
  // what the item is — it knows what the item's neighbours are called. "Bluetooth" ticked onto a
  // title for a thing with no Bluetooth is a not-as-described case, so every term is an offer with
  // its evidence beside it and the seller is the one who knows.

  let nlKwState   = null;
  let nlKwRunning = false;

  function initKeywordGap() {
    on('nl-kw-run', 'click', nlRunKeywordGap);
    on('nl-kw-close', 'click', () => { const p = $('nl-kw-panel'); if (p) p.hidden = true; });
    on('nl-kw-apply', 'click', nlApplySuggestedTitle);
    on('nl-kw-fill-specifics', 'click', () => nlFillMarketSpecifics(true));

    // The free-character count is live even before anything is searched: 80 characters is the only
    // free keyword space eBay gives a seller, and the commonest mistake is not spending it.
    on('nl-title', 'input', nlRenderFreeChars);
    nlRenderFreeChars();
  }

  function nlResetKeywordGap() {
    nlKwState = null;
    const panel = $('nl-kw-panel');
    if (panel) panel.hidden = true;
    const btn = $('nl-kw-run');
    if (btn) { btn.disabled = false; btn.textContent = 'Find the words buyers search'; }
    nlRenderFreeChars();
  }

  function nlRenderFreeChars() {
    const el = $('nl-kw-free');
    if (!el) return;
    const len  = ($('nl-title')?.value || '').trim().length;
    const free = Math.max(0, 80 - len);
    // Nothing to say about a title that is already full, or about an empty one — the character
    // counter beside the label covers those, and a second line saying the same thing is noise.
    el.hidden = len === 0 || free === 0;
    el.textContent = free + ' characters of free keyword space unused';
  }

  async function nlRunKeywordGap() {
    if (nlKwRunning) return;
    const title = ($('nl-title')?.value || '').trim();
    const btn   = $('nl-kw-run');

    if (!title) {
      nlKwRender({
        status: 'bad_input',
        headline: 'Write a title first',
        message: 'This searches eBay for what you have written and reads the listings that come back, so it needs a few words to search with.',
      });
      return;
    }

    nlKwRunning = true;
    if (btn) { btn.disabled = true; btn.textContent = 'Reading eBay…'; }

    try {
      const res = await fetch('/api/listing/search-terms', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          categoryId:    $('nl-category-id')?.value || '',
          brand:         $('nl-brand')?.value || '',
          mpn:           $('nl-mpn')?.value || '',
          itemSpecifics: nlCollectAspectValues(),
        }),
      });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      nlKwRender(await res.json());
    } catch (err) {
      // Two eBay calls behind this, either of which can be down. A keyword tool that fails must
      // read as "not now", not as "your title is fine".
      nlKwRender({
        status: 'error',
        headline: 'Couldn’t read eBay just now',
        message: 'The search didn’t come back, so nothing is claimed about your title either way. Try again in a moment — listing still works.',
      });
    } finally {
      nlKwRunning = false;
      if (btn) { btn.disabled = false; btn.textContent = 'Find the words buyers search'; }
    }
  }

  function nlKwRender(r) {
    nlKwState = r;
    const panel = $('nl-kw-panel');
    if (!panel) return;
    panel.hidden = false;

    const set = (id, text) => { const el = $(id); if (el) el.textContent = text || ''; };
    set('nl-kw-headline', r.headline);
    set('nl-kw-source', r.sourceLabel);

    const msg = $('nl-kw-message');
    if (msg) { msg.textContent = r.message || ''; msg.hidden = !r.message; }

    const missing = r.missing || [];
    const shared  = r.shared  || [];

    const missWrap = $('nl-kw-missing-wrap');
    const missBox  = $('nl-kw-missing');
    if (missBox) {
      missBox.innerHTML = '';
      missing.forEach(t => missBox.appendChild(nlKwChip(t, true)));
    }
    if (missWrap) missWrap.hidden = missing.length === 0;

    const sharedWrap = $('nl-kw-shared-wrap');
    const sharedBox  = $('nl-kw-shared');
    if (sharedBox) {
      sharedBox.innerHTML = '';
      shared.forEach(t => sharedBox.appendChild(nlKwChip(t, false)));
    }
    if (sharedWrap) sharedWrap.hidden = shared.length === 0;
    set('nl-kw-shared-count', shared.length ? '(' + shared.length + ')' : '');

    // The one-click title. Only offered when the server built one that differs from what is in
    // the box — the seller may already have applied it, or typed past it.
    const sugWrap = $('nl-kw-suggest-wrap');
    const built   = r.suggestedTitle || '';
    const current = ($('nl-title')?.value || '').trim();
    const showSug = built.length > 0 && built !== current && (r.addedTerms || []).length > 0;
    if (sugWrap) sugWrap.hidden = !showSug;
    if (showSug) {
      set('nl-kw-suggest-title', built);
      const added = r.addedTerms || [];
      set('nl-kw-suggest-note',
        `Adds ${added.length} word${added.length === 1 ? '' : 's'} — ${built.length} of 80 characters. Nothing you wrote is removed.`);
    }

    nlKwRenderSpecifics(r);
  }

  function nlKwChip(t, clickable) {
    const el = document.createElement(clickable ? 'button' : 'span');
    if (clickable) el.type = 'button';
    el.className = 'kw-chip' + (clickable ? ' is-add' : ' is-have');

    // The counts are the whole argument. "31 of 50 top results" is a reason to add a word;
    // "recommended keyword" is a brand of advice nobody should act on.
    const evidence = [];
    if (t.rankedTotal > 0) evidence.push(`${t.rankedCount} of ${t.rankedTotal} top results`);
    if (t.soldTotal   > 0) evidence.push(`${t.soldCount} of ${t.soldTotal} sold`);
    const why = evidence.join(' · ');

    el.innerHTML = `<span class="kw-chip-term">${esc(t.term)}</span>` +
                   `<span class="kw-chip-why">${esc(why)}</span>`;
    el.title = why;

    if (clickable) el.addEventListener('click', () => nlAddTerm(t.term, el));
    return el;
  }

  // Appends one term, and only if it fits. eBay truncates past 80 characters, so a word that
  // pushes the title over is a word that never gets indexed — and it would have shoved the
  // seller's own last word out to do it.
  function nlAddTerm(term, chip) {
    const input = $('nl-title');
    if (!input) return;
    const current = (input.value || '').trim();
    const next    = current ? current + ' ' + term : term;
    if (next.length > 80) {
      addActivity('Title is full', `“${term}” doesn’t fit in eBay’s 80 characters — take a word out first, or drop a less common one.`);
      return;
    }
    input.value = next;
    input.dispatchEvent(new Event('input',  { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    if (chip) { chip.disabled = true; chip.classList.add('is-added'); }
    nlRenderFreeChars();
  }

  function nlApplySuggestedTitle() {
    const built = nlKwState?.suggestedTitle || '';
    const input = $('nl-title');
    if (!built || !input) return;
    input.value = built;
    input.dispatchEvent(new Event('input',  { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    nlRenderFreeChars();
    const added = nlKwState?.addedTerms || [];
    addActivity('Title widened',
      added.length + ' word' + (added.length === 1 ? '' : 's') +
      ' the listings above yours use: ' + added.join(', '));
    // Every missing chip is now in the title. Re-asking is a second pair of eBay calls for an
    // answer whose whole content is "you applied it", so the panel just reflects what happened.
    document.querySelectorAll('#nl-kw-missing .kw-chip').forEach(c => {
      c.disabled = true; c.classList.add('is-added');
    });
    const sugWrap = $('nl-kw-suggest-wrap'); if (sugWrap) sugWrap.hidden = true;
  }

  // ── Item Specifics, read off the same listings ───────────────────

  function nlKwRenderSpecifics(r) {
    const wrap = $('nl-kw-specifics-wrap');
    const box  = $('nl-kw-specifics');
    const list = r.specifics || [];
    if (!wrap || !box) return;

    box.innerHTML = '';
    // A suggestion whose field isn't on screen can't be filled, and offering it would be a button
    // that does nothing. That happens when the category changed after the search was run.
    const usable = list.filter(s => !!nlSpecificField(s.name));
    wrap.hidden = usable.length === 0;
    if (usable.length === 0) return;

    usable.forEach(s => {
      const row = document.createElement('div');
      row.className = 'kw-spec' + (s.required ? ' is-required' : '');
      const pill = s.required
        ? '<span class="kw-spec-pill is-required">eBay requires this</span>'
        : s.recommended ? '<span class="kw-spec-pill is-rec">Buyers filter by this</span>' : '';
      row.innerHTML =
        `<div class="kw-spec-main"><span class="kw-spec-name">${esc(s.name)}</span> ${pill}
           <div class="kw-spec-why">${s.agreeCount} of the ${s.voteCount} listings that named one said “${esc(s.value)}”</div></div>`;
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'btn btn-ghost small kw-spec-use';
      btn.textContent = 'Use “' + s.value + '”';
      btn.addEventListener('click', () => {
        if (nlWriteSpecific(s)) { btn.disabled = true; btn.textContent = 'Filled'; }
        nlRunReadiness(true);
      });
      row.appendChild(btn);
      box.appendChild(row);
    });
  }

  function nlSpecificField(name) {
    return document.querySelector(`#nl-aspects-panel [data-aspect-name="${cssEscape(name)}"]`);
  }

  // Attribute-selector quoting. An aspect name is eBay's, not ours — "Manufacturer's Part Number"
  // has an apostrophe in it, and a name with a quote in it would otherwise end the selector early
  // and throw, taking the whole panel with it.
  function cssEscape(s) {
    return String(s == null ? '' : s).replace(/["\\]/g, '\\$&');
  }

  // Never over the top of an answer the seller gave. The server only offers a value for a field it
  // saw empty, and this refuses again on the way in: a panel rendered before the seller typed must
  // not undo the typing.
  function nlWriteSpecific(s) {
    const el = nlSpecificField(s.name);
    if (!el) return false;
    if (String(el.value || '').trim()) return false;
    el.value = s.value;
    el.classList.add('asp-just-filled');
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return true;
  }

  function nlFillMarketSpecifics(announce) {
    const list = nlKwState?.specifics || [];
    let filled = 0;
    const names = [];
    list.forEach(s => { if (nlWriteSpecific(s)) { filled++; names.push(s.name); } });
    if (!filled) return 0;
    if (announce) {
      addActivity('Item Specifics filled from the market',
        names.join(', ') + ' — taken from what the listings ranking for this search agree on');
    }
    // The buttons on the rows that just landed would otherwise still read "Use".
    nlKwRenderSpecifics(nlKwState || {});
    document.querySelectorAll('#nl-kw-specifics .kw-spec-use').forEach(b => {
      const row  = b.closest('.kw-spec');
      const name = row?.querySelector('.kw-spec-name')?.textContent || '';
      const el   = nlSpecificField(name);
      if (el && String(el.value || '').trim()) { b.disabled = true; b.textContent = 'Filled'; }
    });
    nlRunReadiness(true);
    return filled;
  }

  // ── Filling the listing's own fields ─────────────────────────────
  //
  // A suggestion carries a map of field id → value, because several of these are more than one
  // box: a weight is pounds and ounces, a size is three numbers. Applying half of either is
  // worse than applying none, so the whole map goes in together.
  //
  // Nothing is written over. The server only attaches a suggestion to a field its own check
  // found empty, and this refuses again on the way in — a stale result rendered a moment before
  // the seller typed must not undo the typing.
  function nlApplySuggestion(s) {
    if (!s || !s.set) return false;
    const targets = Object.entries(s.set)
      .map(([id, value]) => [$(id), value])
      .filter(([el]) => el);
    if (!targets.length) return false;

    // "Already answered" differs by control: a package type always has a value, so it is the one
    // field here that is a correction rather than a gap, and the server only offers it when the
    // current choice is too small for the box.
    const isCorrection = s.field === 'packageType';

    // The category is answered by its hidden ID, not by the box beside it. That box is a search
    // field, and half-typed search text left in it is not a chosen category — testing it the way
    // every other field is tested would refuse to fill a category that was never picked.
    const isCategory = s.field === 'category';

    if (isCategory) {
      if (String($('nl-category-id')?.value || '').trim()) return false;
    }
    else if (!isCorrection && targets.some(([el]) => String(el.value || '').trim() && parseFloat(el.value) !== 0)) return false;

    targets.forEach(([el, value]) => {
      el.value = value;
      el.classList.add('asp-just-filled');
      el.dispatchEvent(new Event('change', { bubbles: true }));
    });

    // Same finishing move the dropdown makes: the name moves onto the chip and the search box goes
    // back to being a search box. Without it the category reads as typed-but-unpicked, which is
    // the state the seller has just been saved from.
    if (isCategory) nlSyncCategoryDisplay();
    return true;
  }

  // The chosen category's display name, read from the chip the picker puts it on.
  function nlSelectedCategoryName() {
    if (!$('nl-category-id')?.value) return '';
    const chip = $('nl-cat-selected');
    if (!chip || chip.hidden) return '';
    return ($('nl-cat-selected-name')?.textContent || '').trim();
  }

  // One click from "not ready" to as ready as the app can make it: every listing field it has a
  // confident value for, plus eBay's own required Item Specifics. Low-confidence offers — the
  // package guessed for an item the estimator did not recognise — are left on their rows to be
  // read and clicked individually.
  function nlFillEverything() {
    const r = nlRdState;
    if (!r) return;

    const fields = (r.fieldSuggestions || [])
      .filter(s => s.confidence === 'high' || s.confidence === 'medium');
    let filled = 0;
    const labels = [];
    fields.forEach(s => { if (nlApplySuggestion(s)) { filled++; labels.push(s.label); } });

    const aspects = nlApplyAspectSuggestions();

    if (!filled && !aspects) return;
    const parts = [];
    if (labels.length) parts.push(labels.join(', '));
    if (aspects) parts.push(aspects + ' item specific' + (aspects === 1 ? '' : 's') + ' from eBay’s list');
    addActivity('Listing filled in', parts.join(' · ')
      + ' — from your own title, where you filed items like this before, your saved settings and the packing estimate');
    nlRunReadiness(true);
  }

  // ── Rendering: the readiness bar and its fix list ────────────────

  function nlRenderReadiness(r) {
    const bar = $('nl-readiness');
    if (!bar) return;
    bar.hidden = false;

    const blockers = r.blockerCount || 0;
    const tone = blockers > 0 ? 'is-blocker' : r.score >= 90 ? 'is-ok' : r.score >= 70 ? 'is-good' : 'is-warn';
    bar.className = 'rd-bar ' + tone;

    const scoreEl = $('nl-rd-score');
    if (scoreEl) scoreEl.textContent = r.score;
    const gradeEl = $('nl-rd-grade');
    if (gradeEl) gradeEl.textContent = r.grade || '';
    const headEl = $('nl-rd-headline');
    if (headEl) headEl.textContent = r.headline || '';

    const counts = $('nl-rd-counts');
    if (counts) {
      const parts = [];
      if (blockers) parts.push(blockers + ' blocking');
      if (r.warningCount) parts.push(r.warningCount + ' costing sales');
      counts.textContent = parts.join(' · ');
    }

    nlSyncBlockerGate(r);
    nlRenderFillRow(r);

    const list = $('nl-rd-list');
    if (!list) return;
    list.innerHTML = '';

    const fixes = r.fixes || [];
    if (!fixes.length) {
      list.innerHTML = '<p class="rd-empty">Nothing left to fix. This is as complete as the app knows how to check.</p>';
      return;
    }

    fixes.forEach(f => {
      const row = document.createElement('div');
      row.className = 'rd-fix is-' + f.severity;
      row.innerHTML = `
        <span class="rd-dot" aria-hidden="true"></span>
        <div class="rd-fix-text">
          <span class="rd-fix-label">${esc(f.label)}</span>
          <span class="rd-fix-why">${esc(f.why)}</span>
        </div>`;
      // The value, where the app has one — the row stops being a thing to read and becomes a
      // thing to press. The source is on the button itself, not in a tooltip: a number that
      // prices a shipping label has to say where it came from at the moment it is accepted.
      if (f.suggestion) {
        const s = f.suggestion;
        const fillBtn = document.createElement('button');
        fillBtn.type = 'button';
        fillBtn.className = 'rd-fix-fill' + (s.confidence === 'low' ? ' is-low' : '');
        // The estimator's own basis already opens by saying it estimated; only sources that
        // don't say so get the word put in front of them.
        const src = s.isEstimate && !/^estimat/i.test(s.source) ? 'estimated — ' + s.source : s.source;
        fillBtn.innerHTML =
          `Use “${esc(s.display)}”` +
          `<span class="rd-fix-src${s.isEstimate ? ' rd-fix-est' : ''}">${esc(src)}</span>`;
        fillBtn.addEventListener('click', () => {
          if (nlApplySuggestion(s)) {
            addActivity(s.label + ' filled', s.display + ' — ' + s.source);
            nlRunReadiness(true);
          }
        });
        row.appendChild(fillBtn);
      } else if (f.fieldId) {
        const go = document.createElement('button');
        go.type = 'button';
        go.className = 'btn btn-ghost small rd-fix-go';
        go.textContent = 'Go to it';
        go.addEventListener('click', () => nlFocusField(f.fieldId));
        row.appendChild(go);
      }
      list.appendChild(row);
    });
  }

  // The single button above the fix list. Its label counts what pressing it will actually do —
  // listing fields the app is confident about plus eBay's own specifics — so the promise and the
  // action cannot drift apart. Nothing to fill means no button at all rather than a dead one.
  function nlRenderFillRow(r) {
    const row  = $('nl-rd-fill-row');
    const btn  = $('nl-rd-fill');
    const note = $('nl-rd-fill-note');
    if (!row || !btn) return;

    const fields  = r.fillableFieldCount || 0;
    const aspects = r.aspectStatus === 'ok' ? (r.autoFillableCount || 0) : 0;
    const total   = fields + aspects;

    row.hidden = total === 0;
    if (!total) return;

    btn.textContent = `Fill in ${total} thing${total === 1 ? '' : 's'}`;
    if (note) {
      const confident = (r.fieldSuggestions || [])
        .filter(s => s.confidence === 'high' || s.confidence === 'medium');
      const estimated = confident.some(s => s.isEstimate);
      // The category is worth naming when it is in the pile. It is the one blocker on this list
      // the app could never answer before, and it is the field that decides which Item Specifics
      // eBay then asks for — so the seller should know that is what the button is about to do.
      const category = confident.some(s => s.field === 'category');
      note.textContent = category
        ? 'Including the category — filling it in is what lets eBay say which Item Specifics this listing needs. Nothing you already typed is touched.'
        : estimated
          ? 'From your title, your saved settings and an estimated packing weight — nothing you already typed is touched.'
          : 'From your own title and saved settings — nothing you already typed is touched.';
    }
  }

  // Jump to the field a fix belongs to, opening whatever collapsed panel it lives in — a
  // "Go to it" that scrolls to a closed <details> has sent the seller nowhere.
  function nlFocusField(fieldId) {
    const el = $(fieldId);
    if (!el) return;
    let node = el.parentElement;
    while (node) {
      if (node.tagName === 'DETAILS') node.open = true;
      node = node.parentElement;
    }
    el.scrollIntoView({ block: 'center', behavior: 'smooth' });

    // Some targets aren't form controls — "Add at least one photo" points at the photo grid,
    // which is a div and silently ignores .focus(). A borrowed tabindex makes the jump land
    // somewhere for a keyboard user too, and is removed again so it stays out of the tab order.
    const borrowTabIndex = !el.hasAttribute('tabindex') &&
      !/^(INPUT|SELECT|TEXTAREA|BUTTON|A)$/.test(el.tagName);
    if (borrowTabIndex) el.setAttribute('tabindex', '-1');
    if (typeof el.focus === 'function') el.focus({ preventScroll: true });
    if (borrowTabIndex) el.addEventListener('blur', () => el.removeAttribute('tabindex'), { once: true });

    el.classList.add('asp-just-filled');
    setTimeout(() => el.classList.remove('asp-just-filled'), 1600);
  }

  // ── The pre-publish gate ─────────────────────────────────────────
  //
  // Returns true when the publish should go ahead. A blocker is eBay's rule, not the app's
  // guess, so this is worth stopping for — but it stops once, explains, and offers the override,
  // because the app can be wrong about a category and the account is the seller's.
  function nlBlockersStopPublish() {
    const r = nlRdState;
    if (!r || nlRdOverride) return false;
    const blockers = (r.fixes || []).filter(f => f.severity === 'blocker');
    if (!blockers.length) return false;

    nlRenderBlockerGate(blockers);

    // Open the fix list so the reasons are one click away, not two.
    const rdList = $('nl-rd-list');
    if (rdList && rdList.hidden) $('nl-rd-toggle')?.click();
    return true;
  }

  function nlRenderBlockerGate(blockers) {
    const el = $('nl-result-msg');
    if (!el) return;
    const list = blockers.map(f => `<li>${esc(f.label)}</li>`).join('');
    el.className = 'nl-result-msg error';
    el.dataset.rdGate = '1';   // marks this message as ours, so it can be kept current
    el.innerHTML =
      `<strong>eBay would reject this publish.</strong> ${blockers.length === 1 ? 'One thing needs fixing' : blockers.length + ' things need fixing'} first:` +
      `<ul class="rd-block-list">${list}</ul>` +
      '<button type="button" class="btn btn-primary small" id="nl-rd-fix-first">Take me to the first one</button> ' +
      '<button type="button" class="btn btn-ghost small" id="nl-rd-publish-anyway">Publish anyway</button>';
    $('nl-rd-fix-first')?.addEventListener('click', () => {
      const target = blockers.find(f => f.fieldId);
      if (target) nlFocusField(target.fieldId);
    });
    $('nl-rd-publish-anyway')?.addEventListener('click', () => {
      nlRdOverride = true;
      addActivity('Publishing past the readiness check', blockers.map(f => f.label).join('; '));
      nlSubmit('publish');
    });
  }

  // The gate is a snapshot of the blockers at the moment Publish was pressed. Fixing one of
  // them leaves it on screen still naming it, directly under a bar that now says otherwise —
  // two contradictory answers, and the stale one is the louder. So it tracks, or it goes.
  function nlSyncBlockerGate(r) {
    const el = $('nl-result-msg');
    if (!el || el.dataset.rdGate !== '1') return;

    const blockers = (r.fixes || []).filter(f => f.severity === 'blocker');
    if (!blockers.length) {
      delete el.dataset.rdGate;
      el.className = 'nl-result-msg';
      el.innerHTML = '';
      return;
    }
    nlRenderBlockerGate(blockers);
  }

  function nlAddSpecificRow(key, value) {
    const row = document.createElement('div');
    row.className = 'specific-row';
    row.innerHTML = `
      <input type="text" placeholder="Name, e.g. Model" value="${esc(key)}" />
      <input type="text" placeholder="Value" value="${esc(value)}" />
      <button type="button" title="Remove">X</button>`;
    row.querySelector('button')?.addEventListener('click', () => row.remove());
    $('nl-specifics-list')?.appendChild(row);
  }

  // ── 6-slot Photo Grid ──────────────────────────────────────────

  const PHOTO_SLOT_COUNT = 6;

  function initPhotoGrid() {
    const grid = $('nl-photo-grid');
    if (!grid) return;
    grid.innerHTML = '';
    for (let i = 0; i < PHOTO_SLOT_COUNT; i++) grid.appendChild(createPhotoSlot(i));
  }

  function createPhotoSlot(index) {
    const slot = document.createElement('div');
    slot.className = 'nl-photo-slot';
    slot.dataset.slotIndex = String(index);

    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = 'image/*';
    fileInput.hidden = true;
    fileInput.addEventListener('change', () => {
      if (fileInput.files[0]) nlLoadFileIntoSlot(fileInput.files[0], index);
    });

    const ph = document.createElement('div');
    ph.className = 'slot-placeholder';
    ph.innerHTML = `<span class="slot-plus">+</span><span class="slot-num">Picture ${index + 1}</span>`;

    const img = document.createElement('img');
    img.alt = `Picture ${index + 1}`;
    img.style.display = 'none';

    const label = document.createElement('div');
    label.className = 'slot-label';
    label.textContent = `Picture ${index + 1}`;
    label.style.display = 'none';

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'slot-remove';
    removeBtn.textContent = '✕';
    removeBtn.title = 'Remove';
    removeBtn.addEventListener('click', e => { e.stopPropagation(); clearPhotoSlot(index); });

    const rembgBtn = document.createElement('button');
    rembgBtn.type = 'button';
    rembgBtn.className = 'slot-rembg';
    rembgBtn.textContent = 'Remove BG';
    rembgBtn.addEventListener('click', e => { e.stopPropagation(); nlRemoveBgFromSlot(index); });

    slot.append(fileInput, ph, img, label, removeBtn, rembgBtn);

    slot.addEventListener('click', () => {
      if (slot.classList.contains('has-image')) openPhotoEditor(index);
      else fileInput.click();
    });
    slot.addEventListener('dragover', e => { e.preventDefault(); slot.classList.add('drag-over'); });
    slot.addEventListener('dragleave', () => slot.classList.remove('drag-over'));
    slot.addEventListener('drop', e => {
      e.preventDefault();
      slot.classList.remove('drag-over');
      if (e.dataTransfer.files[0]) nlLoadFileIntoSlot(e.dataTransfer.files[0], index);
    });

    return slot;
  }

  function getPhotoSlot(index) {
    return $('nl-photo-grid')?.querySelector(`[data-slot-index="${index}"]`) || null;
  }

  function setPhotoSlotUrl(index, url, isEbay = false) {
    const slot = getPhotoSlot(index);
    if (!slot) return;
    const img = slot.querySelector('img');
    if (img) { img.src = url; img.style.display = ''; }
    slot.querySelector('.slot-label').style.display = '';
    // Remove old eBay badge if any
    slot.querySelector('.slot-ebay-badge')?.remove();
    if (isEbay) {
      const badge = document.createElement('span');
      badge.className = 'slot-ebay-badge';
      badge.textContent = 'eBay';
      slot.appendChild(badge);
    }
    slot.dataset.url = url;
    slot.classList.add('has-image');
    $('nl-photo-grid')?.closest('details')?.setAttribute('open', '');
    nlRunReadiness();   // photo count is one of the things the readiness bar scores
  }

  function clearPhotoSlot(index) {
    const slot = getPhotoSlot(index);
    if (!slot) return;
    const img = slot.querySelector('img');
    if (img) { img.src = ''; img.style.display = 'none'; }
    slot.querySelector('.slot-label').style.display = 'none';
    slot.querySelector('.slot-ebay-badge')?.remove();
    const fi = slot.querySelector('input[type=file]');
    if (fi) fi.value = '';
    delete slot.dataset.url;
    slot.classList.remove('has-image');
    nlRunReadiness();
  }

  function nlClearAllPhotoSlots() {
    const grid = $('nl-photo-grid');
    if (!grid || !grid.querySelector('.nl-photo-slot')) {
      initPhotoGrid();
      return;
    }
    for (let i = 0; i < PHOTO_SLOT_COUNT; i++) clearPhotoSlot(i);
  }

  function nextEmptySlotIndex() {
    const grid = $('nl-photo-grid');
    if (!grid) return -1;
    const slots = grid.querySelectorAll('.nl-photo-slot');
    for (let i = 0; i < slots.length; i++) {
      if (!slots[i].classList.contains('has-image')) return parseInt(slots[i].dataset.slotIndex);
    }
    return -1;
  }

  function nlAddPhotoRow(url, prepend = false) {
    if (!url) return;
    if (prepend) {
      // Shift existing photos right by one and put new one at slot 0
      const grid = $('nl-photo-grid');
      if (grid) {
        const urls = nlCollectPhotoUrls();
        nlClearAllPhotoSlots();
        setPhotoSlotUrl(0, url);
        urls.slice(0, PHOTO_SLOT_COUNT - 1).forEach((u, i) => setPhotoSlotUrl(i + 1, u));
      }
    } else {
      const idx = nextEmptySlotIndex();
      if (idx !== -1) setPhotoSlotUrl(idx, url);
    }
  }

  async function nlLoadFileIntoSlot(file, index) {
    if (!file.type.startsWith('image/')) return;
    const reader = new FileReader();
    reader.onload = ev => {
      const base64   = ev.target.result.split(',')[1];
      const mimeType = file.type;
      fetch('/api/photos/save-uploaded', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageBase64: base64, mimeType })
      }).then(r => r.ok ? r.json() : null)
        .then(d => setPhotoSlotUrl(index, d?.url || ev.target.result))
        .catch(() => setPhotoSlotUrl(index, ev.target.result));
      addActivity('Photo added', `Picture ${index + 1}`);
    };
    reader.readAsDataURL(file);
  }

  async function nlRemoveBgFromSlot(index) {
    const slot = getPhotoSlot(index);
    if (!slot?.classList.contains('has-image')) return;
    const url = slot.dataset.url;
    if (!url) return;

    const btn = slot.querySelector('.slot-rembg');
    if (btn) { btn.textContent = 'Working…'; btn.disabled = true; }

    try {
      let b64, mimeType;
      if (url.startsWith('data:')) {
        const [header, data] = url.split(',');
        b64 = data; mimeType = header.match(/data:([^;]+)/)?.[1] || 'image/jpeg';
      } else {
        const fetchRes = await fetch(url);
        if (!fetchRes.ok) throw new Error('Could not fetch image');
        const blob = await fetchRes.blob();
        mimeType = blob.type || 'image/jpeg';
        b64 = await blobToBase64(blob);
      }
      const res  = await fetch('/api/photos/remove-bg', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageBase64: b64, mimeType })
      });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error || 'BG removal failed');
      setPhotoSlotUrl(index, body.url);
      addActivity('Background removed', `Picture ${index + 1}`);
    } catch (err) {
      toastErr(errorText(err, 'Unknown error.'), {
        title: `Background removal failed on picture ${index + 1}`,
        action: { label: 'Try again', onClick: () => nlRemoveBgFromSlot(index) },
      });
    } finally {
      if (btn) { btn.textContent = 'Remove BG'; btn.disabled = false; }
    }
  }

  async function uploadPhotosToEbay(photoUrls) {
    const statusEl = $('nl-photo-upload-status');
    if (statusEl) { statusEl.classList.remove('hidden'); statusEl.className = 'nl-photo-upload-status'; statusEl.textContent = 'Uploading photos to eBay…'; }

    const results = [];
    for (let i = 0; i < photoUrls.length; i++) {
      const url = photoUrls[i];
      if (!url) { results.push(url); continue; }

      // Already on eBay CDN — skip
      if (url.includes('ebayimg.com') || url.includes('ebay.com/images')) {
        results.push(url);
        continue;
      }

      try {
        if (statusEl) statusEl.textContent = `Uploading picture ${i + 1} of ${photoUrls.length} to eBay…`;

        let b64, mimeType;
        if (url.startsWith('data:')) {
          const [header, data] = url.split(',');
          b64 = data; mimeType = header.match(/data:([^;]+)/)?.[1] || 'image/jpeg';
        } else {
          const fetchRes = await fetch(url);
          if (!fetchRes.ok) throw new Error(`Could not fetch image: ${url}`);
          const blob = await fetchRes.blob();
          mimeType = blob.type || 'image/jpeg';
          b64 = await blobToBase64(blob);
        }

        const uploadRes = await fetch('/api/ebay/upload-picture', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ imageBase64: b64, mimeType })
        });
        const body = await uploadRes.json();
        if (!uploadRes.ok) throw new Error(body.error || 'Upload failed');

        // Update slot to show eBay badge
        setPhotoSlotUrl(i, body.url, true);
        results.push(body.url);
      } catch (err) {
        addActivity(`Picture ${i + 1} eBay upload failed`, errorText(err));
        // Do NOT fall back to local URL — eBay will reject relative/localhost URLs
        // Leave this slot out of the published listing; image can be added in Seller Hub
        if (statusEl) statusEl.textContent = `Picture ${i + 1} upload failed: ${errorText(err)}`;
      }
    }

    if (statusEl) {
      const uploaded = results.filter(Boolean).length;
      statusEl.className = 'nl-photo-upload-status done';
      statusEl.textContent = uploaded > 0
        ? `${uploaded} photo(s) uploaded to eBay.`
        : 'Photo upload failed — listing will publish without images.';
      setTimeout(() => statusEl.classList.add('hidden'), 4000);
    }
    return results.filter(Boolean);
  }

  function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
      const fr = new FileReader();
      fr.onload  = () => resolve(fr.result.split(',')[1]);
      fr.onerror = reject;
      fr.readAsDataURL(blob);
    });
  }

  function nlCollectPhotoUrls() {
    const grid = $('nl-photo-grid');
    if (!grid) return [];
    return [...grid.querySelectorAll('.nl-photo-slot.has-image')]
      .map(slot => (slot.dataset.url || '').trim())
      .filter(Boolean);
  }

  function nlToggleBestOffer(show) {
    if ($('nl-best-offer-fields')) $('nl-best-offer-fields').style.display = show ? '' : 'none';
    if ($('nl-best-offer-decline')) $('nl-best-offer-decline').style.display = show ? '' : 'none';
  }

  function nlUpdateCharCount(inputId, countId, max) {
    const el = $(inputId);
    const counter = $(countId);
    if (!el || !counter) return;
    const len = el.value.length;
    counter.textContent = `${len} / ${max}`;
    counter.style.color = len > max * .9 ? 'var(--danger)' : '';
  }

  // Terms eBay's own generic "improper words / violation of eBay policy" rejection commonly
  // fires on — mirrors the denylist ClaudeService already avoids when generating descriptions
  // (see HtmlTemplateInstructions / _contactPat in ClaudeService.cs). eBay's error text never
  // names the actual offending word, so this is a best-effort guess at WHERE to look, not a
  // guarantee of finding the exact match — eBay's real filter is broader and undocumented.
  const EBAY_FLAGGED_TERMS = ['guarantee', 'guaranteed', 'warranty', 'best price', 'lowest price', 'click here'];
  const EBAY_CONTACT_PATTERN =
    /(whatsapp\s*[:+]?\s*\+?\d|telegram\s*[:@]|wechat\s*[:@]|[\w.+-]+@[\w-]+\.[a-z]{2,}|\+?1?[\s.-]?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4})/i;
  const EBAY_POLICY_ERROR_PATTERN = /improper words|violation of eBay policy|cannot be listed or modified/i;

  function nlFindFlaggedTerms(text) {
    if (!text) return [];
    const found = [];
    const lower = text.toLowerCase();
    for (const term of EBAY_FLAGGED_TERMS) if (lower.includes(term)) found.push(term);
    const contactMatch = text.match(EBAY_CONTACT_PATTERN);
    if (contactMatch) found.push(contactMatch[0].trim());
    return found;
  }

  function nlClearPolicyHighlights() {
    ['nl-title', 'nl-desc-text', 'nl-description', 'nl-desc-preview'].forEach(id => $(id)?.classList.remove('field-flagged'));
    document.querySelectorAll('#nl-specifics-list .field-flagged').forEach(el => el.classList.remove('field-flagged'));
    document.querySelectorAll('#nl-specifics-list .specific-row.field-flagged').forEach(el => el.classList.remove('field-flagged'));
  }

  // Called after a publish failure — when eBay rejects for a MISSING/INVALID item specific (e.g.
  // "The item specific Chipset/GPU Model is missing"), find that specific's row and highlight it so
  // the seller can jump straight to the box to fix. If the required specific isn't present at all,
  // add an empty row pre-labeled with its name, then highlight + focus its value box.
  function nlHighlightMissingSpecifics(errorText) {
    const text = errorText || '';
    const names = new Set();
    const patterns = [
      /item specific(?:\s+name)?\s+["']?(.+?)["']?\s+is\s+missing/gi,
      /item specific(?:\s+name)?\s+["']?(.+?)["']?\s+is\s+required/gi,
      /missing\s+(?:required\s+)?item specifics?:?\s*["']?([^."'\n]+)["']?/gi,
      /(?:enter|add|provide)\s+a?\s*(?:valid\s+)?value\s+for\s+(?:the\s+)?["']?(.+?)["']?[.,]/gi,
    ];
    for (const re of patterns) {
      let m;
      while ((m = re.exec(text)) !== null) {
        m[1].split(/,|\band\b/).forEach(n => {
          const name = n.replace(/["'.]/g, '').replace(/\s+/g, ' ').trim();
          // Guard against over-capturing whole sentences.
          if (name && name.length <= 60 && !/\bmissing\b|\brequired\b|\blisting\b/i.test(name)) names.add(name);
        });
      }
    }
    if (names.size === 0) return false;

    let firstEl = null;
    names.forEach(name => {
      const norm = name.toLowerCase();
      let row = Array.from(document.querySelectorAll('#nl-specifics-list .specific-row'))
        .find(r => (r.querySelector('input')?.value || '').trim().toLowerCase() === norm);
      if (!row) {
        nlAddSpecificRow(name, '');
        const all = document.querySelectorAll('#nl-specifics-list .specific-row');
        row = all[all.length - 1];
      }
      if (row) {
        row.classList.add('field-flagged');
        const valInput = row.querySelectorAll('input')[1];
        valInput?.classList.add('field-flagged');
        firstEl = firstEl || valInput || row;
      }
    });

    if (firstEl) {
      const note = `\n\n⚠ eBay needs a value for item specific(s): "${[...names].join('", "')}" — highlighted below. Enter a value and republish.`;
      const el = $('nl-result-msg');
      if (el) el.innerHTML += esc(note).replace(/\n/g, '<br>');
      firstEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => firstEl.focus(), 300);
    }
    return true;
  }

  // Called after a publish/save failure — if the error looks like eBay's generic content-policy
  // rejection, scans Title and Description for known-flagged phrases and visually flags whichever
  // field(s) actually contain something suspicious, so the user isn't left guessing which of two
  // fields (or which word in a 4000-character description) to comb through by hand.
  function nlHighlightPolicyIssues(errorText) {
    nlClearPolicyHighlights();
    if (!EBAY_POLICY_ERROR_PATTERN.test(errorText || '')) return;

    const titleText = $('nl-title')?.value || '';
    const descText  = nlHtmlToText($('nl-description')?.value || '') || $('nl-desc-text')?.value || '';
    const titleHits = nlFindFlaggedTerms(titleText);
    const descHits  = nlFindFlaggedTerms(descText);

    let note = '';
    let focusEl = null;

    if (titleHits.length) {
      $('nl-title')?.classList.add('field-flagged');
      focusEl = focusEl || $('nl-title');
      note += `\n\n⚠ Possible flagged text in Title: "${titleHits.join('", "')}"`;
    }
    if (descHits.length) {
      $('nl-desc-text')?.classList.add('field-flagged');
      $('nl-description')?.classList.add('field-flagged');
      $('nl-desc-preview')?.classList.add('field-flagged');
      focusEl = focusEl || $('nl-desc-text');
      note += `\n\n⚠ Possible flagged text in Description: "${descHits.join('", "')}"`;
    }
    if (!titleHits.length && !descHits.length) {
      $('nl-title')?.classList.add('field-flagged');
      $('nl-desc-text')?.classList.add('field-flagged');
      $('nl-description')?.classList.add('field-flagged');
      $('nl-desc-preview')?.classList.add('field-flagged');
      focusEl = $('nl-title');
      note += `\n\n⚠ eBay didn't say which word — Title and Description are both flagged below for review. Common triggers: guarantee/warranty claims, contact info (phone/email/WhatsApp/Telegram), off-eBay sale language.`;
    }

    if (note) {
      const el = $('nl-result-msg');
      if (el) el.innerHTML += esc(note).replace(/\n/g, '<br>');
    }
    focusEl?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    focusEl?.focus();
  }

  function nlSetResult(type, text) {
    const el = $('nl-result-msg');
    if (!el) return;
    delete el.dataset.rdGate;   // a publish result is not the readiness gate; stop tracking it
    el.className = 'nl-result-msg' + (type ? ` ${type}` : '');
    // Use innerHTML with line breaks to show multi-line error details
    el.innerHTML = esc(text).replace(/\n/g, '<br>');
  }

  // ── Description Edit Text / Edit HTML / Preview tabs ──────────────────────────────────────
  // One implementation, two screens: the New Listing form (id prefix "nl") and the listing edit
  // drawer (prefix "f"). Their ids differ only by that prefix, so everything below is written
  // against the prefix rather than against nl-*. The drawer had no tabs at all and showed the
  // seller a wall of markup; a second copy of this logic would only have drifted from the first.
  //
  //   <prefix>-description        the HTML textarea — always the source of truth for saving
  //   <prefix>-desc-text          the plain-text textarea
  //   <prefix>-desc-preview       the rendered view
  //   <prefix>-desc-{edit,text,preview}-wrap, <prefix>-desc-count

  // eBay's own cap is far higher; this matches the ceiling the SEO rewrite prompt is given in
  // ClaudeService. The old 4,000 predated that template, which lands at 6-7k of real HTML, so
  // the counter flagged every AI-written description as over budget.
  const DESC_MAX_CHARS = 9000;

  // Prefixes whose plain-text tab the seller has actually typed into. Folding the text back into
  // the HTML flattens the inline markup inside each block, so it is done only when there is a
  // real edit to fold in — never on a tab the seller merely looked at.
  const descTextDirty = new Set();

  function descIds(prefix) {
    return {
      html:     `${prefix}-description`,
      text:     `${prefix}-desc-text`,
      preview:  `${prefix}-desc-preview`,
      count:    `${prefix}-desc-count`,
      editWrap: `${prefix}-desc-edit-wrap`,
      textWrap: `${prefix}-desc-text-wrap`,
      prevWrap: `${prefix}-desc-preview-wrap`,
    };
  }

  function descTabBar(prefix) {
    return document.querySelector(`.desc-tab-bar[data-desc-prefix="${prefix}"]`);
  }

  function descActiveTab(prefix) {
    return descTabBar(prefix)?.querySelector('.desc-tab.active')?.dataset.descTab;
  }

  function initDescTabs(prefix) {
    const bar = descTabBar(prefix);
    if (!bar) return;
    const ids = descIds(prefix);
    bar.querySelectorAll('.desc-tab').forEach(tab => {
      tab.addEventListener('click', () => descShowTab(prefix, tab.dataset.descTab));
    });
    on(ids.html, 'input', () => {
      descSyncPreview(prefix);
      descUpdateCount(prefix);
      $(ids.html)?.classList.remove('field-flagged');
      $(ids.preview)?.classList.remove('field-flagged');
    });
    on(ids.text, 'input', () => {
      descTextDirty.add(prefix);
      descUpdateCount(prefix);
      $(ids.text)?.classList.remove('field-flagged');
    });
    descUpdateCount(prefix);
  }

  function descShowTab(prefix, arriving) {
    const bar = descTabBar(prefix);
    if (!bar) return;
    const ids = descIds(prefix);
    descCommitText(prefix);   // banked before the text tab stops being what the seller sees
    bar.querySelectorAll('.desc-tab').forEach(t => t.classList.toggle('active', t.dataset.descTab === arriving));
    $(ids.editWrap)?.classList.toggle('hidden', arriving !== 'edit');
    $(ids.textWrap)?.classList.toggle('hidden', arriving !== 'text');
    $(ids.prevWrap)?.classList.toggle('hidden', arriving !== 'preview');
    if (arriving === 'text' && $(ids.text)) $(ids.text).value = nlHtmlToText($(ids.html)?.value || '');
    if (arriving === 'preview') descSyncPreview(prefix);
    descUpdateCount(prefix);
  }

  // Writes any pending plain-text edits into the HTML field, which is the only thing ever saved.
  // Called on a tab switch and again when the payload is built, so a seller who types in Edit Text
  // and hits Save without touching the tabs keeps their words.
  function descCommitText(prefix) {
    if (!descTextDirty.has(prefix)) return;
    const ids = descIds(prefix);
    const html = $(ids.html);
    if (!html) return;
    html.value = nlMergeTextIntoHtml(html.value, $(ids.text)?.value || '');
    descTextDirty.delete(prefix);
  }

  // Loads a description into all three tabs and returns the field to the readable default.
  // Opening a listing should read like a listing, not like its source.
  function descSetHtml(prefix, html) {
    const ids = descIds(prefix);
    const value = html || '';
    if ($(ids.html)) $(ids.html).value = value;
    if ($(ids.text)) $(ids.text).value = nlHtmlToText(value);
    descTextDirty.delete(prefix);   // freshly loaded, not edited
    descTabBar(prefix)?.querySelectorAll('.desc-tab')
      .forEach(t => t.classList.toggle('active', t.dataset.descTab === 'text'));
    $(ids.editWrap)?.classList.add('hidden');
    $(ids.textWrap)?.classList.remove('hidden');
    $(ids.prevWrap)?.classList.add('hidden');
    descSyncPreview(prefix);
    descUpdateCount(prefix);
  }

  function descUpdateCount(prefix) {
    const ids = descIds(prefix);
    const counter = $(ids.count);
    if (!counter) return;
    const len = descActiveTab(prefix) === 'text'
      ? nlTextToHtml($(ids.text)?.value || '').length
      : ($(ids.html)?.value || '').length;
    counter.textContent = len.toLocaleString() + ' / ' + DESC_MAX_CHARS.toLocaleString();
    counter.style.color = len > DESC_MAX_CHARS ? 'var(--danger)'
      : len > DESC_MAX_CHARS * 0.9 ? 'var(--warning)' : '';
  }

  function descSyncPreview(prefix) {
    const preview = $(descIds(prefix).preview);
    if (!preview) return;
    preview.innerHTML = descSanitizeHtml($(descIds(prefix).html)?.value || '');
  }

  // Every read of a description's structure goes through here. The markup is not the seller's —
  // Claude wrote it, or eBay sent it back, or it was pasted in from another listing — so it is
  // parsed inside a <template>, whose contents belong to an inert document with no browsing
  // context: nothing runs and nothing is fetched. The wrapper is created by that same inert
  // document so the nodes never leave it. `div.innerHTML = html` on the live document looks
  // equivalent and is not — an <img src=x onerror=…> in there fires the moment the load fails.
  function descParse(html) {
    const tpl = document.createElement('template');
    tpl.innerHTML = html || '';
    const holder = tpl.content.ownerDocument.createElement('div');
    holder.append(tpl.content);
    return holder;
  }

  // What Preview is allowed to put on the page. Only the preview is filtered — the textarea keeps
  // the HTML verbatim, so nothing is lost from what eventually gets sent to eBay.
  function descSanitizeHtml(html) {
    const holder = descParse(html);
    holder.querySelectorAll('script, iframe, object, embed, form, link, meta, base, style')
      .forEach(el => el.remove());
    holder.querySelectorAll('*').forEach(el => {
      [...el.attributes].forEach(({ name, value }) => {
        const attr = name.toLowerCase();
        // "java\tscript:" is the same URL to a browser as "javascript:", so collapse first.
        const url = value.replace(/[\s\u0000-\u001F]/g, '').toLowerCase();
        if (attr.startsWith('on') || attr === 'srcdoc'
            || url.startsWith('javascript:') || url.startsWith('data:text/html')) {
          el.removeAttribute(name);
        }
      });
    });
    return holder.innerHTML;
  }

  // Named wrappers for the New Listing form's own call sites.
  function nlUpdateDescCount() { descUpdateCount('nl'); }
  function nlSyncDescPreview()  { descSyncPreview('nl'); }

  function nlHtmlToText(html) {
    if (!html.trim()) return '';
    const tmp = descParse(html);
    // A <script> or <style> body is markup, not words. Left in, its source shows up in the
    // seller's text box as if they had typed it, and is written back as a paragraph.
    tmp.querySelectorAll('script, style').forEach(el => el.remove());
    // Insert newlines at block boundaries before extracting text
    tmp.querySelectorAll('br').forEach(el => el.replaceWith('\n'));
    tmp.querySelectorAll('p, div, h1, h2, h3, h4, h5, h6, li').forEach(el => {
      el.insertAdjacentText('afterend', '\n\n');
    });
    return (tmp.textContent || '').replace(/\n{3,}/g, '\n\n').trim();
  }

  function nlTextToHtml(text) {
    if (!text.trim()) return '';
    return text.trim()
      .split(/\n\n+/)
      .map(p => '<p>' + p.replace(/\n/g, '<br>').trim() + '</p>')
      .filter(p => p !== '<p></p>')
      .join('\n');
  }

  // The leaf block elements nlHtmlToText() walks to build plain text — kept as a single
  // shared definition so extraction and merge-back always agree on the same paragraph order.
  function nlDescBlocks(root) {
    return [...root.querySelectorAll('p, div, h1, h2, h3, h4, h5, h6, li')]
      .filter(el => !el.querySelector('p, div, h1, h2, h3, h4, h5, h6, li'));
  }

  // Writes edited plain text back into the ORIGINAL description's HTML — every heading,
  // bullet list, and inline style stays exactly as Claude generated it; only the wording of
  // each paragraph/heading/list item changes. Falls back to a fresh rebuild only if the
  // original has no recognizable structure to preserve.
  function nlMergeTextIntoHtml(originalHtml, editedText) {
    if (!originalHtml.trim()) return nlTextToHtml(editedText);

    const tmp = descParse(originalHtml);
    const blocks = nlDescBlocks(tmp);
    if (blocks.length === 0) return nlTextToHtml(editedText);

    const paragraphs = editedText.trim() ? editedText.trim().split(/\n\n+/) : [];

    blocks.forEach((el, i) => {
      const text = paragraphs[i];
      if (text === undefined) { el.remove(); return; } // paragraph deleted — drop that block
      el.innerHTML = esc(text.trim()).replace(/\n/g, '<br>');
    });

    // Extra paragraphs beyond the original block count are new — append as plain <p> tags
    if (paragraphs.length > blocks.length) {
      const extraHtml = paragraphs.slice(blocks.length)
        .map(p => '<p>' + esc(p.trim()).replace(/\n/g, '<br>') + '</p>').join('');
      tmp.insertAdjacentHTML('beforeend', extraHtml);
    }

    return tmp.innerHTML;
  }

  async function nlAutoRemoveBg(localUrl) {
    $('nl-cutout-wrap')?.classList.remove('hidden');
    $('nl-cutout-spinner')?.classList.remove('hidden');
    const cutoutImg = $('nl-cutout-img');
    if (cutoutImg) cutoutImg.src = '';

    try {
      const fetchRes = await fetch(localUrl);
      if (!fetchRes.ok) throw new Error('Could not fetch photo');
      const blob   = await fetchRes.blob();
      const b64    = await blobToBase64(blob);
      const apiRes = await fetch('/api/photos/remove-bg', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageBase64: b64, mimeType: blob.type || 'image/png' })
      });
      const body = await apiRes.json();
      if (!apiRes.ok) throw new Error(body.error || 'Background removal failed');

      if (cutoutImg) cutoutImg.src = body.url;
      setPhotoSlotUrl(0, body.url);
      addActivity('Background removed automatically', 'Set as Picture 1');
    } catch (err) {
      $('nl-cutout-wrap')?.classList.add('hidden');
      addActivity('Auto BG removal failed', errorText(err));
    } finally {
      $('nl-cutout-spinner')?.classList.add('hidden');
    }
  }

  async function nlAutoRemoveBgFromBase64(b64, mimeType) {
    $('nl-cutout-wrap')?.classList.remove('hidden');
    $('nl-cutout-spinner')?.classList.remove('hidden');
    const cutoutImg = $('nl-cutout-img');
    if (cutoutImg) cutoutImg.src = '';
    try {
      const apiRes = await fetch('/api/photos/remove-bg', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageBase64: b64, mimeType })
      });
      const body = await apiRes.json();
      if (!apiRes.ok) throw new Error(body.error || 'Background removal failed');
      if (cutoutImg) cutoutImg.src = body.url;
      setPhotoSlotUrl(0, body.url);
      addActivity('Background removed automatically', 'Set as Picture 1');
    } catch (err) {
      $('nl-cutout-wrap')?.classList.add('hidden');
      addActivity('Auto BG removal failed', errorText(err));
    } finally {
      $('nl-cutout-spinner')?.classList.add('hidden');
    }
  }

  async function nlRemoveBg() {
    if (!nlImageBase64) { return; }
    try {
      const res = await fetch('/api/photos/remove-bg', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageBase64: nlImageBase64, mimeType: nlMimeType || 'image/jpeg' })
      });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error || 'Background removal failed');
      nlAddPhotoRow(body.url, true);
      addActivity('Background removed', 'Set as Picture 1');
    } catch (err) {
      addActivity('Background removal failed', errorText(err));
    }
  }

  async function nlImproveSeo() {
    const btn = $('nl-btn-improve-seo');
    if (btn) { btn.disabled = true; btn.textContent = 'Improving…'; }
    $('nl-ai-done')?.classList.add('hidden');
    $('nl-ai-status')?.classList.remove('hidden');
    if ($('nl-ai-msg')) $('nl-ai-msg').textContent = 'Improving SEO and description…';

    try {
      const payload = {
        title:                   $('nl-title')?.value || '',
        subtitle:                $('nl-subtitle')?.value || '',
        category:                $('nl-category')?.value || '',
        categoryId:              $('nl-category-id')?.value || '',
        condition:               $('nl-condition')?.value || 'USED_EXCELLENT',
        conditionDescription:    $('nl-condition-desc')?.value || '',
        brand:                   $('nl-brand')?.value || '',
        mpn:                     $('nl-mpn')?.value || '',
        description:             $('nl-description')?.value || '',
        price:                   parseFloat($('nl-price')?.value) || 0,
        quantity:                parseInt($('nl-quantity')?.value, 10) || 1,
        weightLbs:               parseFloat($('nl-weight-lbs')?.value) || 0,
        weightOz:                parseFloat($('nl-weight-oz')?.value) || 0,
        packageLengthIn:         parseFloat($('nl-length')?.value) || 0,
        packageWidthIn:          parseFloat($('nl-width')?.value) || 0,
        packageHeightIn:         parseFloat($('nl-height')?.value) || 0,
        handlingTimeBusinessDays: parseInt($('nl-handling-time')?.value, 10) || 1,
        itemLocationPostalCode:  $('nl-location-zip')?.value || '',
        imageUrls:               nlCollectPhotoUrls(),
        itemSpecifics:           nlCollectSpecifics(),
      };

      const { ok, data, failure } = await callApi('/api/improve-seo', {
        method: 'POST', body: payload, timeoutMs: AI_TIMEOUT_MS,
      });

      if (!ok) {
        $('nl-ai-status')?.classList.add('hidden');
        // The listing is untouched on failure — the rewrite is applied only on success — so the
        // original title and description are still exactly as the seller left them.
        renderFailure('nl-failure', failure, { onRetry: () => nlImproveSeo() });
        addActivity('SEO improvement failed', failure?.headline || 'Unknown error');
        return;
      }

      fillNlForm(data);
      scheduleAutosave();
      $('nl-ai-status')?.classList.add('hidden');
      $('nl-ai-done')?.classList.remove('hidden');
      addActivity('SEO improved', data.title || 'Title and description updated');
    } catch (err) {
      $('nl-ai-status')?.classList.add('hidden');
      renderFailure('nl-failure', {
        kind: 'Unknown', headline: 'The app hit an unexpected error during the SEO rewrite',
        whatHappened: 'Your listing has not been changed.',
        whatToDo: 'Try again, or carry on editing by hand.',
        retryable: true, workPreserved: true, technical: technicalDetail(err),
      }, { onRetry: () => nlImproveSeo() });
      addActivity('SEO improvement failed', technicalDetail(err));
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Improve SEO + Description'; }
    }
  }

  // One publish at a time, enforced here as well as by disabling the buttons. The buttons are not
  // enough on their own: /api/listing/post's success path wires up its own "Publish to eBay Live"
  // button, the readiness gate can re-enter this, and Enter in a text field submits the form — three
  // routes to a second in-flight publish, which is how one item becomes two live listings.
  let publishInFlight = false;

  // Set only by nlSubmitWithoutPhotos, so the "every photo failed" gate can be passed once,
  // deliberately, rather than being silently skipped every time.
  let nlPhotosDeliberatelyEmpty = false;

  async function nlSubmit(mode) {
    const payload = buildNlPayload();
    if (!payload.title.trim()) {
      nlSetResult('error', 'Title is required before submitting.');
      return;
    }
    if (!payload.price || payload.price <= 0) {
      nlSetResult('error', 'Price must be greater than zero.');
      return;
    }

    // Catch what eBay would reject before spending the round trip on it. Drafts are exempt:
    // an unfinished draft is the point of a draft.
    if (mode === 'publish' && nlBlockersStopPublish()) return;

    if (publishInFlight) {
      nlSetResult('', mode === 'publish'
        ? 'Already publishing this listing — waiting for eBay to answer.'
        : 'Already saving.');
      return;
    }

    // Claimed before the first await below, not after it. The in-flight flag is what stops a second
    // click becoming a second live listing, and a guard that yields between its test and its set is
    // a guard two quick clicks walk straight through.
    publishInFlight = true;
    const publishBtn = $('nl-btn-publish');
    const draftBtn = $('nl-btn-draft');
    if (publishBtn) publishBtn.disabled = true;
    if (draftBtn) draftBtn.disabled = true;
    hideFailure('nl-failure');

    const endpoint = mode === 'publish' ? '/api/listing/publish' : '/api/listing/post';
    nlSetResult('', mode === 'publish' ? 'Publishing to eBay…' : 'Saving draft…');

    try {
      // Committed to disk before anything is sent. If the app dies mid-publish, this is the row that
      // comes back as "publish outcome unknown" with a Check eBay button beside it.
      //
      // Awaited, which it was not. The comment above has always said "before anything is sent", and
      // the code underneath it fired the save and moved straight on to the publish — two requests
      // racing, on the one path where their order decides what the seller is told afterwards. The
      // publish marks the row `publishing`; a save landing a moment later used to write it back to
      // `editing`, and took the unresolved-publish warning with it.
      //
      // A save that fails is no longer a reason to hold up the publish: the app now journals the
      // attempt whether or not a draft ever reached it.
      payload.workKey = currentWorkKey();
      await flushAutosave(false);

      // Upload photos to eBay EPS before publishing so eBay has accessible URLs
      if (mode === 'publish' && payload.imageUrls && payload.imageUrls.length > 0) {
        const wanted = payload.imageUrls.length;
        payload.imageUrls = await uploadPhotosToEbay(payload.imageUrls);

        // A listing that reaches eBay with no photograph does not sell, and this used to be a
        // four-second status line that then auto-hid — the publish carried on regardless and the
        // seller found out from the live listing. It is now a decision they get to make.
        if (payload.imageUrls.length === 0 && wanted > 0 && !nlPhotosDeliberatelyEmpty) {
          nlSetResult('error', 'None of the photos could be uploaded to eBay.');
          renderFailure('nl-failure', {
            kind: 'Photos',
            headline: `None of the ${wanted} photo${wanted === 1 ? '' : 's'} reached eBay`,
            whatHappened: 'Every photo upload failed, so publishing now would put a listing live with no '
                        + 'pictures at all.',
            whatToDo: 'Try again — photo uploads usually fail on a temporary connection problem. Publishing '
                    + 'without pictures is possible but sells very badly.',
            retryable: true,
            workPreserved: true,
            technical: 'See Logs for the per-photo eBay upload errors.',
          }, {
            onRetry: () => nlSubmit(mode),
            extraButtons: [{
              label: 'Publish without photos',
              run: () => { hideFailure('nl-failure'); nlSubmitWithoutPhotos(mode); },
            }],
          });
          addActivity('Publish stopped', 'No photos could be uploaded to eBay.');
          return;
        }
      }

      const { ok, data: body, failure } = await callApi(endpoint, {
        method: 'POST', body: payload, timeoutMs: PUBLISH_TIMEOUT_MS,
      });

      if (!ok) {
        const short = failure?.headline || body?.error || 'Request failed';
        const details = failure?.technical || body?.details || short;
        nlSetResult('error', (body?.where ? '[' + body.where + '] ' : '') + short);

        // Kept: both of these read eBay's own words to point at the field that needs changing, and
        // eBay's words are still carried through in the technical detail.
        nlHighlightPolicyIssues(short + ' ' + details);
        nlHighlightMissingSpecifics(short + ' ' + details);

        // A publish whose outcome the app cannot vouch for gets a "look, don't resend" button
        // instead of a Retry: pressing Retry on a publish that actually succeeded is what creates
        // the duplicate listing this whole path exists to prevent.
        const uncertain = mode === 'publish'
          && ['Timeout', 'Network', 'UpstreamServerError'].includes(failure?.kind);

        renderFailure('nl-failure', failure || {
          kind: 'Unknown', headline: short, whatHappened: details,
          whatToDo: 'Fix what is named above, then try again.', retryable: false, workPreserved: true,
        }, {
          onRetry: failure?.retryable ? () => nlSubmit(mode) : null,
          extraButtons: uncertain ? [{ label: 'Check eBay', run: () => nlCheckPublished(payload) }] : [],
        });

        addActivity(mode === 'publish' ? 'Publish failed' : 'Save draft failed', short);
        return;
      }

      if (mode === 'publish') {
        const link = body.listingUrl
          ? ' <a href="' + esc(body.listingUrl) + '" target="_blank" rel="noopener noreferrer">View on eBay</a>'
          : '';
        // Three distinct outcomes, said plainly. "Already live" and "just published" are not the same
        // thing, and a seller told the wrong one either goes looking for a listing that does not
        // exist or publishes a duplicate of one that does.
        const headline = body.alreadyPublished
          ? '✓ Already live — no second listing was created. ID: ' + (body.listingId || '-')
          : body.reconciled
            ? '✓ It did go live — the confirmation just got lost on the way back. ID: ' + (body.listingId || '-')
            : '✓ Published live! Listing ID: ' + (body.listingId || '-');
        nlSetResult('success', headline + (link ? ' —' : ''));
        $('nl-result-msg').innerHTML += link;
        if (body.message) {
          $('nl-result-msg').innerHTML += '<span class="nl-result-note">' + esc(body.message) + '</span>';
        }
        // What the publish did about the money, in the server's own words. Shown whether it recorded
        // the cost or refused to — a seller who thinks the cost was captured and finds out months
        // later that it wasn't has been told the wrong thing at the one moment they could fix it.
        if (body.costMessage) {
          $('nl-result-msg').innerHTML += '<span class="nl-result-note">' + esc(body.costMessage) + '</span>';
          addActivity('What this listing cost', body.costMessage);
        }
        addActivity('Listing published live', 'ID: ' + (body.listingId || '-') + '; Offer: ' + (body.offerId || '-'));
        loadListings('Listings refreshed after publish');
        // Published work is no longer unfinished work — stop offering it back.
        loadRecoverableWork();
      } else {
        const offerId = body.offerId || '-';
        const el = $('nl-result-msg');
        if (el) {
          el.className = 'nl-result-msg success';
          el.innerHTML =
            '✓ Draft saved (offer ID: ' + esc(offerId) + '). ' +
            '<a href="https://www.ebay.com/sh/inventory?status=UNPUBLISHED" target="_blank" rel="noopener noreferrer"><strong>View in Seller Hub → Inventory → Unpublished ↗</strong></a> — ' +
            'or publish now: ' +
            '<button type="button" class="btn btn-primary small" id="nl-publish-now-btn" style="margin-left:8px">Publish to eBay Live</button>';
          $('nl-publish-now-btn')?.addEventListener('click', () => nlSubmit('publish'));
        }
        addActivity('Draft saved', 'Offer ID: ' + offerId);
      }
    } catch (err) {
      // callApi does not throw, so anything landing here is a bug in this function rather than a
      // failed request — say so honestly instead of blaming eBay, and never imply work was lost.
      nlSetResult('error', 'The app hit an unexpected error before finishing.');
      renderFailure('nl-failure', {
        kind: 'Unknown',
        headline: 'The app hit an unexpected error',
        whatHappened: 'Something failed inside the app while ' + (mode === 'publish' ? 'publishing' : 'saving') + '.',
        whatToDo: 'Your listing is still on screen and autosaved. Try again, and send the detail below if it '
                + 'keeps happening.',
        retryable: true,
        workPreserved: true,
        technical: technicalDetail(err),
      }, { onRetry: () => nlSubmit(mode), });
      addActivity(mode === 'publish' ? 'Publish failed' : 'Save draft failed', technicalDetail(err));
    } finally {
      publishInFlight = false;
      if (publishBtn) publishBtn.disabled = false;
      if (draftBtn) draftBtn.disabled = false;
    }
  }

  // The seller has decided a photoless listing is better than no listing. Their call to make, so it
  // is offered as a button rather than decided for them in either direction.
  async function nlSubmitWithoutPhotos(mode) {
    nlPhotosDeliberatelyEmpty = true;
    try { await nlSubmit(mode); }
    finally { nlPhotosDeliberatelyEmpty = false; }
  }

  // "Did it actually go live?", asked without sending anything. This is the button offered instead of
  // Retry after a timeout, because a retry there is exactly what produces a duplicate listing.
  async function nlCheckPublished(payload) {
    nlSetResult('', 'Checking your live eBay listings…');
    const { ok, data, failure } = await callApi('/api/listing/check-published', {
      method: 'POST',
      body: { title: payload.title, workKey: payload.workKey },
      timeoutMs: 90000,
    });

    if (!ok) {
      renderFailure('nl-failure', failure, { onRetry: () => nlCheckPublished(payload) });
      nlSetResult('error', 'The check did not complete.');
      return;
    }

    if (data.found) {
      hideFailure('nl-failure');
      const link = data.listingUrl
        ? ' <a href="' + esc(data.listingUrl) + '" target="_blank" rel="noopener noreferrer">View on eBay</a>'
        : '';
      nlSetResult('success', '✓ It is live on eBay — listing ID ' + (data.listingId || '-') + '.' + (link ? ' —' : ''));
      $('nl-result-msg').innerHTML += link +
        '<span class="nl-result-note">' + esc(data.message || '') + '</span>';
      addActivity('Publish reconciled', 'The listing was already live — no duplicate was created.');
      loadListings('Listings refreshed after reconciling a publish');
      loadRecoverableWork();
      return;
    }

    // Not found is good news here, and worth saying so plainly: it makes publishing again safe.
    renderFailure('nl-failure', {
      kind: 'NotFound',
      headline: 'It did not go live',
      whatHappened: data.message || 'No live listing with this title was found on your account.',
      whatToDo: 'Publishing again is safe — there is nothing to duplicate.',
      retryable: true,
      workPreserved: true,
      technical: '',
    }, { onRetry: () => nlSubmit('publish') });
    nlSetResult('', 'Not found on eBay — publishing again is safe.');
  }

  // ── Settings page: the optional Image Generation strip ───────
  // The only place image generation is configured. It used to be configured here *and* at the top
  // of the setup modal, which meant two sets of fields for one setting, and the modal copy of it
  // sat above the API key — so the first thing a new seller was asked to decide was whether they
  // wanted a Stable Diffusion server, before anything told them what the app needed to run at all.

  function computePgImggenMode(imageGenMode, localSdBackend) {
    if (imageGenMode === 'dalle') return 'dalle';
    if (imageGenMode === 'local_sd') return localSdBackend === 'comfyui' ? 'comfyui' : 'a1111';
    return 'disabled';
  }

  function applyPgImggenVisibility(pgMode) {
    const isLocal = pgMode === 'a1111' || pgMode === 'comfyui';
    const isComfy = pgMode === 'comfyui';
    const ep = $('pg-imggen-endpoint-wrap');
    const m  = $('pg-imggen-model-wrap');
    if (ep) ep.style.display = isLocal ? '' : 'none';
    if (m)  m.style.display  = isComfy ? '' : 'none';
    if (pgMode === 'a1111') {
      const cur = $('pg-imggen-endpoint')?.value;
      if (!cur || cur === 'http://127.0.0.1:8188') setVal('pg-imggen-endpoint', 'http://127.0.0.1:7860');
    } else if (pgMode === 'comfyui') {
      const cur = $('pg-imggen-endpoint')?.value;
      if (!cur || cur === 'http://127.0.0.1:7860') setVal('pg-imggen-endpoint', 'http://127.0.0.1:8188');
    }
  }

  // The chip on the strip's header: what image generation is doing right now, in the same shape
  // as the Terapeak and Facebook connect states beside it.
  function renderImageGenState(pgMode) {
    const chip = $('pg-imggen-state');
    if (!chip) return;
    const labels = {
      disabled: 'Off',
      a1111:    'On · local AUTOMATIC1111',
      comfyui:  'On · local ComfyUI',
      dalle:    'On · OpenAI DALL·E 3',
    };
    chip.textContent = labels[pgMode] || 'Off';
    chip.classList.toggle('is-on', pgMode !== 'disabled');
  }

  async function savePgImggen() {
    const pgMode   = $('pg-imggen-mode')?.value || 'disabled';
    const endpoint = $('pg-imggen-endpoint')?.value.trim() || '';
    const model    = $('pg-imggen-model')?.value.trim() || '';
    const msg      = $('pg-imggen-msg');
    if (msg) { msg.textContent = 'Saving…'; msg.className = 'sd-test-msg'; }

    let imageGenMode, localSdBackend, localSdEndpoint;
    if (pgMode === 'a1111') {
      imageGenMode = 'local_sd'; localSdBackend = 'automatic1111';
      localSdEndpoint = endpoint || 'http://127.0.0.1:7860';
    } else if (pgMode === 'comfyui') {
      imageGenMode = 'local_sd'; localSdBackend = 'comfyui';
      localSdEndpoint = endpoint || 'http://127.0.0.1:8188';
    } else if (pgMode === 'dalle') {
      imageGenMode = 'dalle'; localSdBackend = 'automatic1111'; localSdEndpoint = '';
    } else {
      imageGenMode = 'disabled'; localSdBackend = 'automatic1111'; localSdEndpoint = '';
    }

    // Only the image-generation fields go up: this is an optional strip, and a save from it must
    // not touch the required setup. Everything absent from the body is left as it is on the server.
    const body = { imageGenMode, localSdBackend, localSdModelName: model };
    if (localSdEndpoint) body.localSdEndpoint = localSdEndpoint;
    const prompt = $('pg-image-prompt')?.value.trim();
    if (prompt !== undefined) body.imagePromptTemplate = prompt;

    try {
      const res = await fetch('/api/setup/save', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
      });
      if (!res.ok) throw new Error(await res.text());
      if (msg) { msg.textContent = pgMode === 'disabled' ? 'Saved — image generation is off.' : 'Saved.'; msg.className = 'sd-test-msg ok'; }
      renderImageGenState(pgMode);
      addActivity('Image generation settings saved', pgMode === 'disabled' ? 'Disabled' : pgMode);
    } catch (err) {
      if (msg) { msg.textContent = 'Save failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    }
  }

  async function loadComfyModels(endpoint, selectId, msgId) {
    const sel = $(selectId);
    const msg = msgId ? $(msgId) : null;
    if (!sel) return;
    if (!endpoint) {
      if (msg) { msg.textContent = 'Enter the ComfyUI endpoint first.'; msg.className = 'sd-test-msg error'; }
      return;
    }
    if (msg) { msg.textContent = 'Loading models…'; msg.className = 'sd-test-msg'; }
    try {
      const data = await fetch('/api/image-gen/comfyui-models?endpoint=' + encodeURIComponent(endpoint)).then(r => r.json());
      const models = data.models || [];
      if (models.length === 0) {
        if (msg) { msg.textContent = 'No checkpoints found in ComfyUI.'; msg.className = 'sd-test-msg error'; }
        return;
      }
      const current = sel.value;
      sel.innerHTML = models.map(m =>
        `<option value="${esc(m)}"${m === current ? ' selected' : ''}>${esc(m)}</option>`
      ).join('');
      if (msg) { msg.textContent = models.length + ' model(s) loaded.'; msg.className = 'sd-test-msg ok'; }
    } catch (err) {
      if (msg) { msg.textContent = 'Failed to load models: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    }
  }

  async function testPgImggenConnection() {
    const pgMode   = $('pg-imggen-mode')?.value || 'disabled';
    const endpoint = $('pg-imggen-endpoint')?.value.trim();
    const backend  = pgMode === 'comfyui' ? 'comfyui' : 'automatic1111';
    const msg      = $('pg-imggen-msg');
    const btn      = $('pg-imggen-test');

    if (pgMode === 'disabled' || pgMode === 'dalle') {
      if (msg) { msg.textContent = 'No local server to test in this mode.'; msg.className = 'sd-test-msg'; }
      return;
    }
    if (!endpoint) {
      if (msg) { msg.textContent = 'Enter a server URL first.'; msg.className = 'sd-test-msg error'; }
      return;
    }
    if (btn) { btn.disabled = true; btn.textContent = 'Testing…'; }
    if (msg) { msg.textContent = ''; msg.className = 'sd-test-msg'; }

    try {
      const res = await fetch('/api/image-gen/test-endpoint?endpoint=' + encodeURIComponent(endpoint) + '&backend=' + encodeURIComponent(backend))
        .then(r => r.json());
      if (msg) { msg.textContent = res.message; msg.className = 'sd-test-msg ' + (res.online ? 'ok' : 'error'); }
      if (res.online && pgMode === 'comfyui') {
        await loadComfyModels(endpoint, 'pg-imggen-model', 'pg-imggen-msg');
      }
    } catch (err) {
      if (msg) { msg.textContent = 'Error: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Test Connection'; }
    }
  }

  function bindPgImggen() {
    on('pg-imggen-mode', 'change', e => applyPgImggenVisibility(e.target.value));
    on('pg-imggen-save', 'click', savePgImggen);
    on('pg-imggen-test', 'click', testPgImggenConnection);
    on('pg-imggen-guide', 'click', openImageGenSetup);
    on('pg-imggen-load-models', 'click', () => {
      const endpoint = $('pg-imggen-endpoint')?.value.trim();
      loadComfyModels(endpoint, 'pg-imggen-model', 'pg-imggen-msg');
    });
    on('pg-defaults-save', 'click', saveListingDefaults);
    on('pg-fees-save', 'click', saveFeeProfile);
  }

  // ── Image Generator Setup Modal ──────────────────────────────

  function bindImageGenSetup() {
    on('imggen-close',     'click', closeImageGenSetup);
    on('imggen-btn-cancel','click', closeImageGenSetup);
    on('imggen-setup-overlay', 'click', e => {
      if (e.target === $('imggen-setup-overlay')) closeImageGenSetup();
    });
    $('imggen-setup-overlay')?.addEventListener('keydown', e => {
      if (e.key === 'Escape') closeImageGenSetup();
    });

    document.querySelectorAll('.imggen-tab').forEach(tab => {
      tab.addEventListener('click', () => switchImageGenTab(tab.dataset.imggenTab));
    });

    on('imggen-backend', 'change', () => {
      const backend = $('imggen-backend')?.value;
      if (backend === 'comfyui') {
        if ($('imggen-endpoint')?.value === 'http://127.0.0.1:7860') $('imggen-endpoint').value = 'http://127.0.0.1:8188';
        if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = '';
      } else {
        if ($('imggen-endpoint')?.value === 'http://127.0.0.1:8188') $('imggen-endpoint').value = 'http://127.0.0.1:7860';
        if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = 'none';
      }
    });

    on('imggen-btn-test', 'click', testImageGenConnection);
    on('imggen-btn-save', 'click', saveImageGenSettings);
    on('nl-imggen-setup-link',  'click', openImageGenSetup);
  }

  function openImageGenSetup() {
    // Pre-fill from the Settings-page strip, the one place these are configured.
    const pgMode   = $('pg-imggen-mode')?.value || 'disabled';
    const backend  = pgMode === 'comfyui' ? 'comfyui' : 'automatic1111';
    const endpoint = $('pg-imggen-endpoint')?.value || (backend === 'comfyui' ? 'http://127.0.0.1:8188' : 'http://127.0.0.1:7860');
    const model    = $('pg-imggen-model')?.value    || '';
    if ($('imggen-endpoint')) $('imggen-endpoint').value = endpoint;
    if ($('imggen-backend'))  $('imggen-backend').value  = backend;
    if ($('imggen-model'))    $('imggen-model').value    = model;
    if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = backend === 'comfyui' ? '' : 'none';

    const msg = $('imggen-test-msg');
    if (msg) { msg.textContent = ''; msg.className = 'sd-test-msg'; }

    $('imggen-setup-overlay')?.classList.remove('hidden');
    $('imggen-setup-overlay')?.focus();
    detectImageServers();
  }

  function closeImageGenSetup() {
    $('imggen-setup-overlay')?.classList.add('hidden');
  }

  function switchImageGenTab(tab) {
    document.querySelectorAll('.imggen-tab').forEach(t => t.classList.toggle('active', t.dataset.imggenTab === tab));
    ['stability','a1111','comfyui'].forEach(id => {
      $('imggen-panel-' + id)?.classList.toggle('hidden', id !== tab);
    });
    if (tab === 'comfyui') {
      if ($('imggen-backend')) $('imggen-backend').value = 'comfyui';
      if ($('imggen-endpoint')?.value === 'http://127.0.0.1:7860') $('imggen-endpoint').value = 'http://127.0.0.1:8188';
      if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = '';
    } else if (tab === 'a1111') {
      if ($('imggen-backend')) $('imggen-backend').value = 'automatic1111';
      if ($('imggen-endpoint')?.value === 'http://127.0.0.1:8188') $('imggen-endpoint').value = 'http://127.0.0.1:7860';
      if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = 'none';
    }
    // stability tab: leave backend/endpoint as-is so user can choose
  }

  async function detectImageServers() {
    const banner = $('imggen-detect-banner');
    const text   = $('imggen-detect-text');
    if (banner) banner.className = 'imggen-detect-banner detecting';
    if (text)   text.textContent = 'Checking for running image servers...';

    try {
      const result = await fetch('/api/image-gen/detect').then(r => r.json());
      let msg, cls;

      if (result.a1111Online && result.comfyOnline) {
        msg = 'Both AUTOMATIC1111 (port 7860) and ComfyUI (port 8188) detected. Select which backend to use below.';
        cls = 'detected';
      } else if (result.a1111Online) {
        msg = 'AUTOMATIC1111 detected at ' + result.a1111Endpoint + '. Click Test Connection to confirm, then Enable & Save.';
        cls = 'detected';
        if ($('imggen-backend'))  $('imggen-backend').value  = 'automatic1111';
        if ($('imggen-endpoint')) $('imggen-endpoint').value = result.a1111Endpoint;
        if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = 'none';
      } else if (result.comfyOnline) {
        msg = 'ComfyUI detected at ' + result.comfyEndpoint + '. Enter the checkpoint name below, then click Test Connection.';
        cls = 'detected';
        if ($('imggen-backend'))  $('imggen-backend').value  = 'comfyui';
        if ($('imggen-endpoint')) $('imggen-endpoint').value = result.comfyEndpoint;
        if ($('imggen-model-wrap')) $('imggen-model-wrap').style.display = '';
      } else {
        msg = 'No local image server detected at ports 7860 or 8188. Follow the setup guide below to install one.';
        cls = 'not-detected';
      }

      if (banner) banner.className = 'imggen-detect-banner ' + cls;
      if (text)   text.textContent = msg;
    } catch (err) {
      if (banner) banner.className = 'imggen-detect-banner not-detected';
      if (text)   text.textContent = 'Detection error: ' + errorText(err);
    }
  }

  async function testImageGenConnection() {
    const btn      = $('imggen-btn-test');
    const msg      = $('imggen-test-msg');
    const endpoint = $('imggen-endpoint')?.value.trim();
    const backend  = $('imggen-backend')?.value || 'automatic1111';

    if (!endpoint) {
      if (msg) { msg.textContent = 'Enter a server URL first.'; msg.className = 'sd-test-msg error'; }
      return;
    }

    if (btn) { btn.disabled = true; btn.textContent = 'Testing...'; }
    if (msg) { msg.textContent = ''; msg.className = 'sd-test-msg'; }

    try {
      const res = await fetch('/api/image-gen/test-endpoint?endpoint=' + encodeURIComponent(endpoint) + '&backend=' + encodeURIComponent(backend))
        .then(r => r.json());
      if (msg) {
        msg.textContent = res.message;
        msg.className = 'sd-test-msg ' + (res.online ? 'ok' : 'error');
      }
    } catch (err) {
      if (msg) { msg.textContent = 'Error: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Test Connection'; }
    }
  }

  async function saveImageGenSettings() {
    const endpoint = $('imggen-endpoint')?.value.trim() || 'http://127.0.0.1:7860';
    const backend  = $('imggen-backend')?.value || 'automatic1111';
    const model    = $('imggen-model')?.value.trim() || '';
    const msg      = $('imggen-test-msg');

    try {
      const res = await fetch('/api/setup/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ imageGenMode: 'local_sd', localSdEndpoint: endpoint, localSdBackend: backend, localSdModelName: model })
      });
      if (!res.ok) throw new Error(await res.text());

      // Sync the Settings-page strip, which is where this setting lives.
      const pgMode = backend === 'comfyui' ? 'comfyui' : 'a1111';
      setVal('pg-imggen-mode', pgMode);
      applyPgImggenVisibility(pgMode);
      setVal('pg-imggen-endpoint', endpoint);
      setModelSelect('pg-imggen-model', model);
      renderImageGenState(pgMode);

      addActivity('Local image generation enabled', 'Backend: ' + backend + '; Endpoint: ' + endpoint);
      closeImageGenSetup();
    } catch (err) {
      if (msg) { msg.textContent = 'Save failed: ' + errorText(err); msg.className = 'sd-test-msg error'; }
    }
  }

  function bindForm() {
    on('btn-new-listing', 'click', () => {
      activeOfferId = '';
      activeListingId = '';
      activeSku = '';
      activeListingStatus = '';
      pendingDraftPayload = null;
      hideDraftPreview();
      document.querySelectorAll('.listing-card.active').forEach(c => c.classList.remove('active'));
      $('btn-post')?.classList.remove('hidden');
      $('btn-create-ebay-draft')?.classList.add('hidden');
      $('btn-update')?.classList.add('hidden');
      $('btn-new-listing')?.classList.add('hidden');
      $('form-section')?.classList.add('hidden');
      closeEditDrawer(true);   // leaving edit mode entirely — nothing to warn about
      showAiSection();
      hideResult();
    });

    // Pushes straight to the live eBay listing — same call the New Listing "Publish to eBay"
    // button uses under the hood (UpdateListingAsync/ReviseInventoryStatusAsync in
    // EbayService.cs), no separate "local only" step first. UpdateListingAsync picks the right
    // eBay API automatically: the Inventory API if this listing has an offerId (created through
    // this app), or the Trading API's ReviseInventoryStatus (price/quantity) if it only has a
    // ListingId (imported from eBay directly, which is most of a seller's existing catalog).
    on('btn-update', 'click', async () => {
      if (!canReviseOnEbay({ offerId: activeOfferId, listingId: activeListingId, sku: activeSku, status: activeListingStatus })) {
        showResult('error', 'This is a sample/placeholder listing — it was never published to eBay, so there is nothing to update there.');
        return;
      }
      if (!confirm('This will push these changes directly to your live eBay listing. Continue?')) return;

      const btn = $('btn-update');
      btn.disabled = true;
      btn.textContent = 'Publishing to eBay…';
      hideResult();

      const payload = buildPayload();
      payload.offerId = activeOfferId;
      payload.listingId = activeListingId;
      payload.sku = activeSku;
      payload.manualRevisionConfirmed = true;

      try {
        const res = await fetch('/api/listing/update', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        if (!res.ok) throw new Error(await res.text());
        const updated = await res.json().catch(() => ({}));

        // Keep the local dashboard cache in sync too — best-effort, doesn't affect the
        // already-successful eBay update if it fails for some reason.
        try {
          const editRes = await fetch('/api/local-listings/save-edit', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (editRes.ok) applyLocalEdit(payload, (await editRes.json()).savedAt);
        } catch { /* non-fatal */ }

        // Name the fields that reached eBay. "Published to eBay live" was shown even when the
        // call underneath carried only price and quantity, so the one thing this message must
        // never do again is claim more than actually happened.
        const changed = Array.isArray(updated.changed) ? updated.changed : [];
        const warnings = Array.isArray(updated.warnings) ? updated.warnings : [];
        let msg = changed.length
          ? `✓ Published to eBay live — updated ${changed.join(', ')}.`
          : '✓ Published to eBay live.';
        if (warnings.length) msg += ` eBay noted: ${warnings.join(' ')}`;
        showResult(warnings.length ? 'warning' : 'success', msg);
        addActivity('eBay listing updated', payload.title || activeSku);
        loadListings('Listings refreshed after eBay update');
      } catch (err) {
        showResult('error', `eBay update failed: ${esc(errorText(err))}`);
        addActivity('eBay update failed', errorText(err));
      } finally {
        btn.disabled = false;
        btn.textContent = 'Save Changes';
      }
    });

    on('listing-form', 'submit', e => {
      e.preventDefault();
      pendingDraftPayload = buildPayload();
      renderDraftPreview(pendingDraftPayload);
      showResult('success', 'Draft preview is ready. Live publishing will be added behind a separate confirmation workflow.');
      addActivity('Draft preview prepared', $('f-title')?.value || 'Untitled draft');
      $('btn-create-ebay-draft')?.classList.remove('hidden');
    });

    on('btn-create-ebay-draft', 'click', async () => {
      if (!pendingDraftPayload) pendingDraftPayload = buildPayload();
      const ok = window.confirm('Create an eBay draft offer now? This will not publish the listing.');
      if (!ok) return;

      const btn = $('btn-create-ebay-draft');
      btn.disabled = true;
      btn.textContent = 'Creating draft...';
      hideResult();

      try {
        const { res, body } = await safePost('/api/listing/post', pendingDraftPayload);
        if (!res.ok) {
          const short   = body.error   || 'Request failed';
          const details = body.details || short;
          const where   = body.where   ? ' [' + body.where + ']' : '';
          showResult('error', 'Draft creation failed' + where + ': ' + esc(short)
            + (details !== short ? '<br><small style="opacity:.8">' + esc(details) + '</small>' : ''));
          addActivity('Draft creation failed', 'HTTP ' + res.status + ': ' + short);
        } else {
          showResult('success', 'eBay draft created. Offer ID: ' + esc(body.offerId || '-') + '. It has not been published.');
          addActivity('eBay draft created', body.offerId || pendingDraftPayload.title || 'Draft offer');
        }
      } catch (err) {
        showResult('error', 'Draft creation failed: ' + esc(errorText(err)));
        addActivity('Draft creation failed', errorText(err));
      } finally {
        btn.disabled = false;
        btn.textContent = 'Create eBay Draft';
      }
    });

    on('btn-new-from-edit', 'click', openNewListingModal);
    on('f-title', 'input', () => updateCharCount('f-title', 'title-count', 80));
    on('f-subtitle', 'input', () => updateCharCount('f-subtitle', 'subtitle-count', 55));
    on('f-best-offer', 'change', e => toggleBestOfferFields(e.target.checked));
    on('f-format', 'change', e => {
      $('duration-wrap').style.display = e.target.value === 'AUCTION' ? '' : 'none';
    });
    if ($('duration-wrap')) $('duration-wrap').style.display = 'none';
    initDescTabs('f');   // same description tabs as the New Listing form
    on('btn-add-specific', 'click', () => addSpecificRow('', ''));
    on('btn-add-photo-url', 'click', () => addPhotoRow(''));
  }

  function fillForm(d) {
    set('f-title', d.title || '');
    set('f-subtitle', d.subtitle || '');
    set('f-category', d.category || '');
    set('f-category-id', d.categoryId || '');
    set('f-secondary-category-id', d.secondaryCategoryId || '');
    set('f-condition', d.condition || 'USED_EXCELLENT');
    set('f-condition-desc', d.conditionDescription || '');
    set('f-brand', d.brand || '');
    set('f-mpn', d.mpn || '');
    set('f-upc', d.upc || '');
    set('f-ean', d.ean || '');
    set('f-isbn', d.isbn || '');
    descSetHtml('f', d.description || '');   // all three tabs, landing on the readable one
    set('f-price', d.price || '');
    set('f-quantity', d.quantity || 1);
    set('f-qty-limit', d.quantityLimitPerBuyer || '');
    set('f-package-type', d.packageType || 'PACKAGE_THICK_ENVELOPE');
    set('f-weight-lbs', d.weightLbs || 0);
    set('f-weight-oz', d.weightOz || 0);
    set('f-length', d.packageLengthIn || '');
    set('f-width', d.packageWidthIn || '');
    set('f-height', d.packageHeightIn || '');
    set('f-handling-time', d.handlingTimeBusinessDays || 1);
    set('f-location-zip', d.itemLocationPostalCode || '');
    set('f-location-country', d.itemLocationCountry || 'US');
    set('f-charity-pct', d.charityDonationPercentage || 0);
    set('f-charity-id', d.charityId || '');

    const bestOffer = !!d.bestOfferEnabled;
    if ($('f-best-offer')) $('f-best-offer').checked = bestOffer;
    toggleBestOfferFields(bestOffer);
    if (bestOffer) {
      set('f-auto-accept', '');
      set('f-auto-decline', '');
    }

    if ($('f-private')) $('f-private').checked = !!d.privateListing;

    const list = $('specifics-list');
    if (list) list.innerHTML = '';
    if (d.itemSpecifics) {
      Object.entries(d.itemSpecifics).forEach(([k, v]) => addSpecificRow(k, v));
    }

    const photos = $('photo-url-list');
    if (photos) photos.innerHTML = '';
    (d.imageUrls || []).forEach(url => addPhotoRow(url));

    updateCharCount('f-title', 'title-count', 80);
    updateCharCount('f-subtitle', 'subtitle-count', 55);
    scheduleTakeHome('f');   // a new price means a new take-home
  }

  function toggleBestOfferFields(show) {
    if ($('best-offer-fields')) $('best-offer-fields').style.display = show ? '' : 'none';
    if ($('best-offer-decline')) $('best-offer-decline').style.display = show ? '' : 'none';
  }

  function addSpecificRow(key, value) {
    const row = document.createElement('div');
    row.className = 'specific-row';
    row.innerHTML = `
      <input type="text" placeholder="Name, e.g. Model" value="${esc(key)}" />
      <input type="text" placeholder="Value" value="${esc(value)}" />
      <button type="button" title="Remove">X</button>`;
    row.querySelector('button')?.addEventListener('click', () => row.remove());
    $('specifics-list')?.appendChild(row);
  }

  function addPhotoRow(value) {
    const row = document.createElement('div');
    row.className = 'photo-url-row';
    row.innerHTML = `
      <input type="url" placeholder="https://example.com/photo.jpg" value="${esc(value)}" />
      <button type="button" title="Remove">X</button>`;
    row.querySelector('button')?.addEventListener('click', () => row.remove());
    $('photo-url-list')?.appendChild(row);
  }

  function collectSpecifics() {
    const out = {};
    document.querySelectorAll('.specific-row').forEach(row => {
      const [k, v] = row.querySelectorAll('input');
      if (k.value.trim()) out[k.value.trim()] = v.value.trim();
    });
    return out;
  }

  function collectPhotoUrls() {
    return [...document.querySelectorAll('.photo-url-row input')]
      .map(input => input.value.trim())
      .filter(Boolean);
  }

  function applyLocalEdit(payload, savedAt) {
    const listing = cachedListings.find(l =>
      (payload.listingId && l.listingId === payload.listingId) ||
      (payload.offerId && l.offerId === payload.offerId) ||
      (payload.sku && l.sku === payload.sku)
    );
    if (!listing) return;

    listing.title = payload.title;
    listing.price = payload.price;
    listing.quantity = payload.quantity;
    listing.category = payload.category;
    listing.categoryId = payload.categoryId;
    listing.thumbnailUrl = payload.imageUrls[0] || listing.thumbnailUrl || '';
    listing.condition = payload.condition;
    listing.status = (listing.status || '').toUpperCase() === 'SAMPLE' ? 'SAMPLE' : 'LOCAL_EDIT';
    listing.lastUpdated = savedAt || new Date().toISOString();
    listing.data = { ...payload };
    renderListings();
    updateStats();
    markDrawerClean();   // saved — drop the unsaved-changes guard
  }

  function renderDraftPreview(payload) {
    const panel = $('draft-preview-panel');
    if (!panel) return;

    panel.innerHTML = `
      <h3>Draft Preview</h3>
      <div class="draft-preview-grid">
        ${previewItem('Title', payload.title || 'Untitled draft')}
        ${previewItem('Price', money(payload.price))}
        ${previewItem('Quantity', payload.quantity || 1)}
        ${previewItem('Category', payload.category || payload.categoryId || '-')}
        ${previewItem('Condition', displayStatus(payload.condition || ''))}
        ${previewItem('Photos', `${payload.imageUrls.length} URL${payload.imageUrls.length === 1 ? '' : 's'}`)}
        ${previewItem('Item Specifics', Object.keys(payload.itemSpecifics || {}).length)}
        ${previewItem('Shipping', `${payload.weightLbs || 0} lb ${payload.weightOz || 0} oz`)}
      </div>`;
    panel.classList.remove('hidden');
  }

  function hideDraftPreview() {
    const panel = $('draft-preview-panel');
    if (!panel) return;
    panel.classList.add('hidden');
    panel.innerHTML = '';
  }

  function previewItem(label, value) {
    return `<div class="draft-preview-item"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;
  }

  function buildPayload() {
    descCommitText('f');   // words typed on the text tab, before the HTML field is read
    return {
      title: $('f-title').value,
      subtitle: $('f-subtitle').value,
      category: $('f-category').value,
      categoryId: $('f-category-id').value,
      secondaryCategoryId: $('f-secondary-category-id').value,
      condition: $('f-condition').value,
      conditionDescription: $('f-condition-desc').value,
      brand: $('f-brand').value,
      mpn: $('f-mpn').value,
      upc: $('f-upc').value,
      ean: $('f-ean').value,
      isbn: $('f-isbn').value,
      description: $('f-description').value,
      price: parseFloat($('f-price').value) || 0,
      quantity: parseInt($('f-quantity').value, 10) || 1,
      quantityLimitPerBuyer: parseInt($('f-qty-limit').value, 10) || null,
      bestOfferEnabled: $('f-best-offer').checked,
      autoAcceptPrice: $('f-best-offer').checked ? parseFloat($('f-auto-accept').value) || null : null,
      autoDeclinePrice: $('f-best-offer').checked ? parseFloat($('f-auto-decline').value) || null : null,
      itemLocationPostalCode: $('f-location-zip').value,
      itemLocationCountry: $('f-location-country').value || 'US',
      packageType: $('f-package-type').value,
      weightLbs: parseFloat($('f-weight-lbs').value) || 0,
      weightOz: parseFloat($('f-weight-oz').value) || 0,
      packageLengthIn: parseFloat($('f-length').value) || 0,
      packageWidthIn: parseFloat($('f-width').value) || 0,
      packageHeightIn: parseFloat($('f-height').value) || 0,
      handlingTimeBusinessDays: parseInt($('f-handling-time').value, 10) || 1,
      privateListing: $('f-private').checked,
      charityDonationPercentage: parseInt($('f-charity-pct').value, 10) || 0,
      charityId: $('f-charity-id').value,
      listingFormat: $('f-format').value,
      durationDays: parseInt($('f-duration').value, 10) || 7,
      itemSpecifics: collectSpecifics(),
      imageUrls: collectPhotoUrls(),
    };
  }

  function listingSearchText(listing) {
    return [
      listing.title,
      listing.sku,
      listing.listingId,
      listing.status,
      listingCategory(listing),
      listingUpdated(listing)
    ].join(' ').toLowerCase();
  }

  function listingCategory(listing) {
    return listing.category || listing.categoryId || listing.data?.category || listing.data?.categoryId || '-';
  }

  function listingUpdated(listing) {
    const value = listing.lastUpdated || listing.updatedAt || listing.data?.lastUpdated || '';
    if (!value) return 'Not synced';
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString();
  }

  function displayStatus(status) {
    if (!status) return 'Unknown';
    if (status.toUpperCase() === 'PUBLISHED') return 'Live';
    if (status.toUpperCase() === 'ACTIVE') return 'Active';
    if (status.toUpperCase() === 'SAMPLE') return 'Sample';
    if (status.toUpperCase() === 'LOCAL_EDIT') return 'Local edit';
    return status.replaceAll('_', ' ');
  }

  function statusClass(status) {
    const upper = (status || '').toUpperCase();
    if (upper === 'PUBLISHED' || upper === 'ACTIVE') return 'status-chip live';
    if (upper === 'SAMPLE') return 'status-chip sample';
    if (upper === 'LOCAL_EDIT') return 'status-chip local';
    if (!upper || upper === 'DRAFT') return 'status-chip review';
    return 'status-chip';
  }

  // ── Data visualisation primitives ─────────────────────────────────────────
  //
  // Five marks, one tooltip, one rule about colour. Every chart on every money
  // screen is built from these rather than from its own inline SVG, so the
  // profit chart, a sell-through meter and a trend sparkline are recognisably
  // the same drawing hand. The palette and the mark specs live in style.css
  // under "Data visualisation" — including why the brand teal could not be
  // slot 1 without being nudged over the chroma floor first.
  //
  // Three rules hold across all of them:
  //   * the value is never trapped in a tooltip — it is always in a direct
  //     label, the legend, or the table twin under the chart as well;
  //   * text never wears the data colour, only the mark beside it does;
  //   * a hit target is the whole band, never the mark, and is keyboard
  //     reachable wherever it carries something the eye cannot already read.

  // A share of a whole, drawn as a track and a fill. Tone is by threshold, not
  // by rank, so the same percentage is always the same colour — a meter that
  // recolours because the rest of the list changed is telling the reader
  // something that isn't true about this row.
  function vizToneForPercent(pct, { good = 60, mid = 30 } = {}) {
    if (!Number.isFinite(pct)) return 'flat';
    if (pct >= good) return 'good';
    if (pct >= mid) return 'mid';
    return 'low';
  }

  function vizMeter(percent, { max = 100, tone, valueText, label, tip } = {}) {
    const pct = Number(percent);
    if (!Number.isFinite(pct)) return '';
    const width = Math.max(0, Math.min(100, (pct / (max || 100)) * 100));
    const cls = tone || vizToneForPercent(pct);
    const text = valueText != null ? valueText : `${Math.round(pct)}%`;
    return `<div class="viz-meter viz-tone-${cls}" role="img"
      aria-label="${esc(label || `${text} of ${max}`)}"${tip ? ` data-viz-tip="${esc(tip)}"` : ''}>
      <span class="viz-meter-track"><span class="viz-meter-fill" style="width:${width.toFixed(1)}%"></span></span>
      ${valueText === '' ? '' : `<span class="viz-meter-value">${esc(text)}</span>`}
    </div>`;
  }

  // A top-five list is a bar chart that was never drawn. Each row is
  // { label, value, valueText, percent, tone, href, tip } — `percent` is the
  // bar length, already resolved by the caller against whichever scale is
  // honest for that card (0–100 for a rate, set-maximum for a count).
  function vizRankBars(rows, { note } = {}) {
    if (!rows.length) return '';
    const body = rows.map(r => {
      const cls = r.tone || 'solo';
      const name = r.href
        ? `<a href="${esc(r.href)}" target="_blank" rel="noopener">${esc(r.label)}</a>`
        : esc(r.label);
      // A signed row gets the diverging chip instead of a left-anchored bar: a bar that grows from
      // the left cannot show a price that went DOWN, and these lists contain both.
      const mark = r.delta != null
        ? vizDelta(r.delta, { scale: r.deltaScale, label: `${r.label}, ${r.valueText}` })
        : `<span class="viz-rank-track"><span class="viz-rank-bar" style="width:${Math.max(0, Math.min(100, Number(r.percent) || 0)).toFixed(1)}%"></span></span>`;
      return `<div class="viz-rank-row viz-tone-${cls}"${r.tip ? ` data-viz-tip="${esc(r.tip)}"` : ''}>
        <span class="viz-rank-label" title="${esc(r.label)}">${name}</span>
        ${mark}
        <span class="viz-rank-value">${esc(r.valueText)}</span>
      </div>`;
    }).join('');
    return `<div class="viz-rank">${body}</div>${note ? `<p class="viz-rank-note">${esc(note)}</p>` : ''}`;
  }

  // A signed change, drawn out from a shared centre so "+8%" and "−8%" are the
  // same length in opposite directions. `scale` is the value that fills half
  // the chip; anything beyond it clamps rather than rescaling the row, because
  // one runaway outlier must not flatten every other row on the board.
  function vizDelta(percent, { scale = 30, label } = {}) {
    const pct = Number(percent);
    if (!Number.isFinite(pct)) return '';
    const frac = Math.min(1, Math.abs(pct) / (scale || 30)) * 100;
    const text = `${pct > 0 ? '+' : pct < 0 ? '−' : ''}${Math.abs(pct).toFixed(1)}%`;
    return `<span class="viz-delta" role="img" aria-label="${esc(label || text)}">
      <span class="viz-delta-neg" style="width:${pct < 0 ? frac.toFixed(1) : 0}%"></span>
      <span class="viz-delta-pos" style="width:${pct > 0 ? frac.toFixed(1) : 0}%"></span>
    </span>`;
  }

  // One whole broken into its parts, with a legend that carries every value —
  // so the picture is the fast read and nothing is only in the picture.
  // Segments are { name, value, slot, tip }; `slot` is a fixed categorical
  // position (1-4) or 'none' for the grey unmeasured share.
  function vizStack(segments, { total, formatter = moneyExact } = {}) {
    const sum = total || segments.reduce((a, s) => a + Math.max(0, s.value || 0), 0);
    if (!(sum > 0)) return '';

    const share = v => (Math.max(0, v || 0) / sum) * 100;
    const bar = segments.filter(s => share(s.value) > 0).map(s => `
      <div class="viz-seg viz-seg-${esc(String(s.slot))}" style="flex:${share(s.value).toFixed(3)} 1 0"
        data-viz-tip="${esc(`${s.name}\n${formatter(s.value)} · ${share(s.value).toFixed(1)}% of every dollar taken in${s.tip ? `\n${s.tip}` : ''}`)}">
        <span class="viz-seg-label">${esc(formatter(s.value))}</span>
      </div>`).join('');

    const legend = segments.map(s => `
      <span class="viz-legend-item">
        <span class="viz-swatch viz-swatch-${esc(String(s.slot))}"></span>
        <span class="viz-legend-name">${esc(s.name)}</span>
        <span class="viz-legend-value">${esc(formatter(s.value))}</span>
        <span class="viz-legend-share">${share(s.value).toFixed(1)}%</span>
      </span>`).join('');

    return `<div class="viz-stack">${bar}</div><div class="viz-legend">${legend}</div>`;
  }

  // A label inside a coloured segment is only drawn once the browser has
  // confirmed it fits with padding on both sides. Measuring is the only way to
  // know: a segment's width comes from its share and the card's width, neither
  // of which is knowable when the HTML is built. A clipped "$1,2…" is worse
  // than no label at all, and every value is in the legend regardless.
  function vizFitSegmentLabels(host) {
    if (!host) return;
    const measure = () => host.querySelectorAll('.viz-seg').forEach(seg => {
      const label = seg.querySelector('.viz-seg-label');
      if (!label) return;
      seg.classList.toggle('viz-fits', seg.clientWidth > 0 && label.scrollWidth + 16 <= seg.clientWidth);
    });
    measure();
    // The card can be re-measured by a window resize or by the screen it lives
    // on being opened for the first time, which is when its width stops being
    // zero. One observer per host, replaced on re-render.
    host._vizFitObserver?.disconnect();
    if (typeof ResizeObserver === 'function') {
      host._vizFitObserver = new ResizeObserver(measure);
      host._vizFitObserver.observe(host);
    }
  }

  // Gap-aware sparkline. Points are { x, value, gap } in order; a gapped point
  // breaks the line rather than being interpolated through, because joining
  // straight across a month with no data draws a steady series out of an
  // intermittent one. Returns the inner SVG markup — the caller owns the
  // <svg> element so it can size and tone it.
  function vizSparkPaths(points, { w, h, pad = 3, area = true, endDot = true }) {
    const live = points.filter(p => !p.gap && Number.isFinite(p.value));
    if (live.length < 2) return '';

    const values = live.map(p => p.value);
    const min = Math.min(...values), max = Math.max(...values);
    const span = (max - min) || 1;
    const step = points.length > 1 ? (w - pad * 2) / (points.length - 1) : 0;
    const xy = i => [pad + i * step, h - pad - ((points[i].value - min) / span) * (h - pad * 2)];

    // One run per unbroken stretch of real readings.
    const runs = [];
    let run = [];
    points.forEach((p, i) => {
      if (!p.gap && Number.isFinite(p.value)) run.push(i);
      else { if (run.length) runs.push(run); run = []; }
    });
    if (run.length) runs.push(run);

    const drawn = runs.filter(r => r.length > 1);
    const lines = drawn.map(r =>
      `<polyline class="viz-spark-line" points="${r.map(i => xy(i).map(n => n.toFixed(1)).join(',')).join(' ')}" />`).join('');

    const fills = area ? drawn.map(r => {
      const pts = r.map(i => xy(i).map(n => n.toFixed(1)).join(' ')).join(' L');
      const [x0] = xy(r[0]), [xN] = xy(r[r.length - 1]);
      return `<path class="viz-spark-area" d="M${x0.toFixed(1)} ${(h - pad).toFixed(1)} L${pts} L${xN.toFixed(1)} ${(h - pad).toFixed(1)} Z" />`;
    }).join('') : '';

    const lastRun = drawn[drawn.length - 1];
    const dot = endDot && lastRun
      ? (([x, y]) => `<circle class="viz-spark-end" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3" />`)(xy(lastRun[lastRun.length - 1]))
      : '';

    return `${fills}${lines}${dot}`;
  }

  // ── One tooltip for every chart ───────────────────────────────────────────
  // Driven off data-viz-tip, so any mark — SVG or HTML — opts in with one
  // attribute and gets the same styled, positioned, keyboard-reachable
  // tooltip. Newlines in the attribute become lines; the first is the title.
  let vizTipEl = null;

  function initVizTooltips() {
    if (vizTipEl) return;
    vizTipEl = document.createElement('div');
    vizTipEl.className = 'viz-tip';
    vizTipEl.setAttribute('role', 'tooltip');
    vizTipEl.hidden = true;
    document.body.appendChild(vizTipEl);

    document.addEventListener('pointerover', e => showVizTip(e.target?.closest?.('[data-viz-tip]')));
    document.addEventListener('pointerout', e => { if (e.target?.closest?.('[data-viz-tip]')) hideVizTip(); });
    // Keyboard raises exactly what hover raises. A value a mouse can reach and
    // a caret cannot is a value that isn't really there.
    document.addEventListener('focusin', e => showVizTip(e.target?.closest?.('[data-viz-tip]')));
    document.addEventListener('focusout', hideVizTip);
    document.addEventListener('keydown', e => { if (e.key === 'Escape') hideVizTip(); });
    // Anchored to a rect that scrolling moves, so it is dismissed rather than
    // left floating over unrelated content.
    window.addEventListener('scroll', hideVizTip, true);
  }

  function showVizTip(target) {
    if (!target || !vizTipEl) return;
    const raw = target.getAttribute('data-viz-tip');
    if (!raw) return;

    const [title, ...rest] = raw.split('\n');
    vizTipEl.innerHTML = `<span class="viz-tip-title">${esc(title)}</span>` +
      rest.map(line => `<span class="viz-tip-line">${esc(line)}</span>`).join('');
    vizTipEl.hidden = false;

    const box = target.getBoundingClientRect();
    const tip = vizTipEl.getBoundingClientRect();
    const margin = 8;
    let left = box.left + box.width / 2 - tip.width / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - tip.width - margin));
    // Above the mark by default; below it when there is no room above, so the
    // tooltip never covers the thing it is describing.
    const above = box.top - tip.height - margin;
    vizTipEl.style.left = `${Math.round(left)}px`;
    vizTipEl.style.top = `${Math.round(above > margin ? above : box.bottom + margin)}px`;
    vizTipEl.classList.add('is-open');
  }

  function hideVizTip() {
    if (!vizTipEl) return;
    vizTipEl.classList.remove('is-open');
    vizTipEl.hidden = true;
  }

  function money(value) {
    const number = parseFloat(value) || 0;
    return number.toLocaleString(undefined, { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  }

  // money() rounds to whole dollars, which is fine for sold comps but would misstate a
  // fee-adjusted cross-listing price by up to 50 cents — the cents are the whole point there.
  function moneyExact(value) {
    const number = parseFloat(value) || 0;
    return number.toLocaleString(undefined, {
      style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2,
    });
  }

  function updateCharCount(inputId, countId, max) {
    if (!$(inputId) || !$(countId)) return;
    const len = $(inputId).value.length;
    $(countId).textContent = `${len} / ${max}`;
    $(countId).style.color = len > max * .9 ? 'var(--danger)' : '';
  }

  function showResult(type, html) {
    const el = $('result');
    if (!el) return;
    el.className = type;
    el.innerHTML = html;
    el.classList.remove('hidden');
    el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function hideResult() {
    $('result')?.classList.add('hidden');
  }

  function setVal(id, val) {
    const el = $(id);
    if (el) el.value = val;
  }

  async function safePost(url, payload) {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    noteBackendReachable();
    if (res.status === 402) {
      const b = await res.clone().json().catch(() => ({}));
      if (b.error === 'trial_expired') { throw new Error(b.message || 'Error.'); }
    }
    const text = await res.text();
    let body;
    try { body = JSON.parse(text); }
    catch { body = { ok: false, error: text, details: text }; }
    return { res, body };
  }

  function setValue(id, val) {
    const el = $(id);
    if (el && val) el.value = val;
  }

  // For dynamic <select> elements whose options may not be loaded yet —
  // adds the saved value as an option so it's preserved until the full list loads.
  function setModelSelect(id, val) {
    const sel = $(id);
    if (!sel || !val) return;
    if (![...sel.options].some(o => o.value === val)) {
      const opt = document.createElement('option');
      opt.value = val; opt.textContent = val;
      sel.appendChild(opt);
    }
    sel.value = val;
  }

  function set(id, val) {
    const el = $(id);
    if (el) el.value = val;
  }

  function setText(id, val) {
    const el = $(id);
    if (el) el.textContent = val;
  }

  function on(id, event, handler) {
    $(id)?.addEventListener(event, handler);
  }

  function $(id) {
    return document.getElementById(id);
  }

  function showLightbox(url) {
    let lb = document.getElementById('img-lightbox');
    if (!lb) {
      lb = document.createElement('div');
      lb.id = 'img-lightbox';
      lb.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.88);display:flex;align-items:center;justify-content:center;cursor:zoom-out';
      lb.innerHTML = '<img id="img-lightbox-img" style="max-width:90vw;max-height:90vh;border-radius:8px;box-shadow:0 8px 40px #000" />';
      lb.addEventListener('click', () => lb.remove());
      document.addEventListener('keydown', e => { if (e.key === 'Escape') lb.remove(); }, { once: true });
      document.body.appendChild(lb);
    }
    document.getElementById('img-lightbox-img').src = url;
    lb.style.display = 'flex';
  }

  function esc(s) {
    return String(s ?? '')
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  // ── Motion & micro-interactions ─────────────────────────────────────────
  // Four things, all decoration, none of them load-bearing: screens enter
  // instead of appearing, overlays close instead of vanishing, figures count
  // instead of teleporting, and a result arrives as a toast instead of an
  // alert(). Each one degrades to the instant behaviour it replaced, so a
  // seller with reduced motion turned on loses nothing but the movement.

  const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)');

  function prefersReducedMotion() {
    return !!reducedMotion?.matches;
  }

  /**
   * Play the section-enter animation on a screen that just became visible.
   * Restarting it on a screen that is already showing needs the reflow: the
   * class is still on the element from last time when a tab is re-activated
   * quickly, and re-adding a class the element already has does nothing.
   */
  function playEnter(el) {
    if (!el || prefersReducedMotion() || el.classList.contains('hidden')) return;
    // A transform makes the element the containing block for every
    // position:fixed descendant. Four screens have their confirm dialog
    // nested inside them, so a screen left with one open would re-anchor that
    // dialog to the panel for the length of the animation. Not worth 200ms.
    if (el.querySelector('.modal-overlay:not(.hidden)')) return;
    el.classList.remove('section-enter');
    void el.offsetWidth;
    el.classList.add('section-enter');
    el.addEventListener('animationend', function done(e) {
      if (e.target !== el) return;         // a child's own animation is not ours to clear
      el.removeEventListener('animationend', done);
      el.classList.remove('section-enter');
    });
  }

  /**
   * Hold a modal overlay on screen for one exit animation after something
   * hides it.
   *
   * Every close in the app is `classList.add('hidden')` from one of about
   * thirty call sites, and none of them are async. Rather than convert all
   * of them, this watches the class attribute and adds `.closing`, which the
   * CSS uses to out-specify `.hidden { display: none !important }` for the
   * length of the animation. `.hidden` itself is never touched, so every
   * `contains('hidden')` check elsewhere keeps telling the truth, and an
   * overlay that gets re-opened mid-exit simply drops `.closing` and shows.
   */
  function initOverlayMotion() {
    const overlays = document.querySelectorAll('.modal-overlay');
    if (!overlays.length || typeof MutationObserver !== 'function') return;

    const observer = new MutationObserver(records => {
      for (const record of records) {
        const el = record.target;
        const wasHidden = (record.oldValue || '').split(/\s+/).includes('hidden');
        const isHidden = el.classList.contains('hidden');
        // Adding or removing `.closing` is itself a class mutation. Only a
        // change in hidden-ness is a real open or close.
        if (wasHidden === isHidden) continue;

        if (!isHidden) { el.classList.remove('closing'); continue; }
        if (prefersReducedMotion()) continue;

        el.classList.add('closing');
        const finish = () => {
          clearTimeout(el._closeTimer);
          el.removeEventListener('animationend', onEnd);
          el.classList.remove('closing');
        };
        const onEnd = e => { if (e.target === el) finish(); };
        el.addEventListener('animationend', onEnd);
        // A dropped animationend (a background tab, a display change mid-flight)
        // would otherwise leave the overlay stuck visible over the app.
        el._closeTimer = setTimeout(finish, 600);
      }
    });

    overlays.forEach(el => observer.observe(el, {
      attributes: true, attributeFilter: ['class'], attributeOldValue: true,
    }));
  }

  /**
   * Walk a figure from what it currently reads to `target`, then leave it
   * showing exactly `format(target)` — never an interpolated value, so the
   * number the seller ends up reading is always the real one.
   *
   * @param {HTMLElement|null} el
   * @param {number} target
   * @param {(n: number) => string} [format]
   */
  function countUp(el, target, format = String) {
    if (!el) return;
    const to = Number(target);
    if (!Number.isFinite(to)) { el.textContent = format(target); return; }

    cancelAnimationFrame(el._countRaf || 0);

    // Read the value already on screen rather than caching it: another code
    // path may have written the figure directly, and counting from a stale
    // cached number would run the wrong distance.
    const from = parseFloat(String(el.textContent || '').replace(/[^0-9.-]/g, ''));
    const start = Number.isFinite(from) ? from : 0;

    // Nothing to count: no animation, and no settle pop for a figure that
    // did not actually change. Refreshing a dashboard should be quiet when
    // nothing moved.
    if (start === to) { el.textContent = format(to); return; }

    // Off-screen or motion-averse: land on the number and stop.
    if (prefersReducedMotion() || !el.offsetParent) { el.textContent = format(to); return; }

    // Longer walks get a little more time, but never enough to make a
    // refresh feel slow. A one-unit change is over almost immediately.
    const span = Math.abs(to - start);
    const duration = Math.min(900, Math.max(280, 240 + Math.log10(span + 1) * 190));
    const t0 = performance.now();

    const step = now => {
      const t = Math.min(1, (now - t0) / duration);
      const eased = 1 - Math.pow(1 - t, 3);     // ease-out: fast off the mark, long settle
      if (t < 1) {
        el.textContent = format(start + (to - start) * eased);
        el._countRaf = requestAnimationFrame(step);
        return;
      }
      el._countRaf = 0;
      el.textContent = format(to);
      el.classList.remove('num-settled');
      void el.offsetWidth;
      el.classList.add('num-settled');
      el.addEventListener('animationend', () => el.classList.remove('num-settled'), { once: true });
    };
    el._countRaf = requestAnimationFrame(step);
  }

  /** countUp() by element id — the setText() of animated figures. */
  function countUpText(id, value, format) {
    countUp($(id), value, format);
  }

  /** Shimmer the dashboard stat tiles while the numbers behind them reload. */
  function setStatsLoading(on) {
    document.querySelectorAll('.stats-grid > .stat-card')
      .forEach(card => card.classList.toggle('is-loading', !!on));
  }

  // ── Toasts ──────────────────────────────────────────────────────────────
  // The app had eight alert() calls, every one of them on a failure path.
  // An alert freezes the page, cannot be styled, cannot carry the action
  // that would fix the problem, and renders as an OS dialog with the page
  // origin in its title bar. These say the same things without stopping
  // anyone, and can hand back the button that resolves the failure.

  const TOAST_ICONS = {
    success: '<path d="M20 6 9 17l-5-5"/>',
    error:   '<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 16.5v.01"/>',
    warning: '<path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4M12 17v.01"/>',
    info:    '<circle cx="12" cy="12" r="9"/><path d="M12 16v-4M12 8v.01"/>',
  };

  const TOAST_TITLES = {
    success: 'Done', error: 'That did not work', warning: 'Heads up', info: 'ING Listing Engine',
  };

  function toastStack() {
    let stack = $('toast-stack');
    if (!stack) {
      stack = document.createElement('div');
      stack.id = 'toast-stack';
      stack.className = 'toast-stack';
      document.body.appendChild(stack);
    }
    return stack;
  }

  /**
   * @param {string} message
   * @param {{kind?: 'success'|'error'|'warning'|'info', title?: string,
   *          timeout?: number, action?: {label: string, onClick: () => void}}} [opts]
   * @returns {() => void} dismiss
   */
  function toast(message, opts = {}) {
    const kind = TOAST_ICONS[opts.kind] ? opts.kind : 'info';
    // An error the seller has to read and probably act on gets longer than a
    // "saved" they already expected.
    const timeout = opts.timeout ?? (kind === 'error' ? 9000 : 5000);
    const stack = toastStack();

    const slot = document.createElement('div');
    slot.className = 'toast-slot';
    slot.innerHTML =
      `<div class="toast toast--${kind}" role="${kind === 'error' ? 'alert' : 'status'}" aria-live="${kind === 'error' ? 'assertive' : 'polite'}">
         <span class="toast-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${TOAST_ICONS[kind]}</svg></span>
         <div class="toast-body">
           <p class="toast-title">${esc(opts.title ?? TOAST_TITLES[kind])}</p>
           <p class="toast-msg">${esc(message)}</p>
           ${opts.action ? `<button class="toast-action" type="button">${esc(opts.action.label)}</button>` : ''}
         </div>
         <button class="toast-close" type="button" aria-label="Dismiss">&times;</button>
         ${timeout > 0 ? `<span class="toast-life" style="animation-duration:${timeout}ms"></span>` : ''}
       </div>`;

    let closed = false;
    const dismiss = () => {
      if (closed) return;
      closed = true;
      clearTimeout(slot._timer);
      slot.classList.add('leaving');
      // The slot collapses on a transition; if that never fires — the stack
      // was hidden, the tab was in the background — the node still has to go.
      const drop = () => slot.remove();
      slot.addEventListener('transitionend', e => { if (e.target === slot) drop(); });
      setTimeout(drop, 700);
    };

    slot.querySelector('.toast-close').addEventListener('click', dismiss);
    if (opts.action) {
      slot.querySelector('.toast-action').addEventListener('click', () => {
        dismiss();
        try { opts.action.onClick(); } catch (e) { console.error('toast action failed', e); }
      });
    }

    // The hairline pauses on hover in CSS; the timer that actually removes
    // the toast has to agree with it, or the toast disappears out from under
    // a pointer that is holding it open to read.
    if (timeout > 0) {
      const toastEl = slot.firstElementChild;
      const arm = () => { slot._timer = setTimeout(dismiss, timeout); };
      toastEl.addEventListener('pointerenter', () => clearTimeout(slot._timer));
      toastEl.addEventListener('pointerleave', arm);
      toastEl.addEventListener('focusin', () => clearTimeout(slot._timer));
      toastEl.addEventListener('focusout', arm);
      arm();
    }

    stack.appendChild(slot);
    // A stack that keeps growing becomes a wall. Oldest goes first.
    while (stack.children.length > 4) stack.firstElementChild?.remove();
    return dismiss;
  }

  const toastOk  = (message, opts) => toast(message, { kind: 'success', ...opts });
  const toastErr = (message, opts) => toast(message, { kind: 'error', ...opts });

  // ── Empty / loading / error states ──────────────────────────────────────
  // Every data view in the app has the same three non-happy moments, and each
  // one used to be a sentence in a grey bar — which reads as a defect whether
  // it is one or not. These build the one state block the CSS styles, so a
  // view that has nothing to show still looks deliberate and, where an action
  // would fix it, offers that action instead of describing it.

  /**
   * @param {{variant?: 'empty'|'error'|'success', icon?: string, title: string,
   *          body?: string, detail?: string, actions?: {label: string, id?: string,
   *          kind?: string, href?: string}[], hint?: string}} opts
   */
  function stateBlockHtml(opts) {
    const variant = opts.variant || 'empty';
    const cls = variant === 'empty' ? 'state' : `state state--${variant}`;
    const icon = opts.icon
      ? `<svg aria-hidden="true"><use href="#${esc(opts.icon)}"/></svg>`
      : `<svg aria-hidden="true"><use href="#${variant === 'error' ? 'i-alert' : 'i-inbox'}"/></svg>`;

    const actions = (opts.actions || []).map(a => {
      const kind = a.kind || 'btn-secondary';
      return a.href
        ? `<a class="btn ${esc(kind)}" href="${esc(a.href)}" target="_blank" rel="noopener noreferrer">${esc(a.label)}</a>`
        : `<button class="btn ${esc(kind)}" type="button"${a.id ? ` data-state-action="${esc(a.id)}"` : ''}>${esc(a.label)}</button>`;
    }).join('');

    return `
      <div class="${cls}${opts.compact ? ' state--compact' : ''}${opts.inline ? ' state--inline' : ''}">
        <div class="state-icon">${icon}</div>
        <div class="state-title">${esc(opts.title)}</div>
        ${opts.body ? `<p class="state-body">${esc(opts.body)}</p>` : ''}
        ${opts.detail ? `<div class="state-detail">${esc(opts.detail)}</div>` : ''}
        ${actions ? `<div class="state-actions">${actions}</div>` : ''}
        ${opts.hint ? `<p class="state-hint">${esc(opts.hint)}</p>` : ''}
      </div>`;
  }

  /**
   * Renders a state block into a container and wires its buttons. `handlers`
   * maps the action ids used above onto functions — declared next to the
   * state so the copy and the thing it promises can't drift apart.
   */
  function renderState(container, opts, handlers = {}) {
    const el = typeof container === 'string' ? $(container) : container;
    if (!el) return;
    el.innerHTML = stateBlockHtml(opts);
    el.querySelectorAll('[data-state-action]').forEach(btn => {
      const fn = handlers[btn.dataset.stateAction];
      if (fn) btn.addEventListener('click', fn);
    });
  }

  /** Card-shaped placeholders sized like the real listing cards they replace. */
  function skeletonCardsHtml(count = 8) {
    const one = `
      <div class="skeleton-card" aria-hidden="true">
        <div class="skeleton skeleton-media"></div>
        <div class="skeleton skeleton-line tall w-90"></div>
        <div class="skeleton skeleton-line w-50"></div>
        <div class="skeleton-meta">
          <div class="skeleton skeleton-line"></div>
          <div class="skeleton skeleton-line"></div>
          <div class="skeleton skeleton-line w-70"></div>
          <div class="skeleton skeleton-line w-40"></div>
        </div>
      </div>`;
    return one.repeat(count);
  }

  function skeletonRowsHtml(count = 6) {
    const one = `
      <div class="skeleton-row" aria-hidden="true">
        <div class="skeleton skeleton-avatar"></div>
        <div class="skeleton-fill">
          <div class="skeleton skeleton-line w-70" style="margin-bottom:8px"></div>
          <div class="skeleton skeleton-line w-40"></div>
        </div>
      </div>`;
    return one.repeat(count);
  }

  /** The listings bar reports counts, progress and failures; each reads differently. */
  function setListingsFeedback(text, tone = 'info') {
    const el = $('listings-feedback');
    if (!el) return;
    el.textContent = text;
    el.classList.toggle('is-error', tone === 'error');
    el.classList.toggle('is-busy', tone === 'busy');
  }

  // ── Photo Editor (opens in new window) ───────────────────────────────────

  function initPhotoEditorPaste() {
    // Paste image from clipboard into next empty slot
    document.addEventListener('paste', e => {
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || document.activeElement?.isContentEditable) return;
      const items = e.clipboardData?.items;
      if (!items) return;
      for (const item of items) {
        if (item.type.startsWith('image/')) {
          const file = item.getAsFile();
          if (!file) continue;
          const idx = nextEmptySlotIndex();
          if (idx === -1) return;
          nlLoadFileIntoSlot(file, idx);
          addActivity('Photo pasted', `Picture ${idx + 1}`);
          e.preventDefault();
          return;
        }
      }
    });
    // Receive saved image back from the editor window
    window.addEventListener('message', e => {
      if (e.data?.type === 'photo-editor-save') {
        setPhotoSlotUrl(e.data.slotIndex, e.data.url);
        addActivity('Photo edited', `Picture ${e.data.slotIndex + 1}`);
      }
    });
  }

  function openPhotoEditor(slotIndex) {
    const slot = getPhotoSlot(slotIndex);
    if (!slot?.classList.contains('has-image')) return;
    const imgUrl = slot.dataset.url;
    const label  = `Picture ${slotIndex + 1}`;

    // Full-screen iframe overlay — no popup blocker issues
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#0d1117;';

    const iframe = document.createElement('iframe');
    iframe.src = '/editor.html';
    iframe.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;border:none;';
    overlay.appendChild(iframe);
    document.body.appendChild(overlay);

    const handler = e => {
      if (e.data?.type === 'editor-ready') {
        iframe.contentWindow?.postMessage(
          { type: 'load-image', url: imgUrl, slotIndex, label }, '*'
        );
      }
      if (e.data?.type === 'photo-editor-save') {
        window.removeEventListener('message', handler);
        setPhotoSlotUrl(e.data.slotIndex, e.data.url);
        addActivity('Photo edited', `Picture ${e.data.slotIndex + 1}`);
        overlay.remove();
      }
      if (e.data?.type === 'photo-editor-cancel') {
        window.removeEventListener('message', handler);
        overlay.remove();
      }
    };
    window.addEventListener('message', handler);
  }

})();
